// Load .env file (works in both dev and packaged builds).
// Production: prefer ~/.noted-terminal/.env (survives reinstall) and fall back
// to the .env next to execPath if present. Dev: project cwd.
function loadEnvFile(p) {
  try {
    if (!fs.existsSync(p)) return;
    // These files contain service credentials used by Electron main. Keep the
    // values intact, but do not leave them readable by other local users.
    try { fs.chmodSync(p, 0o600); } catch { /* read-only fallback may still be usable */ }
    for (const line of fs.readFileSync(p, 'utf8').split('\n')) {
      const match = line.match(/^([^#=]+)=(.*)$/);
      if (match) process.env[match[1].trim()] = match[2].trim();
    }
  } catch { /* ignore */ }
}
try {
  if (app.isPackaged) {
    loadEnvFile(path.join(os.homedir(), '.noted-terminal', '.env'));
    loadEnvFile(path.join(path.dirname(process.execPath), '.env'));
  } else {
    loadEnvFile(path.resolve(process.cwd(), '.env'));
  }
} catch { /* .env optional */ }

// Capture Electron's canonical application-data directory before an isolated
// dev/E2E launch overrides userData. Shared ~/.codex and ~/.claude mutations
// must still be checked against the real production database, not a temporary
// empty sibling path.
const canonicalNotedUserDataDir = app.getPath('userData');
const E2E_WINDOWED = process.env.NOTED_E2E_WINDOWED === '1';
if (E2E_WINDOWED && (app.isPackaged || process.env.NOTED_E2E_TEST !== 'true'
    || !process.env.NOTED_USER_DATA_DIR
    || path.resolve(process.env.NOTED_USER_DATA_DIR) === canonicalNotedUserDataDir)) {
  throw new Error('NOTED_E2E_WINDOWED requires an unpackaged E2E instance with private userData');
}

if (process.env.NOTED_USER_DATA_DIR) {
  try {
    const userDataDir = path.resolve(process.env.NOTED_USER_DATA_DIR);
    fs.mkdirSync(userDataDir, { recursive: true });
    app.setPath('userData', userDataDir);
    console.log('[Startup] userData override:', userDataDir);
  } catch (error) {
    console.warn('[Startup] userData override failed:', error?.message || error);
  }
}

// E2E test mode: suppress native error dialogs that block Playwright
if (process.env.NOTED_E2E_TEST === 'true') {
  dialog.showErrorBox = (title, content) => {
    console.error('[E2E SUPPRESSED ERROR]', title, ':', content);
  };
  process.on('uncaughtException', (error) => {
    console.error('[E2E uncaughtException]', error.message, error.stack);
  });
  process.on('unhandledRejection', (reason) => {
    console.error('[E2E unhandledRejection]', reason);
  });
}

// Потолок памяти главного процесса. По умолчанию движок обрывает процесс
// примерно на 4 ГБ — и это не «утечка кончилась», а жёсткий предел: при его
// достижении вызывается abort(), приложение просто исчезает с системным
// сообщением о сбое (прод 17.08 19:10, 20:41, 20:47 и 18.08 03:04 — во всех
// четырёх отчётах одна и та же вершина стека: FatalProcessOutOfMemory).
//
// Рабочий объём здесь законно большой: живой транскрипт сессии на 111 МБ — это
// ~15 тысяч разобранных записей, которые обязаны лежать в памяти целиком, иначе
// каждый запрос истории перечитывал бы файл заново. Замерено в проде: ровный
// фон 1.6 ГБ, а любой обычный всплеск (разбор второго транскрипта, сборка
// таймлайна) добавляет к нему ещё 1.5–2 ГБ — и упирается в предел. В машине
// 32 ГБ, так что предел здесь искусственный.
//
// 8 ГБ — это НЕ разрешение течь: фон и всплески измерены и укладываются вдвое,
// запас нужен ровно на то, чтобы одновременный всплеск не убивал процесс.
// Если фон когда-нибудь подберётся к 8 ГБ — это уже настоящая утечка, и её
// надо искать, а не поднимать число дальше.
app.commandLine.appendSwitch('js-flags', '--max-old-space-size=8192');

// Disable HTTP cache to ensure fresh code after updates
app.commandLine.appendSwitch('disable-http-cache');

// Disable Claude Code's mutating attribution header. It injects a per-request
// fingerprint + cch=00000 placeholder at the very start of the system prompt;
// the placeholder is rewritten by Bun's native HTTP stack to a hash of the
// request body before send. Both make the prompt prefix drift on every call →
// prompt-cache prefix mismatch → cache_read drops to ~0, full cache_creation
// on every turn. Affects long sessions, but especially fork/--resume where
// otherwise-identical prefixes would hit parent's cache. Documented killswitch,
// not a hack: see packages/claude-code-src/constants/system.ts:52. Off-by-env
// for OAuth users anyway; for us it just stabilises the prefix so the server
// cache key stays stable across turns AND across forks of the same session.
process.env.CLAUDE_CODE_ATTRIBUTION_HEADER = '0';

// CDP только в dev — нужен для автотестов через node /tmp/cdp.js (port 9224
// уникален для этого проекта: sc-desktop=9223, gt-editor=9222). В prod не
// открываем сокет, чтобы не давать сторонним процессам доступ к Electron.
if (process.env.NODE_ENV === 'development' || !app.isPackaged) {
  const cdpPort = String(process.env.NOTED_CDP_PORT || '9224');
  app.commandLine.appendSwitch('remote-debugging-port', cdpPort);
  console.log('[Startup] remote-debugging-port:', cdpPort);
}

