const agentSendReceiptStartupReconcile = agentSendReceiptStore.reconcileStartup();
for (const record of agentSendReceiptStartupReconcile.records) agentSendActivity.update(record);
if (agentSendReceiptStartupReconcile.changed > 0) {
  console.warn('[AgentSendReceipt] startup reconciled active attempts to delivery-unknown count='
    + agentSendReceiptStartupReconcile.changed);
}
const agentSendReceiptStartupReady = (async () => {
  const unresolved = agentSendReceiptStartupReconcile.records.filter((record) => (
    record?.state === AGENT_SEND_DURABLE_STATES.AUDIT_PENDING
    || record?.state === AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN
  ));
  const decisions = await reconcileAgentSendStartupRecords(unresolved, {
    allRecords: agentSendReceiptStartupReconcile.records,
  });
  let promoted = 0;
  let providerNotAccepted = 0;
  let absent = 0;
  let unknown = 0;
  let markedUnconfirmed = 0;
  for (const result of decisions) {
    if (result?.decision === 'found' && result.audit) {
      const promotion = agentSendReceiptStore.promoteFromAudit(result.audit);
      if (promotion?.promoted === true
        || (promotion?.idempotent === true
          && promotion?.record?.state === AGENT_SEND_DURABLE_STATES.CONFIRMED)) {
        promoted += 1;
      } else {
        unknown += 1;
        console.warn('[AgentSendReceipt] startup transcript proof rejected operation='
          + String(result.operationKey || '-').slice(0, 72)
          + ' reason=' + (promotion?.reason || 'unknown'));
      }
    } else if (result?.decision === 'provider-not-accepted' && result.receipt) {
      const settlement = agentSendReceiptStore.settleAttempt(
        result.operationKey,
        result.attemptId,
        result.receipt,
      );
      if (settlement?.record?.state === AGENT_SEND_DURABLE_STATES.PROVIDER_NOT_ACCEPTED) {
        providerNotAccepted += 1;
      } else {
        unknown += 1;
        console.warn('[AgentSendReceipt] startup provider queue return rejected operation='
          + String(result.operationKey || '-').slice(0, 72)
          + ' reason=' + (settlement?.reason || 'unknown'));
      }
    } else {
      if (result?.decision === 'absent') absent += 1;
      else unknown += 1;
      // A negative or incomplete startup scan is never retry authority: Enter
      // may have crossed the PTY boundary. It is, however, enough to stop
      // presenting an active CONFIRMING spinner after the app has restarted.
      // Keep the same immutable attempt replay-blocked and promotable by a
      // later exact transcript audit, but project it as finite UNCONFIRMED.
      if (result?.operationKey && result?.attemptId) {
        const transition = agentSendReceiptStore.markStartupUnconfirmed(
          result.operationKey,
          result.attemptId,
          result,
        );
        if (transition?.record?.state === AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN) {
          markedUnconfirmed += 1;
        } else if (transition?.reason !== 'already-confirmed') {
          console.warn('[AgentSendReceipt] startup unconfirmed transition rejected operation='
            + String(result.operationKey || '-').slice(0, 72)
            + ' reason=' + (transition?.reason || 'unknown'));
        }
      }
    }
  }
  if (decisions.length > 0) {
    const reasons = new Map();
    for (const result of decisions) {
      const key = String(result?.decision || 'unknown')
        + ':' + String(result?.reason || 'unspecified');
      reasons.set(key, (reasons.get(key) || 0) + 1);
    }
    console.warn('[AgentSendReceipt] startup transcript reconcile records=' + decisions.length
      + ' promoted=' + promoted
      + ' providerNotAccepted=' + providerNotAccepted
      + ' absent=' + absent
      + ' unknown=' + unknown
      + ' markedUnconfirmed=' + markedUnconfirmed
      + ' reasons=' + JSON.stringify(Object.fromEntries(reasons)));
  }
  return {
    ready: true,
    records: decisions.length,
    promoted,
    providerNotAccepted,
    absent,
    unknown,
    markedUnconfirmed,
  };
})().catch((error) => {
  console.warn('[AgentSendReceipt] startup transcript reconcile failed:', error?.message || error);
  return { ready: false, error: error?.message || String(error) };
});
