function terminalHistoryAssistantText(message) {
  if (!message || message.type !== 'assistant') return '';
  const content = message?.message?.content;
  if (typeof content === 'string') return content.trim();
  if (!Array.isArray(content)) return '';
  return content
    .filter((block) => block?.type === 'text' && typeof block.text === 'string')
    .map((block) => block.text)
    .join('\n')
    .trim();
}

function terminalHistoryStructuredBoundaryKind(message) {
  const content = message?.message?.content;
  if (!Array.isArray(content)) return null;
  if (message?.type === 'assistant') {
    if (content.some((block) => block?.type === 'tool_use')) return 'tool-use';
    if (content.some((block) => block?.type === 'thinking')) return 'thinking';
  }
  if (message?.type === 'user'
    && content.some((block) => block?.type === 'tool_result')) return 'tool-result';
  return null;
}

function collectTerminalHistoryStructuredProofStrings(value, output, depth = 0) {
  if (output.length >= 64 || depth > 8 || value == null) return;
  if (typeof value === 'string') {
    const text = value.trim();
    if (text) output.push(text);
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectTerminalHistoryStructuredProofStrings(
      item,
      output,
      depth + 1,
    );
    return;
  }
  if (typeof value !== 'object') return;
  for (const nested of Object.values(value)) {
    collectTerminalHistoryStructuredProofStrings(nested, output, depth + 1);
    if (output.length >= 64) break;
  }
}

// Exact structured JSONL is not only a boundary: its payload is a receipt for
// the tool/thinking projection which the TUI may paint later or leave behind
// after scrolling. The controller keeps this bounded and in memory for the
// active turn; it is never used to manufacture assistant text.
function terminalHistoryStructuredProofTexts(message, kind) {
  const content = message?.message?.content;
  if (!Array.isArray(content) || !kind) return [];
  const result = [];
  for (const block of content) {
    if (!block || typeof block !== 'object') continue;
    if (kind === 'tool-use' && block.type === 'tool_use') {
      const inputStrings = [];
      collectTerminalHistoryStructuredProofStrings(block.input, inputStrings);
      result.push(...inputStrings);
      const name = typeof block.name === 'string' ? block.name.trim() : '';
      if (name && inputStrings.length > 0) {
        result.push(name + '(' + inputStrings.join('\n') + ')');
      }
      try {
        if (name && block.input && typeof block.input === 'object') {
          result.push(name + '(' + JSON.stringify(block.input) + ')');
        }
      } catch {}
    } else if (kind === 'tool-result' && block.type === 'tool_result') {
      collectTerminalHistoryStructuredProofStrings(block.content, result);
      collectTerminalHistoryStructuredProofStrings(block.result, result);
    } else if (kind === 'thinking' && block.type === 'thinking') {
      collectTerminalHistoryStructuredProofStrings(block.thinking, result);
    }
    if (result.length >= 64) break;
  }
  if (kind === 'tool-result') {
    // Claude Edit stores the exact structured patch beside message.content,
    // not inside the visible tool_result string.
    collectTerminalHistoryStructuredProofStrings(message?.toolUseResult, result);
    collectTerminalHistoryStructuredProofStrings(message?.message?.toolUseResult, result);
  }
  return result.slice(0, 64);
}

function terminalHistoryToolResultIds(message) {
  const content = message?.message?.content;
  if (!Array.isArray(content)) return [];
  return content
    .filter((block) => block?.type === 'tool_result')
    .map((block) => block.tool_use_id || block.toolUseId || null)
    .filter(Boolean)
    .map(String);
}

function observeTerminalHistoryCanonicalLiveMessage(detail) {
  const provider = detail?.toolType;
  if (provider !== 'claude' && provider !== 'codex') return false;
  const message = detail.message;
  const shared = {
    tabId: detail.tabId,
    provider,
    sessionId: detail.sessionId || message?.sessionId || null,
    sourceSequence: detail.sourceSequence,
    sourceEndOffset: detail.recordEndByteOffset ?? detail.recordByteOffset,
    identity: message?.sourceIdentity || message?.uuid || message?.message?.id || null,
    semanticItemId: message?.semanticItemId || null,
    semanticMessageId: provider === 'claude' ? message?.message?.id || null : null,
    canonicalTexts: provider === 'claude' && Array.isArray(message?.message?.content)
      ? message.message.content.filter(block => block?.type === 'text' && typeof block.text === 'string')
        .map(block => block.text)
      : null,
  };
  const kind = terminalHistoryStructuredBoundaryKind(message);
  const structuredTexts = terminalHistoryStructuredProofTexts(message, kind);
  if (provider === 'claude' && kind === 'tool-result') {
    const toolUseIds = terminalHistoryToolResultIds(message);
    const released = toolUseIds.length > 0
      ? claudeToolScreenHolds.release({ tabId: detail.tabId, toolUseIds })
      : claudeToolScreenHolds.releaseCompleted(detail.tabId);
    console.log('[ClaudeToolScreenHold] JSONL_RELEASE tab=' + String(detail.tabId).slice(-12)
      + ' ids=' + (toolUseIds.join(',') || '-')
      + ' released=' + released
      + ' remaining=' + claudeToolScreenHolds.snapshot(detail.tabId).length);
  }
  const text = terminalHistoryAssistantText(message);
  if (text) {
    safelyObserveProviderSemantic('canonical', () => providerSemanticShadow.observeCanonical({
      tabId: detail.tabId,
      provider,
      sessionId: shared.sessionId,
      turnId: message?.turnId || message?.message?.turnId || null,
      itemId: shared.semanticItemId,
      text,
    }));
    const canonicalObserved = terminalHistoryPreviewController.observeCanonical({
      ...shared,
      canonicalText: text,
    });
    if (!kind) return canonicalObserved;
    // A Claude assistant record may contain prose and tool_use in one JSONL
    // object. Canonicalize the prose first, then open the next structured
    // segment using the same exact record without pretending it is a newer
    // transcript sequence.
    return terminalHistoryPreviewController.observeBoundary({
      ...shared,
      sourceSequence: null,
      sourceEndOffset: null,
      kind,
      structuredTexts,
    }) || canonicalObserved;
  }
  if (!kind) return false;
  return terminalHistoryPreviewController.observeBoundary({
    ...shared,
    kind,
    structuredTexts,
  });
}

function observeCodexProviderPreviewRawRecord(detail) {
  if (detail?.toolType !== 'codex' || !detail?.tabId || !detail?.message) return false;
  const tabId = detail.tabId;
  const boundary = classifyCodexProviderPreviewRecord({
    record: detail.message,
    sessionId: detail.sessionId,
    recordByteOffset: detail.recordByteOffset,
    recordEndByteOffset: detail.recordEndByteOffset,
  });
  if (!boundary) return false;
  // History subscriptions are optional and may replay late. They own text and
  // preview boundaries, never the live turn's activity. The independent Codex
  // watcher settles that activity even when no History tab is mounted.
  if (boundary.kind === 'lifecycle') return false;
  const owner = codexProviderSemanticSources.get(tabId) || null;
  if (!owner) return false;
  const watcher = codexTurnWatchers.get(tabId) || null;
  const verdict = codexProviderPreviewRolloutVerdict({
    owner,
    current: currentCodexProviderSemanticOwnerContext(tabId),
    watcher,
    detail,
  });
  if (!verdict.allowed) {
    console.warn('[CodexProviderSemantic] ROLLOUT_STALE tab=' + String(tabId).slice(-12)
      + ' session=' + String(detail.sessionId || '-').slice(0, 8)
      + ' offset=' + String(detail.recordByteOffset ?? '-')
      + ' reason=' + verdict.reason);
    return false;
  }
  if (boundary.kind === 'assistant') {
    safelyObserveProviderSemantic('canonical-raw', () => providerSemanticShadow.observeCanonical({
      tabId,
      provider: 'codex',
      sessionId: boundary.sessionId,
      turnId: owner.turnId || null,
      itemId: boundary.itemId,
      text: boundary.text,
    }));
    const settled = terminalHistoryPreviewController.observeCanonical({
      tabId,
      provider: 'codex',
      sessionId: boundary.sessionId,
      sourceEndOffset: boundary.recordEndByteOffset,
      identity: boundary.identity,
      semanticItemId: boundary.itemId,
      canonicalText: boundary.text,
    });
    console.log('[CodexProviderSemantic] ROLLOUT_CANONICAL tab=' + String(tabId).slice(-12)
      + ' rollout=' + String(boundary.sessionId || '-').slice(0, 8)
      + ' provider=' + String(owner.turnId || '-').slice(-18)
      + ' item=' + String(boundary.itemId || '-').slice(-18)
      + ' identity=' + String(boundary.identity || '-').slice(-32)
      + ' settled=' + !!settled);
    return settled;
  }
  if (boundary.kind === 'boundary') {
    const observed = terminalHistoryPreviewController.observeBoundary({
      tabId,
      provider: 'codex',
      sessionId: boundary.sessionId,
      sourceEndOffset: boundary.recordEndByteOffset,
      identity: boundary.identity,
      kind: boundary.boundaryKind,
      structuredTexts: boundary.structuredTexts,
    });
    console.log('[CodexProviderSemantic] ROLLOUT_BOUNDARY tab=' + String(tabId).slice(-12)
      + ' rollout=' + String(boundary.sessionId || '-').slice(0, 8)
      + ' kind=' + boundary.boundaryKind
      + ' phase=' + boundary.phase
      + ' identity=' + String(boundary.identity || '-').slice(-32)
      + ' observed=' + !!observed);
    return observed;
  }
  return false;
}

function findTerminalPreviewCursorComposerRow(snapshot) {
  const lines = Array.isArray(snapshot?.lines) ? snapshot.lines : [];
  const baseY = Number(snapshot?.baseY);
  const cursorY = Number(snapshot?.cursorY);
  if (!Number.isFinite(baseY) || !Number.isFinite(cursorY)) return null;
  const cursorRow = baseY + cursorY;
  let index = lines.findIndex((line) => Number(line?.row) === cursorRow);
  if (index < 0) return null;
  while (index >= 0) {
    const text = String(lines[index]?.text || '');
    if (/[❯›⏵]/u.test(text)) return Number(lines[index]?.row);
    if (lines[index]?.wrapped !== true) return null;
    index -= 1;
  }
  return null;
}

function findTerminalHistoryPreviewComposerRow(snapshot, provider) {
  let composerRow = findTerminalPreviewCursorComposerRow(snapshot);
  if (provider === 'claude') {
    const composerProof = parseClaudeComposerCurrentFrame(snapshot);
    if (Number.isFinite(Number(composerProof?.promptRow))) {
      composerRow = Number(composerProof.promptRow);
    }
  } else if (provider === 'codex' && composerRow === null) {
    const candidate = snapshot?.codexActivePrompt?.row
      ?? snapshot?.codexCursorComposer?.row;
    if (Number.isFinite(Number(candidate))) composerRow = Number(candidate);
  }
  return composerRow;
}

function readTerminalHistoryPreviewFrame({ state, snapshot }) {
  if (state?.provider === 'claude' && claudeToolScreenHolds.isHeld(state.tabId)) {
    return { status: 'unknown', reason: 'claude-hook-tool-screen-owned' };
  }
  const viewportY = Number(snapshot?.viewportY);
  const lines = Array.isArray(snapshot?.lines) ? snapshot.lines : [];
  const preViewportLines = Array.isArray(snapshot?.preViewportLines)
    ? snapshot.preViewportLines
    : [];
  if (!Number.isFinite(viewportY) || lines.length === 0) {
    return { status: 'ready', reason: 'committed-frame-empty', physicalLines: [] };
  }
  const composerRow = findTerminalHistoryPreviewComposerRow(snapshot, state.provider);
  const promptBoundary = findTerminalHistorySubmittedPromptBoundary({
    physicalLines: lines,
    promptText: state.promptText,
    provider: state.provider,
    beforeRow: composerRow,
  });
  const markerAlive = !!state.marker
    && state.marker.isDisposed !== true
    && Number.isFinite(Number(state.marker.line))
    && Number(state.marker.line) >= 0;
  const markerLine = markerAlive ? Number(state.marker.line) : null;
  let firstOwnedRow = null;
  let boundaryKind = null;
  let boundaryRow = null;
  let baselinePhysicalLines = null;
  let baselineFrameGeneration = null;
  let baselineWriteSeq = null;
  if (promptBoundary) {
    firstOwnedRow = Math.max(viewportY, promptBoundary.endRow + 1);
    boundaryKind = 'exact-submitted-prompt';
    boundaryRow = promptBoundary.endRow;
    state.promptBoundaryConfirmed = true;
  } else if (state.promptBoundaryConfirmed === true && state.text) {
    // A long answer legitimately scrolls the prompt out of the viewport. The
    // controller already owns a proven prefix and its overlap merge admits
    // only a continuation of that prefix.
    firstOwnedRow = viewportY;
    boundaryKind = 'proven-output-continuation';
    boundaryRow = viewportY - 1;
  } else if (!state.promptText && markerLine !== null) {
    // Rebase after a canonical assistant record has no submitted prompt. In
    // that narrow append-only phase the current xterm marker remains useful,
    // but losing it freezes the preview rather than ending the lifecycle.
    firstOwnedRow = Math.max(viewportY, markerLine + 1);
    boundaryKind = 'xterm-marker';
    boundaryRow = markerLine;
  } else if (!state.promptText && state.rebaseBaselineSnapshot) {
    const baseline = state.rebaseBaselineSnapshot;
    const baselineViewportY = Number(baseline?.viewportY);
    const baselineLines = Array.isArray(baseline?.lines) ? baseline.lines : [];
    const baselineComposerRow = findTerminalHistoryPreviewComposerRow(
      baseline,
      state.provider,
    );
    if (baseline?.authoritativeFrameCommitted !== true
      || baseline.mirrorGeneration !== state.mirrorGeneration
      || !Number.isFinite(baselineViewportY)
      || baselineLines.length === 0) {
      return { status: 'unknown', reason: 'exact-jsonl-baseline-not-authoritative' };
    }
    // A viewport which is not showing its composer may be historical scrollback.
    // Never turn that into a live assistant preview merely because it is newer
    // than the JSONL record.
    if (composerRow === null || baselineComposerRow === null) {
      return { status: 'unknown', reason: 'exact-jsonl-baseline-composer-unavailable' };
    }
    firstOwnedRow = viewportY;
    boundaryKind = 'exact-jsonl-frame-baseline';
    boundaryRow = viewportY - 1;
    baselinePhysicalLines = baselineLines.filter((line) => {
      const row = Number(line?.row);
      return row >= baselineViewportY && row < baselineComposerRow;
    });
    baselineFrameGeneration = baseline.committedFrameGeneration ?? null;
    baselineWriteSeq = baseline.writeSeq ?? null;
  } else {
    return {
      status: 'unknown',
      reason: state.promptText
        ? 'exact-submitted-prompt-not-visible'
        : 'turn-boundary-unavailable',
    };
  }
  const physicalLines = lines.filter((line) => {
    const row = Number(line?.row);
    return row >= firstOwnedRow && (composerRow === null || row < composerRow);
  });
  // Preserve a small read-only slice immediately before the exact boundary.
  // It never becomes candidate output; the parser uses it only to prove that
  // the first owned rows continue a provider-owned card whose root is above
  // the marker/baseline (Claude Tip, Codex Updated Plan, tool child, etc.).
  const leadingPhysicalLines = [...preViewportLines, ...lines].filter((line) => {
    const row = Number(line?.row);
    return row >= firstOwnedRow - 24 && row < firstOwnedRow;
  });
  return {
    status: 'ready',
    reason: (boundaryKind === 'proven-output-continuation'
      ? 'owned-output-continued-after-scroll'
      : 'owned-output-after-' + boundaryKind)
      + (composerRow === null ? '-composer-fallback' : '-cursor-composer-bound'),
    physicalLines,
    leadingPhysicalLines,
    composerRow,
    boundaryKind,
    boundaryRow,
    baselinePhysicalLines,
    baselineFrameGeneration,
    baselineWriteSeq,
    promptPrefixClipped: boundaryKind === 'proven-output-continuation',
    // This is only a warning on the first captured frame. Once prior rows are
    // accumulated in the controller, scrolling the marker above the viewport
    // is the normal way a long answer advances.
    truncated: boundaryKind === 'proven-output-continuation' && !state.text,
  };
}

function emitTerminalHistoryPreview(detail) {
  if (!mainWindow || mainWindow.isDestroyed()) return;
  mainWindow.webContents.send('agent-transcript:terminal-preview', detail);
}

const TERMINAL_HISTORY_STREAMING_STATE_KEY = 'noted-terminal-terminal-history-streaming';
const terminalHistoryStreamingStored = projectManager.db.getAppState(
  TERMINAL_HISTORY_STREAMING_STATE_KEY,
);
let terminalHistoryStreamingEnabled = terminalHistoryStreamingStored === null
  || terminalHistoryStreamingStored === undefined
  || terminalHistoryStreamingStored === true
  || terminalHistoryStreamingStored === 1
  || terminalHistoryStreamingStored === '1'
  || terminalHistoryStreamingStored === 'true';

const terminalHistoryPreviewController = createTerminalHistoryPreviewController({
  getContext: (tabId) => {
    const terminal = terminals.get(tabId) || null;
    const mirror = terminalHeadlessMirrors.get(tabId) || null;
    const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
    if (!terminal || !mirror || mirror.failed || mirror.disposed) return null;
    return { terminal, mirror, lifecycleGeneration };
  },
  readFrame: readTerminalHistoryPreviewFrame,
  emit: emitTerminalHistoryPreview,
  log: console,
  isEnabled: () => terminalHistoryStreamingEnabled,
});
// Provider streams own live History prose; the terminal still owns input and
// readiness. Claude is armed by its exact UserPromptSubmit hook. The Codex launch
// generation below is the authority: late frames from an older Codex process
// cannot write into a replacement turn even though both use the same tab route.
const codexProviderSemanticSources = new Map();

function currentCodexProviderSemanticSourceId(tabId) {
  return codexProviderSemanticSources.get(tabId)?.sourceId || null;
}

function currentCodexProviderSemanticOwnerContext(tabId) {
  return {
    terminalToken: terminals.get(tabId) || null,
    runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    launchId: codexLastRunCommandPayload.get(tabId)?.launchId || null,
  };
}

function codexProviderRequestCausalTurnSnapshot(tabId) {
  const providerOwner = codexProviderSemanticSources.get(tabId) || null;
  const turnState = codexTurnWatchers.get(tabId) || null;
  const prompt = codexPromptInFlight.get(tabId) || null;
  let promptInFlightSubmitted = false;
  if (prompt) {
    const ageMs = Date.now() - Number(prompt.startedAt || 0);
    if (ageMs > CODEX_PROMPT_IN_FLIGHT_TTL_MS) {
      clearCodexPromptInFlight(tabId, 'provider-request-authority-ttl');
    } else {
      promptInFlightSubmitted = prompt.submitted === true;
    }
  }
  const pendingCompact = compactOperations.getPending(tabId, 'codex');
  return codexProviderCausalTurnVerdict({
    providerTurnActive: providerOwner?.turnActive === true,
    rolloutTurnBusy: turnState?.busy === true,
    promptInFlightSubmitted,
    startupBeforeInputReady: isCodexStartupLifecycleFresh(tabId),
    pendingCompact: !!pendingCompact,
  });
}

function authorizeCodexProviderMainRequest({ tabId, identity } = {}) {
  const writerSessionId = getCodexWriterProofSnapshot(tabId)?.sessionId || null;
  const causalTurn = codexProviderRequestCausalTurnSnapshot(tabId);
  let verdict = codexProviderRequestAdmissionVerdict({
    hasCausalTurn: causalTurn.active,
    writerSessionId,
    requestSessionId: identity?.sessionId || null,
  });
  if (!verdict.allowed
    && verdict.reason === 'provider-request-without-causal-turn'
    && causalTurn.reason) {
    verdict = { ...verdict, reason: causalTurn.reason };
  }
  if (!verdict.allowed) {
    console.log('[CodexProviderSemantic] REQUEST_SIDE tab=' + String(tabId || '').slice(-12)
      + ' turn=' + String(identity?.turnId || '-').slice(-18)
      + ' requestSession=' + String(identity?.sessionId || '-').slice(-8)
      + ' writerSession=' + String(writerSessionId || '-').slice(-8)
      + ' causal=' + causalTurn.reason
      + ' reason=' + verdict.reason);
  }
  return verdict;
}

function publishCodexProviderTurnActivity({
  tabId,
  sourceId,
  active,
  turnId = null,
  phase = 'turn',
  reason = active ? 'provider-turn-active' : 'provider-turn-ended',
  responseTimingEligible = true,
} = {}) {
  const owner = codexProviderSemanticSources.get(tabId) || null;
  const verdict = codexProviderPreviewOwnerVerdict(
    owner,
    currentCodexProviderSemanticOwnerContext(tabId),
    sourceId,
  );
  if (!verdict.allowed) {
    console.warn('[CodexProviderSemantic] ACTIVITY_STALE tab=' + String(tabId || '').slice(-12)
      + ' source=' + String(sourceId || '').slice(-24)
      + ' active=' + !!active
      + ' reason=' + verdict.reason);
    return false;
  }
  owner.turnActive = active === true;
  owner.turnId = turnId || owner.turnId || null;
  owner.phase = phase;
  const turnState = codexTurnWatchers.get(tabId) || null;
  if (turnState) {
    turnState.providerTurnActive = owner.turnActive;
    turnState.providerTurnId = owner.turnId;
    turnState.providerTurnPhase = phase;
    turnState.busy = owner.turnActive;
  }
  recordActivity(tabId, owner.turnActive, 'codex', {
    responseTimingEligible,
    reason,
  });
  publishCodexRuntimeProjection(tabId, 'provider-turn-activity:' + reason);
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:busy-state', {
      ...codexTurnStateSnapshot(turnState),
      tabId,
      busy: owner.turnActive,
      reason,
      turnId: owner.turnId,
      lifecycleGeneration: owner.lifecycleGeneration,
      providerActivity: true,
      providerPhase: phase,
    });
  }
  console.log('[CodexProviderSemantic] ACTIVITY tab=' + String(tabId).slice(-12)
    + ' source=' + String(sourceId).slice(-24)
    + ' active=' + (owner.turnActive ? '1' : '0')
    + ' turn=' + String(owner.turnId || '-').slice(-18)
    + ' phase=' + phase
    + ' reason=' + reason);
  return true;
}

function armCodexProviderSemanticSource({ tabId, launchId } = {}) {
  if (!tabId || !launchId) return null;
  const sourceId = 'codex-provider:' + String(launchId);
  const terminalToken = terminals.get(tabId) || null;
  const runSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  codexProviderSemanticSources.set(tabId, {
    sourceId,
    launchId: String(launchId),
    terminalToken,
    runSeq,
    lifecycleGeneration,
    turnActive: false,
    turnId: null,
    phase: 'idle',
  });
  terminalHistoryPreviewController.expectSemanticSource({ tabId });
  terminalHistoryPreviewController.activateSemanticSource({
    tabId,
    instanceId: sourceId,
  });
  console.log('[CodexProviderSemantic] ARM tab=' + String(tabId).slice(-12)
    + ' source=' + String(sourceId).slice(-24)
    + ' runSeq=' + runSeq
    + ' lifecycle=' + String(lifecycleGeneration || '-').slice(-18));
  return sourceId;
}

function disarmCodexProviderSemanticSource(tabId, reason = 'clear', expectedLaunchId = null) {
  const current = codexProviderSemanticSources.get(tabId) || null;
  if (expectedLaunchId && current?.launchId !== String(expectedLaunchId)) return false;
  if (current?.turnActive === true && mainWindow && !mainWindow.isDestroyed()) {
    recordActivity(tabId, false, 'codex', { reason: 'provider-source-release:' + reason });
    mainWindow.webContents.send('codex:busy-state', {
      tabId,
      busy: false,
      reason: 'provider-source-release:' + reason,
      turnId: current.turnId || null,
      lifecycleGeneration: current.lifecycleGeneration || null,
      providerActivity: true,
      providerPhase: 'idle',
    });
  }
  codexProviderSemanticSources.delete(tabId);
  terminalHistoryPreviewController.clearSemanticSource(tabId, reason);
  if (current) {
    console.log('[CodexProviderSemantic] RELEASE tab=' + String(tabId).slice(-12)
      + ' source=' + String(current.sourceId).slice(-24)
      + ' reason=' + reason);
  }
  return !!current;
}

function handleCodexProviderSemanticEvent(detail) {
  const tabId = detail?.tabId;
  const sourceId = detail?.sourceId;
  const event = detail?.event;
  if (!tabId || !sourceId || !event?.type) return false;
  const owner = codexProviderSemanticSources.get(tabId) || null;
  const verdict = codexProviderPreviewOwnerVerdict(
    owner,
    currentCodexProviderSemanticOwnerContext(tabId),
    sourceId,
  );
  if (!verdict.allowed) {
    console.warn('[CodexProviderSemantic] STALE tab=' + String(tabId).slice(-12)
      + ' source=' + String(sourceId).slice(-24)
      + ' event=' + event.type
      + ' reason=' + verdict.reason);
    return false;
  }
  if (event.type === 'turn_started') {
    publishCodexProviderTurnActivity({
      tabId,
      sourceId,
      active: true,
      turnId: event.turnId || null,
      phase: 'provider-response',
      reason: 'provider-turn-started',
    });
  } else if (event.type === 'turn_completed') {
    // A Responses request ends before Codex executes its tool and opens the
    // continuation request. Only rollout task_complete/turn_aborted may lower
    // the turn-level loader.
    console.log('[CodexProviderSemantic] SEGMENT_END tab=' + String(tabId).slice(-12)
      + ' source=' + String(sourceId).slice(-24)
      + ' turn=' + String(event.turnId || '-').slice(-18)
      + ' request=' + String(event.requestId || '-').slice(-20));
  }
  return terminalHistoryPreviewController.observeSemanticEvent({
    tabId,
    instanceId: sourceId,
    gap: detail?.gap === true,
    event,
  });
}

function handleClaudeProviderSemanticEvent({ tabId, sourceId, gap, event } = {}) {
  if (!tabId || !sourceId || !event) return false;
  // A message_stop is one response segment. Claude Stop/StopFailure hooks
  // remain the only whole-turn completion signal; this path never writes busy.
  if (event.type === 'turn_completed') {
    console.log('[ClaudeProviderSemantic] SEGMENT_END tab=' + String(tabId).slice(-12)
      + ' turn=' + String(event.turnId || '-') + ' request=' + String(event.requestId || '-'));
  }
  return terminalHistoryPreviewController.observeSemanticEvent({
    tabId, instanceId: sourceId, gap: gap === true, event,
  });
}

const providerSemanticShadow = createProviderSemanticShadow({
  log: console,
  onCodexSemanticEvent: handleCodexProviderSemanticEvent,
  onClaudeSemanticEvent: handleClaudeProviderSemanticEvent,
  authorizeCodexMainRequest: authorizeCodexProviderMainRequest,
});
function safelyObserveProviderSemantic(action, operation, fallback = null) {
  try { return operation(); } catch (error) {
    console.warn('[ProviderSemanticShadow] type=OBSERVER_ERROR action=' + action
      + ' error=' + (error?.message || String(error)));
    return fallback;
  }
}
const claudeToolScreenHolds = createClaudeToolScreenHoldTracker();

ipcMain.handle('agent-transcript:set-terminal-preview-enabled', (_event, payload = {}) => {
  const enabled = payload?.enabled !== false;
  const changed = terminalHistoryStreamingEnabled !== enabled;
  terminalHistoryStreamingEnabled = enabled;
  try {
    projectManager.db.setAppState(TERMINAL_HISTORY_STREAMING_STATE_KEY, String(enabled));
  } catch (error) {
    console.warn('[TerminalHistoryPreview] TOGGLE_PERSIST_FAILED enabled=' + enabled
      + ' error=' + (error?.message || String(error)));
  }
  const cleared = enabled
    ? 0
    : terminalHistoryPreviewController.clearAll('global-toggle-disabled');
  console.log('[TerminalHistoryPreview] TOGGLE enabled=' + enabled
    + ' changed=' + changed
    + ' cleared=' + cleared
    + ' source=' + String(payload?.source || 'renderer'));
  return { success: true, enabled, changed, cleared };
});

ipcMain.handle('agent-transcript:get-terminal-preview', (_event, payload = {}) => {
  const preview = terminalHistoryPreviewController.get(
    String(payload?.tabId || ''),
    payload?.toolType === 'claude' || payload?.toolType === 'codex'
      ? payload.toolType
      : null,
  );
  // A settled provisional block is retained only for the already-mounted
  // renderer until its canonical JSONL record arrives. A freshly mounted
  // History performs a durable load, so rehydrating an old settled terminal
  // block would recreate a duplicate after a tab switch.
  return {
    success: true,
    enabled: terminalHistoryStreamingEnabled,
    preview: preview?.phase === 'streaming' ? preview : null,
  };
});

ipcMain.handle('agent-transcript:get-semantic-shadow', (_event, payload = {}) => {
  const tabs = safelyObserveProviderSemantic(
    'snapshot',
    () => providerSemanticShadow.snapshot(String(payload?.tabId || '') || null),
    null,
  );
  return tabs
    ? { success: true, mode: 'shadow', tabs }
    : { success: false, mode: 'shadow', tabs: [], error: 'semantic-shadow-unavailable' };
});

function terminalHistoryPreviewDiagnosticNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function normalizeTerminalHistoryPreviewDiagnosticPreview(value) {
  if (!value || typeof value !== 'object') return null;
  const text = typeof value.text === 'string' ? value.text : '';
  const maxTextChars = 256 * 1024;
  const normalizedText = text.length <= maxTextChars
    ? { text, chars: text.length, truncatedForDiagnostic: false }
    : {
      head: text.slice(0, maxTextChars / 2),
      tail: text.slice(-maxTextChars / 2),
      chars: text.length,
      truncatedForDiagnostic: true,
    };
  return {
    previewId: typeof value.previewId === 'string' ? value.previewId : null,
    tabId: typeof value.tabId === 'string' ? value.tabId : null,
    toolType: value.toolType === 'claude' || value.toolType === 'codex'
      ? value.toolType
      : null,
    sessionId: typeof value.sessionId === 'string' ? value.sessionId : null,
    turnId: typeof value.turnId === 'string' ? value.turnId : null,
    lifecycleGeneration: typeof value.lifecycleGeneration === 'string'
      ? value.lifecycleGeneration
      : null,
    mirrorGeneration: typeof value.mirrorGeneration === 'string'
      ? value.mirrorGeneration
      : null,
    mirrorGenerationOrdinal: terminalHistoryPreviewDiagnosticNumber(
      value.mirrorGenerationOrdinal,
    ),
    committedFrameGeneration: terminalHistoryPreviewDiagnosticNumber(
      value.committedFrameGeneration,
    ),
    writeSeq: terminalHistoryPreviewDiagnosticNumber(value.writeSeq),
    previewSeq: terminalHistoryPreviewDiagnosticNumber(value.previewSeq),
    phase: value.phase === 'streaming' || value.phase === 'settled' ? value.phase : null,
    sourceMode: value.sourceMode === 'semantic' || value.sourceMode === 'semantic-pending'
      ? value.sourceMode
      : 'screen',
    textHash: typeof value.textHash === 'string' ? value.textHash : null,
    startedAt: terminalHistoryPreviewDiagnosticNumber(value.startedAt),
    updatedAt: terminalHistoryPreviewDiagnosticNumber(value.updatedAt),
    reason: typeof value.reason === 'string' ? value.reason : null,
    boundaryKind: typeof value.boundaryKind === 'string' ? value.boundaryKind : null,
    boundaryRow: terminalHistoryPreviewDiagnosticNumber(value.boundaryRow),
    truncated: value.truncated === true,
    promptAuthority: typeof value.promptAuthority === 'string' ? value.promptAuthority : null,
    ...normalizedText,
  };
}

function terminalHistoryPreviewDiagnosticCommandState(tabId) {
  const state = terminalCommandState.get(tabId) || null;
  if (!state) return null;
  return {
    isRunning: state.isRunning === true,
    runSeq: terminalHistoryPreviewDiagnosticNumber(state.runSeq),
    lastExitCode: terminalHistoryPreviewDiagnosticNumber(state.lastExitCode),
    lastCommand: typeof state.lastCommand === 'string' ? state.lastCommand.slice(0, 4096) : null,
    lastCommandAt: terminalHistoryPreviewDiagnosticNumber(state.lastCommandAt),
    activeCommandSource: typeof state.activeCommandSource === 'string'
      ? state.activeCommandSource
      : null,
    activeCommand: typeof state.activeCommand === 'string'
      ? state.activeCommand.slice(0, 4096)
      : null,
  };
}

async function captureTerminalHistoryPreviewDiagnostic(payload = {}) {
  const tabId = String(payload?.tabId || '');
  const toolType = payload?.toolType === 'claude' || payload?.toolType === 'codex'
    ? payload.toolType
    : null;
  if (!tabId || !toolType) throw new TypeError('tabId and toolType are required');

  const capturedAt = Date.now();
  const incidentId = crypto.randomUUID();
  const mirror = getHeadlessTerminalMirror(tabId);
  const terminal = terminals.get(tabId) || null;
  const historyEntry = normalizeHistoryEntryCopyDiagnostic(payload?.historyEntry);
  if (historyEntry && (historyEntry.tabId !== tabId || historyEntry.toolType !== toolType)) {
    throw new TypeError('history entry diagnostic owner mismatch');
  }
  const presentedPreview = normalizeTerminalHistoryPreviewDiagnosticPreview(payload?.preview);
  const currentPreview = normalizeTerminalHistoryPreviewDiagnosticPreview(
    terminalHistoryPreviewController.get(tabId, toolType),
  );
  const identity = {
    presentedPreviewId: presentedPreview?.previewId || null,
    currentPreviewId: currentPreview?.previewId || null,
    previewIdMatched: !!presentedPreview?.previewId
      && presentedPreview.previewId === currentPreview?.previewId,
    textHashMatched: !!presentedPreview?.textHash
      && presentedPreview.textHash === currentPreview?.textHash,
    lifecycleMatched: !!presentedPreview?.lifecycleGeneration
      && presentedPreview.lifecycleGeneration === getTerminalLifecycleGeneration(tabId),
    mirrorMatched: !!presentedPreview?.mirrorGeneration
      && presentedPreview.mirrorGeneration === mirror?.generation,
  };
  const incident = {
    reason: payload.incidentReason || (historyEntry ? 'manual-unconfirmed-message-copy' : 'manual-preview-context-menu'),
    ...(payload.context ? { context: payload.context } : {}),
    identity,
    presentedPreview,
    currentPreview,
  };
  if (historyEntry) {
    incident.historyEntry = historyEntry;
    incident.currentSessionId = toolType === 'codex'
      ? codexKnownSessions.get(tabId) || null
      : bridgeKnownSessions.get(tabId) || null;
    incident.messageSessionMatched = !!historyEntry.sessionId
      && historyEntry.sessionId === incident.currentSessionId;
    // Use exact message ownership, never the active tab or the newest send in
    // the project. A late confirmation is recorded alongside the status the
    // user saw when opening the menu; it does not suppress the diagnostic.
    try {
      incident.sendReceipts = historyEntry.handoffId
        ? agentSendReceiptStore.list({ tabId, handoffId: historyEntry.handoffId, limit: 16 })
          .filter((record) => record.provider === toolType)
          .map((record) => ({
            operationKey: record.operationKey, attemptId: record.attemptId,
            handoffId: record.handoffId, sessionId: record.sessionId,
            state: record.state, promptHash: record.promptHash, promptLength: record.promptLength,
            createdAt: record.createdAt, updatedAt: record.updatedAt,
            receipt: boundedDiagnosticText(JSON.stringify(record.receipt ?? null)),
            auditIdentity: record.auditIdentity || null,
          }))
        : [];
      incident.sendReceiptLookup = historyEntry.handoffId ? 'exact-tab-handoff' : 'handoff-id-unavailable';
    } catch (error) {
      incident.sendReceipts = [];
      incident.sendReceiptLookup = 'failed';
      incident.sendReceiptError = String(error?.message || error);
    }
  }
  const composerTrace = mirror?.composerForensics
    ? historyEntry
      ? snapshotTerminalComposerForensicWindow(mirror.composerForensics, {
        capturedAt, incident, handoffId: historyEntry.handoffId,
        sendAttemptId: incident.sendReceipts?.length === 1 ? incident.sendReceipts[0].attemptId : null,
      })
      : snapshotTerminalComposerForensics(mirror.composerForensics, { capturedAt, incident })
    : null;
  const liveSnapshot = mirror
    ? getHeadlessVisibleBufferSnapshot(tabId, 'manual-terminal-history-preview-diagnostic', { preferCommitted: false })
    : null;
  let serializedScreen = null;
  if (historyEntry || payload.incidentReason) {
    try {
      serializedScreen = mirror?.serializeAddon ? {
        source: 'headless-screen-serialization', encoding: 'utf8', scrollback: 0,
        mirrorGeneration: mirror.generation, writeSeq: mirror.writeSeq, flushedSeq: mirror.flushedSeq,
        // Escaped ANSI is retained as text, not stripped to plain lines. This
        // is a serialized current screen, not a fabricated original PTY log.
        ...boundedDiagnosticText(mirror.serializeAddon.serialize({ scrollback: 0 })),
      } : { unavailable: true, reason: mirror ? 'serialize-addon-unavailable' : 'no-headless-mirror' };
    } catch (error) {
      serializedScreen = { unavailable: true, reason: String(error?.message || error) };
    }
  }
  const diagnostic = {
    incident,
    terminal: {
      exists: !!terminal,
      pid: terminalHistoryPreviewDiagnosticNumber(terminal?.pid),
      lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
      command: terminalHistoryPreviewDiagnosticCommandState(tabId),
    },
    mirror: mirror ? {
      exists: true,
      failed: mirror.failed === true,
      disposed: mirror.disposed === true,
      complete: mirror.complete === true,
      incompleteReason: mirror.incompleteReason || null,
      generation: mirror.generation || null,
      generationOrdinal: terminalHistoryPreviewDiagnosticNumber(mirror.generationOrdinal),
      writeSeq: terminalHistoryPreviewDiagnosticNumber(mirror.writeSeq),
      flushedSeq: terminalHistoryPreviewDiagnosticNumber(mirror.flushedSeq),
      committedFrameGeneration: terminalHistoryPreviewDiagnosticNumber(
        mirror.committedFrameGeneration,
      ),
      pendingResizeWriteSeq: terminalHistoryPreviewDiagnosticNumber(
        mirror.pendingResizeWriteSeq,
      ),
    } : { exists: false },
    committedSnapshot: mirror?.lastCommittedVisibleSnapshot || null,
    liveSnapshot,
    redrawTrace: snapshotTerminalRedrawTrace(mirror?.redrawTrace, 48),
    composerTrace,
    replayJournal: mirror?.replayJournal?.snapshot() || null,
    ...((historyEntry || payload.incidentReason) ? { serializedScreen } : {}),
    ...(payload.rendererSnapshot ? { rendererSnapshot: payload.rendererSnapshot } : {}),
  };
  // Main snapshots above were taken at the detection boundary. A renderer
  // reply is separately timestamped and never substituted for that boundary.
  if (payload.incidentReason && !diagnostic.rendererSnapshot) {
    diagnostic.rendererSnapshot = await requestTerminalIncidentRendererSnapshot(tabId);
  }
  const persisted = await persistTerminalHistoryPreviewDiagnostic({
    logsDir: app.getPath('logs'),
    tabId,
    toolType,
    incidentId,
    capturedAt,
    diagnostic,
  });
  const reference = buildTerminalHistoryPreviewDiagnosticReference({
    ...persisted,
    tabId,
    toolType,
    sessionId: presentedPreview?.sessionId || currentPreview?.sessionId || null,
    turnId: presentedPreview?.turnId || currentPreview?.turnId || null,
    previewId: presentedPreview?.previewId || currentPreview?.previewId || null,
    ...(historyEntry ? {
      kind: 'send', sessionId: historyEntry.sessionId,
      messageId: historyEntry.messageId, handoffId: historyEntry.handoffId,
      queueStatus: historyEntry.queueStatus,
    } : {}),
  });
  console.log('[TerminalHistoryPreview] DIAGNOSTIC_SAVED'
    + ' tab=' + tabId.slice(-12)
    + ' provider=' + toolType
    + ' preview=' + String(presentedPreview?.previewId || '-').slice(-18)
    + ' currentMatched=' + identity.previewIdMatched
    + ' transitions=' + String(composerTrace?.transitions?.length || 0)
    + ' path=' + JSON.stringify(persisted.artifactPath));
  return { ...persisted, reference, snapshotAvailable: liveSnapshot?.success === true
    || !!mirror?.lastCommittedVisibleSnapshot };
}

async function captureClaudePromptShapeDiagnostic(payload) {
  const context = payload?.context;
  if (payload?.toolType !== 'claude' || !payload.tabId
    || context?.schema !== 'claude-audit-multiblock-shape-v1' || context.metadataOnly !== true) {
    throw new TypeError('Claude prompt shape metadata is required');
  }
  // Deliberately bypass all terminal/composer/renderer snapshots: this rare
  // observation needs ordered part hashes, never prompt text or image bytes.
  const persisted = await persistTerminalHistoryPreviewDiagnostic({
    logsDir: app.getPath('logs'), tabId: payload.tabId, toolType: 'claude',
    incidentId: crypto.randomUUID(), capturedAt: Date.now(),
    diagnostic: { metadataOnly: true, incident: { reason: payload.incidentReason, context } },
  });
  return { ...persisted, metadataOnly: true, snapshotAvailable: false,
    reference: buildTerminalHistoryPreviewDiagnosticReference({
      ...persisted, tabId: payload.tabId, toolType: 'claude', kind: 'send',
      sessionId: context.entity?.sessionId, messageId: context.entity?.uuid,
      handoffId: context.entity?.handoffId,
    }) };
}

const {
  createTerminalIncidentReporter,
  terminalSendIncidentNotification,
} = require(path.join(srcMainDir, 'terminal-incident-reporting'));
const { createTerminalReplayJournal } = require(path.join(srcMainDir, 'terminal-replay-journal'));
const reportTerminalIncident = createTerminalIncidentReporter({
  capture: payload => payload.incidentReason === 'claude-audit-multiblock-shape'
    ? captureClaudePromptShapeDiagnostic(payload)
    : captureTerminalHistoryPreviewDiagnostic(payload),
  notify: result => {
    let currentReceipt = null;
    if (result.sendIdentity?.operationKey) {
      try { currentReceipt = agentSendReceiptStore.get(result.sendIdentity.operationKey); }
      catch (error) {
        console.warn('[TerminalIncident] receipt lookup failed: ' + String(error?.message || error));
      }
    }
    const sendNotice = terminalSendIncidentNotification(result, currentReceipt);
    const headline = sendNotice?.headline || (result.incidentReason === 'claude-audit-multiblock-shape'
      ? 'Необычная структура сообщения Claude. Сохранён отчёт без текста сообщения.'
      : result.incidentReason === 'codex-turn-identity-contradiction'
      ? 'Codex сообщил о завершении другого хода. Сохранён диагностический отчёт.'
      : result.incidentReason === 'claude-settings-dialog-observation'
      ? 'Неоднозначный экран настройки Claude. Сохранён диагностический отчёт.'
      : result.incidentReason === 'draft-screen-contradiction'
      ? 'Копии терминала расходятся: поле ввода пустое / содержит текст.'
      : result.incidentReason === 'startup-ready-timeout'
      ? 'Готовность сессии не подтвердилась. Откройте диагностический отчёт.'
      : result.incidentReason === 'raw-input-terminal-replaced'
      ? 'Терминал заменён до записи. Отложенный ввод в новый терминал не передан.'
      : 'Отправка не подтверждена. Повторно не отправляйте: проверка продолжается.');
    const capturedReference = result.reference || ['Terminal diagnostic capture failed',
      'tabId: ' + result.tabId, 'reason: ' + result.incidentReason, 'error: ' + result.error].join('\n');
    const reference = sendNotice
      ? capturedReference + '\n' + sendNotice.referenceSuffix
      : capturedReference;
    console.warn('[TerminalIncident] ' + result.incidentReason + ' tab=' + result.tabId
      + ' saved=' + result.success + ' path=' + String(result.artifactPath || '-'));
    if (mainWindow && !mainWindow.isDestroyed() && !mainWindow.webContents.isDestroyed()) {
      mainWindow.webContents.send('terminal:incident-saved', {
        tabId: result.tabId, headline, reference, success: result.success,
        tone: sendNotice?.tone || 'warning',
      });
    }
  },
});

function reportTerminalSendDiagnostic(record, incidentReason = 'send-delivery-unconfirmed') {
  if (!record?.tabId || !['codex', 'claude'].includes(record.provider)) return;
  const delayed = incidentReason === 'send-confirmation-delayed';
  void reportTerminalIncident((delayed ? 'send-delay:' : 'send:') + record.operationKey + ':' + record.attemptId, {
    tabId: record.tabId, toolType: record.provider,
    incidentReason,
    sendIdentity: { operationKey: record.operationKey, attemptId: record.attemptId },
    historyEntry: {
      tabId: record.tabId, toolType: record.provider, sessionId: record.sessionId,
      handoffId: record.handoffId, messageId: null,
      queueStatus: delayed ? 'audit-pending' : 'delivery-unknown',
      statusReason: record.receipt?.code, statusChangedAt: record.updatedAt,
      promptText: record.receipt?.promptText || record.receipt?.transportText || '',
      imagePaths: record.receipt?.expectedImagePaths || [],
    },
  });
}

function requestTerminalIncidentRendererSnapshot(tabId) {
  const wc = mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null;
  if (!wc || wc.isDestroyed()) return Promise.resolve({ success: false, error: 'renderer-unavailable' });
  return new Promise(resolve => {
    const requestId = crypto.randomUUID();
    const finish = result => {
      clearTimeout(timer);
      ipcMain.removeListener('terminal:incident-snapshot-response', handler);
      resolve(result);
    };
    const handler = (event, payload) => {
      if (event.sender !== wc || payload?.requestId !== requestId || payload?.tabId !== tabId) return;
      finish(payload.snapshot);
    };
    const timer = setTimeout(() => finish({ success: false, error: 'renderer-diagnostic-timeout' }), 700);
    ipcMain.on('terminal:incident-snapshot-response', handler);
    try { wc.send('terminal:incident-snapshot-request', { tabId, requestId }); }
    catch (error) { finish({ success: false, error: String(error?.message || error) }); }
  });
}

function getTerminalLifecycleGeneration(tabId) {
  const terminal = terminals.get(tabId) || null;
  const runSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  if (!terminal || !Number.isInteger(runSeq) || runSeq <= 0) return null;
  let epoch = terminalLifecycleEpochs.get(terminal);
  if (!epoch) {
    epoch = crypto.randomUUID();
    terminalLifecycleEpochs.set(terminal, epoch);
  }
  return epoch + ':' + runSeq;
}

function normalizeRememberedShellCommand(command) {
  let text = String(command || '').replace(/^\x15+/, '').trim();
  const promptMatch = text.match(/^[^"'`]*@[^"'`]*(?:\s[%$#]|[❯➜])\s+(.+)$/);
  if (promptMatch) text = promptMatch[1].trim();
  text = text.replace(/^lsof\s+-ti:[^;]+;\s*/i, '').trim();
  if (!text || text === '!!') return '';
  if (/^\[[0-?]*[ -/]*[@-~]$/.test(text)) return '';
  if (/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(text)) return '';
  if (text.includes('\x1b[200~') || text.includes('\x1b[201~')) return '';
  return text;
}

function isAiLaunchShellCommand(command) {
  const text = String(command || '').trim();
  if (!text) return false;
  if (/(^|[;&|]\s*)(?:command\s+)?(?:codex|claude|gemini)(?=\s|$)/i.test(text)) return true;
  if (/(^|[;&|]\s*)(?:npx|pnpm\s+dlx|bunx)\s+@openai\/codex(?=\s|$)/i.test(text)) return true;
  return false;
}

function rememberTerminalLastCommand(tabId, command) {
  const normalized = normalizeRememberedShellCommand(command);
  if (!normalized) return;
  if (isAiLaunchShellCommand(normalized)) {
    console.log('[LastCommand] skip-ai tab=' + String(tabId).slice(-12) + ' command=' + JSON.stringify(normalized));
    return;
  }
  const state = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
  const at = Date.now();
  const cwd = terminalProjects.get(tabId) || null;
  state.lastCommand = normalized;
  state.lastCommandAt = at;
  state.lastCommandCwd = cwd;
  terminalCommandState.set(tabId, state);
  rememberTerminalLastCommandForCwd(tabId, normalized, at, cwd);
  console.log('[LastCommand] tab=' + String(tabId).slice(-12) + ' project=' + (terminalProjectIds.get(tabId) || '-') + ' cwd=' + JSON.stringify(cwd || '') + ' command=' + JSON.stringify(normalized));
}

function rememberTerminalCommandRun(tabId, command, source = 'shell', at = Date.now()) {
  const normalized = normalizeRememberedShellCommand(command);
  if (!tabId || !normalized || isAiLaunchShellCommand(normalized)) return;
  const cwd = terminalProjects.get(tabId) || null;
  const projectId = terminalProjectIds.get(tabId) || null;
  try {
    const current = projectManager?.db?.getAppState?.(COMMAND_RUN_HISTORY_KEY);
    const map = current && typeof current === 'object' && !Array.isArray(current) ? { ...current } : {};
    const existing = Array.isArray(map[tabId]) ? map[tabId] : [];
    const first = existing[0] || null;
    if (first?.command === normalized && Math.abs(Number(first.at || 0) - at) < 1500) return;
    const row = {
      id: `${at}:${tabId}`,
      tabId,
      projectId,
      cwd,
      command: normalized,
      source: source || 'shell',
      at,
    };
    map[tabId] = [row, ...existing].slice(0, COMMAND_RUN_HISTORY_PER_TAB_LIMIT);

    const rows = Object.values(map)
      .flatMap((items) => Array.isArray(items) ? items : [])
      .sort((a, b) => Number(b?.at || 0) - Number(a?.at || 0))
      .slice(0, COMMAND_RUN_HISTORY_TOTAL_LIMIT);
    const pruned = {};
    for (const item of rows) {
      if (!item?.tabId) continue;
      if (!pruned[item.tabId]) pruned[item.tabId] = [];
      if (pruned[item.tabId].length < COMMAND_RUN_HISTORY_PER_TAB_LIMIT) {
        pruned[item.tabId].push(item);
      }
    }
    projectManager?.db?.setAppState?.(COMMAND_RUN_HISTORY_KEY, pruned);
    console.log('[CommandRunHistory] tab=' + String(tabId).slice(-12) + ' project=' + (projectId || '-') + ' cwd=' + JSON.stringify(cwd || '') + ' source=' + (source || 'shell') + ' command=' + JSON.stringify(normalized));
  } catch (e) {
    console.warn('[CommandRunHistory] persist failed tab=' + String(tabId).slice(-12) + ': ' + (e?.message || e));
  }
}

function rememberDetectedTerminalCommand(tabId, command) {
  if (!tabId || !terminals.has(tabId)) return;
  if (!shouldCaptureShellInputLine(tabId)) return;
  rememberTerminalLastCommand(tabId, command);
}

function normalizeTerminalCommandMeta(meta) {
  if (!meta || typeof meta !== 'object') return null;
  const source = typeof meta.source === 'string' ? meta.source.trim() : '';
  if (source !== RESTART_AFTER_COMMAND_SOURCE) return null;
  const rawCommand = typeof meta.command === 'string' ? meta.command.trim() : '';
  const command = normalizeRememberedShellCommand(rawCommand) || rawCommand;
  return {
    source,
    command: command || null,
    at: Date.now(),
  };
}

function queueTerminalCommandMeta(tabId, meta) {
  if (!tabId) return;
  const normalized = normalizeTerminalCommandMeta(meta);
  if (!normalized) return;
  terminalPendingCommandMeta.set(tabId, normalized);
  console.log('[CommandOrigin] queued tab=' + String(tabId).slice(-12) + ' source=' + normalized.source + ' command=' + JSON.stringify(normalized.command || ''));
}

function clearTerminalActiveCommandMeta(state) {
  if (!state) return;
  delete state.activeCommandSource;
  delete state.activeCommand;
  delete state.activeCommandStartedAt;
}

function applyTerminalCommandStartMeta(tabId, state) {
  const pending = terminalPendingCommandMeta.get(tabId) || null;
  terminalPendingCommandMeta.delete(tabId);
  if (pending && Date.now() - pending.at <= TERMINAL_COMMAND_META_TTL_MS) {
    state.activeCommandSource = pending.source;
    state.activeCommand = pending.command || null;
    state.activeCommandStartedAt = Date.now();
    console.log('[CommandOrigin] active tab=' + String(tabId).slice(-12) + ' source=' + pending.source + ' command=' + JSON.stringify(pending.command || ''));
    return;
  }
  clearTerminalActiveCommandMeta(state);
}

function clearTerminalCommandOrigin(tabId, state, reason = 'clear') {
  if (!tabId || !state) return;
  if (state.activeCommandSource) {
    console.log('[CommandOrigin] clear tab=' + String(tabId).slice(-12) + ' source=' + state.activeCommandSource + ' reason=' + reason);
  }
  clearTerminalActiveCommandMeta(state);
  terminalPendingCommandMeta.delete(tabId);
}

function queueRestartRerunCommandMeta(tabId, meta) {
  if (!meta || typeof meta !== 'object') return;
  const state = terminalCommandState.get(tabId) || null;
  const command = typeof meta.command === 'string' && meta.command.trim()
    ? meta.command.trim()
    : (state?.lastCommand || terminalInitialCommand.get(tabId) || '');
  queueTerminalCommandMeta(tabId, { ...meta, command });
}

async function rememberTerminalLastCommandForCwd(tabId, command, at = Date.now(), knownCwd = null) {
  const cwd = knownCwd || await getTerminalCurrentCwd(tabId, { quiet: true });
  if (!cwd) return;
  try {
    const current = projectManager?.db?.getAppState?.(LAST_COMMANDS_BY_CWD_KEY);
    const map = current && typeof current === 'object' && !Array.isArray(current) ? { ...current } : {};
    const previousAt = Number(map[cwd]?.at || 0);
    if (previousAt > at) return;
    map[cwd] = {
      cwd,
      command,
      at,
      tabId,
      projectId: terminalProjectIds.get(tabId) || null,
    };
    const entries = Object.entries(map)
      .sort(([, a], [, b]) => Number(b?.at || 0) - Number(a?.at || 0))
      .slice(0, LAST_COMMANDS_BY_CWD_LIMIT);
    projectManager?.db?.setAppState?.(LAST_COMMANDS_BY_CWD_KEY, Object.fromEntries(entries));
  } catch (e) {
    console.warn('[LastCommand] persist failed tab=' + String(tabId).slice(-12) + ': ' + (e?.message || e));
  }
}

function shouldCaptureShellInputLine(tabId) {
  return !(
    claudeCliActive?.has?.(tabId) ||
    geminiActiveTabs?.has?.(tabId) ||
    codexKnownSessions?.has?.(tabId) ||
    codexTurnWatchers?.has?.(tabId)
  );
}

function captureTerminalInputForLastCommand(tabId, data) {
  if (typeof data !== 'string') return;
  if (data.includes('\x1b[200~') || data.includes('\x1b[201~')) return;
  if (!shouldCaptureShellInputLine(tabId)) {
    terminalInputLineBuffers.delete(tabId);
    terminalInputEscapeStates.delete(tabId);
    return;
  }

  let buffer = terminalInputLineBuffers.get(tabId) || '';
  let escapeState = terminalInputEscapeStates.get(tabId) || '';
  for (const ch of data) {
    const code = ch.charCodeAt(0);
    if (escapeState === 'esc') {
      if (ch === '[') {
        escapeState = 'csi';
      } else if (ch === ']') {
        escapeState = 'osc';
      } else {
        escapeState = '';
      }
      continue;
    }
    if (escapeState === 'csi') {
      if (code >= 0x40 && code <= 0x7e) escapeState = '';
      continue;
    }
    if (escapeState === 'osc') {
      if (ch === '\x07') {
        escapeState = '';
      } else if (ch === '\x1b') {
        escapeState = 'osc-esc';
      }
      continue;
    }
    if (escapeState === 'osc-esc') {
      escapeState = ch === '\\' ? '' : 'osc';
      continue;
    }

    if (ch === '\x03' || ch === '\x15') {
      buffer = '';
      continue;
    }
    if (ch === '\x1b') {
      buffer = '';
      escapeState = 'esc';
      continue;
    }
    if (ch === '\x7f' || ch === '\x08') {
      buffer = buffer.slice(0, -1);
      continue;
    }
    if (ch === '\r' || ch === '\n') {
      rememberTerminalLastCommand(tabId, buffer);
      buffer = '';
      continue;
    }
    if (ch === '\t' || code >= 32) {
      buffer += ch;
    }
  }

  if (buffer) terminalInputLineBuffers.set(tabId, buffer);
  else terminalInputLineBuffers.delete(tabId);
  if (escapeState) terminalInputEscapeStates.set(tabId, escapeState);
  else terminalInputEscapeStates.delete(tabId);
}

function hasClaimedAiLifecycle(tabId) {
  return claudeCliActive.get(tabId) === true
    || bridgeKnownSessions.has(tabId)
    || codexLaunchAcceptancePending.has(tabId)
    || codexKnownSessions.has(tabId)
    || codexLastRunCommandPayload.has(tabId)
    || codexTurnWatchers.has(tabId)
    || codexTuiReadyTabs.has(tabId);
}

function readHeadlessShellPromptFrame(tabId) {
  const state = getHeadlessTerminalMirror(tabId);
  const terminal = state?.terminal;
  const buf = terminal?.buffer?.active;
  if (
    !state
    || state.complete !== true
    || !terminal
    || !buf
    || state.redrawTrace?.synchronizedOutputOpen === true
    || Number(state.writeSeq || 0) !== Number(state.flushedSeq || 0)
  ) return null;
  const cursorRow = Number(buf.baseY || 0) + Number(buf.cursorY || 0);
  const logical = getLogicalLineSnapshotAt(buf, cursorRow);
  if (!logical) return null;
  return {
    mirrorGeneration: state.generation,
    bufferType: buf.type,
    lineText: String(logical.text || ''),
    cursorX: Number(buf.cursorX || 0),
    inputRevision: getTerminalInputRevision(tabId),
  };
}

function captureReadyShellPromptFrameAfterWrite(tabId, terminalToken) {
  const readiness = terminalShellReadiness.snapshot(tabId, terminalToken);
  if (
    readiness.ready !== true
    || !Number.isFinite(Number(readiness.readyAt))
    || terminalShellReadiness.promptFrameSnapshot(tabId, terminalToken)
    || terminalShellPromptFrameCapturePending.get(tabId) === Number(readiness.readyAt)
  ) return false;
  const readyAt = Number(readiness.readyAt);
  const inputRevisionAtPrompt = getTerminalInputRevision(tabId);
  terminalShellPromptFrameCapturePending.set(tabId, readyAt);
  void flushHeadlessTerminalMirror(tabId)
    .then(() => {
      const currentReadiness = terminalShellReadiness.snapshot(tabId, terminalToken);
      if (
        terminals.get(tabId) !== terminalToken
        || currentReadiness.ready !== true
        || Number(currentReadiness.readyAt) !== readyAt
        || getTerminalInputRevision(tabId) !== inputRevisionAtPrompt
      ) return;
      const frame = readHeadlessShellPromptFrame(tabId);
      if (!frame) return;
      if (terminalShellReadiness.markPromptFrame(
        tabId,
        terminalToken,
        readyAt,
        frame,
      )) {
        console.log('[AgentShellLaunch] prompt baseline captured tab='
          + String(tabId).slice(-12)
          + ' chars=' + frame.lineText.length
          + ' cursorX=' + frame.cursorX);
      }
    })
    .catch((error) => {
      console.warn('[AgentShellLaunch] prompt baseline capture failed tab='
        + String(tabId).slice(-12)
        + ' error=' + (error?.message || String(error)));
    })
    .finally(() => {
      if (terminalShellPromptFrameCapturePending.get(tabId) === readyAt) {
        terminalShellPromptFrameCapturePending.delete(tabId);
      }
    });
  return true;
}

async function reconcileShellDraftProofForLaunch(tabId, expectedTerm) {
  const trackedDraftChars = String(terminalInputLineBuffers.get(tabId) || '').length;
  const inputRevision = getTerminalInputRevision(tabId);
  const baseline = terminalShellReadiness.promptFrameSnapshot(tabId, expectedTerm);
  if (!baseline) {
    return {
      status: trackedDraftChars > 0 ? 'draft' : 'unknown',
      reason: trackedDraftChars > 0 ? 'tracked-input-without-prompt-frame' : 'prompt-frame-unavailable',
      trackedDraftChars,
    };
  }
  await flushHeadlessTerminalMirror(tabId);
  if (terminals.get(tabId) !== expectedTerm) {
    return { status: 'unknown', reason: 'terminal-generation-changed', trackedDraftChars };
  }
  if (getTerminalInputRevision(tabId) !== inputRevision) {
    return { status: 'unknown', reason: 'input-changed-during-prompt-proof', trackedDraftChars };
  }
  const decision = classifyTerminalShellDraftProof({
    baseline,
    current: readHeadlessShellPromptFrame(tabId),
  });
  if (decision.status === 'empty' && trackedDraftChars > 0) {
    terminalInputLineBuffers.delete(tabId);
    terminalInputEscapeStates.delete(tabId);
    console.warn('[AgentShellLaunch] cleared stale tracked input tab='
      + String(tabId).slice(-12)
      + ' chars=' + trackedDraftChars
      + ' proof=' + decision.reason);
  }
  return { ...decision, trackedDraftChars };
}

async function proveIdleShellForAgentLaunch(tabId, toolType, options = {}) {
  const expectedTerm = options.expectedTerm || terminals.get(tabId);
  const expectedInputRevision = getTerminalInputRevision(tabId);
  const expectedLifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const expectedRunSeq = Number.isFinite(options.expectedRunSeq)
    ? Number(options.expectedRunSeq)
    : null;
  const allowCurrentLaunchClaim = options.allowCurrentLaunchClaim === true;
  const allowCurrentStoppingClaim = options.allowCurrentStoppingClaim === true;

  const readLocalState = () => {
    const state = terminalCommandState.get(tabId) || null;
    const generationChanged = expectedRunSeq !== null
      && Number(state?.runSeq || 0) !== expectedRunSeq;
    const shellPromptReady = terminalShellReadiness.snapshot(tabId, expectedTerm).ready === true;
    return {
      state,
      generationChanged,
      shellPromptReady,
      commandRunning: state?.isRunning === true
        && !(allowCurrentLaunchClaim && !generationChanged),
      lifecycleClaimed: !allowCurrentLaunchClaim && hasClaimedAiLifecycle(tabId),
      stopping: aiStoppingTabs.has(tabId) && !allowCurrentStoppingClaim,
    };
  };

  if (!expectedTerm || terminals.get(tabId) !== expectedTerm) {
    return { allowed: false, reason: 'terminal_generation_changed', lookup: null };
  }
  const shellDraftProof = await reconcileShellDraftProofForLaunch(tabId, expectedTerm);
  if (getTerminalInputRevision(tabId) !== expectedInputRevision) {
    return { allowed: false, reason: 'terminal_input_changed_before_launch', lookup: null };
  }
  if (shellDraftProof.status === 'draft') {
    return {
      allowed: false,
      reason: 'terminal_has_unsent_input',
      lookup: null,
      draftChars: shellDraftProof.trackedDraftChars,
      draftProof: shellDraftProof.reason,
    };
  }
  const before = readLocalState();
  if (before.generationChanged) {
    return { allowed: false, reason: 'terminal_command_generation_changed', lookup: null };
  }
  // A retained OSC-A shell prompt is stronger than a stale app-owned
  // `isRunning=true` projection, but it is not enough on its own: the same
  // fresh process snapshot below must also prove that the shell owns the PTY
  // foreground group and that no AI descendant exists.
  const staleCommandCandidate = before.commandRunning && before.shellPromptReady;
  const localDecision = decideAgentShellLaunchAdmission({
    processLookupStatus: AI_PROCESS_LOOKUP_STATUS.ABSENT,
    commandRunning: before.commandRunning && !staleCommandCandidate,
    lifecycleClaimed: before.lifecycleClaimed,
    stopping: before.stopping,
  });
  if (!localDecision.allowed) {
    return { ...localDecision, lookup: null };
  }

  // Ctrl+C is destructive in a live TUI. Bypass both lookup caches and prove
  // that this PTY currently has no Claude/Codex/Gemini descendant at the final
  // write boundary. UNKNOWN is deliberately not treated as absence.
  invalidateAiProcessLookupCache(tabId);
  let processSnapshot = null;
  const lookup = await inspectAiDescendantProcessesByTab(tabId, null, {
    forceFresh: true,
    onSnapshot: (snapshot) => { processSnapshot = snapshot; },
  });
  if (terminals.get(tabId) !== expectedTerm) {
    return { allowed: false, reason: 'terminal_generation_changed', lookup };
  }
  // A fresh process lookup says nothing about text typed while it was pending.
  // The input belongs to the user even if its echo has not reached the mirror.
  if (getTerminalInputRevision(tabId) !== expectedInputRevision) {
    return { allowed: false, reason: 'terminal_input_changed_before_launch', lookup };
  }
  if (getTerminalLifecycleGeneration(tabId) !== expectedLifecycleGeneration) {
    return { allowed: false, reason: 'terminal_generation_changed', lookup };
  }
  const after = readLocalState();
  if (after.generationChanged) {
    return { allowed: false, reason: 'terminal_command_generation_changed', lookup };
  }
  const staleAfterLookup = after.commandRunning && after.shellPromptReady;
  let foreground = null;
  if (staleAfterLookup && lookup.status === AI_PROCESS_LOOKUP_STATUS.ABSENT) {
    const shellProcess = processSnapshot?.processesByPid?.get?.(Number(expectedTerm.pid)) || null;
    const descendants = processSnapshot
      ? collectDescendantProcessEntries(processSnapshot.children, Number(expectedTerm.pid))
      : [];
    foreground = classifyTerminalForegroundSnapshot({ shellProcess, descendants });
    if (foreground.status === 'unknown') {
      return {
        allowed: false,
        reason: foreground.reason,
        lookup: { ...lookup, status: AI_PROCESS_LOOKUP_STATUS.UNKNOWN },
        foreground,
      };
    }
    if (foreground.status === 'found') {
      return {
        allowed: false,
        reason: 'foreground_command_running',
        lookup,
        foreground,
      };
    }
  }
  const reconciledStaleCommand = staleAfterLookup
    && lookup.status === AI_PROCESS_LOOKUP_STATUS.ABSENT
    && foreground?.status === 'absent';
  const decision = decideAgentShellLaunchAdmission({
    processLookupStatus: lookup.status,
    commandRunning: after.commandRunning && !reconciledStaleCommand,
    lifecycleClaimed: after.lifecycleClaimed,
    stopping: after.stopping,
  });
  if (!decision.allowed) {
    console.warn('[AgentShellLaunch] blocked tab=' + String(tabId).slice(-12)
      + ' tool=' + toolType
      + ' reason=' + decision.reason
      + ' lookup=' + lookup.status
      + ' pids=' + lookup.matches.map((match) => match.pid).join(','));
  }
  if (decision.allowed && reconciledStaleCommand && after.state) {
    after.state.isRunning = false;
    after.state.lastExitCode = Number.isFinite(Number(after.state.lastExitCode))
      ? Number(after.state.lastExitCode)
      : 0;
    clearTerminalCommandOrigin(tabId, after.state, 'stale-shell-command-reconciled');
    terminalCommandState.set(tabId, after.state);
    console.warn('[AgentShellLaunch] reconciled stale command state tab=' + String(tabId).slice(-12)
      + ' tool=' + toolType
      + ' runSeq=' + Number(after.state.runSeq || 0)
      + ' proof=retained-shell-prompt+foreground-shell+no-ai-descendant');
  }
  return {
    ...decision, lookup, foreground, draftProof: shellDraftProof.reason,
    // This private in-process witness is consumed at the synchronous write,
    // not reconstructed from a tab ID or an earlier empty-screen observation.
    shellWriteProof: decision.allowed ? {
      terminalToken: expectedTerm,
      runSeq: Number(after.state?.runSeq || 0),
      inputRevision: expectedInputRevision,
      lifecycleGeneration: expectedLifecycleGeneration,
    } : null,
  };
}

function agentShellLaunchError(admission, alreadyRunningError) {
  if (admission?.reason === 'terminal_input_changed_before_launch') {
    return 'terminal_input_changed_before_launch';
  }
  if (admission?.reason === 'terminal_has_unsent_input') {
    return 'terminal_has_unsent_input';
  }
  if (admission?.lookup?.status === AI_PROCESS_LOOKUP_STATUS.UNKNOWN) {
    return 'process_lookup_failed';
  }
  if (admission?.lookup?.status === AI_PROCESS_LOOKUP_STATUS.FOUND) {
    return alreadyRunningError;
  }
  return 'shell_not_idle';
}

function writeAgentLaunchCommandToIdleShell(term, { tabId, toolType, command, launchId = null, admission }) {
  if (!term || terminals.get(tabId) !== term) {
    throw new Error('terminal_generation_changed');
  }
  const proof = admission?.allowed === true ? admission.shellWriteProof : null;
  if (!proof || proof.terminalToken !== term
    || proof.runSeq !== Number(terminalCommandState.get(tabId)?.runSeq || 0)
    || proof.lifecycleGeneration !== getTerminalLifecycleGeneration(tabId)) {
    throw new Error('terminal_generation_changed');
  }
  if (proof.inputRevision !== getTerminalInputRevision(tabId)) {
    throw new Error('terminal_input_changed_before_launch');
  }
  const trackedDraftChars = String(terminalInputLineBuffers.get(tabId) || '').length;
  terminalInputLineBuffers.delete(tabId);
  terminalInputEscapeStates.delete(tabId);
  const input = buildAgentShellLaunchInput(command);
  console.log('[AgentShellLaunch] clear-and-write tab=' + String(tabId).slice(-12)
    + ' tool=' + toolType
    + ' launch=' + (launchId || '-')
    + ' lookup=absent'
    + ' trackedDraftChars=' + trackedDraftChars
    + ' bytes=' + input.length);
  term.write(input);
}

function markClaudeShellLaunchStarted(
  tabId,
  sessionId = null,
  reason = 'claude-run-command',
  {
    expectsInterruptPrelude = true,
    sawOscCommandStart = false,
    emitCommandStarted = true,
  } = {},
) {
  claudeCliActive.set(tabId, true);
  clearAiStopping(tabId, reason);
  const commandState = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
  commandState.isRunning = true;
  clearTerminalCommandOrigin(tabId, commandState, reason);
  terminalCommandState.set(tabId, commandState);
  claudeStartupIntents.set(tabId, {
    sessionId: sessionId || null,
    at: Date.now(),
    reason,
    terminalToken: terminals.get(tabId) || null,
    expectsInterruptPrelude,
    sawOscCommandStart,
  });
  // The accepted shell command is the launch boundary. Readiness events only
  // join this generation; they are not competing owners of process identity.
  const launchGeneration = beginClaudeLaunchGeneration(
    tabId,
    null,
    reason,
    {
      launchMode: sessionId ? 'resume' : 'fresh',
      sessionIdHint: sessionId || null,
    },
  );
  if (emitCommandStarted && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:command-started', { tabId, commandType: 'claude' });
  }
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId: sessionId || null,
    busy: false,
    sessionStatus: 'starting',
    starting: true,
    inputReady: false,
    toolType: 'claude',
    commandType: 'claude',
  });
  return launchGeneration;
}

function rollbackClaudeShellLaunchClaims(tabId, {
  sessionId = null,
  reason = 'claude-shell-launch-write-failed',
} = {}) {
  if (claudeState.get(tabId) === 'WAITING_PROMPT') claudeState.delete(tabId);
  claudePendingPrompt.delete(tabId);
  if (sessionId) clearClaudePendingJsonlOwner(sessionId, tabId, reason);
  console.warn('[Claude Runner] launch claims rolled back tab=' + String(tabId).slice(-12)
    + ' session=' + (sessionId ? String(sessionId).slice(0, 8) : '-')
    + ' reason=' + reason);
}

function readHeadlessCursorMetrics(state) {
  const terminal = state?.terminal;
  const buf = terminal?.buffer?.active;
  if (!terminal || !buf) return null;
  return {
    rows: terminal.rows,
    cols: terminal.cols,
    bufferType: buf.type,
    bufferLength: buf.length,
    baseY: buf.baseY,
    viewportY: buf.viewportY,
    cursorX: buf.cursorX,
    cursorY: buf.cursorY,
    cursorRow: buf.baseY + buf.cursorY,
    cursorVisible: state.redrawTrace?.cursorVisible ?? null,
  };
}

function logTerminalComposerForensicError(tabId, state, phase, error) {
  const now = Date.now();
  if (state && now - Number(state.lastComposerForensicErrorAt || 0) < 5000) return;
  if (state) state.lastComposerForensicErrorAt = now;
  console.warn('[TerminalComposerForensics] phase=' + phase
    + ' tab=' + String(tabId).slice(-12)
    + ' error=' + (error?.message || String(error)));
}

function recordComposerForensicPtyInput(tabId, data, meta = {}) {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state?.composerForensics) return null;
  const value = String(data || '');
  const singlePrintable = value.length === 1
    && value.charCodeAt(0) >= 32
    && value.charCodeAt(0) !== 127;
  // The committed composer frames already retain character-by-character
  // typing. Keeping the same printable byte again as an input event would
  // evict the earlier Enter which made a residual-cell incident causal.
  if (singlePrintable && meta.checkpoint !== true && meta.keepSinglePrintable !== true) {
    return null;
  }
  try {
    return recordTerminalComposerInput(state.composerForensics, data, {
      ...meta,
      revision: meta.revision ?? getTerminalInputRevision(tabId),
      terminalRunSeq: meta.terminalRunSeq
        ?? Number(terminalCommandState.get(tabId)?.runSeq || 0),
      lifecycleGeneration: meta.lifecycleGeneration
        ?? getTerminalLifecycleGeneration(tabId),
      mirrorGeneration: meta.mirrorGeneration ?? state.generation,
      mirrorWriteSeq: meta.mirrorWriteSeq ?? state.writeSeq,
    });
  } catch (error) {
    logTerminalComposerForensicError(tabId, state, 'input', error);
    return null;
  }
}

function resolveTerminalComposerForensicProvider(tabId, state, terminalRunSeq, lifecycleGeneration) {
  const identityKey = String(terminalRunSeq || 0) + ':' + String(lifecycleGeneration || 'none');
  const now = Date.now();
  if (state?.composerForensicProviderIdentityKey === identityKey) {
    if (state.composerForensicProvider) return state.composerForensicProvider;
    if (now - Number(state.composerForensicProviderCheckedAt || 0) < 1000) return 'unknown';
  }
  const provider = resolveAiToolTypeForTab(tabId, null);
  if (state) {
    state.composerForensicProviderIdentityKey = identityKey;
    state.composerForensicProviderCheckedAt = now;
    state.composerForensicProvider = provider || null;
  }
  return provider || 'unknown';
}

function buildTerminalComposerForensicObservation(tabId, snapshot, provider = 'unknown') {
  const sourceLines = Array.isArray(snapshot?.lines) ? snapshot.lines : [];
  const baseY = Number(snapshot?.baseY);
  const cursorY = Number(snapshot?.cursorY);
  const cursorX = Number(snapshot?.cursorX);
  const cursorRow = Number.isFinite(baseY) && Number.isFinite(cursorY)
    ? baseY + cursorY
    : null;
  let proof = null;
  if (provider === 'claude') {
    try { proof = parseClaudeComposerCurrentFrame(snapshot); } catch { proof = null; }
  }
  let promptRow = Number.isFinite(Number(proof?.promptRow))
    ? Number(proof.promptRow)
    : findTerminalPreviewCursorComposerRow(snapshot);
  if (provider === 'codex' && !Number.isFinite(promptRow)) {
    const candidate = snapshot?.codexActivePrompt?.row
      ?? snapshot?.codexCursorComposer?.row;
    if (Number.isFinite(Number(candidate))) promptRow = Number(candidate);
  }
  if (!Number.isFinite(promptRow)) promptRow = null;

  let relevantLines = [];
  if (promptRow !== null && Number.isFinite(cursorRow)) {
    const lower = Math.min(promptRow, cursorRow);
    const upper = Math.max(promptRow, cursorRow);
    relevantLines = sourceLines.filter((line) => {
      const row = Number(line?.row);
      return Number.isFinite(row) && row >= lower && row <= upper;
    });
    if (relevantLines.length > 14) {
      relevantLines = [
        ...relevantLines.slice(0, 2),
        ...relevantLines.slice(-12),
      ];
    }
  }
  const lines = relevantLines.map((line) => ({
    row: Number(line?.row),
    text: String(line?.text || '').slice(0, 1024),
    wrapped: line?.wrapped === true,
    occupiedEndX: Number.isFinite(Number(line?.occupiedEndX))
      ? Number(line.occupiedEndX)
      : null,
    promptCellX: Number.isFinite(Number(line?.promptCellX))
      ? Number(line.promptCellX)
      : null,
    promptSuffixAllDim: line?.promptSuffixAllDim === true,
    promptSuffixHasInverse: line?.promptSuffixHasInverse === true,
    promptSuffixHasNonDefaultBg: line?.promptSuffixHasNonDefaultBg === true,
    promptSuffixWrapped: line?.promptSuffixWrapped === true,
    hasDim: line?.hasDim === true,
    allTextDim: line?.allTextDim === true,
    hasInverse: line?.hasInverse === true,
    hasNonDefaultBg: line?.hasNonDefaultBg === true,
    firstTextStyle: line?.firstTextStyle || null,
  }));
  let proofOutcome = proof?.proofOutcome || 'unknown';
  let proofReason = proof?.proofReason || 'provider-composer-proof-unavailable';
  if (provider === 'codex' && snapshot?.codexCursorComposer?.hasDraft === true) {
    proofOutcome = 'found';
    proofReason = 'codex-current-composer-text';
  } else if (provider === 'codex' && promptRow !== null) {
    proofReason = 'codex-active-prompt-visible';
  }
  return {
    provider,
    proofOutcome,
    proofReason,
    exactCaptureRecommended: proof?.exactCaptureRecommended === true,
    promptRow,
    cursorRow: promptRow === null ? null : cursorRow,
    cursorX: promptRow === null || !Number.isFinite(cursorX) ? null : cursorX,
    occupiedEndX: Number.isFinite(Number(proof?.occupiedEndX))
      ? Number(proof.occupiedEndX)
      : null,
    screenText: lines.map((line) => line.text).join('\n').slice(0, 8192),
    lines,
  };
}

function observeCommittedTerminalComposerForensics(
  tabId,
  state,
  snapshot,
  committedFrameGeneration,
) {
  if (!state?.composerForensics || !snapshot?.success) return null;
  try {
    const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
    const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
    const provider = resolveTerminalComposerForensicProvider(
      tabId,
      state,
      terminalRunSeq,
      lifecycleGeneration,
    );
    return observeTerminalComposerFrame(
      state.composerForensics,
      buildTerminalComposerForensicObservation(tabId, snapshot, provider),
      {
        writeSeq: snapshot.writeSeq,
        flushedSeq: snapshot.flushedSeq,
        committedFrameGeneration,
        rows: snapshot.rows,
        cols: snapshot.cols,
        inputRevision: getTerminalInputRevision(tabId),
        terminalRunSeq,
        lifecycleGeneration,
        mirrorGeneration: state.generation,
        mirrorGenerationOrdinal: state.generationOrdinal,
      },
    );
  } catch (error) {
    logTerminalComposerForensicError(tabId, state, 'committed-frame', error);
    return null;
  }
}

function buildHeadlessDraftProofDiagnostic(tabId, proof, reason) {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) return { available: false, reason: 'no-headless-mirror' };
  const terminal = state.terminal;
  const buf = terminal?.buffer?.active;
  if (!terminal || !buf) return { available: false, reason: 'no-headless-buffer' };
  const cursorRow = Number.isFinite(Number(proof?.cursorRow))
    ? Number(proof.cursorRow)
    : buf.baseY + buf.cursorY;
  const promptRow = Number.isFinite(Number(proof?.promptRow))
    ? Number(proof.promptRow)
    : null;
  const requestedRows = new Set();
  for (let row = cursorRow - 4; row <= cursorRow + 4; row += 1) requestedRows.add(row);
  if (promptRow !== null) {
    for (let row = promptRow - 2; row <= promptRow + 2; row += 1) requestedRows.add(row);
  }
  const rows = Array.from(requestedRows)
    .sort((a, b) => a - b)
    .filter((row) => row >= 0 && row < buf.length)
    .slice(0, 16)
    .map((row) => {
      const line = buf.getLine(row);
      const text = String(line?.translateToString?.(true) || '');
      const styles = summarizeXtermLineStyles(line);
      return {
        row,
        cursor: row === cursorRow,
        prompt: promptRow !== null && row === promptRow,
        wrapped: !!line?.isWrapped,
        text: text.slice(0, 180),
        firstTextStyle: styles.firstTextStyle,
        hasInverse: styles.hasInverse,
        hasNonDefaultBg: styles.hasNonDefaultBg,
      };
    });
  return {
    available: true,
    reason,
    generation: state.generation,
    generationOrdinal: state.generationOrdinal,
    complete: state.complete === true,
    writeSeq: state.writeSeq,
    flushedSeq: state.flushedSeq,
    cursor: readHeadlessCursorMetrics(state),
    proof: {
      outcome: proof?.proofOutcome ?? null,
      reason: proof?.proofReason ?? null,
      source: proof?.source ?? null,
      promptRow,
      cursorRow,
      cursorX: proof?.cursorX ?? buf.cursorX,
      terminalRunSeq: proof?.terminalRunSeq ?? null,
      inputRevision: proof?.inputRevision ?? null,
      terminalLifecycleGeneration: proof?.terminalLifecycleGeneration ?? null,
      mirrorGeneration: proof?.mirrorGeneration ?? null,
    },
    rows,
    redraw: snapshotTerminalRedrawTrace(state.redrawTrace, 18),
  };
}

function decorateAgentDraftProofIdentity(tabId, proof) {
  const state = getHeadlessTerminalMirror(tabId);
  return {
    ...(proof || {}),
    terminalRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    inputRevision: getTerminalInputRevision(tabId),
    terminalLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    mirrorGeneration: state?.generation || null,
    mirrorGenerationOrdinal: state?.generationOrdinal ?? null,
    mirrorWriteSeq: state?.writeSeq ?? null,
    mirrorFlushedSeq: state?.flushedSeq ?? null,
    mirrorSynchronizedOutputOpen: state?.redrawTrace?.synchronizedOutputOpen === true,
    synchronizedOutputGeneration: Number(
      state?.redrawTrace?.synchronizedOutputGeneration || 0,
    ),
  };
}

function logAgentDraftProofContradiction(tabId, agent, pending, text) {
  const proof = pending?.draftProof || null;
  if (
    !proof
    || (
      proof.hasDraft !== true
      && proof.proofOutcome !== 'found'
      && proof.exactCaptureRecommended !== true
    )
    || String(text || '').trim()
    || !['grab', 'copy'].includes(pending?.mode)
  ) return null;
  const identityStable = validateAgentInputIdentity(tabId, pending.captureIdentity)
    && pending.draftProofIdentityAtWrite === true
    && agentDraftProofMatchesCaptureIdentity(
      proof,
      pending.draftProofCaptureIdentity || pending.captureIdentity,
    );
  const before = pending.draftProofDiagnostic || null;
  const rendererBefore = proof.rendererDiagnostic || null;
  const parity = compareAgentDraftScreenParity(before, rendererBefore);
  console.error('[AgentDraftProof:CONTRADICTION] agent=' + agent
    + ' tab=' + String(tabId).slice(-12)
    + ' screen=' + (proof.proofOutcome || (proof.hasDraft === true ? 'found' : 'unknown'))
    + ' ctrlG=absent'
    + ' identityStable=' + identityStable
    + ' parity=' + JSON.stringify(parity)
    + ' rendererBefore=' + JSON.stringify(rendererBefore)
    + ' headlessBefore=' + JSON.stringify(before)
    + ' after=' + JSON.stringify(buildHeadlessDraftProofDiagnostic(
      tabId,
      proof,
      'ctrl-g-empty-after-screen-found',
    )));
  void captureAgentDraftForensicArtifact(
    tabId,
    agent,
    proof,
    'ctrl-g-empty-after-screen-found',
    {
      mode: pending?.mode || null,
      identityStable,
      parity,
    },
  );
  requestAgentDraftScreenDiagnostic(
    tabId,
    agent,
    proof,
    'ctrl-g-empty-after-screen-found',
  );
  return { proof, before, rendererBefore, parity };
}

function logAgentDraftProofContradictionAfterReturn(
  tabId,
  agent,
  contradiction,
  editorReturn,
  identityStable,
  inputRevisionTransitionOwned,
) {
  if (!contradiction) return;
  console.error('[AgentDraftProof:CONTRADICTION_AFTER_RETURN] agent=' + agent
    + ' tab=' + String(tabId).slice(-12)
    + ' editorReturn=' + (editorReturn?.ready === true)
    + ' editorReason=' + (editorReturn?.reason || '-')
    + ' identityStable=' + (identityStable === true)
    + ' inputTransitionOwned=' + (inputRevisionTransitionOwned === true)
    + ' frame=' + JSON.stringify(buildHeadlessDraftProofDiagnostic(
      tabId,
      contradiction.proof,
      'ctrl-g-editor-return-frame',
    )));
}

const AGENT_DRAFT_SCREEN_DIAGNOSTIC_TIMEOUT_MS = 65_000;
const pendingAgentDraftScreenDiagnostics = new Map();
const pendingAgentDraftScreenDiagnosticByTab = new Map();

function finishAgentDraftScreenDiagnostic(requestId) {
  const pending = pendingAgentDraftScreenDiagnostics.get(requestId);
  if (!pending) return null;
  clearTimeout(pending.timer);
  pendingAgentDraftScreenDiagnostics.delete(requestId);
  if (pendingAgentDraftScreenDiagnosticByTab.get(pending.tabId) === requestId) {
    pendingAgentDraftScreenDiagnosticByTab.delete(pending.tabId);
  }
  return pending;
}

function requestAgentDraftScreenDiagnostic(tabId, agent, proof, reason) {
  if (!mainWindow || mainWindow.isDestroyed() || mainWindow.webContents.isDestroyed()) return null;
  const previousRequestId = pendingAgentDraftScreenDiagnosticByTab.get(tabId);
  if (previousRequestId) finishAgentDraftScreenDiagnostic(previousRequestId);

  const requestId = crypto.randomUUID();
  const timer = setTimeout(() => {
    const expired = finishAgentDraftScreenDiagnostic(requestId);
    if (!expired) return;
    console.error('[AgentDraftProof:SCREEN_FOLLOWUP_TIMEOUT] agent=' + expired.agent
      + ' tab=' + String(expired.tabId).slice(-12)
      + ' request=' + requestId
      + ' reason=' + expired.reason);
  }, AGENT_DRAFT_SCREEN_DIAGNOSTIC_TIMEOUT_MS);
  pendingAgentDraftScreenDiagnostics.set(requestId, {
    requestId,
    tabId,
    agent,
    proof,
    reason,
    timer,
    requestedAt: Date.now(),
    retryCount: 0,
  });
  pendingAgentDraftScreenDiagnosticByTab.set(tabId, requestId);
  mainWindow.webContents.send('terminal:draft-screen-diagnostic-request', {
    requestId,
    tabId,
    reason,
    promptRow: Number.isFinite(Number(proof?.promptRow)) ? Number(proof.promptRow) : null,
    cursorRow: Number.isFinite(Number(proof?.cursorRow)) ? Number(proof.cursorRow) : null,
  });
  return requestId;
}

async function captureAgentDraftScreenArtifact(webContents, pending, rendererDiagnostic) {
  const dom = rendererDiagnostic?.dom || null;
  const x = Math.max(0, Math.floor(Number(dom?.left)));
  const y = Math.max(0, Math.floor(Number(dom?.top)));
  const width = Math.max(1, Math.floor(Number(dom?.width)));
  const height = Math.max(1, Math.floor(Number(dom?.height)));
  if (
    dom?.painted !== true
    || !Number.isFinite(x)
    || !Number.isFinite(y)
    || !Number.isFinite(width)
    || !Number.isFinite(height)
    || width <= 1
    || height <= 1
    || !webContents
    || webContents.isDestroyed()
  ) return null;
  try {
    const image = await webContents.capturePage({ x, y, width, height });
    const logsDir = app.getPath('logs');
    await fs.promises.mkdir(logsDir, { recursive: true });
    const safeTab = String(pending.tabId).slice(-24).replace(/[^a-z0-9_-]/gi, '_');
    const artifactPath = path.join(logsDir, `agent-draft-screen-${safeTab}-latest.png`);
    await fs.promises.writeFile(artifactPath, image.toPNG());
    console.error('[AgentDraftProof:SCREEN_ARTIFACT] agent=' + pending.agent
      + ' tab=' + String(pending.tabId).slice(-12)
      + ' request=' + pending.requestId
      + ' rendererCapturedAt=' + (rendererDiagnostic?.capturedAt ?? '-')
      + ' artifactCapturedAt=' + Date.now()
      + ' path=' + JSON.stringify(artifactPath));
    return artifactPath;
  } catch (error) {
    console.error('[AgentDraftProof:SCREEN_ARTIFACT_FAILED] agent=' + pending.agent
      + ' tab=' + String(pending.tabId).slice(-12)
      + ' request=' + pending.requestId
      + ' error=' + (error?.message || String(error)));
    return null;
  }
}

async function captureAgentDraftForensicArtifact(
  tabId,
  agent,
  proof,
  reason,
  context = {},
) {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state?.composerForensics) return null;
  try {
    const trace = snapshotTerminalComposerForensics(state.composerForensics, {
      incident: {
        agent,
        reason,
        mode: context.mode || null,
        identityStable: context.identityStable === true,
        parity: context.parity || null,
        command: typeof context.command === 'string' ? context.command : null,
        source: typeof context.source === 'string' ? context.source : null,
        startupGeneration: context.startupGeneration || null,
        pasteWritten: context.pasteWritten === true,
        enterWritten: context.enterWritten === true,
        proof: {
          outcome: proof?.proofOutcome ?? null,
          reason: proof?.proofReason ?? null,
          source: proof?.source ?? null,
          promptRow: Number.isFinite(Number(proof?.promptRow))
            ? Number(proof.promptRow)
            : null,
          cursorRow: Number.isFinite(Number(proof?.cursorRow))
            ? Number(proof.cursorRow)
            : null,
          cursorX: Number.isFinite(Number(proof?.cursorX))
            ? Number(proof.cursorX)
            : null,
          occupiedEndX: Number.isFinite(Number(proof?.occupiedEndX))
            ? Number(proof.occupiedEndX)
            : null,
          terminalRunSeq: Number.isFinite(Number(proof?.terminalRunSeq))
            ? Number(proof.terminalRunSeq)
            : null,
          inputRevision: Number.isFinite(Number(proof?.inputRevision))
            ? Number(proof.inputRevision)
            : null,
          terminalLifecycleGeneration: proof?.terminalLifecycleGeneration || null,
          mirrorGeneration: proof?.mirrorGeneration || null,
          mirrorWriteSeq: Number.isFinite(Number(proof?.mirrorWriteSeq))
            ? Number(proof.mirrorWriteSeq)
            : null,
        },
        headlessAtIncident: buildHeadlessDraftProofDiagnostic(tabId, proof, reason),
      },
    });
    if (!trace) return null;
    const logsDir = app.getPath('logs');
    await fs.promises.mkdir(logsDir, { recursive: true });
    const safeTab = String(tabId).slice(-24).replace(/[^a-z0-9_-]/gi, '_');
    const artifactPath = path.join(
      logsDir,
      `agent-draft-forensics-${safeTab}-latest.json`,
    );
    const temporaryPath = artifactPath + '.tmp-' + process.pid + '-' + crypto.randomUUID();
    await fs.promises.writeFile(
      temporaryPath,
      JSON.stringify({
        kind: 'agent-draft-composer-forensics',
        tabId,
        agent,
        trace,
      }, null, 2),
      { encoding: 'utf8', mode: 0o600 },
    );
    await fs.promises.rename(temporaryPath, artifactPath);
    console.error('[AgentDraftProof:FORENSIC_ARTIFACT] agent=' + agent
      + ' tab=' + String(tabId).slice(-12)
      + ' transitions=' + trace.transitions.length
      + ' inputs=' + trace.inputs.length
      + ' path=' + JSON.stringify(artifactPath));
    return artifactPath;
  } catch (error) {
    console.error('[AgentDraftProof:FORENSIC_ARTIFACT_FAILED] agent=' + agent
      + ' tab=' + String(tabId).slice(-12)
      + ' error=' + (error?.message || String(error)));
    return null;
  }
}

function sampleTerminalSendForensicText(value, maxChars = 64 * 1024) {
  if (typeof value !== 'string') return null;
  const sample = {
    chars: value.length,
    hash: pasteAuditHash(value),
    truncated: value.length > maxChars,
  };
  if (value.length <= maxChars) return { ...sample, text: value };
  const half = Math.floor(maxChars / 2);
  return {
    ...sample,
    head: value.slice(0, half),
    tail: value.slice(-half),
  };
}

async function removeClaudePostEnterForensicArtifact(audit, artifactPath, reason) {
  if (!artifactPath) return false;
  try {
    const removed = await removeTerminalSendForensicArtifact(artifactPath);
    if (removed) {
      console.log('[ClaudePostEnterForensics] removed-after-proof'
        + ' handoff=' + (audit?.handoffId || '-')
        + ' reason=' + reason
        + ' path=' + JSON.stringify(artifactPath));
    }
    if (audit?.postEnterForensicArtifactPath === artifactPath) {
      audit.postEnterForensicArtifactPath = null;
    }
    return removed;
  } catch (error) {
    console.warn('[ClaudePostEnterForensics] remove-failed'
      + ' handoff=' + (audit?.handoffId || '-')
      + ' reason=' + reason
      + ' path=' + JSON.stringify(artifactPath)
      + ' error=' + (error?.message || String(error)));
    return false;
  }
}

function discardClaudePostEnterForensicArtifact(audit, reason = 'delivery-confirmed') {
  if (!audit) return;
  audit.postEnterForensicDiscardRequested = true;
  if (audit.postEnterForensicArtifactPath) {
    void removeClaudePostEnterForensicArtifact(
      audit,
      audit.postEnterForensicArtifactPath,
      reason,
    );
  }
  if (audit.postEnterForensicArtifactPromise) {
    void audit.postEnterForensicArtifactPromise.then((artifactPath) => (
      removeClaudePostEnterForensicArtifact(audit, artifactPath, reason)
    ));
  }
}

async function persistClaudePostEnterForensicArtifact({
  tabId,
  audit,
  result,
  capture,
  transcriptRead,
}) {
  if (!audit || audit.result?.success === true || audit.postEnterForensicDiscardRequested === true) {
    return null;
  }
  if (audit.postEnterForensicArtifactPromise) {
    return audit.postEnterForensicArtifactPromise;
  }

  audit.postEnterForensicArtifactPromise = (async () => {
    const state = getHeadlessTerminalMirror(tabId);
    if (!state?.composerForensics) return null;
    const capturedAt = Date.now();
    const incident = {
      error: result?.error || null,
      code: result?.code || null,
      semanticStatus: result?.semanticStatus || null,
      final: result?.final === true,
      composerDraftState: result?.composerDraftState || null,
      expectedLen: audit.expectedLen ?? null,
      expectedHash: audit.expectedHash || null,
      expectedImagePathCount: result?.expectedImagePathCount ?? null,
      capturedImageCount: result?.capturedImageCount ?? null,
      capture: {
        success: capture?.success === true,
        proofOutcome: capture?.proofOutcome || null,
        terminalIdentityStable: capture?.terminalIdentityStable === true,
        editorReturnReady: capture?.editorReturnReady === true,
        images: Number(capture?.images || 0),
        error: capture?.error || null,
        text: sampleTerminalSendForensicText(capture?.text),
      },
      transcript: {
        success: transcriptRead?.success === true,
        userRecordCount: Number(transcriptRead?.userRecordCount || 0),
        transcriptPath: transcriptRead?.transcriptPath || null,
        error: transcriptRead?.error || null,
      },
      headlessAtIncident: buildHeadlessDraftProofDiagnostic(
        tabId,
        capture,
        'claude-post-enter-unconfirmed',
      ),
    };
    const trace = snapshotTerminalComposerForensicWindow(state.composerForensics, {
      capturedAt,
      inputId: audit.forensicEnterInputId,
      handoffId: audit.handoffId,
      sendAttemptId: audit.sendAttemptId,
      sendOperationKey: audit.sendOperationKey,
      incident,
    });
    if (!trace) return null;
    try {
      const artifactPath = await persistTerminalSendForensicArtifact({
        logsDir: app.getPath('logs'),
        tabId,
        provider: 'claude',
        attempt: {
          enterInputId: audit.forensicEnterInputId,
          handoffId: audit.handoffId,
          sendAttemptId: audit.sendAttemptId,
          sendOperationKey: audit.sendOperationKey,
          sentAt: audit.sentAt,
        },
        incident,
        trace,
        capturedAt,
      });
      audit.postEnterForensicArtifactPath = artifactPath;
      if (audit.postEnterForensicDiscardRequested === true || audit.result?.success === true) {
        await removeClaudePostEnterForensicArtifact(
          audit,
          artifactPath,
          'late-delivery-confirmed',
        );
        return null;
      }
      console.error('[ClaudePostEnterForensics] saved'
        + ' tab=' + String(tabId).slice(-12)
        + ' handoff=' + (audit.handoffId || '-')
        + ' enterInput=' + (audit.forensicEnterInputId ?? '-')
        + ' transitions=' + trace.transitions.length
        + ' inputs=' + trace.inputs.length
        + ' path=' + JSON.stringify(artifactPath));
      return artifactPath;
    } catch (error) {
      console.error('[ClaudePostEnterForensics] save-failed'
        + ' tab=' + String(tabId).slice(-12)
        + ' handoff=' + (audit.handoffId || '-')
        + ' error=' + (error?.message || String(error)));
      return null;
    }
  })().catch((error) => {
    console.error('[ClaudePostEnterForensics] snapshot-failed'
      + ' tab=' + String(tabId).slice(-12)
      + ' handoff=' + (audit.handoffId || '-')
      + ' error=' + (error?.message || String(error)));
    return null;
  });

  return audit.postEnterForensicArtifactPromise;
}

ipcMain.on('terminal:draft-screen-diagnostic-response', (event, payload = {}) => {
  const requestId = String(payload?.requestId || '');
  const pending = pendingAgentDraftScreenDiagnostics.get(requestId);
  if (!pending || payload?.tabId !== pending.tabId) return;
  const rendererDiagnostic = payload?.snapshot || null;
  const headlessDiagnostic = buildHeadlessDraftProofDiagnostic(
    pending.tabId,
    pending.proof,
    'renderer-' + String(payload?.phase || 'unknown'),
  );
  const parity = compareAgentDraftScreenParity(headlessDiagnostic, rendererDiagnostic);
  console.error('[AgentDraftProof:SCREEN_FOLLOWUP] agent=' + pending.agent
    + ' tab=' + String(pending.tabId).slice(-12)
    + ' request=' + requestId
    + ' phase=' + (payload?.phase || 'unknown')
    + ' settled=' + (payload?.settled === true)
    + ' timedOut=' + (payload?.timedOut === true)
    + ' parity=' + JSON.stringify(parity)
    + ' renderer=' + JSON.stringify(rendererDiagnostic)
    + ' headless=' + JSON.stringify(headlessDiagnostic));

  if (payload?.phase === 'painted-settled') {
    if (parity.comparable !== true && pending.retryCount < 2) {
      pending.retryCount += 1;
      setTimeout(() => {
        if (!pendingAgentDraftScreenDiagnostics.has(requestId) || event.sender.isDestroyed()) return;
        event.sender.send('terminal:draft-screen-diagnostic-request', {
          requestId,
          tabId: pending.tabId,
          reason: pending.reason + ':retry-' + pending.retryCount,
          promptRow: Number.isFinite(Number(pending.proof?.promptRow))
            ? Number(pending.proof.promptRow)
            : null,
          cursorRow: Number.isFinite(Number(pending.proof?.cursorRow))
            ? Number(pending.proof.cursorRow)
            : null,
        });
      }, 180);
      return;
    }
    void captureAgentDraftScreenArtifact(event.sender, pending, rendererDiagnostic);
    finishAgentDraftScreenDiagnostic(requestId);
  } else if (payload?.phase === 'painted-timeout') {
    finishAgentDraftScreenDiagnostic(requestId);
  }
});

function createHeadlessTerminalMirror(tabId, cols = 80, rows = 24, options = {}) {
  if (!tabId || !HeadlessXTerminal) return null;
  const existing = terminalHeadlessMirrors.get(tabId);
  if (existing && !existing.failed) return existing;
  try {
    const safeCols = Math.max(2, Number(cols) || 80);
    const safeRows = Math.max(2, Number(rows) || 24);
    const terminal = new HeadlessXTerminal({
      cols: safeCols,
      rows: safeRows,
      scrollback: HEADLESS_XTERM_SCROLLBACK,
      allowProposedApi: true,
    });
    const serializeAddon = HeadlessSerializeAddon ? new HeadlessSerializeAddon() : null;
    if (serializeAddon) terminal.loadAddon(serializeAddon);
    const promptBoundaryMarkers = new Map();
    terminal.parser.registerOscHandler(7777, (payload) => {
      const match = /^prompt:(\d+)$/.exec(String(payload || ''));
      if (!match) return true;
      const seq = Number(match[1]);
      if (!Number.isFinite(seq) || promptBoundaryMarkers.has(seq)) return true;
      const marker = terminal.registerMarker(0);
      if (!marker) return true;
      promptBoundaryMarkers.set(seq, marker);
      marker.onDispose(() => {
        if (promptBoundaryMarkers.get(seq) === marker) {
          promptBoundaryMarkers.delete(seq);
        }
      });
      return true;
    });
    const state = {
      terminal,
      serializeAddon,
      promptBoundaryMarkers,
      generation: crypto.randomUUID(),
      generationOrdinal: ++terminalHeadlessGenerationCounter,
      writePump: null,
      writeSeq: 0,
      flushedSeq: 0,
      failed: false,
      disposed: false,
      complete: options.complete !== false,
      incompleteReason: options.complete === false
        ? String(options.incompleteReason || 'unknown-history')
        : null,
      redrawTrace: createTerminalRedrawTrace(),
      composerForensics: createTerminalComposerForensics(),
      replayJournal: createTerminalReplayJournal(),
      lastCommittedVisibleSnapshot: null,
      committedFrameGeneration: 0,
      pendingResizeWriteSeq: null,
      synchronizedFrameWaiters: new Set(),
      lastErrorAt: 0,
      cols: safeCols,
      rows: safeRows,
    };
    state.writePump = createXtermWritePump(
      (data, done) => state.terminal.write(data, done),
      {
        onFlushed: (meta, flushInfo) => {
          const seq = Number(meta?.seq);
          if (Number.isFinite(seq)) {
            state.flushedSeq = Math.max(state.flushedSeq || 0, seq);
          }
          recordTerminalFlush(state.redrawTrace, {
            seq: Number.isFinite(seq) ? seq : null,
            chars: flushInfo?.chars,
            items: flushInfo?.items,
            after: readHeadlessCursorMetrics(state),
          });
          const committedSnapshot = commitHeadlessVisibleBufferSnapshot(tabId, state, seq);
          if (committedSnapshot) {
            terminalHistoryPreviewController.observeFrame(tabId, state, committedSnapshot);
          }
          if (committedSnapshot) {
            try {
              state.replayJournal.checkpoint(() => state.serializeAddon ? {
                generation: state.generation, writeSeq: state.flushedSeq,
                rows: state.rows, cols: state.cols,
                screen: state.serializeAddon.serialize({ scrollback: 0 }), capturedAt: Date.now(),
              } : null);
            } catch (error) { logHeadlessTerminalMirrorError(tabId, state, 'diagnostic checkpoint failed', error); }
          }
          observeCodexLateMcpProofAfterHeadlessFlush(
            tabId,
            state,
            seq,
            committedSnapshot,
          );
          for (const notify of Array.from(state.synchronizedFrameWaiters)) {
            try { notify(); } catch {}
          }
          if (meta?.synchronizedFrameEnd === true) {
            observeClaudeSynchronizedFrameFlushed(tabId, state, seq);
          }
        },
        onError: (error) => {
          state.failed = true;
          for (const notify of Array.from(state.synchronizedFrameWaiters)) {
            try { notify(); } catch {}
          }
          logHeadlessTerminalMirrorError(tabId, state, 'write failed', error);
        },
      },
    );
    terminalHeadlessMirrors.set(tabId, state);
    console.log('[HeadlessXterm] create tab=' + String(tabId).slice(-12)
      + ' generation=' + state.generation.slice(0, 8)
      + '/' + state.generationOrdinal
      + ' cols=' + safeCols
      + ' rows=' + safeRows
      + ' complete=' + state.complete
      + (state.incompleteReason ? ' incompleteReason=' + state.incompleteReason : ''));
    return state;
  } catch (err) {
    console.warn('[HeadlessXterm] create failed tab=' + String(tabId).slice(-12) + ' ' + (err?.message || String(err)));
    terminalHeadlessMirrors.delete(tabId);
    return null;
  }
}

function waitForHeadlessSynchronizedOutputClose(
  tabId,
  expectedState,
  timeoutMs,
  { afterWriteSeq = null } = {},
) {
  const state = expectedState || getHeadlessTerminalMirror(tabId);
  if (!state) return Promise.resolve({ ready: false, reason: 'no-headless-mirror' });
  const isReady = () => (
    getHeadlessTerminalMirror(tabId) === state
    && state.failed !== true
    && (
      afterWriteSeq === null
      || Number(state.writeSeq || 0) > Number(afterWriteSeq)
    )
    && state.redrawTrace?.synchronizedOutputOpen !== true
    && Number(state.flushedSeq || 0) === Number(state.writeSeq || 0)
  );
  if (isReady()) {
    return Promise.resolve({
      ready: true,
      reason: 'synchronized-frame-closed',
      writeSeq: state.writeSeq,
    });
  }

  return new Promise((resolve) => {
    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      state.synchronizedFrameWaiters?.delete(check);
      resolve(result);
    };
    const check = () => {
      if (getHeadlessTerminalMirror(tabId) !== state) {
        finish({ ready: false, reason: 'headless-generation-changed' });
        return;
      }
      if (state.failed === true) {
        finish({ ready: false, reason: 'headless-mirror-failed' });
        return;
      }
      if (isReady()) {
        finish({
          ready: true,
          reason: 'synchronized-frame-closed',
          writeSeq: state.writeSeq,
        });
      }
    };
    // The timeout only terminates an unresolved wait. It can never authorize
    // input; readiness comes exclusively from a parsed+flushed PTY frame.
    const timer = setTimeout(() => finish({
      ready: false,
      reason: afterWriteSeq !== null
        && Number(state.writeSeq || 0) <= Number(afterWriteSeq)
        ? 'synchronized-frame-not-applied'
        : state.redrawTrace?.synchronizedOutputOpen === true
        ? 'synchronized-frame-still-open'
        : 'synchronized-frame-not-flushed',
    }), Math.max(50, Number(timeoutMs) || 700));
    state.synchronizedFrameWaiters.add(check);
    check();
  });
}

async function waitForAgentEditorReturnReady(tabId, agent, captureIdentity, edgePromise) {
  const edge = await edgePromise;
  if (edge?.ready !== true || agent !== 'claude') return edge;

  // Claude's DEC 2026 end marker is emitted on the raw PTY stream before the
  // headless xterm write pump necessarily applies that same chunk. The raw
  // edge proves that Claude returned from the external editor; it does not by
  // itself prove that consumers can already inspect the completed frame.
  const flushedFrame = await waitForHeadlessSynchronizedOutputClose(
    tabId,
    captureIdentity?.mirrorToken || null,
    700,
    { afterWriteSeq: captureIdentity?.mirrorWriteSeq ?? null },
  );
  if (flushedFrame?.ready !== true) {
    return {
      ...flushedFrame,
      edgeReady: true,
      edgeReason: edge.reason || null,
    };
  }
  return {
    ...edge,
    ...flushedFrame,
    ready: true,
    reason: 'synchronized-frame-flushed',
    edgeReason: edge.reason || null,
  };
}

function getHeadlessTerminalMirror(tabId) {
  const state = terminalHeadlessMirrors.get(tabId);
  if (!state || state.failed) return null;
  return state;
}

function logHeadlessTerminalMirrorError(tabId, state, reason, err) {
  const now = Date.now();
  if (state && now - (state.lastErrorAt || 0) < 5000) return;
  if (state) state.lastErrorAt = now;
  console.warn('[HeadlessXterm] ' + reason + ' tab=' + String(tabId).slice(-12) + ' ' + (err?.message || String(err)));
}

function writeHeadlessTerminalMirror(tabId, data, { onReserved = null } = {}) {
  if (!data) return null;
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) return null;
  const seq = ++state.writeSeq;
  try {
    state.replayJournal?.output(data, seq);
    try {
      recordTerminalComposerOutput(state.composerForensics, data, { seq });
    } catch (error) {
      logTerminalComposerForensicError(tabId, state, 'pty-output', error);
    }
    const redrawEntry = recordTerminalOutput(state.redrawTrace, data, { seq });
    const redrawKinds = new Set(
      (redrawEntry?.controls || []).map((control) => control.kind),
    );
    const synchronizedFrameBegin = redrawKinds.has('synchronized-output-begin');
    const synchronizedFrameEnd = redrawKinds.has('synchronized-output-end');
    if (synchronizedFrameBegin) {
      const generation = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
      if (generation) {
        claudePromptStability.markActivity(
          tabId,
          generation,
          'synchronized-frame-begin:' + seq,
        );
      }
    }
    if (typeof onReserved === 'function') {
      try {
        onReserved({
          writeSeq: seq,
          generation: state.generation,
          generationOrdinal: state.generationOrdinal,
          mirrorState: state,
        });
      } catch (error) {
        console.warn('[HeadlessXterm] write reservation observer failed tab='
          + String(tabId).slice(-12)
          + ' seq=' + seq
          + ' error=' + (error?.message || String(error)));
      }
    }
    state.writePump.push(String(data), {
      seq,
      generation: state.generation,
      generationOrdinal: state.generationOrdinal,
      synchronizedFrameEnd,
    });
  } catch (err) {
    state.failed = true;
    logHeadlessTerminalMirrorError(tabId, state, 'write setup failed', err);
  }
  return {
    writeSeq: seq,
    generation: state.generation,
    generationOrdinal: state.generationOrdinal,
  };
}

function fanoutTerminalPresentationData(tabId, ptyProcess, data, {
  observeCodexImages = true,
  onHeadlessWriteReserved = null,
} = {}) {
  const headlessWrite = writeHeadlessTerminalMirror(tabId, data, {
    onReserved: onHeadlessWriteReserved,
  });
  if (observeCodexImages) {
    const boundCodexImages = codexImageBindings.observe(tabId, data);
    if (boundCodexImages.length > 0) {
      console.log('[CodexImageBinding] tab=' + String(tabId).slice(-12)
        + ' bound=' + boundCodexImages.map((ref) => '#'
          + ref.id + ':' + String(ref.assetId || path.basename(ref.path || '')).slice(0, 12)).join(',')
        + ' ' + codexImageBindings.describe(tabId));
    }
  }
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:data', {
      pid: ptyProcess?.pid ?? null,
      tabId,
      data,
      headlessWriteSeq: headlessWrite?.writeSeq ?? null,
      headlessGeneration: headlessWrite?.generation ?? null,
      headlessGenerationOrdinal: headlessWrite?.generationOrdinal ?? null,
    });
  }
  return headlessWrite;
}

async function injectClaudeEmptyFrameForTest(request = {}, frameKind = 'residual') {
  if (!aiBoundaryTestGate.enabled) {
    return { success: false, error: 'test_hook_disabled' };
  }
  const tabId = String(request?.tabId || '').trim();
  const generation = String(request?.generation || request?.launchGeneration || '').trim();
  if (!tabId || !generation) {
    return { success: false, error: 'tabId and generation required' };
  }
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const term = terminals.get(tabId) || null;
  const mirror = getHeadlessTerminalMirror(tabId);
  if (!term || !mirror || launch?.generation !== generation) {
    return { success: false, error: 'terminal_or_generation_changed' };
  }
  const flushed = await flushHeadlessTerminalMirror(tabId);
  if (!flushed.success
    || getHeadlessTerminalMirror(tabId) !== mirror
    || mirror.complete !== true
    || mirror.redrawTrace?.synchronizedOutputOpen === true) {
    return { success: false, error: flushed.error || 'headless_frame_not_closed' };
  }
  const beforeSnapshot = getHeadlessVisibleBufferSnapshot(
    tabId,
    'e2e-residual-empty-before',
  );
  const beforeProof = parseClaudeComposerCurrentFrame(beforeSnapshot);
  if (beforeProof?.proofOutcome !== 'absent' || beforeProof?.hasDraft !== false) {
    return {
      success: false,
      error: 'composer_not_proven_empty',
      proofOutcome: beforeProof?.proofOutcome || 'unknown',
      proofReason: beforeProof?.proofReason || null,
    };
  }
  const identity = {
    tabId,
    generation,
    terminalRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    inputRevision: getTerminalInputRevision(tabId),
    lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    mirrorGeneration: mirror.generation,
    writeSeq: mirror.writeSeq,
  };
  const missingPrompt = frameKind === 'missing-prompt';
  const claimed = aiBoundaryTestGate.claim({
    kind: missingPrompt
      ? 'claude-missing-prompt-empty-frame'
      : 'claude-residual-empty-frame',
    identity,
  });
  if (claimed.claimed !== true || claimed.action !== 'inject') {
    return {
      success: false,
      error: claimed.reason || 'residual_frame_hook_not_armed',
    };
  }
  const marker = missingPrompt
    ? null
    : String(
      claimed.payload?.marker || ('E2E_RESIDUAL_' + claimed.arm.armId),
    ).replace(/[^A-Za-z0-9_.:-]/g, '_').slice(0, 96);
  const ansi = missingPrompt
    ? buildMissingPromptEmptyFrameAnsi(beforeSnapshot.cursorX)
    : buildResidualEmptyFrameAnsi(marker);
  const beforeWriteSeq = mirror.writeSeq;
  const published = fanoutTerminalPresentationData(tabId, term, ansi, {
    observeCodexImages: false,
  });
  const afterFlush = await flushHeadlessTerminalMirror(tabId);
  const afterSnapshot = afterFlush.success
    ? getHeadlessVisibleBufferSnapshot(tabId, 'e2e-residual-empty-after')
    : null;
  const afterProof = afterSnapshot?.success
    ? parseClaudeComposerCurrentFrame(afterSnapshot)
    : null;
  const expectedProofObserved = missingPrompt
    ? afterProof?.proofReason === 'active-prompt-not-found'
    : afterProof?.exactCaptureRecommended === true;
  const injected = afterFlush.success
    && getHeadlessTerminalMirror(tabId) === mirror
    && terminals.get(tabId) === term
    && mirror.generation === identity.mirrorGeneration
    && afterProof?.proofOutcome === 'unknown'
    && expectedProofObserved;
  aiBoundaryTestGate.complete({
    armId: claimed.arm.armId,
    operationId: claimed.arm.operationId,
    reason: injected
      ? (missingPrompt ? 'missing-prompt-frame-injected' : 'residual-frame-injected')
      : (missingPrompt ? 'missing-prompt-frame-not-observed' : 'residual-frame-not-observed'),
    result: {
      success: injected,
      beforeWriteSeq,
      afterWriteSeq: published?.writeSeq ?? mirror.writeSeq,
    },
  });
  console.warn('[TestFault] inject kind=' + (missingPrompt
    ? 'missing-prompt-empty-frame'
    : 'residual-empty-frame')
    + ' tab=' + tabId.slice(-12)
    + ' gen=' + generation
    + ' operation=' + claimed.arm.operationId
    + ' run=' + identity.terminalRunSeq
    + ' inputRevision=' + identity.inputRevision
    + ' lifecycle=' + identity.lifecycleGeneration
    + ' mirror=' + String(identity.mirrorGeneration).slice(0, 8)
    + ' write=' + beforeWriteSeq + '/' + (published?.writeSeq ?? mirror.writeSeq)
    + ' observed=' + injected);
  return {
    success: injected,
    error: injected ? null : (afterFlush.error || (missingPrompt
      ? 'missing_prompt_frame_not_observed'
      : 'residual_frame_not_observed')),
    armId: claimed.arm.armId,
    operationId: claimed.arm.operationId,
    marker,
    beforeWriteSeq,
    afterWriteSeq: published?.writeSeq ?? mirror.writeSeq,
    proofOutcome: afterProof?.proofOutcome || null,
    proofReason: afterProof?.proofReason || null,
  };
}

async function injectResidualEmptyClaudeFrameForTest(request = {}) {
  return injectClaudeEmptyFrameForTest(request, 'residual');
}

async function injectMissingPromptEmptyClaudeFrameForTest(request = {}) {
  return injectClaudeEmptyFrameForTest(request, 'missing-prompt');
}

async function flushHeadlessTerminalMirror(tabId, timeoutMs = HEADLESS_XTERM_FLUSH_TIMEOUT_MS) {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) return { success: false, error: 'no-headless-mirror' };
  const deadline = Date.now() + Math.max(1, Number(timeoutMs) || HEADLESS_XTERM_FLUSH_TIMEOUT_MS);

  // A PTY chunk can arrive while an earlier write callback is pending. Keep
  // following the latest sequence until the mirror is fully caught up, then
  // synchronously serialize it before another onData callback can interleave.
  while (state.flushedSeq < state.writeSeq) {
    if (terminalHeadlessMirrors.get(tabId) !== state || state.disposed) {
      return {
        success: false,
        error: 'headless-mirror-generation-changed',
        writeSeq: state.writeSeq,
        flushedSeq: state.flushedSeq,
      };
    }
    const remainingMs = deadline - Date.now();
    if (remainingMs <= 0) {
      return {
        success: false,
        error: 'headless-flush-timeout',
        writeSeq: state.writeSeq,
        flushedSeq: state.flushedSeq,
      };
    }
    const pending = state.writePump?.drain?.() || Promise.resolve();
    let timedOut = false;
    let timeoutHandle = null;
    await Promise.race([
      pending.catch((err) => {
        state.failed = true;
        logHeadlessTerminalMirrorError(tabId, state, 'flush failed', err);
      }),
      new Promise((resolve) => {
        timeoutHandle = setTimeout(() => {
          timedOut = true;
          resolve();
        }, remainingMs);
      }),
    ]);
    if (timeoutHandle) clearTimeout(timeoutHandle);
    if (terminalHeadlessMirrors.get(tabId) !== state || state.disposed) {
      return {
        success: false,
        error: 'headless-mirror-generation-changed',
        writeSeq: state.writeSeq,
        flushedSeq: state.flushedSeq,
      };
    }
    if (timedOut) {
      return {
        success: false,
        error: 'headless-flush-timeout',
        writeSeq: state.writeSeq,
        flushedSeq: state.flushedSeq,
      };
    }
    if (state.failed) {
      return {
        success: false,
        error: 'headless-flush-failed',
        writeSeq: state.writeSeq,
        flushedSeq: state.flushedSeq,
      };
    }
  }
  return { success: true, writeSeq: state.writeSeq, flushedSeq: state.flushedSeq };
}

async function getHeadlessSerializedTerminalSnapshot(tabId, reason = 'renderer-hydration') {
  const startedAt = nodePerformance.now();
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) {
    return { success: false, error: 'no-headless-mirror', tabId, reason };
  }
  if (!state.serializeAddon) {
    return { success: false, error: 'serialize-addon-unavailable', tabId, reason };
  }
  if (state.complete !== true) {
    return {
      success: false,
      error: 'headless-mirror-incomplete',
      incompleteReason: state.incompleteReason || 'unknown-history',
      tabId,
      reason,
    };
  }
  const flush = await flushHeadlessTerminalMirror(tabId);
  if (!flush.success) {
    return { ...flush, success: false, tabId, reason };
  }
  if (terminalHeadlessMirrors.get(tabId) !== state || state.failed) {
    return {
      success: false,
      error: 'headless-mirror-generation-changed',
      tabId,
      reason,
    };
  }
  try {
    const serializeStartedAt = nodePerformance.now();
    const serialized = state.serializeAddon.serialize();
    const serializeMs = nodePerformance.now() - serializeStartedAt;
    const totalMs = nodePerformance.now() - startedAt;
    const bufferRows = Number(state.terminal?.buffer?.active?.length || 0);
    console.log('[HeadlessXterm:SNAPSHOT] tab=' + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' generation=' + String(state.generation || '').slice(0, 8)
      + '/' + state.generationOrdinal
      + ' seq=' + state.writeSeq
      + ' chars=' + serialized.length
      + ' bufferRows=' + bufferRows
      + ' serializeMs=' + serializeMs.toFixed(1)
      + ' totalMs=' + totalMs.toFixed(1));
    return {
      success: true,
      tabId,
      reason,
      serialized,
      writeSeq: state.writeSeq,
      flushedSeq: state.flushedSeq,
      generation: state.generation,
      generationOrdinal: state.generationOrdinal,
      cols: state.cols,
      rows: state.rows,
      bufferRows,
      serializeMs,
      totalMs,
      promptBoundaries: Array.from(state.promptBoundaryMarkers || [])
        .filter(([, marker]) => marker && !marker.isDisposed && marker.line >= 0)
        .map(([seq, marker]) => ({ seq, line: marker.line })),
    };
  } catch (err) {
    logHeadlessTerminalMirrorError(tabId, state, 'serialize failed', err);
    return {
      success: false,
      error: err?.message || String(err),
      tabId,
      reason,
      writeSeq: state.writeSeq,
      flushedSeq: state.flushedSeq,
    };
  }
}

function resizeHeadlessTerminalMirror(tabId, cols, rows) {
  const state = getHeadlessTerminalMirror(tabId) || createHeadlessTerminalMirror(
    tabId,
    cols,
    rows,
    {
      complete: false,
      incompleteReason: 'mirror-created-after-pty-start',
    },
  );
  if (!state) return;
  const safeCols = Math.max(2, Number(cols) || state.cols || 80);
  const safeRows = Math.max(2, Number(rows) || state.rows || 24);
  if (state.cols === safeCols && state.rows === safeRows) return;
  try {
    // Geometry is part of a frame proof. Never replay a snapshot captured for
    // the previous grid after xterm has reflowed its buffer.
    state.lastCommittedVisibleSnapshot = null;
    state.pendingResizeWriteSeq = Number(state.writeSeq || 0);
    state.replayJournal?.resize(safeCols, safeRows, state.writeSeq !== state.flushedSeq);
    state.terminal.resize(safeCols, safeRows);
    state.cols = safeCols;
    state.rows = safeRows;
    recordTerminalResize(state.redrawTrace, safeCols, safeRows);
  } catch (err) {
    state.failed = true;
    logHeadlessTerminalMirrorError(tabId, state, 'resize failed', err);
  }
}

function disposeHeadlessTerminalMirror(tabId, reason = 'dispose') {
  const state = terminalHeadlessMirrors.get(tabId);
  terminalInputRevisions.delete(tabId);
  codexManualQueueInterrupts.delete(tabId);
  terminalHistoryPreviewController.clear(tabId, 'headless-' + reason);
  if (!state) return;
  terminalHeadlessMirrors.delete(tabId);
  state.disposed = true;
  try { state.writePump?.dispose?.(); } catch {}
  try { state.terminal.dispose?.(); } catch {}
  console.log('[HeadlessXterm] dispose tab=' + String(tabId).slice(-12) + ' reason=' + reason);
}

function getTerminalInputRevision(tabId) {
  return Number(terminalInputRevisions.get(tabId) || 0);
}

function bumpTerminalInputRevision(tabId) {
  const next = getTerminalInputRevision(tabId) + 1;
  terminalInputRevisions.set(tabId, next);
  return next;
}

function describeXtermCellStyle(cell) {
  if (!cell) return 'empty';
  const read = (name) => {
    const value = cell?.[name];
    return typeof value === 'function' ? value.call(cell) : value;
  };
  const parts = [];
  const fgMode = read('getFgColorMode');
  const fgColor = read('getFgColor');
  const bgMode = read('getBgColorMode');
  const bgColor = read('getBgColor');
  parts.push('fg=' + (fgMode ?? '-') + ':' + (fgColor ?? '-'));
  parts.push('bg=' + (bgMode ?? '-') + ':' + (bgColor ?? '-'));
  if (read('isInverse')) parts.push('inverse');
  if (read('isBold')) parts.push('bold');
  if (read('isDim')) parts.push('dim');
  if (read('isItalic')) parts.push('italic');
  if (read('isUnderline')) parts.push('underline');
  if (read('isBlink')) parts.push('blink');
  if (read('isInvisible')) parts.push('invisible');
  return parts.join(',');
}

function xtermStyleHasNonDefaultBg(style) {
  const match = /bg=([^,\s]+)/.exec(String(style || ''));
  if (!match) return false;
  const bg = match[1];
  return bg !== '0:-1' && bg !== '-:-' && bg !== '-:-1' && bg !== 'none';
}

function xtermStyleHasNonDefaultFg(style) {
  const match = /fg=([^,\s]+)/.exec(String(style || ''));
  if (!match) return false;
  const fg = match[1];
  return fg !== '0:-1' && fg !== '-:-' && fg !== '-:-1' && fg !== 'none';
}

function summarizeXtermLineStyles(line) {
  if (!line) return {
    styles: [],
    firstTextStyle: 'none',
    hasInverse: false,
    hasNonDefaultBg: false,
    hasNonDefaultFg: false,
    hasDim: false,
    allTextDim: false,
    textCellCount: 0,
  };
  const counts = new Map();
  let firstTextStyle = 'none';
  let hasInverse = false;
  let hasNonDefaultBg = false;
  let hasNonDefaultFg = false;
  let dimTextCells = 0;
  let textCellCount = 0;
  for (let x = 0; x < line.length; x++) {
    const cell = line.getCell(x);
    if (!cell || cell.getWidth?.() === 0) continue;
    const ch = cell.getChars?.() || ' ';
    if (!String(ch).trim()) continue;
    textCellCount += 1;
    const style = describeXtermCellStyle(cell);
    if (firstTextStyle === 'none') firstTextStyle = style;
    if (style.includes('inverse')) hasInverse = true;
    if (style.includes('dim')) dimTextCells += 1;
    if (xtermStyleHasNonDefaultBg(style)) hasNonDefaultBg = true;
    if (xtermStyleHasNonDefaultFg(style)) hasNonDefaultFg = true;
    counts.set(style, (counts.get(style) || 0) + 1);
  }
  const styles = Array.from(counts.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([style, count]) => style + ' x' + count);
  return {
    styles,
    firstTextStyle,
    hasInverse,
    hasNonDefaultBg,
    hasNonDefaultFg,
    hasDim: dimTextCells > 0,
    allTextDim: textCellCount > 0 && dimTextCells === textCellCount,
    textCellCount,
  };
}

function summarizeXtermLineGeometry(line) {
  if (!line) return { occupiedEndX: 0, promptCellX: null };
  let occupiedEndX = 0;
  let promptCellX = null;
  for (let x = 0; x < line.length; x += 1) {
    const cell = line.getCell(x);
    if (!cell || cell.getWidth?.() === 0) continue;
    const chars = String(cell.getChars?.() || '');
    if (chars.includes('❯') || chars.includes('›')) promptCellX = x;
    // Cursor blocks are presentation, not composer text. Spaces intentionally
    // do not extend the occupied tail: a user may type trailing spaces and the
    // cursor remains the stronger boundary witness.
    if (chars.replace(/[▌█]/g, '').trim()) {
      occupiedEndX = x + Math.max(1, Number(cell.getWidth?.()) || 1);
    }
  }
  return { occupiedEndX, promptCellX };
}

function getLogicalLineSnapshotAt(buf, row) {
  if (!buf || row < 0 || row >= buf.length) return { text: '', cells: [] };
  let start = row;
  let line = buf.getLine(start);
  while (line?.isWrapped && start > 0) {
    start -= 1;
    line = buf.getLine(start);
  }

  const cells = [];
  let physicalRowCount = 0;
  for (let i = start; i < buf.length; i++) {
    const current = buf.getLine(i);
    if (!current) break;
    physicalRowCount += 1;

    for (let x = 0; x < current.length; x++) {
      const cell = current.getCell(x);
      if (!cell || cell.getWidth?.() === 0) continue;
      const ch = cell.getChars?.() || ' ';
      cells.push({
        ch: ch || ' ',
        dim: !!cell.isDim?.(),
        inverse: !!cell.isInverse?.(),
        nonDefaultBg: xtermStyleHasNonDefaultBg(describeXtermCellStyle(cell)),
      });
    }
    const next = buf.getLine(i + 1);
    if (!next?.isWrapped) break;
  }

  while (cells.length > 0 && !String(cells[cells.length - 1].ch || '').trim()) cells.pop();
  return {
    text: cells.map((cell) => cell.ch).join(''),
    cells,
    wrapped: physicalRowCount > 1,
  };
}

function extractCodexDraftFromLine(snapshotOrLine) {
  const snapshot = typeof snapshotOrLine === 'string'
    ? { text: snapshotOrLine, cells: [] }
    : (snapshotOrLine || { text: '', cells: [] });
  const normalized = String(snapshot.text || '')
    .replace(/\u00a0/g, ' ')
    .trimEnd();
  const normalizedClean = normalized.replace(/[▌█]/g, '');
  if (!normalizedClean.trim()) return { hasDraft: false, preview: '' };

  const promptIdx = findLastCodexComposerPromptIndex(normalized);
  if (promptIdx >= 0) {
    const afterPrompt = normalized.slice(promptIdx + 1).replace(/[▌█]/g, '').trim();
    if (!afterPrompt) return { hasDraft: false, preview: '' };
    const afterPromptCells = (snapshot.cells || [])
      .slice(promptIdx + 1)
      .filter((cell) => String(cell.ch || '').trim() && cell.ch !== '▌' && cell.ch !== '█');
    if (afterPromptCells.length > 0 && afterPromptCells.every((cell) => cell.dim)) {
      return { hasDraft: false, preview: afterPrompt.slice(0, 120), sourceSuffix: ':dim-hint' };
    }
    if (CODEX_EMPTY_COMPOSER_HINT_RE.test(afterPrompt)) {
      return { hasDraft: false, preview: afterPrompt.slice(0, 120), sourceSuffix: ':idle-hint' };
    }
    if (CODEX_NON_DRAFT_LINE_RE.test(afterPrompt)) return { hasDraft: null, preview: afterPrompt.slice(0, 120) };
    return { hasDraft: true, text: afterPrompt, preview: afterPrompt.slice(0, 120) };
  }

  const nonBlankCells = (snapshot.cells || [])
    .filter((cell) => String(cell.ch || '').trim() && cell.ch !== '▌' && cell.ch !== '█');
  if (nonBlankCells.length > 0 && nonBlankCells.every((cell) => cell.dim)) {
    return { hasDraft: false, preview: normalizedClean.trim().slice(0, 120), sourceSuffix: ':dim-hint' };
  }
  if (CODEX_EMPTY_COMPOSER_HINT_RE.test(normalizedClean.trim())) {
    return { hasDraft: false, preview: normalizedClean.trim().slice(0, 120), sourceSuffix: ':idle-hint' };
  }
  if (CODEX_NON_DRAFT_LINE_RE.test(normalizedClean.trim())) {
    return { hasDraft: null, preview: normalizedClean.trim().slice(0, 120) };
  }

  return { hasDraft: null, preview: normalizedClean.trim().slice(0, 120) };
}

function extractCodexDraftAfterEmptyPrompt(buf, promptRow) {
  if (!buf || promptRow < 0 || promptRow >= buf.length) return null;
  const end = Math.min(buf.length, promptRow + 18);
  for (let row = promptRow + 1; row < end; row++) {
    const line = buf.getLine(row);
    if (!line) break;

    const snapshot = getLogicalLineSnapshotAt(buf, row);
    const raw = String(line.translateToString?.(true) || '');
    const normalized = (String(snapshot.text || '') || raw)
      .replace(/\u00a0/g, ' ')
      .replace(/[▌█]/g, '')
      .trimEnd();
    const rawNormalized = raw
      .replace(/\u00a0/g, ' ')
      .replace(/[▌█]/g, '')
      .trimEnd();
    const withoutBorder = normalized.replace(/^\s*[│┃║]\s?/, '');
    const rawWithoutBorder = rawNormalized.replace(/^\s*[│┃║]\s?/, '');
    const candidate = withoutBorder.trim();
    const rawCandidate = rawWithoutBorder.trim();
    const effectiveCandidate = candidate || rawCandidate;
    if (!effectiveCandidate) continue;
    if (/^[╭╰]/.test(effectiveCandidate)) return null;

    const candidateCells = (snapshot.cells || [])
      .filter((cell) => String(cell.ch || '').trim() && cell.ch !== '▌' && cell.ch !== '█' && !/[│┃║]/.test(cell.ch));
    if (candidateCells.length > 0 && candidateCells.every((cell) => cell.dim)) return null;
    if (CODEX_EMPTY_COMPOSER_HINT_RE.test(effectiveCandidate)) return null;
    if (CODEX_NON_DRAFT_LINE_RE.test(effectiveCandidate)) return null;

    return {
      hasDraft: true,
      text: effectiveCandidate,
      preview: effectiveCandidate.slice(0, 120),
      sourceSuffix: ':multiline-draft-row-' + row,
    };
  }
  return null;
}

function describeCodexDraftProbeRow(buf, row) {
  if (!buf || row < 0 || row >= buf.length) return 'row=' + row + ':out-of-range';
  const raw = String(buf.getLine(row)?.translateToString?.(true) || '').replace(/\s+/g, ' ').slice(0, 140);
  const snapshot = getLogicalLineSnapshotAt(buf, row);
  const parsed = extractCodexDraftFromLine(snapshot);
  const text = String(snapshot.text || '').replace(/\s+/g, ' ').slice(0, 180);
  const hasPrompt = hasCodexComposerPromptGlyph(snapshot.text);
  return 'row=' + row + ':prompt=' + hasPrompt + ':parsed=' + parsed.hasDraft + ':suffix=' + (parsed.sourceSuffix || '') + ':raw=' + JSON.stringify(raw) + ':logical=' + JSON.stringify(text);
}

function buildCodexProbeDebug(buf, terminal, cursorRows, visibleStart, visibleEnd, reason) {
  const tailStart = Math.max(0, buf.length - Math.max(12, Math.min(terminal.rows || 12, 32)));
  const sampleRows = Array.from(new Set([
    ...cursorRows,
    ...Array.from({ length: Math.max(0, visibleEnd - visibleStart) }, (_, i) => visibleStart + i),
    ...Array.from({ length: Math.max(0, buf.length - tailStart) }, (_, i) => tailStart + i),
  ])).filter((row) => row >= 0 && row < buf.length);
  return [
    'reason=' + reason,
    'rows=' + terminal.rows,
    'cols=' + terminal.cols,
    'bufLength=' + buf.length,
    'baseY=' + buf.baseY,
    'cursorY=' + buf.cursorY,
    'viewportY=' + buf.viewportY,
    'visible=' + visibleStart + '-' + visibleEnd,
    'tail=' + tailStart + '-' + buf.length,
    'cursorRows=' + (cursorRows.join(',') || 'none'),
    'samples=[' + sampleRows.map((row) => describeCodexDraftProbeRow(buf, row)).join(' | ') + ']',
  ].join(' ');
}

function getHeadlessCodexDraftState(tabId, reason = 'headless-draft') {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) {
    return { success: false, hasDraft: null, preview: '', source: 'no-headless-mirror', debug: 'reason=no-headless-mirror:' + reason };
  }
  if (state.complete !== true) {
    return {
      success: false,
      hasDraft: null,
      preview: '',
      source: 'headless-mirror-incomplete',
      debug: 'reason=headless-mirror-incomplete:' + (state.incompleteReason || reason),
    };
  }
  const frameBlocker = getCodexDraftFrameBlocker({
    synchronizedOutputOpen: state.redrawTrace?.synchronizedOutputOpen === true,
    writeSeq: state.writeSeq,
    flushedSeq: state.flushedSeq,
    pendingResizeWriteSeq: state.pendingResizeWriteSeq,
  });
  if (frameBlocker) {
    return {
      success: true,
      hasDraft: null,
      preview: '',
      source: 'headless-main:frame-not-authoritative',
      debug: [
        'reason=' + frameBlocker + ':' + reason,
        'writeSeq=' + Number(state.writeSeq || 0),
        'flushedSeq=' + Number(state.flushedSeq || 0),
        'resizeBoundary=' + (state.pendingResizeWriteSeq ?? 'none'),
      ].join(' '),
    };
  }
  try {
    const terminal = state.terminal;
    const buf = terminal.buffer.active;
    const visibleEnd = Math.min(buf.viewportY + terminal.rows, buf.length);
    const visibleStart = Math.max(buf.viewportY, visibleEnd - 10);
    const cursorRows = Array.from(new Set([
      buf.baseY + buf.cursorY,
      buf.cursorY,
    ])).filter((row) => row >= 0 && row < buf.length);
    const withSource = (parsed, source) => ({
      ...parsed,
      success: true,
      source: 'headless-main:' + source,
      frameIdentity: { generation: state.generation, writeSeq: state.flushedSeq },
    });

    const currentScreen = getHeadlessVisibleBufferSnapshot(
      tabId,
      reason + ':draft-surface-proof',
    );
    const currentScreenText = Array.isArray(currentScreen?.lines)
      ? currentScreen.lines.map((line) => String(line?.text || '')).join('\n')
      : '';
    const rewindFrame = classifyManualCodexEnterFrame(currentScreen);
    const surfaceGuard = enforceCodexInteractiveSurfaceDraftAuthority(
      {
        success: true,
        hasDraft: false,
        preview: currentScreenText.replace(/\s+/g, ' ').trim().slice(0, 160),
      },
      {
        nativeRewindProven: rewindFrame.kind === 'native-rewind-confirm'
          || isCodexNativeRewindFrameText(currentScreenText),
        activePicker: isCodexActivePickerFrame(currentScreenText),
      },
    );
    if (surfaceGuard?.hasDraft === null) {
      return {
        ...surfaceGuard,
        debug: 'reason=' + surfaceGuard.source
          + ' rewind=' + rewindFrame.reason,
      };
    }

    for (const row of cursorRows) {
      const cursorSnapshot = getLogicalLineSnapshotAt(buf, row);
      // Cursor position alone is not composer proof. Native Rewind and picker
      // footers are dim too; treating any dim row as "empty" let History send
      // Enter into an overlay instead of the composer.
      if (!hasCodexComposerPromptGlyph(cursorSnapshot.text)) continue;
      const parsed = extractCodexDraftFromLine(cursorSnapshot);
      if (parsed.hasDraft !== null) {
        const multilineDraft = parsed.hasDraft === false && !parsed.preview
          ? extractCodexDraftAfterEmptyPrompt(buf, row)
          : null;
        if (multilineDraft) return withSource(multilineDraft, 'cursor:' + row + multilineDraft.sourceSuffix);
        const debug = parsed.hasDraft === false && !parsed.preview
          ? buildCodexProbeDebug(buf, terminal, cursorRows, visibleStart, visibleEnd, 'cursor-empty-false')
          : undefined;
        return withSource({ ...parsed, debug }, 'cursor:' + row + (parsed.sourceSuffix || ''));
      }
    }

    for (let row = visibleEnd - 1; row >= visibleStart; row--) {
      const snapshot = getLogicalLineSnapshotAt(buf, row);
      if (!hasCodexComposerPromptGlyph(snapshot.text)) continue;
      const parsed = extractCodexDraftFromLine(snapshot);
      if (parsed.hasDraft !== null) {
        const multilineDraft = parsed.hasDraft === false && !parsed.preview
          ? extractCodexDraftAfterEmptyPrompt(buf, row)
          : null;
        if (multilineDraft) return withSource(multilineDraft, 'viewport:' + row + multilineDraft.sourceSuffix);
        const debug = parsed.hasDraft === false && !parsed.preview
          ? buildCodexProbeDebug(buf, terminal, cursorRows, visibleStart, visibleEnd, 'viewport-empty-false')
          : undefined;
        return withSource({ ...parsed, debug }, 'viewport:' + row + (parsed.sourceSuffix || ''));
      }
    }

    const tailStart = Math.max(0, buf.length - Math.max(12, Math.min(terminal.rows || 12, 32)));
    for (let row = buf.length - 1; row >= tailStart; row--) {
      if (row >= visibleStart && row < visibleEnd) continue;
      if (cursorRows.includes(row)) continue;
      const snapshot = getLogicalLineSnapshotAt(buf, row);
      if (!hasCodexComposerPromptGlyph(snapshot.text)) continue;
      const parsed = extractCodexDraftFromLine(snapshot);
      if (parsed.hasDraft !== null) {
        const multilineDraft = parsed.hasDraft === false && !parsed.preview
          ? extractCodexDraftAfterEmptyPrompt(buf, row)
          : null;
        if (multilineDraft) return withSource(multilineDraft, 'tail:' + row + multilineDraft.sourceSuffix);
        const debug = parsed.hasDraft === false && !parsed.preview
          ? buildCodexProbeDebug(buf, terminal, cursorRows, visibleStart, visibleEnd, 'tail-empty-false')
          : undefined;
        return withSource({ ...parsed, debug }, 'tail:' + row + (parsed.sourceSuffix || ''));
      }
    }

    const debug = buildCodexProbeDebug(buf, terminal, cursorRows, visibleStart, visibleEnd, 'no-definitive-codex-composer-row');
    return { success: true, hasDraft: null, preview: '', source: 'headless-main:unknown', debug };
  } catch (err) {
    state.failed = true;
    logHeadlessTerminalMirrorError(tabId, state, 'draft probe failed', err);
    return { success: false, hasDraft: null, preview: '', source: 'headless-main:error', error: err?.message || String(err), debug: 'reason=exception:' + reason };
  }
}

async function waitForHeadlessCodexDraftState(
  tabId,
  expected,
  timeoutMs = 900,
  reason = 'headless-draft-wait',
  { waitOnUnknownOnly = false } = {},
) {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) {
    return { success: false, hasDraft: null, preview: '', source: 'no-headless-mirror', debug: 'reason=no-headless-mirror:' + reason };
  }
  if (state.complete !== true) {
    return {
      success: false,
      hasDraft: null,
      preview: '',
      source: 'headless-mirror-incomplete',
      debug: 'reason=headless-mirror-incomplete:' + (state.incompleteReason || reason),
    };
  }
  let checks = 0;
  const read = () => {
    checks += 1;
    return getHeadlessCodexDraftState(tabId, reason);
  };
  let first = read();
  if (
    agentSendTestFaultActive('codex-draft-unknown-once')
    && !codexDraftUnknownTestFaultConsumed
    && codexTurnWatchers.get(tabId)?.busy === true
  ) {
    codexDraftUnknownTestFaultConsumed = true;
    first = {
      ...first,
      success: true,
      hasDraft: null,
      preview: '',
      source: 'test-fault:codex-draft-unknown-once',
    };
    console.warn('[TestFault] codex draft proof forced unknown once tab='
      + String(tabId).slice(-12)
      + ' generation=' + String(state.generation || '-').slice(0, 8)
      + ' reason=' + reason);
  }
  if (!shouldWaitForCodexDraftProof({
    initialHasDraft: first.hasDraft,
    expected,
    waitOnUnknownOnly,
  })) {
    return { ...first, success: true, timedOut: false, checks };
  }

  console.log('[CodexDraftProofWait] start tab=' + String(tabId).slice(-12)
    + ' generation=' + String(state.generation || '-').slice(0, 8)
    + ' reason=' + reason
    + ' initial=' + first.hasDraft
    + ' expected=' + expected
    + ' unknownOnly=' + waitOnUnknownOnly);

  return await new Promise((resolve) => {
    let settled = false;
    let sub = null;
    let timer = null;
    const finish = (draftState, timedOut) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      try { sub?.dispose?.(); } catch {}
      state.synchronizedFrameWaiters?.delete(check);
      console.log('[CodexDraftProofWait] finish tab=' + String(tabId).slice(-12)
        + ' generation=' + String(state.generation || '-').slice(0, 8)
        + ' reason=' + reason
        + ' hasDraft=' + draftState?.hasDraft
        + ' timedOut=' + timedOut
        + ' checks=' + checks
        + (draftState?.error ? ' error=' + draftState.error : ''));
      resolve({ ...draftState, timedOut, checks });
    };
    const check = () => {
      if (getHeadlessTerminalMirror(tabId) !== state || state.disposed === true) {
        finish({
          success: false,
          hasDraft: null,
          preview: '',
          source: 'headless-main:generation-changed',
          error: 'headless-mirror-generation-changed',
        }, false);
        return;
      }
      if (state.failed === true) {
        finish({
          success: false,
          hasDraft: null,
          preview: '',
          source: 'headless-main:error',
          error: 'headless-mirror-failed',
        }, false);
        return;
      }
      const draftState = read();
      if (shouldFinishCodexDraftProofWait({
        hasDraft: draftState.hasDraft,
        expected,
        waitOnUnknownOnly,
      })) finish(draftState, false);
    };
    const onWriteParsed = state.terminal?.onWriteParsed;
    if (typeof onWriteParsed === 'function') {
      sub = onWriteParsed.call(state.terminal, check);
    }
    state.synchronizedFrameWaiters?.add(check);
    timer = setTimeout(() => finish(createCodexDraftProofWaitTimeoutOutcome({
      source: first.source,
    }), true), timeoutMs);
    check();
  });
}

function getHeadlessVisibleBufferSnapshot(tabId, reason, { preferCommitted = true } = {}) {
  const state = getHeadlessTerminalMirror(tabId);
  if (!state) return { success: false, error: 'no-headless-mirror', tabId, reason, source: 'headless-main' };
  if (state.complete !== true) {
    return {
      success: false,
      error: 'headless-mirror-incomplete',
      incompleteReason: state.incompleteReason || 'unknown-history',
      tabId,
      reason,
      source: 'headless-main',
    };
  }
  if (preferCommitted
    && state.redrawTrace?.synchronizedOutputOpen === true
    && state.lastCommittedVisibleSnapshot) {
    return {
      ...state.lastCommittedVisibleSnapshot,
      reason,
      committedFrameReplay: true,
      liveSynchronizedOutputOpen: true,
      liveSynchronizedOutputGeneration: Number(
        state.redrawTrace?.synchronizedOutputGeneration || 0,
      ),
      liveWriteSeq: state.writeSeq,
      liveFlushedSeq: state.flushedSeq,
    };
  }
  try {
    const terminal = state.terminal;
    const buf = terminal.buffer.active;
    const startLine = buf.viewportY;
    const endLine = Math.min(startLine + terminal.rows, buf.length);
    // Codex's native transcript title can sit one physical buffer row above
    // the auto-follow viewport while the selected inverse prompt and footer
    // remain visible. Keep a tiny same-frame guard band for destructive UI
    // classification; do not expand the ordinary visible `lines` projection.
    const preViewportLines = [];
    for (let i = Math.max(0, startLine - 2); i < startLine; i++) {
      const line = buf.getLine(i);
      if (!line) continue;
      const text = line.translateToString(true);
      const row = {
        row: i,
        text,
        wrapped: !!line.isWrapped,
      };
      if (String(text || '').trim()) {
        const summary = summarizeXtermLineStyles(line);
        row.firstTextStyle = summary.firstTextStyle;
        row.styles = summary.styles;
        row.hasInverse = summary.hasInverse;
        row.hasNonDefaultBg = summary.hasNonDefaultBg;
        row.hasNonDefaultFg = summary.hasNonDefaultFg;
        row.hasDim = summary.hasDim;
        row.allTextDim = summary.allTextDim;
        row.styleCellCount = summary.textCellCount;
      }
      preViewportLines.push(row);
    }
    const lines = [];
    let codexActivePrompt = null;
    for (let i = startLine; i < endLine; i++) {
      const line = buf.getLine(i);
      if (!line) continue;
      const text = line.translateToString(true);
      const isPromptLine = hasCodexComposerPromptGlyph(text);
      const geometry = summarizeXtermLineGeometry(line);
      const row = {
        row: i,
        text,
        wrapped: !!line.isWrapped,
        occupiedEndX: geometry.occupiedEndX,
        promptCellX: geometry.promptCellX,
      };
      if (String(text || '').trim()) {
        const summary = summarizeXtermLineStyles(line);
        row.firstTextStyle = summary.firstTextStyle;
        row.styles = summary.styles;
        row.hasInverse = summary.hasInverse;
        row.hasNonDefaultBg = summary.hasNonDefaultBg;
        row.hasNonDefaultFg = summary.hasNonDefaultFg;
        row.hasDim = summary.hasDim;
        row.allTextDim = summary.allTextDim;
        row.styleCellCount = summary.textCellCount;
        row.activeByInverse = isPromptLine && summary.hasInverse;
        if (isPromptLine) {
          const logical = getLogicalLineSnapshotAt(buf, i);
          const promptIndex = Math.max(
            String(logical.text || '').lastIndexOf('❯'),
            String(logical.text || '').lastIndexOf('›'),
          );
          const suffixCells = promptIndex >= 0
            ? (logical.cells || [])
              .slice(promptIndex + 1)
            : [];
          const suffixStyle = summarizeClaudePromptSuffixStyle(suffixCells);
          row.promptSuffixAllDim = suffixStyle.allDim;
          row.promptSuffixHasInverse = suffixStyle.hasInverse;
          row.promptSuffixHasNonDefaultBg = suffixStyle.hasNonDefaultBg;
          row.promptSuffixWrapped = logical.wrapped === true;
        }
        if (isPromptLine && summary.hasInverse) {
          const logical = getLogicalLineSnapshotAt(buf, i);
          codexActivePrompt = {
            row: i,
            text: logical.text || text,
            firstTextStyle: summary.firstTextStyle,
            styles: summary.styles,
            hasInverse: summary.hasInverse,
            hasNonDefaultBg: summary.hasNonDefaultBg,
          };
        }
      }
      lines.push(row);
    }
    if (codexActivePrompt) {
      const selectedText = readManualCodexRewindSelectedText(
        lines,
        codexActivePrompt.row,
      );
      if (selectedText) {
        codexActivePrompt = {
          ...codexActivePrompt,
          text: selectedText,
        };
      }
    }
    const cursorRow = buf.baseY + buf.cursorY;
    let codexCursorComposer = null;
    if (cursorRow >= 0 && cursorRow < buf.length) {
      const cursorLogical = getLogicalLineSnapshotAt(buf, cursorRow);
      if (hasCodexComposerPromptGlyph(cursorLogical.text)) {
        const parsedCursorComposer = extractCodexDraftFromLine(cursorLogical);
        if (parsedCursorComposer.hasDraft === true) {
          codexCursorComposer = {
            row: cursorRow,
            cursorX: buf.cursorX,
            text: parsedCursorComposer.text,
            hasDraft: true,
            cursorOwned: true,
          };
        }
      }
    }
    return {
      success: true,
      source: 'headless-main',
      tabId,
      reason,
      rows: terminal.rows,
      cols: terminal.cols,
      baseY: buf.baseY,
      viewportY: buf.viewportY,
      cursorX: buf.cursorX,
      cursorY: buf.cursorY,
      bufferType: buf.type,
      mirrorGeneration: state.generation,
      mirrorGenerationOrdinal: state.generationOrdinal,
      synchronizedOutputOpen: state.redrawTrace?.synchronizedOutputOpen === true,
      synchronizedOutputSeq: state.redrawTrace?.synchronizedOutputSeq ?? null,
      synchronizedOutputGeneration: Number(
        state.redrawTrace?.synchronizedOutputGeneration || 0,
      ),
      authoritativeFrameCommitted: state.redrawTrace?.synchronizedOutputOpen !== true
        && Number(state.writeSeq || 0) === Number(state.flushedSeq || 0)
        && (
          state.pendingResizeWriteSeq === null
          || Number(state.writeSeq || 0) > Number(state.pendingResizeWriteSeq)
        ),
      committedFrameGeneration: state.lastCommittedVisibleSnapshot?.writeSeq === state.writeSeq
        ? Number(state.lastCommittedVisibleSnapshot.committedFrameGeneration || 0)
        : null,
      committedWriteSeq: state.lastCommittedVisibleSnapshot?.writeSeq === state.writeSeq
        ? state.lastCommittedVisibleSnapshot.writeSeq
        : null,
      preViewportLines,
      lines,
      codexActivePrompt,
      codexCursorComposer,
      writeSeq: state.writeSeq,
      flushedSeq: state.flushedSeq,
      pendingResizeWriteSeq: state.pendingResizeWriteSeq,
    };
  } catch (err) {
    state.failed = true;
    logHeadlessTerminalMirrorError(tabId, state, 'snapshot failed', err);
    return { success: false, error: err?.message || String(err), tabId, reason, source: 'headless-main' };
  }
}

function commitHeadlessVisibleBufferSnapshot(tabId, state, flushedSeq) {
  const frameBlocker = getCodexDraftFrameBlocker({
    synchronizedOutputOpen: state?.redrawTrace?.synchronizedOutputOpen === true,
    writeSeq: state?.writeSeq,
    flushedSeq: state?.flushedSeq,
    pendingResizeWriteSeq: state?.pendingResizeWriteSeq,
  });
  if (!state
    || getHeadlessTerminalMirror(tabId) !== state
    || state.failed === true
    || state.complete !== true
    || frameBlocker !== null
    || Number(flushedSeq || 0) !== Number(state.writeSeq || 0)) {
    return null;
  }
  const snapshot = getHeadlessVisibleBufferSnapshot(
    tabId,
    'committed-frame:' + String(flushedSeq),
    { preferCommitted: false },
  );
  if (!snapshot?.success) return null;
  const previous = state.lastCommittedVisibleSnapshot;
  if (previous?.writeSeq === snapshot.writeSeq) return previous;
  const committedFrameGeneration = ++state.committedFrameGeneration;
  const committed = {
    ...snapshot,
    authoritativeFrameCommitted: true,
    committedFrameGeneration,
    committedWriteSeq: snapshot.writeSeq,
    committedFrameReplay: false,
    liveSynchronizedOutputOpen: false,
    pendingResizeWriteSeq: null,
  };
  state.lastCommittedVisibleSnapshot = committed;
  state.pendingResizeWriteSeq = null;
  // Settle the exact native choice before ANY downstream frame/readiness
  // observer can reconcile an older app intent against the new composer.
  observeCodexNativeSettingsIntentFrame(tabId, state, committed);
  observeCommittedTerminalComposerForensics(
    tabId,
    state,
    committed,
    committedFrameGeneration,
  );
  observeClaudeProviderFatalCommittedFrame(
    tabId,
    state,
    committed,
    committedFrameGeneration,
  );
  observeCodexModelCapacityCommittedFrame(
    tabId,
    state,
    committed,
    committedFrameGeneration,
  );
  observeCodexQueuedMessageCommittedFrame(tabId, state, committed);
  observeCodexInputControlReadinessFrame(tabId, state, committed);
  observeCodexSettingsActivityFrame(tabId, state, committed);
  observeCodexStartupGoalCommittedFrame(tabId, state, committed);
  observeCodexStartupComposerCommittedFrame(tabId, state, committed);
  observeClaudeTrustFolderPromptCommittedFrame(
    tabId,
    state,
    committed,
    committedFrameGeneration,
  );
  observeClaudeAutoModeDefaultPromptCommittedFrame(
    tabId,
    state,
    committed,
    committedFrameGeneration,
  );
  return committed;
}

function parseClaudeDraftFromVisibleSnapshot(snapshot) {
  return parseClaudeComposerCurrentFrame(snapshot);
}

function claudeMissingPromptControlSurfaceActive(tabId, snapshot) {
  const visibleText = Array.isArray(snapshot?.lines)
    ? snapshot.lines.map((line) => line?.text || '').join('\n')
    : '';
  return claudeCtrlCDangerZone.has(tabId)
    || inspectClaudeTrustFolderPromptSnapshot(snapshot).visible === true
    || looksLikeClaudeRewindMenuText(visibleText)
    || /(?:Change effort level|Switch model\?)/i.test(visibleText)
    || inspectClaudeAutoModeDefaultPromptSnapshot(snapshot).visible === true;
}

function classifyClaudeMissingPromptCaptureForTab(
  tabId,
  snapshot,
  proof,
  ownedWriteOperation = null,
) {
  const term = terminals.get(tabId) || null;
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const startupGate = claudeStartupDefaultsGateByTab.get(tabId) || null;
  const rewind = activeRewindOperations.get(tabId) || null;
  return classifyClaudeMissingPromptExactCaptureAdmission({
    proof,
    snapshot,
    turnBusy: claudeTurnBusy.get(tabId) === true,
    localCommandActive: claudeLocalCommandWatchers.has(tabId),
    compactActive: !!compactOperations.getActive(tabId, 'claude'),
    awaitingInput: claudeAwaitingInput.get(tabId) === true
      || claudePendingQuestion.has(tabId),
    stopping: aiStoppingTabs.get(tabId)?.toolType === 'claude',
    rewindActive: rewind?.toolType === 'claude',
    writeOperationActive: !!term && hasConflictingPtyWriteOperation({
      activeOperation: ptyActiveWriteOperation.get(term) || null,
      lastQueuedOperation: ptyLastQueuedWriteOperation.get(term) || null,
      ownedOperation: ownedWriteOperation,
    }),
    startupGateReady: !!launch?.generation
      && claudePromptReady.has(tabId)
      && startupGate?.generation === launch.generation
      && startupGate?.status === 'ready',
    controlSurfaceActive: claudeMissingPromptControlSurfaceActive(tabId, snapshot),
  });
}

async function requestTerminalClaudeDraftState(webContents, tabId, reason, timeoutMs = 700) {
  if (!tabId || !terminals.has(tabId) || !hasLiveClaudeInTab(tabId) || aiStoppingTabs.get(tabId)?.toolType === 'claude') {
    return {
      success: true,
      proofOutcome: 'unknown',
      proofReason: aiStoppingTabs.get(tabId)?.toolType === 'claude'
        ? 'claude-stopping'
        : 'claude-current-process-not-proven',
      hasDraft: null,
      text: '',
      preview: '',
      source: 'claude-composer:presence-not-live',
    };
  }

  const terminalBefore = terminals.get(tabId) || null;
  const runSeqBefore = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const inputRevisionBefore = getTerminalInputRevision(tabId);
  const lifecycleGenerationBefore = getTerminalLifecycleGeneration(tabId);
  const mirrorBefore = getHeadlessTerminalMirror(tabId);
  let snapshot = await requestTerminalVisibleBufferSnapshot(
    webContents,
    tabId,
    typeof reason === 'string' ? reason : 'claude-draft-state',
    Math.max(100, Math.min(Number(timeoutMs) || 700, 2500))
  );
  if (!snapshot?.success) {
    return {
      success: false,
      hasDraft: null,
      text: '',
      preview: '',
      source: snapshot?.source || 'visible-buffer',
      error: snapshot?.error || 'snapshot_failed',
    };
  }
  if (snapshot.synchronizedOutputOpen === true && mirrorBefore) {
    const closed = await waitForHeadlessSynchronizedOutputClose(
      tabId,
      mirrorBefore,
      Math.max(100, Math.min(Number(timeoutMs) || 700, 2500)),
    );
    if (closed.ready === true) {
      snapshot = await requestTerminalVisibleBufferSnapshot(
        webContents,
        tabId,
        (typeof reason === 'string' ? reason : 'claude-draft-state') + ':after-sync-close',
        Math.max(100, Math.min(Number(timeoutMs) || 700, 2500)),
      );
    }
  }
  if (!snapshot?.success) {
    return {
      success: false,
      hasDraft: null,
      text: '',
      preview: '',
      source: snapshot?.source || 'headless-main',
      error: snapshot?.error || 'snapshot_after_frame_close_failed',
    };
  }
  if (
    snapshot.source !== 'headless-main'
    || !mirrorBefore
    || !snapshot.mirrorGeneration
    || snapshot.writeSeq !== snapshot.flushedSeq
  ) {
    return {
      success: true,
      tabId,
      proofOutcome: 'unknown',
      hasDraft: null,
      text: '',
      preview: '',
      source: (snapshot?.source || 'visible-buffer') + ':claude-composer:unknown:headless-proof-required',
      proofReason: 'headless-current-frame-proof-required',
    };
  }
  if (snapshot.synchronizedOutputOpen === true) {
    return {
      success: true,
      tabId,
      proofOutcome: 'unknown',
      hasDraft: null,
      text: '',
      preview: '',
      source: 'headless-main:claude-composer:unknown:synchronized-frame-open',
      proofReason: 'synchronized-frame-open',
      mirrorGeneration: snapshot.mirrorGeneration,
      mirrorGenerationOrdinal: snapshot.mirrorGenerationOrdinal ?? null,
      mirrorWriteSeq: snapshot.writeSeq ?? null,
      mirrorFlushedSeq: snapshot.flushedSeq ?? null,
      mirrorSynchronizedOutputOpen: true,
      synchronizedOutputGeneration: snapshot.synchronizedOutputGeneration ?? null,
    };
  }
  const stableGeneration = terminalBefore
    && terminals.get(tabId) === terminalBefore
    && Number(terminalCommandState.get(tabId)?.runSeq || 0) === runSeqBefore
    && getTerminalInputRevision(tabId) === inputRevisionBefore
    && getTerminalLifecycleGeneration(tabId) === lifecycleGenerationBefore
    && getHeadlessTerminalMirror(tabId) === mirrorBefore
    && snapshot.mirrorGeneration === mirrorBefore.generation;
  if (!stableGeneration) {
    return {
      success: true,
      tabId,
      proofOutcome: 'unknown',
      hasDraft: null,
      text: '',
      preview: '',
      source: (snapshot?.source || 'visible-buffer') + ':claude-composer:unknown:generation-changed',
      proofReason: 'terminal-or-input-generation-changed',
    };
  }
  const trustFolderPrompt = inspectClaudeTrustFolderPromptSnapshot(snapshot);
  const autoModeDefaultPrompt = inspectClaudeAutoModeDefaultPromptSnapshot(snapshot);
  const parsedProof = (
    claudeTrustFolderPromptHintTabs.has(tabId)
    || trustFolderPrompt.visible === true
  )
    ? {
        success: true,
        proofOutcome: 'unknown',
        hasDraft: null,
        text: '',
        preview: '',
        source: 'headless-main:claude-composer:unknown:trust-folder-prompt',
        proofReason: 'trust-folder-prompt',
      }
    : (
      claudeAutoModeDefaultPromptHintTabs.has(tabId)
    || autoModeDefaultPrompt.visible === true
    )
    ? {
        success: true,
        proofOutcome: 'unknown',
        hasDraft: null,
        text: '',
        preview: '',
        source: 'headless-main:claude-composer:unknown:auto-mode-default-prompt',
        proofReason: 'auto-mode-default-prompt',
      }
    : parseClaudeDraftFromVisibleSnapshot(snapshot);
  const missingPromptAdmission = classifyClaudeMissingPromptCaptureForTab(
    tabId,
    snapshot,
    parsedProof,
  );
  return {
    tabId,
    terminalRunSeq: runSeqBefore,
    inputRevision: inputRevisionBefore,
    terminalLifecycleGeneration: lifecycleGenerationBefore,
    mirrorGeneration: snapshot.mirrorGeneration,
    mirrorGenerationOrdinal: snapshot.mirrorGenerationOrdinal ?? null,
    mirrorWriteSeq: snapshot.writeSeq ?? null,
    mirrorFlushedSeq: snapshot.flushedSeq ?? null,
    mirrorSynchronizedOutputOpen: snapshot.synchronizedOutputOpen === true,
    synchronizedOutputGeneration: snapshot.synchronizedOutputGeneration ?? null,
    ...parsedProof,
    ...(missingPromptAdmission.recommended === true
      ? {
          exactCaptureRecommended: true,
          exactCaptureAdmissionReason: missingPromptAdmission.reason,
        }
      : (parsedProof?.proofReason === 'active-prompt-not-found'
        ? { exactCaptureBlockedReason: missingPromptAdmission.reason }
        : {})),
  };
}

function claudeDraftProofIsSettled(result) {
  return (result?.proofOutcome === 'found' && result?.hasDraft === true)
    || (result?.proofOutcome === 'absent' && result?.hasDraft === false);
}

async function waitForTerminalClaudeDraftState(
  webContents,
  tabId,
  reason,
  timeoutMs = 700,
  {
    waitOnUnknownOnly = false,
    waitTimeoutMs = 15000,
  } = {},
) {
  const firstMirror = getHeadlessTerminalMirror(tabId);
  let observedWriteSeq = Number(firstMirror?.writeSeq || 0);
  let result = await requestTerminalClaudeDraftState(
    webContents,
    tabId,
    reason,
    timeoutMs,
  );
  if (waitOnUnknownOnly !== true || claudeDraftProofIsSettled(result)) {
    return { ...result, timedOut: false, checks: 1 };
  }

  const deadline = Date.now() + Math.max(100, Number(waitTimeoutMs) || 15000);
  let checks = 1;
  console.log('[ClaudeDraftProofWait] start tab=' + String(tabId).slice(-12)
    + ' generation=' + String(firstMirror?.generation || '-').slice(0, 8)
    + ' reason=' + reason
    + ' initial=' + (result?.proofOutcome || 'unknown')
    + ':' + (result?.proofReason || result?.error || '-'));
  while (Date.now() < deadline) {
    const mirror = getHeadlessTerminalMirror(tabId);
    if (!mirror || mirror !== firstMirror || mirror.disposed === true || mirror.failed === true) {
      return {
        ...result,
        timedOut: false,
        checks,
        proofOutcome: 'unknown',
        hasDraft: null,
        proofReason: !mirror || mirror !== firstMirror
          ? 'headless-mirror-generation-changed'
          : 'headless-mirror-failed',
      };
    }
    const resultWriteSeq = Number(result?.mirrorWriteSeq);
    if (Number.isFinite(resultWriteSeq)) {
      observedWriteSeq = Math.max(observedWriteSeq, resultWriteSeq);
    }
    if (Number(mirror.writeSeq || 0) <= observedWriteSeq) {
      const edge = await waitForHeadlessSynchronizedOutputClose(
        tabId,
        mirror,
        Math.max(50, deadline - Date.now()),
        { afterWriteSeq: observedWriteSeq },
      );
      if (edge?.ready !== true) {
        console.warn('[ClaudeDraftProofWait] finish tab=' + String(tabId).slice(-12)
          + ' reason=' + reason
          + ' outcome=unknown'
          + ' edge=' + (edge?.reason || '-')
          + ' checks=' + checks);
        return {
          ...result,
          timedOut: true,
          checks,
          proofOutcome: 'unknown',
          hasDraft: null,
          proofReason: edge?.reason || result?.proofReason || 'claude-draft-proof-timeout',
        };
      }
    }
    observedWriteSeq = Math.max(observedWriteSeq, Number(mirror.writeSeq || 0));
    checks += 1;
    result = await requestTerminalClaudeDraftState(
      webContents,
      tabId,
      reason + ':wait-' + checks,
      timeoutMs,
    );
    if (claudeDraftProofIsSettled(result)) {
      console.log('[ClaudeDraftProofWait] finish tab=' + String(tabId).slice(-12)
        + ' reason=' + reason
        + ' outcome=' + result.proofOutcome
        + ' hasDraft=' + result.hasDraft
        + ' checks=' + checks);
      return { ...result, timedOut: false, checks };
    }
  }
  return {
    ...result,
    timedOut: true,
    checks,
    proofOutcome: 'unknown',
    hasDraft: null,
    proofReason: result?.proofReason || 'claude-draft-proof-timeout',
  };
}

async function verifyClaudeComposerEmptyAtWriteBoundary(
  tabId,
  term,
  reason,
  { exactEmptyEvidence = null } = {},
) {
  let proof = await requestTerminalClaudeDraftState(
    mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    tabId,
    reason,
    900,
  );
  const mirror = getHeadlessTerminalMirror(tabId);
  let decision = validateClaudeComposerWriteBoundary({
    proof,
    terminalMatches: terminals.get(tabId) === term,
    currentInputRevision: getTerminalInputRevision(tabId),
    currentRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    currentLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    currentMirrorGeneration: mirror?.generation || null,
    currentMirrorWriteSeq: mirror?.writeSeq ?? null,
    currentMirrorFlushedSeq: mirror?.flushedSeq ?? null,
    currentMirrorSynchronizedOutputOpen: mirror?.redrawTrace?.synchronizedOutputOpen === true,
  });
  if (!decision.valid && exactEmptyEvidence) {
    const currentSnapshot = getHeadlessVisibleBufferSnapshot(
      tabId,
      reason + ':reserved-exact-empty-consume',
      { preferCommitted: false },
    );
    const launch = claudeLaunchGenerationByTab.get(tabId) || null;
    const startupGate = claudeStartupDefaultsGateByTab.get(tabId) || null;
    const exactDecision = resolveClaudeComposerWriteBoundaryWithReservedExactEmptyEvidence({
      proof,
      evidence: exactEmptyEvidence,
      reservedEvidenceOwnedByCurrentOperation:
        ptyActiveWriteOperation.get(term)?.claudeExactEmptyEvidence === exactEmptyEvidence,
      terminalMatches: terminals.get(tabId) === term,
      currentInputRevision: getTerminalInputRevision(tabId),
      currentRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
      currentLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
      currentMirrorGeneration: mirror?.generation || null,
      currentMirrorWriteSeq: mirror?.writeSeq ?? null,
      currentMirrorFlushedSeq: mirror?.flushedSeq ?? null,
      currentMirrorSynchronizedOutputOpen: mirror?.redrawTrace?.synchronizedOutputOpen === true,
      currentSynchronizedOutputGeneration: Number(
        mirror?.redrawTrace?.synchronizedOutputGeneration || 0,
      ),
      turnBusy: claudeTurnBusy.get(tabId) === true || claudeSpinnerBusy.get(tabId) === true,
      localCommandActive: claudeLocalCommandWatchers.has(tabId),
      compactActive: !!compactOperations.getActive(tabId, 'claude'),
      awaitingInput: claudeAwaitingInput.get(tabId) === true || claudePendingQuestion.has(tabId),
      stopping: aiStoppingTabs.get(tabId)?.toolType === 'claude',
      rewindActive: activeRewindOperations.get(tabId)?.toolType === 'claude',
      startupGateReady: !!launch?.generation
        && claudePromptReady.has(tabId)
        && startupGate?.generation === launch.generation
        && startupGate?.status === 'ready',
      pickerActive: currentSnapshot?.success === true
        && inspectClaudeThinkingPickerSnapshot(currentSnapshot).visible === true,
      controlSurfaceActive: currentSnapshot?.success !== true
        || claudeMissingPromptControlSurfaceActive(tabId, currentSnapshot),
      replacementActive: terminals.get(tabId) !== term,
    });
    if (exactDecision.valid) {
      proof = exactDecision.proof;
      decision = exactDecision;
    }
  }
  console.log('[ClaudeComposerWriteBoundary] tab=' + String(tabId).slice(-12)
    + ' valid=' + decision.valid
    + ' reason=' + decision.reason
    + ' proof=' + (proof?.proofOutcome || 'unknown')
    + ' source=' + (proof?.source || '-')
    + ' promptRow=' + (proof?.promptRow ?? '-')
    + ' cursor=' + (proof?.cursorRow ?? '-') + ':' + (proof?.cursorX ?? '-')
    + ' run=' + (proof?.terminalRunSeq ?? '-')
    + ' inputRevision=' + (proof?.inputRevision ?? '-')
    + ' lifecycle=' + (proof?.terminalLifecycleGeneration || '-')
    + ' mirror=' + (proof?.mirrorGeneration || '-')
    + ' write=' + (proof?.mirrorWriteSeq ?? '-') + '/' + (proof?.mirrorFlushedSeq ?? '-')
    + ' syncOpen=' + (proof?.mirrorSynchronizedOutputOpen === true));
  return { ...decision, proof };
}

const claudeEditableLastPromptByTab = new Map();

function normalizeEditableLastPromptText(text) {
  return String(text || '')
    .replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function clearClaudeEditableLastPrompt(tabId, reason = 'clear') {
  if (!tabId || !claudeEditableLastPromptByTab.has(tabId)) return;
  const prev = claudeEditableLastPromptByTab.get(tabId);
  claudeEditableLastPromptByTab.delete(tabId);
  console.log('[ClaudeEditableLastPrompt] clear tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' uuid=' + String(prev?.targetUuid || '').slice(0, 8));
}

function markClaudeEditableLastPrompt(tabId, payload = {}) {
  const targetUuid = String(payload.targetUuid || '').trim();
  const targetText = normalizeEditableLastPromptText(payload.targetText || '');
  if (!tabId || !targetUuid || !targetText) return null;
  const liveSessionId = bridgeKnownSessions.get(tabId) || null;
  const state = {
    status: 'editable-last-prompt',
    tabId,
    sessionId: payload.sessionId || liveSessionId || null,
    targetUuid,
    targetText,
    startedAt: Date.now(),
    source: payload.source || 'claude-native-rewind',
  };
  claudeEditableLastPromptByTab.set(tabId, state);
  console.log('[ClaudeEditableLastPrompt] mark tab=' + String(tabId).slice(-12)
    + ' session=' + String(state.sessionId || '').slice(0, 8)
    + ' uuid=' + targetUuid.slice(0, 8)
    + ' chars=' + targetText.length
    + ' source=' + state.source);
  return state;
}

function getClaudeEditableLastPromptState(tabId, reason = 'get') {
  const state = tabId ? claudeEditableLastPromptByTab.get(tabId) : null;
  if (!state) {
    return { success: true, status: null, hasEditableLastPrompt: false, source: 'editable-last-prompt:none', reason };
  }
  if (!terminals.has(tabId) || !bridgeKnownSessions.has(tabId) || aiStoppingTabs.get(tabId)?.toolType === 'claude') {
    clearClaudeEditableLastPrompt(tabId, 'not-live:' + reason);
    return { success: true, status: null, hasEditableLastPrompt: false, source: 'editable-last-prompt:not-live', reason };
  }
  const liveSessionId = bridgeKnownSessions.get(tabId) || null;
  if (state.sessionId && liveSessionId && state.sessionId !== liveSessionId) {
    clearClaudeEditableLastPrompt(tabId, 'session-changed:' + reason);
    return { success: true, status: null, hasEditableLastPrompt: false, source: 'editable-last-prompt:session-changed', reason };
  }
  return {
    success: true,
    status: 'editable-last-prompt',
    hasEditableLastPrompt: true,
    targetUuid: state.targetUuid,
    targetText: state.targetText,
    sessionId: state.sessionId || liveSessionId || null,
    startedAt: state.startedAt,
    source: state.source,
    reason,
  };
}
// Claude Handshake: prompt injection with debounce (thinking handled by alwaysThinkingEnabled)
