async function flushClaudePendingPromptAfterStartup(tabId, generation, reason) {
  const dispatcher = claudePendingPromptDispatchers.get(tabId) || null;
  if (!dispatcher || dispatcher.generation !== generation) return false;
  if (dispatcher.inflight) return dispatcher.inflight;
  dispatcher.inflight = (async () => {
    if (
      claudeLaunchGenerationByTab.get(tabId)?.generation !== generation
      || terminals.get(tabId) !== dispatcher.term
      || claudePendingPrompt.get(tabId) !== dispatcher.prompt
    ) {
      console.warn('[ClaudeHandshake] pending prompt cancelled tab=' + String(tabId).slice(-12)
        + ' gen=' + generation
        + ' reason=ownership-changed trigger=' + reason);
      claudePendingPromptDispatchers.delete(tabId);
      return false;
    }
    claudePendingPromptDispatchers.delete(tabId);
    claudePendingPrompt.delete(tabId);
    console.log('[ClaudeHandshake] sending pending prompt after startup defaults tab='
      + String(tabId).slice(-12)
      + ' gen=' + generation
      + ' trigger=' + reason);
    await dispatcher.send();
    return true;
  })().catch((error) => {
    console.warn('[ClaudeHandshake] pending prompt send failed tab=' + String(tabId).slice(-12)
      + ' gen=' + generation
      + ' error=' + (error?.message || String(error)));
    return false;
  });
  return dispatcher.inflight;
}

async function handleClaudeAutoModeDefaultPrompt({
  tabId,
  expectedTerm,
  expectedMirror,
  expectedLaunchGeneration,
  expectedRunSeq,
  expectedLifecycleGeneration,
  expectedInputRevision,
} = {}) {
  const operation = {
    kind: 'claude-auto-mode-default-prompt',
    source: 'committed-headless-frame',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: true,
    manualEnterSubmitsPrompt: false,
    phase: 'queued',
    queuedAt: Date.now(),
  };
  return withPtyWriteLock(expectedTerm, async () => {
    const stillOwnsBeforeMutation = () => (
      terminals.get(tabId) === expectedTerm
      && getHeadlessTerminalMirror(tabId) === expectedMirror
      && (claudeLaunchGenerationByTab.get(tabId)?.generation || null) === expectedLaunchGeneration
      && Number(terminalCommandState.get(tabId)?.runSeq || 0) === expectedRunSeq
      && getTerminalLifecycleGeneration(tabId) === expectedLifecycleGeneration
      && getTerminalInputRevision(tabId) === expectedInputRevision
    );
    if (!stillOwnsBeforeMutation()) {
      return { success: false, handled: false, error: 'auto_mode_prompt_identity_changed' };
    }

    const closed = await waitForHeadlessSynchronizedOutputClose(
      tabId,
      expectedMirror,
      1500,
    );
    if (!closed.ready || !stillOwnsBeforeMutation()) {
      return {
        success: false,
        handled: false,
        error: closed.reason || 'auto_mode_prompt_frame_not_closed',
      };
    }
    let snapshot = getHeadlessVisibleBufferSnapshot(
      tabId,
      'claude-auto-mode-default:preflight',
      { preferCommitted: false },
    );
    let inspection = inspectClaudeAutoModeDefaultPromptSnapshot(snapshot);
    if (inspection.visible !== true || inspection.selectedOption === null) {
      return {
        success: true,
        handled: false,
        reason: inspection.reason || 'auto_mode_prompt_not_actionable',
      };
    }

    const ownedInputRevision = bumpTerminalInputRevision(tabId);
    const stillOwns = () => (
      terminals.get(tabId) === expectedTerm
      && getHeadlessTerminalMirror(tabId) === expectedMirror
      && (claudeLaunchGenerationByTab.get(tabId)?.generation || null) === expectedLaunchGeneration
      && Number(terminalCommandState.get(tabId)?.runSeq || 0) === expectedRunSeq
      && getTerminalLifecycleGeneration(tabId) === expectedLifecycleGeneration
      && getTerminalInputRevision(tabId) === ownedInputRevision
    );
    const observeAfterWrite = (data, phase, acceptInspection, timeoutMs = 2500) => {
      const afterWriteSeq = Number(snapshot?.writeSeq || 0);
      operation.phase = phase;
      return waitForCommittedSemanticFrame({
        subscribe(listener) {
          expectedMirror.synchronizedFrameWaiters.add(listener);
          return () => expectedMirror.synchronizedFrameWaiters.delete(listener);
        },
        readSnapshot() {
          return getHeadlessVisibleBufferSnapshot(
            tabId,
            'claude-auto-mode-default:' + phase,
            { preferCommitted: false },
          );
        },
        inspectSnapshot: inspectClaudeAutoModeDefaultPromptSnapshot,
        acceptInspection,
        trigger() {
          if (!stillOwns()) throw new Error('auto_mode_prompt_identity_changed');
          expectedTerm.write(data);
        },
        getAbortReason() {
          if (!stillOwns()) return 'auto_mode_prompt_identity_changed';
          if (expectedMirror.failed === true) return 'auto_mode_prompt_mirror_failed';
          return null;
        },
        afterWriteSeq,
        timeoutMs,
      });
    };

    if (inspection.selectedOption === 1) {
      const moved = await observeAfterWrite(
        '\x1b[B',
        'select-keep-bypass',
        (next) => next.visible === true && next.selectedOption === 2,
      );
      if (!moved.ready) {
        console.warn('[ClaudeAutoModeDefault] selection not proven tab='
          + String(tabId).slice(-12)
          + ' reason=' + moved.reason);
        return {
          success: false,
          handled: true,
          submitted: false,
          error: moved.reason || 'auto_mode_prompt_selection_unproven',
        };
      }
      snapshot = moved.snapshot;
      inspection = moved.inspection;
    }

    if (inspection.selectedOption !== 2 || !stillOwns()) {
      return {
        success: false,
        handled: true,
        submitted: false,
        error: 'auto_mode_prompt_keep_bypass_not_proven',
      };
    }

    console.log('[ClaudeAutoModeDefault] keep-bypass proven; writing Enter tab='
      + String(tabId).slice(-12));
    const dismissed = await observeAfterWrite(
      '\r',
      'confirm-keep-bypass',
      (next) => next.visible !== true,
      3500,
    );
    operation.submitted = true;
    operation.submittedAt = Date.now();
    if (!dismissed.ready) {
      console.warn('[ClaudeAutoModeDefault] Enter written but dismissal not proven tab='
        + String(tabId).slice(-12)
        + ' reason=' + dismissed.reason);
    } else {
      claudeAutoModeDefaultPromptHintTabs.delete(tabId);
      claudeAutoModeDefaultPromptHintBuffers.delete(tabId);
    }
    return {
      success: true,
      handled: true,
      submitted: true,
      dismissed: dismissed.ready === true,
      reason: dismissed.ready === true
        ? 'keep_bypass_confirmed'
        : 'keep_bypass_enter_written_dismissal_unproven',
    };
  }, operation);
}

function observeClaudeAutoModeDefaultPromptCommittedFrame(
  tabId,
  state,
  snapshot,
  committedFrameGeneration,
) {
  const inspection = inspectClaudeAutoModeDefaultPromptSnapshot(snapshot);
  if (
    !claudeLaunchGenerationByTab.has(tabId)
    && !bridgeKnownSessions.has(tabId)
    && claudeCliActive.get(tabId) !== true
  ) {
    return null;
  }
  if (inspection.visible !== true) {
    if (claudeAutoModeDefaultPromptHintTabs.has(tabId)) {
      const visibleText = Array.isArray(snapshot?.lines)
        ? snapshot.lines.map((line) => line?.text || '').join('\n')
        : '';
      const thinking = inspectClaudeThinkingPickerSnapshot(snapshot);
      const proceed = inspectClaudeThinkingProceedSnapshot(snapshot);
      const competingControlSurface = (
        looksLikeClaudeTrustFolderPromptText(visibleText)
        || looksLikeClaudeAutoModeDefaultPromptText(visibleText)
        || claudeCtrlCDangerZone.has(tabId)
        || looksLikeClaudeRewindMenuText(visibleText)
        || classifyClaudeSettingsDialogText(visibleText) !== null
        || thinking.modalPresent === true
        || proceed.visible === true
      );
      const composer = competingControlSurface
        ? null
        : parseClaudeComposerCurrentFrame(snapshot);
      if (
        composer
        && (composer.proofOutcome === 'found' || composer.proofOutcome === 'absent')
      ) {
        claudeAutoModeDefaultPromptHintTabs.delete(tabId);
        claudeAutoModeDefaultPromptHintBuffers.delete(tabId);
        console.log('[ClaudeAutoModeDefault] hint disproven by current composer tab='
          + String(tabId).slice(-12)
          + ' frame=' + committedFrameGeneration);
        publishClaudePromptReady(tabId, 'auto-mode onboarding dismissed');
      }
    }
    return null;
  }
  claudeAutoModeDefaultPromptHintTabs.add(tabId);
  if (claudePromptReady.delete(tabId)) {
    const launch = claudeLaunchGenerationByTab.get(tabId) || null;
    if (launch?.generation) {
      claudePromptStability.markActivity(
        tabId,
        launch.generation,
        'auto-mode-default-prompt:' + committedFrameGeneration,
      );
    }
    console.warn('[ClaudeAutoModeDefault] revoked false composer readiness tab='
      + String(tabId).slice(-12)
      + ' frame=' + committedFrameGeneration);
  }
  if (inspection.selectedOption === null) return inspection;
  if (claudeAutoModeDefaultPromptInflight.has(tabId)) return inspection;

  const expectedTerm = terminals.get(tabId) || null;
  if (!expectedTerm || getHeadlessTerminalMirror(tabId) !== state) return null;
  const token = {
    tabId,
    expectedTerm,
    expectedMirror: state,
    expectedLaunchGeneration:
      claudeLaunchGenerationByTab.get(tabId)?.generation || null,
    expectedRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    expectedLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    expectedInputRevision: getTerminalInputRevision(tabId),
    committedFrameGeneration,
  };
  const pending = Promise.resolve()
    .then(() => handleClaudeAutoModeDefaultPrompt(token))
    .then((result) => {
      console.log('[ClaudeAutoModeDefault] handled tab=' + String(tabId).slice(-12)
        + ' frame=' + committedFrameGeneration
        + ' selected=' + inspection.selectedOption
        + ' success=' + (result?.success === true)
        + ' submitted=' + (result?.submitted === true)
        + ' reason=' + String(result?.reason || result?.error || '-'));
      return result;
    })
    .catch((error) => {
      console.warn('[ClaudeAutoModeDefault] handler failed tab=' + String(tabId).slice(-12)
        + ' frame=' + committedFrameGeneration
        + ' error=' + (error?.message || String(error)));
      return { success: false, handled: false, error: error?.message || String(error) };
    })
    .finally(() => {
      if (claudeAutoModeDefaultPromptInflight.get(tabId) === pending) {
        claudeAutoModeDefaultPromptInflight.delete(tabId);
      }
    });
  claudeAutoModeDefaultPromptInflight.set(tabId, pending);
  return inspection;
}

async function handleClaudeTrustFolderPrompt({
  tabId,
  expectedTerm,
  expectedMirror,
  expectedLaunchGeneration,
  expectedRunSeq,
  expectedLifecycleGeneration,
  expectedInputRevision,
} = {}) {
  const operation = {
    kind: 'claude-trust-folder-prompt',
    source: 'committed-headless-frame',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: true,
    manualEnterSubmitsPrompt: false,
    phase: 'queued',
    queuedAt: Date.now(),
  };
  return withPtyWriteLock(expectedTerm, async () => {
    const stillOwns = (inputRevision = expectedInputRevision) => (
      terminals.get(tabId) === expectedTerm
      && getHeadlessTerminalMirror(tabId) === expectedMirror
      && (claudeLaunchGenerationByTab.get(tabId)?.generation || null)
        === expectedLaunchGeneration
      && Number(terminalCommandState.get(tabId)?.runSeq || 0) === expectedRunSeq
      && getTerminalLifecycleGeneration(tabId) === expectedLifecycleGeneration
      && getTerminalInputRevision(tabId) === inputRevision
    );
    if (!expectedLaunchGeneration || !stillOwns()) {
      return { success: false, handled: false, error: 'trust_folder_identity_changed' };
    }

    const closed = await waitForHeadlessSynchronizedOutputClose(
      tabId,
      expectedMirror,
      1500,
    );
    if (!closed.ready || !stillOwns()) {
      return {
        success: false,
        handled: false,
        error: closed.reason || 'trust_folder_frame_not_closed',
      };
    }
    let snapshot = getHeadlessVisibleBufferSnapshot(
      tabId,
      'claude-trust-folder:preflight',
      { preferCommitted: false },
    );
    let inspection = inspectClaudeTrustFolderPromptSnapshot(snapshot);
    if (inspection.visible !== true) {
      return { success: true, handled: false, reason: inspection.reason };
    }
    if (inspection.selectedOption === null) {
      return {
        success: true,
        handled: false,
        reason: 'trust_folder_selection_unproven',
      };
    }

    const ownedInputRevision = bumpTerminalInputRevision(tabId);
    if (!stillOwns(ownedInputRevision)) {
      return { success: false, handled: false, error: 'trust_folder_identity_changed' };
    }
    if (inspection.selectedOption === 2) {
      const selectKey = getClaudeTrustFolderSelectionKey(snapshot);
      if (!selectKey) return {
        success: false, handled: false, submitted: false,
        error: 'trust_folder_option_order_unproven',
      };
      operation.phase = 'select-trust-folder';
      console.log('[ClaudeTrustFolder] selecting semantic Yes tab=' + String(tabId).slice(-12)
        + ' direction=' + (selectKey === '\x1b[A' ? 'up' : 'down'));
      const moved = await waitForCommittedSemanticFrame({
        subscribe(listener) {
          expectedMirror.synchronizedFrameWaiters.add(listener);
          return () => expectedMirror.synchronizedFrameWaiters.delete(listener);
        },
        readSnapshot() {
          return getHeadlessVisibleBufferSnapshot(tabId, 'claude-trust-folder:select', { preferCommitted: false });
        },
        inspectSnapshot: inspectClaudeTrustFolderPromptSnapshot,
        acceptInspection: next => next.visible === true && next.selectedOption === 1,
        trigger() {
          if (!stillOwns(ownedInputRevision)) throw new Error('trust_folder_identity_changed');
          // A redraw or a user's intervening keystroke must not launch a second
          // automatic selection after this owned attempt has already written.
          claudeTrustFolderPromptFired.set(tabId, {
            generation: expectedLaunchGeneration,
            lifecycleGeneration: expectedLifecycleGeneration,
            phase: 'select-trust-folder', at: Date.now(),
          });
          recordComposerForensicPtyInput(tabId, selectKey, {
            kind: 'programmatic-control', phase: 'pty-write-attempt',
            origin: 'claude-trust-folder', source: 'claude-trust-folder-select',
            operationKind: 'claude-trust-folder-prompt', checkpoint: true,
          });
          expectedTerm.write(selectKey);
        },
        getAbortReason() {
          if (!stillOwns(ownedInputRevision)) return 'trust_folder_identity_changed';
          if (expectedMirror.failed === true) return 'trust_folder_mirror_failed';
          return null;
        },
        afterWriteSeq: Number(snapshot?.writeSeq || 0),
        timeoutMs: 2500,
      });
      if (!moved.ready) return {
        success: false, handled: true, submitted: false,
        error: moved.reason || 'trust_folder_yes_selection_unproven',
      };
      snapshot = moved.snapshot;
      inspection = moved.inspection;
    }
    // More than one redraw may have committed before the selection waiter
    // resumed. Confirm the current frame, not an earlier observed Yes.
    snapshot = getHeadlessVisibleBufferSnapshot(tabId, 'claude-trust-folder:before-enter', { preferCommitted: false });
    inspection = inspectClaudeTrustFolderPromptSnapshot(snapshot);
    if (snapshot?.authoritativeFrameCommitted !== true
      || snapshot?.liveSynchronizedOutputOpen === true
      || Number(snapshot?.flushedSeq) !== Number(snapshot?.writeSeq)
      || inspection.visible !== true
      || inspection.selectedOption !== 1 || !stillOwns(ownedInputRevision)) return {
      success: false, handled: true, submitted: false,
      error: 'trust_folder_yes_selection_unproven',
    };
    const afterWriteSeq = Number(snapshot?.writeSeq || 0);
    operation.phase = 'confirm-trust-folder';
    console.log('[ClaudeTrustFolder] Yes proven; writing one Enter tab='
      + String(tabId).slice(-12));
    const dismissed = await waitForCommittedSemanticFrame({
      subscribe(listener) {
        expectedMirror.synchronizedFrameWaiters.add(listener);
        return () => expectedMirror.synchronizedFrameWaiters.delete(listener);
      },
      readSnapshot() {
        return getHeadlessVisibleBufferSnapshot(
          tabId,
          'claude-trust-folder:confirm',
          { preferCommitted: false },
        );
      },
      inspectSnapshot: inspectClaudeTrustFolderPromptSnapshot,
      acceptInspection: (next) => next.visible !== true,
      trigger() {
        if (!stillOwns(ownedInputRevision)) {
          throw new Error('trust_folder_identity_changed');
        }
        claudeTrustFolderPromptFired.set(tabId, {
          generation: expectedLaunchGeneration,
          lifecycleGeneration: expectedLifecycleGeneration,
          at: Date.now(),
        });
        recordComposerForensicPtyInput(tabId, '\r', {
          kind: 'programmatic-enter',
          phase: 'pty-write-attempt',
          origin: 'claude-trust-folder',
          source: 'claude-trust-folder-confirm',
          operationKind: 'claude-trust-folder-prompt',
          checkpoint: true,
        });
        try {
          expectedTerm.write('\r');
        } catch (error) {
          claudeTrustFolderPromptFired.delete(tabId);
          throw error;
        }
      },
      getAbortReason() {
        if (!stillOwns(ownedInputRevision)) return 'trust_folder_identity_changed';
        if (expectedMirror.failed === true) return 'trust_folder_mirror_failed';
        return null;
      },
      afterWriteSeq,
      timeoutMs: 3500,
    });
    operation.submitted = true;
    operation.submittedAt = Date.now();
    if (dismissed.ready === true) {
      claudeTrustFolderPromptHintTabs.delete(tabId);
      claudeTrustFolderPromptHintBuffers.delete(tabId);
    } else {
      console.warn('[ClaudeTrustFolder] Enter written but dismissal not proven tab='
        + String(tabId).slice(-12)
        + ' reason=' + dismissed.reason);
    }
    return {
      success: true,
      handled: true,
      submitted: true,
      dismissed: dismissed.ready === true,
      reason: dismissed.ready === true
        ? 'trust_folder_confirmed'
        : 'trust_folder_enter_written_dismissal_unproven',
    };
  }, operation);
}

function observeClaudeTrustFolderPromptCommittedFrame(
  tabId,
  state,
  snapshot,
  committedFrameGeneration,
) {
  const inspection = inspectClaudeTrustFolderPromptSnapshot(snapshot);
  const launchGeneration = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const fired = claudeTrustFolderPromptFired.get(tabId) || null;
  if (fired && (
    fired.generation !== launchGeneration
    || fired.lifecycleGeneration !== lifecycleGeneration
  )) {
    claudeTrustFolderPromptFired.delete(tabId);
  }

  if (inspection.visible !== true) {
    if (claudeTrustFolderPromptHintTabs.has(tabId)) {
      const visibleText = Array.isArray(snapshot?.lines)
        ? snapshot.lines.map((line) => line?.text || '').join('\n')
        : '';
      const competingControlSurface = (
        looksLikeClaudeTrustFolderPromptText(visibleText)
        || looksLikeClaudeAutoModeDefaultPromptText(visibleText)
        || claudeCtrlCDangerZone.has(tabId)
        || looksLikeClaudeRewindMenuText(visibleText)
        || classifyClaudeSettingsDialogText(visibleText) !== null
      );
      const composer = competingControlSurface
        ? null
        : parseClaudeComposerCurrentFrame(snapshot);
      if (composer
        && (composer.proofOutcome === 'found' || composer.proofOutcome === 'absent')) {
        claudeTrustFolderPromptHintTabs.delete(tabId);
        claudeTrustFolderPromptHintBuffers.delete(tabId);
        console.log('[ClaudeTrustFolder] hint disproven by current composer tab='
          + String(tabId).slice(-12)
          + ' frame=' + committedFrameGeneration);
        publishClaudePromptReady(tabId, 'trust folder dismissed');
      }
    }
    return null;
  }

  claudeTrustFolderPromptHintTabs.add(tabId);
  if (claudePromptReady.delete(tabId) && launchGeneration) {
    claudePromptStability.markActivity(
      tabId,
      launchGeneration,
      'trust-folder-prompt:' + committedFrameGeneration,
    );
    console.warn('[ClaudeTrustFolder] revoked false composer readiness tab='
      + String(tabId).slice(-12)
      + ' frame=' + committedFrameGeneration);
  }
  if (!launchGeneration || inspection.selectedOption === null) return inspection;
  if (fired
    && fired.generation === launchGeneration
    && fired.lifecycleGeneration === lifecycleGeneration) return inspection;
  if (claudeTrustFolderPromptInflight.has(tabId)) return inspection;

  const expectedTerm = terminals.get(tabId) || null;
  if (!expectedTerm || getHeadlessTerminalMirror(tabId) !== state) return null;
  const token = {
    tabId,
    expectedTerm,
    expectedMirror: state,
    expectedLaunchGeneration: launchGeneration,
    expectedRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    expectedLifecycleGeneration: lifecycleGeneration,
    expectedInputRevision: getTerminalInputRevision(tabId),
  };
  const pending = Promise.resolve()
    .then(() => handleClaudeTrustFolderPrompt(token))
    .then((result) => {
      console.log('[ClaudeTrustFolder] handled tab=' + String(tabId).slice(-12)
        + ' frame=' + committedFrameGeneration
        + ' success=' + (result?.success === true)
        + ' submitted=' + (result?.submitted === true)
        + ' reason=' + String(result?.reason || result?.error || '-'));
      return result;
    })
    .catch((error) => {
      console.warn('[ClaudeTrustFolder] handler failed tab=' + String(tabId).slice(-12)
        + ' frame=' + committedFrameGeneration
        + ' error=' + (error?.message || String(error)));
      return { success: false, handled: false, error: error?.message || String(error) };
    })
    .finally(() => {
      if (claudeTrustFolderPromptInflight.get(tabId) === pending) {
        claudeTrustFolderPromptInflight.delete(tabId);
      }
    });
  claudeTrustFolderPromptInflight.set(tabId, pending);
  return inspection;
}

function clearClaudeConfirmDialogCooldown(tabId) {
  for (const key of claudeConfirmDialogCooldown.keys()) {
    if (key.startsWith(tabId + ':')) claudeConfirmDialogCooldown.delete(key);
  }
}

function classifyClaudeSettingsDialogText(text) {
  const normalized = String(text || '').replace(/\u00a0/g, ' ');
  if (!normalized.trim()) return null;
  const compact = normalized.replace(/\s+/g, '');
  if (/Changeeffortlevel\?/i.test(compact)) return 'EffortDialog';
  if (/Switchmodel\?/i.test(compact)) return 'ModelDialog';
  if (/(?:❯|>)1\.Yes,?switchto/i.test(compact)) return 'ModelDialog';
  return null;
}

function classifyClaudeSettingsDialogSnapshot(snapshot) {
  if (snapshot?.success !== true || !Array.isArray(snapshot.lines)) return null;
  return classifyClaudeSettingsDialogText(
    snapshot.lines.map((line) => String(line?.text || '')).join('\n'),
  );
}

async function confirmClaudeSettingsDialogFromCurrentFrame(
  tabId,
  expectedDialogType = null,
  reason = 'settings-dialog',
) {
  const expectedTerm = terminals.get(tabId);
  if (!expectedTerm) return { success: false, confirmed: false, error: 'no_terminal' };
  const inputRevision = getTerminalInputRevision(tabId);

  const flush = await flushHeadlessTerminalMirror(tabId);
  if (!flush.success) {
    return {
      success: false,
      confirmed: false,
      error: flush.error || 'headless_flush_failed',
    };
  }
  if (
    terminals.get(tabId) !== expectedTerm
    || getTerminalInputRevision(tabId) !== inputRevision
  ) {
    return {
      success: false,
      confirmed: false,
      error: 'terminal_generation_changed',
    };
  }

  const snapshot = getHeadlessVisibleBufferSnapshot(tabId, reason);
  const dialogType = classifyClaudeSettingsDialogSnapshot(snapshot);
  if (!dialogType) {
    return {
      success: true,
      confirmed: false,
      reason: 'dialog_not_visible',
      writeSeq: snapshot?.writeSeq ?? null,
    };
  }
  if (expectedDialogType && dialogType !== expectedDialogType) {
    return {
      success: true,
      confirmed: false,
      reason: 'different_dialog_visible',
      dialogType,
      expectedDialogType,
    };
  }

  const now = Date.now();
  const cooldownKey = tabId + ':' + dialogType;
  const lastFire = claudeConfirmDialogCooldown.get(cooldownKey) || 0;
  if (now - lastFire <= 2000) {
    return {
      success: true,
      confirmed: true,
      alreadyScheduled: true,
      dialogType,
    };
  }

  // Re-check the exact PTY/input generation at the write boundary. A delayed
  // detector must never submit whatever the user typed after the dialog frame
  // was observed.
  if (
    terminals.get(tabId) !== expectedTerm
    || getTerminalInputRevision(tabId) !== inputRevision
  ) {
    return {
      success: false,
      confirmed: false,
      error: 'terminal_generation_changed',
    };
  }

  observeClaudeSettingsDialogWrite({
    snapshot, dialogType,
    operation: ptyActiveWriteOperation.get(expectedTerm) || null,
    capture: detail => reportTerminalIncident(
      'settings-dialog:' + tabId + ':' + snapshot?.generation + ':' + snapshot?.writeSeq + ':' + inputRevision,
      { tabId, toolType: 'claude', incidentReason: 'claude-settings-dialog-observation',
        context: { ...detail, source: reason, inputRevision } },
    ),
  });
  claudeConfirmDialogCooldown.set(cooldownKey, now);
  bumpTerminalInputRevision(tabId);
  console.log('[' + dialogType + '] Tab ' + tabId
    + ': current-frame proof confirmed, writing Enter reason=' + reason);
  expectedTerm.write('\r');
  return {
    success: true,
    confirmed: true,
    alreadyScheduled: false,
    dialogType,
  };
}
const claudeCliActive = new Map();          // claudeTabId -> true (Claude CLI is running inside PTY, not just shell)
// "Claude TUI has rendered its prompt at least once" — deterministic ready
// signal. Set on first ⏵/> detection in PTY output for a tab, cleared on
// terminal:kill / PTY exit / explicit clearBridgeTab. Mobile-web composer
// uses this to gate Send: while the flag is false the chat shows a "starting
// Claude..." loader instead of an active input. See fact-claude-tui-mechanics.md
// section 2 (Ink debounce + drain semantics) for why the prompt char is the
// right cut-off — it's the same signal Claude Handshake uses internally to
// decide it can write the next prompt.
const claudePromptReady = new Set();        // tabIds whose Claude TUI is ready for input
const ppidToGeminiTab = new Map();          // Bug 3 fix: cache ppid -> geminiTabId (stable within MCP server lifetime)
let mcpHttpServer = null;               // http.Server instance
let mcpHttpPort = null;                 // assigned port number
const geminiCommandQueue = new Map();   // tabId -> Promise (serialized Gemini commands)

// ========== CLAUDE BUSY DETECTION (Content Spinner) ==========
// Color-independent. Detects spinner chars ✢✳✶✻✽ in TUI CONTENT (not window title).
// · (middle dot) excluded — it's the status bar separator, not a spinner.
// Diagnostic busy: spinner char found in content → instant.
// Diagnostic idle: no spinner char in content for 500ms → debounce.
// OSC sequences (title) are stripped before checking to avoid false positives
// from Claude's static branding title "✳ Claude Code".
// This map is deliberately NOT a public turn/loader source. Exact hooks and
// explicit local commands own lifecycle; the glyph remains useful for draft
// guards, watchdog diagnostics, and log evidence.
const claudeSpinnerBusy = new Map();       // tabId → boolean
const claudeSpinnerIdleTimer = new Map();  // tabId → timeout ID
const claudeSpinnerLastSeenAt = new Map(); // tabId → ms timestamp of last visible TUI spinner frame
const OSC_RE = /\x1b\][^\x07]*\x07/g;     // matches all OSC sequences (title, etc)
const CONTENT_SPINNER_RE = /[\u2722\u2733\u2736\u273B\u273D]/; // ✢✳✶✻✽ (no · !)

// ========== GEMINI SPINNER DETECTION (Braille busy indicator) ==========
// Detects Gemini CLI Braille spinner chars (⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏) + "esc to cancel" text.
// Emits gemini:busy-state IPC and logs [GeminiSpinner] for E2E test observability.
const geminiSpinnerBusy = new Map();       // tabId → boolean
const geminiSpinnerIdleTimers = new Map(); // tabId → timeout ID (debounce idle transition)
const GEMINI_SPINNER_RE = /[\u280B\u2819\u2839\u2838\u283C\u2834\u2826\u2827\u2807\u280F]/;
const geminiActiveTabs = new Set();        // tabs with active Gemini process (for spinner detection)

// ========== AGENT ACTIVITY TRACKING (loader-on intervals) ==========
// Records how long an agent (Claude PTY / Claude SDK / Gemini) is actively
// working in a tab \u2014 defined as "the tab loader is on", i.e. the SAME
// busy-state signal the UI consumes. recordActivity() is the single
// idempotent, edge-triggered chokepoint: open-on-first-true, close-on-
// first-false; redundant calls of the same polarity are no-ops. This lets us
// drop purely-additive recordActivity() calls next to every existing
// busy-state send WITHOUT touching the loader sends themselves.
//
// Only CLOSED intervals are persisted (start+end known) \u2014 a crash mid-interval
// loses that one in-flight span but never corrupts. Identity (project / tab /
// session) is snapshotted at OPEN time, while the tab is still alive, and
// denormalized into the row so it survives later tab/project deletion.
const activityOpenIntervals = new Map();   // tabId \u2192 { startTs, engine, projectId, projectPath, projectName, tabName, sessionId }
// A History/queue send shows the same perimeter loader while bytes are being
// admitted to the PTY, before the authoritative agent busy edge. Preserve that
// earlier edge so the eventual durable response duration covers one unbroken
// visual loader. The safe-paste finally block removes an unconsumed preflight,
// so a rejected submit cannot contaminate the next turn.
const responseActivityPreflights = new Map(); // tabId -> { startTs, engine, source }
let projectActivityBroadcastTimer = null;
const projectLayoutChangedIds = new Set();
let projectOrderChanged = false;

// Resolve a denormalized identity snapshot for a tab at this instant. Works for
// PTY tabs (terminalProjectIds live map \u2192 SQLite fallback) and SDK tabs
// (sdkSessions). Best-effort: any missing field is left null, the interval is
// still worth recording for total-time aggregation.
function resolveActivityIdentity(tabId, engine) {
  const out = {
    engine: engine || null,
    projectId: null, projectPath: null, projectName: null,
    tabName: null, sessionId: null,
  };
  try {
    let projectId = terminalProjectIds.get(tabId) || null;
    let row = null;
    if (projectManager?.db?.db) {
      try {
        row = projectManager.db.db.prepare(
          'SELECT project_id, name, claude_session_id, gemini_session_id, codex_session_id FROM tabs WHERE tab_id = ? LIMIT 1'
        ).get(tabId);
      } catch {}
    }
    if (!projectId && row) projectId = row.project_id || null;
    out.projectId = projectId;
    if (row) {
      out.tabName = row.name || null;
    }
    // SDK tabs aren't in terminalProjectIds; pull cwd/session from sdkSessions.
    const sdk = sdkSessions.get(tabId);
    out.sessionId = resolveActivitySessionIdForEngine(engine, {
      bridgeSessionId: bridgeKnownSessions.get(tabId) || null,
      codexRuntimeSessionId: codexKnownSessions.get(tabId) || null,
      claudeSessionId: row?.claude_session_id || null,
      geminiSessionId: row?.gemini_session_id || null,
      codexSessionId: row?.codex_session_id || null,
      sdkSessionId: sdk?.sessionId || null,
    });
    if (sdk) {
      if (!out.projectPath) out.projectPath = sdk.cwd || null;
    }
    if (projectId && projectManager?.db?.db) {
      // Direct one-row lookup — getProjectById() also hydrates all tabs +
      // global commands, far more than the name/path we need per turn-start.
      try {
        const proj = projectManager.db.db.prepare(
          'SELECT name, path FROM projects WHERE id = ? LIMIT 1'
        ).get(projectId);
        if (proj) {
          out.projectName = proj.name || null;
          if (!out.projectPath) out.projectPath = proj.path || null;
        }
      } catch {}
    }
    if (!out.projectPath) out.projectPath = terminalProjects.get(tabId) || null;
  } catch (e) {
    console.error('[Activity] identity resolve failed:', e.message);
  }
  return out;
}

// Aggregate "is anything still working" across EVERY tab in EVERY project.
// Single source of truth: reuses the SAME live Maps that drive the per-tab
// loader in the UI — there is no second notion of "busy" invented here.
//   • PTY Claude   → bridgeKnownSessions + terminals + turn/spinner/local-command
//                    busy signals; process-liveness alone is only active/starting
//   • SDK Claude   → sdkSessions (one entry per in-flight query())
//   • Gemini       → geminiSpinnerBusy
//   • Codex        → rollout watcher task_started/task_complete busy
//   • restart-after shell command → terminalCommandState.isRunning + command
//                    origin metadata (OSC 133 B/D), excluding AI CLI tabs whose
//                    PTY process is merely alive at prompt
// Consumed by the external `build:i-obs` poller via GET /api/active-loaders so
// a rebuild waits until every Claude / Gemini / SDK / restart-after process across
// the app has gone idle. Runs in main (not via the renderer bridge) so it still
// answers correctly while the renderer is mid-reload or unfocused.
function computeActiveLoaders() {
  const loaders = [];
  const seen = new Set(); // tabId — one tab contributes at most one loader
  const hasRestartAfterSubscription = (row) => {
    if (!row) return false;
    if (row.restart_after_tab_id) return true;
    if (!row.restart_after_tab_ids) return false;
    try {
      const ids = JSON.parse(row.restart_after_tab_ids);
      return Array.isArray(ids) && ids.some((id) => typeof id === 'string' && id.trim());
    } catch {
      return false;
    }
  };

  // tabId → DB row. Reused both for labels and for separating "AI CLI alive"
  // from an ordinary shell command running in a terminal tab.
  const tabRowCache = new Map();
  const tabRowFor = (tabId) => {
    if (tabRowCache.has(tabId)) return tabRowCache.get(tabId);
    let row = null;
    if (projectManager?.db?.db) {
      try {
        row = projectManager.db.db.prepare(
          'SELECT project_id, name, command_type, tab_type, claude_session_id, codex_session_id, gemini_session_id, restart_after_tab_id, restart_after_tab_ids, restart_after_command, restart_after_paused FROM tabs WHERE tab_id = ? LIMIT 1'
        ).get(tabId) || null;
      } catch {}
    }
    tabRowCache.set(tabId, row);
    return row;
  };

  const isAiRuntimeTab = (tabId) => {
    const row = tabRowFor(tabId);
    const commandType = row?.command_type || '';
    const tabType = row?.tab_type || '';
    return (
      commandType === 'claude' ||
      commandType === 'codex' ||
      commandType === 'gemini' ||
      commandType === 'claude-sdk' ||
      tabType === 'claude-sdk' ||
      !!row?.claude_session_id ||
      !!row?.codex_session_id ||
      !!row?.gemini_session_id ||
      bridgeKnownSessions.has(tabId) ||
      codexKnownSessions.has(tabId) ||
      codexTurnWatchers.has(tabId) ||
      claudeTurnBusy.has(tabId) ||
      claudeSpinnerBusy.has(tabId) ||
      claudeLocalCommandWatchers.has(tabId)
    );
  };

  // tabId → { project, name } label, resolved from terminalProjectIds → SQLite
  // tabs row → projects row. Per-call project-name cache keeps it to ~1 query
  // per distinct project even with many tabs.
  const projNameCache = new Map();
  const labelFor = (tabId) => {
    let projectId = terminalProjectIds.get(tabId) || null;
    let tabName = null;
    const row = tabRowFor(tabId);
    if (row) {
      tabName = row.name || null;
      if (!projectId) projectId = row.project_id || null;
    }
    let projectName = null;
    if (projectId) {
      if (projNameCache.has(projectId)) projectName = projNameCache.get(projectId);
      else {
        try {
          const p = projectManager.db.db.prepare('SELECT name FROM projects WHERE id = ? LIMIT 1').get(projectId);
          projectName = p?.name || null;
        } catch {}
        projNameCache.set(projectId, projectName);
      }
    }
    return {
      project: projectName,
      name: tabName || ('tab ' + String(tabId).slice(-6)),
      cwd: terminalProjects.get(tabId) || null,
      commandType: row?.command_type || null,
    };
  };

  // Preparation is a real launch phase before the shell command exists.  It
  // blocks Build Install for the same reason as the later startup loader: a
  // restart here would cut transcript validation or lose the accepted launch.
  for (const state of agentLaunchPreparations.list()) {
    const tabId = state.tabId;
    if (seen.has(tabId)) continue;
    loaders.push({
      tabId,
      kind: state.toolType || 'agent',
      status: 'preparing',
      phase: state.phase || null,
      ...labelFor(tabId),
    });
    seen.add(tabId);
  }

  for (const [tabId, state] of aiStoppingTabs) {
    if (seen.has(tabId)) continue;
    loaders.push({ tabId, kind: state.toolType || 'agent', status: 'stopping', ...labelFor(tabId) });
    seen.add(tabId);
  }

  // 1) PTY Claude. bridgeKnownSessions = "CLI alive in this tab" (persists until
  //    terminal killed). Skip if the PTY is already gone — that mirrors
  //    get-presence returning 'inactive' (no loader) for a stale bridge entry.
  //    Do NOT treat claudeCliActive as busy: it is process liveness, true while
  //    Claude is idle at the prompt. /api/active-loaders is a blocker list, not
  //    a presence list, so idle-alive Claude must not be returned at all.
  for (const tabId of bridgeKnownSessions.keys()) {
    if (!terminals.has(tabId)) continue; // PTY dead → not blocking (= 'inactive')
    if (seen.has(tabId)) continue;
    const compactOperation = compactOperations.getActive(tabId, 'claude');
    const isBusy = !!claudeTurnBusy.get(tabId)
      || claudeLocalCommandWatchers.has(tabId)
      || !!compactOperation;
    if (!isBusy) continue;
    loaders.push({
      tabId,
      kind: 'claude',
      status: 'busy',
      phase: compactOperation?.phase || null,
      operation: compactOperation?.kind || null,
      ...labelFor(tabId),
    });
    seen.add(tabId);
  }

  // 2) SDK Claude — every live query() is an in-flight turn.
  for (const tabId of sdkSessions.keys()) {
    if (seen.has(tabId)) continue;
    loaders.push({ tabId, kind: 'claude-sdk', status: 'busy', ...labelFor(tabId) });
    seen.add(tabId);
  }

  // 3) Gemini thinking/streaming.
  for (const [tabId, busy] of geminiSpinnerBusy) {
    if (!busy || seen.has(tabId)) continue;
    loaders.push({ tabId, kind: 'gemini', status: 'busy', ...labelFor(tabId) });
    seen.add(tabId);
  }

  // 4) Codex turn watcher. Codex CLI stays alive while idle, so process liveness
  //    is not enough; only rollout task_started→task_complete busy blocks.
  for (const [tabId, state] of codexTurnWatchers) {
    const compactOperation = compactOperations.getActive(tabId, 'codex');
    if (seen.has(tabId) || (state?.busy !== true && !compactOperation)) continue;
    loaders.push({
      tabId,
      kind: 'codex',
      status: 'busy',
      phase: compactOperation?.phase || null,
      operation: compactOperation?.kind || null,
      ...labelFor(tabId),
    });
    seen.add(tabId);
  }

  // 5) Restart-after-owned non-AI process. Manual shell commands (`npm run dev`,
  //    `npm run build`, `./deploy.sh`) are not install blockers by themselves:
  //    they are ordinary terminal state. A shell command blocks the rebuild only
  //    when it was launched by Restart after and that subscription is still set on
  //    the tab. AI CLI tabs are excluded here; they block only through deterministic
  //    busy/loader signals above.
  for (const [tabId, st] of terminalCommandState) {
    if (!st?.isRunning || seen.has(tabId)) continue;
    if (isAiRuntimeTab(tabId)) continue;
    if (st.activeCommandSource !== RESTART_AFTER_COMMAND_SOURCE) continue;
    const row = tabRowFor(tabId);
    if (!hasRestartAfterSubscription(row)) continue;
    if (row.restart_after_paused === 1) continue;
    const cmd = st.activeCommand || row?.restart_after_command || terminalInitialCommand.get(tabId) || null;
    loaders.push({ tabId, kind: 'restart-after', status: 'running', source: RESTART_AFTER_COMMAND_SOURCE, command: cmd, ...labelFor(tabId) });
    seen.add(tabId);
  }

  const gitOperations = typeof gitIpcModule?.getActiveOperations === 'function'
    ? gitIpcModule.getActiveOperations()
    : [];
  for (const operation of gitOperations) {
    if (!operation?.tabId || seen.has(operation.tabId)) continue;
    loaders.push(operation);
    seen.add(operation.tabId);
  }

  // 7) Outstanding Run after / Loop promises. Everything above answers "is a
  //    turn running right now?"; a queue chain is only finished when nothing is
  //    owed. Between two links nobody runs — the trigger tab has finished and
  //    the owner tab has not started — and that hole is a real state, not a
  //    sampling artifact: measured 1.7s on 2026-08-16, wide enough for the
  //    rebuild to land inside it and Ctrl+C a chain mid-flight. No number of
  //    extra idle confirmations closes it; the promise itself has to be visible.
  //
  //    Read from the persisted snapshot the queue store writes: main keeps no
  //    live copy of the renderer's queues, and a second copy would be one more
  //    thing to drift. A small keyed SELECT + parse, once per poll.
  //
  //    Liveness is "the tab row still exists", NOT "the PTY is alive": an armed
  //    queue legitimately waits on a stopped tab and launches it when its
  //    trigger fires (seen live: `inactive → LAUNCH_FOR_QUEUE start-fresh`).
  //    Only a genuinely closed tab's leftover row must be ignored, or it would
  //    wedge every future rebuild.
  try {
    const queueBlockers = computePromptQueueInstallBlockers({
      persistedQueues: projectManager?.db?.getAppState('promptQueueByTab') || null,
      sharedLoopText: projectManager?.db?.getAppState('promptQueueSharedLoopPrompt') || null,
      tabExists: (tabId) => !!tabRowFor(tabId),
      labelFor,
      seen,
    });
    for (const blocker of queueBlockers) {
      loaders.push(blocker);
      seen.add(blocker.tabId);
    }
  } catch (e) {
    console.warn('[ActiveLoaders] prompt-queue blockers unavailable: ' + (e?.message || String(e)));
    loaders.push(promptQueueReadFailureBlocker(e));
  }

  return { idle: loaders.length === 0, count: loaders.length, loaders, ts: Date.now() };
}

// Tiny project-level aggregate for native iOS project badges. This intentionally
// does NOT read every project's /tabs payload and does NOT include transcript
// state. It mirrors the same runtime maps that drive the desktop/mobile loader:
// count = live agent tabs in a project; streaming = at least one loader-on tab.
function computeProjectActivity() {
  const byProject = new Map(); // projectId -> { projectId, count, streaming }
  const seenTabs = new Set();
  const tabRowCache = new Map();

  const tabRowFor = (tabId) => {
    if (tabRowCache.has(tabId)) return tabRowCache.get(tabId);
    let row = null;
    if (projectManager?.db?.db) {
      try {
        row = projectManager.db.db.prepare(
          'SELECT project_id, command_type, tab_type, claude_session_id, codex_session_id, gemini_session_id FROM tabs WHERE tab_id = ? LIMIT 1'
        ).get(tabId) || null;
      } catch {}
    }
    tabRowCache.set(tabId, row);
    return row;
  };

  const projectIdFor = (tabId, row, hint) => (
    hint ||
    terminalProjectIds.get(tabId) ||
    row?.project_id ||
    null
  );

  const itemForProject = (projectId) => {
    let item = byProject.get(projectId);
    if (!item) {
      item = { projectId, count: 0, streaming: false, notificationCount: 0, tabs: [] };
      byProject.set(projectId, item);
    } else if (typeof item.notificationCount !== 'number') {
      item.notificationCount = 0;
    }
    return item;
  };

  const mark = (tabId, { live = true, busy = false, status = null, projectIdHint = null } = {}) => {
    if (!tabId || !live) return;
    const row = tabRowFor(tabId);
    const projectId = projectIdFor(tabId, row, projectIdHint);
    if (!projectId) return;
    const item = itemForProject(projectId);
    const gate = claudeStartupDefaultsGateByTab.get(tabId) || null;
    const gateBlocksReady = (row?.command_type === 'claude' || row?.tool_type === 'claude' || bridgeKnownSessions.has(tabId) || claudeCliActive.get(tabId) === true)
      && (gate?.status === 'pending' || gate?.status === 'failed');
    const runtimeStatus = status === 'stopping'
      ? 'stopping'
      : (gateBlocksReady ? 'starting' : (busy ? 'busy' : (status || 'active')));
    const lifecycleIdentity = currentAiLifecycleIdentity(tabId, {
      processStatus: live ? 'found' : 'absent',
      sessionId: row?.codex_session_id || row?.claude_session_id || row?.gemini_session_id || null,
    });
    const codexRuntime = row?.command_type === 'codex' || codexKnownSessions.has(tabId) || codexTurnWatchers.has(tabId);
    const claudeRuntime = row?.command_type === 'claude' || bridgeKnownSessions.has(tabId) || claudeCliActive.get(tabId) === true;
    const inputReady = !gateBlocksReady && runtimeStatus !== 'stopping'
      && (busy
        || (codexRuntime && isCodexTuiEffectivelyReady(tabId))
        || (claudeRuntime && claudePromptReady.has(tabId))
        || (!codexRuntime && !claudeRuntime));
    const runtimeFields = {
      inputReady,
      turnBusy: !!busy,
      lifecycleGeneration: lifecycleIdentity.lifecycleGeneration || null,
      sessionId: lifecycleIdentity.sessionId || null,
    };
    const extra = gate ? {
      startupDefaultsPending: gate.status === 'pending',
      startupDefaultsReady: gate.status === 'ready',
      startupDefaultsError: gate.status === 'failed' ? (gate.error || gate.reason || 'startup-defaults-failed') : null,
    } : null;
    if (!seenTabs.has(tabId)) {
      item.count += 1;
      seenTabs.add(tabId);
      item.tabs.push({ tabId, status: runtimeStatus, streaming: gateBlocksReady ? false : !!busy, ...runtimeFields, ...(extra || {}) });
    } else if (busy) {
      const existing = item.tabs.find((t) => t.tabId === tabId);
      if (existing) {
        existing.status = runtimeStatus;
        existing.streaming = gateBlocksReady ? false : true;
        Object.assign(existing, runtimeFields);
        if (extra) Object.assign(existing, extra);
      }
    } else if (extra) {
      const existing = item.tabs.find((t) => t.tabId === tabId);
      if (existing) Object.assign(existing, runtimeFields, extra);
    } else {
      const existing = item.tabs.find((t) => t.tabId === tabId);
      if (existing) Object.assign(existing, runtimeFields);
    }
    if (busy && !gateBlocksReady) item.streaming = true;
  };

  for (const [tabId] of aiStoppingTabs) {
    mark(tabId, {
      live: terminals.has(tabId),
      busy: true,
      status: 'stopping',
    });
  }

  const claudeBusyForTab = (tabId) => (
    claudeTurnBusy.get(tabId) === true ||
    claudeLocalCommandWatchers.has(tabId) ||
    activityOpenIntervals.has(tabId)
  );

  for (const tabId of claudePromptReady) {
    if (claudeCliActive.get(tabId) !== true && !bridgeKnownSessions.has(tabId)) continue;
    mark(tabId, {
      live: terminals.has(tabId),
      busy: claudeBusyForTab(tabId),
      status: 'active',
    });
  }

  for (const tabId of bridgeKnownSessions.keys()) {
    const busy = claudeBusyForTab(tabId);
    mark(tabId, {
      live: terminals.has(tabId),
      busy,
      status: claudePromptReady.has(tabId) ? 'active' : 'starting',
    });
  }

  const now = Date.now();
  for (const [tabId, intent] of claudeStartupIntents) {
    if (!intent || (now - intent.at) >= 45_000) continue;
    mark(tabId, {
      live: terminals.has(tabId),
      busy: claudeBusyForTab(tabId),
      status: claudePromptReady.has(tabId) ? 'active' : 'starting',
    });
  }

  for (const [tabId, active] of claudeCliActive) {
    if (active !== true) continue;
    mark(tabId, {
      live: terminals.has(tabId),
      busy: claudeBusyForTab(tabId),
      status: claudePromptReady.has(tabId) ? 'active' : 'starting',
    });
  }

  for (const tabId of codexKnownSessions.keys()) {
    const state = codexTurnWatchers.get(tabId);
    const busy = state?.busy === true || activityOpenIntervals.has(tabId);
    mark(tabId, {
      live: terminals.has(tabId),
      busy,
      status: isCodexTuiEffectivelyReady(tabId) ? 'active' : 'starting',
    });
  }
  for (const tabId of codexLastRunCommandPayload.keys()) {
    const state = codexTurnWatchers.get(tabId);
    const busy = state?.busy === true || activityOpenIntervals.has(tabId);
    mark(tabId, {
      live: terminals.has(tabId),
      busy,
      status: isCodexTuiEffectivelyReady(tabId) ? 'active' : 'starting',
    });
  }
  for (const [tabId, state] of codexTurnWatchers) {
    const busy = state?.busy === true || activityOpenIntervals.has(tabId);
    mark(tabId, {
      live: terminals.has(tabId),
      busy,
      status: isCodexTuiEffectivelyReady(tabId) ? 'active' : 'starting',
    });
  }
  for (const tabId of codexTuiReadyTabs) {
    const hasCodexRuntime = codexKnownSessions.has(tabId) ||
      codexLastRunCommandPayload.has(tabId) ||
      codexTurnWatchers.has(tabId) ||
      activityOpenIntervals.get(tabId)?.engine === 'codex';
    if (!hasCodexRuntime) continue;
    const state = codexTurnWatchers.get(tabId);
    const busy = state?.busy === true || activityOpenIntervals.has(tabId);
    mark(tabId, {
      live: terminals.has(tabId),
      busy,
      status: isCodexTuiEffectivelyReady(tabId) ? 'active' : 'starting',
    });
  }

  for (const tabId of geminiActiveTabs) {
    mark(tabId, {
      live: terminals.has(tabId),
      busy: geminiSpinnerBusy.get(tabId) === true || activityOpenIntervals.has(tabId),
    });
  }
  for (const [tabId, busy] of geminiSpinnerBusy) {
    mark(tabId, {
      live: terminals.has(tabId),
      busy: busy === true || activityOpenIntervals.has(tabId),
    });
  }

  // SDK sessions are in-flight query() calls: live == busy.
  for (const tabId of sdkSessions.keys()) {
    mark(tabId, { live: true, busy: true });
  }

  // Safety net for any loader-on interval whose engine edge fired before the
  // corresponding liveness map was observable here. recordActivity stores the
  // project identity at open-time, so this can still set streaming without a
  // heavy renderer bridge call.
  for (const [tabId, open] of activityOpenIntervals) {
    mark(tabId, { live: true, busy: true, projectIdHint: open?.projectId || null });
  }

  for (const [tabId, note] of tabCompletionNotifications) {
    const row = tabRowFor(tabId);
    const projectId = projectIdFor(tabId, row, note?.projectId || null);
    if (!projectId) continue;
    const item = itemForProject(projectId);
    item.notificationCount += 1;
    const existing = item.tabs.find((t) => t.tabId === tabId);
    const payload = {
      completionNotificationFired: true,
      completionNotificationFiredAt: note?.firedAt || null,
      completionNotificationMode: note?.persistent ? 'persistent' : 'oneshot',
      name: note?.tabName || null,
    };
    if (existing) {
      Object.assign(existing, payload);
    } else {
      item.tabs.push({
        tabId,
        status: 'completed',
        streaming: false,
        ...payload,
      });
    }
  }

  return {
    projects: Array.from(byProject.values())
      .filter((p) => p.count > 0 || p.streaming || p.notificationCount > 0)
      .sort((a, b) => String(a.projectId).localeCompare(String(b.projectId))),
    layoutChangedProjectIds: Array.from(projectLayoutChangedIds),
    projectOrderChanged,
    ts: Date.now(),
  };
}

function scheduleProjectActivityBroadcast(reason = 'event') {
  if (projectActivityBroadcastTimer) return;
  projectActivityBroadcastTimer = setTimeout(() => {
    projectActivityBroadcastTimer = null;
    try {
      require(path.join(srcMainDir, 'web-server')).broadcastProjectActivity(reason);
    } catch {}
    projectLayoutChangedIds.clear();
    projectOrderChanged = false;
  }, 80);
}

ipcMain.on('agent:tui-ready-internal', (_event, payload = {}) => {
  const toolType = payload?.toolType || 'agent';
  scheduleProjectActivityBroadcast(toolType + '-ready');
  if (toolType === 'codex' && payload?.tabId) {
    void scheduleCodexModelEffortIntentReconcile(payload.tabId, 'tui-ready');
  }
});

ipcMain.on('agent:readiness-changed-internal', (_event, payload = {}) => {
  // Closing an established /model picker is not another process startup.
  // Pending choices must resume on the shared ready edge, even with no
  // ControlBar mounted and no new status query from a tab switch.
  if (payload?.toolType === 'codex' && payload?.tabId && payload?.status === 'ready') {
    void scheduleCodexModelEffortIntentReconcile(payload.tabId, 'input-ready:' + (payload.source || 'event'));
  }
});

// Re-queryable snapshot of the startup gate. The incident showed why an event
// alone is not a contract: the `failed` event arrived 549ms AFTER the user had
// switched tabs, TerminalArea's active-tab guard dropped it, and nothing ever
// re-read the state — the user came back to a generic "starting" with no
// reason. The data was alive in both the renderer map and this mirror; there
// was simply no way to ask for it. Presentation now reads this on mount /
// tab-switch / view-change and treats the event as an optimization.
ipcMain.handle('claude:get-startup-defaults-gate', (_event, payload = {}) => {
  const tabId = String(payload?.tabId || '');
  if (!tabId) return { success: false, error: 'tabId required', gate: null };
  const gate = claudeStartupDefaultsGateByTab.get(tabId) || null;
  return { success: true, tabId, gate: gate ? { ...gate } : null };
});

ipcMain.handle('claude:retry-startup-defaults', (_event, payload = {}) => {
  const tabId = String(payload?.tabId || '');
  if (!tabId) return { success: false, accepted: false, error: 'tabId required' };
  const retry = claudeStartupMainRuntime.retry(tabId);
  return {
    success: retry.started === true || retry.joined === true,
    accepted: retry.started === true || retry.joined === true,
    reason: retry.reason || null,
    generation: claudeLaunchGenerationByTab.get(tabId)?.generation || null,
  };
});

ipcMain.handle('claude:set-setting-claim-result', (_event, payload = {}) => {
  const tabId = String(payload?.tabId || '');
  const claimId = Number(payload?.claimId || 0);
  if (!tabId || !Number.isFinite(claimId) || claimId <= 0) {
    return { success: false, settled: false, error: 'invalid_arguments' };
  }
  const settled = claudeStartupMainRuntime.settleManualClaim(
    tabId,
    claimId,
    payload?.success === true,
    String(payload?.reason || 'renderer-proof-result'),
  );
  return { success: true, settled };
});

function emitAgentReadinessChanged(tabId, payload = {}) {
  if (!tabId) return;
  const change = {
    tabId,
    toolType: payload?.toolType || 'claude',
    source: payload?.source || 'startup-defaults',
    status: payload?.status || null,
    reason: payload?.reason || null,
  };
  ipcMain.emit('agent:readiness-changed-internal', null, change);
  // A live /model picker closing is not another process start. Renderer
  // scenarios must wake too, then read current owner/readiness themselves.
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('agent:readiness-changed', change);
  }
}

function publishClaudeStartupDefaultsGate(payload = {}, { notifyRenderer = false } = {}) {
  const tabId = String(payload?.tabId || '');
  if (!tabId) return;
  if (notifyRenderer && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('claude:startup-defaults-gate-state', {
      ...payload,
      tabId,
    });
  }
  if (payload?.status === 'cleared') {
    const reason = 'startup-defaults-cleared';
    claudeStartupDefaultsGateByTab.delete(tabId);
    console.log('[ClaudeStartupDefaultsGate] tab=' + String(tabId).slice(-12)
      + ' status=cleared session=nil reason=' + String(payload?.reason || '-')
      + ' code=-'
      + ' error=-');
    try {
      const persisted = projectManager?.db?.db?.prepare(
        'SELECT project_id FROM tabs WHERE tab_id = ? LIMIT 1'
      ).get(tabId) || null;
      if (persisted?.project_id) scheduleProjectLayoutBroadcast(persisted.project_id, reason);
      else scheduleProjectActivityBroadcast(reason);
    } catch {
      scheduleProjectActivityBroadcast(reason);
    }
    emitAgentReadinessChanged(tabId, {
      status: 'cleared',
      reason: payload?.reason || reason,
    });
    return;
  }
  const status = payload?.status === 'ready'
    ? 'ready'
    : (payload?.status === 'failed' ? 'failed' : 'pending');
  claudeStartupDefaultsGateByTab.set(tabId, {
    status,
    generation: payload?.generation ? String(payload.generation) : null,
    reason: String(payload?.reason || ''),
    error: payload?.error ? String(payload.error) : null,
    errorCode: payload?.errorCode ? String(payload.errorCode) : null,
    // Which command failed and whether the user may retry it. The generic
    // "terminal input did not become ready" subtitle contradicted the real
    // cause in the incident; the card must be able to name `/effort max`.
    failedCommand: payload?.failedCommand ? String(payload.failedCommand) : null,
    proofOutcome: payload?.proofOutcome ? String(payload.proofOutcome) : null,
    userRetryable: payload?.userRetryable === true,
    at: Date.now(),
  });
  if (status === 'ready' && payload?.generation) {
    const readyGeneration = String(payload.generation);
    consumeClaudeStartupIntent(tabId, readyGeneration);
    void flushClaudePendingPromptAfterStartup(
      tabId,
      readyGeneration,
      'startup-defaults-ready',
    );
  }
  const sessionId = bridgeKnownSessions.get(tabId) || null;
  const snapshotStatus = status === 'ready' ? 'active' : 'starting';
  const reason = 'startup-defaults-' + status;
  console.log('[ClaudeStartupDefaultsGate] tab=' + String(tabId).slice(-12)
    + ' status=' + status
    + ' session=' + (sessionId ? String(sessionId).slice(0, 8) : 'nil')
    + ' reason=' + String(payload?.reason || '-')
    + ' code=' + String(payload?.errorCode || '-')
    + ' error=' + String(payload?.error || '-'));
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId,
    busy: false,
    sessionStatus: snapshotStatus,
    starting: snapshotStatus === 'starting',
    stopping: false,
    inputReady: status === 'ready',
    toolType: 'claude',
    commandType: 'claude',
    startupDefaultsPending: status === 'pending',
    startupDefaultsReady: status === 'ready',
    startupDefaultsError: status === 'failed' ? String(payload?.error || payload?.reason || 'startup-defaults-failed') : null,
    startupDefaultsErrorCode: status === 'failed' ? String(payload?.errorCode || '') || null : null,
    reason,
  });
  try {
    const persisted = projectManager?.db?.db?.prepare(
      'SELECT project_id FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId) || null;
    if (persisted?.project_id) scheduleProjectLayoutBroadcast(persisted.project_id, reason);
    else scheduleProjectActivityBroadcast(reason);
  } catch {
    scheduleProjectActivityBroadcast(reason);
  }
  // `tui-ready` is only the first readiness input for Claude. The Project API
  // and Terminal MCP may already be waiting when the startup transaction later
  // flips pending → ready/failed, so this post-TUI transition needs its own
  // internal wake-up edge. A renderer IPC event cannot be the owner of that
  // contract because main now runs the transaction even with a cold renderer.
  emitAgentReadinessChanged(tabId, {
    status,
    reason: payload?.reason || reason,
  });
}

async function readMainAgentStartReadiness(tabId, toolType) {
  if (toolType === 'claude') {
    const gate = claudeStartupDefaultsGateByTab.get(tabId) || null;
    const generation = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
    const currentGate = gate?.generation === generation ? gate : null;
    const promptReady = !!generation && claudePromptReady.has(tabId);
    const defaultsReady = currentGate?.status === 'ready';
    const defaultsError = currentGate?.status === 'failed'
      ? String(gate.error || gate.reason || 'Claude startup defaults failed')
      : null;
    const defaultsErrorCode = currentGate?.status === 'failed'
      ? String(gate.errorCode || '') || null
      : null;
    const runtimePresence = getClaudePtyRuntimePresence(tabId);
    const inputReady = runtimePresence.inputReady === true
      || (promptReady && defaultsReady);
    return {
      tabId,
      toolType: 'claude',
      commandType: 'claude',
      sessionId: bridgeKnownSessions.get(tabId) || null,
      launchGeneration: generation,
      launchId: generation,
      status: runtimePresence.status,
      liveLifecycle: runtimePresence.status !== 'inactive',
      stopping: runtimePresence.status === 'stopping',
      inputReady: runtimePresence.status !== 'inactive'
        && runtimePresence.status !== 'stopping' && inputReady,
      startupDefaultsPending: currentGate?.status === 'pending',
      startupDefaultsReady: defaultsReady,
      startupDefaultsError: defaultsError,
      startupDefaultsErrorCode: defaultsErrorCode,
      startupFailed: !!defaultsError,
      startupError: defaultsError,
      startupErrorCode: defaultsErrorCode,
    };
  }
  if (toolType === 'codex') {
    const toReadiness = (runtime, tui = {}) => ({
      ...tui,
      ...getCodexPublicWriterFields(tabId),
      ...runtime,
      tabId,
      toolType: 'codex',
      commandType: 'codex',
      sessionId: runtime?.sessionId || getCodexRuntimeSessionId(tabId),
      codexSessionId: runtime?.sessionId || getCodexRuntimeSessionId(tabId),
      status: runtime?.sessionStatus || 'starting',
      inputReady: runtime?.inputReady === true,
    });
    // Resume Goal can enter an exact task_started before Codex ever paints an
    // idle composer frame. That current busy turn is already an operational
    // input surface (new input uses the queue/steering path), so let it settle
    // startup/AutoResume without waiting for the turn to finish.
    let runtime = projectCodexRuntimeSnapshotFromEvents(tabId);
    if (runtime?.inputReady === true) return toReadiness(runtime);
    const tui = await getCodexTuiReadyState(tabId);
    runtime = projectCodexRuntimeSnapshotFromEvents(tabId);
    return toReadiness(runtime, tui);
  }
  return {
    tabId,
    toolType,
    commandType: toolType,
    status: 'active',
    inputReady: true,
  };
}

async function waitForMainAgentStartReady(tabId, toolType, timeoutMs = 60_000, expectedOwner = null) {
  return await waitForAgentReadyTransition({
    tabId,
    timeoutMs,
    expectedOwner,
    eventBus: ipcMain,
    readStatus: () => readMainAgentStartReadiness(tabId, toolType),
    log: (message) => console.log(message.replace('[AgentReadyWait]', '[MCPStartReady]')),
  });
}

ipcMain.handle('agent:wait-start-ready', async (_event, request = {}) => {
  const tabId = String(request?.tabId || '');
  const toolType = request?.toolType === 'claude' || request?.toolType === 'codex'
    ? request.toolType
    : null;
  if (!tabId || !toolType) {
    return { success: false, ready: false, error: 'invalid_agent_ready_wait_request' };
  }
  try {
    const status = await waitForMainAgentStartReady(
      tabId,
      toolType,
      Number(request?.timeoutMs) || 60_000,
      request?.expectedOwner || null,
    );
    return { success: true, ready: status?.inputReady === true, status };
  } catch (error) {
    if (error?.code === 'agent_ready_timeout') {
      void reportTerminalIncident('startup:' + tabId + ':' + getTerminalLifecycleGeneration(tabId), {
        tabId, toolType, incidentReason: 'startup-ready-timeout',
        context: { error: error.code, detail: error.message, status: error.status || null,
          expectedOwner: request.expectedOwner || null },
      });
    }
    return {
      success: false,
      ready: false,
      error: error?.code || 'agent_ready_wait_failed',
      detail: error?.message || String(error),
      status: error?.status || null,
    };
  }
});

async function readMainAgentStartReadinessForTab(tabId) {
  const toolType = resolveAiToolTypeForTab(tabId);
  if (!toolType) {
    return {
      tabId,
      toolType: null,
      commandType: null,
      status: 'unknown',
      inputReady: false,
    };
  }
  return await readMainAgentStartReadiness(tabId, toolType);
}

// Legacy renderer writers remain accepted while old dev renderers hot-reload,
// but the live startup transaction publishes this state directly from main.
ipcMain.on('claude:startup-defaults-gate', (_event, payload = {}) => {
  publishClaudeStartupDefaultsGate(payload, { notifyRenderer: false });
});

function scheduleProjectLayoutBroadcast(projectId, reason = 'tab-layout') {
  if (projectId) projectLayoutChangedIds.add(projectId);
  scheduleProjectActivityBroadcast(reason);
}

function scheduleProjectOrderBroadcast(reason = 'project-order') {
  projectOrderChanged = true;
  scheduleProjectActivityBroadcast(reason);
}

function recordActivity(tabId, busy, engine, options = {}) {
  if (!tabId) return;
  const open = activityOpenIntervals.get(tabId);
  if (busy) {
    if (open) {
      if (options.responseTimingEligible === true) {
        open.responseTimingEligible = true;
      }
      return; // already open \u2014 no-op (idempotent)
    }
    const id = resolveActivityIdentity(tabId, engine);
    const preflight = responseActivityPreflights.get(tabId);
    const preflightMatches = preflight && preflight.engine === engine;
    if (preflightMatches) responseActivityPreflights.delete(tabId);
    const next = {
      startTs: preflightMatches ? preflight.startTs : Date.now(),
      responseTimingEligible: options.responseTimingEligible === true,
      ...id,
    };
    activityOpenIntervals.set(tabId, next);
    console.log('[ActivityTiming] open'
      + ' tab=' + String(tabId).slice(-12)
      + ' engine=' + (next.engine || '-')
      + ' session=' + String(next.sessionId || '-').slice(0, 12)
      + ' start=' + next.startTs
      + ' preflight=' + preflightMatches
      + ' reason=' + (options.reason || '-'));
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('agent-activity:timing-changed', {
        tabId,
        busy: true,
        engine: next.engine,
        sessionId: next.sessionId,
        startTs: next.startTs,
      });
    }
    scheduleProjectActivityBroadcast('activity-open');
  } else {
    if (!open) return; // wasn't open \u2014 no-op
    activityOpenIntervals.delete(tabId);
    const endTs = Date.now();
    // Engine may be known only at close-time (e.g. forwarder); prefer the
    // engine captured at open, fall back to the close-time hint.
    if (engine && !open.engine) open.engine = engine;
    const closeIdentity = resolveActivityIdentity(tabId, open.engine || engine);
    let saved = null;
    try {
      saved = projectManager?.db?.saveActivityInterval({
        tabId,
        projectId: open.projectId,
        projectPath: open.projectPath,
        projectName: open.projectName,
        tabName: open.tabName,
        engine: open.engine,
        sessionId: open.sessionId,
        startTs: open.startTs,
        endTs,
      });
      const toolType = normalizeHistoryResponseToolType(open.engine || engine);
      // A close without an explicit completion proof is cleanup, not proof of
      // an answer. This prevents quit/watchdog/process-exit paths from leaving
      // a five-minute "waiting for response row" sidecar.
      const responseTimingEligible = options.responseTimingEligible === true;
      if (saved?.id && toolType && responseTimingEligible) {
        projectManager?.db?.savePendingHistoryResponseTiming({
          intervalId: saved.id,
          toolType,
          tabId,
          sessionId: closeIdentity.sessionId || open.sessionId || null,
        });
      }
      console.log('[ActivityTiming] close'
        + ' tab=' + String(tabId).slice(-12)
        + ' engine=' + (open.engine || engine || '-')
        + ' interval=' + (saved?.id || '-')
        + ' openSession=' + String(open.sessionId || '-').slice(0, 12)
        + ' closeSession=' + String(closeIdentity.sessionId || '-').slice(0, 12)
        + ' response=' + responseTimingEligible
        + ' reason=' + (options.reason || '-'));
    } catch (e) {
      console.error('[Activity] save failed:', e.message);
    }
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('agent-activity:timing-changed', {
        tabId,
        busy: false,
        engine: open.engine || engine || null,
        sessionId: closeIdentity.sessionId || open.sessionId || null,
        intervalId: saved?.id || null,
        startTs: open.startTs,
        endTs,
        durationMs: saved?.durationMs || Math.max(0, endTs - open.startTs),
      });
    }
    scheduleProjectActivityBroadcast('activity-close');
  }
}

ipcMain.handle('agent-activity:get-tab-timing', (_event, payload = {}) => {
  const tabId = String(payload?.tabId || '').trim();
  const requestedToolType = normalizeHistoryResponseToolType(payload?.toolType);
  if (!tabId) return { success: false, error: 'tabId required', timing: null };
  const open = activityOpenIntervals.get(tabId);
  if (open) {
    const toolType = normalizeHistoryResponseToolType(open.engine);
    if (!requestedToolType || requestedToolType === toolType) {
      return {
        success: true,
        timing: {
          state: 'running',
          intervalId: null,
          toolType,
          sessionId: open.sessionId || null,
          startTs: open.startTs,
          endTs: null,
          durationMs: null,
        },
      };
    }
  }
  const pending = projectManager?.db?.getLatestPendingHistoryResponseTimingForTab(
    tabId,
    requestedToolType,
  ) || null;
  // Pending is only the short handoff between loader end and exact JSONL row
  // binding. Keep the durable row for delayed transcript refresh, but never
  // leave a frozen top-bar timer visible for minutes.
  const recentPending = pending && Date.now() - Number(pending.endTs || 0) <= 10 * 1000
    ? pending
    : null;
  return {
    success: true,
    timing: recentPending
      ? { ...recentPending, state: 'pending' }
      : null,
  };
});

// Persist every currently-open interval, truncated at now. Called on app quit
// so in-flight turns aren't lost. Closes each via recordActivity(false) which
// drains activityOpenIntervals as it goes.
function flushOpenActivityIntervals() {
  const openTabs = Array.from(activityOpenIntervals.keys());
  for (const tabId of openTabs) recordActivity(tabId, false);
  if (openTabs.length) console.log('[Activity] flushed ' + openTabs.length + ' open interval(s) on quit');
}

// ========== GEMINI INPUT STATE ==========
// Tracks whether user has text typed in Gemini input field.
// Uses character counter (not boolean) to handle backspace correctly.
const geminiInputCharCount = new Map();    // tabId → number (approximate character count)

// Helper: check if Gemini tab has text in input
function geminiHasInput(tabId) {
  return (geminiInputCharCount.get(tabId) || 0) > 0;
}

// Helper: update char count and notify renderer on state transitions
function updateGeminiCharCount(tabId, newCount, reason) {
  const prev = geminiInputCharCount.get(tabId) || 0;
  const count = Math.max(0, newCount);
  geminiInputCharCount.set(tabId, count);

  const prevHasText = prev > 0;
  const nowHasText = count > 0;

  if (prevHasText !== nowHasText) {
    console.log('[GeminiInput] Tab ' + tabId + ': ' + (nowHasText ? 'Input detected' : 'Input cleared') + ' (' + reason + ', count=' + count + ')');
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('gemini:input-state', { tabId, hasText: nowHasText });
    }
  }
}


// ========== UUID COLORIZATION (purple highlight for MCP Task IDs in terminal) ==========
// Wraps UUID patterns in ANSI purple (RGB 180,130,255) before sending to renderer.
// IMPORTANT: Skips UUIDs inside OSC sequences (e.g. OSC 8 hyperlinks from Claude Code).
// Injecting CSI color codes inside an OSC would abort xterm.js parser → URL leaks as visible text.
const UUID_COLOR_RE = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;
const UUID_COLOR_PREFIX = '\x1b[38;2;180;130;255m';
const UUID_COLOR_SUFFIX = '\x1b[39m';
function colorizeUUIDs(data) {
  // Split data into OSC sequences (pass-through) and regular text (colorize).
  // OSC = \x1b] ... \x07 (or \x1b\\). UUIDs inside OSC URLs must NOT be colorized.
  var result = '';
  var i = 0;
  while (i < data.length) {
    if (data.charCodeAt(i) === 0x1b && i + 1 < data.length && data.charCodeAt(i + 1) === 0x5d) {
      // OSC start — scan for terminator, pass through as-is
      var j = i + 2;
      while (j < data.length) {
        if (data.charCodeAt(j) === 0x07) { j++; break; }
        if (data.charCodeAt(j) === 0x1b && j + 1 < data.length && data.charCodeAt(j + 1) === 0x5c) { j += 2; break; }
        j++;
      }
      result += data.slice(i, j);
      i = j;
    } else {
      // Regular text — find next OSC start or end of data
      var j = i + 1;
      while (j < data.length) {
        if (data.charCodeAt(j) === 0x1b && j + 1 < data.length && data.charCodeAt(j + 1) === 0x5d) break;
        j++;
      }
      result += data.slice(i, j).replace(UUID_COLOR_RE, function(m) {
        return UUID_COLOR_PREFIX + m + UUID_COLOR_SUFFIX;
      });
      i = j;
    }
  }
  return result;
}

// ========== PROMPT BOUNDARY MARKERS (OSC 7777 injection for deterministic navigation) ==========
// State machine per tab: 'idle' (prompt visible) → 'busy' (Claude processing) → 'idle' (inject marker!)
// When BUSY→IDLE transition detected, we inject OSC 7777 into PTY data BEFORE sending to renderer.
// xterm.js parser fires registerOscHandler(7777) → registerMarker(0) at exact buffer position.
const promptBoundaryState = new Map(); // tabId → 'idle' | 'busy'
const promptBoundarySeq = new Map();   // tabId → number (auto-increment sequence)
const escapeCarryover = new Map();     // tabId → string (buffered incomplete escape tail from previous chunk)

function hasClaudePromptGlyph(text) {
  return String(text || '').includes('\u23F5') || // ⏵
    String(text || '').includes('\u276F') ||      // ❯
    String(text || '').includes('\u203A') ||      // ›
    String(text || '').includes('\u2570');        // ╰
}

function hasClaudeComposerPromptGlyph(text) {
  return String(text || '').includes('\u23F5') || // ⏵
    String(text || '').includes('\u2570');        // ╰
}

function hasClaudeAsciiComposerPrompt(text) {
  const clean = stripVTControlCharacters(String(text || ''))
    .replace(/\u00a0/g, ' ');
  const lines = clean
    .split(/[\r\n]+/)
    .map(line => line.trim())
    .filter(Boolean);
  return lines.slice(-8).some(line => /^>\s*(?:$|\S)/.test(line));
}

function looksLikeClaudeRewindMenuText(text) {
  const normalized = stripVTControlCharacters(String(text || ''))
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!normalized) return false;
  return /(Restore\s+and\s+fork|Stay\s+at\s+current\s+position|Enter\s+to\s+continue|Esc\s+to\s+cancel|Rewind\s+conversation|Do\s+nothing)/i.test(normalized)
    && /([●❯›]\s*\S|↑\s*\d+\s*more\s*above|↓\s*\d+\s*more\s*below)/i.test(normalized);
}

function armPromptBoundaryForSubmittedCommand(tabId, reason = 'command-submit') {
  if (!tabId) return;
  promptBoundaryState.set(tabId, 'busy');
  const generation = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
  if (generation) {
    claudePromptStability.markActivity(tabId, generation, 'submitted-command:' + reason);
  }
  console.log('[BoundarySM] Tab ' + String(tabId).slice(-8) + ': forced busy for next prompt reason=' + reason + ' seq=' + (promptBoundarySeq.get(tabId) || 0));
}

// Detect incomplete escape sequence at the end of a PTY data chunk.
// Returns number of bytes to buffer (0 if no incomplete sequence).
// This prevents OSC 7777 injection from splitting a multi-chunk escape sequence.
function detectIncompleteEscapeTail(data) {
  for (let i = data.length - 1; i >= Math.max(0, data.length - 128); i--) {
    if (data.charCodeAt(i) === 0x1b) {
      const tail = data.slice(i);
      if (tail.length === 1) return tail.length; // ESC alone
      const second = tail.charCodeAt(1);
      // CSI: ESC [
      if (second === 0x5b) {
        for (let j = 2; j < tail.length; j++) {
          const ch = tail.charCodeAt(j);
          if (ch >= 0x40 && ch <= 0x7e) return 0; // Final byte found → complete
        }
        return tail.length; // No final byte → incomplete CSI
      }
      // OSC: ESC ]
      if (second === 0x5d) {
        if (tail.includes('\x07') || tail.includes('\x1b\\')) return 0;
        return tail.length; // No terminator → incomplete OSC
      }
      // DCS: ESC P
      if (second === 0x50) {
        if (tail.includes('\x1b\\')) return 0;
        return tail.length;
      }
      // Two-byte escape (ESC + 0x40..0x7E)
      if (second >= 0x40 && second <= 0x7e) return 0;
      return tail.length; // Unknown → buffer for safety
    }
  }
  return 0;
}

// ========== LLM PROVIDER PROXY ==========
// Embedded HTTP proxy that lets Claude Code talk to alternative providers.
// Per-tab routing: each Claude is spawned with
//   ANTHROPIC_BASE_URL=http://127.0.0.1:<PROXY_PORT>/t/<encoded-tabId>
// so the proxy can dispatch each request to that tab's own provider state
// independently of other tabs.
// Modes:
//   "anthropic" — passthrough to api.anthropic.com (subscription auth)
//   "zen"       — passthrough to opencode.ai/zen (Anthropic-compatible, Kimi/MiniMax/GLM)
//   "deepseek"  — api.deepseek.com/anthropic (V4 Flash/Pro), supports thinking + output_config.effort
let PROVIDER_PROXY_PORT = 4001;
let providerProxyReady = false;
// providerStates: tabId → { type, model?, thinking?, effort? }
// 'global' is a fallback bucket for requests that didn't carry a /t/<id> prefix
// (e.g. external Claude started outside spawn-with-watcher).
const providerStates = new Map();
const PROVIDER_DEFAULT = Object.freeze({ type: 'anthropic' });
function getProviderState(tabId) {
  if (!tabId) return providerStates.get('global') || PROVIDER_DEFAULT;
  return providerStates.get(tabId) || providerStates.get('global') || PROVIDER_DEFAULT;
}
function setProviderState(tabId, state) {
  providerStates.set(tabId || 'global', state);
}

const ZEN_API_KEY = process.env.OPENCODE_ZEN_KEY || '';
const DEEPSEEK_API_KEY = process.env.DEEPSEEK_API_KEY || '';

// Keep-alive agents: reuse TCP+TLS connections instead of handshake per request (~200-500ms saving)
const anthropicAgent = new https.Agent({ keepAlive: true, keepAliveMsecs: 60000, maxSockets: 10, maxFreeSockets: 5 });
const zenAgent = new https.Agent({ keepAlive: true, keepAliveMsecs: 60000, maxSockets: 5, maxFreeSockets: 3 });
const deepseekAgent = new https.Agent({ keepAlive: true, keepAliveMsecs: 60000, maxSockets: 5, maxFreeSockets: 3 });
const codexAgent = new https.Agent({ keepAlive: true, keepAliveMsecs: 60000, maxSockets: 10, maxFreeSockets: 5 });
const { WebSocket: ProviderProxyWebSocket, WebSocketServer: ProviderProxyWebSocketServer } = require('ws');
const providerProxyWebSocketServer = new ProviderProxyWebSocketServer({
  noServer: true,
  clientTracking: false,
  perMessageDeflate: false,
  handleProtocols(protocols, request) {
    const upstreamProtocol = request.__providerProxyUpstreamProtocol;
    return upstreamProtocol && protocols.has(upstreamProtocol) ? upstreamProtocol : false;
  },
});
providerProxyWebSocketServer.on('headers', (headers, request) => {
  const upstreamHeaders = request.__providerProxyUpstreamHeaders || {};
  for (const [name, value] of Object.entries(upstreamHeaders)) {
    if (!/^x-(?:codex|openai)-/i.test(name) || value === undefined) continue;
    const values = Array.isArray(value) ? value : [value];
    for (const entry of values) headers.push(name + ': ' + String(entry));
  }
});
providerProxyWebSocketServer.on('error', (error) => {
  console.warn('[ProviderProxy] websocket server error=' + (error?.message || String(error)));
});

// Track active proxy connections for graceful shutdown
const proxyActiveConnections = new Set();
const proxyActiveWebSockets = new Set();
let providerProxyHttpRequestSeq = 0;
let providerProxyWebSocketSeq = 0;

function providerProxyLoadLabel(agent) {
  const load = providerProxyAgentLoad(agent);
  return 'active=' + load.active + ' free=' + load.free + ' queued=' + load.queued;
}

function logProviderProxyHttpLifecycle(tabId, targetPath, event) {
  const details = [
    'event=' + event.event,
    'request=' + event.requestId,
    'tab=' + String(tabId || 'global').slice(-12),
    'path=' + targetPath,
    'elapsedMs=' + event.elapsedMs,
    'active=' + event.load.active,
    'free=' + event.load.free,
    'queued=' + event.load.queued,
  ];
  if (event.statusCode !== undefined && event.statusCode !== null) {
    details.push('status=' + event.statusCode);
  }
  if (event.reason) details.push('reason=' + event.reason);
  if (event.code) details.push('code=' + event.code);
  if (event.reusedSocket !== undefined) details.push('reused=' + (event.reusedSocket ? 1 : 0));
  console.log('[ProviderProxy:HTTP] ' + details.join(' '));
}

const providerProxy = http.createServer((req, res) => {
  // Track connection for graceful shutdown.
  // FIX (2026-04-25): with keep-alive enabled, one TCP socket serves MANY HTTP
  // requests. Previously each request unconditionally added its own
  // `socket.once('close', ...)` listener — after 11 requests on the same socket
  // Node printed `MaxListenersExceededWarning: 11 close listeners added`.
  // Guard: only attach the close listener (and set membership) the FIRST time
  // we see a socket. Subsequent requests on the same keep-alive socket skip both.
  const socket = req.socket;
  if (!proxyActiveConnections.has(socket)) {
    proxyActiveConnections.add(socket);
    socket.once('close', () => proxyActiveConnections.delete(socket));
  }

  // Claude keeps the legacy /t/<tabId> route. Codex uses an explicit provider
  // prefix so the same local server can preserve two different upstream wire
  // protocols without guessing from request bodies.
  const proxyRoute = parseProviderProxyRoute(req.url);
  const proxyProvider = proxyRoute.provider;
  const tabId = proxyRoute.tabId;
  const forwardUrl = proxyRoute.forwardUrl;
  const reqState = getProviderState(tabId);

  const chunks = [];
  req.on('data', (chunk) => chunks.push(chunk));
  req.on('end', () => {
    let body = Buffer.concat(chunks);
    const mode = proxyProvider === 'codex' ? 'codex' : reqState.type;
    const codexHttpRequestId = mode === 'codex'
      ? 'c' + (++providerProxyHttpRequestSeq).toString(36)
      : null;
    let proxyHttpLifecycle = null;
    const targetModel = reqState.model || '';
    const semanticObserver = proxyProvider === 'claude'
      && /\/messages(?:\?|$)/.test(forwardUrl)
      ? safelyObserveProviderSemantic('claude-request-begin', () => providerSemanticShadow.beginClaudeRequest({
          tabId: tabId || 'global',
          headers: req.headers,
          body,
          transport: 'http-sse',
        }))
      : null;
    const codexSemanticConnection = proxyProvider === 'codex'
      && /\/responses(?:\?|$)/.test(forwardUrl)
      ? safelyObserveProviderSemantic('codex-http-connection', () => providerSemanticShadow.createCodexConnection({
          tabId: tabId || 'global',
          transport: 'http-sse',
          sourceId: currentCodexProviderSemanticSourceId(tabId || 'global'),
        }))
      : null;
    semanticObserver?.bindDownstream(res);
    const codexSemanticRequest = codexSemanticConnection
      ? safelyObserveProviderSemantic(
          'codex-http-request',
          () => codexSemanticConnection.observeHttpRequest(body, req.headers),
        )
      : null;

    // Determine target host
    let targetHost, targetPort, targetPath, authHeaders, agent;
    if (mode === 'codex') {
      const upstream = resolveCodexUpstream({ headers: req.headers, forwardUrl });
      targetHost = upstream.hostname;
      targetPort = upstream.port;
      targetPath = upstream.path;
      agent = codexAgent;
      authHeaders = {};
      console.log('[ProviderProxy] Codex[' + (tabId ? tabId.slice(-12) : 'global')
        + '] transport=http upstream=' + (upstream.subscription ? 'subscription' : 'api')
        + ' path=' + targetPath
        + ' request=' + codexHttpRequestId
        + ' ' + providerProxyLoadLabel(codexAgent));
    } else if (mode === 'zen') {
      // OpenCode Zen — Anthropic-compatible, direct passthrough with model rewrite
      targetHost = 'opencode.ai';
      targetPort = 443;
      targetPath = '/zen/go' + forwardUrl;
      agent = zenAgent;
      // Rewrite model name in body
      try {
        const parsed = JSON.parse(body.toString());
        const origModel = parsed.model;
        parsed.model = targetModel;
        body = Buffer.from(JSON.stringify(parsed));
        console.log('[ProviderProxy] Zen: ' + origModel + ' → ' + targetModel + ' msgs=' + (parsed.messages?.length || 0));
      } catch {}
      authHeaders = { 'x-api-key': ZEN_API_KEY };
    } else if (mode === 'deepseek') {
      // DeepSeek — official Anthropic-compatible endpoint at /anthropic/v1/messages.
      // Same Anthropic Messages format; rewrite model name; auth via DEEPSEEK_API_KEY.
      // DeepSeek-specific extensions injected into body (from UI state):
      //   thinking.type: 'enabled' | 'disabled'  (DeepSeek ignores budget_tokens)
      //   output_config.effort: 'low' | 'medium' | 'high'  (controls reasoning depth)
      // DeepSeek ignores cache_control, so SSE message_start cache stats will always be 0 — expected.
      targetHost = 'api.deepseek.com';
      targetPort = 443;
      targetPath = '/anthropic' + forwardUrl;
      agent = deepseekAgent;
      try {
        const parsed = JSON.parse(body.toString());
        const origModel = parsed.model;
        parsed.model = targetModel;
        // DeepSeek API constraint: thinking.type:'disabled' cannot coexist with output_config.effort.
        // Unified UI state: reqState.effort in {'off','low','medium','high'} (default 'medium').
        //   'off' → thinking disabled, no output_config
        //   low/medium/high → thinking enabled + output_config.effort:<level>
        // We deliberately ignore reqState.thinking here — it's redundant for DeepSeek (the effort 'off' value carries that signal).
        const reqEffort = reqState.effort || 'medium';
        let logEffort;
        if (reqEffort === 'off') {
          parsed.thinking = { type: 'disabled' };
          delete parsed.output_config;
          logEffort = 'off';
        } else {
          const lvl = ['low','medium','high'].includes(reqEffort) ? reqEffort : 'medium';
          parsed.thinking = { type: 'enabled' };
          parsed.output_config = { effort: lvl };
          logEffort = lvl;
        }
        body = Buffer.from(JSON.stringify(parsed));
        console.log('[ProviderProxy] DeepSeek[' + (tabId ? tabId.slice(-12) : 'global') + ']: ' + origModel + ' → ' + targetModel + ' msgs=' + (parsed.messages?.length || 0) + ' effort=' + logEffort);
      } catch {}
      authHeaders = { 'x-api-key': DEEPSEEK_API_KEY };
    } else {
      // Anthropic passthrough
      targetHost = 'api.anthropic.com';
      targetPort = 443;
      targetPath = forwardUrl;
      agent = anthropicAgent;
      authHeaders = {};
      // Fast path: skip JSON parse if no thinking blocks to strip (preserves exact body bytes → cache key intact)
      const bodyStr = body.toString();
      if (bodyStr.includes('"thinking"') || bodyStr.includes('"redacted_thinking"')) {
        try {
          const parsed = JSON.parse(bodyStr);
          let cleaned = false;
          if (Array.isArray(parsed.messages)) {
            for (const msg of parsed.messages) {
              if (Array.isArray(msg.content)) {
                const before = msg.content.length;
                msg.content = msg.content.filter(b => b.type !== 'thinking' && b.type !== 'redacted_thinking');
                if (msg.content.length === 0) msg.content = [{ type: 'text', text: '.' }];
                if (msg.content.length !== before) cleaned = true;
              }
            }
          }
          if (cleaned) {
            body = Buffer.from(JSON.stringify(parsed));
            console.log('[ProviderProxy] Anthropic: stripped foreign thinking blocks');
          }
        } catch {}
      }
      console.log('[ProviderProxy] Anthropic[' + (tabId ? tabId.slice(-12) : 'global') + '] passthrough: ' + forwardUrl);
    }

    const fwdHeaders = {
      ...forwardProviderProxyHeaders(req.headers),
      host: targetHost,
      ...authHeaders,
    };
    if (mode === 'zen' || mode === 'deepseek') {
      // Strip Claude OAuth (we authenticate to the third-party provider via x-api-key instead)
      delete fwdHeaders['authorization'];
    }
    // Recalculate content-length for correct body size (may have changed after thinking strip)
    fwdHeaders['content-length'] = Buffer.byteLength(body);

    const proxyReq = https.request({
      hostname: targetHost,
      port: targetPort,
      path: targetPath,
      method: req.method,
      headers: fwdHeaders,
      agent,
    }, (proxyRes) => {
      if (proxyHttpLifecycle
        && !proxyHttpLifecycle.attachUpstreamResponse(proxyRes, proxyRes.statusCode)) {
        return;
      }
      const modeLabel = mode === 'codex'
        ? 'Codex'
        : mode === 'zen'
          ? 'Zen'
          : mode === 'deepseek'
            ? 'DeepSeek'
            : 'Anthropic';
      const responseContentType = String(proxyRes.headers['content-type'] || '').toLowerCase();
      // The ChatGPT Codex HTTPS fallback is a known Responses stream even
      // when its compatibility endpoint does not label the response as
      // text/event-stream. Codex itself still consumes the body as SSE. Gate
      // Claude by Content-Type, but always inspect the already-proven Codex
      // /responses route. This tap is observational; the original bytes keep
      // flowing to the CLI unchanged below.
      const inspectProviderStream = responseContentType.includes('event-stream')
        || !!codexSemanticConnection;
      console.log('[ProviderProxy] ' + modeLabel + ' responded: ' + proxyRes.statusCode
        + (codexHttpRequestId ? ' request=' + codexHttpRequestId : '')
        + ' contentType=' + (responseContentType || '-')
        + ' semanticTap=' + (inspectProviderStream ? '1' : '0'));

      // Mirror the decoded SSE into the shadow semantic observer while the
      // original compressed bytes continue to the CLI unchanged. A broken
      // parser/decompressor can only mark the shadow stream incomplete; it is
      // never allowed to pause or mutate the provider response.
      if (inspectProviderStream) {
        const { PassThrough } = require('stream');
        const zlib = require('zlib');
        const tap = new PassThrough();
        const enc = (proxyRes.headers['content-encoding'] || '').toLowerCase();
        let inspectStream = tap;
        if (enc.includes('br')) inspectStream = tap.pipe(zlib.createBrotliDecompress());
        else if (enc.includes('gzip')) inspectStream = tap.pipe(zlib.createGunzip());
        else if (enc.includes('deflate')) inspectStream = tap.pipe(zlib.createInflate());
        else if (enc.includes('zstd') && typeof zlib.createZstdDecompress === 'function') {
          inspectStream = tap.pipe(zlib.createZstdDecompress());
        }
        let cacheParsed = false;
        let cacheDiagBufLogged = false;
        const sseParser = createSseParser({
          onGap: (reason) => {
            if (semanticObserver) {
              safelyObserveProviderSemantic('claude-sse-gap', () => semanticObserver.markGap(reason));
            }
          },
          onEvent: (sseEvent) => {
            if (semanticObserver) {
              safelyObserveProviderSemantic(
                'claude-sse-event',
                () => semanticObserver.observeSseEvent(sseEvent),
              );
            }
            if (codexSemanticConnection && codexSemanticRequest) {
              safelyObserveProviderSemantic(
                'codex-sse-event',
                () => codexSemanticConnection.observeHttpEvent(codexSemanticRequest, sseEvent),
              );
            }
            if (mode !== 'anthropic' || cacheParsed) return;
            const evt = (() => {
              try { return JSON.parse(sseEvent.data); } catch { return null; }
            })();
            if (evt?.type !== 'message_start' && sseEvent.event !== 'message_start') return;
            cacheParsed = true;
            try {
              const u = evt.message?.usage;
              if (u) {
                const cacheRead = u.cache_read_input_tokens || 0;
                const cacheCreate = u.cache_creation_input_tokens || 0;
                const input = u.input_tokens || 0;
                console.log('[ProviderProxy] Cache: read=' + cacheRead + ' create=' + cacheCreate + ' input=' + input +
                  (cacheRead > 0 ? ' HIT' : cacheCreate > 0 ? ' MISS(new)' : ' NONE'));
                // Forward the cache split to the renderer so ClaudeControlBar can
                // render the cooldown chip. Only anthropic mode reaches here (the
                // `if (mode === 'anthropic')` guard above) — DeepSeek/Zen have no
                // cache, so the chip stays hidden for them by construction. tabId
                // is captured from the /t/<id> URL prefix parsed at request start.
                // ts is the moment this turn touched the cache → cooldown anchor
                // (server 1h TTL refreshes on every use; see fact-provider-proxy.md).
                if (mainWindow && !mainWindow.isDestroyed() && (cacheRead > 0 || cacheCreate > 0)) {
                  mainWindow.webContents.send('claude:cache-update', {
                    tabId: tabId || null,
                    cacheRead, cacheCreate, input,
                    ts: Date.now(),
                  });
                }
              }
            } catch {}
          },
        });
        inspectStream.on('error', (error) => {
          try { tap.unpipe(); } catch {}
          tap.resume();
          if (semanticObserver) {
            safelyObserveProviderSemantic(
              'claude-decode-error',
              () => semanticObserver.markGap(
                'decode-error:' + (error?.code || error?.message || 'unknown'),
              ),
            );
          }
          if (codexSemanticConnection) {
            safelyObserveProviderSemantic(
              'codex-decode-error',
              () => codexSemanticConnection.finishAll('decode-error'),
            );
          }
        });
        inspectStream.on('data', (chunk) => {
          if (!cacheDiagBufLogged) {
            cacheDiagBufLogged = true;
            console.log('[CacheDiag] provider=' + proxyProvider
              + ' enc=' + (enc || 'none')
              + ' firstChunkHead=' + JSON.stringify(chunk.toString().slice(0, 120)));
          }
          safelyObserveProviderSemantic('sse-parser-push', () => sseParser.push(chunk));
        });
        inspectStream.on('end', () => {
          safelyObserveProviderSemantic('sse-parser-end', () => sseParser.end());
          if (semanticObserver) {
            safelyObserveProviderSemantic(
              'claude-response-end',
              () => semanticObserver.finish('response-end'),
            );
          }
          if (codexSemanticConnection) {
            safelyObserveProviderSemantic(
              'codex-response-end',
              () => codexSemanticConnection.finishAll('response-end'),
            );
          }
        });
        res.writeHead(proxyRes.statusCode, proxyRes.headers);
        proxyRes.pipe(tap);
        proxyRes.pipe(res);
      } else {
        proxyRes.once('end', () => {
          if (semanticObserver) {
            safelyObserveProviderSemantic(
              'claude-non-stream-end',
              () => semanticObserver.finish('non-stream-response-end'),
            );
          }
          if (codexSemanticConnection) {
            safelyObserveProviderSemantic(
              'codex-non-stream-end',
              () => codexSemanticConnection.finishAll('non-stream-response-end'),
            );
          }
        });
        res.writeHead(proxyRes.statusCode, proxyRes.headers);
        proxyRes.pipe(res);
      }
    });
    {
      proxyHttpLifecycle = createProviderProxyHttpLifecycle({
        downstreamRequest: req,
        downstreamResponse: res,
        upstreamRequest: proxyReq,
        agent,
        requestId: codexHttpRequestId || semanticObserver?.requestId || 'claude-http',
        // Long Anthropic/compatible responses have no proxy-owned deadline.
        // Client cancellation still owns the exact upstream socket and tap.
        timeoutMs: mode === 'codex' ? codexResponseHeaderTimeoutMs(targetPath) : null,
        onEvent: (event) => {
          logProviderProxyHttpLifecycle(tabId, targetPath, event);
          if (event.event === 'terminated' && semanticObserver) {
            safelyObserveProviderSemantic('claude-http-terminated', () => {
              semanticObserver.markGap(event.reason);
              semanticObserver.finish(event.reason);
            });
          }
        },
      });
    }
    proxyReq.on('error', (e) => {
      proxyHttpLifecycle?.terminate('upstream-request-error', e);
      if (semanticObserver) {
        safelyObserveProviderSemantic('claude-forward-error', () => {
          semanticObserver.markGap('forward-error');
          semanticObserver.finish('forward-error');
        });
      }
      if (codexSemanticConnection) {
        safelyObserveProviderSemantic(
          'codex-forward-error',
          () => codexSemanticConnection.finishAll('forward-error'),
        );
      }
      console.error('[ProviderProxy] Forward error'
        + (codexHttpRequestId ? ' request=' + codexHttpRequestId : '')
        + ': ' + e.message);
      const clientAborted = e?.code === 'ECLIENTABORT'
        || req.aborted === true
        || res.destroyed === true;
      if (clientAborted) return;
      const statusCode = e?.code === 'ETIMEDOUT' ? 504 : 502;
      if (!res.headersSent && !res.writableEnded) {
        res.writeHead(statusCode, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: { message: 'Proxy error: ' + e.message } }));
      } else if (!res.destroyed) {
        res.destroy(e);
      }
    });
    proxyReq.write(body);
    proxyReq.end();
  });
});

function rejectProviderProxyUpgrade(socket, statusCode, message) {
  if (!socket || socket.destroyed) return;
  const body = String(message || 'WebSocket proxy error');
  socket.write('HTTP/1.1 ' + statusCode + ' Provider Proxy Error\r\n'
    + 'Connection: close\r\n'
    + 'Content-Type: text/plain; charset=utf-8\r\n'
    + 'Content-Length: ' + Buffer.byteLength(body) + '\r\n\r\n'
    + body);
  socket.destroy();
}

function providerProxyCloseCode(code, fallback = 1000) {
  const value = Number(code);
  return value === 1000 || (value >= 3000 && value <= 4999) ? value : fallback;
}

function providerProxyCloseReason(reason) {
  return Buffer.from(reason || '').toString('utf8').slice(0, 100);
}

// Codex keeps one native Responses WebSocket for prewarm, the user turn and
// tool continuations. Wait for the real upstream handshake before accepting
// the local client so a failed relay cannot masquerade as a connected stream.
providerProxy.on('upgrade', (req, socket, head) => {
  const route = parseProviderProxyRoute(req.url);
  if (route.provider !== 'codex' || !route.tabId) {
    rejectProviderProxyUpgrade(socket, 404, 'Unsupported WebSocket route');
    return;
  }
  const webSocketRequestId = 'w' + (++providerProxyWebSocketSeq).toString(36);
  proxyActiveConnections.add(socket);
  socket.once('close', () => proxyActiveConnections.delete(socket));

  const upstreamTarget = resolveCodexUpstream({
    headers: req.headers,
    forwardUrl: route.forwardUrl,
  });
  const protocols = String(req.headers['sec-websocket-protocol'] || '')
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean);
  const options = {
    headers: forwardProviderProxyHeaders(req.headers, { websocket: true }),
    agent: codexAgent,
    perMessageDeflate: false,
    handshakeTimeout: 15000,
  };
  const upstreamUrl = 'wss://' + upstreamTarget.hostname + upstreamTarget.path;
  const upstream = protocols.length > 0
    ? new ProviderProxyWebSocket(upstreamUrl, protocols, options)
    : new ProviderProxyWebSocket(upstreamUrl, options);
  const semanticConnection = safelyObserveProviderSemantic(
    'codex-websocket-connection',
    () => providerSemanticShadow.createCodexConnection({
      tabId: route.tabId,
      transport: 'websocket',
      sourceId: currentCodexProviderSemanticSourceId(route.tabId),
    }),
  );
  let client = null;
  let heartbeat = null;
  let upstreamHeaders = {};
  let settled = false;

  socket.once('close', () => {
    if (client || settled) return;
    settled = true;
    console.warn('[ProviderProxy:WS] event=downstream-close-before-upgrade request='
      + webSocketRequestId + ' tab=' + route.tabId.slice(-12));
    try { upstream.terminate(); } catch {}
  });

  proxyActiveWebSockets.add(upstream);
  upstream.once('upgrade', (response) => {
    upstreamHeaders = response?.headers || {};
  });
  upstream.once('open', () => {
    if (settled || socket.destroyed) {
      upstream.close(1001, 'client-gone-before-upgrade');
      return;
    }
    req.__providerProxyUpstreamHeaders = upstreamHeaders;
    req.__providerProxyUpstreamProtocol = upstream.protocol || '';
    providerProxyWebSocketServer.handleUpgrade(req, socket, head, (accepted) => {
      client = accepted;
      proxyActiveWebSockets.add(client);
      console.log('[ProviderProxy] Codex[' + route.tabId.slice(-12)
        + '] transport=websocket upstream='
        + (upstreamTarget.subscription ? 'subscription' : 'api')
        + ' connected=true request=' + webSocketRequestId);

      heartbeat = startProviderProxyWebSocketHeartbeat({
        upstream,
        onEvent: (event) => {
          if (event.event !== 'heartbeat-stopped') return;
          console.log('[ProviderProxy:WS] event=' + event.event
            + ' request=' + webSocketRequestId
            + ' tab=' + route.tabId.slice(-12)
            + ' reason=' + event.reason);
        },
        onTimeout: (error) => {
          console.warn('[ProviderProxy:WS] event=upstream-heartbeat-timeout request='
            + webSocketRequestId + ' tab=' + route.tabId.slice(-12)
            + (error ? ' error=' + (error.message || String(error)) : ''));
        },
      });

      client.on('message', (data, isBinary) => {
        if (semanticConnection) {
          safelyObserveProviderSemantic(
            'codex-websocket-client-frame',
            () => semanticConnection.observeClientFrame(data, isBinary),
          );
        }
        if (upstream.readyState === ProviderProxyWebSocket.OPEN) {
          upstream.send(data, { binary: isBinary });
        }
      });
      upstream.on('message', (data, isBinary) => {
        if (semanticConnection) {
          safelyObserveProviderSemantic(
            'codex-websocket-server-frame',
            () => semanticConnection.observeServerFrame(data, isBinary),
          );
        }
        if (client?.readyState === ProviderProxyWebSocket.OPEN) {
          client.send(data, { binary: isBinary });
        }
      });
      client.on('close', (code, reason) => {
        heartbeat?.stop('client-close:' + code);
        proxyActiveWebSockets.delete(client);
        if (semanticConnection) {
          safelyObserveProviderSemantic(
            'codex-websocket-client-close',
            () => semanticConnection.finishAll('client-close:' + code),
          );
        }
        if (upstream.readyState === ProviderProxyWebSocket.OPEN
          || upstream.readyState === ProviderProxyWebSocket.CONNECTING) {
          // The local Codex half is already gone. A graceful close can itself
          // wait forever when the upstream TCP half is stale/CLOSE_WAIT, which
          // recreates the poisoned shared-pool bug. There is no remaining
          // consumer to preserve, so release this exact upstream immediately.
          upstream.terminate();
        }
      });
      client.on('error', (error) => {
        console.warn('[ProviderProxy] Codex websocket client error tab='
          + route.tabId.slice(-12) + ' error=' + (error?.message || String(error)));
      });
    });
  });
  upstream.on('unexpected-response', (_request, response) => {
    heartbeat?.stop('upstream-http-' + (response?.statusCode || 502));
    settled = true;
    proxyActiveWebSockets.delete(upstream);
    if (semanticConnection) {
      safelyObserveProviderSemantic(
        'codex-websocket-upstream-http',
        () => semanticConnection.finishAll('upstream-http-' + (response?.statusCode || 502)),
      );
    }
    rejectProviderProxyUpgrade(
      socket,
      response?.statusCode || 502,
      'Codex upstream rejected WebSocket upgrade',
    );
  });
  upstream.on('close', (code, reason) => {
    heartbeat?.stop('upstream-close:' + code);
    settled = true;
    proxyActiveWebSockets.delete(upstream);
    if (semanticConnection) {
      safelyObserveProviderSemantic(
        'codex-websocket-upstream-close',
        () => semanticConnection.finishAll('upstream-close:' + code),
      );
    }
    if (client?.readyState === ProviderProxyWebSocket.OPEN) {
      client.close(
        providerProxyCloseCode(code, 1011),
        providerProxyCloseReason(reason),
      );
    } else if (!client && !socket.destroyed) {
      rejectProviderProxyUpgrade(socket, 502, 'Codex upstream closed before upgrade');
    }
  });
  upstream.on('error', (error) => {
    heartbeat?.stop('upstream-error');
    console.warn('[ProviderProxy] Codex websocket upstream error tab='
      + route.tabId.slice(-12) + ' error=' + (error?.message || String(error)));
    if (!client && !socket.destroyed) {
      settled = true;
      rejectProviderProxyUpgrade(socket, 502, 'Codex upstream WebSocket error');
    } else if (client?.readyState === ProviderProxyWebSocket.OPEN) {
      client.close(1011, 'upstream-error');
    }
  });
});

// Graceful shutdown: drain active connections before killing proxy
async function proxyGracefulShutdown() {
  providerProxyReady = false;
  if (proxyActiveConnections.size === 0 && proxyActiveWebSockets.size === 0) return;
  console.log('[ProviderProxy] Graceful shutdown: ' + proxyActiveConnections.size
    + ' active connections, ' + proxyActiveWebSockets.size + ' websockets, draining...');
  providerProxy.close(); // stop accepting new connections
  for (const ws of proxyActiveWebSockets) {
    try { ws.close(1001, 'application-shutdown'); } catch {}
  }
  const deadline = Date.now() + 15000; // 15s max wait
  while ((proxyActiveConnections.size > 0 || proxyActiveWebSockets.size > 0)
    && Date.now() < deadline) {
    await new Promise(r => setTimeout(r, 200));
  }
  for (const ws of proxyActiveWebSockets) {
    try { ws.terminate(); } catch {}
  }
  proxyActiveWebSockets.clear();
  if (proxyActiveConnections.size > 0) {
    console.log('[ProviderProxy] Force-closing ' + proxyActiveConnections.size + ' connections after timeout');
    for (const socket of proxyActiveConnections) socket.destroy();
  }
}

// Try port 4001, fallback to 4002-4010 if busy (e.g. dev + test running simultaneously)
function startProxyOnPort(port) {
  const onListening = () => {
    providerProxy.removeListener('error', onError);
    PROVIDER_PROXY_PORT = port;
    providerProxyReady = true;
    console.log('[ProviderProxy] Started on http://127.0.0.1:' + port + ' (keepAlive=true, per-tab routing)');
  };
  const onError = (e) => {
    providerProxy.removeListener('listening', onListening);
    if (e.code === 'EADDRINUSE' && port < 4010) {
      providerProxyReady = false;
      console.log('[ProviderProxy] Port ' + port + ' busy, trying ' + (port + 1));
      setImmediate(() => startProxyOnPort(port + 1));
    } else {
      providerProxyReady = false;
      console.error('[ProviderProxy] Server error:', e.message);
    }
  };
  providerProxy.once('listening', onListening);
  providerProxy.once('error', onError);
  providerProxy.listen(port, '127.0.0.1');
}
startProxyOnPort(4001);

// ========== SESSION BRIDGE (StatusLine-based session detection) ==========
// Claude's statusLine feature calls ~/.claude/statusline-bridge.sh after every response,
// writing {session_id, ppid, cwd, ...} to ~/.claude/bridge/{session_id}.json.
// We watch that directory and match bridge files to tabs via PID tree:
// bridge.ppid (Claude PID) → parent PID (shell) → ptyProcess.pid (our tab)
const bridgeDir = path.join(os.homedir(), '.claude', 'bridge');
const bridgeKnownSessions = new Map(); // tabId → sessionId
const agentContextUsageState = createAgentContextUsageState();

function commitAgentContextUsage({ tabId, provider, sessionId, contextPct, source }) {
  const observed = agentContextUsageState.observe({
    tabId,
    provider,
    sessionId,
    contextPct,
  });
  if (!observed.accepted) return null;
  let persistenceAccepted = true;
  if (observed.shouldPersist) {
    try {
      const persisted = provider === 'codex'
        ? projectManager?.db?.updateCodexTabContextPctForSession?.(
          tabId,
          sessionId,
          observed.snapshot.contextPct,
        )
        : (projectManager?.db?.updateTabContextPct?.(tabId, observed.snapshot.contextPct), true);
      if (persisted === true) {
        console.log('[AgentContext] persisted tab=' + String(tabId).slice(-12)
          + ' provider=' + provider
          + ' session=' + String(sessionId).slice(0, 8)
          + ' pct=' + observed.snapshot.contextPct.toFixed(1)
          + ' source=' + (source || 'unknown'));
      } else {
        persistenceAccepted = false;
        console.log('[AgentContext] persist skipped tab=' + String(tabId).slice(-12)
          + ' provider=' + provider
          + ' session=' + String(sessionId).slice(0, 8)
          + ' reason=session-binding-changed');
      }
    } catch {
      persistenceAccepted = false;
    }
  }
  return { ...observed.snapshot, persistenceAccepted };
}

function codexContextBoundTabs(sessionId) {
  if (!sessionId) return [];
  try {
    return projectManager?.db?.db?.prepare(`
      SELECT tab_id, cwd
      FROM tabs
      WHERE codex_session_id = ? AND tab_id IS NOT NULL
    `).all(sessionId) || [];
  } catch {
    return [];
  }
}

function codexPersistedContextSessions() {
  try {
    return projectManager?.db?.db?.prepare(`
      SELECT codex_session_id AS sessionId, MAX(cwd) AS cwd
      FROM tabs
      WHERE codex_session_id IS NOT NULL
        AND codex_session_id != ''
      GROUP BY codex_session_id
      ORDER BY MAX(created_at) DESC
    `).all() || [];
  } catch (error) {
    console.warn('[CodexContext:Observer] hydration query failed:', error?.message || error);
    return [];
  }
}

function publishCodexContextFrame(tabId, sessionId, contextPct, {
  invalidated = false,
  reason = null,
  source = null,
} = {}) {
  const frame = {
    tabId,
    sessionId,
    contextPct: invalidated ? null : contextPct,
    contextInvalidated: invalidated,
    reason: reason || undefined,
    source: source || undefined,
  };
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:context-update', frame);
  }
  try {
    _webBroadcast(tabId, {
      type: 'bridge-update',
      sessionId,
      contextPct: frame.contextPct,
      contextInvalidated: invalidated,
      contextReason: reason || undefined,
    });
  } catch {}
}

codexSessionContextObserver = createCodexContextSessionObserver({
  transcriptService,
  listBoundTabs: codexContextBoundTabs,
  listCachedSessions: codexPersistedContextSessions,
  readContextState: (tabId, sessionId) => agentContextUsageState.read(tabId, {
    provider: 'codex',
    sessionId,
  }),
  commitContextValue: ({ tabId, sessionId, contextPct, source }) => commitAgentContextUsage({
    tabId,
    provider: 'codex',
    sessionId,
    contextPct,
    source,
  }),
  invalidateContextState: (tabId, sessionId) => agentContextUsageState.invalidate(tabId, {
    provider: 'codex',
    sessionId,
  }),
  clearPersistedContext: (tabId, sessionId) => (
    projectManager?.db?.clearCodexTabContextPctForSession?.(tabId, sessionId) === true
  ),
  publishContextFrame: publishCodexContextFrame,
  log: console,
});
// Proven writer only. Resume arguments and persisted fallback IDs live in the
// launch intent / SQLite respectively and must never enter this map until the
// PTY descendant is proven to hold that rollout open for writing.
const codexKnownSessions = new Map(); // tabId → active writer sessionId
const codexConversationMaterializationCache = new Map(); // sessionId → exact transcript verdict
const codexWriterProofs = new Map(); // tabId → last process-open rollout proof + validity
// A bounded filesystem watcher may retire while the same Resume process stays
// idle for hours. Keep only its exact generation-bound source observation;
// this is read/Rewind admission evidence, never durable writer authority.
const codexProvisionalSourceObservations = new Map(); // tabId → exact live Resume source observation
const codexWriterProcessProofInflight = new Map(); // tabId → shared ps/lsof proof promise
const codexWriterReconcileInflight = new Map(); // tab/observer key → shared adoption promise
const codexWriterSessionInflight = new Map(); // rollout sessionId → cross-tab ownership transaction
const codexRewindReservations = new Map(); // tabId → the one destructive native Rewind currently authorized
let codexRewindReservationSeq = 0;
const codexActionAuthorities = new Map(); // `${profile}:${tabId}` → last exact action lease (including terminal states)
