function rememberCodexProvisionalSourceObservation(tabId, observation) {
  if (!tabId || !observation) return null;
  const stored = Object.freeze({
    ...observation,
    pids: Object.freeze([...(Array.isArray(observation.pids) ? observation.pids : [])]),
  });
  codexProvisionalSourceObservations.set(tabId, stored);
  return stored;
}

function getCurrentCodexProvisionalSourceObservation(tabId) {
  const observation = codexProvisionalSourceObservations.get(tabId) || null;
  if (!observation) return null;
  const intent = codexSessionDiscoveryIntents.get(tabId) || null;
  const validation = validateCodexProvisionalSourceObservation(observation, {
    sourceSessionId: intent?.sourceSessionId || null,
    persistedSessionId: codexSessionIdFromDb(tabId),
    launchId: intent?.launchId || null,
    terminalToken: terminals.get(tabId) || null,
    terminalRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    terminalLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    processRunning: terminalCommandState.get(tabId)?.isRunning === true,
  });
  if (validation.valid) return observation;
  codexProvisionalSourceObservations.delete(tabId);
  console.log('[CodexLaunchObservation] stale provisional source dropped tab='
    + String(tabId).slice(-12)
    + ' reason=' + validation.reason);
  return null;
}

function codexActionAuthorityKey(profile, tabId) {
  return String(profile || '') + ':' + String(tabId || '');
}

function currentCodexActionAuthorityIdentity(tabId, authority, {
  launchId = authority?.identity?.launchId || null,
  sourceSessionId = authority?.identity?.sourceSessionId || null,
  operationId = authority?.identity?.operationId || null,
  requestId = authority?.identity?.requestId || null,
} = {}) {
  return {
    terminalToken: terminals.get(tabId) || null,
    projectId: resolveAuthoritativeTabProjectId(tabId),
    tabId,
    lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    launchId,
    sourceSessionId,
    persistedSessionId: codexSessionIdFromDb(tabId),
    inputRevision: getTerminalInputRevision(tabId),
    operationId,
    requestId,
  };
}

function publishCodexActionAuthorityState(authority, reason = null) {
  if (!authority) return;
  const detail = {
    authorityId: authority.authorityId,
    profile: authority.profile,
    phase: authority.phase,
    reason: reason || authority.reason || null,
    tabId: authority.identity?.tabId || null,
    projectId: authority.identity?.projectId || null,
    lifecycleGeneration: authority.identity?.lifecycleGeneration || null,
    runSeq: authority.identity?.runSeq ?? null,
    launchId: authority.identity?.launchId || null,
    actionGeneration: authority.actionGeneration || null,
    sourceSessionId: authority.identity?.sourceSessionId || null,
    persistedSessionId: authority.identity?.persistedSessionId || null,
    inputRevision: authority.identity?.inputRevision ?? null,
    operationId: authority.identity?.operationId || null,
    requestId: authority.identity?.requestId || null,
    target: authority.target ? { ...authority.target } : null,
    at: authority.updatedAt || Date.now(),
  };
  console.warn('[CodexActionAuthority] profile=' + detail.profile
    + ' state=' + detail.phase
    + ' id=' + String(detail.authorityId || '').slice(-16)
    + ' tab=' + String(detail.tabId || '').slice(-12)
    + ' project=' + String(detail.projectId || '').slice(-12)
    + ' source=' + String(detail.sourceSessionId || '').slice(0, 8)
    + ' launch=' + (detail.launchId || '-')
    + ' action=' + (detail.actionGeneration || '-')
    + ' run=' + (detail.runSeq ?? '-')
    + ' input=' + (detail.inputRevision ?? '-')
    + (detail.reason ? ' reason=' + detail.reason : ''));
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:action-authority-state', detail);
  }
}

function createMainCodexActionAuthority({
  profile,
  tabId,
  launchId,
  sourceSessionId,
  operationId,
  requestId,
  target = null,
}) {
  const authorityId = profile + '-' + Date.now() + '-' + (++codexActionAuthoritySeq);
  const created = createCodexActionAuthority({
    authorityId,
    profile,
    identity: currentCodexActionAuthorityIdentity(tabId, null, {
      launchId,
      sourceSessionId,
      operationId,
      requestId,
    }),
    target,
  });
  if (!created.success) return created;
  const key = codexActionAuthorityKey(profile, tabId);
  const previous = codexActionAuthorities.get(key) || null;
  if (previous && previous.phase !== 'revoked' && previous.phase !== 'committed') {
    transitionMainCodexActionAuthority(previous, 'revoked', 'replaced-by-new-action');
  }
  codexActionAuthorities.set(key, created.authority);
  publishCodexActionAuthorityState(created.authority);
  return created;
}

function transitionMainCodexActionAuthority(authority, phase, reason = null) {
  const result = transitionCodexActionAuthority(authority, phase, { reason });
  if (result.success) {
    publishCodexActionAuthorityState(authority, reason);
    if (phase === 'revoked' || phase === 'committed') {
      const waiter = codexActionAuthorityTestWaiters.get(authority.authorityId) || null;
      if (waiter) {
        codexActionAuthorityTestWaiters.delete(authority.authorityId);
        waiter.resolve({ released: false, terminal: true, phase, reason });
      }
    }
  }
  return result;
}

function validateMainCodexActionAuthority(authority, options = {}) {
  if (!authority) return { valid: false, reason: 'action-authority-missing' };
  const tabId = authority.identity?.tabId || null;
  return validateCodexActionAuthority(
    authority,
    currentCodexActionAuthorityIdentity(tabId, authority, options),
    options,
  );
}

function validateConsumedCodexResumedSubmitAuthority(authority, reservation, {
  allowPersistedWriterAdoption = false,
} = {}) {
  if (!authority || !reservation) {
    return { valid: false, reason: 'action-authority-missing' };
  }
  const currentIdentity = currentCodexActionAuthorityIdentity(
    authority.identity?.tabId || null,
    authority,
    {
      launchId: reservation.launchId,
      sourceSessionId: reservation.sourceSessionId,
    },
  );
  // Input ownership is consumed at the paste/Enter boundary. Later manual
  // keystrokes cannot unsend that Enter and must not prevent its exact rollout
  // record from reconciling. Every process/terminal/project/run/launch owner is
  // still checked against the original lease.
  currentIdentity.inputRevision = authority.identity.inputRevision;
  if (allowPersistedWriterAdoption) {
    currentIdentity.persistedSessionId = authority.identity.persistedSessionId;
  }
  return validateCodexActionAuthority(authority, currentIdentity, {
    phases: ['consumed'],
    profile: CODEX_ACTION_PROFILE_RESUMED_ACTIVE_SUBMIT,
    target: authority.target,
  });
}

function revokeCodexActionAuthoritiesForTab(tabId, reason, {
  exceptAuthority = null,
  profile = null,
} = {}) {
  let revoked = 0;
  for (const authority of codexActionAuthorities.values()) {
    if (authority?.identity?.tabId !== tabId
      || authority === exceptAuthority
      || (profile && authority.profile !== profile)
      || authority.phase === 'revoked'
      || authority.phase === 'committed') continue;
    if (transitionMainCodexActionAuthority(authority, 'revoked', reason).success) revoked += 1;
  }
  return revoked;
}

function revokeCodexActionAuthoritiesForManualInput(tabId) {
  const observer = codexWatchers.get(tabId) || null;
  const manualRewindAuthority = observer?.manualRewind
    ? observer.actionAuthority || null
    : null;
  const submittedAuthority = observer?.provisionalSubmitReservation?.enterWritten === true
    ? observer.provisionalSubmitReservation.actionAuthority || null
    : null;
  let revoked = 0;
  for (const authority of codexActionAuthorities.values()) {
    if (authority?.identity?.tabId !== tabId
      || authority === manualRewindAuthority
      || authority === submittedAuthority
      || authority.phase === 'revoked'
      || authority.phase === 'committed') continue;
    if (transitionMainCodexActionAuthority(authority, 'revoked', 'manual-input').success) {
      revoked += 1;
    }
  }
  return revoked;
}

function revokeCodexActionAuthoritiesForWriterAdoption(tabId, sessionId) {
  const observer = codexWatchers.get(tabId) || null;
  const rewindAuthority = observer?.sourceMode === 'writer-handoff'
    ? observer.actionAuthority || null
    : null;
  const submitReservation = observer?.provisionalSubmitReservation || null;
  const submitAuthority = submitReservation?.actionAuthority || null;
  const causalSessionId = submitReservation?.causalWriterProof?.sessionId || null;
  let revoked = 0;
  for (const authority of codexActionAuthorities.values()) {
    if (authority?.identity?.tabId !== tabId
      || authority.phase === 'revoked'
      || authority.phase === 'committed') continue;
    const exactRewindHandoff = authority === rewindAuthority;
    const exactSubmitHandoff = authority === submitAuthority
      && (
        sessionId === submitReservation.sourceSessionId
        || sessionId === causalSessionId
      );
    if (exactRewindHandoff || exactSubmitHandoff) continue;
    if (transitionMainCodexActionAuthority(authority, 'revoked', 'competing-writer-adopted').success) {
      revoked += 1;
    }
  }
  return revoked;
}

function codexActionAuthorityTestHoldEnabled(profile) {
  if (!isDev || process.env.NOTED_E2E_TEST !== 'true') return false;
  const configured = String(process.env.NOTED_E2E_CODEX_ACTION_AUTHORITY_HOLD || '')
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean);
  return configured.includes('*') || configured.includes(profile);
}

async function waitForCodexActionAuthorityTestRelease(authority) {
  if (!authority || !codexActionAuthorityTestHoldEnabled(authority.profile)) {
    return { released: true, held: false };
  }
  let resolveWaiter;
  const promise = new Promise((resolve) => { resolveWaiter = resolve; });
  codexActionAuthorityTestWaiters.set(authority.authorityId, {
    authority,
    resolve: resolveWaiter,
  });
  console.warn('[CodexActionAuthority] DEV hold armed profile=' + authority.profile
    + ' id=' + authority.authorityId
    + ' tab=' + String(authority.identity?.tabId || '').slice(-12));
  return promise;
}

ipcMain.handle('__test:codex-action-authority', (_event, payload = {}) => {
  if (!isDev || process.env.NOTED_E2E_TEST !== 'true') {
    return { success: false, error: 'test_hook_disabled' };
  }
  const action = String(payload.action || 'snapshot');
  const profile = String(payload.profile || '');
  const tabId = String(payload.tabId || '');
  if (action === 'snapshot') {
    const authorities = [...codexActionAuthorities.values()]
      .filter((authority) => (!profile || authority.profile === profile)
        && (!tabId || authority.identity?.tabId === tabId))
      .map((authority) => ({
        authorityId: authority.authorityId,
        profile: authority.profile,
        phase: authority.phase,
        reason: authority.reason || null,
        tabId: authority.identity?.tabId || null,
        projectId: authority.identity?.projectId || null,
        lifecycleGeneration: authority.identity?.lifecycleGeneration || null,
        runSeq: authority.identity?.runSeq ?? null,
        launchId: authority.identity?.launchId || null,
        actionGeneration: authority.actionGeneration || null,
        sourceSessionId: authority.identity?.sourceSessionId || null,
        persistedSessionId: authority.identity?.persistedSessionId || null,
        inputRevision: authority.identity?.inputRevision ?? null,
        operationId: authority.identity?.operationId || null,
        requestId: authority.identity?.requestId || null,
        target: authority.target ? { ...authority.target } : null,
        held: codexActionAuthorityTestWaiters.has(authority.authorityId),
      }));
    return { success: true, authorities };
  }
  if (action === 'release') {
    const authority = codexActionAuthorities.get(codexActionAuthorityKey(profile, tabId)) || null;
    const waiter = authority
      ? codexActionAuthorityTestWaiters.get(authority.authorityId) || null
      : null;
    if (!waiter) return { success: false, error: 'test_hold_not_found' };
    codexActionAuthorityTestWaiters.delete(authority.authorityId);
    waiter.resolve({ released: true, held: true });
    return { success: true, authorityId: authority.authorityId };
  }
  if (action === 'clear') {
    for (const [authorityId, waiter] of codexActionAuthorityTestWaiters.entries()) {
      codexActionAuthorityTestWaiters.delete(authorityId);
      waiter.resolve({ released: false, terminal: true, reason: 'test-clear' });
    }
    return { success: true };
  }
  return { success: false, error: 'test_action_unknown' };
});
// Rewind UI can outlive a renderer mount and cancellation can race the final
// Enter. Keep operation ownership in main so a stale component cannot cancel a
// newer rewind, and so cancellation never types `q` after mutation began.
const activeRewindOperations = new Map(); // tabId → { opId, toolType, mutationStarted, protocolUiOpen }
const rewindOperationSettlements = new WeakMap(); // operation → { promise, resolve }
let codexRewindRecoveryScanStatus = 'not-run'; // complete | unknown
const codexLaunchObservationPending = new Map(); // tabId → launchId while observer is being attached
// tabId → launchId from PTY write until authoritative TUI/rollout/lifecycle
// settlement (or the one-shot startup watchdog). This is not process proof.
const codexLaunchAcceptancePending = new Map();
// Start/Resume/Fork and Stop share one FIFO per tab. A launch-only lock let a
// delayed orchestration Stop race a restored process in either direction.
const aiLifecycleActionInflight = new Map(); // tabId → main-owned lifecycle action transaction
const codexLaunchInflight = new Map(); // tabId → serialized launch/resume admission
const claudeResumePreparationInflight = new Map(); // sessionId → serialized trim/repair transaction
// A resume source is launch intent, not writer identity, but two live resumes
// of the same source cannot be attributed reliably if both processes keep that
// rollout writable. Lease the source for the process lifetime; fork remains
// multi-owner because it must create an independent child rollout.
const codexResumeSourceLeases = new Map(); // sourceSessionId → { tabId, launchId, at }
const aiStoppingTabs = new Map(); // tabId → { toolType, reason, since, sessionId }
const claudeStartupIntents = new Map(); // tabId → { sessionId, at, reason }
const claudeStartupDefaultsGateByTab = new Map(); // tabId → { status, reason, error, at }

// Launch generation of the live Claude process per tab. This is the identity
// the startup-settings transaction is keyed by: readiness signals
// (`process-started`, `tui-ready`) are inputs to ONE owner rather than two
// competing initiators, and a proof or event belonging to an older launch can
// no longer close (or fail) the current transaction. The accepted launch
// command normally opens it; readiness remains a fallback for legacy/manual
// shells that cannot attach command metadata. Cleared when the process dies.
const claudeLaunchGenerationByTab = new Map(); // tabId → { generation, pid, at }
// A durable per-tab next-launch choice is consumed only after the exact launch
// generation proves both startup commands. Keeping the use record separate
// from provider state prevents a failed/superseded launch from deleting the
// user's choice.
const claudeStartupIntentUseByTab = new Map(); // tabId → { generation, model, effort }
let claudeLaunchGenerationSeq = 0;
const claudePromptStability = createClaudePromptStabilityRegistry({
  now: () => Date.now(),
  log: (message) => console.log(message),
});

function observeClaudeSynchronizedFrameFlushed(tabId, expectedState, writeSeq) {
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  if (!launch?.generation || getHeadlessTerminalMirror(tabId) !== expectedState) return;
  if (
    expectedState.failed === true
    || expectedState.redrawTrace?.synchronizedOutputOpen === true
    || Number(expectedState.flushedSeq || 0) !== Number(expectedState.writeSeq || 0)
    || Number(writeSeq || 0) !== Number(expectedState.flushedSeq || 0)
  ) return;
  if (claudeTurnBusy.get(tabId) === true || aiStoppingTabs.has(tabId)) return;

  const snapshot = getHeadlessVisibleBufferSnapshot(tabId, 'claude-prompt-stability');
  if (!snapshot?.success || snapshot.synchronizedOutputOpen === true) return;
  const visibleText = snapshot.lines.map((line) => line?.text || '').join('\n');
  if (
    claudeTrustFolderPromptHintTabs.has(tabId)
    || inspectClaudeTrustFolderPromptSnapshot(snapshot).visible === true
    || looksLikeClaudeTrustFolderPromptText(visibleText)
    || claudeAutoModeDefaultPromptHintTabs.has(tabId)
    || inspectClaudeAutoModeDefaultPromptSnapshot(snapshot).visible === true
    || looksLikeClaudeAutoModeDefaultPromptText(visibleText)
    || looksLikeClaudeRewindMenuText(visibleText)
    || /(?:Change effort level|Switch model\?)/i.test(visibleText)
  ) return;
  const proof = parseClaudeComposerCurrentFrame(snapshot);
  if (
    proof.proofOutcome !== 'found'
    && proof.proofOutcome !== 'absent'
    && proof.exactCaptureRecommended !== true
  ) return;
  claudePromptStability.markStable(
    tabId,
    launch.generation,
    'current-composer-frame:' + writeSeq,
  );
}

function currentClaudeFrameHasStashMarker(tabId) {
  const snapshot = getHeadlessVisibleBufferSnapshot(tabId, 'startup-stash-marker');
  if (
    snapshot?.success !== true
    || snapshot.source !== 'headless-main'
    || snapshot.synchronizedOutputOpen === true
    || Number(snapshot.writeSeq) !== Number(snapshot.flushedSeq)
  ) return null;
  const visible = snapshot.lines.map((line) => line?.text || '').join('\n');
  return STASH_MARKER_RE.test(visible);
}

function exactClaudeEmptyEvidenceStillCurrent(tabId, evidence) {
  if (
    !evidence
    || evidence.proofOutcome !== 'absent'
    || evidence.terminalIdentityStable !== true
    || evidence.editorReturnReady !== true
    || String(evidence.text || '').trim()
    || Number(evidence.images || 0) > 0
  ) return false;
  const mirror = getHeadlessTerminalMirror(tabId);
  return Number(evidence.terminalRunSeq) === Number(terminalCommandState.get(tabId)?.runSeq || 0)
    && Number(evidence.inputRevision) === getTerminalInputRevision(tabId)
    && evidence.terminalLifecycleGeneration === getTerminalLifecycleGeneration(tabId)
    && evidence.mirrorGeneration === (mirror?.generation || null);
}

async function exactClaudeStartupComposerRead(tabId, generation, lease, proof) {
  const captured = await captureAgentInput(tabId, 'copy', 'claude', {
    draftProof: proof,
  });
  if (captured?.success !== true) {
    return {
      ready: false,
      retryAdmission: false,
      error: captured?.error || 'claude_startup_exact_input_failed',
    };
  }

  // Ctrl+G temporarily leaves the TUI. Its editor-return frame owns a new
  // lease, so never keep using the frame lease captured before Ctrl+G.
  const promptStable = await claudePromptStability.wait(tabId, generation);
  if (promptStable?.ready !== true) {
    return {
      ready: false,
      retryAdmission: false,
      error: promptStable?.reason || 'claude_startup_editor_return_unresolved',
    };
  }
  const nextLease = promptStable.lease || null;
  const admission = claudePromptStability.validate(tabId, generation, nextLease);
  if (!admission.valid) {
    return {
      ready: false,
      retryAdmission: true,
      error: admission.reason,
    };
  }
  if (String(captured.text || '').trim() || Number(captured.images || 0) > 0) {
    return {
      ready: true,
      hasDraft: true,
      lease: nextLease,
      captured,
    };
  }
  if (!exactClaudeEmptyEvidenceStillCurrent(tabId, captured)) {
    return {
      ready: false,
      retryAdmission: false,
      error: captured?.proofReason || 'claude_startup_exact_empty_unresolved',
    };
  }
  return {
    ready: true,
    hasDraft: false,
    lease: nextLease,
    exactEmptyEvidence: captured,
  };
}

async function prepareClaudeStartupComposer({
  tabId,
  generation,
  lease,
  term,
  retryCommand = '',
  retryRecovery = null,
}) {
  let currentLease = lease;
  let proof = await requestTerminalClaudeDraftState(
    mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    tabId,
    'startup-command-before-stash',
    900,
  );
  let admission = claudePromptStability.validate(tabId, generation, currentLease);
  if (!admission.valid) {
    return { ready: false, retryAdmission: true, error: admission.reason };
  }

  let exactEmptyEvidence = null;
  let hasDraft = proof?.proofOutcome === 'found' && proof?.hasDraft === true;
  const retryComposer = classifyClaudeStartupRetryComposer({
    recovery: retryRecovery,
    command: retryCommand,
    composer: proof,
  });
  if (retryComposer.ownership === 'transaction-command') {
    console.warn('[StartupTx] retry-command-restored tab=' + String(tabId).slice(-12)
      + ' gen=' + generation
      + ' command=' + JSON.stringify(retryCommand)
      + ' action=submit-existing-input reason=' + retryComposer.reason);
    return {
      ready: true,
      lease: currentLease,
      proof,
      exactEmptyEvidence: null,
      existingOwnedCommand: true,
    };
  }
  if (
    proof?.proofOutcome === 'unknown'
    && proof?.exactCaptureRecommended === true
  ) {
    const exact = await exactClaudeStartupComposerRead(
      tabId,
      generation,
      currentLease,
      proof,
    );
    if (!exact.ready) return exact;
    currentLease = exact.lease;
    hasDraft = exact.hasDraft === true;
    exactEmptyEvidence = exact.exactEmptyEvidence || null;
    const exactRetryComposer = classifyClaudeStartupRetryComposer({
      recovery: retryRecovery,
      command: retryCommand,
      composer: {
        proofOutcome: exact.hasDraft === true ? 'found' : 'absent',
        hasDraft: exact.hasDraft === true,
        source: 'claude-hook-grab-input',
        exactCapture: true,
        text: exact.captured?.text || '',
      },
    });
    if (exactRetryComposer.ownership === 'transaction-command') {
      console.warn('[StartupTx] retry-command-restored tab=' + String(tabId).slice(-12)
        + ' gen=' + generation
        + ' command=' + JSON.stringify(retryCommand)
        + ' action=submit-existing-input reason=' + exactRetryComposer.reason
        + ' proof=exact-capture');
      return {
        ready: true,
        lease: currentLease,
        proof,
        exactEmptyEvidence: null,
        existingOwnedCommand: true,
      };
    }
  } else if (proof?.proofOutcome !== 'absent' && !hasDraft) {
    return {
      ready: false,
      retryAdmission: false,
      error: proof?.proofReason || proof?.error || 'claude_startup_composer_unknown',
    };
  }

  if (!hasDraft) {
    return {
      ready: true,
      lease: currentLease,
      proof,
      exactEmptyEvidence,
    };
  }

  const stashVisible = currentClaudeFrameHasStashMarker(tabId);
  if (stashVisible !== false) {
    return {
      ready: false,
      retryAdmission: false,
      error: stashVisible === true
        ? 'claude_startup_draft_and_existing_stash'
        : 'claude_startup_stash_state_unknown',
    };
  }
  admission = claudePromptStability.validate(tabId, generation, currentLease);
  if (!admission.valid || terminals.get(tabId) !== term) {
    return {
      ready: false,
      retryAdmission: true,
      error: admission.valid ? 'claude_startup_terminal_changed' : admission.reason,
    };
  }

  console.log('[StartupTx] stash-native-draft tab=' + String(tabId).slice(-12)
    + ' gen=' + generation);
  const editorFrame = waitForNextPtySynchronizedFrame(term, { timeoutMs: 1800 });
  bumpTerminalInputRevision(tabId);
  term.write('\x13');
  const stashedFrame = await editorFrame;
  if (stashedFrame?.ready !== true) {
    return {
      ready: false,
      retryAdmission: false,
      error: stashedFrame?.reason || 'claude_startup_stash_frame_unconfirmed',
    };
  }

  const promptStable = await claudePromptStability.wait(tabId, generation);
  if (promptStable?.ready !== true) {
    return {
      ready: false,
      retryAdmission: false,
      error: promptStable?.reason || 'claude_startup_stash_prompt_unresolved',
    };
  }
  currentLease = promptStable.lease || null;
  admission = claudePromptStability.validate(tabId, generation, currentLease);
  if (!admission.valid) {
    return { ready: false, retryAdmission: true, error: admission.reason };
  }

  proof = await requestTerminalClaudeDraftState(
    mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    tabId,
    'startup-command-after-stash',
    900,
  );
  admission = claudePromptStability.validate(tabId, generation, currentLease);
  if (!admission.valid) {
    return { ready: false, retryAdmission: true, error: admission.reason };
  }
  if (proof?.proofOutcome === 'absent' && proof?.hasDraft === false) {
    return { ready: true, lease: currentLease, proof, exactEmptyEvidence: null };
  }
  if (proof?.proofOutcome === 'unknown' && proof?.exactCaptureRecommended === true) {
    const exact = await exactClaudeStartupComposerRead(
      tabId,
      generation,
      currentLease,
      proof,
    );
    if (exact.ready && exact.hasDraft === false) {
      return {
        ready: true,
        lease: exact.lease,
        proof,
        exactEmptyEvidence: exact.exactEmptyEvidence,
      };
    }
    return exact.ready
      ? { ready: false, retryAdmission: false, error: 'claude_startup_stash_did_not_clear' }
      : exact;
  }
  return {
    ready: false,
    retryAdmission: false,
    error: 'claude_startup_stash_did_not_clear',
  };
}

async function verifyClaudeStartupCommandAtEnterBoundary({
  tabId,
  generation,
  lease,
  term,
  command,
}) {
  const admissionBefore = claudePromptStability.validate(
    tabId,
    generation,
    lease,
    { allowFrameAdvance: true },
  );
  if (!admissionBefore.valid) return admissionBefore;
  if (
    terminals.get(tabId) !== term
    || claudeLaunchGenerationByTab.get(tabId)?.generation !== generation
  ) {
    return { valid: false, reason: 'claude-startup-generation-changed' };
  }

  // The paste itself legitimately creates one or more redraw frames, so the
  // pre-paste lease cannot require an unchanged frame sequence at Enter. Do
  // not merely waive that check, though: prove from the freshly flushed
  // current frame that the composer contains exactly the command we pasted.
  // An unrelated restored notification, menu, partial redraw, or user edit
  // therefore loses admission before Enter rather than colliding with it.
  const proof = await requestTerminalClaudeDraftState(
    mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    tabId,
    'startup-command-enter-boundary',
    900,
  );
  const admissionAfter = claudePromptStability.validate(
    tabId,
    generation,
    lease,
    { allowFrameAdvance: true },
  );
  if (!admissionAfter.valid) return admissionAfter;
  if (
    terminals.get(tabId) !== term
    || claudeLaunchGenerationByTab.get(tabId)?.generation !== generation
  ) {
    return { valid: false, reason: 'claude-startup-generation-changed' };
  }
  if (
    proof?.proofOutcome !== 'found'
    || proof?.hasDraft !== true
    || !String(proof?.source || '').startsWith('headless-main:')
  ) {
    return {
      valid: false,
      reason: 'claude-startup-command-not-proven-at-enter',
      proof,
    };
  }
  if (
    normalizeClaudeLocalCommandText(proof.text)
    !== normalizeClaudeLocalCommandText(command)
  ) {
    return {
      valid: false,
      reason: 'claude-startup-command-changed-at-enter',
      proof,
    };
  }
  return {
    valid: true,
    reason: 'claude-startup-command-exact-at-enter',
    proof,
  };
}

const claudeStartupMainRuntime = createClaudeStartupMainRuntime({
  now: () => Date.now(),
  log: (message) => console.log(message),
  currentLaunchGeneration: (tabId) =>
    claudeLaunchGenerationByTab.get(tabId)?.generation || null,
  resolveSettings: (context) => resolveClaudeStartupSettingsInMain(context),
  sendCommand: async ({ tabId, generation, command, source, recovery = null }) => {
    let admissionAttempt = 0;
    while (claudeLaunchGenerationByTab.get(tabId)?.generation === generation) {
      admissionAttempt += 1;
      const promptStable = await claudePromptStability.wait(tabId, generation);
      console.log('[StartupTx] prompt-stability tab=' + String(tabId).slice(-12)
        + ' gen=' + String(generation || '-')
        + ' attempt=' + admissionAttempt
        + ' ready=' + (promptStable?.ready === true)
        + ' reason=' + String(promptStable?.reason || '-'));
      if (promptStable?.ready !== true) {
        return {
          success: false,
          submitted: false,
          pasteWritten: false,
          error: 'claude_prompt_not_stable',
          reason: promptStable?.reason || 'prompt-stability-unresolved',
        };
      }
      let lease = promptStable.lease || null;
      const restoredWorkBoundary = await aiBoundaryTestGate.waitIfArmed({
        kind: 'claude-resume-work-after-first-ready',
        identity: { tabId, generation },
      });
      if (restoredWorkBoundary?.claimed === true
        && restoredWorkBoundary.action === 'inject') {
        const marker = String(
          restoredWorkBoundary.payload?.marker
          || ('E2E-RESTORED-WORK-' + restoredWorkBoundary.arm.armId),
        ).slice(0, 120);
        console.warn('[TestFault] trigger kind=resume-work-after-first-ready'
          + ' tab=' + String(tabId).slice(-12)
          + ' gen=' + generation
          + ' operation=' + restoredWorkBoundary.arm.operationId
          + ' marker=' + marker);
        const injected = await sendClaudeCommandInternal(
          tabId,
          marker + ' — reply with OK.',
          {
            source: 'e2e-resume-work-after-first-ready:' + marker,
            stashFirst: false,
            armPromptBoundaryOnSubmit: true,
            // This DEV-only injection creates the restored-work precondition
            // before Resume has necessarily re-established a transcript
            // boundary. Requiring that boundary here prevents the hook from
            // creating the state it exists to test. Physical paste/Enter and
            // the following busy -> new-ready edge remain authoritative.
            awaitUserMessageAudit: false,
            verifyClaudeVisibleDraftBeforePaste: true,
          },
        );
        aiBoundaryTestGate.complete({
          armId: restoredWorkBoundary.arm.armId,
          operationId: restoredWorkBoundary.arm.operationId,
          reason: injected?.success === true ? 'test-turn-submitted' : 'test-turn-failed',
          result: {
            success: injected?.success === true,
            submitted: injected?.submitted === true,
          },
        });
        if (injected?.success !== true || injected?.submitted !== true) {
          return {
            success: false,
            submitted: false,
            pasteWritten: injected?.pasteWritten === true,
            error: injected?.error || 'claude_test_restored_work_submit_failed',
          };
        }
        console.log('[StartupTx] prompt-admission-retry tab=' + String(tabId).slice(-12)
          + ' gen=' + generation
          + ' attempt=' + admissionAttempt
          + ' stage=test-resumed-work');
        continue;
      }
      const beforeSend = claudePromptStability.validate(tabId, generation, lease);
      if (!beforeSend.valid) {
        console.log('[StartupTx] prompt-admission-retry tab=' + String(tabId).slice(-12)
          + ' gen=' + generation
          + ' attempt=' + admissionAttempt
          + ' stage=before-send'
          + ' reason=' + beforeSend.reason);
        continue;
      }
      let composerAdmission = null;
      if (recovery?.kind !== 'submit-existing-input') {
        // Reserve input ownership before the exact composer proof. The shared
        // command sender normally advances this revision itself; startup does
        // it here so its empty/exact evidence is not made stale between the
        // preparation and the eventual paste.
        bumpTerminalInputRevision(tabId);
        composerAdmission = await prepareClaudeStartupComposer({
          tabId,
          generation,
          lease,
          term: terminals.get(tabId),
          retryCommand: command,
          retryRecovery: recovery,
        });
        if (composerAdmission?.ready !== true) {
          if (composerAdmission?.retryAdmission === true) {
            console.log('[StartupTx] prompt-admission-retry tab=' + String(tabId).slice(-12)
              + ' gen=' + generation
              + ' attempt=' + admissionAttempt
              + ' stage=composer-prepare'
              + ' reason=' + String(composerAdmission?.error || '-'));
            continue;
          }
          return {
            success: false,
            submitted: false,
            pasteWritten: false,
            error: composerAdmission?.error || 'claude_startup_composer_unresolved',
          };
        }
        lease = composerAdmission.lease || lease;
      }
      const submitExistingInput = recovery?.kind === 'submit-existing-input'
        || composerAdmission?.existingOwnedCommand === true;
      const result = submitExistingInput
        ? await inspectClaudeExactSettingInput(tabId, command, {
          submit: true,
          source: composerAdmission?.existingOwnedCommand === true
            ? source + ':restored-owned-command'
            : source,
          generation,
          startupPromptLease: lease,
        })
        : await sendClaudeCommandInternal(
          tabId,
          command,
          {
            source,
            // The launch prompt has no user-owned text yet: the pending user
            // message is held behind this gate. Avoiding Ctrl+S keeps the prompt
            // lease meaningful up to the actual paste boundary. A real native
            // draft was already moved into Claude's own stash by the
            // generation-owned preparation above.
            stashFirst: false,
            armPromptBoundaryOnSubmit: true,
            startupPromptLease: lease,
            startupExactEmptyEvidence: composerAdmission?.exactEmptyEvidence || null,
            verifyClaudeVisibleDraftBeforePaste: true,
            inputRevisionAlreadyReserved: true,
          },
        );
      if (
        result?.error === 'claude_prompt_not_stable'
        && result?.pasteWritten !== true
      ) {
        // Admission changed before any bytes reached Claude. This is not a
        // delivery retry and consumes none of the transaction's one safe
        // retry allowance; wait event-driven for the next exact prompt lease.
        console.log('[StartupTx] prompt-admission-retry tab=' + String(tabId).slice(-12)
          + ' gen=' + generation
          + ' attempt=' + admissionAttempt
          + ' stage=before-paste'
          + ' reason=' + String(result.reason || '-'));
        continue;
      }
      if (
        result?.error === 'claude_prompt_not_stable'
        && result?.pasteWritten === true
      ) {
        // Bytes are present but Enter was withheld. Delivery is not guessed:
        // the transaction's normal proof step checks the exact current input.
        // Only that exact ABSENT proof may spend the one automatic retry.
        return {
          ...result,
          success: true,
          submitted: false,
          reason: result.reason || 'startup-command-held-before-enter',
        };
      }
      return result;
    }
    return {
      success: false,
      submitted: false,
      pasteWritten: false,
      error: 'claude_prompt_not_stable',
      reason: 'stale-generation',
    };
  },
  proveCommand: (context) => waitForClaudeStartupSlashProofInMain(context),
  publishGate: (payload) => publishClaudeStartupDefaultsGate(
    payload,
    { notifyRenderer: true },
  ),
});

function ensureClaudeStartupSettingsInMain(tabId, generation, trigger, sessionIdHint = null) {
  try {
    return claudeStartupMainRuntime.ensure({
      tabId,
      generation,
      trigger,
      sessionIdHint,
    });
  } catch (error) {
    console.error('[StartupTx] ensure failed tab=' + String(tabId).slice(-12)
      + ' gen=' + String(generation || '-')
      + ' trigger=' + String(trigger || '-')
      + ' error=' + (error?.message || String(error)));
    return { started: false, reason: 'ensure-failed', promise: Promise.resolve(null) };
  }
}

function beginClaudeLaunchGeneration(
  tabId,
  pid,
  reason = 'process-started',
  {
    launchMode = 'unknown',
    sessionIdHint = null,
  } = {},
) {
  if (!tabId) return null;
  const previous = claudeLaunchGenerationByTab.get(tabId) || null;
  claudeLaunchGenerationSeq += 1;
  const generation = 'claude-launch-' + claudeLaunchGenerationSeq;
  claudeLaunchGenerationByTab.set(tabId, {
    generation,
    pid: pid || null,
    at: Date.now(),
    launchMode,
    sessionIdHint: sessionIdHint || null,
  });
  if (previous?.generation) {
    claudeStartupProofSession?.cancel(
      tabId,
      previous.generation,
      'generation-superseded',
    );
    aiBoundaryTestGate.cancelMatching({
      tabId,
      generation: previous.generation,
    }, 'claude-launch-generation-superseded');
  }
  claudePendingPromptDispatchers.delete(tabId);
  claudeTrustFolderPromptHintTabs.delete(tabId);
  claudeTrustFolderPromptHintBuffers.delete(tabId);
  claudeTrustFolderPromptFired.delete(tabId);
  claudeTrustFolderPromptInflight.delete(tabId);
  claudePromptStability.open(tabId, generation, reason);
  console.log('[StartupTx] generation-open tab=' + String(tabId).slice(-12)
    + ' gen=' + generation
    + ' pid=' + (pid || '-')
    + ' reason=' + reason
    + ' launchMode=' + launchMode
    + ' session=' + (sessionIdHint ? String(sessionIdHint).slice(0, 8) : '-'));
  return generation;
}

// Readiness can arrive before we ever saw a bridge PID (tui-ready fires 2-6s
// earlier in prod). Normal launches already have a generation at their shell
// command boundary. This fallback preserves aliases/older integrations while
// still making both readiness signals join the same transaction.
function ensureClaudeLaunchGeneration(tabId, pid, reason) {
  const existing = claudeLaunchGenerationByTab.get(tabId);
  if (existing) {
    if (pid && !existing.pid) existing.pid = pid;
    // A different live PID means a genuinely new launch (manual relaunch in the
    // shell, restart) even if we never observed the old one exiting.
    if (pid && existing.pid && existing.pid !== pid) {
      return beginClaudeLaunchGeneration(tabId, pid, reason + ':pid-change');
    }
    return existing.generation;
  }
  return beginClaudeLaunchGeneration(tabId, pid, reason);
}

function clearClaudeLaunchGeneration(tabId, reason = 'process-exit') {
  const existing = claudeLaunchGenerationByTab.get(tabId);
  claudeStartupIntentUseByTab.delete(tabId);
  claudePendingPromptDispatchers.delete(tabId);
  // The onboarding hint is scoped to one live Claude process. If that process
  // exits before the modal is dismissed, retaining the hint would suppress
  // readiness for the next launch in the same PTY tab.
  claudeAutoModeDefaultPromptHintTabs.delete(tabId);
  claudeAutoModeDefaultPromptHintBuffers.delete(tabId);
  claudeTrustFolderPromptHintTabs.delete(tabId);
  claudeTrustFolderPromptHintBuffers.delete(tabId);
  claudeTrustFolderPromptFired.delete(tabId);
  claudeTrustFolderPromptInflight.delete(tabId);
  clearClaudePtyCompactProofAttempt(
    tabId,
    undefined,
    'launch-generation-clear:' + reason,
  );
  if (!existing) {
    claudeStartupProofSession?.cancel(tabId, null, reason);
    claudePromptStability.clear(tabId, null, reason);
    return;
  }
  claudeLaunchGenerationByTab.delete(tabId);
  claudeStartupProofSession?.cancel(tabId, existing.generation, reason);
  claudePromptStability.clear(tabId, existing.generation, reason);
  claudeStartupMainRuntime.clear(tabId, reason);
  console.log('[StartupTx] generation-clear tab=' + String(tabId).slice(-12)
    + ' gen=' + existing.generation + ' reason=' + reason);
  emitAgentReadinessChanged(tabId, { toolType: 'claude', status: 'inactive', reason });
}

function readClaudeStartupIntent(tabId) {
  return normalizeClaudeStartupIntent(getProviderState(tabId));
}

function rememberClaudeStartupIntentUse(tabId, generation, intent) {
  if (!tabId || !generation || !intent) return;
  claudeStartupIntentUseByTab.set(tabId, {
    generation,
    model: intent.model,
    effort: intent.effort,
  });
}

function consumeClaudeStartupIntent(tabId, generation) {
  const used = claudeStartupIntentUseByTab.get(tabId) || null;
  if (!used || used.generation !== generation) return false;
  const current = { ...getProviderState(tabId) };
  const pending = normalizeClaudeStartupIntent(current);
  if (!pending || pending.model !== used.model || pending.effort !== used.effort) {
    claudeStartupIntentUseByTab.delete(tabId);
    return false;
  }
  delete current.startupModel;
  delete current.startupEffort;
  setProviderState(tabId, current);
  if (tabId && projectManager?.db) {
    projectManager.db.updateTabProviderState(tabId, current);
  }
  claudeStartupIntentUseByTab.delete(tabId);
  broadcastProviderState(tabId, current);
  console.log('[StartupTx] intent-consumed tab=' + String(tabId).slice(-12)
    + ' gen=' + generation
    + ' model=' + used.model
    + ' effort=' + used.effort);
  return true;
}
const bridgeMetadata = new Map(); // tabId → { model, contextPct }
const bridgePidCache = new Map(); // claudePid → tabId
// Hook routing can prebind bridgePidCache before statusLine writes its first
// file. Process-start readiness therefore needs independent once-per-process
// ownership; using the route cache as the sentinel suppresses Bridge:Fresh and
// silently removes the second input to the startup transaction.
const claudeBridgeProcessStarts = createClaudeBridgeProcessStartTracker();
const bridgeFileMtimes = new Map(); // filename → mtimeMs
const bridgeStaleLogged = new Set(); // filenames we've already warned about (dedupe spam)
const BRIDGE_STALE_SECONDS = 600; // bridge.json older than this = stale process, skip
const CLAUDE_PENDING_JSONL_OWNER_TTL_MS = 30 * 1000;
const claudePendingJsonlOwners = new Map(); // lowerSessionId → { tabId, since, source }
const CLAUDE_SESSION_ID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let bridgeWatcher = null;
let bridgePollInterval = null;

function claudeSessionKey(sessionId) {
  return sessionId ? String(sessionId).toLowerCase() : null;
}

function pruneClaudePendingJsonlOwners(now = Date.now()) {
  for (const [sid, owner] of claudePendingJsonlOwners) {
    if (!owner || (now - owner.since) > CLAUDE_PENDING_JSONL_OWNER_TTL_MS || !terminals.has(owner.tabId)) {
      claudePendingJsonlOwners.delete(sid);
    }
  }
}

function markClaudePendingJsonlOwner(sessionId, tabId, source) {
  const key = claudeSessionKey(sessionId);
  if (!key || !tabId) return false;
  pruneClaudePendingJsonlOwners();
  const prev = claudePendingJsonlOwners.get(key);
  if (prev && prev.tabId !== tabId) {
    console.warn('[ClaudeJsonlOwner] pending collision session=' + key.slice(0, 8) +
      ' existingTab=' + String(prev.tabId).slice(-12) +
      ' newTab=' + String(tabId).slice(-12) +
      ' source=' + (source || 'unknown'));
    return false;
  }
  claudePendingJsonlOwners.set(key, { tabId, since: Date.now(), source: source || 'unknown' });
  if (!prev || prev.tabId !== tabId) {
    console.log('[ClaudeJsonlOwner] pending session=' + key.slice(0, 8) + ' tab=' + String(tabId).slice(-12) + ' source=' + (source || 'unknown'));
  }
  return true;
}

function clearClaudePendingJsonlOwner(sessionId, tabId, reason) {
  const key = claudeSessionKey(sessionId);
  if (!key) return;
  const owner = claudePendingJsonlOwners.get(key);
  if (!owner) return;
  if (tabId && owner.tabId !== tabId) return;
  claudePendingJsonlOwners.delete(key);
  console.log('[ClaudeJsonlOwner] pending cleared session=' + key.slice(0, 8) + ' tab=' + String(owner.tabId).slice(-12) + ' reason=' + (reason || 'unknown'));
}

function clearClaudePendingJsonlOwnersForTab(tabId, reason) {
  if (!tabId) return;
  for (const [sid, owner] of claudePendingJsonlOwners) {
    if (owner?.tabId === tabId) {
      claudePendingJsonlOwners.delete(sid);
      console.log('[ClaudeJsonlOwner] pending cleared session=' + sid.slice(0, 8) + ' tab=' + String(tabId).slice(-12) + ' reason=' + (reason || 'unknown'));
    }
  }
}

function isClaudeProcessRunningInTab(tabId) {
  if (!tabId) return false;
  const commandState = terminalCommandState.get(tabId) || null;
  return claudeCliActive.get(tabId) === true
    || !!findClaudePidByTab(tabId)
    || (bridgeKnownSessions.has(tabId) && commandState?.isRunning === true);
}

function getClaudeJsonlLiveOwner(sessionId, callerTabId = null) {
  const target = claudeSessionKey(sessionId);
  if (!target) return null;
  pruneClaudePendingJsonlOwners();
  const pending = claudePendingJsonlOwners.get(target);
  if (pending) {
    return { tabId: pending.tabId, reason: 'pending-resume', source: pending.source, since: pending.since };
  }
  for (const [ownerTabId, sid] of bridgeKnownSessions) {
    if (claudeSessionKey(sid) === target && isClaudeProcessRunningInTab(ownerTabId)) {
      return { tabId: ownerTabId, reason: 'live-bridge' };
    }
  }
  for (const [ownerTabId, state] of aiStoppingTabs) {
    if (state?.toolType === 'claude' && claudeSessionKey(state?.sessionId) === target) {
      return { tabId: ownerTabId, reason: 'stopping' };
    }
  }
  if (callerTabId && isClaudeProcessRunningInTab(callerTabId)) {
    return { tabId: callerTabId, reason: 'caller-process-active' };
  }
  return null;
}

const { classifyClaudeProcessCommand, claudeProcessSessionArgument } = require(path.join(srcMainDir, 'claude-process-command'));

function looksLikeClaudeProcessCommand(commandLine) {
  return commandLooksLikeAiProcess(commandLine, 'claude');
}

async function getClaudeJsonlExternalOwner(sessionId, cwd = null) {
  const target = claudeSessionKey(sessionId);
  if (!target || !CLAUDE_SESSION_ID_RE.test(target)) return null;
  let processSnapshot = null;

  // Cross-process guard #1: a real CLI entrypoint with an exact session argv.
  // This catches another Noted Terminal instance and manual shell starts before
  // this instance has any bridgeKnownSessions state. Reuse the app-wide
  // process-tree snapshot: four AutoResume calls must not spawn four `ps`
  // processes and then independently parse the same system state.
  try {
    processSnapshot = await getProcessTreeSnapshot({ forceFresh: true });
    for (const processInfo of processSnapshot.processesByPid.values()) {
      const command = String(processInfo?.cmd || '');
      const proof = claudeProcessSessionArgument(command, target);
      if (!proof) continue;
      console.warn('[ClaudeJsonlOwner] external writer session=' + target.slice(0, 8)
        + ' pid=' + processInfo.pid + ' proofKind=' + proof.proofKind);
      return {
        tabId: null,
        reason: 'external-ps-resume',
        pid: processInfo.pid,
        ppid: processInfo.ppid,
        proofKind: proof.proofKind,
      };
    }
  } catch (e) {
    console.warn('[ClaudeJsonlOwner] external ps check failed session=' + target.slice(0, 8) + ': ' + (e?.message || String(e)));
  }

  // Cross-process guard #2: Claude statusline bridge is global under ~/.claude.
  // The statusline contract writes exactly `<session_id>.json`. The previous
  // implementation read every historical file in the directory for every
  // Resume (2,150 files on the incident machine), even though the target name
  // was already known. Four concurrent Claude restores therefore spent
  // 36–38 seconds walking the same tombstones. Read only the exact identity.
  try {
    const filename = target + '.json';
    const filePath = path.join(bridgeDir, filename);
    let data = null;
    try {
      data = JSON.parse(await fs.promises.readFile(filePath, 'utf8'));
    } catch (error) {
      if (error?.code === 'ENOENT') return null;
      throw error;
    }
    const nowSec = Math.floor(Date.now() / 1000);
    if (claudeSessionKey(data?.session_id) !== target) return null;
    if (data.transcript_path && !fs.existsSync(data.transcript_path)) return null;
    if (typeof data.updated_at === 'number' && (nowSec - data.updated_at) > BRIDGE_STALE_SECONDS) return null;
    const pid = Number(data.ppid);
    if (!Number.isFinite(pid) || pid <= 0) return null;
    try {
      processSnapshot = processSnapshot || await getProcessTreeSnapshot({ forceFresh: true });
      const processInfo = processSnapshot.processesByPid.get(pid) || null;
      if (processInfo && looksLikeClaudeProcessCommand(processInfo.cmd)) {
        const proofKind = 'exact-session-bridge:' + classifyClaudeProcessCommand(processInfo.cmd).proofKind;
        console.warn('[ClaudeJsonlOwner] external writer session=' + target.slice(0, 8)
          + ' pid=' + pid + ' proofKind=' + proofKind);
        return { tabId: null, reason: 'external-bridge', pid, bridgeFile: filename, proofKind };
      }
    } catch (error) {
      console.warn('[ClaudeJsonlOwner] exact bridge PID check failed session=' + target.slice(0, 8)
        + ': ' + (error?.message || String(error)));
    }
  } catch (e) {
    console.warn('[ClaudeJsonlOwner] external bridge check failed session=' + target.slice(0, 8) + ': ' + (e?.message || String(e)));
  }

  return null;
}

function captureClaudeFirstAcceptedBridge(tabId, pid, isFreshProcess) {
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const terminalToken = terminals.get(tabId) || null;
  const runSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const numericPid = Number(pid);
  if (isFreshProcess !== true || launch?.launchMode !== 'resume'
    || !launch.sessionIdHint || !launch.generation || launch.firstAcceptedBridge
    || !terminalToken || !Number.isInteger(runSeq) || runSeq <= 0 || !lifecycleGeneration
    || !Number.isInteger(numericPid) || numericPid <= 0 || Number(launch.pid) !== numericPid
    || bridgePidCache.get(numericPid) !== tabId) return null;
  return {
    launch, generation: launch.generation, pid: numericPid, terminalToken,
    runSeq, lifecycleGeneration,
    previousBridgeSessionId: bridgeKnownSessions.get(tabId) || null,
  };
}

function pinClaudeFirstAcceptedBridge(tabId, sessionId, captured) {
  if (!captured || !sessionId) return false;
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const currentBridgeSessionId = bridgeKnownSessions.get(tabId) || null;
  if (launch !== captured.launch || launch.firstAcceptedBridge
    || launch.generation !== captured.generation || Number(launch.pid) !== captured.pid
    || terminals.get(tabId) !== captured.terminalToken
    || Number(terminalCommandState.get(tabId)?.runSeq || 0) !== captured.runSeq
    || getTerminalLifecycleGeneration(tabId) !== captured.lifecycleGeneration
    || bridgePidCache.get(captured.pid) !== tabId
    || (currentBridgeSessionId !== captured.previousBridgeSessionId && currentBridgeSessionId !== sessionId)) return false;
  launch.firstAcceptedBridge = Object.freeze({
    sessionId, pid: captured.pid, terminalToken: captured.terminalToken,
    runSeq: captured.runSeq, lifecycleGeneration: captured.lifecycleGeneration,
    generation: captured.generation,
  });
  console.log('[Bridge:ResumeInitialWriter] tab=' + String(tabId).slice(-12)
    + ' generation=' + captured.generation + ' pid=' + captured.pid
    + ' source=' + String(launch.sessionIdHint).slice(0, 8)
    + ' writer=' + String(sessionId).slice(0, 8));
  return true;
}

function startSessionBridge() {
  try { fs.mkdirSync(bridgeDir, { recursive: true }); } catch {}

  const processFile = async (filename) => {
    const filePath = path.join(bridgeDir, filename);
    try {
      const stat = fs.statSync(filePath);
      if (bridgeFileMtimes.get(filename) === stat.mtimeMs) return;
      bridgeFileMtimes.set(filename, stat.mtimeMs);

      const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
      if (!data.session_id || !data.ppid) return;

      // === LIVENESS CHECKS (skip stale bridge.json from long-dead claude processes) ===
      // Claude CLI does NOT clean up its bridge.json on exit — files in ~/.claude/bridge/
      // can be months old. If we naively trust them, PID reuse + path-prefix tolerance
      // can stomp on a freshly-resumed tab with an ancient sessionId. Two cheap probes:
      //
      // 1. transcript file existence — if Claude wrote bridge.json the JSONL must exist
      //    on disk; missing = bridge.json is a tombstone from a deleted/cleaned session.
      // 2. updated_at freshness — anything older than 10 minutes is from a stale process;
      //    a live Claude rewrites bridge.json after every assistant turn.
      //
      // Both probes are file-system stat calls; no API/CLI calls, no flakiness.
      // See docs/knowledge/fix-bridge-stale-takeover.md for full incident report.
      if (data.transcript_path && !fs.existsSync(data.transcript_path)) {
        if (!bridgeStaleLogged.has(filename)) {
          bridgeStaleLogged.add(filename);
          console.warn('[Bridge:DeadTranscript] ' + filename + ' references missing JSONL (' + (data.transcript_path || '?') + ') — ignoring forever');
        }
        return;
      }
      const nowSec = Math.floor(Date.now() / 1000);
      if (typeof data.updated_at === 'number' && (nowSec - data.updated_at) > BRIDGE_STALE_SECONDS) {
        if (!bridgeStaleLogged.has(filename)) {
          bridgeStaleLogged.add(filename);
          const ageMin = Math.round((nowSec - data.updated_at) / 60);
          console.warn('[Bridge:StaleSkip] ' + filename + ' updated_at=' + data.updated_at + ' (' + ageMin + ' min ago) — ignoring until file is rewritten by live claude');
        }
        return;
      }

      // Check PID cache first
      let tabId = bridgePidCache.get(data.ppid);
      let pidSource = tabId ? 'cache' : 'resolve';

      if (!tabId) {
        // Resolve Claude PID → parent (shell PID) → match to our PTY.
        // Verify the PID is actually a claude process (not a PID-reuse coincidence)
        // by inspecting both `command=` (process name) and `ppid=`. If the kernel
        // has recycled this PID for a non-claude binary, command-name guard rejects.
        try {
          const psOut = await execAsync('ps -p ' + data.ppid + ' -o ppid=,command=');
          const trimmed = psOut.trim();
          if (!trimmed) return; // process gone — bridge.json points to dead PID
          const m = trimmed.match(/^(\d+)\s+(.+)$/);
          if (!m) return;
          const shellPid = parseInt(m[1], 10);
          const commandLine = m[2];
          // Accept anything resembling claude (handles full paths, "node /…/claude.js", aliases).
          if (!/(^|\/)claude(\b|[^a-zA-Z])/i.test(commandLine) && !/claude/i.test(commandLine)) {
            console.warn('[Bridge:NotClaude] ppid=' + data.ppid + ' command="' + commandLine + '" — PID reuse, ignoring bridge file');
            return;
          }
          for (const [tid, pty] of terminals) {
            if (pty.pid === shellPid) { tabId = tid; break; }
          }
          if (tabId) {
            bridgePidCache.set(data.ppid, tabId);
          }
        } catch {}
      }

      if (!tabId) return; // Not our process
      // `bridgePidCache` may already contain this PID because safe paste
      // prebound the UserPromptSubmit hook route. That is routing knowledge,
      // not proof that Bridge:Fresh was emitted. Claim the first statusLine
      // observation independently so process-started always joins the launch
      // transaction exactly once.
      const isFreshProcess = claudeBridgeProcessStarts.claim(data.ppid, tabId);

      // Notify renderer once per fresh Claude process. Lands BEFORE session-detected
      // so handlers can correlate "new PID + same/different sessionId".
      if (isFreshProcess) {
        console.log('[Bridge:Fresh] tab=' + tabId.slice(-12) + ' claudePid=' + data.ppid + ' session=' + data.session_id.slice(0, 8));
        // Main owns the transaction. The bridge and TUI prompt are readiness
        // inputs for the same launch generation; renderer only observes state.
        const launchGeneration = ensureClaudeLaunchGeneration(tabId, data.ppid, 'bridge-fresh');
        // [EffortDiag2026-05] main-side emit log — written synchronously here,
        // not relayed through renderer. If renderer logs show only 1 [Terminal:EffortInject]
        // but main shows 2 [Bridge:Fresh] for the same tab, processFile entered
        // the isFreshProcess branch twice (PID cache miss twice).
        console.warn('[EffortDiag2026-05][MAIN-EMIT] tab=' + tabId.slice(-12) + ' claudePid=' + data.ppid + ' sessionId=' + data.session_id.slice(0, 8) + ' ts=' + Date.now());
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('claude:process-started', {
            tabId, sessionId: data.session_id, claudePid: data.ppid, launchGeneration,
          });
        }
        ensureClaudeStartupSettingsInMain(
          tabId,
          launchGeneration,
          'process-started',
          data.session_id,
        );
      }
      // Only this first process observation can prove the accepted Resume's
      // initial writer. Later same-PID /resume updates must never replace it,
      // even if they overtake this callback while quota persistence awaits.
      const firstAcceptedBridgeScope = captureClaudeFirstAcceptedBridge(tabId, data.ppid, isFreshProcess);

      // CWD guard: don't overwrite tab session if the detected session belongs to a different cwd.
      // Happens when user runs `claude --resume <foreignId>` in tab "X" — Claude finds the session
      // file in OTHER project's slug, but PID resolves to tab "X" → bridge would slap foreign sessionId
      // on the wrong tab. Compare bridge.cwd to tab's PTY cwd; mismatch = wrong-project resume.
      //
      // Path-prefix tolerance: user may `cd` inside the shell (up to a parent dir, or down into a
      // subdir) before running `claude`. Bridge cwd then differs from tab cwd, but it's still the
      // same filesystem branch — not a foreign project. Allow if one path is ancestor of the other.
      const tabCwd = terminalProjects.get(tabId);
      if (data.cwd && tabCwd && data.cwd !== tabCwd) {
        const relation = await resolveDirectoryRelation(data.cwd, tabCwd);
        if (!relation.related) {
          const known = bridgeKnownSessions.get(tabId);
          if (known !== data.session_id) {
            console.warn('[Bridge:CwdGuard] Skip overwrite: tab cwd=' + tabCwd + ' but bridge cwd=' + data.cwd + ' (sid=' + data.session_id.substring(0, 8) + '...) — paths unrelated');
            // Renderer-side persistence still fires. CwdGuard's job is to prevent
            // `terminalProjects.set` and `bridgeKnownSessions.set` (those are the
            // takeover vectors — see fix-bridge-stale-takeover.md). But the *renderer*
            // needs sessionId to land in Tab.claudeSessionId or the tab forgets its
            // session across app restart. PID resolution already proved this PTY's
            // shell parents the live Claude → safe to tell renderer. We just don't
            // mutate main-side caches.
            if (mainWindow && !mainWindow.isDestroyed()) {
              mainWindow.webContents.send('claude:session-detected', { tabId, sessionId: data.session_id });
            }
            _notifyClaudeSession(tabId, data.session_id);
          }
          return;
        }
        // Related path (cd up/down within same branch) — accept for THIS update.
        // Do NOT overwrite terminalProjects: when a stale bridge.json sneaks past
        // the freshness/transcript guards, leaving the canonical tab cwd intact
        // means subsequent checks still compare against the right project.
        // See docs/knowledge/fix-bridge-stale-takeover.md.
        console.log('[Bridge:CwdGuard] Path drift OK (tab=' + tabCwd + ' bridge=' + data.cwd
          + ' canonical=' + relation.canonicalized + ') — accepted for this update, tab cwd preserved');
      }

      // Commit Claude Code's official statusLine quota snapshot before the
      // existing bridge-update event reaches renderer. The event can then
      // trigger an immediate IPC read without racing this write.
      if (data.rate_limits) {
        try {
          await require(path.join(srcMainDir, 'ipc', 'claude-usage')).recordStatuslineUsage(data);
        } catch (e) {
          console.warn('[ClaudeUsage] statusline bridge record failed:', e?.message || String(e));
        }
      }
      // CwdGuard has accepted this bridge. Recheck the exact captured launch,
      // PTY and run after the await before granting source -> writer authority.
      pinClaudeFirstAcceptedBridge(tabId, data.session_id, firstAcceptedBridgeScope);

      // Debug: log PID chain resolution for session detection
      const knownForTab = bridgeKnownSessions.get(tabId);
      if (knownForTab !== data.session_id) {
        console.log('[Bridge:PID] session=' + data.session_id.substring(0, 8) + '... claudePid=' + data.ppid + ' → tab=' + tabId + ' (via ' + pidSource + ') | was=' + (knownForTab ? knownForTab.substring(0, 8) + '...' : 'none'));
      }

      const bridgeContextPct = normalizeAuthoritativeContextPct(data.context_pct);
      const contextSnapshot = commitAgentContextUsage({
        tabId,
        provider: 'claude',
        sessionId: data.session_id,
        contextPct: bridgeContextPct,
        source: 'statusline',
      });

      // Cache bridge metadata for use in sub-agent responses. Missing context
      // stays null; an authoritative zero is a real compact/clear update.
      bridgeMetadata.set(tabId, {
        model: data.model || 'unknown',
        contextPct: contextSnapshot?.contextPct ?? null,
      });

      // Always send bridge metadata (model, context) on every update
      if (mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('claude:bridge-update', {
          tabId,
          sessionId: data.session_id,
          model: data.model || 'unknown',
          contextPct: contextSnapshot?.contextPct ?? null
        });
      }
      // Mirror to mobile-web subscribers so the phone's header pill updates
      // model + context% live (otherwise mobile only sees these via the next
      // /params fetch, which is on-open only).
      _webBroadcast(tabId, {
        type: 'bridge-update',
        sessionId: data.session_id,
        model: data.model || 'unknown',
        contextPct: contextSnapshot?.contextPct ?? null,
      });

      // Check for session change
      const oldSessionId = bridgeKnownSessions.get(tabId);
      if (oldSessionId === data.session_id) {
        claudeStartupIntents.delete(tabId);
        // The observer is main-owned and idempotent. Reasserting it on the
        // bridge heartbeat repairs a missed initial subscription without
        // making History visibility part of background-agent liveness.
        void ensureClaudeBackgroundActivityObserver(
          tabId,
          data.session_id,
          terminalProjects.get(tabId) || data.cwd || null,
        );
        return;
      }

      bridgeKnownSessions.set(tabId, data.session_id);
      void tabWorkContext.syncLinks().catch((error) => {
        console.warn('[TabContext] Claude source sync:', error.message);
      });
      void ensureClaudeBackgroundActivityObserver(
        tabId,
        data.session_id,
        terminalProjects.get(tabId) || data.cwd || null,
      );
      claudeStartupIntents.delete(tabId);
      clearClaudePendingJsonlOwner(data.session_id, tabId, 'bridge-detected');
      console.log('[Bridge] Tab', tabId, '-> session:', data.session_id.substring(0, 8) + '...', '(model:', data.model + ', ctx:', data.context_pct + '%)');
      emitClaudeTuiReadyFromVisibleBuffer(tabId, 'bridge-fresh').catch((err) => {
        console.log('[TUI-Ready] tab=' + String(tabId).slice(-12) +
          ' — visible-buffer fallback failed source=bridge-fresh err=' + (err?.message || err));
      });

      // Save session link for Clear Context chain resolution (old → new)
      if (oldSessionId) {
        console.log('[Bridge] Session transition:', oldSessionId.substring(0, 8) + '...', '→', data.session_id.substring(0, 8) + '...');
        try {
          projectManager.db.saveSessionLink(oldSessionId, data.session_id);
        } catch (e) {
          console.error('[Bridge] Failed to save session link:', e.message);
        }
      }

      if (mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('claude:session-detected', { tabId, sessionId: data.session_id });
      }
      _notifyClaudeSession(tabId, data.session_id);
    } catch {}
  };

  const scan = async () => {
    try {
      const files = fs.readdirSync(bridgeDir).filter(f => f.endsWith('.json') && !f.startsWith('_'));
      for (const f of files) await processFile(f);
    } catch {}
  };

  // Method 1: fs.watch for instant detection
  try {
    bridgeWatcher = fs.watch(bridgeDir, (eventType, filename) => {
      if (filename?.endsWith('.json') && !filename.startsWith('_')) {
        processFile(filename);
      }
    });
    console.log('[Bridge] fs.watch active on', bridgeDir);
  } catch (e) {
    console.log('[Bridge] fs.watch failed:', e.message);
  }

  // Method 2: polling every 2s (reliable fallback)
  bridgePollInterval = setInterval(scan, 2000);
  console.log('[Bridge] Polling active (2s interval)');

  // Initial scan
  scan();
}

function stopSessionBridge() {
  if (bridgeWatcher) { try { bridgeWatcher.close(); } catch {} bridgeWatcher = null; }
  if (bridgePollInterval) { clearInterval(bridgePollInterval); bridgePollInterval = null; }
}

function clearBridgeTab(tabId, reason = 'process_exited') {
  const had = bridgeKnownSessions.has(tabId);
  const wasTurnBusy = claudeTurnBusy.get(tabId) === true;
  const wasSpinnerBusy = claudeSpinnerBusy.get(tabId) === true;
  const wasLocalBusy = claudeLocalCommandWatchers.has(tabId);
  if (wasTurnBusy) emitClaudeAbnormalTurnEnd(tabId, reason);
  clearClaudeEditableLastPrompt(tabId, 'bridge-clear');
  const questionExit = clearClaudeQuestionStateOnProcessExit({
    tabId,
    awaitingByTab: claudeAwaitingInput,
    pendingQuestionByTab: claudePendingQuestion,
  });
  if (questionExit.wasAwaiting && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
  }
  if (questionExit.hadPendingQuestion) {
    _webBroadcast(tabId, { type: 'question-cancelled', source: 'pty' });
  }
  if (questionExit.changed) {
    console.log('[ClaudeQuestion] process-exit clear tab=' + String(tabId).slice(-12)
      + ' awaiting=' + questionExit.wasAwaiting
      + ' pending=' + questionExit.hadPendingQuestion);
  }
  bridgeKnownSessions.delete(tabId);
  if (had) {
    void tabWorkContext.syncLinks().catch((error) => {
      console.warn('[TabContext] Claude source clear:', error.message);
    });
  }
  clearClaudeBackgroundActivityObserver(tabId, 'bridge-clear');
  claudeStartupIntents.delete(tabId);
  claudeStartupDefaultsGateByTab.delete(tabId);
  clearClaudePendingJsonlOwnersForTab(tabId, 'bridge-clear');
  // Claude TUI gone — prompt is no longer rendered. Mobile should flip back
  // to "inactive" so the Resume banner shows and the composer/busy spinner
  // resets. Broadcast on ANY transition out of a known-session state — not
  // only when claudePromptReady was set. The earlier guard `if
  // (claudePromptReady.delete(tabId))` missed the case where Claude exited
  // mid-thinking (no ⏵ rendered yet → flag never set), leaving mobile stuck
  // in busy with no way to reach Resume. Also broadcast busy=false so the
  // mobile composer's loader resets regardless of which event ordering wins.
  claudePromptReady.delete(tabId);
  claudeAutoModeDefaultPromptHintTabs.delete(tabId);
  claudeAutoModeDefaultPromptHintBuffers.delete(tabId);
  clearClaudeLaunchGeneration(tabId, 'bridge-clear');
  if (had) {
    console.log('[MobBcast] busy+snapshot tab=' + String(tabId).slice(-12) + ' busy=false status=inactive src=clearBridgeTab');
    _webBroadcast(tabId, { type: 'busy', busy: false });
    _webBroadcast(tabId, { type: 'snapshot', sessionId: null, busy: false, sessionStatus: 'inactive', inputReady: false });
  }
  promptBoundaryState.delete(tabId);
  // Do not reset promptBoundarySeq on Claude exit. The renderer keeps existing
  // OSC markers in the xterm buffer for this tab; restarting from #1 makes the
  // next marker look stale/duplicate and any waitForPromptBoundaryAfter() call
  // times out. Sequence lifetime is the tab/buffer, not the Claude process.
  escapeCarryover.delete(tabId);
  for (const [pid, tid] of bridgePidCache) {
    if (tid === tabId) bridgePidCache.delete(pid);
  }
  claudeBridgeProcessStarts.clearTab(tabId);
  // Drop stale turn state for this tab so a reused tabId doesn't inherit "busy"
  claudeTurnBusy.delete(tabId);
  wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, 'bridge-clear');
  clearClaudeProviderFatalTurnWatch(tabId, 'bridge-clear');
  clearTimeout(claudeTurnWatchdog.get(tabId));
  claudeTurnWatchdog.delete(tabId);
  claudeSpinnerLastSeenAt.delete(tabId);
  finalizeClaudePasteAuditsOnBridgeClear(tabId);
  stopInterruptWatcher(tabId);
  stopClaudeLocalCommandWatcher(tabId, 'bridge-clear');
  claudeInputLineBuffers.delete(tabId);
  if (wasTurnBusy || wasSpinnerBusy || wasLocalBusy) {
    const reason = wasLocalBusy ? 'local-command' : 'command-finished';
    console.warn('[Bridge:ClearBusy] tab=' + tabId.slice(-12) +
      ' reason=' + reason +
      ' turnBusy=' + wasTurnBusy +
      ' spinnerBusy=' + wasSpinnerBusy +
      ' localBusy=' + wasLocalBusy);
    clearTimeout(claudeSpinnerIdleTimer.get(tabId));
    claudeSpinnerIdleTimer.delete(tabId);
    emitClaudeBusyState(tabId, false, reason);
  }
  // Claude retirement must not clear a newer Codex capture in the same tab.
  // Actual PTY teardown retires every provider owned by that terminal.
  retireAgentInputCaptureForProcess(
    tabId,
    reason === 'pty-exit' || reason === 'terminal-kill' ? null : 'claude',
    reason,
  );
  if (had) {
    console.log('[Bridge:Clear] Tab ' + tabId.slice(-12) + ' removed from bridgeKnownSessions (remaining=' + bridgeKnownSessions.size + ')');
  }
}

async function emitClaudeTuiReadyFromVisibleBuffer(tabId, source) {
  if (!tabId || claudePromptReady.has(tabId)) return false;
  if (!mainWindow || mainWindow.isDestroyed()) return false;
  const snapshot = await requestTerminalVisibleBufferSnapshot(
    mainWindow.webContents,
    tabId,
    'claude-tui-ready-' + source,
    700
  );
  if (!snapshot?.success || !Array.isArray(snapshot.lines)) {
    console.log('[TUI-Ready] tab=' + String(tabId).slice(-12) +
      ' — visible-buffer fallback skipped source=' + source +
      ' error=' + (snapshot?.error || 'bad-snapshot'));
    return false;
  }
  const visibleText = snapshot.lines.map((line) => line?.text || '').join('\n');
  if (
    claudeTrustFolderPromptHintTabs.has(tabId)
    || looksLikeClaudeTrustFolderPromptText(visibleText)
  ) {
    claudeTrustFolderPromptHintTabs.add(tabId);
    console.log('[TUI-Ready] tab=' + String(tabId).slice(-12)
      + ' — visible-buffer fallback blocked by folder trust prompt source=' + source);
    return false;
  }
  if (
    claudeAutoModeDefaultPromptHintTabs.has(tabId)
    || looksLikeClaudeAutoModeDefaultPromptText(visibleText)
  ) {
    claudeAutoModeDefaultPromptHintTabs.add(tabId);
    console.log('[TUI-Ready] tab=' + String(tabId).slice(-12)
      + ' — visible-buffer fallback blocked by auto-mode onboarding source=' + source);
    return false;
  }
  const rewindMenuVisible = looksLikeClaudeRewindMenuText(visibleText);
  const composerReady = hasClaudeComposerPromptGlyph(visibleText) || (hasClaudeAsciiComposerPrompt(visibleText) && !rewindMenuVisible);
  if (!composerReady) {
    console.log('[TUI-Ready] tab=' + String(tabId).slice(-12) +
      ' — visible-buffer fallback saw no prompt source=' + source +
      ' lines=' + snapshot.lines.length +
      ' rewindMenuVisible=' + rewindMenuVisible);
    return false;
  }
  publishClaudePromptReady(tabId, 'visible-buffer ' + source);
  return true;
}

function publishClaudePromptReady(tabId, reason = 'prompt-ready') {
  if (!tabId || claudePromptReady.has(tabId)) return false;
  if (claudeTrustFolderPromptHintTabs.has(tabId)) {
    console.log('[TUI-Ready] tab=' + String(tabId).slice(-12)
      + ' — blocked by folder trust prompt (' + reason + ')');
    return false;
  }
  if (claudeAutoModeDefaultPromptHintTabs.has(tabId)) {
    console.log('[TUI-Ready] tab=' + String(tabId).slice(-12)
      + ' — blocked by auto-mode onboarding (' + reason + ')');
    return false;
  }
  claudePromptReady.add(tabId);
  const turnBusy = !!claudeTurnBusy.get(tabId);
  // tui-ready usually lands BEFORE bridge.json exists. It joins the generation
  // opened by the accepted shell command; ensure() is only a compatibility
  // fallback when an older shell integration did not identify that command.
  const launchGeneration = ensureClaudeLaunchGeneration(tabId, null, 'tui-ready');
  agentLaunchPreparations.clearRejected(tabId, {
    toolType: 'claude',
    reason: 'claude-tui-ready',
  });
  console.log('[TUI-Ready] tab=' + String(tabId).slice(-12) +
    ' — emitting claude:tui-ready (' + reason + ')');
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('claude:tui-ready', { tabId, ts: Date.now(), launchGeneration });
  }
  ensureClaudeStartupSettingsInMain(tabId, launchGeneration, 'tui-ready');
  ipcMain.emit('agent:tui-ready-internal', null, { tabId, toolType: 'claude' });
  const startupGate = claudeStartupDefaultsGateByTab.get(tabId) || null;
  const startupReady = startupGate?.generation === launchGeneration
    && startupGate?.status === 'ready';
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId: bridgeKnownSessions.get(tabId) || null,
    busy: turnBusy,
    sessionStatus: startupReady ? (turnBusy ? 'busy' : 'active') : 'starting',
    starting: !startupReady,
    inputReady: startupReady,
    startupDefaultsPending: !startupReady,
    startupDefaultsReady: startupReady,
    toolType: 'claude',
    commandType: 'claude',
  });
  return true;
}

function persistCodexKnownSessionBinding(tabId, sessionId, settingsProof = null, {
  expectedBindingSessionId = null,
  lineageSourceSessionId = null,
  lineageEvent = null,
} = {}) {
  const projectId = resolveAuthoritativeTabProjectId(tabId);
  const normalizedEffort = typeof settingsProof?.effort === 'string'
    ? settingsProof.effort.trim().toLowerCase()
    : '';
  if (lineageEvent) {
    if (!projectId) {
      return { success: false, error: 'codex_tab_project_unresolved', retryable: true };
    }
    return projectManager?.db?.commitCodexWriterBindingWithLineage?.({
      projectId,
      tabId,
      sourceSessionId: lineageSourceSessionId,
      expectedBindingSessionId,
      nextSessionId: sessionId,
      lineageEvent,
      settingsProof: settingsProof && normalizedEffort !== 'ultra' ? settingsProof : null,
    }) || { success: false, error: 'codex_writer_lineage_persistence_unavailable', retryable: true };
  }
  if (settingsProof && normalizedEffort !== 'ultra') {
    if (!projectId) {
      return { success: false, error: 'codex_tab_project_unresolved', retryable: true };
    }
    try {
      const updated = projectManager?.db?.updateTabCodexSessionAndSettings?.(
        projectId,
        tabId,
        {
          sessionId,
          model: settingsProof.model,
          effort: normalizedEffort,
          proofAt: settingsProof.proofAt,
        },
      );
      return updated === true
        ? { success: true, updated: true, currentSessionId: sessionId }
        : { success: false, error: 'codex_writer_settings_not_committed', retryable: true };
    } catch (error) {
      return {
        success: false,
        error: error?.message || String(error),
        retryable: true,
      };
    }
  }
  return persistCodexWriterBinding({
    projectId,
    tabId,
    sessionId,
    readBinding: (scopedProjectId, scopedTabId) => (
      projectManager?.db?.getTabCodexSessionId?.(scopedProjectId, scopedTabId)
    ),
    writeBinding: (scopedProjectId, scopedTabId, nextSessionId) => (
      projectManager?.db?.updateTabCodexSessionId?.(scopedProjectId, scopedTabId, nextSessionId)
    ),
  });
}

function setCodexKnownSession(tabId, sessionId, reason = 'detected', proof = null, durableBinding = null) {
  if (!tabId || !sessionId) {
    return { success: false, error: 'codex_writer_identity_invalid', retryable: false };
  }
  const existingTierProof = codexTuiReadyMeta.get(tabId)?.serviceTierProof || null;
  const incomingLaunchId = String(proof?.launchId || '').trim();
  const currentTierLifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const serviceTierGenerationMode = incomingLaunchId ? 'launch' : 'terminal-run';
  const serviceTierGenerationId = incomingLaunchId || currentTierLifecycleGeneration;
  const serviceTierOwnerHandoff = authorizeCodexServiceTierProofOwnerHandoff(
    existingTierProof,
    {
      sourceOwnerId: incomingLaunchId
        ? 'launch:' + incomingLaunchId
        : currentTierLifecycleGeneration
          ? 'terminal-run:' + currentTierLifecycleGeneration
          : null,
      targetOwnerId: sessionId,
      terminalToken: terminals.get(tabId) || null,
      terminalLifecycleGeneration: currentTierLifecycleGeneration,
      terminalRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
      launchId: incomingLaunchId || null,
      generationMode: serviceTierGenerationMode,
      generationId: serviceTierGenerationId,
    },
  );
  const pendingSettingsProof = codexPendingSettingsProofHandoffs.get(tabId) || null;
  const pendingSettingsCarry = consumePendingCodexSettingsProofHandoff(
    pendingSettingsProof,
    {
      terminalToken: terminals.get(tabId) || null,
      runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
      launchId: proof?.launchId || null,
      writerSessionId: sessionId,
    },
  );
  const exactSettingsProofToPersist = pendingSettingsCarry.carry
    ? {
      ...pendingSettingsCarry.proof,
      ...(serviceTierOwnerHandoff.allowed
        ? { fast: serviceTierOwnerHandoff.proof.fast }
        : {}),
    }
    : null;
  const persisted = durableBinding?.success === true
    ? durableBinding
    : persistCodexKnownSessionBinding(
      tabId,
      sessionId,
      exactSettingsProofToPersist,
    );
  if (persisted?.success !== true) {
    console.warn('[Codex:Known] persist pending tab=' + String(tabId).slice(-12)
      + ' session=' + String(sessionId).slice(0, 8)
      + ' reason=' + reason
      + ' error=' + (persisted?.error || 'codex_writer_binding_not_committed'));
    return {
      success: false,
      error: persisted?.error || 'codex_writer_binding_not_committed',
      retryable: persisted?.retryable !== false,
    };
  }
  if (pendingSettingsProof) {
    codexPendingSettingsProofHandoffs.delete(tabId);
    console.log('[CodexSettingsProof] pre-rollout proof '
      + (pendingSettingsCarry.carry ? 'adopted' : 'discarded')
      + ' tab=' + String(tabId).slice(-12)
      + ' session=' + String(sessionId).slice(0, 8)
      + ' launch=' + (proof?.launchId || '-')
      + ' reason=' + pendingSettingsCarry.reason);
  }
  const prev = codexKnownSessions.get(tabId) || null;
  const prevProof = codexWriterProofs.get(tabId) || null;
  if (prev !== sessionId) {
    revokeCodexActionAuthoritiesForWriterAdoption(tabId, sessionId);
  }
  codexKnownSessions.set(tabId, sessionId);
  const proofRecord = {
    sessionId,
    kind: proof?.kind || 'event-proof',
    filePath: proof?.filePath || null,
    pids: Array.isArray(proof?.pids) ? proof.pids : [],
    at: Date.now(),
    launchId: proof?.launchId || null,
    actionGeneration: proof?.actionGeneration || proof?.launchId || null,
    terminalToken: proof?.terminalToken || null,
    lifecycleGeneration: proof?.lifecycleGeneration || null,
    runSeq: normalizeCodexPositiveRunSeq(proof?.runSeq),
    sourceMatch: proof?.sourceMatch || null,
    forkedFromId: proof?.forkedFromId || null,
    sourceSessionId: proof?.sourceSessionId || null,
    carryCodexSettingsProof: proof?.carryCodexSettingsProof === true
      || pendingSettingsCarry.carry === true,
    codexSettingsProof: exactSettingsProofToPersist,
    valid: true,
    invalidatedAt: null,
    invalidatedReason: null,
  };
  // The startup payload/read lease retires after a child writer is adopted.
  // Keep only its already-proven same-generation Resume source with the writer,
  // so an in-flight addressed send does not lose its destination at ready.
  proofRecord.acceptedResumeSource = currentCodexAcceptedResumeSourceProof(tabId, proofRecord,
    prevProof?.sessionId === sessionId ? prevProof.acceptedResumeSource : null);
  codexWriterProofs.set(tabId, proofRecord);
  const settingsIntent = getCodexModelEffortIntentRecord(tabId);
  const settingsIntentOwnerHandoff = planCodexModelEffortIntentOwnerHandoff({
    ...settingsIntent,
    launchOwnerId: proofRecord.launchId ? 'launch:' + proofRecord.launchId : null,
    writerOwnerId: sessionId,
    provenModel: exactSettingsProofToPersist?.model,
    provenEffort: exactSettingsProofToPersist?.effort,
  });
  if (settingsIntentOwnerHandoff.transfer === true) {
    markCodexModelEffortIntentApplied(
      tabId,
      settingsIntent,
      sessionId,
      'writer-adoption-owner-handoff',
    );
  }
  void codexSessionContextObserver?.ensure(
    sessionId,
    terminalProjects.get(tabId) || null,
  );
  ipcMain.emit(CODEX_SETTINGS_WRITER_ADOPTED_EVENT, null, {
    tabId,
    sessionId,
    launchId: proofRecord.launchId || null,
    runSeq: proofRecord.runSeq,
    lifecycleGeneration: proofRecord.lifecycleGeneration || null,
  });
  void scheduleCodexModelEffortIntentReconcile(tabId, 'writer-adopted');
  clearCodexReadIdentitySubmitBarrier(
    tabId,
    null,
    'writer-adopted:' + sessionId,
    { resolution: 'writer-adopted' },
  );
  const proofChanged = prev !== sessionId
    || prevProof?.kind !== proofRecord.kind
    || prevProof?.filePath !== proofRecord.filePath
    || prevProof?.valid !== true;
  if (proofChanged) {
    void tabWorkContext.syncLinks().catch((error) => {
      console.warn('[TabContext] Codex source sync:', error.message);
    });
  }
  if (proofChanged && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:mcp-ai-tab', {
      tabId,
      engine: 'codex',
      sessionId,
      reason,
      writerProven: true,
      writerProof: proofRecord.kind,
      previousSessionId: prev,
      writerGeneration: proofRecord.launchId,
      carryCodexSettingsProof: proofRecord.carryCodexSettingsProof,
      codexSettingsProof: proofRecord.codexSettingsProof,
      requiresExactCodexSettingsProof: !!pendingSettingsProof,
    });
  }
  const carriedFast = exactSettingsProofToPersist?.fast;
  if (serviceTierOwnerHandoff.allowed) {
    publishCodexServiceTierProof(
      tabId,
      serviceTierOwnerHandoff.serviceTier,
      'exact-first-writer-service-tier-handoff',
      sessionId,
    );
  } else if (typeof carriedFast === 'boolean') {
    publishCodexServiceTierProof(
      tabId,
      carriedFast ? 'priority' : 'default',
      'verified-composer-writer-handoff',
      sessionId,
    );
  } else if (proofRecord.carryCodexSettingsProof) {
    if (existingTierProof?.ownerId === prev) {
      publishCodexServiceTierProof(
        tabId,
        existingTierProof.serviceTier,
        'live-writer-handoff',
        sessionId,
      );
    }
  }
  reconcileCodexServiceTierProofIdentity(tabId, 'writer-adoption');
  if (proofChanged) {
    console.log('[Codex:Known] set tab=' + String(tabId).slice(-12) +
      ' session=' + String(sessionId).slice(0, 8) +
      ' reason=' + reason +
      ' prev=' + (prev ? String(prev).slice(0, 8) : 'none') +
      ' revalidated=' + (prev === sessionId) +
      ' total=' + codexKnownSessions.size);
    const turnState = codexTurnWatchers.get(tabId) || null;
    if (turnState?.publicTurnStateSuppressed === true) {
      console.log('[CodexTurn] writer snapshot deferred until catch-up tab='
        + String(tabId).slice(-12)
        + ' session=' + String(sessionId).slice(0, 8)
        + ' reason=' + reason);
    } else {
      broadcastCodexPublicRuntimeSnapshot(tabId, reason);
    }
  }
  clearCodexServiceTierLaunchCandidate(
    tabId,
    'first-writer-adopted:' + sessionId,
  );
  return {
    success: true,
    persisted,
    proofChanged,
    carryCodexSettingsProof: proofRecord.carryCodexSettingsProof,
    codexSettingsProof: proofRecord.codexSettingsProof,
    requiresExactCodexSettingsProof: !!pendingSettingsProof,
  };
}

function getCodexWriterProofSnapshot(tabId) {
  if (!tabId) return null;
  const sessionId = codexKnownSessions.get(tabId) || null;
  const proof = codexWriterProofs.get(tabId) || null;
  if (!sessionId || !proof || proof.sessionId !== sessionId || proof.valid !== true) return null;
  return { ...proof, sessionId };
}

function getCodexProvisionalSettingsSnapshot(tabId, expectedOwnerId = null) {
  if (!tabId || getCodexWriterProofSnapshot(tabId)) return null;
  const pending = codexPendingSettingsProofHandoffs.get(tabId) || null;
  const projected = projectPendingCodexSettingsProofOwner(pending, {
    terminalToken: terminals.get(tabId) || null,
    runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    expectedOwnerId,
  });
  if (!projected) return null;
  return {
    codexProvisionalSettingsOwnerId: projected.ownerId,
    codexProvisionalSettingsLaunchId: projected.launchId,
    codexProvisionalModel: projected.model,
    codexProvisionalEffort: projected.effort,
    codexProvisionalFast: projected.fast,
    codexProvisionalSettingsProofAt: projected.proofAt,
    codexProvisionalSettingsProofSource: projected.applicationProofSource,
  };
}

function clearCodexServiceTierLaunchCandidate(
  tabId,
  reason = 'clear',
  expectedLaunchId = null,
) {
  if (!tabId) return false;
  const candidate = codexServiceTierLaunchCandidates.get(tabId) || null;
  if (!candidate) return false;
  if (expectedLaunchId && candidate.launchId !== expectedLaunchId) {
    console.log('[CodexSettingsProof] stale launch candidate clear ignored tab='
      + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' expected=' + expectedLaunchId
      + ' current=' + candidate.launchId);
    return false;
  }
  codexServiceTierLaunchCandidates.delete(tabId);
  console.log('[CodexSettingsProof] launch candidate cleared tab='
    + String(tabId).slice(-12)
    + ' launch=' + candidate.launchId
    + ' reason=' + reason);
  return true;
}

function armCodexServiceTierLaunchCandidate(tabId, launch) {
  if (!tabId || !launch) return null;
  const candidate = createCodexLaunchSettingsObservationCandidate({
    launchId: launch.launchId,
    terminalToken: launch.terminalToken,
    runSeq: launch.runSeq,
    terminalLifecycleGeneration: launch.lifecycleGeneration,
    createdAt: Date.now(),
  });
  if (!candidate) return null;
  codexServiceTierLaunchCandidates.set(tabId, candidate);
  console.log('[CodexSettingsProof] launch candidate armed tab='
    + String(tabId).slice(-12)
    + ' launch=' + candidate.launchId
    + ' runSeq=' + candidate.runSeq
    + ' lifecycle=' + candidate.terminalLifecycleGeneration);
  return candidate;
}

function getCurrentCodexServiceTierLaunchCandidate(tabId, {
  expectedLaunchId = null,
  expectedTerminal = null,
  expectedRunSeq = null,
} = {}) {
  const candidate = codexServiceTierLaunchCandidates.get(tabId) || null;
  const terminalToken = terminals.get(tabId) || null;
  const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const validation = validateCodexLaunchSettingsObservationCandidate(candidate, {
    launchId: expectedLaunchId,
    terminalToken,
    runSeq: terminalRunSeq,
    terminalLifecycleGeneration: lifecycleGeneration,
    writerPresent: !!getCodexWriterProofSnapshot(tabId),
  });
  if (!validation.valid) {
    if (candidate && validation.reason !== 'candidate-missing') {
      clearCodexServiceTierLaunchCandidate(
        tabId,
        'candidate-invalid:' + validation.reason,
        candidate.launchId,
      );
    }
    return null;
  }
  if ((expectedTerminal && terminalToken !== expectedTerminal)
    || (expectedRunSeq != null && terminalRunSeq !== Number(expectedRunSeq))) {
    return null;
  }
  return candidate;
}

function resolveCodexVerifiedCurrentFrameSettings(tabId, frameText, {
  expectedLaunchId = null,
  expectedTerminal = null,
  expectedRunSeq = null,
} = {}) {
  const footerSettings = parseCodexVerifiedComposerFooter(frameText || '');
  if (footerSettings) return footerSettings;

  const launchCardSettings = parseCodexVerifiedLaunchCardSettings(frameText || '');
  if (!launchCardSettings || getCodexWriterProofSnapshot(tabId)) return null;

  const launch = codexLastRunCommandPayload.get(tabId)
    || getCurrentCodexServiceTierLaunchCandidate(tabId, {
      expectedLaunchId,
      expectedTerminal,
      expectedRunSeq,
    })
    || null;
  const terminalToken = terminals.get(tabId) || null;
  const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const launchId = String(launch?.launchId || '').trim();
  if (!launchId
    || !terminalToken
    || !Number.isInteger(terminalRunSeq)
    || terminalRunSeq <= 0
    || launch?.terminalToken !== terminalToken
    || Number(launch?.runSeq) !== terminalRunSeq
    || !(launch?.lifecycleGeneration || launch?.terminalLifecycleGeneration)
    || (launch.lifecycleGeneration || launch.terminalLifecycleGeneration) !== lifecycleGeneration
    || (expectedLaunchId && launchId !== expectedLaunchId)
    || (expectedTerminal && terminalToken !== expectedTerminal)
    || (expectedRunSeq != null && terminalRunSeq !== Number(expectedRunSeq))) {
    return null;
  }
  return launchCardSettings;
}

function confirmCodexIntentFromCurrentLaunchSettings(tabId, settings, launchId) {
  // Called only after armCodexCurrentLaunchSettingsProof has validated the
  // exact terminal/run/lifecycle/launch. A current composer footer is already
  // settings proof; a saved intent or the old startup banner is not.
  if (settings?.proof !== 'verified-composer-footer'
    || terminalCommandState.get(tabId)?.isRunning !== true) return false;
  retireCodexScopedModelEffortIntent(tabId, 'before-current-launch-proof');
  const intent = getCodexModelEffortIntentRecord(tabId);
  const ownerId = 'launch:' + launchId;
  if (!intent || intent.model !== settings.model || intent.effort !== settings.effort) return false;
  if (intent.appliedRevision === intent.revision && intent.appliedOwnerId === ownerId) return true;
  const applied = markCodexModelEffortIntentApplied(tabId, intent, ownerId,
    'verified-current-launch-footer', { publish: false });
  if (applied.applied !== true) return false;
  const result = {
    success: true, applied: true, queued: false, intentPending: false,
    model: intent.model, effort: intent.effort, intentRevision: intent.revision,
    applicationMode: intent.effort === 'ultra' ? 'conversation-only' : 'persistent-default',
    applicationProofSource: settings.proof,
    codexSettingsProofSessionId: null,
    codexProvisionalSettingsOwnerId: ownerId,
    providerState: applied.providerState,
  };
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:model-effort-intent-applied', {
      tabId, model: intent.model, effort: intent.effort, revision: intent.revision, result,
    });
  }
  broadcastProviderState(tabId, applied.providerState);
  return true;
}

function armCodexCurrentLaunchSettingsProof(tabId, settings, {
  expectedLaunchId = null,
  expectedTerminal = null,
  expectedRunSeq = null,
} = {}) {
  if (!settings || getCodexWriterProofSnapshot(tabId)) return null;
  const launch = codexLastRunCommandPayload.get(tabId)
    || getCurrentCodexServiceTierLaunchCandidate(tabId, {
      expectedLaunchId,
      expectedTerminal,
      expectedRunSeq,
    })
    || null;
  const terminalToken = terminals.get(tabId) || null;
  const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const launchId = String(launch?.launchId || '').trim();
  if (!launchId
    || !terminalToken
    || !Number.isInteger(terminalRunSeq)
    || terminalRunSeq <= 0
    || launch?.terminalToken !== terminalToken
    || Number(launch?.runSeq) !== terminalRunSeq
    || !(launch?.lifecycleGeneration || launch?.terminalLifecycleGeneration)
    || (launch.lifecycleGeneration || launch.terminalLifecycleGeneration) !== lifecycleGeneration
    || (expectedLaunchId && launchId !== expectedLaunchId)
    || (expectedTerminal && terminalToken !== expectedTerminal)
    || (expectedRunSeq != null && terminalRunSeq !== Number(expectedRunSeq))) {
    return null;
  }

  const existing = codexPendingSettingsProofHandoffs.get(tabId) || null;
  if (existing?.generationMode === 'launch'
    && existing.launchId === launchId
    && existing.terminalToken === terminalToken
    && Number(existing.runSeq) === terminalRunSeq
    && existing.model === settings.model
    && existing.effort === settings.effort
    && existing.fast === settings.fast
    && existing.applicationProofSource === settings.proof) {
    confirmCodexIntentFromCurrentLaunchSettings(tabId, settings, launchId);
    return existing;
  }

  const pendingProof = createPendingCodexSettingsProofHandoff({
    result: {
      success: true,
      model: settings.model,
      effort: settings.effort,
      fast: settings.fast,
      proofAt: Date.now(),
      applicationProofSource: settings.proof,
      codexSettingsProofSessionId: null,
    },
    terminalToken,
    runSeq: terminalRunSeq,
    launchId,
  });
  if (!pendingProof) return null;
  codexPendingSettingsProofHandoffs.set(tabId, pendingProof);
  console.log('[CodexSettingsProof] verified current-frame proof armed tab='
    + String(tabId).slice(-12)
    + ' launch=' + launchId
    + ' runSeq=' + terminalRunSeq
    + ' model=' + settings.model
    + ' effort=' + settings.effort
    + ' fast=' + settings.fast
    + ' source=' + settings.proof);
  if (!confirmCodexIntentFromCurrentLaunchSettings(tabId, settings, launchId)) {
    void scheduleCodexModelEffortIntentReconcile(tabId, 'verified-launch-settings');
  }
  return pendingProof;
}

function getCurrentCodexServiceTierProofIdentity(tabId, explicitOwnerId = null) {
  if (!tabId) return { success: false, reason: 'tab-missing' };
  const terminalToken = terminals.get(tabId) || null;
  const terminalLifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  if (!terminalToken
    || !terminalLifecycleGeneration
    || !Number.isInteger(terminalRunSeq)
    || terminalRunSeq <= 0) {
    return { success: false, reason: 'terminal-generation-unproven' };
  }

  const writerProof = getCodexWriterProofSnapshot(tabId);
  const provisional = writerProof ? null : getCodexProvisionalSettingsSnapshot(tabId);
  const writerOwnerId = String(writerProof?.sessionId || '').trim();
  const provisionalOwnerId = String(provisional?.codexProvisionalSettingsOwnerId || '').trim();
  const terminalRunOwnerId = !writerOwnerId
    && !provisionalOwnerId
    && terminalCommandState.get(tabId)?.isRunning === true
    && codexTuiReadyTabs.has(tabId)
    ? 'terminal-run:' + terminalLifecycleGeneration
    : '';
  const requestedOwnerId = String(explicitOwnerId || '').trim();
  if (requestedOwnerId
    && requestedOwnerId !== writerOwnerId
    && requestedOwnerId !== provisionalOwnerId
    && requestedOwnerId !== terminalRunOwnerId) {
    return { success: false, reason: 'proof-owner-not-current' };
  }
  const ownerId = requestedOwnerId || writerOwnerId || provisionalOwnerId || terminalRunOwnerId;
  if (!ownerId) return { success: false, reason: 'proof-owner-unproven' };

  // Before the first rollout exists, the launch is the only exact owner of
  // the observed footer/card. Once that launch is atomically adopted by a
  // durable writer, the writer + terminal lifecycle/run becomes the stronger
  // live identity. Do not keep coupling the service-tier proof to the
  // one-shot launch record: ordinary process revalidation may legitimately
  // discard that launch metadata while the exact writer and PTY generation
  // remain unchanged.
  const launchId = ownerId === provisionalOwnerId
    ? String(provisional?.codexProvisionalSettingsLaunchId || '').trim()
    : '';
  const generationMode = launchId ? 'launch' : 'terminal-run';
  const generationId = launchId || terminalLifecycleGeneration;

  return {
    success: true,
    ownerId,
    terminalToken,
    terminalLifecycleGeneration,
    terminalRunSeq,
    generationMode,
    generationId,
    launchId: launchId || null,
  };
}

function clearCodexServiceTierProof(
  tabId,
  reason = 'ownership-unknown',
  expectedOwnerId = null,
  { emit = true } = {},
) {
  if (!tabId) return false;
  const previousMeta = codexTuiReadyMeta.get(tabId) || null;
  const previousProof = previousMeta?.serviceTierProof || null;
  if (!previousProof) return false;
  if (expectedOwnerId && previousProof.ownerId !== expectedOwnerId) return false;
  const { serviceTierProof: _discardedProof, ...remainingMeta } = previousMeta;
  codexTuiReadyMeta.set(tabId, remainingMeta);
  console.warn('[CodexServiceTier] proof cleared tab=' + String(tabId).slice(-12)
    + ' owner=' + String(previousProof.ownerId || 'none').slice(0, 24)
    + ' reason=' + reason);
  if (emit && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:service-tier-proof', {
      tabId,
      ownerId: previousProof.ownerId || null,
      serviceTier: null,
      cleared: true,
      reason,
    });
  }
  return true;
}

function reconcileCodexServiceTierProofIdentity(tabId, reason = 'identity-refresh') {
  const proof = codexTuiReadyMeta.get(tabId)?.serviceTierProof || null;
  if (!proof) return { preserved: false, proof: null, reason: 'proof-missing' };
  const identity = getCurrentCodexServiceTierProofIdentity(tabId);
  const result = identity.success === true
    ? preserveCodexServiceTierProofForTurnEnd(proof, identity)
    : { preserved: false, proof: null, reason: identity.reason };
  if (!result.preserved) {
    clearCodexServiceTierProof(tabId, reason + ':' + result.reason);
  }
  return result;
}

function retainCodexServiceTierProofAcrossReadinessBlocker(
  tabId,
  reason = 'readiness-blocker',
) {
  const previousProof = codexTuiReadyMeta.get(tabId)?.serviceTierProof || null;
  if (!previousProof) return null;
  const identity = getCurrentCodexServiceTierProofIdentity(tabId);
  const retention = identity.success === true
    ? preserveCodexServiceTierProofForTurnEnd(previousProof, identity)
    : { preserved: false, proof: null, reason: identity.reason };
  if (!retention.preserved) {
    clearCodexServiceTierProof(
      tabId,
      reason + ':' + (retention.reason || 'identity-changed'),
    );
    return null;
  }
  console.log('[CodexServiceTier] proof retained across readiness blocker tab='
    + String(tabId).slice(-12)
    + ' owner=' + String(previousProof.ownerId || 'none').slice(0, 24)
    + ' reason=' + reason);
  return retention.proof;
}

function syncPendingCodexServiceTierProof(tabId, proof, identity) {
  const pending = codexPendingSettingsProofHandoffs.get(tabId) || null;
  const expectedMode = pending?.generationMode === 'terminal-run'
    ? 'terminal-run'
    : 'launch';
  const expectedOwnerId = expectedMode === 'launch'
    ? 'launch:' + String(pending?.launchId || '')
    : 'terminal-run:' + String(identity?.terminalLifecycleGeneration || '');
  if (!pending
    || !['launch', 'terminal-run'].includes(pending.generationMode)
    || (expectedMode === 'launch' && !pending.launchId)
    || identity?.ownerId !== expectedOwnerId
    || identity?.terminalToken !== pending.terminalToken
    || Number(identity?.terminalRunSeq) !== Number(pending.runSeq)
    || identity?.generationMode !== expectedMode
    || (expectedMode === 'launch' && identity?.launchId !== pending.launchId)
    || (expectedMode === 'terminal-run'
      && identity?.generationId !== identity?.terminalLifecycleGeneration)
    || typeof proof?.fast !== 'boolean') {
    return false;
  }
  if (pending.fast === proof.fast) return true;
  codexPendingSettingsProofHandoffs.set(tabId, {
    ...pending,
    fast: proof.fast,
  });
  console.log('[CodexSettingsProof] provisional FAST proof refreshed tab='
    + String(tabId).slice(-12)
    + ' generation=' + (pending.launchId || identity.generationId || '-')
    + ' fast=' + proof.fast
    + ' source=' + (proof.source || '-'));
  return true;
}

function publishCodexServiceTierProof(
  tabId,
  serviceTier,
  source = 'tui',
  explicitOwnerId = null,
  { emit = true } = {},
) {
  if (!tabId) return null;
  const normalizedTier = String(serviceTier || '').trim().toLowerCase();
  if (normalizedTier !== 'priority' && normalizedTier !== 'default') return null;
  const identity = getCurrentCodexServiceTierProofIdentity(tabId, explicitOwnerId);
  if (identity.success !== true) {
    console.warn('[CodexServiceTier] proof rejected tab=' + String(tabId).slice(-12)
      + ' tier=' + normalizedTier
      + ' source=' + String(source || 'tui')
      + ' reason=' + identity.reason);
    return null;
  }

  const proofSource = String(source || 'tui');
  if ((proofSource === 'tui' || proofSource === 'tui-service-tier-feedback')
    && !codexFastIntentReconcileInflight.has(tabId)) {
    // A manual/native `/fast` outside our reconciler is a newer user choice.
    // Adopt the exact TUI result so durable intent never toggles it back.
    persistCodexFastIntentValue(
      tabId,
      normalizedTier === 'priority',
      'external-fast-feedback',
    );
  }

  const previousMeta = codexTuiReadyMeta.get(tabId) || {};
  const previousProof = previousMeta.serviceTierProof || null;
  const reusableProof = previousProof?.serviceTier === normalizedTier
    ? preserveCodexServiceTierProofForTurnEnd(previousProof, identity)
    : { preserved: false, proof: null };
  if (reusableProof.preserved) {
    // Repeated footer frames are observations of the same fact, not a new
    // service-tier transition. Keep the exact proof timestamp/source/object so
    // an ordinary prompt + task_complete cannot appear to have replaced it.
    syncPendingCodexServiceTierProof(tabId, reusableProof.proof, identity);
    void scheduleCodexFastIntentReconcile(tabId, 'service-tier-proof-reused');
    return reusableProof.proof;
  }
  const proof = createCodexServiceTierProof({
    ...identity,
    serviceTier: normalizedTier,
    proofAt: Date.now(),
    source: String(source || 'tui'),
  });
  if (!proof) return null;
  codexTuiReadyMeta.set(tabId, {
    ...previousMeta,
    serviceTierProof: proof,
  });
  syncPendingCodexServiceTierProof(tabId, proof, identity);
  const changed = previousProof?.ownerId !== proof.ownerId
    || previousProof?.serviceTier !== proof.serviceTier
    || previousProof?.terminalLifecycleGeneration !== proof.terminalLifecycleGeneration
    || Number(previousProof?.terminalRunSeq) !== proof.terminalRunSeq
    || previousProof?.launchId !== proof.launchId;
  if (changed) {
    console.log('[CodexServiceTier] proof tab=' + String(tabId).slice(-12)
      + ' owner=' + proof.ownerId.slice(0, 24)
      + ' tier=' + normalizedTier
      + ' source=' + proof.source
      + ' launch=' + proof.launchId
      + ' run=' + proof.terminalRunSeq);
  }
  if (emit && changed && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:service-tier-proof', {
      tabId,
      ...proof,
    });
  }
  void scheduleCodexFastIntentReconcile(tabId, 'service-tier-proof');
  return proof;
}

function isCodexWriterUsableForMutation(tabId) {
  if (!getCodexWriterProofSnapshot(tabId)) return false;
  const discovery = codexWatchers.get(tabId) || null;
  return !(discovery?.sourceMode === 'writer-handoff' && discovery.handoffPending === true);
}

function hasCodexEstablishedWriterUiLifecycle(tabId) {
  if (isCodexWriterUsableForMutation(tabId)) return true;
  const proof = codexWriterProofs.get(tabId) || null;
  const payload = codexLastRunCommandPayload.get(tabId) || null;
  const discovery = codexWatchers.get(tabId) || null;
  if (!proof?.sessionId || codexKnownSessions.get(tabId) !== proof.sessionId) return false;
  if (payload?.launchId && proof.launchId !== payload.launchId) return false;
  if (discovery?.sourceMode === 'writer-handoff' && discovery.handoffPending === true) return false;
  // Preserve only the visual lifecycle across a fallible process-inspection
  // outage. The current session ID and all mutations remain revoked. Other
  // invalidation reasons (new launch, rewind handoff, absence) must show
  // starting/unresolved rather than reusing an old active state.
  const reason = String(proof.invalidatedReason || '');
  return proof.valid !== true && (
    reason.includes('process-unknown')
    || reason.includes('writer-unknown')
    || reason.includes('revalidation-unknown')
  );
}

function invalidateCodexWriterProof(tabId, reason = 'unproven') {
  const proof = codexWriterProofs.get(tabId) || null;
  if (!proof) return false;
  const changed = proof.valid === true || proof.invalidatedReason !== reason;
  codexWriterProofs.set(tabId, {
    ...proof,
    valid: false,
    invalidatedAt: Date.now(),
    invalidatedReason: reason,
  });
  if (changed) {
    console.warn('[CodexWriterProof] invalidate tab=' + String(tabId).slice(-12)
      + ' session=' + String(proof.sessionId || 'none').slice(0, 8)
      + ' reason=' + reason);
    clearCodexServiceTierProof(tabId, 'writer-proof-invalidated:' + reason);
    void tabWorkContext.syncLinks().catch((error) => {
      console.warn('[TabContext] Codex source invalidate:', error.message);
    });
  }
  return changed;
}

function clearCodexKnownSession(tabId, reason = 'clear') {
  retireCodexScopedModelEffortIntent(tabId, 'known-session-clear:' + reason);
  closeCodexDelayedWriterObserver(tabId, reason);
  clearCodexTabSubagentActivity(tabId, 'known-session-clear:' + reason);
  const sid = codexKnownSessions.get(tabId) || null;
  const hadWriterProof = codexWriterProofs.has(tabId);
  clearCodexServiceTierLaunchCandidate(tabId, 'known-writer-cleared:' + reason);
  clearCodexServiceTierProof(tabId, 'known-writer-cleared:' + reason);
  if (codexPreclaimedCommandGenerations.delete(tabId)) {
    console.log('[CodexGeneration] preclaimed launch generation cleared tab='
      + String(tabId).slice(-12)
      + ' reason=' + reason);
  }
  if (codexPendingSettingsProofHandoffs.delete(tabId)) {
    console.log('[CodexSettingsProof] pre-rollout proof cleared tab='
      + String(tabId).slice(-12)
      + ' reason=' + reason);
  }
  codexWriterProofs.delete(tabId);
  if (sid || hadWriterProof) {
    void tabWorkContext.syncLinks().catch((error) => {
      console.warn('[TabContext] Codex source clear:', error.message);
    });
  }
  releaseCodexResumeSourceLeaseForTab(tabId, reason);
  if (!sid) return;
  codexKnownSessions.delete(tabId);
  console.log('[Codex:Known] clear tab=' + String(tabId).slice(-12) +
    ' session=' + String(sid).slice(0, 8) +
    ' reason=' + reason +
    ' remaining=' + codexKnownSessions.size);
}

function claimCodexResumeSourceLease(sourceSessionId, tabId, launchId) {
  const provenOwner = getCodexSessionOwner(sourceSessionId, tabId);
  return claimCodexResumeSourceLeaseInRegistry(codexResumeSourceLeases, {
    sourceSessionId,
    tabId,
    launchId,
    provenOwner,
  });
}

function releaseCodexResumeSourceLeaseForTab(
  tabId,
  reason = 'clear',
  sourceSessionId = null,
  launchId = null,
) {
  const released = releaseCodexResumeSourceLeasesInRegistry(codexResumeSourceLeases, {
    tabId,
    sourceSessionId,
    launchId,
  });
  const pendingBarrier = codexReadIdentitySubmitPending.get(tabId) || null;
  if (pendingBarrier
    && released.includes(pendingBarrier.sourceSessionId)
    && (!launchId || pendingBarrier.launchId === launchId)) {
    clearCodexReadIdentitySubmitBarrier(
      tabId,
      pendingBarrier,
      'resume-lease:' + reason,
      { resolution: 'resume-lease-released' },
    );
  }
  for (const source of released) {
    console.log('[CodexResumeLease] release tab=' + String(tabId).slice(-12)
      + ' source=' + String(source).slice(0, 8)
      + ' reason=' + reason);
  }
}

function getCodexResumeSourceLeaseForTab(tabId) {
  for (const [sourceSessionId, lease] of codexResumeSourceLeases) {
    if (lease?.tabId === tabId) return { sourceSessionId, ...lease };
  }
  return null;
}

function getCodexResumeReadIdentityLeaseForTab(tabId) {
  const lease = getCodexResumeSourceLeaseForTab(tabId);
  const readIdentity = lease?.readIdentity || null;
  if (!readIdentity
    || readIdentity.tabId !== tabId
    || readIdentity.sessionId !== lease.sourceSessionId
    || readIdentity.launchId !== lease.launchId) return null;
  return readIdentity;
}

function bindCodexResumeReadIdentityLease({
  tabId,
  sourceSessionId,
  launchId,
  terminalToken,
  terminalRunSeq,
  terminalLifecycleGeneration,
}) {
  const lease = codexResumeSourceLeases.get(sourceSessionId) || null;
  if (!lease || lease.tabId !== tabId || lease.launchId !== launchId) return false;
  const readIdentity = createCodexResumeReadIdentityLease({
    tabId,
    sourceSessionId,
    launchId,
    terminalToken,
    terminalRunSeq,
    terminalLifecycleGeneration,
  });
  if (!readIdentity) return false;
  lease.readIdentity = {
    ...readIdentity,
    // A materialized Fresh also uses codex-c internally. Preserve its actual
    // launch kind after the short-lived payload retires, for shutdown recovery.
    materializedFresh: codexLastRunCommandPayload.get(tabId)?.materializedFresh === true,
  };
  console.log('[CodexReadIdentity] Resume read lease bound tab=' + String(tabId).slice(-12)
    + ' source=' + String(sourceSessionId).slice(0, 8)
    + ' launch=' + launchId
    + ' run=' + readIdentity.runSeq);
  return true;
}

function markCodexLaunchAcceptancePending(tabId, launchId) {
  if (!tabId || !launchId) return;
  const previousLaunchId = codexLaunchAcceptancePending.get(tabId) || null;
  codexLaunchAcceptancePending.set(tabId, launchId);
  console.log('[CodexLaunchAcceptance] pending tab=' + String(tabId).slice(-12)
    + ' launch=' + launchId
    + ' replaced=' + (previousLaunchId || '-'));
}

function clearCodexLaunchAcceptancePending(tabId, reason = 'clear', expectedLaunchId = null) {
  if (!tabId) return false;
  const currentLaunchId = codexLaunchAcceptancePending.get(tabId) || null;
  if (!shouldClearCodexLaunchPending(currentLaunchId, expectedLaunchId)) {
    if (currentLaunchId && expectedLaunchId) {
      console.log('[CodexLaunchAcceptance] stale clear ignored tab=' + String(tabId).slice(-12)
        + ' reason=' + reason
        + ' expected=' + expectedLaunchId
        + ' current=' + currentLaunchId);
    }
    return false;
  }
  codexLaunchAcceptancePending.delete(tabId);
  console.log('[CodexLaunchAcceptance] clear tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' launch=' + currentLaunchId);
  return true;
}

function clearCodexStartupNoStateTimeoutTimer(tabId, reason = 'clear', expectedLaunchId = null) {
  if (!tabId) return false;
  const state = codexStartupNoStateTimeoutTimers.get(tabId);
  if (!state) return false;
  if (expectedLaunchId && state.launchId !== expectedLaunchId) {
    console.log('[CodexStartupTimeout] stale timer clear ignored tab=' + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' expected=' + expectedLaunchId
      + ' current=' + (state.launchId || '-'));
    return false;
  }
  if (state.timer) clearTimeout(state.timer);
  codexStartupNoStateTimeoutTimers.delete(tabId);
  console.log('[CodexStartupTimeout] timer clear tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' launch=' + (state.launchId || '-')
    + ' startedAt=' + (state.startedAt || 0));
  return true;
}

function clearCodexLaunchPayload(
  tabId,
  reason = 'clear',
  expectedLaunchId = null,
  {
    preserveServiceTierLaunchCandidate = false,
    lateMcpRecoveryReceipt = null,
  } = {},
) {
  if (!tabId) return false;
  const payload = codexLastRunCommandPayload.get(tabId) || null;
  if (payload && expectedLaunchId && payload.launchId !== expectedLaunchId) {
    console.log('[Codex Runner] stale launch payload clear ignored tab=' + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' expected=' + expectedLaunchId
      + ' current=' + (payload.launchId || '-'));
    return false;
  }
  const scopedLaunchId = expectedLaunchId || payload?.launchId || null;
  if (!preserveServiceTierLaunchCandidate) {
    clearCodexServiceTierLaunchCandidate(tabId, 'launch-payload:' + reason, scopedLaunchId);
  }
  clearCodexPendingModelMigration(tabId, 'launch-payload:' + reason);
  clearCodexStartupNoStateTimeoutTimer(tabId, 'launch-payload:' + reason, scopedLaunchId);
  clearCodexLaunchAcceptancePending(tabId, reason, scopedLaunchId);
  const preclaimedGeneration = codexPreclaimedCommandGenerations.get(tabId) || null;
  if (preclaimedGeneration
    && (!scopedLaunchId || preclaimedGeneration.launchId === scopedLaunchId)) {
    codexPreclaimedCommandGenerations.delete(tabId);
    console.log('[CodexGeneration] preclaimed launch generation cleared tab='
      + String(tabId).slice(-12)
      + ' reason=launch-payload:' + reason
      + ' launch=' + (preclaimedGeneration.launchId || '-'));
  }
  if (!payload) return false;
  if (lateMcpRecoveryReceipt) {
    payload.lateMcpRecoveryReceipt = {
      ...lateMcpRecoveryReceipt,
      launchId: payload.launchId,
      retainedAt: Date.now(),
      reason,
    };
    console.log('[Codex Runner] launch payload retained for late MCP proof tab='
      + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' launch=' + (payload.launchId || '-')
      + ' run=' + (lateMcpRecoveryReceipt.terminalRunSeq ?? '-')
      + ' lifecycle=' + (lateMcpRecoveryReceipt.terminalLifecycleGeneration || '-')
      + ' inputRevision=' + (lateMcpRecoveryReceipt.inputRevision ?? '-'));
    return true;
  }
  codexLastRunCommandPayload.delete(tabId);
  console.log('[Codex Runner] launch payload clear tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' launch=' + (payload?.launchId || '-')
    + ' command=' + (payload?.command || '-')
    + ' session=' + (payload?.sessionId ? String(payload.sessionId).slice(0, 8) : 'new'));
  return true;
}

function clearCodexManualActionRequired(tabId, reason = 'clear') {
  if (!tabId) return;
  const state = codexManualActionRequired.get(tabId);
  if (!state) return;
  codexManualActionRequired.delete(tabId);
  console.log('[CodexManualAction] clear tab=' + String(tabId).slice(-12)
    + ' type=' + (state.type || '-')
    + ' reason=' + reason
    + ' ageMs=' + (Date.now() - (state.detectedAt || Date.now())));
}

function publishCodexLifecycleWarning(tabId, warning, reason = 'update') {
  if (!tabId) return;
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:lifecycle-warning', {
      tabId,
      warning: warning || null,
      reason,
    });
  }
  broadcastCodexPublicRuntimeSnapshot(tabId, 'lifecycle-warning:' + reason);
}

function clearCodexLifecycleWarning(
  tabId,
  reason = 'clear',
  expectedWarningId = null,
  { publish = true } = {},
) {
  if (!tabId) return false;
  const current = codexLifecycleWarnings.get(tabId) || null;
  if (!current) return false;
  if (expectedWarningId && current.id !== expectedWarningId) return false;
  codexLifecycleWarnings.delete(tabId);
  console.log('[CodexLifecycleWarning] clear tab=' + String(tabId).slice(-12)
    + ' type=' + (current.type || '-')
    + ' reason=' + reason
    + ' ageMs=' + (Date.now() - Number(current.detectedAt || Date.now())));
  if (publish) publishCodexLifecycleWarning(tabId, null, reason);
  return true;
}

function setCodexLifecycleWarning(tabId, warning, reason = 'detected', { publish = true } = {}) {
  if (!tabId || !warning?.type) return null;
  const previous = codexLifecycleWarnings.get(tabId);
  if (previous?.code === 'codex_capacity_retry_exhausted'
    && warning.code === 'codex_model_at_capacity'
    && previous.turnId === warning.turnId
    && previous.terminalLifecycleGeneration === warning.terminalLifecycleGeneration) {
    return previous; // a late TUI frame cannot downgrade the exhausted alert
  }
  const next = {
    ...warning,
    id: warning.id || [
      warning.type,
      getTerminalLifecycleGeneration(tabId) || 'no-lifecycle',
      warning.committedFrameGeneration || Date.now(),
    ].join(':'),
    detectedAt: Number(warning.detectedAt || Date.now()),
  };
  codexLifecycleWarnings.set(tabId, next);
  console.warn('[CodexLifecycleWarning] set tab=' + String(tabId).slice(-12)
    + ' type=' + next.type
    + ' frame=' + (next.committedFrameGeneration ?? '-')
    + ' reason=' + reason);
  if (publish) publishCodexLifecycleWarning(tabId, next, reason);
  return next;
}

function clearCodexModelCapacityWatch(tabId, reason = 'clear') {
  const watch = codexModelCapacityWatches.get(tabId) || null;
  if (!watch) return false;
  codexModelCapacityWatches.delete(tabId);
  console.log('[CodexModelCapacity] disarm tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' ageMs=' + (Date.now() - Number(watch.startedAt || Date.now())));
  return true;
}

function armCodexModelCapacityWatch(tabId, reason = 'prompt-submitted', { turnId = null } = {}) {
  const terminal = terminals.get(tabId) || null;
  const mirror = getHeadlessTerminalMirror(tabId);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  if (!terminal || !mirror || !lifecycleGeneration || terminalRunSeq <= 0) {
    clearCodexModelCapacityWatch(tabId, 'attempt-identity-unavailable');
    return null;
  }
  const baselineFrame = mirror.lastCommittedVisibleSnapshot || null;
  const baseline = inspectCodexModelCapacityFrame(baselineFrame);
  const watch = {
    terminal,
    mirror,
    lifecycleGeneration,
    terminalRunSeq,
    mirrorGeneration: mirror.generation,
    cols: Number(mirror.cols || 0),
    rows: Number(mirror.rows || 0),
    inputRevision: getTerminalInputRevision(tabId),
    armedCommittedFrameGeneration: Number(baselineFrame?.committedFrameGeneration || 0),
    baselineFingerprint: baseline?.capacity === true ? baseline.fingerprint : null,
    baselineStartRow: baseline?.capacity === true ? baseline.startRow : null,
    sawNonCapacityFrame: false,
    turnId: turnId || null,
    startedAt: Date.now(),
    reason,
  };
  codexModelCapacityWatches.set(tabId, watch);
  console.log('[CodexModelCapacity] arm tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' turn=' + (watch.turnId || '-')
    + ' lifecycle=' + lifecycleGeneration
    + ' run=' + terminalRunSeq
    + ' inputRevision=' + watch.inputRevision
    + ' frame=' + watch.armedCommittedFrameGeneration
    + ' baseline=' + (watch.baselineFingerprint ? 'capacity' : 'none'));
  return watch;
}

function codexModelCapacityWatchIdentityCurrent(tabId, state, watch) {
  return !!watch
    && terminals.get(tabId) === watch.terminal
    && getHeadlessTerminalMirror(tabId) === watch.mirror
    && state === watch.mirror
    && state?.generation === watch.mirrorGeneration
    && Number(state?.cols || 0) === Number(watch.cols || 0)
    && Number(state?.rows || 0) === Number(watch.rows || 0)
    && getTerminalLifecycleGeneration(tabId) === watch.lifecycleGeneration
    && Number(terminalCommandState.get(tabId)?.runSeq || 0) === watch.terminalRunSeq
    && Number(getTerminalInputRevision(tabId)) === Number(watch.inputRevision)
    && aiStoppingTabs.get(tabId)?.toolType !== 'codex';
}

let codexCapacityRetryRuntime = null;
const codexCapacityRetryOwners = new Map();
let codexCapacityRetryWasEnabled = true;

function getCodexCapacityRetryRuntime() {
  if (codexCapacityRetryRuntime) return codexCapacityRetryRuntime;
  const web = () => require(path.join(srcMainDir, 'web-server'));
  codexCapacityRetryRuntime = createCodexCapacityRetryRuntime({
    getSettings: () => web().getOrchestrationSettings(),
    loadState: tabId => projectManager.db.getAppState('codex-capacity-retry-state:' + tabId),
    saveState: (tabId, state) => projectManager.db.setAppState('codex-capacity-retry-state:' + tabId, state),
    isCurrent: owner => terminals.get(owner.tabId) === owner.terminal
      && codexTurnWatchers.get(owner.tabId) === owner.watcher
      && owner.watcher.sessionId === owner.sessionId
      && getTerminalLifecycleGeneration(owner.tabId) === owner.generation
      && !aiStoppingTabs.has(owner.tabId),
    send: (owner, effect, isCurrent) => web().sendCodexCapacityContinuation({
      tabId: owner.tabId, sessionId: owner.sessionId, turnId: effect.errorId,
      generation: owner.generation, handoffId: effect.handoffId, isCurrent,
    }),
    cancelSend: (tabId, handoffId, reason) => agentSendCancellations.cancel(tabId, handoffId, { reason }),
    notify: async (owner, effect, failure = null) => {
      const projectId = resolveAuthoritativeTabProjectId(owner.tabId);
      if (!projectId) return;
      const row = projectManager.db.getAllProjects().find(p => p.id === projectId)?.tabs?.find(t => t.tabId === owner.tabId);
      const message = failure
        ? 'Автопродолжение не отправлено: ' + failure
        : 'Перегрузка модели: ' + effect.attempt + ' повторов без прогресса. Автопродолжение остановлено.';
      setCodexLifecycleWarning(owner.tabId, {
        type: 'model-capacity', code: 'codex_capacity_retry_exhausted', message,
        terminalLifecycleGeneration: owner.generation, turnId: effect.errorId,
      }, 'capacity-retry-exhausted');
      const detail = {
        tabId: owner.tabId, projectId,
        tabName: (row?.name || 'Codex') + ' — ' + message,
        firedAt: Date.now(), fired: true, persistent: false,
      };
      // Same bell/outbox/APNs pipeline; test-owned instances never send a real
      // notification to the user's devices or Telegram.
      if (!aiBoundaryTestGate.enabled) {
        ipcMain.emit('tab-notification:completed', null, detail);
        ipcMain.emit('tab-notification:fired', null, detail);
      }
      mainWindow?.webContents?.send('tab-notification:force-fired', detail);
      console.warn('[CodexCapacityRetry] exhausted tab=' + owner.tabId.slice(-12) + ' attempts=' + effect.attempt);
    },
    log: message => console.log('[CodexCapacityRetry] ' + message),
  });
  return codexCapacityRetryRuntime;
}

ipcMain.on('codex-capacity-retry:settings-updated', (_event, settings = {}) => {
  const enabled = settings.codexCapacityRetryEnabled !== false;
  if (codexCapacityRetryRuntime) for (const owner of codexCapacityRetryOwners.values()) {
    if (!enabled) codexCapacityRetryRuntime.cancel(owner.tabId, 'settings-disabled');
    else if (!codexCapacityRetryWasEnabled) codexCapacityRetryRuntime.reset(owner, Math.max(0, Number(owner.watcher.offset || 0) - 1));
  }
  codexCapacityRetryWasEnabled = enabled;
});

function observeCodexCapacityRetryRecord(state, record, suppressed) {
  if (suppressed || codexTurnWatchers.get(state.tabId) !== state
    || !Number.isFinite(record.__byteOffset)
    || record.__byteOffset < Number(state.capacityRetryLiveAfterOffset ?? Infinity)) return;
  const event = classifyCodexCapacityRetryRecord(record);
  if (!event || (event.type === 'progress' && !state.busy)) return;
  const owner = {
    tabId: state.tabId, sessionId: state.sessionId, watcher: state,
    terminal: terminals.get(state.tabId), generation: getTerminalLifecycleGeneration(state.tabId),
  };
  codexCapacityRetryOwners.set(state.tabId, owner);
  // Byte positions are the ordering authority within one immutable rollout;
  // multiple real records can legitimately share the same millisecond.
  event.at = record.__byteOffset;
  const runtime = getCodexCapacityRetryRuntime();
  if (event.type === 'progress') runtime.progress(owner, event);
  else {
    setCodexLifecycleWarning(state.tabId, {
      type: 'model-capacity', code: 'codex_model_at_capacity', message: CODEX_MODEL_CAPACITY_MESSAGE,
      terminalLifecycleGeneration: owner.generation, turnId: event.errorId,
    }, 'typed-capacity-record', { publish: false });
    const web = require(path.join(srcMainDir, 'web-server'));
    void web.coordinateCodexCapacityContinuation({ ...owner, turnId: event.errorId },
      () => runtime.capacity(owner, event))
      .catch(error => console.warn('[CodexCapacityRetry] observation failed: ' + error.message));
  }
}

function finishCodexModelCapacityOutcome(tabId, watch, capacity, committedFrameGeneration) {
  codexModelCapacityWatches.delete(tabId);
  const timestamp = new Date().toISOString();
  const turnState = codexTurnWatchers.get(tabId) || null;
  const turnId = watch.turnId || turnState?.currentTurnId || null;
  const warning = setCodexLifecycleWarning(tabId, {
    type: 'model-capacity',
    code: capacity.code,
    message: capacity.message,
    committedFrameGeneration,
    terminalLifecycleGeneration: watch.lifecycleGeneration,
    turnId,
  }, 'committed-capacity-frame', { publish: false });

  const lifecycleStillPending = turnState?.busy === true
    || codexPromptInFlight.has(tabId)
    || isCodexStartupLifecycleFresh(tabId);
  clearCodexPromptInFlight(tabId, 'model-capacity');
  markCodexTuiReadyFromTurnEnd(tabId, 'model-capacity');
  if (turnState && lifecycleStillPending) {
    turnState.busy = false;
    turnState.lastEventType = 'provider_error';
    turnState.lastEventTs = timestamp;
    turnState.liveTurnEvents = Number(turnState.liveTurnEvents || 0) + 1;
  }
  if (lifecycleStillPending) {
    emitCodexBusy(tabId, false, 'model_capacity', {
      capacitySurfaceOnly: true,
      outcome: {
        event: 'provider_error',
        busy: false,
        reason: 'model_capacity',
        hasFinalResult: false,
      },
      timestamp,
      turnId,
    });
  }
  publishCodexLifecycleWarning(tabId, warning, 'committed-capacity-frame');
  console.warn('[CodexModelCapacity] confirmed tab=' + String(tabId).slice(-12)
    + ' turn=' + (turnId || '-')
    + ' frame=' + committedFrameGeneration
    + ' rows=' + capacity.startRow + '-' + capacity.endRow);
}

function observeCodexModelCapacityCommittedFrame(
  tabId,
  state,
  snapshot,
  committedFrameGeneration,
) {
  const watch = codexModelCapacityWatches.get(tabId) || null;
  if (!watch) return null;
  const capacity = inspectCodexModelCapacityFrame(snapshot);
  const decision = decideCodexModelCapacityObservation({
    identityCurrent: codexModelCapacityWatchIdentityCurrent(tabId, state, watch),
    committedFrameGeneration,
    armedCommittedFrameGeneration: watch.armedCommittedFrameGeneration,
    capacity,
    baselineFingerprint: watch.baselineFingerprint,
    baselineStartRow: watch.baselineStartRow,
    sawNonCapacityFrame: watch.sawNonCapacityFrame,
  });
  if (decision.action === 'cancel') {
    clearCodexModelCapacityWatch(tabId, decision.reason);
    return null;
  }
  if (decision.action === 'observe-non-capacity') {
    // Only a fully ready composer frame in which the warning is absent proves
    // that a baseline scrollback warning has left the current surface. A
    // half-drawn frame (`ready-composer-required`) proves nothing about it.
    if (capacity?.reason === 'capacity-surface-absent') {
      watch.sawNonCapacityFrame = true;
    }
    return null;
  }
  if (decision.action !== 'accept') return null;
  finishCodexModelCapacityOutcome(tabId, watch, capacity, committedFrameGeneration);
  return capacity;
}

function inspectCodexAuthRequiredPrompt(cleanText) {
  const text = String(cleanText || '').replace(/\u00a0/g, ' ');
  const compact = text.toLowerCase().replace(/\s+/g, ' ');
  const squashed = compact.replace(/[^a-z0-9]+/g, '');
  const hasPhrase = (phrase) => squashed.includes(String(phrase).toLowerCase().replace(/[^a-z0-9]+/g, ''));
  const visible = hasPhrase('welcome to codex openais command line coding agent')
    && hasPhrase('sign in with chatgpt')
    && hasPhrase('sign in with device code')
    && hasPhrase('provide your own api key');
  return {
    visible,
    firstOptionSelected: /[›❯>]\s*1\.\s*Sign\s+in\s+with\s+ChatGPT/i.test(text),
    secondOptionSelected: /[›❯>]\s*2\.\s*Sign\s+in\s+with\s+Device\s+Code/i.test(text),
    thirdOptionSelected: /[›❯>]\s*3\.\s*Provide\s+your\s+own\s+API\s+key/i.test(text),
  };
}

function markCodexManualActionRequired(tabId, type, inspected = {}, clean = '', phase = 'manual-action') {
  if (!tabId || !type) return false;
  const previewTail = String(inspected?.sampleText || clean || '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(-260);
  const prev = codexManualActionRequired.get(tabId) || null;
  const key = [type, phase || '-', previewTail.slice(-120)].join('|');
  if (prev?.key === key) return false;

  const state = {
    type,
    key,
    detectedAt: Date.now(),
    phase: phase || '-',
    source: inspected?.source || '-',
    reason: 'blocked:' + type,
    blockers: [type],
    previewTail,
  };
  codexManualActionRequired.set(tabId, state);

  const quietTimer = codexTuiReadyQuietTimers.get(tabId);
  if (quietTimer) clearTimeout(quietTimer);
  codexTuiReadyQuietTimers.delete(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  clearCodexServiceTierProof(tabId, 'manual-action-required:' + type);
  codexTuiReadyMeta.delete(tabId);
  codexStartupNoStateTimeoutTabs.delete(tabId);
  codexTuiReadyTabs.delete(tabId);
  clearCodexStartupAutoEnter(tabId, type);
  clearCodexMcpStartupWatchdog(tabId, type);
  clearCodexLaunchPayload(tabId, type);
  clearCodexPromptInFlight(tabId, 'manual-action:' + type);

  codexTuiReadyLastNotReady.set(tabId, {
    ts: state.detectedAt,
    phase: state.phase,
    source: state.source,
    reason: state.reason,
    blockers: state.blockers.slice(),
    sampleMode: inspected?.sampleMode || '-',
    sampleBytes: inspected?.sampleBytes || previewTail.length,
    totalBytes: inspected?.totalBytes || previewTail.length,
    startupArmed: false,
    previewTail,
    manualActionRequired: true,
  });

  console.warn('[CodexManualAction] required tab=' + String(tabId).slice(-12)
    + ' type=' + type
    + ' phase=' + (phase || '-')
    + ' source=' + (inspected?.source || '-')
    + ' preview=' + JSON.stringify(previewTail));

  finalizeStoppedAiCommandState(tabId, type, { processName: 'codex', forceEvent: true });
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:tui-manual-action-required', {
      tabId,
      type,
      reason: state.reason,
      lastNotReady: codexTuiReadyLastNotReady.get(tabId) || null,
    });
  }
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId: null,
    busy: false,
    sessionStatus: 'inactive',
    starting: false,
    stopping: false,
    inputReady: false,
    toolType: 'codex',
    commandType: 'codex',
    manualActionRequired: true,
    manualActionType: type,
    lastNotReady: codexTuiReadyLastNotReady.get(tabId) || null,
    reason: type,
  });
  return true;
}

function getCodexRuntimeSessionId(tabId) {
  if (!tabId) return null;
  // While a Codex process is live, an old durable binding is display/history
  // state only. It must never masquerade as the current writer in APIs, loader
  // snapshots, Copy ID, or destructive Timeline actions.
  if (hasEstablishedCodexLifecycleIndicators(tabId)) {
    return getCodexWriterProofSnapshot(tabId)?.sessionId || null;
  }
  return codexSessionIdFromDb(tabId) || codexKnownSessions.get(tabId) || null;
}

function hasEstablishedCodexLifecycleIndicators(tabId) {
  if (!tabId) return false;
  return terminalCommandState.get(tabId)?.isRunning === true
    || !!getCodexWriterProofSnapshot(tabId)
    || codexWatchers.has(tabId)
    || codexTurnWatchers.has(tabId)
    || codexTuiReadyTabs.has(tabId)
    || codexLastRunCommandPayload.has(tabId)
    || codexSessionDiscoveryIntents.has(tabId)
    || codexPromptInFlight.has(tabId)
    || aiStoppingTabs.get(tabId)?.toolType === 'codex'
    || activityOpenIntervals.get(tabId)?.engine === 'codex';
}

function codexHasLivePtySubmitEvidence(tabId) {
  return codexTuiReadyTabs.has(tabId)
    || codexWatchers.has(tabId)
    || codexTurnWatchers.has(tabId)
    || !!getCodexWriterProofSnapshot(tabId)
    || codexPromptInFlight.has(tabId);
}

function captureCodexPtySubmitAdmission(tabId, term, expectedInputRevision = null) {
  const state = terminalCommandState.get(tabId) || null;
  const currentInputRevision = getTerminalInputRevision(tabId);
  if (
    expectedInputRevision !== null
    && currentInputRevision !== Number(expectedInputRevision)
  ) {
    return {
      available: false,
      reason: 'codex_input_ownership_changed',
      runSeq: Number(state?.runSeq || 0),
      inputRevision: currentInputRevision,
      tabId,
      term,
    };
  }
  return {
    ...createCodexPtySubmitAdmission({
      processRunning: state?.isRunning === true,
      hasLiveCodexEvidence: codexHasLivePtySubmitEvidence(tabId),
      stopping: aiStoppingTabs.get(tabId)?.toolType === 'codex',
      inputReadinessProofPending: !isCodexTuiEffectivelyReady(tabId),
      runSeq: state?.runSeq || 0,
      inputRevision: currentInputRevision,
    }),
    tabId,
    term,
  };
}

function revalidateCodexPtySubmitAdmission(token) {
  if (!token?.tabId || terminals.get(token.tabId) !== token.term) {
    return { valid: false, reason: 'codex_terminal_generation_changed' };
  }
  const state = terminalCommandState.get(token.tabId) || null;
  return validateCodexPtySubmitAdmission(token, {
    processRunning: state?.isRunning === true,
    hasLiveCodexEvidence: codexHasLivePtySubmitEvidence(token.tabId),
    stopping: aiStoppingTabs.get(token.tabId)?.toolType === 'codex',
    inputReadinessProofPending: !isCodexTuiEffectivelyReady(token.tabId),
    runSeq: state?.runSeq || 0,
    inputRevision: getTerminalInputRevision(token.tabId),
  });
}

function captureClaudePromptQueuePtyAdmission(tabId, term) {
  const state = terminalCommandState.get(tabId) || null;
  const runSeq = Number(state?.runSeq || 0);
  if (!tabId || terminals.get(tabId) !== term) {
    return { available: false, reason: 'claude_terminal_generation_changed', runSeq, tabId, term };
  }
  if (aiStoppingTabs.get(tabId)?.toolType === 'claude') {
    return { available: false, reason: 'claude_input_not_ready', runSeq, tabId, term };
  }
  if (state?.isRunning !== true || !hasLiveClaudeInTab(tabId)) {
    return { available: false, reason: 'claude_input_not_ready', runSeq, tabId, term };
  }
  if (!claudePromptReady.has(tabId)
    || claudeTurnBusy.get(tabId) === true
    || claudeLocalCommandWatchers.has(tabId)) {
    return { available: false, reason: 'claude_input_not_ready', runSeq, tabId, term };
  }
  return { available: true, reason: null, runSeq, tabId, term };
}

function revalidateClaudePromptQueuePtyAdmission(token) {
  if (!token?.available) {
    return { valid: false, reason: token?.reason || 'claude_input_not_ready' };
  }
  const current = captureClaudePromptQueuePtyAdmission(token.tabId, token.term);
  if (!current.available) return { valid: false, reason: current.reason };
  if (current.runSeq !== token.runSeq) {
    return { valid: false, reason: 'claude_process_generation_changed' };
  }
  return { valid: true, reason: null };
}

function getCodexSavedSessionId(tabId) {
  return codexSessionIdFromDb(tabId) || codexKnownSessions.get(tabId) || null;
}

function getCodexPublicWriterFields(tabId) {
  const proof = getCodexWriterProofSnapshot(tabId);
  return {
    writerConfirmed: !!proof,
    writerUsableForMutation: !!proof && isCodexWriterUsableForMutation(tabId),
    canCopySessionId: !!proof && isCodexWriterUsableForMutation(tabId),
    provenWriterSessionId: proof?.sessionId || null,
    savedSessionId: getCodexSavedSessionId(tabId),
    resumeSourceSessionId: codexLastRunCommandPayload.get(tabId)?.sessionId || null,
  };
}

function getCodexPublicRuntimeProjection(tabId) {
  const turnState = codexTurnStateSnapshot(codexTurnWatchers.get(tabId) || null);
  const providerTurnBusy = codexProviderSemanticSources.get(tabId)?.turnActive === true;
  const turnBusy = turnState.busy === true || providerTurnBusy;
  const stopping = aiStoppingTabs.get(tabId)?.toolType === 'codex';
  const proofPending = codexLateMcpProofPending.has(tabId);
  return projectCodexPublicRuntimeProjection({
    liveLifecycle: null,
    stopping,
    turnBusy,
    tuiInputReady: isCodexTuiEffectivelyReady(tabId),
    tuiLifecycleEstablished: hasCodexEstablishedComposerLifecycle(tabId),
    inputControlActive: !!getCodexLiveInputControl(tabId),
    inputProofPending: proofPending,
    writerUsableForMutation: isCodexWriterUsableForMutation(tabId),
    writerUiLifecycleEstablished: hasCodexEstablishedWriterUiLifecycle(tabId),
    hasEstablishedLifecycle: true,
  });
}

function projectCodexRuntimeSnapshotFromEvents(
  tabId,
  projectId = null,
  persistedSessionIdHint = undefined,
  trustedProjectHint = false,
) {
  const commandState = terminalCommandState.get(tabId) || null;
  const currentTerminal = terminals.get(tabId) || null;
  const currentLifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const currentRunSeq = Number(commandState?.runSeq || 0);
  const rawProof = codexWriterProofs.get(tabId) || null;
  const writerInspection = projectCodexWriterInspectionFromProof({
    proof: rawProof,
    knownSessionId: codexKnownSessions.get(tabId) || null,
    terminalToken: rawProof?.terminalToken || null,
    currentTerminalToken: currentTerminal,
    lifecycleGeneration: rawProof?.lifecycleGeneration || null,
    currentLifecycleGeneration,
    runSeq: rawProof?.runSeq || 0,
    currentRunSeq,
    commandRunning: commandState?.isRunning === true,
  });
  const discovery = codexWatchers.get(tabId) || null;
  const provisionalSource = getCurrentCodexProvisionalSourceObservation(tabId);
  const hasLiveEvent = commandState?.isRunning === true && (
    !!writerInspection
    || !!codexLastRunCommandPayload.get(tabId)
    || !!discovery
    || codexTuiReadyTabs.has(tabId)
    || codexTurnWatchers.has(tabId)
  );
  const liveLifecycle = writerInspection || hasLiveEvent
    ? true
    : !currentTerminal || commandState?.isRunning === false
      ? false
      : null;
  const turn = codexTurnWatchers.get(tabId) || null;
  const turnState = codexTurnStateSnapshot(turn);
  const stopping = liveLifecycle !== false && aiStoppingTabs.get(tabId)?.toolType === 'codex';
  const busy = liveLifecycle !== false && (
    turnState.busy === true
    || codexProviderSemanticSources.get(tabId)?.turnActive === true
  );
  const proofPending = codexLateMcpProofPending.has(tabId);
  const writerConfirmed = liveLifecycle === true && !!writerInspection?.sessionId;
  const writerUsableForMutation = writerConfirmed && isCodexWriterUsableForMutation(tabId);
  const publicRuntime = projectCodexPublicRuntimeProjection({
    liveLifecycle,
    stopping,
    turnBusy: busy,
    tuiInputReady: isCodexTuiEffectivelyReady(tabId),
    tuiLifecycleEstablished: hasCodexEstablishedComposerLifecycle(tabId),
    inputControlActive: !!getCodexLiveInputControl(tabId),
    inputProofPending: proofPending,
    writerUsableForMutation,
    writerUiLifecycleEstablished: writerUsableForMutation
      || hasCodexEstablishedWriterUiLifecycle(tabId),
    hasEstablishedLifecycle: hasEstablishedCodexLifecycleIndicators(tabId),
  });
  const inputReady = publicRuntime.inputReady;
  const sessionStatus = publicRuntime.sessionStatus;
  const scopedProjectId = trustedProjectHint === true && projectId
    ? projectId
    : resolveAuthoritativeTabProjectId(tabId, projectId);
  const dbSessionId = persistedSessionIdHint !== undefined
    ? (persistedSessionIdHint || null)
    : codexSessionIdFromDb(tabId, scopedProjectId);
  const knownSessionId = codexKnownSessions.get(tabId) || null;
  const savedSessionId = dbSessionId || knownSessionId || null;
  const provenWriterSessionId = writerInspection?.sessionId || null;
  const sessionId = liveLifecycle === false ? savedSessionId : provenWriterSessionId;

  const currentPayload = codexLastRunCommandPayload.get(tabId) || null;
  const currentIntent = codexSessionDiscoveryIntents.get(tabId) || null;
  const currentResumeLease = getCodexResumeSourceLeaseForTab(tabId);
  const currentResumeReadLease = getCodexResumeReadIdentityLeaseForTab(tabId);
  const currentReadinessLaunch = currentPayload || currentResumeReadLease;
  const currentReadLaunch = currentPayload?.command === 'codex-c'
    ? currentPayload
    : currentResumeReadLease;
  const readIdentity = resolveCodexReadIdentity({
    tabId,
    liveLifecycle,
    savedSessionId,
    persistedSessionId: dbSessionId,
    provenWriterSessionId,
    writerConfirmed,
    writerUsableForMutation,
    writerProof: rawProof?.kind || null,
    writerStatus: writerInspection
      ? 'adopted'
      : provisionalSource
        ? 'provisional-source'
        : liveLifecycle === false
          ? 'absent'
          : 'pending',
    observedWriterSessionId: writerInspection?.sessionId || provisionalSource?.sessionId || null,
    resumeSourceSessionId: currentReadLaunch?.sessionId || null,
    launch: currentPayload?.command === 'codex-c' ? currentPayload : null,
    resumeReadLease: currentResumeReadLease,
    intent: currentIntent,
    resumeLease: currentResumeLease,
    sourceTurn: turn,
    terminalToken: currentTerminal,
    terminalRunSeq: currentRunSeq,
    terminalLifecycleGeneration: currentLifecycleGeneration,
    processRunning: commandState?.isRunning === true,
    processPids: writerInspection?.pids || provisionalSource?.pids || [],
    promptOrTurnInFlight: hasCodexPromptOrTurnInFlight(tabId),
    provisionalSubmitReserved: !!discovery?.provisionalSubmitReservation,
    submitResolutionPending: codexReadIdentitySubmitPending.get(tabId) || null,
  });

  const materializationSessionId = provenWriterSessionId || savedSessionId || null;
  const directMaterialization = materializationSessionId
    ? codexConversationMaterializationCache.get(materializationSessionId) || null
    : null;
  const lineageSourceSessionId = String(
    writerInspection?.forkedFromId || writerInspection?.sourceSessionId || '',
  ).trim() || null;
  const lineageMaterialization = lineageSourceSessionId
    ? codexConversationMaterializationCache.get(lineageSourceSessionId) || null
    : null;
  const visibleMaterialization = directMaterialization?.materialized === true
    ? directMaterialization
    : lineageMaterialization?.materialized === true
      ? {
        ...lineageMaterialization,
        materialized: true,
        metadataOnly: false,
        writerMetadataOnly: directMaterialization?.metadataOnly === true,
        reason: 'fork-source-history-present',
      }
      : directMaterialization;
  const conversationMaterialized = visibleMaterialization?.materialized === true;
  const transcriptStatus = conversationMaterialized
    ? lineageSourceSessionId && directMaterialization?.materialized !== true
      ? 'lineage-ready'
      : 'ready'
    : directMaterialization?.metadataOnly === true
      ? lineageSourceSessionId
        ? 'lineage-unresolved'
        : 'metadata-only'
      : 'unavailable';
  const historyActions = projectCodexHistoryActionAvailability({
    liveLifecycle,
    savedSessionId,
    inputReady,
    busy,
    stopping,
    promptOrTurnInFlight: hasCodexPromptOrTurnInFlight(tabId),
    writerUsableForMutation,
    provisionalResumeAvailable: readIdentity.available === true
      && readIdentity.source === 'resume-source'
      && readIdentity.sessionId === savedSessionId,
    conversationMaterialized,
  });
  const forkSnapshot = projectCodexForkSnapshotAvailability({
    liveLifecycle,
    savedSessionId,
    inputReady,
    busy,
    stopping,
    promptOrTurnInFlight: hasCodexPromptOrTurnInFlight(tabId),
    writerUsableForMutation,
    provisionalResumeAvailable: readIdentity.available === true
      && readIdentity.source === 'resume-source'
      && readIdentity.sessionId === savedSessionId,
    conversationMaterialized,
  });
  const manualAction = codexManualActionRequired.get(tabId) || null;
  const textReady = isCodexTuiEffectivelyReady(tabId);
  const lastNotReady = codexTuiReadyLastNotReady.get(tabId)
    || (!textReady ? getCodexMcpStartupStatus(tabId) : null)
    || null;
  const startupProofFailure = lastNotReady?.startupFailed === true ? lastNotReady : null;
  const startupTimeout = codexStartupNoStateTimeoutTabs.has(tabId)
    ? getCodexStartupNoStateTimeout(tabId)
    : null;
  // Presence is the level-triggered public runtime contract. Include the
  // exact launch-owned settings proof here as well as in the one-shot
  // `codex:tui-ready` event; a renderer that subscribes after the ready edge
  // must still recover the accepted model/effort without a second process
  // lookup or a guessed value from the tab database.
  const provisionalSettings = liveLifecycle === true
    ? getCodexProvisionalSettingsSnapshot(tabId)
    : null;

  return {
    success: true,
    tabId,
    projectId: scopedProjectId,
    sessionId,
    displaySessionId: sessionId,
    readSessionId: readIdentity.sessionId,
    readIdentitySource: readIdentity.source,
    readIdentityReason: readIdentity.reason,
    sessionStatus,
    busy,
    inputReady,
    proofPending,
    hasTerm: !!currentTerminal,
    lastNotReady,
    startupFailed: !!startupTimeout || !!startupProofFailure,
    startupError: startupProofFailure?.startupError
      || startupProofFailure?.reason
      || startupTimeout?.reason
      || null,
    manualActionRequired: !!manualAction,
    manualActionType: manualAction?.type || null,
    lifecycleWarning: codexLifecycleWarnings.get(tabId) || null,
    liveLifecycle,
    lifecycleGeneration: liveLifecycle === false ? null : currentLifecycleGeneration,
    processObservation: writerInspection || hasLiveEvent
      ? 'found'
      : liveLifecycle === false
        ? 'absent'
        : 'unknown',
    knownSessionId,
    dbSessionId,
    savedSessionId,
    provenWriterSessionId,
    writerConfirmed,
    writerUsableForMutation,
    writerProof: writerConfirmed ? rawProof?.kind || null : null,
    writerStatus: writerInspection
      ? 'adopted'
      : provisionalSource
        ? 'provisional-source'
        : liveLifecycle === false
          ? 'absent'
          : 'pending',
    writerObservationSource: 'event-projection',
    writerSourceMatch: writerInspection?.sourceMatch || null,
    writerSourceSessionId: writerInspection?.sourceSessionId || null,
    writerForkedFromId: writerInspection?.forkedFromId || null,
    writerLaunchId: writerInspection?.launchId || null,
    launchId: writerInspection?.launchId || (
      currentReadinessLaunch?.terminalToken === currentTerminal
      && currentReadinessLaunch?.runSeq === currentRunSeq
      && currentReadinessLaunch?.lifecycleGeneration === currentLifecycleGeneration
      && commandState?.isRunning === true ? currentReadinessLaunch.launchId : null
    ),
    canCopySessionId: readIdentity.available === true,
    canNativeRewind: historyActions.canNativeRewind,
    canRewriteHistory: historyActions.canRewriteHistory,
    canDeleteHistory: historyActions.canDeleteHistory,
    historyActionReason: historyActions.reason,
    canForkSnapshot: forkSnapshot.canForkSnapshot,
    forkSnapshotReason: forkSnapshot.reason,
    conversationMaterialized,
    metadataOnlySession: visibleMaterialization?.metadataOnly === true,
    writerMetadataOnlySession: visibleMaterialization?.writerMetadataOnly === true,
    historyLineageSourceSessionId: lineageSourceSessionId,
    transcriptStatus,
    timelineCount: lineageSourceSessionId
      ? null
      : Number.isFinite(Number(visibleMaterialization?.userTurns))
        ? Number(visibleMaterialization.userTurns)
        : null,
    materializationReason: visibleMaterialization?.reason || 'history-read-unavailable',
    hasWatcher: turnState.hasWatcher === true,
    catchUpPending: turnState.catchUpPending === true,
    outcomeKnown: turnState.outcomeKnown === true,
    lastOutcomeReason: turnState.lastOutcomeReason || null,
    hasLaunchPayload: !!currentPayload,
    ...(provisionalSettings || {}),
  };
}

function publishCodexRuntimeProjection(tabId, reason = 'runtime-event', projectId = null) {
  if (!tabId) return null;
  return codexRuntimeProjectionStore.publish(
    tabId,
    projectCodexRuntimeSnapshotFromEvents(tabId, projectId),
    reason,
  );
}

function getCodexRuntimeProjectionBatch(tabDescriptors, projectId = null) {
  const result = {};
  for (const descriptor of Array.isArray(tabDescriptors) ? tabDescriptors : []) {
    const tabId = typeof descriptor === 'string' ? descriptor : descriptor?.tabId;
    if (!tabId) continue;
    const persistedSessionIdHint = typeof descriptor === 'object'
      ? descriptor.savedSessionId ?? null
      : undefined;
    let snapshot = codexRuntimeProjectionStore.read(tabId);
    if (!snapshot || (projectId && snapshot.projectId !== projectId)) {
      snapshot = codexRuntimeProjectionStore.publish(
        tabId,
        projectCodexRuntimeSnapshotFromEvents(
          tabId,
          projectId,
          persistedSessionIdHint,
          true,
        ),
        'project-api-seed',
      );
    }
    if (snapshot) result[tabId] = snapshot;
  }
  return result;
}

function broadcastCodexPublicRuntimeSnapshot(tabId, reason = 'runtime-snapshot') {
  publishCodexRuntimeProjection(tabId, reason);
  const runtimeProjection = getCodexPublicRuntimeProjection(tabId);
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId: getCodexRuntimeSessionId(tabId),
    busy: runtimeProjection.busy,
    sessionStatus: runtimeProjection.sessionStatus,
    starting: runtimeProjection.sessionStatus === 'starting',
    toolType: 'codex',
    commandType: 'codex',
    inputReady: runtimeProjection.inputReady,
    reason,
    ...getCodexPublicWriterFields(tabId),
  });
}

function getLiveAiRuntimeOwners(tabId) {
  const runtimeOwners = [];
  if (codexKnownSessions.has(tabId) || codexLastRunCommandPayload.has(tabId) || codexTurnWatchers.has(tabId) || codexTuiReadyTabs.has(tabId)) runtimeOwners.push('codex');
  if (bridgeKnownSessions.has(tabId) || claudePromptReady.has(tabId) || claudeTurnBusy.has(tabId) || claudeSpinnerBusy.has(tabId) || claudeLocalCommandWatchers.has(tabId)) runtimeOwners.push('claude');
  if (geminiActiveTabs.has(tabId) || geminiSpinnerBusy.has(tabId)) runtimeOwners.push('gemini');
  return runtimeOwners;
}

function resolveAiToolTypeForTab(tabId, fallback = null) {
  const runtimeOwners = getLiveAiRuntimeOwners(tabId);
  if (runtimeOwners.length > 0) {
    const liveOwner = resolveAiToolOwner({ runtimeOwners });
    if (liveOwner) return liveOwner;
    console.warn('[AiToolOwner] ambiguous live runtimes tab=' + String(tabId).slice(-12)
      + ' owners=' + runtimeOwners.join(','));
    return null;
  }
  try {
    const row = projectManager?.db?.db?.prepare(
      'SELECT command_type, claude_session_id, codex_session_id FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId);
    const persistedOwner = resolveAiToolOwner({
      claudeSessionId: row?.claude_session_id || null,
      codexSessionId: row?.codex_session_id || null,
      fallback,
      storedCommandType: row?.command_type || null,
    });
    if (!persistedOwner && row?.claude_session_id && row?.codex_session_id) {
      console.warn('[AiToolOwner] ambiguous persisted bindings tab=' + String(tabId).slice(-12));
    }
    return persistedOwner;
  } catch {}
  return resolveAiToolOwner({ fallback });
}

function getAiRuntimeSessionId(tabId, toolType) {
  if (toolType === 'codex') return getCodexRuntimeSessionId(tabId);
  if (toolType === 'claude') return bridgeKnownSessions.get(tabId) || null;
  return null;
}

function broadcastAiRuntimeStatus(tabId, toolType, sessionStatus, reason, runtimeProjection = null) {
  if (!tabId || (toolType !== 'claude' && toolType !== 'codex')) return;
  const busy = typeof runtimeProjection?.busy === 'boolean'
    ? runtimeProjection.busy
    : sessionStatus === 'busy' || sessionStatus === 'stopping';
  const inputReady = typeof runtimeProjection?.inputReady === 'boolean'
    ? runtimeProjection.inputReady
    : sessionStatus === 'active';
  let sessionId = sessionStatus === 'inactive' ? null : getAiRuntimeSessionId(tabId, toolType);
  let transcriptState = {};
  if (toolType === 'claude') {
    let persisted = null;
    try {
      persisted = projectManager?.db?.db?.prepare(
        'SELECT project_id, claude_session_id, cwd FROM tabs WHERE tab_id = ? LIMIT 1'
      ).get(tabId) || null;
    } catch {}
    const materializationSessionId = persisted?.claude_session_id || bridgeKnownSessions.get(tabId) || null;
    let materialization = null;
    if (materializationSessionId && getSessionMaterialization) {
      try {
        materialization = getSessionMaterialization(materializationSessionId, persisted?.cwd || process.cwd());
      } catch (err) {
        console.warn('[AiRuntimeStatus] materialization check failed tab=' + String(tabId).slice(-12) + ' session=' + String(materializationSessionId).slice(0, 8) + ' err=' + (err?.message || String(err)));
      }
    }
    const conversationMaterialized = materialization?.materialized === true;
    if (!sessionId && materializationSessionId) sessionId = materializationSessionId;
    transcriptState = {
      conversationMaterialized,
      canResume: sessionStatus === 'inactive' && conversationMaterialized,
      canCopySessionId: conversationMaterialized,
      timelineCount: typeof materialization?.timelineCount === 'number' ? materialization.timelineCount : null,
      materializationReason: materialization?.reason || null,
    };
    if (sessionStatus === 'inactive' && persisted?.project_id) {
      scheduleProjectLayoutBroadcast(persisted.project_id, 'claude-runtime-inactive');
    }
  } else if (toolType === 'codex') {
    let persisted = null;
    try {
      persisted = projectManager?.db?.db?.prepare(
        'SELECT project_id, codex_session_id, cwd FROM tabs WHERE tab_id = ? LIMIT 1'
      ).get(tabId) || null;
    } catch {}
    const writerProof = getCodexWriterProofSnapshot(tabId);
    const writerSessionId = writerProof?.sessionId || null;
    const writerUsableForMutation = !!writerSessionId && isCodexWriterUsableForMutation(tabId);
    const savedSessionId = persisted?.codex_session_id || null;
    const materializationSessionId = writerSessionId || savedSessionId || null;
    if (sessionStatus === 'inactive') {
      sessionId = savedSessionId || writerSessionId || null;
    } else {
      sessionId = writerSessionId;
    }
    const cachedMaterialization = materializationSessionId
      ? codexConversationMaterializationCache.get(materializationSessionId) || null
      : null;
    const conversationMaterialized = cachedMaterialization
      ? cachedMaterialization.materialized === true
      : !!materializationSessionId;
    transcriptState = {
      conversationMaterialized,
      canResume: sessionStatus === 'inactive' && !!savedSessionId,
      canCopySessionId: sessionStatus === 'inactive'
        ? !!savedSessionId
        : writerUsableForMutation,
      timelineCount: cachedMaterialization
        ? Number(cachedMaterialization.userTurns || 0)
        : null,
      materializationReason: cachedMaterialization?.reason
        || (conversationMaterialized ? 'codex-session-id' : 'no-session-id'),
      writerConfirmed: sessionStatus !== 'inactive' && !!writerSessionId,
      writerUsableForMutation: sessionStatus !== 'inactive' && writerUsableForMutation,
      savedSessionId,
      resumeSourceSessionId: codexLastRunCommandPayload.get(tabId)?.sessionId || null,
    };
    if (sessionStatus === 'inactive' && persisted?.project_id) {
      scheduleProjectLayoutBroadcast(persisted.project_id, 'codex-runtime-inactive');
    }
  }
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId,
    busy,
    sessionStatus,
    starting: sessionStatus === 'starting',
    stopping: sessionStatus === 'stopping',
    inputReady,
    toolType,
    commandType: toolType,
    reason,
    ...transcriptState,
  });
}

function restoreAiRuntimeStatusAfterFailedStop(tabId, toolType, reason = 'stop-failed') {
  if (!tabId || (toolType !== 'claude' && toolType !== 'codex')) return;
  if (toolType === 'codex') {
    const runtimeProjection = getCodexPublicRuntimeProjection(tabId);
    broadcastAiRuntimeStatus(tabId, toolType, runtimeProjection.sessionStatus, reason, runtimeProjection);
    return;
  }

  const runtimeProjection = resolveClaudeRuntimeAfterFailedStop({
    claudeTurnBusy: claudeTurnBusy.get(tabId) === true,
    claudePromptReady: claudePromptReady.has(tabId),
  });
  broadcastAiRuntimeStatus(
    tabId,
    toolType,
    runtimeProjection.sessionStatus,
    reason,
    runtimeProjection,
  );
}

function markAiStopping(tabId, toolType, reason = 'manual-stop', options = {}) {
  const resolvedTool = resolveAiToolTypeForTab(tabId, toolType);
  if (!tabId || !resolvedTool) return null;
  if (resolvedTool === 'codex') codexCapacityRetryRuntime?.cancel(tabId, reason);
  const publicLifecycle = options.publicLifecycle !== false;
  const prev = aiStoppingTabs.get(tabId) || null;
  const sessionId = getAiRuntimeSessionId(tabId, resolvedTool);
  if (prev && prev.toolType === resolvedTool && prev.reason === reason) {
    if (!prev.sessionId && sessionId) {
      prev.sessionId = sessionId;
      aiStoppingTabs.set(tabId, prev);
    }
    console.log('[AgentStopping] keep tab=' + String(tabId).slice(-12) +
      ' tool=' + resolvedTool +
      ' reason=' + reason +
      ' session=' + (prev.sessionId ? String(prev.sessionId).slice(0, 8) : 'none') +
      ' ageMs=' + (Date.now() - prev.since));
    return prev;
  }
  const state = {
    toolType: resolvedTool,
    reason,
    since: prev?.since || Date.now(),
    sessionId,
    publicLifecycle,
  };
  aiStoppingTabs.set(tabId, state);
  if (resolvedTool === 'codex') {
    revokeCodexActionAuthoritiesForTab(tabId, 'stop-start:' + reason);
    invalidateCodexExitObservers(tabId, 'stop-start:' + reason);
  }
  console.log('[AgentStopping] start tab=' + String(tabId).slice(-12) +
    ' tool=' + resolvedTool +
    ' reason=' + reason +
    ' session=' + (state.sessionId ? String(state.sessionId).slice(0, 8) : 'none'));
  if (publicLifecycle && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('agent:stopping-state', { tabId, toolType: resolvedTool, stopping: true, reason, since: state.since });
  }
  if (publicLifecycle) broadcastAiRuntimeStatus(tabId, resolvedTool, 'stopping', reason);
  emitAgentReadinessChanged(tabId, { toolType: resolvedTool, status: 'stopping', reason });
  return state;
}

function clearAiStopping(tabId, reason = 'clear', options = {}) {
  const state = aiStoppingTabs.get(tabId) || null;
  const toolType = resolveAiToolTypeForTab(tabId, options.toolType || state?.toolType || null);
  if (state) {
    aiStoppingTabs.delete(tabId);
    console.log('[AgentStopping] clear tab=' + String(tabId).slice(-12) +
      ' tool=' + (state.toolType || toolType || '-') +
      ' reason=' + reason +
      ' ageMs=' + (Date.now() - state.since));
    if (state.publicLifecycle !== false && mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('agent:stopping-state', { tabId, toolType: toolType || state.toolType || null, stopping: false, reason });
    }
  }
  if (options.broadcastInactive && toolType) {
    broadcastAiRuntimeStatus(tabId, toolType, 'inactive', reason);
  }
}

function exactShutdownCandidatesForTab(tabId) {
  const candidates = [];
  const bridgeSessionId = bridgeKnownSessions.get(tabId) || null;
  if (bridgeSessionId) candidates.push({ engine: 'claude', sessionId: bridgeSessionId, source: 'bridge' });

  const writerSessionId = getCodexWriterProofSnapshot(tabId)?.sessionId || null;
  if (writerSessionId) candidates.push({ engine: 'codex', sessionId: writerSessionId, source: 'writer-proof' });

  const execution = getActiveAgentExecutionContext(tabId);
  if (execution?.sessionId && (execution.provider === 'claude' || execution.provider === 'codex')) {
    candidates.push({ engine: execution.provider, sessionId: execution.sessionId, source: 'active-turn' });
  }

  const stopping = aiStoppingTabs.get(tabId) || null;
  if (stopping?.sessionId && (stopping.toolType === 'claude' || stopping.toolType === 'codex')) {
    candidates.push({ engine: stopping.toolType, sessionId: stopping.sessionId, source: 'stopping' });
  }
  return candidates;
}

function getInterruptedAiSessionEntries() {
  const entries = new Map();
  const tabIds = new Set([
    ...terminals.keys(),
    ...bridgeKnownSessions.keys(),
    ...codexKnownSessions.keys(),
    ...aiStoppingTabs.keys(),
  ]);
  for (const tabId of tabIds) {
    const resolved = resolveExactShutdownTarget(exactShutdownCandidatesForTab(tabId));
    if (resolved.target) entries.set(tabId, resolved.target);
    else if (resolved.ambiguous) {
      console.warn('[Shutdown:Identity] ambiguous tab=' + String(tabId).slice(-12)
        + ' identities=' + resolved.identities.map((item) => item.engine + ':' + item.sessionId.slice(0, 8)).join(','));
    }
  }
  return entries;
}

function initialShutdownLiveTabIds(exactEntries) {
  const live = new Set(exactEntries ? exactEntries.keys() : []);
  for (const tabId of terminals.keys()) {
    if (bridgeKnownSessions.has(tabId) || getCodexWriterProofSnapshot(tabId)) live.add(tabId);
    if (getActiveAgentExecutionContext(tabId) || aiStoppingTabs.has(tabId)) live.add(tabId);
  }
  return live;
}

function getPersistedAiSessionBindingForShutdown(tabId) {
  try {
    return projectManager?.db?.db?.prepare(
      'SELECT command_type, claude_session_id, codex_session_id FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId) || null;
  } catch {
    return null;
  }
}

function captureCodexShutdownScope(tabId) {
  return {
    terminalToken: terminals.get(tabId) || null,
    projectId: resolveAuthoritativeTabProjectId(tabId),
    runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    launchId: codexSessionDiscoveryIntents.get(tabId)?.launchId
      || codexLastRunCommandPayload.get(tabId)?.launchId
      || getCodexResumeReadIdentityLeaseForTab(tabId)?.launchId
      || getCodexWriterProofSnapshot(tabId)?.launchId
      || null,
    inputRevision: getTerminalInputRevision(tabId),
    writerObservationGeneration: getCodexWriterObservationGeneration(tabId),
    exitObserverGeneration: getCodexExitObserverGeneration(tabId),
  };
}

function readCodexShutdownEvidence(tabId, inspection) {
  const scope = captureCodexShutdownScope(tabId);
  const payload = codexLastRunCommandPayload.get(tabId) || null;
  const readLease = getCodexResumeReadIdentityLeaseForTab(tabId);
  const readLaunch = payload?.command === 'codex-c' ? payload : readLease;
  const persistedSessionId = codexSessionIdFromDb(tabId, scope.projectId);
  return {
    writerSessionId: getCodexWriterProofSnapshot(tabId)?.sessionId || null,
    exactCandidates: exactShutdownCandidatesForTab(tabId),
    allowIdleResume: readLaunch?.materializedFresh === false,
    // Consume the same complete lease as read/copy, not its UI boolean or a
    // saved-id fallback. This result is recovery-only and never adopted.
    readIdentity: inspection.status === 'provisional-source'
      ? resolveCodexReadIdentity({
        tabId,
        liveLifecycle: true,
        persistedSessionId,
        writerStatus: inspection.status,
        observedWriterSessionId: inspection.sessionId,
        resumeSourceSessionId: readLaunch?.sessionId || null,
        launch: payload?.command === 'codex-c' ? payload : null,
        resumeReadLease: readLease,
        intent: codexSessionDiscoveryIntents.get(tabId) || null,
        resumeLease: getCodexResumeSourceLeaseForTab(tabId),
        sourceTurn: codexTurnWatchers.get(tabId) || null,
        terminalToken: scope.terminalToken,
        terminalRunSeq: scope.runSeq,
        terminalLifecycleGeneration: scope.lifecycleGeneration,
        processRunning: terminalCommandState.get(tabId)?.isRunning === true,
        processPids: inspection.pids || [],
        promptOrTurnInFlight: hasCodexPromptOrTurnInFlight(tabId),
        provisionalSubmitReserved: !!codexWatchers.get(tabId)?.provisionalSubmitReservation,
        submitResolutionPending: codexReadIdentitySubmitPending.get(tabId) || null,
      })
      : null,
  };
}

/**
 * Process lookup answers only liveness/provider. A missing Codex writer gets
 * one bounded canonical reconciliation; an untouched Resume may separately
 * prove its exact source recovery lease. Neither path guesses an id from DB.
 * Sequential reads share one process-tree snapshot and avoid a new ps storm.
 */
async function augmentShutdownStateFromProcessProof(seedEntries, seedLiveTabIds) {
  const entries = new Map(seedEntries || []);
  const liveTabIds = new Set(seedLiveTabIds || []);
  const codexProofDeadline = Date.now() + 4500;
  for (const tabId of terminals.keys()) {
    const terminalToken = terminals.get(tabId) || null;
    const intentBefore = claudeStartupIntents.get(tabId) || null;
    const launchBefore = claudeLaunchGenerationByTab.get(tabId) || null;
    const runSeqBefore = Number(terminalCommandState.get(tabId)?.runSeq || 0);
    const codexScopeBefore = captureCodexShutdownScope(tabId);
    let lookup;
    try {
      // expectedName=null is deliberate: prove BOTH providers so a dual-owner
      // PTY cannot be misclassified by searching only the preferred label.
      lookup = await inspectAiDescendantProcessesByTab(tabId, null);
    } catch (error) {
      console.warn('[Shutdown:ProcessProof] unknown tab=' + String(tabId).slice(-12)
        + ' error=' + String(error?.message || error));
      continue;
    }
    const providers = new Set((lookup.matches || []).map((match) => match.processName).filter(Boolean));
    if (lookup.status === AI_PROCESS_LOOKUP_STATUS.FOUND) liveTabIds.add(tabId);
    if (providers.size > 1) {
      entries.delete(tabId);
      console.warn('[Shutdown:ProcessProof] ambiguous-live tab=' + String(tabId).slice(-12)
        + ' providers=' + [...providers].join(','));
      continue;
    }

    const provider = providers.size === 1 ? [...providers][0] : null;
    const existing = entries.get(tabId) || null;
    if (existing && provider && existing.engine !== provider) {
      entries.delete(tabId);
      console.warn('[Shutdown:ProcessProof] owner-mismatch tab=' + String(tabId).slice(-12)
        + ' exact=' + existing.engine + ' process=' + provider);
      continue;
    }
    if (provider === 'codex' && lookup.status === AI_PROCESS_LOOKUP_STATUS.FOUND) {
      const isCurrent = () => isCodexShutdownScopeCurrent(codexScopeBefore, captureCodexShutdownScope(tabId));
      const currentWriter = getCodexWriterProofSnapshot(tabId);
      const recovered = currentWriter
        ? (isCurrent()
          ? { ...resolveExactShutdownTarget(exactShutdownCandidatesForTab(tabId)), source: 'writer-proof', reason: 'current-writer-proof' }
          : { target: null, reason: 'shutdown-generation-changed' })
        : await reconcileCodexShutdownTarget({
          processFound: true,
          isCurrent,
          reconcileWriter: async () => {
            const inspection = await reconcileCodexWriterFromProcess(tabId, { reason: 'shutdown-recovery-proof' });
            // Reconciliation inspects Codex only. Recheck the provider set so
            // a second owner appearing during descriptor IO cannot be ignored.
            const currentLookup = await inspectAiDescendantProcessesByTab(tabId, null);
            const currentProviders = new Set((currentLookup.matches || []).map((match) => match.processName));
            return currentLookup.status === AI_PROCESS_LOOKUP_STATUS.FOUND
              && currentProviders.size === 1 && currentProviders.has('codex')
              ? inspection
              : { status: 'shutdown-process-owner-changed' };
          },
          readCurrentEvidence: (inspection) => readCodexShutdownEvidence(tabId, inspection),
          timeoutMs: Math.max(0, codexProofDeadline - Date.now()),
        });
      if (recovered.target) entries.set(tabId, recovered.target);
      else if (!isCurrent()
        || recovered.reason === 'exact-identity-conflict'
        || recovered.ambiguous === true
        || recovered.reason === 'shutdown-process-owner-changed') entries.delete(tabId);
      console.log('[Shutdown:CodexRecovery] tab=' + String(tabId).slice(-12)
        + ' source=' + (recovered.source || 'unresolved')
        + ' session=' + (recovered.target?.sessionId?.slice(0, 8) || 'none')
        + ' reason=' + recovered.reason
        + (recovered.error ? ' error=' + recovered.error : ''));
      continue;
    }
    if (existing || provider !== 'claude') {
      console.log('[Shutdown:ProcessProof] skip tab=' + String(tabId).slice(-12)
        + ' status=' + String(lookup?.status || 'unknown')
        + ' provider=' + String(provider || 'none')
        + ' exact=' + (existing ? existing.engine + ':' + existing.sessionId.slice(0, 8) : 'none'));
      continue;
    }

    // The session id comes from the accepted Resume write transaction, not
    // from the unrelated saved row. Re-read every identity after await.
    const intentAfter = claudeStartupIntents.get(tabId) || null;
    const launchAfter = claudeLaunchGenerationByTab.get(tabId) || null;
    const persistedAfter = getPersistedAiSessionBindingForShutdown(tabId);
    const runSeqAfter = Number(terminalCommandState.get(tabId)?.runSeq || 0);
    const candidate = resolveAcceptedClaudeResumeShutdownTarget({
      provider,
      processFound: lookup.status === AI_PROCESS_LOOKUP_STATUS.FOUND,
      intentSessionId: intentBefore?.sessionId || null,
      intentFresh: !!intentBefore && (Date.now() - intentBefore.at) < 60_000,
      intentTerminalMatches: !!terminalToken
        && intentBefore?.terminalToken === terminalToken
        && terminals.get(tabId) === terminalToken,
      launchMode: launchBefore?.launchMode || null,
      launchSessionId: launchBefore?.sessionIdHint || null,
      generationMatches: !!launchBefore?.generation
        && launchAfter?.generation === launchBefore.generation
        && intentAfter === intentBefore,
      runGenerationMatches: runSeqAfter === runSeqBefore,
      persistedSessionId: persistedAfter?.claude_session_id || null,
    });
    if (!candidate) continue;

    const resolved = resolveExactShutdownTarget([
      ...exactShutdownCandidatesForTab(tabId),
      candidate,
    ]);
    if (!resolved.target) {
      console.warn('[Shutdown:ProcessProof] accepted-resume-conflict tab=' + String(tabId).slice(-12));
      continue;
    }
    entries.set(tabId, resolved.target);
    console.log('[Shutdown:ProcessProof] include tab=' + String(tabId).slice(-12)
      + ' tool=' + resolved.target.engine
      + ' session=' + resolved.target.sessionId.slice(0, 8)
      + ' source=accepted-resume'
      + ' pids=' + (lookup.matches || []).map((match) => match.pid).join(','));
  }
  return { recoverableEntries: entries, liveTabIds };
}

function markInterruptedAiSessionEntries(entries, reason) {
  if (!projectManager?.db?.db) return 0;
  let marked = 0;
  const markStmt = projectManager.db.db.prepare(
    'UPDATE tabs SET was_interrupted = 1, overlay_dismissed = 0 WHERE tab_id = ?'
  );
  for (const [tabId] of entries || []) marked += markStmt.run(tabId).changes;
  persistShutdownInterruptedAgentSnapshot(entries || new Map(), reason);
  return marked;
}

function reconcileInterruptedAiSessionEntries(previousEntries, nextEntries, reason) {
  if (!projectManager?.db?.db) return { cleared: 0, marked: 0 };
  let cleared = 0;
  const clearStmt = projectManager.db.db.prepare(
    'UPDATE tabs SET was_interrupted = 0 WHERE tab_id = ?'
  );
  for (const [tabId] of previousEntries || []) {
    if (!nextEntries?.has(tabId)) cleared += clearStmt.run(tabId).changes;
  }
  const marked = markInterruptedAiSessionEntries(nextEntries, reason);
  return { cleared, marked };
}

let startupInterruptedAgentSnapshot = {
  version: 1,
  source: 'not-captured',
  capturedAt: null,
  shutdownPid: null,
  resolvedAt: null,
  targets: [],
  unresolved: [],
};

function persistShutdownInterruptedAgentSnapshot(entries, reason) {
  const snapshot = createShutdownInterruptedSnapshot(entries, {
    capturedAt: Date.now(),
    shutdownPid: process.pid,
    reason,
  });
  projectManager.db.setAppState(SHUTDOWN_INTERRUPTED_SESSIONS_KEY, snapshot);
  console.log('[Shutdown:ContinueSnapshot] reason=' + reason
    + ' targets=' + snapshot.targets.length
    + ' pid=' + process.pid);
  return snapshot;
}

function captureStartupInterruptedAgentSnapshot() {
  try {
    startupInterruptedAgentSnapshot = resolveStartupInterruptedSnapshot({
      persistedSnapshot: projectManager.db.getAppState(SHUTDOWN_INTERRUPTED_SESSIONS_KEY),
      projects: projectManager.db.getAllProjects(),
      resolvedAt: Date.now(),
    });
    console.log('[Startup:ContinueSnapshot] source=' + startupInterruptedAgentSnapshot.source
      + ' targets=' + startupInterruptedAgentSnapshot.targets.length
      + ' unresolved=' + startupInterruptedAgentSnapshot.unresolved.length
      + ' shutdownPid=' + (startupInterruptedAgentSnapshot.shutdownPid || '-'));
  } catch (error) {
    startupInterruptedAgentSnapshot = {
      version: 1,
      source: 'capture-failed',
      capturedAt: null,
      shutdownPid: null,
      resolvedAt: Date.now(),
      targets: [],
      unresolved: [{ reason: error?.message || String(error) }],
    };
    console.warn('[Startup:ContinueSnapshot] capture failed:', error?.message || error);
  }
  return startupInterruptedAgentSnapshot;
}

function formatInterruptedAiSessionIds(entries) {
  return Array.from(entries, ([tabId, info]) =>
    info.engine + ':' + String(tabId).slice(-7) + '=' + String(info.sessionId).slice(0, 8)
  ).join(',');
}

// ========== Claude Turn Event Bridge ==========
// Deterministic end-of-turn signal sourced from Claude Code's Stop hook.
// Hook script writes one JSON line per event into this socket. A known
// session_id is the primary route; the already-proven launch PID bridges the
// short first-turn window before statusLine binds the new JSONL to the tab.
// The resolved event is broadcast as 'claude:turn-state' to the renderer.
// Per-PID socket path so dev+prod (and N parallel instances) never stomp on
// each other. Before this fix: both instances wrote to /tmp/noted-terminal-claude-hook.sock,
// the second one unlink'd the first's socket and rebound — first instance's
// listener became zombie, all hook events from its Claude tabs went to whoever
// owned the path. Result: claudeTurnBusy stuck true forever → loader hangs.
// Hook script picks the right instance via the discovery dir below.
const CLAUDE_HOOK_DISCOVERY_DIR = path.join(os.homedir(), '.noted-terminal');
const CLAUDE_HOOK_SOCK = '/tmp/noted-terminal-claude-hook-' + process.pid + '.sock';
const CLAUDE_HOOK_DISCOVERY_FILE = path.join(CLAUDE_HOOK_DISCOVERY_DIR, 'claude-hook-' + process.pid + '.json');
// Legacy fixed path used by older hook-script versions — we still bind to it
// only if no live PID-specific socket exists (i.e. we're the sole instance).
// Kept for backward compat during the rollout; once new hook script ships to
// all users this can be removed.
const CLAUDE_HOOK_SOCK_LEGACY = '/tmp/noted-terminal-claude-hook.sock';
const claudeTurnBusy = new Map(); // tabId → boolean (true = turn in flight)
const claudePostEnterResolutionWaiters = new Map(); // tabId → Set<audit>

function wakeClaudePostEnterResolutionWaiter(audit, reason) {
  const waiter = audit?.postEnterResolutionWaiter || null;
  if (!waiter) return false;
  audit.postEnterResolutionWaiter = null;
  const waiting = claudePostEnterResolutionWaiters.get(waiter.tabId);
  if (waiting instanceof Set) {
    waiting.delete(audit);
    if (waiting.size === 0) claudePostEnterResolutionWaiters.delete(waiter.tabId);
  }
  waiter.resolve({ reason, auditFinished: audit.finished === true });
  return true;
}

function wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, reason) {
  const waiting = claudePostEnterResolutionWaiters.get(tabId);
  if (!(waiting instanceof Set) || waiting.size === 0) return 0;
  let resolved = 0;
  for (const audit of [...waiting]) {
    if (wakeClaudePostEnterResolutionWaiter(audit, 'turn-idle:' + reason)) {
      resolved += 1;
    }
  }
  return resolved;
}

function waitForClaudeAuditOrTurnIdle(tabId, audit) {
  if (!audit || audit.finished === true) {
    return Promise.resolve({ reason: 'audit-finished', auditFinished: true });
  }
  if (claudeTurnBusy.get(tabId) !== true) {
    return Promise.resolve({ reason: 'turn-already-idle', auditFinished: false });
  }
  if (audit.postEnterResolutionWaiter?.promise) {
    return audit.postEnterResolutionWaiter.promise;
  }
  let resolveWaiter;
  const promise = new Promise((resolve) => { resolveWaiter = resolve; });
  audit.postEnterResolutionWaiter = {
    tabId,
    promise,
    resolve: resolveWaiter,
  };
  let waiting = claudePostEnterResolutionWaiters.get(tabId);
  if (!(waiting instanceof Set)) {
    waiting = new Set();
    claudePostEnterResolutionWaiters.set(tabId, waiting);
  }
  waiting.add(audit);
  return promise;
}

function registerTaskCompletionIntent({ tabId, sourceTabId = null } = {}) {
  const current = taskCompletionIntents.getTurn(tabId);
  if (!current) return { ok: false, code: 'no_active_turn' };
  const liveBusy = current.provider === 'codex'
    ? codexTurnWatchers.get(tabId)?.busy === true
    : claudeTurnBusy.get(tabId) === true;
  if (!liveBusy) return { ok: false, code: 'no_active_turn' };
  return taskCompletionIntents.requestCompletion({ tabId, sourceTabId });
}

function getActiveAgentExecutionContext(tabId) {
  const turn = taskCompletionIntents.getTurn(tabId);
  if (!turn?.active || !turn.provider) return null;
  const liveBusy = turn.provider === 'codex'
    ? codexTurnWatchers.get(tabId)?.busy === true
    : claudeTurnBusy.get(tabId) === true;
  if (!liveBusy) return null;
  const turnId = turn.turnId || (turn.generation ? turn.provider + ':' + turn.generation : null);
  if (!turnId) return null;
  return {
    provider: turn.provider,
    sessionId: turn.sessionId || null,
    turnId,
    processId: turn.processId || null,
    generation: turn.generation || null,
    startedAt: turn.startedAt || null,
  };
}

function emitClaudeAbnormalTurnEnd(tabId, reason = 'process_exited') {
  const executionContext = getActiveAgentExecutionContext(tabId);
  if (!executionContext || executionContext.provider !== 'claude') {
    return { emitted: false, executionContext: null };
  }
  const taskTurn = taskCompletionIntents.finishTurn({
    tabId,
    provider: 'claude',
    sessionId: executionContext.sessionId,
    processId: executionContext.processId,
    success: false,
  });
  const taskTurnSnapshot = taskTurn?.turn || taskTurn || {};
  const turnId = taskTurnSnapshot?.generation
    ? 'claude:' + taskTurnSnapshot.generation
    : executionContext.turnId;
  const payload = {
    reason,
    provider: 'claude',
    sessionId: executionContext.sessionId || null,
    turnId,
    processId: executionContext.processId || null,
    turnGeneration: taskTurnSnapshot?.generation || executionContext.generation || null,
    turnStartedAt: taskTurnSnapshot?.startedAt || executionContext.startedAt || null,
    backgroundWorkCount: getCombinedTabBackgroundWorkCount(tabId),
  };
  claudeTurnBusy.set(tabId, false);
  claudeSpinnerBusy.set(tabId, false);
  wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, reason);
  claudeHookLastEvent.set(tabId, {
    event: 'AbnormalTurnEnd',
    ts: Date.now(),
    sessionId: payload.sessionId,
    turnId,
    reason,
  });
  _webBroadcast(tabId, { type: 'busy', busy: false, ...payload });
  _webBroadcast(tabId, { type: 'done', ...payload });
  console.warn('[ClaudeLifecycle] abnormal turn end tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' session=' + String(payload.sessionId || '-').slice(0, 8)
    + ' turn=' + String(turnId || '-'));
  return { emitted: true, executionContext };
}
const claudeTurnWatchdog = new Map(); // tabId → timeout ID (silent-tool-stop safety)
const CLAUDE_TURN_WATCHDOG_MS = 60 * 60 * 1000; // 60min — safety net against silent-tool-stop (#29881) and hook-script crashes; only fires when Stop legitimately never arrives
const CLAUDE_TURN_WATCHDOG_EXTENSION_MS = 15 * 60 * 1000;
const CLAUDE_TURN_WATCHDOG_SPINNER_LIVE_MS = 30 * 1000;
const CLAUDE_TURN_WATCHDOG_JSONL_LIVE_MS = 10 * 60 * 1000;

function formatWatchdogAge(ageMs) {
  return Number.isFinite(ageMs) ? Math.round(ageMs / 1000) + 's' : 'none';
}

function getClaudeTurnLiveness(tabId) {
  const now = Date.now();
  const lastSpinnerAt = claudeSpinnerLastSeenAt.get(tabId) || 0;
  const spinnerAgeMs = lastSpinnerAt ? now - lastSpinnerAt : Infinity;
  let jsonlAgeMs = Infinity;
  const watcher = claudeInterruptWatchers.get(tabId);
  if (watcher && watcher.filePath) {
    try {
      jsonlAgeMs = now - fs.statSync(watcher.filePath).mtimeMs;
    } catch {}
  }
  const liveProcess = hasLiveClaudeInTab(tabId);
  const activeArtifact =
    spinnerAgeMs <= CLAUDE_TURN_WATCHDOG_SPINNER_LIVE_MS ||
    jsonlAgeMs <= CLAUDE_TURN_WATCHDOG_JSONL_LIVE_MS;
  return { liveProcess, activeArtifact, spinnerAgeMs, jsonlAgeMs };
}

function scheduleClaudeTurnWatchdog(tabId, sessionId, delayMs = CLAUDE_TURN_WATCHDOG_MS) {
  clearTimeout(claudeTurnWatchdog.get(tabId));
  claudeTurnWatchdog.set(tabId, setTimeout(() => {
    claudeTurnWatchdog.delete(tabId);
    if (claudeTurnBusy.get(tabId) !== true) return;

    const live = getClaudeTurnLiveness(tabId);
    if (live.liveProcess && live.activeArtifact) {
      console.warn(
        '[ClaudeHook] Watchdog extended for tab ' + tabId.slice(-12) +
        ' (Claude still active; spinnerAge=' + formatWatchdogAge(live.spinnerAgeMs) +
        ' jsonlAge=' + formatWatchdogAge(live.jsonlAgeMs) + ')'
      );
      scheduleClaudeTurnWatchdog(tabId, sessionId, CLAUDE_TURN_WATCHDOG_EXTENSION_MS);
      return;
    }

    console.warn(
      '[ClaudeHook] Watchdog fired for tab ' + tabId.slice(-12) +
      ' (Stop never arrived; liveProcess=' + live.liveProcess +
      ' spinnerAge=' + formatWatchdogAge(live.spinnerAgeMs) +
      ' jsonlAge=' + formatWatchdogAge(live.jsonlAgeMs) + ')'
    );
    terminalHistoryPreviewController.finish({
      tabId,
      provider: 'claude',
      reason: 'watchdog',
    });
    clearClaudeProviderFatalTurnWatch(tabId, 'watchdog');
    emitClaudeAbnormalTurnEnd(tabId, 'watchdog');
    claudeSpinnerLastSeenAt.delete(tabId);
    recordActivity(tabId, false, 'claude');
    if (mainWindow && !mainWindow.isDestroyed()) {
      // Stop never arrived within the watchdog window and no fresh Claude-side
      // activity was observed. This is not a clean completion.
      mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: 'watchdog' });
    }
  }, delayMs));
}

// Awaiting-user-input state per tab. true = Claude called AskUserQuestion and is
// blocked in its interactive-permission phase waiting for the human to answer.
// Bracketed deterministically by PreToolUse(AskUserQuestion)=true and
// PostToolUse|PostToolUseFailure(AskUserQuestion)=false — same socket/tabId
// pipeline as claudeTurnBusy. Invariant: awaiting ⊆ busy (a question only exists
// mid-turn), so the renderer also clears awaiting on any claude:busy-state
// busy:false edge as a safety net — we therefore do NOT touch the 12 busy:false
// emit sites here. See fact-claude-awaiting-input.md.
const claudeAwaitingInput = new Map(); // tabId → boolean

// Pending AskUserQuestion CONTENT for PTY-Claude tabs, keyed by tabId →
// { questions:[...], at }. Populated on PreToolUse(AskUserQuestion) from the
// hook's tool_input, cleared on Post/PostFailure (and on any turn-end safety
// net). Mobile reads this (web-server snapshot + ask-question broadcast) to
// render its own question picker, and answers by driving the TUI keystrokes
// (answerClaudeQuestionPTY). SDK tabs use the separate pendingQuestions Map
// (parked canUseTool Promises) — these two never overlap (a tab is PTY xor SDK).
const claudePendingQuestion = new Map(); // tabId → { questions, at }

// Last hook event per tab — for diagnostics. When loader hangs, the difference
// between "hook fired 5s ago" and "hook silent for 20min" tells us instantly
// whether the bridge is alive. Surfaced in dump-claude-state and the periodic
// snapshot logger below.
const claudeHookLastEvent = new Map(); // tabId → { event, ts, sessionId }

// Running counters for hook socket lifecycle. Diff between sock open and
// hook-event log entries proves whether server is reading data or not.
let claudeHookConnSeq = 0;
let claudeHookEventSeq = 0;

// ─── JSONL interruption watcher ─────────────────────────────────────────
// Claude's `aborted_streaming` path in query.ts:1051 returns WITHOUT firing
// stopHooks — so on user interrupt (Esc, Ctrl+C, /interrupt, anything that
// aborts streaming) our Stop hook never arrives and the loader hangs until
// the 60-min CLAUDE_TURN_WATCHDOG_MS expires.
//
// Claude DOES write an authoritative record to the session JSONL though: a
// `type:"user"` message whose content is exactly `[{ type:"text", text:
// "[Request interrupted by user]" }]` (or the `... for tool use` variant
// when it interrupts mid-tool-call). That's a deterministic file-system
// signal we can watch independently of any TUI keystroke.
//
// One watcher per active Claude turn. fs.watch on the session JSONL with a
// minimal tail-only reader (tracks last read byte offset, parses newly-added
// lines on each `change` event). Disarmed on Stop hook arrival or tab close.
const claudeInterruptWatchers = new Map(); // tabId → { watcher, filePath, offset, debounce }
const INTERRUPT_TEXTS = new Set([
  '[Request interrupted by user]',
  '[Request interrupted by user for tool use]',
]);
const claudeLocalCommandWatchers = new Map(); // tabId → { command, watcher, filePath, offset, debounce, timeout, startedAt }
const claudeInputLineBuffers = new Map(); // tabId → { text, exact terminal/session/launch/prompt owner }
const claudePtyCompactProofInflight = new Map(); // tabId → exact transcript-proof attempt
const claudeProviderFatalTurnWatches = new Map(); // tabId → exact turn/process/frame identity

function clearClaudeProviderFatalTurnWatch(tabId, reason = 'clear') {
  const watch = claudeProviderFatalTurnWatches.get(tabId);
  if (!watch) return false;
  claudeProviderFatalTurnWatches.delete(tabId);
  console.log('[ClaudeProviderFatal] disarm tab=' + String(tabId).slice(-12)
    + ' turn=' + (watch.turnId || '-')
    + ' reason=' + reason);
  return true;
}

function armClaudeProviderFatalTurnWatch({
  tabId,
  sessionId = null,
  processId = null,
  turnId = null,
  turnGeneration = null,
  turnStartedAt = null,
} = {}) {
  const terminal = terminals.get(tabId) || null;
  const mirror = getHeadlessTerminalMirror(tabId);
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const terminalRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  if (!terminal || !mirror || !lifecycleGeneration || !turnId || terminalRunSeq <= 0) {
    claudeProviderFatalTurnWatches.delete(tabId);
    return null;
  }
  const baselineFrame = mirror.lastCommittedVisibleSnapshot || null;
  const baseline = inspectClaudeProviderFatalFrame(baselineFrame);
  const watch = {
    terminal,
    mirror,
    lifecycleGeneration,
    terminalRunSeq,
    mirrorGeneration: mirror.generation,
    armedCommittedFrameGeneration: Number(
      baselineFrame?.committedFrameGeneration || 0,
    ),
    sessionId: sessionId || null,
    processId: Number.isSafeInteger(Number(processId)) ? Number(processId) : null,
    turnId,
    turnGeneration: turnGeneration || null,
    turnStartedAt: turnStartedAt || null,
    baselineFatalCode: baseline?.fatal === true ? baseline.code : null,
    sawNonFatalFrameAfterArm: false,
    finalized: false,
  };
  claudeProviderFatalTurnWatches.set(tabId, watch);
  console.log('[ClaudeProviderFatal] arm tab=' + String(tabId).slice(-12)
    + ' turn=' + turnId
    + ' lifecycle=' + lifecycleGeneration
    + ' run=' + terminalRunSeq
    + ' frame=' + watch.armedCommittedFrameGeneration
    + ' baseline=' + (watch.baselineFatalCode || 'none'));
  return watch;
}

function claudeProviderFatalWatchStillOwnsTurn(tabId, state, watch) {
  if (!watch || watch.finalized === true) return false;
  if (terminals.get(tabId) !== watch.terminal) return false;
  if (getHeadlessTerminalMirror(tabId) !== watch.mirror || state !== watch.mirror) return false;
  if (state?.generation !== watch.mirrorGeneration) return false;
  if (getTerminalLifecycleGeneration(tabId) !== watch.lifecycleGeneration) return false;
  if (Number(terminalCommandState.get(tabId)?.runSeq || 0) !== watch.terminalRunSeq) return false;
  if (claudeTurnBusy.get(tabId) !== true || !hasLiveClaudeInTab(tabId)) return false;
  const active = getActiveAgentExecutionContext(tabId);
  if (!active || active.provider !== 'claude' || active.turnId !== watch.turnId) return false;
  if (watch.sessionId && active.sessionId && active.sessionId !== watch.sessionId) return false;
  if (watch.processId && active.processId && Number(active.processId) !== watch.processId) return false;
  return true;
}

function finishClaudeTurnFromProviderFatalFrame(tabId, watch, fatal, committedFrameGeneration) {
  watch.finalized = true;
  claudeProviderFatalTurnWatches.delete(tabId);
  const outcomeTs = Date.now();
  const previousSpinner = claudeSpinnerBusy.get(tabId);
  const taskTurn = taskCompletionIntents.finishTurn({
    tabId,
    provider: 'claude',
    sessionId: watch.sessionId,
    processId: watch.processId,
    success: false,
  });
  const taskTurnSnapshot = taskTurn?.turn || taskTurn || {};
  const turnGeneration = taskTurnSnapshot?.generation || watch.turnGeneration || null;
  const turnStartedAt = taskTurnSnapshot?.startedAt || watch.turnStartedAt || null;

  terminalHistoryPreviewController.finish({
    tabId,
    provider: 'claude',
    turnId: watch.turnId,
    reason: 'provider-error:' + fatal.code,
  });
  claudeTurnBusy.set(tabId, false);
  wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, 'provider-error');
  const launchGeneration = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
  if (launchGeneration) {
    claudePromptStability.markBusy(
      tabId,
      launchGeneration,
      false,
      'claude-provider-fatal:' + fatal.code,
    );
  }
  clearTimeout(claudeSpinnerIdleTimer.get(tabId));
  claudeSpinnerIdleTimer.delete(tabId);
  clearTimeout(claudeTurnWatchdog.get(tabId));
  claudeTurnWatchdog.delete(tabId);
  claudeSpinnerBusy.set(tabId, false);
  claudeSpinnerLastSeenAt.delete(tabId);
  if (claudeLocalCommandWatchers.has(tabId)) {
    completeClaudeLocalCommand(tabId, 'provider-error');
  }
  clearClaudePtyCompactProofAttempt(tabId, undefined, 'provider-error');
  stopInterruptWatcher(tabId);

  if (claudeAwaitingInput.get(tabId)) {
    claudeAwaitingInput.set(tabId, false);
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
    }
  }
  if (claudePendingQuestion.has(tabId)) {
    claudePendingQuestion.delete(tabId);
    _webBroadcast(tabId, { type: 'question-cancelled', source: 'pty' });
  }
  claudeHookLastEvent.set(tabId, {
    event: 'ProviderError',
    ts: outcomeTs,
    sessionId: watch.sessionId,
    turnId: watch.turnId,
    providerErrorCode: fatal.code,
  });

  const outcome = {
    reason: 'provider_error',
    provider: 'claude',
    sessionId: watch.sessionId,
    turnId: watch.turnId,
    processId: watch.processId,
    turnGeneration,
    turnStartedAt,
    providerErrorCode: fatal.code,
    providerErrorMessage: fatal.message,
    outcomeTs,
  };
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('claude:busy-state', {
      tabId,
      busy: false,
      ...outcome,
    });
    mainWindow.webContents.send('claude:turn-state', {
      tabId,
      event: 'ProviderError',
      busy: false,
      success: false,
      lastAssistantMessage: fatal.message,
      ...outcome,
    });
  }
  _webBroadcast(tabId, { type: 'busy', busy: false, ...outcome });
  _webBroadcast(tabId, { type: 'done', ...outcome });
  recordActivity(tabId, false, 'claude', {
    responseTimingEligible: false,
    reason: 'ProviderError',
  });
  console.warn('[ClaudeProviderFatal] confirmed tab=' + String(tabId).slice(-12)
    + ' turn=' + watch.turnId
    + ' code=' + fatal.code
    + ' frame=' + committedFrameGeneration
    + ' rows=' + fatal.startRow + '-' + fatal.endRow
    + ' previousSpinner=' + (previousSpinner === undefined ? 'undef' : previousSpinner));
}

function observeClaudeProviderFatalCommittedFrame(
  tabId,
  state,
  snapshot,
  committedFrameGeneration,
) {
  const watch = claudeProviderFatalTurnWatches.get(tabId);
  if (!watch) return null;
  if (!claudeProviderFatalWatchStillOwnsTurn(tabId, state, watch)) {
    clearClaudeProviderFatalTurnWatch(tabId, 'identity-changed');
    return null;
  }
  if (Number(committedFrameGeneration) <= watch.armedCommittedFrameGeneration) return null;
  const fatal = inspectClaudeProviderFatalFrame(snapshot);
  if (fatal?.fatal !== true) {
    watch.sawNonFatalFrameAfterArm = true;
    return null;
  }
  if (watch.baselineFatalCode === fatal.code && watch.sawNonFatalFrameAfterArm !== true) {
    return null;
  }
  finishClaudeTurnFromProviderFatalFrame(
    tabId,
    watch,
    fatal,
    committedFrameGeneration,
  );
  return fatal;
}

let claudeHookServer = null;

// Ctrl+G is owned by an immutable operation, not by whichever request currently
// happens to use this PID/tab. Timed-out operations retain cancellation intent
// until the actual helper returns (or the owning process is retired).
const grabInputPending = new Map();
const agentInputCaptureProtocol = new AgentInputCaptureProtocol();

function releaseAgentInputCapturePending(tabId, pending, proof = {}) {
  try {
    pending.preserveOutcomeBeforeRelease?.(readCaptureOutcome(pending.captureOperation));
  } catch (error) {
    // Do not delete the helper's only applied/unchanged proof if its operation
    // owner could not persist it. A later exact recovery can finish the write.
    console.error('[RewindPostEnter] helper outcome persistence held:', error);
    return false;
  }
  if (!agentInputCaptureProtocol.release(pending.captureOperation, proof)) return false;
  clearTimeout(pending.timer);
  if (grabInputPending.get(tabId) === pending) grabInputPending.delete(tabId);
  return true;
}

function retireAgentInputCaptureForProcess(tabId, agent, reason) {
  const pending = grabInputPending.get(tabId);
  if (!pending || (agent && pending.agent !== agent)) return;
  const draftTransfer = buildAgentDraftTransfer(pending.captureOperation,
    readCaptureOutcome(pending.captureOperation), pending.preparedDraft, pending.helperId);
  releaseAgentInputCapturePending(tabId, pending, { processRetired: true });
  pending.resolve({ success: false, error: 'capture_generation_changed', reason,
    draftTransfer,
    ...(draftTransfer ? { text: draftTransfer.text, images: draftTransfer.images, imagePaths: draftTransfer.imagePaths } : {}),
  });
}

function stageCodexImageRefs(tabId, refs) {
  const token = codexImageBindings.stage(tabId, refs);
  return token ? { token, refs } : { token: null, refs: [] };
}

function resolveClaudeSessionFileForTab(tabId, sessionId = bridgeKnownSessions.get(tabId) || null) {
  if (!sessionId) return null;
  const cwd = terminalProjects.get(tabId);
  const located = findSessionFile(sessionId, cwd);
  return located?.filePath || null;
}

const CLAUDE_STARTUP_SLASH_PROOF_TAIL_BYTES = 512 * 1024;

function normalizeClaudeLocalCommandText(text) {
  return String(text || '')
    .replace(/\u001b\[[0-9;]*m/g, '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function resolveClaudeStartupSlashSessionId(tabId) {
  const bridgeSessionId = bridgeKnownSessions.get(tabId) || null;
  if (bridgeSessionId) return bridgeSessionId;
  try {
    const row = projectManager?.db?.db?.prepare(
      'SELECT claude_session_id FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId);
    return row?.claude_session_id || null;
  } catch {
    return null;
  }
}

// Three-valued proof, per the project rule for fallible lookups
// (found / absent / unknown). The distinction is load-bearing for the startup
// transaction: `absent` is the only outcome that may be auto-retried, while
// `unresolved` (unreadable transcript, scan error, file truncated under the
// reader) must never be — re-sending a command whose delivery is unknown can
// apply the setting twice. Before this, every non-found result collapsed into
// `success:false`, so a transient read error looked exactly like a swallowed
// command and produced a hard "startup failed".
// Dev-only fault injection for E2E. Some acceptance conditions cannot be
// reached honestly: killing the process yields `cleared`, not `failed`, so a
// scenario checking the failure path would silently verify a different path.
// Enabled only by explicit env; every activation is logged so a run can prove
// the hook fired rather than assuming it did.
const CLAUDE_STARTUP_TEST_FAULT = app.isPackaged
  ? ''
  : String(process.env.NOTED_TEST_STARTUP_FAULT || '').trim();
function claudeStartupTestFaultActive(kind) {
  if (!CLAUDE_STARTUP_TEST_FAULT) return false;
  const active = CLAUDE_STARTUP_TEST_FAULT === kind;
  if (active) console.warn('[TestFault] active kind=' + kind);
  return active;
}

// Dev-only deterministic boundary for the exact Stop-during-Send E2E. The
// normal paste→render→Enter window is only a few milliseconds, so a visual
// driver cannot reliably click inside it. This hook waits for the real
// handoff-scoped cancellation event after bytes reached the composer and never
// invents a timeout or a synthetic success path.
const AGENT_SEND_TEST_FAULT = app.isPackaged
  ? ''
  : String(process.env.NOTED_TEST_SEND_FAULT || '').trim();
let codexDraftUnknownTestFaultConsumed = false;
function agentSendTestFaultActive(kind) {
  const active = AGENT_SEND_TEST_FAULT === kind;
  if (active) console.warn('[TestFault] active kind=agent-send-' + kind);
  return active;
}

function claudeStartupProofOutcome(result) {
  if (result?.success === true) return CLAUDE_STARTUP_PROOF.FOUND;
  // A successfully read transcript that lacks this command still cannot prove
  // non-delivery: Claude may have applied the setting while its JSONL write was
  // delayed, redirected, or trimmed. Only a current-frame composer probe can
  // upgrade this to ABSENT, and only together with send-path proof that Enter
  // was never written and the exact command is still waiting there.
  return CLAUDE_STARTUP_PROOF.UNRESOLVED;
}

function scanClaudeStartupSlashProof(tabId, command, afterMs, sessionIdOverride = null) {
  const target = parseClaudeStartupSlashCommand(command);
  if (!target) return { success: false, reason: 'unsupported-command' };
  // A local slash command can materialize its JSONL before StatusLine bridge
  // ownership is accepted. The exact tab row is updated by the independent
  // terminal session-id detector, so it is a valid discovery fallback; the
  // timestamp + exact command wrapper below prevents stale-session proof.
  const sessionId = sessionIdOverride || resolveClaudeStartupSlashSessionId(tabId);
  const filePath = resolveClaudeSessionFileForTab(tabId, sessionId);
  if (!filePath) {
    return { success: false, reason: 'session-file-missing', sessionId };
  }

  try {
    const stat = fs.statSync(filePath);
    const readSize = Math.min(CLAUDE_STARTUP_SLASH_PROOF_TAIL_BYTES, stat.size);
    if (readSize <= 0) return { success: false, reason: 'empty-file', sessionId, fileSize: stat.size };
    const startOffset = stat.size - readSize;
    const fd = fs.openSync(filePath, 'r');
    const buf = Buffer.alloc(readSize);
    try { fs.readSync(fd, buf, 0, readSize, startOffset); }
    finally { fs.closeSync(fd); }

    const tail = buf.toString('utf8');
    const rawLines = tail.split('\n');
    const lines = startOffset > 0 ? rawLines.slice(1) : rawLines;
    const records = [];
    for (const line of lines) {
      if (!line || line[0] !== '{') continue;
      try { records.push(JSON.parse(line)); } catch { /* partial tail line */ }
    }
    return {
      ...scanClaudeStartupSlashRecords(records, command, { afterMs, sessionId }),
      file: filePath.replace(os.homedir(), '~'),
    };
  } catch (error) {
    return { success: false, reason: 'scan-error', error: error.message, sessionId };
  }
}

async function resolveClaudeStartupSettingsInMain({
  tabId,
  generation,
  sessionIdHint = null,
} = {}) {
  const startupIntent = readClaudeStartupIntent(tabId);
  let model = String(
    projectManager?.db?.getAppState?.('defaultClaudeModel') || 'none',
  ).trim() || 'none';
  let effort = String(
    projectManager?.db?.getAppState?.('defaultClaudeEffort') || 'none',
  ).trim() || 'none';
  if (effort === 'auto') effort = 'low';

  let row = null;
  try {
    row = projectManager?.db?.db?.prepare(
      'SELECT claude_session_id, cwd FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId) || null;
  } catch (error) {
    console.warn('[StartupTx] settings tab lookup failed tab='
      + String(tabId).slice(-12)
      + ' error=' + (error?.message || String(error)));
  }

  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const matchingLaunch = launch?.generation === generation ? launch : null;
  const sessionId = selectClaudeStartupSettingsSession({
    launchMode: matchingLaunch?.launchMode || 'unknown',
    launchSessionId: matchingLaunch?.sessionIdHint || null,
    readinessSessionId: sessionIdHint || bridgeKnownSessions.get(tabId) || null,
    persistedSessionId: row?.claude_session_id || null,
  });
  const cwd = String(row?.cwd || terminalProjects.get(tabId) || '').trim() || null;
  if (!sessionId) {
    const resolved = applyClaudeStartupIntent({
      model,
      effort,
      sessionId: null,
      source: 'app-defaults',
    }, startupIntent);
    if (startupIntent) rememberClaudeStartupIntentUse(tabId, generation, startupIntent);
    console.log('[StartupTx] settings tab=' + String(tabId).slice(-12)
      + ' session=nil source=' + resolved.source
      + ' model=' + resolved.model + ' effort=' + resolved.effort);
    return resolved;
  }

  try {
    const result = await resolveClaudeSettingsAcrossForkChain({
      sessionId,
      readSettings: (candidateSessionId) => claudeDataApi.getConfirmedSettings({
        tabId,
        sessionId: candidateSessionId,
        cwd,
      }),
      getParentSession: (candidateSessionId) => {
        try {
          return projectManager?.db?.getParentSession?.(candidateSessionId) || null;
        } catch (error) {
          console.warn('[StartupTx] fork parent lookup failed session='
            + String(candidateSessionId).slice(0, 8)
            + ' error=' + (error?.message || String(error)));
          return null;
        }
      },
    });
    if (result?.success === true && result.sessionId === sessionId) {
      let restoredModel = result.model || null;
      if (restoredModel) {
        try {
          const claudeCodeSettings = projectManager?.db?.getAppState?.('claudeCodeSettings');
          restoredModel = resolveClaudeStartupModelValue(
            restoredModel,
            Array.isArray(claudeCodeSettings?.models) ? claudeCodeSettings.models : [],
          );
        } catch (error) {
          console.warn('[StartupTx] model alias unresolved tab='
            + String(tabId).slice(-12)
            + ' value=' + JSON.stringify(restoredModel)
            + ' error=' + (error?.message || String(error)));
        }
      }
      const hasSessionSetting = !!result.model || !!result.effort;
      const base = {
        model: restoredModel || model,
        effort: result.effort || effort,
        sessionId,
        source: hasSessionSetting
          ? (result.inherited ? 'fork-parent-history' : 'session-history')
          : 'app-defaults',
      };
      const resolved = applyClaudeStartupIntent(base, startupIntent);
      resolved.effortAlreadyConfirmed = !!result.effort
        && result.effortSessionId === sessionId
        && resolved.effort === result.effort;
      if (startupIntent) rememberClaudeStartupIntentUse(tabId, generation, startupIntent);
      console.log('[StartupTx] settings tab=' + String(tabId).slice(-12)
        + ' session=' + sessionId.slice(0, 8)
        + ' source=' + resolved.source
        + ' model=' + resolved.model
        + ' effort=' + resolved.effort
        + (result.inherited
          ? ' inheritedFrom=' + String(result.modelSessionId || result.effortSessionId || '').slice(0, 8)
          : ''));
      return resolved;
    }
    console.warn('[StartupTx] settings unresolved tab='
      + String(tabId).slice(-12)
      + ' session=' + sessionId.slice(0, 8)
      + ' reason=' + String(result?.reason || 'unconfirmed-result'));
  } catch (error) {
    console.warn('[StartupTx] settings unresolved tab='
      + String(tabId).slice(-12)
      + ' session=' + sessionId.slice(0, 8)
      + ' error=' + (error?.message || String(error)));
  }

  // A failed history lookup is unknown, not proof that a resumed session has
  // no settings. Let Claude keep the state it restored rather than overwriting
  // it with application defaults. An explicit complete next-launch pair is a
  // user instruction rather than an inferred fallback, so it remains safe to
  // apply even when history itself is temporarily unreadable.
  const unresolved = applyClaudeStartupIntent({
    model: 'none',
    effort: 'none',
    sessionId,
    source: 'session-settings-unknown',
  }, startupIntent);
  if (startupIntent) rememberClaudeStartupIntentUse(tabId, generation, startupIntent);
  return unresolved;
}

function readClaudeStartupSlashProof(payload = {}) {
  const tabId = String(payload?.tabId || '');
  const command = String(payload?.command || '');
  const afterMs = Number(payload?.afterMs || 0);
  const sessionId = String(payload?.sessionId || '').trim() || null;
  const label = String(payload?.label || 'startup-slash-proof');
  if (!tabId || !command) {
    return {
      success: false,
      reason: 'missing-args',
      outcome: CLAUDE_STARTUP_PROOF.UNRESOLVED,
    };
  }
  if (claudeStartupTestFaultActive('proof-unresolved')) {
    console.warn('[TestFault] proof-unresolved tab=' + tabId.slice(-12)
      + ' command=' + JSON.stringify(command));
    return {
      success: false,
      reason: 'test-fault-unresolved',
      outcome: CLAUDE_STARTUP_PROOF.UNRESOLVED,
    };
  }
  const result = scanClaudeStartupSlashProof(tabId, command, afterMs, sessionId);
  result.outcome = claudeStartupProofOutcome(result);
  console.log('[ClaudeStartupSlashProof] tab=' + tabId.slice(-12)
    + ' label=' + label
    + ' command=' + JSON.stringify(command)
    + ' afterMs=' + (afterMs || 0)
    + ' success=' + (result.success === true)
    + ' outcome=' + result.outcome
    + ' terminal=' + (result.terminal === true)
    + ' reason=' + (result.reason || '-')
    + ' wrapperSeen=' + !!result.wrapperSeen
    + ' stdoutSeen=' + !!result.stdoutSeen
    + ' session=' + (result.sessionId ? String(result.sessionId).slice(0, 8) : '-')
    + ' file=' + (result.file || '-')
    + ' output=' + JSON.stringify(result.outputPreview || '')
    + ' error=' + (result.error || '-'));
  return result;
}

async function waitForClaudeStartupSlashProofInMain({
  tabId,
  generation,
  command,
  afterMs,
  label,
  sendResult = null,
} = {}) {
  if (claudeLaunchGenerationByTab.get(tabId)?.generation !== generation) {
    return {
      outcome: CLAUDE_STARTUP_PROOF.UNRESOLVED,
      reason: 'stale-generation',
    };
  }

  const target = parseClaudeStartupSlashCommand(command);
  if (target) {
    await confirmClaudeSettingsDialogFromCurrentFrame(
      tabId,
      target.kind === 'model' ? 'ModelDialog' : 'EffortDialog',
      'startup-defaults:' + label,
    ).catch(() => null);
  }

  // Enter was explicitly withheld: this is the one branch where the current
  // composer may prove that no submission happened and authorize one safe
  // retry. Once Enter may have been written, screen state cannot decide the
  // outcome; only the exact transcript result may advance the transaction.
  if (sendResult?.submitted === false) {
    const scan = readClaudeStartupSlashProof({
      tabId,
      command,
      afterMs,
      label,
    });
    if (scan?.outcome === CLAUDE_STARTUP_PROOF.FOUND || scan?.terminal === true) {
      return scan;
    }
    const composer = await inspectClaudeExactSettingInput(tabId, command, {
      submit: false,
      source: 'startup-proof:' + label,
    }).catch((error) => ({
      success: false,
      submitted: false,
      error: error?.message || String(error),
    }));
    const composerForDelivery = {
      ...(composer || {}),
      startupGenerationStable:
        claudeLaunchGenerationByTab.get(tabId)?.generation === generation,
    };

    const delivery = classifyClaudeStartupDeliveryProof({
      scan,
      composer: composerForDelivery,
      sendResult,
    });
    if (delivery.outcome === CLAUDE_STARTUP_PROOF.ABSENT) {
      console.warn('[ClaudeStartupDeliveryProof] tab=' + String(tabId).slice(-12)
        + ' label=' + String(label || '-')
        + ' command=' + JSON.stringify(command)
        + ' outcome=absent'
        + ' reason=' + delivery.reason
        + ' scanReason=' + (scan.reason || '-')
        + ' submitProof=not-written'
        + ' recovery=' + (delivery.recovery?.kind || '-'));
      return delivery;
    }

    console.warn('[ClaudeStartupDeliveryProof] tab=' + String(tabId).slice(-12)
      + ' label=' + String(label || '-')
      + ' command=' + JSON.stringify(command)
      + ' outcome=unresolved'
      + ' scanReason=' + (scan.reason || '-')
      + ' composer=' + delivery.composerProof
      + ' submitProof=' + delivery.submitProof
      + ' error=' + (delivery.composerError || '-'));
    return delivery;
  }

  return claudeStartupProofSession.wait({
    tabId,
    generation,
    command,
    afterMs,
    label,
  });
}

function emitClaudeBusyState(tabId, busy, reason, meta = null) {
  claudeSpinnerBusy.set(tabId, busy);
  const responseTimingEligible = shouldCreateHistoryResponseTiming({
    toolType: 'claude',
    reason,
  });
  recordActivity(tabId, busy, 'claude', { responseTimingEligible, reason });
  if (mainWindow && !mainWindow.isDestroyed()) {
    const payload = { tabId, busy, reason };
    if (meta && typeof meta === 'object') Object.assign(payload, meta);
    mainWindow.webContents.send('claude:busy-state', payload);
  }
}

function detectClaudeCompactOutputPhase(text) {
  if (!text) return null;
  const normalized = String(text).toLowerCase().replace(/\s+/g, '');
  if (normalized.includes('compactingconversation')) return 'compacting';
  if (
    normalized.includes('conversationcompacted') ||
    normalized.includes('compacted(ctrl+o')
  ) {
    return 'compacted';
  }
  return null;
}

function readClaudeLocalCommandOwner(tabId) {
  return {
    terminal: terminals.get(tabId) || null,
    sessionId: bridgeKnownSessions.get(tabId) || null,
    generation: claudeLaunchGenerationByTab.get(tabId)?.generation || null,
    inputRevision: getTerminalInputRevision(tabId),
  };
}

function classifyCurrentClaudeLocalCommandOwner(tabId, state) {
  return classifyClaudeLocalCommandOwner(state?.owner || null, readClaudeLocalCommandOwner(tabId));
}

function stopClaudeLocalCommandWatcher(tabId, reason = 'stop') {
  const state = claudeLocalCommandWatchers.get(tabId);
  if (!state) return null;
  if (state.debounce) clearTimeout(state.debounce);
  if (state.watcher) { try { state.watcher.close(); } catch {} }
  claudeLocalCommandWatchers.delete(tabId);
  clearClaudePtyCompactProofAttempt(tabId, undefined, 'local-command-stop:' + reason);
  compactOperations.finish({
    tabId,
    provider: 'claude',
    operationId: state.operationId,
    sessionId: state.sessionId,
    generation: state.generation,
    outcome: claudeCompactOutcomeFromReason(reason),
    reason,
    completionProof: reason,
  });
  console.log('[ClaudeLocalCommand] STOP tab=' + tabId.slice(-12) + ' command=' + state.command + ' reason=' + reason + ' durMs=' + (Date.now() - state.startedAt));
  return state;
}

function completeClaudeLocalCommand(tabId, reason) {
  const state = claudeLocalCommandWatchers.get(tabId);
  if (!state) return;
  stopClaudeLocalCommandWatcher(tabId, reason);
  clearTimeout(claudeSpinnerIdleTimer.get(tabId));
  claudeSpinnerIdleTimer.delete(tabId);
  emitClaudeBusyState(tabId, false, 'local-command', {
    localCommand: state.command,
    localCommandReason: reason,
  });
  console.log('[ClaudeLocalCommand] DONE tab=' + tabId.slice(-12) + ' command=' + state.command + ' reason=' + reason);
}

function cancelClaudeLocalCommandFromInput(tabId, data) {
  const state = claudeLocalCommandWatchers.get(tabId);
  if (!state) return false;
  if (data !== '\x1b' && data !== '\x03') return false;
  const reason = data === '\x03' ? 'input-ctrl-c' : 'input-escape';
  console.warn('[ClaudeLocalCommand] CANCEL tab=' + tabId.slice(-12) + ' command=' + state.command + ' reason=' + reason);
  completeClaudeLocalCommand(tabId, reason);
  return true;
}

function prepareClaudeLocalCommandWatcher(tabId, command, source = 'unknown', metadata = {}) {
  const normalized = String(command || '').trim();
  if (normalized !== '/compact') return null;

  const existing = claudeLocalCommandWatchers.get(tabId);
  if (existing) {
    console.log('[ClaudeLocalCommand] PREPARE ignored tab=' + tabId.slice(-12) + ' command=' + normalized + ' source=' + source + ' existingAgeMs=' + (Date.now() - existing.startedAt));
    return null;
  }

  const sessionId = bridgeKnownSessions.get(tabId) || null;
  const filePath = resolveClaudeSessionFileForTab(tabId, sessionId);
  if (!filePath) {
    console.warn('[ClaudeLocalCommand] PREPARE fallback tab=' + tabId.slice(-12) + ' command=' + normalized + ' source=' + source + ' session=' + (sessionId ? sessionId.slice(0, 8) : 'none') + ' file=missing - using PTY output completion');
  }

  let offset = 0;
  if (filePath) {
    try { offset = fs.statSync(filePath).size; } catch {}
  }
  const preparation = {
    tabId,
    command: normalized,
    source,
    sessionId,
    filePath,
    offset,
    owner: readClaudeLocalCommandOwner(tabId),
    handoffId: typeof metadata?.handoffId === 'string' && metadata.handoffId
      ? metadata.handoffId
      : null,
    preparedAt: Date.now(),
  };
  console.log('[ClaudeLocalCommand] PREPARE tab=' + tabId.slice(-12)
    + ' command=' + normalized
    + ' source=' + source
    + ' session=' + (sessionId ? sessionId.slice(0, 8) : 'none')
    + ' file=' + (filePath ? filePath.replace(os.homedir(), '~') : 'missing')
    + ' offset=' + offset);
  return preparation;
}

function discardClaudeLocalCommandWatcherPreparation(preparation, reason = 'discard') {
  if (!preparation) return false;
  console.log('[ClaudeLocalCommand] DISCARD tab=' + String(preparation.tabId || '').slice(-12)
    + ' command=' + preparation.command
    + ' source=' + preparation.source
    + ' reason=' + reason
    + ' preparedAgeMs=' + Math.max(0, Date.now() - preparation.preparedAt));
  return true;
}

function activateClaudeLocalCommandWatcher(preparation) {
  if (!preparation?.tabId || preparation.command !== '/compact') return false;
  const {
    tabId,
    command: normalized,
    source,
    sessionId,
    filePath,
    offset,
  } = preparation;
  const existing = claudeLocalCommandWatchers.get(tabId);
  if (existing) {
    console.log('[ClaudeLocalCommand] ACTIVATE ignored tab=' + tabId.slice(-12) + ' command=' + normalized + ' source=' + source + ' existingAgeMs=' + (Date.now() - existing.startedAt));
    return false;
  }

  const state = {
    command: normalized,
    watcher: null,
    filePath,
    offset,
    debounce: null,
    startedAt: Date.now(),
    preparedAt: preparation.preparedAt,
    owner: preparation.owner,
    sessionId: preparation.sessionId || null,
    generation: preparation.owner?.generation == null
      ? null
      : String(preparation.owner.generation),
    handoffId: preparation.handoffId || null,
    operationId: 'claude:'
      + String(preparation.owner?.generation ?? 'generation-unknown')
      + ':' + String(preparation.owner?.inputRevision ?? 'input-unknown')
      + ':' + String(preparation.preparedAt),
    requestTranscriptScan: null,
  };

  const onChange = () => {
    if (state.debounce) return;
    state.debounce = setTimeout(() => {
      state.debounce = null;
      let stat;
      try { stat = fs.statSync(filePath); } catch { return; }
      if (stat.size <= state.offset) { state.offset = stat.size; return; }
      const fd = fs.openSync(filePath, 'r');
      const len = stat.size - state.offset;
      const buf = Buffer.alloc(len);
      try { fs.readSync(fd, buf, 0, len, state.offset); }
      finally { fs.closeSync(fd); }
      state.offset = stat.size;
      const lines = buf.toString('utf8').split('\n');
      for (const line of lines) {
        if (!line) continue;
        let rec;
        try { rec = JSON.parse(line); } catch { continue; }
        const outcome = classifyClaudeCompactWatcherRecord(rec);
        if (!outcome.terminal) {
          if (outcome.reason === 'auto-compact-boundary') {
            console.warn('[ClaudeLocalCommand] ignored automatic compact boundary tab='
              + tabId.slice(-12) + ' command=' + normalized);
          }
          continue;
        }
        const ownership = classifyCurrentClaudeLocalCommandOwner(tabId, state);
        if (!ownership.matches) {
          console.warn('[ClaudeLocalCommand] completion owner changed tab='
            + tabId.slice(-12) + ' command=' + normalized
            + ' proof=' + outcome.reason + ' owner=' + ownership.reason);
          completeClaudeLocalCommand(tabId, 'owner-changed:' + ownership.reason);
          return;
        }
        completeClaudeLocalCommand(tabId, outcome.reason);
        return;
      }
    }, 100);
  };
  state.requestTranscriptScan = onChange;

  if (filePath) {
    try {
      state.watcher = fs.watch(filePath, { persistent: false }, onChange);
    } catch (e) {
      console.warn('[ClaudeLocalCommand] watcher failed tab=' + tabId.slice(-12) + ' command=' + normalized + ' file=' + filePath.replace(os.homedir(), '~') + ' error=' + e.message + ' - using PTY output completion');
      state.watcher = null;
    }
  }

  claudeLocalCommandWatchers.set(tabId, state);
  compactOperations.begin({
    tabId,
    provider: 'claude',
    command: normalized,
    operationId: state.operationId,
    sessionId: state.sessionId,
    generation: state.generation,
    handoffId: state.handoffId,
    source,
    acceptedAt: state.startedAt,
  });
  clearTimeout(claudeSpinnerIdleTimer.get(tabId));
  claudeSpinnerIdleTimer.delete(tabId);
  emitClaudeBusyState(tabId, true, 'local-command', {
    localCommand: normalized,
    localCommandReason: 'start',
    localCommandSource: source,
  });
  console.log('[ClaudeLocalCommand] START tab=' + tabId.slice(-12) + ' command=' + normalized + ' source=' + source + ' session=' + (sessionId ? sessionId.slice(0, 8) : 'none') + ' file=' + (filePath ? filePath.replace(os.homedir(), '~') : 'missing') + ' offset=' + offset + ' preparedAgeMs=' + Math.max(0, Date.now() - preparation.preparedAt));
  // fs.watch starts only after Enter is proven. Scan once from the pre-Enter
  // offset so an exceptionally fast compact marker written in that narrow
  // gap cannot be missed.
  if (filePath) onChange();
  return true;
}

function startClaudeLocalCommandWatcher(tabId, command, source = 'unknown') {
  const preparation = prepareClaudeLocalCommandWatcher(tabId, command, source);
  return activateClaudeLocalCommandWatcher(preparation);
}

function clearClaudePtyCompactProofAttempt(
  tabId,
  attempt = claudePtyCompactProofInflight.get(tabId) || null,
  reason = 'clear',
  { discard = true } = {},
) {
  if (!attempt) return false;
  if (attempt.watcher) {
    try { attempt.watcher.close(); } catch {}
    attempt.watcher = null;
  }
  if (claudePtyCompactProofInflight.get(tabId) === attempt) {
    claudePtyCompactProofInflight.delete(tabId);
  }
  if (discard && attempt.activated !== true) {
    discardClaudeLocalCommandWatcherPreparation(attempt.preparation, reason);
  }
  return true;
}

function requestClaudePtyCompactTranscriptProof(tabId, attempt, source = 'unknown') {
  if (!attempt || claudePtyCompactProofInflight.get(tabId) !== attempt) return;
  if (attempt.scanInFlight) {
    attempt.rescanRequested = true;
    return;
  }
  attempt.scanInFlight = true;
  attempt.rescanRequested = false;

  void readClaudeUserRecords(
    attempt.preparation.filePath,
    null,
    { maxReadBytes: 256 * 1024 },
  ).then((candidates) => {
    const proof = selectLatestClaudeManualCompactIntent(candidates, {
      notBeforeMs: Number(attempt.launchAt || 0),
    });
    const stillCurrent = claudePtyCompactProofInflight.get(tabId) === attempt
      && terminals.get(tabId) === attempt.terminal
      && (claudeLaunchGenerationByTab.get(tabId)?.generation || null) === attempt.generation
      && (bridgeKnownSessions.get(tabId) || null) === attempt.sessionId;
    if (!stillCurrent) {
      clearClaudePtyCompactProofAttempt(
        tabId,
        attempt,
        'terminal-generation-changed',
      );
      return;
    }
    if (!proof.proven) {
      attempt.lastReason = proof.reason;
      console.log('[ClaudeLocalCommand] PROOF_WAIT tab=' + tabId.slice(-12)
        + ' command=/compact source=' + source
        + ' reason=' + proof.reason
        + ' candidates=' + candidates.length
        + ' sawCompacted=' + (attempt.sawCompactedOutput === true));
      const automaticSummary = candidates.find((candidate) => (
        candidate?.record?.isCompactSummary === true
        && String(candidate?.record?.compactMetadata?.trigger || '').toLowerCase() === 'auto'
        && Date.parse(String(candidate?.record?.timestamp || '')) >= attempt.launchAt
      ));
      const newerOrdinaryPromptAt = Date.parse(String(proof.candidate?.record?.timestamp || ''));
      if (automaticSummary) {
        clearClaudePtyCompactProofAttempt(
          tabId,
          attempt,
          'automatic-compact-transcript',
        );
      } else if (
        Number.isFinite(newerOrdinaryPromptAt)
        && newerOrdinaryPromptAt >= attempt.preparation.preparedAt
      ) {
        clearClaudePtyCompactProofAttempt(
          tabId,
          attempt,
          'newer-noncompact-prompt',
        );
      }
      return;
    }

    attempt.activated = true;
    clearClaudePtyCompactProofAttempt(tabId, attempt, 'proof-accepted', { discard: false });
    attempt.preparation.source = 'pty-output-transcript-proof';
    console.log('[ClaudeLocalCommand] PROOF_ACCEPT tab=' + tabId.slice(-12)
      + ' command=/compact source=' + source
      + ' reason=' + proof.reason
      + ' candidateOffset=' + (proof.candidate?.byteOffset ?? '-'));
    activateClaudeLocalCommandWatcher(attempt.preparation);
  }).catch((error) => {
    attempt.lastReason = 'transcript-proof-error';
    console.warn('[ClaudeLocalCommand] PROOF_WAIT tab=' + tabId.slice(-12)
      + ' command=/compact source=' + source
      + ' reason=transcript-proof-error'
      + ' error=' + (error?.message || String(error)));
  }).finally(() => {
    attempt.scanInFlight = false;
    if (
      claudePtyCompactProofInflight.get(tabId) === attempt
      && attempt.rescanRequested === true
    ) {
      requestClaudePtyCompactTranscriptProof(tabId, attempt, 'coalesced-change');
    }
  });
}

function observeClaudeCompactFromPtyWithTranscriptProof(tabId) {
  if (claudeLocalCommandWatchers.has(tabId)) return;
  const existingAttempt = claudePtyCompactProofInflight.get(tabId) || null;
  if (existingAttempt) {
    requestClaudePtyCompactTranscriptProof(tabId, existingAttempt, 'additional-pty-output');
    return;
  }
  const preparation = prepareClaudeLocalCommandWatcher(tabId, '/compact', 'pty-output-proof');
  if (!preparation?.filePath) {
    discardClaudeLocalCommandWatcherPreparation(preparation, 'transcript-unavailable');
    return;
  }
  const terminal = terminals.get(tabId) || null;
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  if (!terminal || !launch?.generation || !Number.isFinite(Number(launch.at))) {
    discardClaudeLocalCommandWatcherPreparation(preparation, 'launch-generation-unavailable');
    return;
  }
  const proofAttempt = {
    terminal,
    generation: launch?.generation || null,
    sessionId: preparation.sessionId || null,
    launchAt: Number(launch?.at || 0),
    preparation,
    watcher: null,
    scanInFlight: false,
    rescanRequested: false,
    sawCompactedOutput: false,
    activated: false,
    lastReason: null,
  };
  claudePtyCompactProofInflight.set(tabId, proofAttempt);
  try {
    proofAttempt.watcher = fs.watch(
      preparation.filePath,
      { persistent: false },
      () => requestClaudePtyCompactTranscriptProof(
        tabId,
        proofAttempt,
        'transcript-change',
      ),
    );
  } catch (error) {
    console.warn('[ClaudeLocalCommand] proof watcher unavailable tab=' + tabId.slice(-12)
      + ' command=/compact error=' + (error?.message || String(error))
      + ' - PTY output will continue event-driven proof attempts');
  }
  requestClaudePtyCompactTranscriptProof(tabId, proofAttempt, 'pty-output-initial');
}

function noteClaudePtyCompactOutputCompletion(tabId) {
  const attempt = claudePtyCompactProofInflight.get(tabId) || null;
  if (!attempt) return;
  attempt.sawCompactedOutput = true;
  requestClaudePtyCompactTranscriptProof(tabId, attempt, 'pty-output-completed');
}

function trackClaudeInputLineForLocalCommands(
  tabId,
  data,
  { isTerminalProtocolResponse = false } = {},
) {
  if (!bridgeKnownSessions.has(tabId) || typeof data !== 'string' || data.length === 0) return null;
  const inputOwner = {
    ...readClaudeLocalCommandOwner(tabId),
    promptSeq: promptBoundarySeq.get(tabId) || 0,
  };
  const observed = advanceManualInputLineState(
    claudeInputLineBuffers.get(tabId) || null,
    {
      data,
      owner: inputOwner,
      isTerminalProtocolResponse,
    },
  );
  if (observed.state) claudeInputLineBuffers.set(tabId, observed.state);
  else claudeInputLineBuffers.delete(tabId);

  let preparation = null;
  for (const command of observed.submittedCommands) {
    console.log('[ClaudeLocalInput] SUBMIT tab=' + tabId.slice(-12)
      + ' command=' + JSON.stringify(String(command || '').slice(0, 80))
      + ' exactCompact=' + (command === '/compact')
      + ' promptSeq=' + inputOwner.promptSeq
      + ' reason=' + observed.reason);
    if (command !== '/compact') continue;
    const candidate = prepareClaudeLocalCommandWatcher(tabId, command, 'terminal-input');
    if (!preparation) preparation = candidate;
    else discardClaudeLocalCommandWatcherPreparation(candidate, 'duplicate-command-in-input-burst');
  }
  return preparation;
}

function isManualXtermInputOrigin(origin) {
  // Terminal.ts marks real xterm onData as user/unknown. Main-generated
  // protocol replies and external submit paths must not feed this tracker.
  return origin === 'user' || origin === 'unknown';
}

function readCodexManualInputOwner(tabId) {
  const watcher = codexTurnWatchers.get(tabId) || null;
  return {
    terminal: terminals.get(tabId) || null,
    sessionId: watcher?.sessionId || getCodexRuntimeSessionId(tabId) || null,
    generation: getTerminalLifecycleGeneration(tabId),
    promptSeq: codexPromptGeneration.get(tabId) || 0,
  };
}

function captureCodexManualCompactBoundary(tabId, owner) {
  const watcher = codexTurnWatchers.get(tabId) || null;
  if (!watcher || !owner?.sessionId || !owner?.generation) return null;
  let sourceByteOffset = Number(watcher.offset);
  try {
    sourceByteOffset = fs.statSync(watcher.filePath).size;
  } catch {}
  return {
    tabId,
    sessionId: owner.sessionId,
    generation: owner.generation,
    promptSeq: owner.promptSeq,
    terminal: owner.terminal,
    filePath: watcher.filePath,
    sourceByteOffset: Number.isFinite(sourceByteOffset) ? sourceByteOffset : null,
    boundaryEventSequence: Number(watcher.eventSequence || 0),
  };
}

function sameCodexManualCompactOwner(pending, owner) {
  return !!pending && !!owner
    && pending.terminal === owner.terminal
    && pending.sessionId === owner.sessionId
    && pending.generation === owner.generation
    && Number(pending.promptGeneration) === Number(owner.promptSeq);
}

function cancelCodexManualCompactPending(tabId, reason, operationId = null) {
  const pending = compactOperations.getPending(tabId, 'codex');
  if (!pending || (operationId && pending.operationId !== operationId)) return null;
  const cancelled = compactOperations.cancelPending({
    tabId,
    provider: 'codex',
    operationId: pending.operationId,
    reason,
  });
  if (cancelled) {
    const feedback = codexCompactTuiFeedbackBuffers.get(tabId) || null;
    if (!feedback || !operationId || feedback.operationId === operationId) {
      codexCompactTuiFeedbackBuffers.delete(tabId);
    }
    console.log('[CodexManualInput] pending compact cancelled tab=' + String(tabId).slice(-12)
      + ' operation=' + pending.operationId
      + ' reason=' + reason);
  }
  return cancelled;
}

function reconcileCodexManualCompactPendingOwner(tabId) {
  const pending = compactOperations.getPending(tabId, 'codex');
  if (!pending) return null;
  const owner = readCodexManualInputOwner(tabId);
  if (sameCodexManualCompactOwner(pending, owner)) return pending;
  cancelCodexManualCompactPending(tabId, 'owner-generation-changed', pending.operationId);
  return null;
}

function normalizeCodexCompactTuiFeedbackChunk(value) {
  return String(value || '')
    // OSC strings and CSI/short ESC commands are presentation protocol, not
    // provider text. The refusal can wrap across rows/chunks, so whitespace is
    // normalized only after a bounded rolling buffer has been assembled.
    .replace(/\x1b\][^\x07]*(?:\x07|\x1b\\)/g, '')
    .replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '')
    .replace(/\x1b[()][0-2A-Z]/g, '')
    .replace(/[\x00-\x08\x0b-\x1f\x7f]/g, ' ');
}

function observeCodexPendingCompactTuiFeedback(tabId, data, terminal) {
  const pending = compactOperations.getPending(tabId, 'codex');
  if (!pending || pending.terminal !== terminal) {
    codexCompactTuiFeedbackBuffers.delete(tabId);
    return null;
  }
  const previous = codexCompactTuiFeedbackBuffers.get(tabId);
  const joined = String(previous?.operationId === pending.operationId ? previous.text : '')
    + normalizeCodexCompactTuiFeedbackChunk(data);
  const bounded = joined.slice(-2048);
  const normalized = bounded.replace(/\s+/g, ' ').trim();
  if (!/[\'’]\/compact[\'’] is disabled while a task is in progress\./i.test(normalized)) {
    codexCompactTuiFeedbackBuffers.set(tabId, {
      operationId: pending.operationId,
      text: bounded,
    });
    return null;
  }

  codexCompactTuiFeedbackBuffers.delete(tabId);
  const settled = compactOperations.rejectPending({
    tabId,
    provider: 'codex',
    operationId: pending.operationId,
    sessionId: pending.sessionId,
    generation: pending.generation,
    promptGeneration: pending.promptGeneration,
    terminal,
    outcome: 'failed',
    reason: 'compact-disabled-while-task-in-progress',
    completionProof: 'exact-codex-tui-compact-disabled-notice',
    message: CODEX_COMPACT_BUSY_TUI_NOTICE,
    endedAt: Date.now(),
  });
  if (settled) {
    console.warn('[CodexCompactFeedback] rejected tab=' + String(tabId).slice(-12)
      + ' operation=' + pending.operationId
      + ' reason=' + settled.reason
      + ' proof=' + settled.completionProof);
  }
  return settled;
}

function isCodexRecordAfterManualCompactBoundary(pending, record) {
  if (!pending || !record) return false;
  const eventSequence = Number(record.__eventSequence);
  const boundarySequence = Number(pending.causalBoundaryEventSequence);
  if (!Number.isFinite(eventSequence)
    || (Number.isFinite(boundarySequence) && eventSequence <= boundarySequence)) return false;
  const sourceByteOffset = Number(record.__byteOffset);
  const boundaryOffset = Number(pending.sourceByteOffset);
  if (!Number.isFinite(sourceByteOffset)) return false;
  if (!Number.isFinite(boundaryOffset)) return true;
  return sourceByteOffset >= boundaryOffset;
}

function codexManualCompactCancelReasonForInput(data) {
  if (isPureCodexEscapeBurst(data)) return 'input-escape';
  if (data === '\x03') return 'input-ctrl-c';
  return 'manual-content-changed';
}

function trackCodexInputLineForCompact(
  tabId,
  data,
  { isTerminalProtocolResponse = false, xtermInputOrigin = null } = {},
) {
  if (!isManualXtermInputOrigin(xtermInputOrigin)
    || typeof data !== 'string'
    || data.length === 0
    || !hasEstablishedCodexLifecycleIndicators(tabId)) return null;
  const owner = readCodexManualInputOwner(tabId);
  const pending = reconcileCodexManualCompactPendingOwner(tabId);
  // Enter is allowed to repeat: the first one may only accept Codex's slash
  // suggestion and the second one may be the provider submit. Any other real
  // user input changes/cancels that exact intent. Terminal protocol replies
  // are observational noise and cannot take ownership.
  if (pending
    && !isTerminalProtocolResponse
    && !/^[\r\n]+$/.test(data)) {
    cancelCodexManualCompactPending(
      tabId,
      codexManualCompactCancelReasonForInput(data),
      pending.operationId,
    );
  }
  const observed = advanceManualInputLineState(
    codexInputLineBuffers.get(tabId) || null,
    { data, owner, isTerminalProtocolResponse },
  );
  if (observed.state) codexInputLineBuffers.set(tabId, observed.state);
  else codexInputLineBuffers.delete(tabId);

  for (let commandIndex = 0; commandIndex < observed.submittedCommands.length; commandIndex += 1) {
    const command = observed.submittedCommands[commandIndex];
    const commandDetail = observed.submittedCommandDetails?.[commandIndex] || null;
    console.log('[CodexManualInput] SUBMIT tab=' + String(tabId).slice(-12)
      + ' command=' + JSON.stringify(String(command).slice(0, 80))
      + ' exactCompact=' + (command === '/compact')
      + ' promptSeq=' + owner.promptSeq
      + ' reason=' + observed.reason);
    if (terminalHistoryStreamingEnabled
      && command !== '/compact'
      && !String(command || '').trimStart().startsWith('/')) {
      const watcher = codexTurnWatchers.get(tabId) || null;
      if (watcher) {
        watcher.terminalHistoryPreviewPendingPrompt = {
          text: String(command || ''),
          terminal: owner.terminal,
          lifecycleGeneration: owner.generation,
          promptGeneration: owner.promptSeq,
          sourceSequence: Number(watcher.eventSequence || 0),
          sourceByteOffset: Number(watcher.offset || 0),
          source: 'manual-terminal-enter',
          promptTruncated: commandDetail?.truncated === true,
        };
        console.log('[TerminalHistoryPreview] PROMPT_CAPTURE tab=' + String(tabId).slice(-12)
          + ' provider=codex source=manual-terminal-enter'
          + ' chars=' + String(command || '').length
          + ' truncated=' + (commandDetail?.truncated === true)
          + ' lifecycle=' + String(owner.generation || '-').slice(-18)
          + ' promptGeneration=' + owner.promptSeq);
      }
    }
    if (command !== '/compact') continue;
    const boundary = captureCodexManualCompactBoundary(tabId, owner);
    if (boundary) return { command, boundary };
  }
  return null;
}

function activateCodexManualCompactAfterPtyWrite(preparation) {
  const boundary = preparation?.boundary || null;
  if (!boundary) return null;
  const currentOwner = readCodexManualInputOwner(boundary.tabId);
  if (
    currentOwner.terminal !== boundary.terminal
    || currentOwner.sessionId !== boundary.sessionId
    || currentOwner.generation !== boundary.generation
    || currentOwner.promptSeq !== boundary.promptSeq
  ) {
    console.warn('[CodexManualInput] exact /compact Enter rejected owner change tab='
      + String(boundary.tabId).slice(-12));
    return null;
  }
  const operation = compactOperations.armPending({
    tabId: boundary.tabId,
    provider: 'codex',
    command: '/compact',
    operationId: 'codex:manual:' + boundary.generation
      + ':' + boundary.promptSeq
      + ':' + boundary.sourceByteOffset
      + ':' + boundary.boundaryEventSequence,
    sessionId: boundary.sessionId,
    generation: boundary.generation,
    promptGeneration: boundary.promptSeq,
    terminal: boundary.terminal,
    sourceByteOffset: boundary.sourceByteOffset,
    causalBoundaryEventSequence: boundary.boundaryEventSequence,
    source: 'manual-xterm-enter',
    acceptedAt: Date.now(),
  });
  if (operation) {
    console.log('[CodexManualInput] pending compact armed tab=' + String(boundary.tabId).slice(-12)
      + ' session=' + String(boundary.sessionId).slice(0, 8)
      + ' generation=' + boundary.generation
      + ' promptGeneration=' + boundary.promptSeq
      + ' sourceOffset=' + (boundary.sourceByteOffset ?? '-')
      + ' eventBoundary=' + boundary.boundaryEventSequence);
  }
  return operation;
}

// ─── JSONL interruption watcher implementation ───────────────────────────
// The hook carries the actual writer path (including custom config roots).
// Re-encoding cwd loses punctuation rules, e.g. fixture.with.dots -> hyphens.
// Shared session discovery is the fallback. Sets up fs.watch on the file;
// each `change` event triggers a tail-read from the last byte offset, parses
// newly-added lines, and flips busy=false if any line matches the
// interruption marker. Idempotent — safe to call repeatedly.
function startInterruptWatcher(tabId, sessionId, transcriptPath = null) {
  stopInterruptWatcher(tabId); // cancel any previous one
  const cwd = terminalProjects.get(tabId);
  if (!cwd || !sessionId) return;
  const hookPath = typeof transcriptPath === 'string' && path.isAbsolute(transcriptPath)
    && path.basename(transcriptPath) === sessionId + '.jsonl' ? path.resolve(transcriptPath) : null;
  const filePath = hookPath || findSessionFile(sessionId, cwd)?.filePath || null;
  if (!filePath) {
    console.warn('[ClaudeInterrupt:JSONL] tab=' + tabId.slice(-12) + ' exact transcript path unavailable');
    return;
  }
  let offset = 0;
  try { offset = fs.statSync(filePath).size; } catch { /* file may appear after first turn */ }
  const state = { watcher: null, filePath, offset, debounce: null };
  const onChange = () => {
    if (state.debounce) return; // coalesce burst of change events
    state.debounce = setTimeout(() => {
      state.debounce = null;
      if (claudeInterruptWatchers.get(tabId) !== state) return;
      let stat;
      try { stat = fs.statSync(filePath); } catch { return; }
      if (stat.size <= state.offset) { state.offset = stat.size; return; }
      const fd = fs.openSync(filePath, 'r');
      const len = stat.size - state.offset;
      const buf = Buffer.alloc(len);
      try { fs.readSync(fd, buf, 0, len, state.offset); }
      finally { fs.closeSync(fd); }
      state.offset = stat.size;
      const lines = buf.toString('utf8').split('\n');
      for (const line of lines) {
        if (!line) continue;
        // Cheap pre-check before JSON.parse — most lines won't match.
        if (line.indexOf('[Request interrupted') === -1) continue;
        let rec;
        try { rec = JSON.parse(line); } catch { continue; }
        const interruptText = claudeDataApi.claudeUserRecordText(rec);
        if (!INTERRUPT_TEXTS.has(interruptText)) continue;
        // Authoritative interruption signal — flip busy=false and tear down.
        if (claudeTurnBusy.get(tabId) === true) {
          console.warn('[ClaudeInterrupt:JSONL] tab=' + tabId.slice(-12) + ' interruption record found in transcript — forcing busy=false (' + interruptText + ')');
          safelyObserveProviderSemantic('claude-interrupt-jsonl', () => providerSemanticShadow.finishClaudeTurn({
            tabId, reason: 'interrupt-jsonl',
          }));
          terminalHistoryPreviewController.finish({
            tabId,
            provider: 'claude',
            reason: 'interrupt-jsonl',
          });
          clearClaudeProviderFatalTurnWatch(tabId, 'interrupt-jsonl');
          claudeTurnBusy.set(tabId, false);
          wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, 'interrupt-jsonl');
          claudeSpinnerBusy.set(tabId, false);
          taskCompletionIntents.abortTurn(tabId);
          clearTimeout(claudeTurnWatchdog.get(tabId));
          claudeTurnWatchdog.delete(tabId);
          recordActivity(tabId, false, 'claude');
          if (mainWindow && !mainWindow.isDestroyed()) {
            // Esc/Ctrl+C interrupt (transcript marker found) — NOT a natural
            // completion. reason:'interrupt' makes the prompt-queue auto-runner
            // skip firing the next prompt. busy:false still turns the loader off.
            mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: 'interrupt' });
            mainWindow.webContents.send('claude:turn-state', {
              tabId, sessionId,
              event: 'InterruptStop', busy: false, success: false,
              lastAssistantMessage: null,
            });
            _webBroadcast(tabId, {
              type: 'busy',
              busy: false,
              reason: 'interrupt',
              toolType: 'claude',
              commandType: 'claude',
              sessionId,
              sessionStatus: 'active',
              inputReady: true,
            });
            _webBroadcast(tabId, { type: 'done', sessionId, reason: 'interrupt' });
          }
        }
        stopInterruptWatcher(tabId);
        return;
      }
    }, 100);
  };
  try {
    state.watcher = fs.watch(filePath, { persistent: false }, onChange);
    console.log('[ClaudeInterrupt:JSONL] tab=' + tabId.slice(-12) + ' watching ' + filePath.replace(os.homedir(), '~') + ' (offset=' + offset + ')');
  } catch (e) {
    // File doesn't exist yet — Claude will create it on first prompt write.
    // Try once more after a short delay; if still missing, give up silently
    // (turn watchdog @60min remains as last-resort fallback).
    setTimeout(() => {
      if (claudeInterruptWatchers.get(tabId) !== state) return; // closed/replaced turn
      try {
        state.watcher = fs.watch(filePath, { persistent: false }, onChange);
        try { state.offset = fs.statSync(filePath).size; } catch {}
        console.log('[ClaudeInterrupt:JSONL] tab=' + tabId.slice(-12) + ' watching (delayed) ' + filePath.replace(os.homedir(), '~'));
      } catch (e2) {
        console.warn('[ClaudeInterrupt:JSONL] tab=' + tabId.slice(-12) + ' failed to attach watcher: ' + e2.message);
        claudeInterruptWatchers.delete(tabId);
      }
    }, 500);
  }
  claudeInterruptWatchers.set(tabId, state);
}

function stopInterruptWatcher(tabId) {
  const state = claudeInterruptWatchers.get(tabId);
  if (!state) return;
  if (state.debounce) clearTimeout(state.debounce);
  if (state.idleProbe) clearTimeout(state.idleProbe);
  if (state.watcher) { try { state.watcher.close(); } catch {} }
  claudeInterruptWatchers.delete(tabId);
}

// Safety net для пограничного кейса:
// Юзер нажал Esc, но Claude НЕ написал "[Request interrupted by user]" в JSONL
// (например прервал до старта стрима, или короткий turn закончился до Esc).
// Watcher по marker'у не сработает, Stop hook не приходит, loader залип.
//
// Решение: armInterruptIdleProbe вызывается из `terminal:input` когда юзер шлёт
// pure Esc (1 байт `\x1b`) или Ctrl+C (`\x03`). Через PROBE_DELAY_MS=1500 проверяем:
// если JSONL не менялся последние PROBE_QUIET_MS=1200 (mtime stale) И turn всё
// ещё помечен busy — значит Claude ничего не пишет → принудительно busy=false.
//
// Почему именно pure Esc, не любой `\x1b`:
// — стрелки/F-keys приходят как многобайтные ESC-sequences (`\x1b[A`, `\x1bO...`),
//   их пропускаем, иначе любая навигация ложно disarm'ит loader (см. fix-claude-aborted-streaming-loader.md).
// — Ctrl+C = одиночный `\x03`, тоже однозначен.
//
// Idle-проверка вместо немедленного сброса:
// — если Claude ЕСТЬ работает (Esc был «случайным»/не был перехвачен TUI), он продолжает
//   писать в JSONL → mtime свежий → guard не срабатывает.
// — если Claude НЕ работает → mtime замораживается → guard правомерно сбрасывает.
function armInterruptIdleProbe(tabId) {
  const state = claudeInterruptWatchers.get(tabId);
  if (!state || !state.filePath) return;
  if (state.idleProbe) clearTimeout(state.idleProbe);
  const PROBE_DELAY_MS = 1500;
  const PROBE_QUIET_MS = 1200;
  state.idleProbe = setTimeout(() => {
    state.idleProbe = null;
    if (claudeTurnBusy.get(tabId) !== true) return; // turn уже завершён нормально
    let stat;
    try { stat = fs.statSync(state.filePath); } catch { return; }
    const ageMs = Date.now() - stat.mtimeMs;
    if (ageMs < PROBE_QUIET_MS) return; // Claude всё ещё что-то пишет — не сбрасываем
    console.warn('[ClaudeInterrupt:Idle] tab=' + tabId.slice(-12) + ' Esc/Ctrl+C без JSONL-записей за ' + ageMs + 'ms — forcing busy=false');
    terminalHistoryPreviewController.finish({
      tabId,
      provider: 'claude',
      reason: 'interrupt-idle',
    });
    clearClaudeProviderFatalTurnWatch(tabId, 'interrupt-idle');
    claudeTurnBusy.set(tabId, false);
    wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, 'interrupt-idle');
    claudeSpinnerBusy.set(tabId, false);
    taskCompletionIntents.abortTurn(tabId);
    clearTimeout(claudeTurnWatchdog.get(tabId));
    claudeTurnWatchdog.delete(tabId);
    recordActivity(tabId, false, 'claude');
    if (mainWindow && !mainWindow.isDestroyed()) {
      // Esc/Ctrl+C before Claude wrote anything to JSONL (idle-probe fallback) —
      // NOT a natural completion. reason:'interrupt' makes the prompt-queue
      // auto-runner skip the next prompt. busy:false still clears the loader.
      const sessionId = bridgeKnownSessions.get(tabId) || null;
      mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: 'interrupt' });
      mainWindow.webContents.send('claude:turn-state', {
        tabId,
        sessionId,
        event: 'InterruptStop',
        busy: false, success: false, lastAssistantMessage: null,
      });
      _webBroadcast(tabId, {
        type: 'busy',
        busy: false,
        reason: 'interrupt',
        toolType: 'claude',
        commandType: 'claude',
        sessionId,
        sessionStatus: 'active',
        inputReady: true,
      });
      _webBroadcast(tabId, { type: 'done', sessionId, reason: 'interrupt' });
    }
    stopInterruptWatcher(tabId);
  }, PROBE_DELAY_MS);
}

function startClaudeHookServer() {
  try { fs.unlinkSync(CLAUDE_HOOK_SOCK); } catch {}
  claudeHookServer = net.createServer((sock) => {
    const connId = ++claudeHookConnSeq;
    const tConnect = Date.now();
    let dataBytes = 0;
    let lines = 0;
    console.log('[ClaudeHook:Conn] open seq=' + connId);
    let buf = '';
    sock.setEncoding('utf8');
    sock.on('data', (chunk) => {
      dataBytes += chunk.length;
      buf += chunk;
      let nl;
      while ((nl = buf.indexOf('\n')) !== -1) {
        const line = buf.slice(0, nl);
        buf = buf.slice(nl + 1);
        if (!line.trim()) continue;
        lines++;
        let msg;
        try { msg = JSON.parse(line); } catch (e) {
          console.warn('[ClaudeHook] Bad JSON conn=' + connId + ':', e.message);
          continue;
        }
        const {
          event,
          session_id,
          last_assistant_message,
          ts,
          transcript_path,
          ppid,
          tool_use_id,
          prompt: submitted_prompt,
        } = msg;
        const eventSeq = ++claudeHookEventSeq;

        // Send ack back to scripts so they can distinguish "kernel buffered"
        // from "server actually parsed it". GrabInput is the one exception:
        // its helper exits only after this ack, and the parent TUI cannot redraw
        // before that exit. We therefore arm the post-editor PTY edge first and
        // acknowledge inside the GrabInput branch. This closes the race where
        // Claude/Codex returned and redrew before main subscribed.
        const acknowledgeHookEnvelope = () => {
          try { sock.write('ok\n'); } catch {}
        };
        if (event !== 'GrabInput') acknowledgeHookEnvelope();

        // The v2 helper has not changed the editor file yet. Only this exact
        // operation/owner/generation may authorize it; PID matching alone would
        // let a late helper steal a newer capture's promise and input effects.
        if (event === 'GrabInput') {
          const cliPid = Number(msg.ppid);
          const tabId = typeof msg.tabId === 'string' ? msg.tabId : null;
          const pending = grabInputPending.get(tabId);
          const acknowledgeCapture = decision => {
            try {
              sock.write(JSON.stringify({
                protocol: 2,
                ownerId: msg.ownerId,
                terminalId: msg.terminalId,
                operationId: msg.operationId,
                helperId: msg.helperId,
                decision,
              }) + '\n');
            } catch {}
          };
          if (!pending || !agentInputCaptureProtocol.matchesEnvelope(pending.captureOperation, msg)) {
            acknowledgeCapture('cancel');
            console.warn('[ClaudeHook] GrabInput rejected unmatched operation ppid=' + cliPid
              + ' operation=' + String(msg.operationId || 'legacy'));
            continue;
          }
          if (pending.processing === true) {
            acknowledgeCapture('duplicate');
            continue;
          }
          pending.processing = true;
          pending.helperId = msg.helperId;
          const agent = pending.agent;
          const text = typeof msg.text === 'string' ? msg.text : '';
          const mode = pending.mode;
          console.log('[ClaudeHook] #' + eventSeq + ' GrabInput agent=' + agent
            + ' tab=' + tabId.slice(-12) + ' mode=' + mode + ' bytes=' + text.length
            + ' operation=' + pending.captureOperation.operationId);
          if (pending) {
            // The PTY write lock remains owned until this promise resolves.
            // Claude exposes a complete synchronized-output frame. Codex does
            // not expose that marker contract here, so its first post-helper
            // PTY output is the deterministic parent-resumed edge. The bounded
            // timeout only produces unknown/failure; it is never success proof.
            const startEditorReturnWait = () => agent === 'claude'
              ? waitForNextPtySynchronizedFrame(pending.captureIdentity?.terminalToken, {
                timeoutMs: 1500,
              })
              : waitForNextPtyOutput(pending.captureIdentity?.terminalToken, {
                timeoutMs: 1500,
              });
            let editorReturnPromise = null;
            const identityStableAtHook = validateAgentInputIdentity(tabId, pending.captureIdentity);
            if (!identityStableAtHook || pending.timedOut === true) {
              editorReturnPromise = startEditorReturnWait();
              const cancellation = agentInputCaptureProtocol.cancel(pending.captureOperation,
                pending.timedOut ? 'external_editor_timeout' : 'capture_generation_changed');
              clearTimeout(pending.timer);
              acknowledgeCapture('cancel');
              void waitForAgentEditorReturnReady(tabId, agent, pending.captureIdentity, editorReturnPromise)
                .then(editorReturn => {
                  if (editorReturn?.ready === true) {
                    releaseAgentInputCapturePending(tabId, pending, { parentReturned: true });
                  }
                  pending.resolve({
                    success: false,
                    error: cancellation.reason || 'capture_operation_cancelled',
                    draftPreserved: true,
                  });
                }).catch(error => {
                  console.warn('[ClaudeHook] cancelled capture return unconfirmed:', error.message);
                  pending.resolve({ success: false, error: 'external_editor_return_unconfirmed', draftPreserved: true });
                });
              continue;
            }
            const images = (text.match(/\[Image(?:\s+#?\d+)?\]/g) || []).length;
            const exactEmpty = !String(text || '').trim() && images === 0;
            let contradiction = null;
            if (exactEmpty) {
              contradiction = logAgentDraftProofContradiction(tabId, agent, pending, text);
            }
            void (async () => {
              let resolvedText = text;
              let sourceRefs = [];
              if (images > 0 && agent === 'codex') {
                const exact = codexImageBindings.resolveGrab(tabId, text, { consume: false });
                resolvedText = exact.text;
                sourceRefs = exact.refs;
                console.warn('[GrabImages:Codex] tab=' + tabId.slice(-12)
                  + ' refs=' + images + ' pathResolved=' + exact.resolved + ' missing=' + exact.missing
                  + ' mode=slot-binding');
              } else if (images > 0 && agent !== 'codex') {
                const sid = bridgeKnownSessions.get(tabId) || null;
                const resolved = resolveGrabbedImagePaths(sid, text);
                sourceRefs = resolved.filter((ref) => !ref.missing);
                const summary = resolved.map((ref) => ref.missing
                  ? ('#' + ref.id + ':MISSING')
                  : ('#' + ref.id + ':' + (ref.size / 1024).toFixed(1) + 'KB')).join(',');
                console.log('[GrabImages] tab=' + tabId.slice(-12) + ' sessionId=' + (sid ? sid.slice(0, 8) : 'none') + ' refs=' + images + ' resolved=[' + summary + ']');
              }

              const durableRefs = sourceRefs.length > 0
                ? await promptQueueAssetStore.materializeRefs(sourceRefs)
                : [];
              const availableById = new Map(durableRefs
                .filter((ref) => ref.availability === 'available')
                .map((ref) => [Number(ref.id), ref]));
              if (images > 0) {
                resolvedText = resolvedText.replace(/\[Image(?:\s+#?(\d+))?\]/g, (marker, rawId) => {
                  if (!rawId) {
                    const prefix = agent === 'codex' ? 'codex' : 'claude';
                    return '[imageError: ' + prefix + '_image_path_unavailable #unknown]';
                  }
                  const id = Number(rawId);
                  if (availableById.has(id)) return marker;
                  const prefix = agent === 'codex' ? 'codex' : 'claude';
                  return '[imageError: ' + prefix + '_image_path_unavailable #' + rawId + ']';
                });
              }
              const imagePaths = Array.from(availableById.values());
              // Stage the complete authoring snapshot BEFORE granting clear.
              // A resolver/disk failure must leave the native draft untouched.
              pending.preparedDraft = { text: resolvedText, capturedText: text, images, imagePaths };
              console.log('[PromptQueueAssets] grab tab=' + tabId.slice(-12)
                + ' agent=' + agent + ' requested=' + images + ' durable=' + imagePaths.length);
              // Arm parent-return before disk commit and socket ACK. Commit is
              // separate from readiness: its transferred snapshot survives a
              // later return timeout or generation change.
              editorReturnPromise = startEditorReturnWait();
              const authorization = agentInputCaptureProtocol.authorize(
                pending.captureOperation,
                msg,
                identityStableAtHook && validateAgentInputIdentity(tabId, pending.captureIdentity)
                  && pending.timedOut !== true,
              );
              clearTimeout(pending.timer);
              acknowledgeCapture(authorization.decision);
              const editorReturn = await waitForAgentEditorReturnReady(
                tabId,
                agent,
                pending.captureIdentity,
                editorReturnPromise,
              );
              let identityStable = identityStableAtHook
                && validateAgentInputIdentity(tabId, pending.captureIdentity);
              const helperOutcome = readCaptureOutcome(pending.captureOperation);
              const helperApplied = captureOperationMatches(helperOutcome, pending.captureOperation)
                && helperOutcome.helperId === msg.helperId
                && helperOutcome.applied === true;
              const draftTransfer = buildAgentDraftTransfer(
                pending.captureOperation, helperOutcome, pending.preparedDraft, msg.helperId,
              );
              // Deterministic crash probe only: the real helper has applied
              // the grab, but no result has reached its receiving consumer.
              // Production cannot arm this gate and does not gain an await.
              if (aiBoundaryTestGate.enabled && helperApplied && mode === 'grab') {
                const captureBoundary = await aiBoundaryTestGate.waitIfArmed({
                  kind: 'agent-capture-after-apply',
                  identity: {
                    tabId, provider: agent, mode,
                    captureOperationId: pending.captureOperation.operationId,
                    captureRequestId: pending.captureRequestId || pending.captureOperation.operationId,
                  },
                });
                if (captureBoundary?.claimed) {
                  identityStable = identityStable
                    && validateAgentInputIdentity(tabId, pending.captureIdentity);
                  aiBoundaryTestGate.complete({
                    armId: captureBoundary.arm.armId,
                    operationId: captureBoundary.arm.operationId,
                    reason: 'capture-return-probe-released',
                    result: { helperApplied: true, identityStable },
                  });
                }
              }
              if (helperApplied && identityStable && agent === 'codex'
                && (mode === 'grab' || mode === 'clear' || mode === 'restore' || mode === 'put')) {
                codexImageBindings.resetComposer(tabId);
              }
              const inputRevisionTransitionOwned =
                validateAgentExactCaptureInputTransition(pending);
              logAgentDraftProofContradictionAfterReturn(
                tabId,
                agent,
                contradiction,
                editorReturn,
                identityStable,
                inputRevisionTransitionOwned,
              );
              const exactEmptyProven = exactEmpty
                && !!contradiction
                && identityStable
                && inputRevisionTransitionOwned
                && editorReturn?.ready === true
                && helperApplied;
              if (editorReturn?.ready === true) {
                releaseAgentInputCapturePending(tabId, pending, { parentReturned: true });
              }
              const captureSucceeded = editorReturn?.ready === true && helperApplied && identityStable;
              pending.resolve({
                success: captureSucceeded,
                ...(captureSucceeded
                  ? {}
                  : { error: !identityStable
                    ? 'capture_generation_changed'
                    : (!helperApplied ? 'external_editor_mutation_unconfirmed' : 'external_editor_return_unconfirmed') }),
                text: resolvedText,
                capturedText: text,
                images,
                imagePaths,
                draftTransfer,
                draftPreserved: helperOutcome?.preserved === true,
                captureOperationId: pending.captureOperation.operationId,
                captureRequestId: pending.captureRequestId,
                mode,
                proofOutcome: identityStable
                  ? (exactEmptyProven ? 'absent' : (exactEmpty ? 'unknown' : 'found'))
                  : 'unknown',
                proofReason: identityStable
                  ? (exactEmptyProven
                    ? 'external-editor-empty-current-frame'
                    : (exactEmpty
                      ? (editorReturn?.reason || 'external-editor-return-unconfirmed')
                      : 'external-editor-draft-found'))
                  : 'terminal-or-input-generation-changed-during-grab',
                editorReturnReady: editorReturn?.ready === true,
                editorReturnReason: editorReturn?.reason || null,
                ...publicAgentInputIdentity(pending.captureIdentity, identityStable),
                ...(exactEmptyProven
                  ? {
                      screenContradiction: true,
                      inputRevisionTransition: 'ctrl-g-exact-capture',
                      inputRevisionTransitionOwned: true,
                      screenProofInputRevision:
                        pending.draftProofCaptureIdentity?.inputRevision ?? null,
                    }
                  : {}),
              });
            })().catch(async (error) => {
              console.error('[PromptQueueAssets] grab materialization failed tab=' + tabId.slice(-12) + ':', error);
              if (!editorReturnPromise) editorReturnPromise = startEditorReturnWait();
              agentInputCaptureProtocol.cancel(pending.captureOperation, 'image_materialization_failed');
              clearTimeout(pending.timer);
              acknowledgeCapture('cancel');
              const editorReturn = await waitForAgentEditorReturnReady(
                tabId, agent, pending.captureIdentity, editorReturnPromise,
              ).catch(() => null);
              const helperOutcome = readCaptureOutcome(pending.captureOperation);
              const draftTransfer = buildAgentDraftTransfer(
                pending.captureOperation, helperOutcome, pending.preparedDraft, msg.helperId,
              );
              if (editorReturn?.ready === true) releaseAgentInputCapturePending(tabId, pending, { parentReturned: true });
              pending.resolve({
                success: false,
                error: error?.code || 'image_materialization_failed',
                mode,
                text: pending.preparedDraft?.text ?? text,
                capturedText: text,
                images,
                imagePaths: pending.preparedDraft?.imagePaths || [],
                draftTransfer,
                draftPreserved: !draftTransfer,
                editorReturnReady: editorReturn?.ready === true,
                captureOperationId: pending.captureOperation.operationId,
                captureRequestId: pending.captureRequestId,
              });
            });
          } else {
            acknowledgeHookEnvelope();
          }
          continue;
        }

        const hookRoute = resolveClaudeHookTab({
          sessionId: session_id,
          ppid,
          sessionByTab: bridgeKnownSessions,
          tabByPid: bridgePidCache,
          hasTab: (candidateTabId) => terminals.has(candidateTabId),
        });
        const tabId = hookRoute.tabId;
        if (!tabId) {
          // Session not in our tab map — could be a stray claude process outside our terminal.
          console.log('[ClaudeHook] #' + eventSeq + ' ' + event
            + ' session=' + (session_id || '').slice(0, 8)
            + ' ppid=' + (Number.isSafeInteger(Number(ppid)) ? Number(ppid) : '-')
            + ' (no tab match)');
          continue;
        }
        if (hookRoute.source === 'pid') {
          console.log('[ClaudeHookRoute] tab=' + String(tabId).slice(-12)
            + ' session=' + (session_id || '').slice(0, 8)
            + ' ppid=' + hookRoute.pid
            + ' source=launch-pid-before-session');
        }

        const hookEventTs = Date.now();
        claudeHookLastEvent.set(tabId, { event, ts: hookEventTs, sessionId: session_id });
        if (event === 'UserPromptSubmit' || event === 'Stop' || event === 'StopFailure') {
          claudeToolScreenHolds.clear(tabId);
        }

        // ── Awaiting-user-input: AskUserQuestion brackets ──
        // PreToolUse(AskUserQuestion) fires the instant Claude blocks on its
        // interactive question dialog (toolExecution.ts: runPreToolUseHooks runs
        // BEFORE canUseTool, and for AskUserQuestion the dialog IS the permission
        // phase). PostToolUse fires when answered; PostToolUseFailure when the
        // question is cancelled/aborted with feedback. These three events must
        // NOT fall through to the `busy = event === 'UserPromptSubmit'` logic
        // below (that would wrongly force busy=false), so we handle + continue.
        // The tool_name guard keeps us scoped to AskUserQuestion even if other
        // tools ever get a PreToolUse matcher pointed at this same script.
        if (event === 'PreToolUse' || event === 'PostToolUse' || event === 'PostToolUseFailure') {
          let exactToolUseId = tool_use_id ? String(tool_use_id) : null;
          if (!exactToolUseId && event !== 'PreToolUse') {
            const legacyMatch = claudeToolScreenHolds.snapshot(tabId)
              .reverse()
              .find((tool) => !tool.completed
                && (!msg.tool_name || tool.toolName === String(msg.tool_name)));
            exactToolUseId = legacyMatch?.toolUseId || null;
          }
          if (!exactToolUseId && event === 'PreToolUse') {
            exactToolUseId = 'legacy:' + eventSeq + ':' + String(msg.tool_name || 'tool');
          }
          const tracked = event === 'PreToolUse'
            ? claudeToolScreenHolds.start({
              tabId,
              toolUseId: exactToolUseId,
              toolName: msg.tool_name,
            })
            : claudeToolScreenHolds.complete({
              tabId,
              toolUseId: exactToolUseId,
            });
          console.log('[ClaudeToolScreenHold] ' + event.toUpperCase()
            + ' tab=' + String(tabId).slice(-12)
            + ' tool=' + String(msg.tool_name || '-')
            + ' id=' + String(exactToolUseId || '-').slice(-24)
            + ' tracked=' + tracked
            + ' held=' + claudeToolScreenHolds.snapshot(tabId).length);
          if (msg.tool_name === 'AskUserQuestion') {
            const awaiting = event === 'PreToolUse';
            const prevAwaiting = claudeAwaitingInput.get(tabId);
            claudeAwaitingInput.set(tabId, awaiting);
            console.log('[ClaudeHook] #' + eventSeq + ' ' + event + '(AskUserQuestion) tab=' + tabId.slice(-12) + ' awaiting=' + awaiting + (prevAwaiting === awaiting ? ' (no change)' : ''));
            if (prevAwaiting !== awaiting && mainWindow && !mainWindow.isDestroyed()) {
              mainWindow.webContents.send('claude:awaiting-input', { tabId, awaiting });
            }
            // ── Mobile question mirror (PTY) ──
            // The desktop reads the question from the Ink TUI; mobile has no TUI,
            // so we forward the structured questions over the same web channel the
            // SDK path uses (type:'ask-question', source:'pty'). On PreToolUse we
            // store + broadcast the questions; on Post/PostFailure we clear +
            // broadcast question-cancelled (the user answered/cancelled at the
            // desktop TUI, or the turn aborted). Answering FROM mobile drives the
            // TUI via keystrokes — see claudePendingQuestion + answerClaudeQuestionPTY.
            if (awaiting) {
              const questions = Array.isArray(msg.tool_input?.questions) ? msg.tool_input.questions : [];
              claudePendingQuestion.set(tabId, {
                questions,
                toolUseID: exactToolUseId || 'pty',
                at: Date.now(),
              });
              console.log('[ClaudeHook] PTY question stored tab=' + tabId.slice(-12) + ' qs=' + questions.length);
              _webBroadcast(tabId, {
                type: 'ask-question',
                source: 'pty',
                toolUseID: exactToolUseId || 'pty',
                questions,
              });
            } else {
              if (claudePendingQuestion.has(tabId)) {
                claudePendingQuestion.delete(tabId);
                _webBroadcast(tabId, { type: 'question-cancelled', source: 'pty' });
              }
            }
          }
          // Pre/PostToolUse are mid-turn — they never change turn busy-state.
          continue;
        }

        // ── [PasteAudit] consume staged expectation on UserPromptSubmit ──
        // safePasteAndSubmit staged {expectedLen, expectedHash, ...} right
        // before pressing Enter. On the next UserPromptSubmit for this tab,
        // tail the transcript JSONL and compare the last user-record's text.
        // Mismatch → [PasteAudit:MISMATCH] log so future paste regressions
        // (TTYHOG truncation, ANSI corruption, single-write data loss) leave
        // detectable evidence instead of "feels wrong".
        let promptSubmitAudit = null;
        if (event === 'UserPromptSubmit') {
          clearClaudeEditableLastPrompt(tabId, 'user-prompt-submit');
          const auditsAtHook = getPendingClaudePasteAudits(tabId);
          const promptAuditOwner = selectUniqueClaudePromptSubmitAudit(
            auditsAtHook,
            submitted_prompt,
            {
              hashText: pasteAuditHash,
              hookTabId: tabId,
              hookPpid: ppid,
              hookPidTabId: bridgePidCache.get(Number(ppid)) || null,
              hookInputRevision: getTerminalInputRevision(tabId),
            },
          );
          promptSubmitAudit = promptAuditOwner.audit;
          if (
            promptSubmitAudit
            && promptAuditOwner.reason === 'unique-owned-provider-transform'
            && typeof submitted_prompt === 'string'
          ) {
            promptSubmitAudit.providerAcceptedText = submitted_prompt;
            promptSubmitAudit.providerAcceptedLen = submitted_prompt.length;
            promptSubmitAudit.providerAcceptedHash = pasteAuditHash(submitted_prompt);
            console.log('[PasteAudit] provider transform bound tab=' + tabId.slice(-12)
              + ' handoff=' + (promptSubmitAudit.handoffId || '-')
              + ' expectedLen=' + promptSubmitAudit.expectedLen
              + ' providerLen=' + submitted_prompt.length
              + ' form=' + (promptSubmitAudit.pasteReadyProof?.form || '-'));
          }
          if (
            promptSubmitAudit
            && promptAuditOwner.routeAdmission?.mode === 'fresh-exact-hook-route'
          ) {
            promptSubmitAudit.freshHookRouteConfirmed = true;
            promptSubmitAudit.freshHookSessionId = session_id || null;
            promptSubmitAudit.freshHookTranscriptPath = typeof transcript_path === 'string'
              ? path.resolve(transcript_path)
              : null;
            console.log('[PasteAudit] fresh hook route confirmed tab=' + tabId.slice(-12)
              + ' handoff=' + (promptSubmitAudit.handoffId || '-')
              + ' ppid=' + Number(ppid));
          }
          if (promptAuditOwner.reason === 'ambiguous-identical-pending-audits') {
            for (const audit of promptAuditOwner.matchingAudits) {
              audit.executionContextDiagnostic ||= promptAuditOwner.reason;
            }
            console.warn('[Orchestration] Claude prompt turn left unbound tab='
              + tabId.slice(-12)
              + ' reason=' + promptAuditOwner.reason
              + ' matches=' + promptAuditOwner.matchingAudits.length
              + ' handoffs=' + promptAuditOwner.matchingAudits
                .map((audit) => audit.handoffId || '-')
                .join(','));
          } else if (auditsAtHook.length > 0 && !promptSubmitAudit) {
            if (
              promptAuditOwner.reason === 'hook-prompt-unavailable'
              && auditsAtHook.length === 1
            ) {
              auditsAtHook[0].executionContextDiagnostic ||= promptAuditOwner.reason;
            }
            console.warn('[Orchestration] Claude prompt turn left unbound tab='
              + tabId.slice(-12)
              + ' reason=' + promptAuditOwner.reason
              + ' pending=' + auditsAtHook.length);
          }
          console.log('[PasteAudit] UserPromptSubmit tab=' + tabId.slice(-12) + ' pending=' + auditsAtHook.length + ' handoffs=' + auditsAtHook.map(a => a.handoffId || '-').join(',') + ' transcript=' + (transcript_path || '-'));
          if (auditsAtHook.length > 0 && transcript_path) {
            // Best-effort, never block the hook ack. Read async, log result.
            // Each pending expectation owns its own confirmation: a record
            // that matches none of them leaves every audit pending (unknown)
            // instead of failing a neighbor — the same contract Codex uses.
            (async () => {
              try {
                const resolvedHookPath = path.resolve(transcript_path);
                const freshAuditAwaitsFile = getPendingClaudePasteAudits(tabId).some((audit) => (
                  audit?.freshHookRouteConfirmed === true
                  && audit?.preSubmitBoundary?.available !== true
                  && audit?.preSubmitBoundary?.reason === 'transcript-unresolved'
                  && !audit?.preSubmitBoundary?.transcriptPath
                  && audit?.freshHookTranscriptPath === resolvedHookPath
                ));
                if (freshAuditAwaitsFile) {
                  const materialization = await waitForClaudeTranscriptMaterialization(
                    resolvedHookPath,
                    { timeoutMs: 7500 },
                  );
                  console.log('[PasteAudit] fresh transcript materialization tab='
                    + tabId.slice(-12)
                    + ' ready=' + materialization.materialized
                    + ' reason=' + materialization.reason
                    + ' transcript=' + resolvedHookPath);
                  if (!materialization.materialized) return;
                }
                // Bounded reads only; the tail extends past the 8s caller
                // timeout so a slow JSONL flush confirms late instead of
                // leaving the expectation to the next hook event.
                const delays = [0, 80, 220, 520, 1000, 2200, 4200];
                const confirmSelection = (selection, attempt) => {
                  const { audit, candidate } = selection;
                  const actualText = candidate.text;
                  const actualLen = actualText.length;
                  const actualHash = pasteAuditHash(actualText);
                  const canonicalIdentity = claudeAuditCanonicalIdentity(
                    audit,
                    actualText,
                    pasteAuditHash,
                  );
                  const auditSessionId = candidate.record?.sessionId
                    || path.basename(transcript_path, '.jsonl')
                    || audit.historySessionId;
                  const auditTimestamp = candidate.record?.timestamp
                    || new Date(audit.sentAt).toISOString();
                  const entryUuid = candidate.record?.uuid || null;
                  const presentationSaved = saveAuditedPromptPresentation(projectManager?.db, {
                    toolType: 'claude',
                    sessionId: auditSessionId,
                    entryUuid,
                    auditTimestamp,
                    actualText,
                    actualHash,
                    snapshot: audit.presentationSnapshot,
                  });
                  console.log('[PasteAudit] tab=' + tabId.slice(-12) + ' handoff=' + (audit.handoffId || '-') + ' source=' + (audit.source || '-') + ' carrier=' + (candidate.promptCarrierKind || 'unknown') + ' ✅ match len=' + actualLen + ' hash=' + actualHash + ' attempt=' + (attempt + 1) + ' late=' + (audit.callerTimedOut === true) + ' (sent ' + (Date.now() - audit.sentAt) + 'ms ago)');
                  finishClaudePasteAudit(tabId, audit, {
                    success: true,
                    actualLen,
                    actualHash,
                    sessionId: auditSessionId,
                    entryUuid,
                    auditTimestamp,
                    recordByteOffset: Number(candidate.byteOffset),
                    presentationSaved,
                    expectedLen: audit.expectedLen,
                    expectedHash: audit.expectedHash,
                    canonicalized: canonicalIdentity.canonicalized,
                    canonicalReason: canonicalIdentity.canonicalReason,
                  });
                };
                const claimedByteOffsets = new Set();
                let lastCandidates = [];
                for (let attempt = 0; attempt < delays.length; attempt++) {
                  const delay = delays[attempt];
                  if (delay > 0) await new Promise((resolve) => setTimeout(resolve, delay));
                  const pending = getPendingClaudePasteAudits(tabId);
                  if (pending.length === 0) return;
                  // One bounded read serves every expectation: start from the
                  // earliest same-file boundary, or fall back to the bounded
                  // tail when any boundary points at another (resume) file.
                  let readBoundary = null;
                  for (const auditItem of pending) {
                    const boundaryItem = auditItem.preSubmitBoundary;
                    if (
                      boundaryItem?.available !== true
                      || !boundaryItem.transcriptPath
                      || path.resolve(boundaryItem.transcriptPath) !== resolvedHookPath
                      || !Number.isFinite(Number(boundaryItem.fileSize))
                    ) {
                      readBoundary = null;
                      break;
                    }
                    if (!readBoundary || Number(boundaryItem.fileSize) < Number(readBoundary.fileSize)) {
                      readBoundary = boundaryItem;
                    }
                  }
                  const candidates = await readClaudeUserRecords(transcript_path, readBoundary);
                  lastCandidates = candidates;
                  let matched = 0;
                  for (;;) {
                    const alive = getPendingClaudePasteAudits(tabId);
                    if (alive.length === 0) break;
                    const selection = selectClaudePendingPromptAudit(alive, candidates, {
                      hashText: pasteAuditHash,
                      claimedByteOffsets,
                    });
                    try {
                      observeClaudePromptShapeCandidates(tabId, alive, candidates, {
                        selection, claimedByteOffsets, source: 'user-prompt-submit-hook',
                        hookPrompt: submitted_prompt,
                      });
                    } catch {}
                    if (!selection) break;
                    claimedByteOffsets.add(selection.candidate.byteOffset);
                    confirmSelection(selection, attempt);
                    matched += 1;
                  }
                  const remaining = getPendingClaudePasteAudits(tabId);
                  if (remaining.length === 0) return;
                  if (attempt < delays.length - 1) {
                    console.log('[PasteAudit] tab=' + tabId.slice(-12)
                      + ' matched=' + matched
                      + ' remaining=' + remaining.map(a => a.handoffId || '-').join(',')
                      + ' candidates=' + candidates.length
                      + ' attempt=' + (attempt + 1)
                      + ' — retrying');
                  }
                }
                // No definitive verdict: the remaining expectations stay
                // pending for late reconciliation (next UserPromptSubmit,
                // bridge-clear final scan, or age-bound eviction). Log the
                // newest unclaimed causal record for corruption forensics —
                // it is evidence, not identity proof, because it may belong
                // to a manual terminal submit.
                const remaining = getPendingClaudePasteAudits(tabId);
                if (remaining.length === 0) return;
                const unclaimed = lastCandidates.filter((candidate) => !claimedByteOffsets.has(candidate.byteOffset));
                const newestUnclaimed = unclaimed[unclaimed.length - 1] || null;
                if (newestUnclaimed) {
                  const newestAudit = remaining[remaining.length - 1];
                  console.warn('[PasteAudit:MISMATCH-CANDIDATE] tab=' + tabId.slice(-12)
                    + ' pending=' + remaining.map(a => a.handoffId || '-').join(',')
                    + ' expectedLen=' + newestAudit.expectedLen + ' actualLen=' + newestUnclaimed.text.length
                    + ' Δ=' + (newestUnclaimed.text.length - newestAudit.expectedLen)
                    + ' expectedHash=' + newestAudit.expectedHash + ' actualHash=' + pasteAuditHash(newestUnclaimed.text)
                    + ' expectedHead=[' + newestAudit.headPreview + ']'
                    + ' actualHead=[' + newestUnclaimed.text.substring(0, 80).replace(/\s+/g, ' ') + ']'
                    + ' expectedTail=[' + newestAudit.tailPreview + ']'
                    + ' actualTail=[' + newestUnclaimed.text.substring(Math.max(0, newestUnclaimed.text.length - 80)).replace(/\s+/g, ' ') + ']'
                    + ' attempts=' + delays.length
                    + ' transcript=' + transcript_path
                    + ' — kept pending, not failed');
                } else {
                  console.warn('[PasteAudit] tab=' + tabId.slice(-12)
                    + ' no causal user record after ' + delays.length + ' attempts'
                    + ' pending=' + remaining.map(a => a.handoffId || '-').join(',')
                    + ' transcript=' + transcript_path
                    + ' — kept pending for late reconciliation');
                }
              } catch (e) {
                console.warn('[PasteAudit] tab=' + tabId.slice(-12) + ' check failed: ' + e.message + ' — audits kept pending');
              }
            })();
          } else if (auditsAtHook.length > 0 && !transcript_path) {
            // A hook event without transcript_path proves nothing about
            // delivery; keep expectations pending for the next event.
            console.warn('[PasteAudit] tab=' + tabId.slice(-12) + ' pending=' + auditsAtHook.length + ' but transcript_path missing — kept pending');
          }
        }

        const busy = event === 'UserPromptSubmit';
        const internalAgentContinuationKind = busy
          ? claudeInternalAgentContinuationKind(submitted_prompt)
          : null;
        const prev = claudeTurnBusy.get(tabId);
        claudeTurnBusy.set(tabId, busy);
        if (!busy) {
          wakeClaudePostEnterResolutionWaitersForTurnIdle(tabId, event);
        }
        const launchGeneration = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
        if (launchGeneration) {
          claudePromptStability.markBusy(
            tabId,
            launchGeneration,
            busy,
            'claude-hook:' + event,
          );
        }
        const taskCompletionEligibility = busy
          ? loopTaskCompletionEligibility({
              source: promptSubmitAudit?.source,
              prompt: submitted_prompt,
            })
          : { eligible: false, source: null };
        const taskTurn = busy
          ? taskCompletionIntents.beginTurn({
              tabId,
              provider: 'claude',
              sessionId: session_id,
              processId: ppid,
              completionEligible: taskCompletionEligibility.eligible,
              completionSource: taskCompletionEligibility.source,
            })
          : taskCompletionIntents.finishTurn({
              tabId,
              provider: 'claude',
              sessionId: session_id,
              processId: ppid,
              success: event === 'Stop',
            });
        const taskTurnSnapshot = taskTurn?.turn || taskTurn;
        const taskTurnId = taskTurnSnapshot?.generation
          ? 'claude:' + taskTurnSnapshot.generation
          : null;
        if (busy) {
          const sourceId = getTerminalLifecycleGeneration(tabId) + ':claude-provider:' + taskTurnId;
          terminalHistoryPreviewController.activateSemanticSource({
            tabId, provider: 'claude', instanceId: sourceId, processId: ppid || null,
          });
          safelyObserveProviderSemantic('claude-turn-arm', () => providerSemanticShadow.armClaudeTurn({
            tabId,
            sessionId: session_id || null,
            turnId: taskTurnId,
            prompt: submitted_prompt || '',
            sourceId,
          }));
        } else {
          safelyObserveProviderSemantic('claude-turn-finish', () => providerSemanticShadow.finishClaudeTurn({
            tabId,
            reason: 'claude-hook:' + event,
          }));
        }
        if (busy) {
          armClaudeProviderFatalTurnWatch({
            tabId,
            sessionId: session_id || null,
            processId: ppid || null,
            turnId: taskTurnId,
            turnGeneration: taskTurnSnapshot?.generation || null,
            turnStartedAt: taskTurnSnapshot?.startedAt || null,
          });
        } else {
          clearClaudeProviderFatalTurnWatch(tabId, 'claude-hook:' + event);
        }
        if (busy) {
          const promptText = String(submitted_prompt || '');
          if (!promptText.trimStart().startsWith('/')) {
            let transcriptBoundary = null;
            if (typeof transcript_path === 'string' && transcript_path) {
              try { transcriptBoundary = fs.statSync(transcript_path).size; } catch (error) {
                if (error?.code === 'ENOENT') transcriptBoundary = 0;
              }
            }
            terminalHistoryPreviewController.begin({
              tabId,
              provider: 'claude',
              sessionId: session_id || null,
              turnId: taskTurnId,
              promptText,
              processId: ppid || null,
              sourceSequence: eventSeq,
              sourceBoundary: transcriptBoundary,
              promptSource: 'claude-user-prompt-submit-hook',
              promptAuthority: 'exact-lifecycle',
            });
          }
        } else {
          terminalHistoryPreviewController.finish({
            tabId,
            provider: 'claude',
            turnId: taskTurnId,
            reason: event === 'StopFailure' ? 'stop-failure' : 'stop',
          });
        }
        if (busy && promptSubmitAudit) {
          const activeExecutionContext = getActiveAgentExecutionContext(tabId);
          if (activeExecutionContext) {
            promptSubmitAudit.executionContext ||= activeExecutionContext;
          } else {
            promptSubmitAudit.executionContextDiagnostic ||=
              'user-prompt-submit-execution-context-unavailable';
          }
        }
        const taskCompletionMeta = !busy && taskTurn?.explicitTaskComplete === true
          ? {
              explicitTaskComplete: true,
              taskCompletionIntentId: taskTurn.taskCompletionIntentId,
              taskCompletionRequestedAt: taskTurn.taskCompletionRequestedAt,
            }
          : {};
        claudeHookLastEvent.set(tabId, {
          event,
          ts: hookEventTs,
          sessionId: session_id,
          turnId: taskTurnId,
          ...taskCompletionMeta,
        });
        if (busy) {
          // Do not let a spinner frame from the previous turn count as fresh
          // liveness when this turn's watchdog eventually checks the tab.
          claudeSpinnerLastSeenAt.delete(tabId);
        }
        // Clear any stale awaiting-input flag on a turn-end edge (Stop/StopFailure).
        // Normally PostToolUse(AskUserQuestion) already cleared it before Stop, but
        // if the turn died another way (process restart re-emitting, abort) this
        // keeps main's map honest. The renderer enforces awaiting⊆busy on its own
        // busy:false edge regardless; this is just main-side bookkeeping.
        if (!busy && claudeAwaitingInput.get(tabId)) {
          claudeAwaitingInput.set(tabId, false);
          if (mainWindow && !mainWindow.isDestroyed()) {
            mainWindow.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
          }
        }
        // Safety net for mobile: if a question was pending and the turn ended
        // any other way than a clean PostToolUse (e.g. user pressed Esc / declined
        // at the desktop TUI → "Request interrupted", or the process died), clear
        // the stored question and tell mobile to drop its picker. Mirrors the
        // awaiting⊆busy net above so mobile's question card never latches.
        if (!busy && claudePendingQuestion.has(tabId)) {
          claudePendingQuestion.delete(tabId);
          _webBroadcast(tabId, { type: 'question-cancelled', source: 'pty' });
        }
        const latency = ts ? (Date.now() - ts) : null;
        // Detailed log for hung-loader diagnosis: include `prev` explicitly so
        // we can spot "UserPromptSubmit while prev=true" (Claude's submit-interrupt
        // path which skips stopHooks) without re-parsing line context.
        console.log('[ClaudeHook] #' + eventSeq + ' ' + event + ' tab=' + tabId.slice(-12) + ' session=' + session_id.slice(0, 8) + ' prev=' + (prev === undefined ? 'undef' : prev) + ' busy=' + busy + (prev === busy ? ' (no change)' : '') + (latency !== null ? ' latency=' + latency + 'ms' : ''));
        if (internalAgentContinuationKind) {
          console.log('[OrchestrationInternalWork] exact Claude continuation tab='
            + tabId.slice(-12)
            + ' session=' + session_id.slice(0, 8)
            + ' kind=' + internalAgentContinuationKind
            + ' turn=' + String(taskTurnId || '-'));
        }

        // ----- Reuse existing claude:busy-state pipeline -----
        // Stop/StopFailure must force loader off, even if spinner glyph still pulses one last frame.
        // UserPromptSubmit forces it on instantly, before the first spinner frame arrives.
        // Cancel any pending spinner IDLE timer so it can't override our authoritative state.
        clearTimeout(claudeSpinnerIdleTimer.get(tabId));
        claudeSpinnerIdleTimer.delete(tabId);
        const prevSpinner = claudeSpinnerBusy.get(tabId);
        claudeSpinnerBusy.set(tabId, busy);
        const lifecycleReason = (!busy && event === 'StopFailure') ? 'error' : undefined;
        if (!busy && event === 'StopFailure' && claudeLocalCommandWatchers.has(tabId)) {
          completeClaudeLocalCommand(tabId, 'stop-failure');
        }
        if (!busy && event === 'StopFailure') {
          clearClaudePtyCompactProofAttempt(tabId, undefined, 'stop-failure');
        }
        if (mainWindow && !mainWindow.isDestroyed()) {
          // Hook events are the authoritative turn bracket and must always reach
          // workflow consumers. A spinner heuristic may already have written the
          // same boolean into claudeSpinnerBusy; suppressing this event by value
          // would hide the real Stop/StopFailure outcome from PromptQueueRunner.
          mainWindow.webContents.send('claude:busy-state', {
            tabId,
            busy,
            reason: lifecycleReason,
            turnId: taskTurnId,
            outcomeTs: busy ? null : hookEventTs,
            ...taskCompletionMeta,
          });
        }
        // Mirror busy-state to any mobile-web subscribers of this PTY+Claude
        // tab — otherwise phone composer never learns Claude is processing
        // and a Send during turn races with the previous prompt's JSONL write.
        // This hook edge is authoritative and must be published even when the
        // presentation spinner already wrote the same boolean. Orchestration
        // requires the matching start edge before it can accept a later done.
        // (SDK tabs already have their own webBroadcast path in sdkStartQuery.)
        console.log('[MobBcast] busy tab=' + String(tabId).slice(-12)
          + ' busy=' + busy
          + ' src=claude-hook'
          + ' prevSpinner=' + (prevSpinner === undefined ? 'undef' : prevSpinner));
        _webBroadcast(tabId, {
          type: 'busy',
          busy,
          reason: lifecycleReason,
          provider: 'claude',
          sessionId: session_id || null,
          turnId: taskTurnId,
          processId: ppid || null,
          turnGeneration: taskTurnSnapshot?.generation || null,
          turnStartedAt: taskTurnSnapshot?.startedAt || null,
          internalAgentContinuation: internalAgentContinuationKind || null,
          backgroundWorkCount: getCombinedTabBackgroundWorkCount(tabId),
        });
        if (busy && getClaudePtyRuntimePresence(tabId).inputReady === true) {
          emitAgentReadinessChanged(tabId, {
            toolType: 'claude',
            source: 'turn-lifecycle',
            status: 'ready',
            reason: 'UserPromptSubmit',
          });
        }
        if (!busy) {
          _webBroadcast(tabId, {
            type: 'done',
            sessionId: session_id,
            reason: lifecycleReason,
            provider: 'claude',
            turnId: taskTurnId,
            processId: ppid || null,
            turnGeneration: taskTurnSnapshot?.generation || null,
            turnStartedAt: taskTurnSnapshot?.startedAt || null,
            backgroundWorkCount: getCombinedTabBackgroundWorkCount(tabId),
          });
        }
        // Activity tracking — authoritative turn edges (idempotent recorder).
        recordActivity(tabId, busy, 'claude', {
          responseTimingEligible: busy
            ? event === 'UserPromptSubmit'
            : shouldCreateHistoryResponseTiming({ toolType: 'claude', event }),
          reason: event,
        });

        // Watchdog — if Stop never fires (silent tool stop bug #29881, hook script crash, etc.)
        // fall back to busy=false after CLAUDE_TURN_WATCHDOG_MS so the loader doesn't hang forever.
        clearTimeout(claudeTurnWatchdog.get(tabId));
        claudeTurnWatchdog.delete(tabId);
        // Start/stop the JSONL interruption watcher on this UserPromptSubmit/Stop edge.
        // See claudeInterruptWatchers below — turn-start arms it, turn-end disarms it.
        if (busy) {
          startInterruptWatcher(tabId, session_id, transcript_path);
        } else {
          stopInterruptWatcher(tabId);
        }
        if (busy) {
          scheduleClaudeTurnWatchdog(tabId, session_id);
        }

        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('claude:turn-state', {
            tabId,
            sessionId: session_id,
            event,
            busy,
            success: event !== 'StopFailure',
            lastAssistantMessage: last_assistant_message || null,
            turnId: taskTurnId,
            ...taskCompletionMeta,
          });
        }
      }
    });
    sock.on('error', (e) => { if (e.code !== 'EPIPE') console.warn('[ClaudeHook:Conn] err seq=' + connId + ':', e.message); });
    sock.on('close', () => {
      // Lifecycle close — pairs every "open seq=N" with "close seq=N bytes=X
      // lines=Y dur=Zms". Diff between open/close count and event count
      // reveals silent-dropout where server accepts but doesn't read.
      console.log('[ClaudeHook:Conn] close seq=' + connId + ' bytes=' + dataBytes + ' lines=' + lines + ' dur=' + (Date.now() - tConnect) + 'ms');
      if (buf.trim()) {
        console.warn('[ClaudeHook] INCOMPLETE_ENVELOPE conn=' + connId
          + ' parsedLines=' + lines + ' bufferedChars=' + buf.length
          + ' reason=peer-closed-before-newline');
      }
    });
  });
  claudeHookServer.on('error', (e) => { console.error('[ClaudeHook] server err:', e.message); });
  claudeHookServer.on('close', () => { console.warn('[ClaudeHook] server CLOSED (unexpected)'); });
  claudeHookServer.listen(CLAUDE_HOOK_SOCK, () => {
    try { fs.chmodSync(CLAUDE_HOOK_SOCK, 0o600); } catch {}
    console.log('[ClaudeHook] Listening on ' + CLAUDE_HOOK_SOCK + ' (pid=' + process.pid + ')');
    writeClaudeHookDiscovery();
  });

  // Legacy listener — second net.Server bound to the old fixed path. Old hook
  // scripts (without discovery support) connect there. We bind ONLY if no
  // other instance owns it; if a sibling already binds, we silently skip and
  // rely on the per-PID path.
  //
  // CRITICAL: do NOT unconditionally unlink the legacy socket file before
  // listen — that's exactly the #83 bug (clobber sibling's listener). Path:
  //   1. try listen(...)
  //   2. on EADDRINUSE → probe-connect. If `connect` succeeds → sibling alive,
  //      leave the path to them, do nothing.
  //   3. on probe ECONNREFUSED → file is orphan (dead listener), unlink + retry.
  // Net result: only the first live instance claims legacy; orphan stays
  // cleaned up automatically for the next startup.
  bindLegacyHookServer();
  claudeHookLegacyServer = currentLegacyServer;
}

// Reference held outside so bindLegacyHookServer can recreate the server on
// EADDRINUSE-after-cleanup retry without losing the handle.
let currentLegacyServer = null;
function bindLegacyHookServer(attempt = 0) {
  const server = net.createServer((sock) => {
    if (claudeHookServer) claudeHookServer.emit('connection', sock);
    else { try { sock.destroy(); } catch {} }
  });
  currentLegacyServer = server;
  server.on('error', (e) => {
    if (e.code === 'EADDRINUSE') {
      if (attempt >= 1) { /* already retried — give up silently */ return; }
      // Probe: is there a live listener, or just orphan socket file?
      const probe = net.createConnection(CLAUDE_HOOK_SOCK_LEGACY);
      const probeFinish = (orphan) => {
        try { probe.destroy(); } catch {}
        if (orphan) {
          try { fs.unlinkSync(CLAUDE_HOOK_SOCK_LEGACY); } catch {}
          bindLegacyHookServer(attempt + 1);
        }
        // else: sibling is alive, leave legacy path to them
      };
      probe.once('connect', () => probeFinish(false));
      probe.once('error', (err) => probeFinish(err && err.code === 'ECONNREFUSED'));
    } else {
      console.warn('[ClaudeHook:Legacy] err:', e.message);
    }
  });
  try {
    server.listen(CLAUDE_HOOK_SOCK_LEGACY, () => {
      try { fs.chmodSync(CLAUDE_HOOK_SOCK_LEGACY, 0o600); } catch {}
      console.log('[ClaudeHook:Legacy] Also listening on ' + CLAUDE_HOOK_SOCK_LEGACY + (attempt > 0 ? ' (after orphan cleanup)' : ''));
    });
  } catch (e) { console.warn('[ClaudeHook:Legacy] listen failed:', e.message); }
}

let claudeHookLegacyServer = null;

// Discovery file: `~/.noted-terminal/claude-hook-<pid>.json` with the socket
// path + open project cwds + isPackaged flag. The hook script reads all such
// files at fire-time and picks the right instance by matching the Claude
// process' cwd against openProjectPaths (longest-prefix), same algorithm as
// MCP routing. See fact-mcp-routing.md for the parallel pattern.
function writeClaudeHookDiscovery() {
  try {
    fs.mkdirSync(CLAUDE_HOOK_DISCOVERY_DIR, { recursive: true });
    // Reuse the open-project-paths list maintained for MCP routing.
    const openProjectPaths = (typeof mcpOpenProjectPaths !== 'undefined' && Array.isArray(mcpOpenProjectPaths)) ? mcpOpenProjectPaths : [];
    fs.writeFileSync(CLAUDE_HOOK_DISCOVERY_FILE, JSON.stringify({
      sock: CLAUDE_HOOK_SOCK,
      pid: process.pid,
      isPackaged: app.isPackaged,
      openProjectPaths,
      updatedAt: Date.now(),
    }));
  } catch (e) { console.warn('[ClaudeHook:Discovery] write failed:', e.message); }
}

// Re-publish discovery whenever the set of open projects changes (same hook
// the MCP discovery file uses). Wired below in the MCP discovery updater.
function refreshClaudeHookDiscovery() { writeClaudeHookDiscovery(); }

function stopClaudeHookServer() {
  if (claudeHookServer) {
    try { claudeHookServer.close(); } catch {}
    claudeHookServer = null;
  }
  if (claudeHookLegacyServer) {
    try { claudeHookLegacyServer.close(); } catch {}
    claudeHookLegacyServer = null;
  }
  try { fs.unlinkSync(CLAUDE_HOOK_SOCK); } catch {}
  try { fs.unlinkSync(CLAUDE_HOOK_DISCOVERY_FILE); } catch {}
}

// Periodic compact snapshot of Claude per-tab state. Only logs when at least
// one tab is busy or has a recent hook event — otherwise silent. The line is
// dense by design: one rolling row per session window so when the user reports
// "loader hung at HH:MM" we have a state photo within 30s of that time
// without needing a fresh repro. Counters at end: conn/event seq + delta
// (delta=0 between snapshots = bridge is silent, very strong signal).
let _lastSnapshotConn = 0;
let _lastSnapshotEvent = 0;
function logPeriodicClaudeSnapshot() {
  const now = Date.now();
  const rows = [];
  const allTabs = new Set([
    ...claudeTurnBusy.keys(),
    ...claudeSpinnerBusy.keys(),
    ...claudeHookLastEvent.keys(),
    ...claudeLocalCommandWatchers.keys(),
  ]);
  for (const tabId of allTabs) {
    const turnBusy = claudeTurnBusy.get(tabId) === true;
    const spinnerBusy = claudeSpinnerBusy.get(tabId) === true;
    const last = claudeHookLastEvent.get(tabId);
    const local = claudeLocalCommandWatchers.get(tabId);
    const lastAgo = last ? Math.round((now - last.ts) / 1000) : null;
    // Skip rows that are completely cold (no busy state + no recent hook)
    if (!turnBusy && !spinnerBusy && !local && (lastAgo === null || lastAgo > 300)) continue;
    rows.push(
      tabId.slice(-12) +
      ' turn=' + (turnBusy ? '1' : '0') +
      ' spin=' + (spinnerBusy ? '1' : '0') +
      (last ? ' last=' + last.event + ':' + lastAgo + 's' : ' last=none') +
      (local ? ' local=' + local.command + ':' + Math.round((now - local.startedAt) / 1000) + 's' : '') +
      (claudeTurnWatchdog.has(tabId) ? ' wd' : '') +
      (claudeInterruptWatchers.has(tabId) ? ' iw' : '')
    );
  }
  const dConn = claudeHookConnSeq - _lastSnapshotConn;
  const dEvent = claudeHookEventSeq - _lastSnapshotEvent;
  _lastSnapshotConn = claudeHookConnSeq;
  _lastSnapshotEvent = claudeHookEventSeq;
  // Silent when nothing is happening; print counters anyway if there was hook
  // activity in the window, to surface "conn but no events" (silent dropout).
  if (rows.length === 0 && dConn === 0 && dEvent === 0) return;
  console.log('[ClaudeSnapshot] tabs=' + rows.length + ' Δconn=' + dConn + ' Δevent=' + dEvent + ' totalConn=' + claudeHookConnSeq + ' totalEvent=' + claudeHookEventSeq + (rows.length ? ' | ' + rows.join(' || ') : ''));
}
setInterval(logPeriodicClaudeSnapshot, 30 * 1000).unref();

// Shell integration directory (for OSC 7 cwd reporting + OSC 133 command lifecycle)
const shellIntegrationDir = path.join(app.getPath('userData'), 'shell-integration');

// Create shell integration files on startup
function setupShellIntegration() {
  // Create directory
  if (!fs.existsSync(shellIntegrationDir)) {
    fs.mkdirSync(shellIntegrationDir, { recursive: true });
  }

  // Zsh integration - .zshrc that loads user's config and adds OSC 7 + OSC 133
  // IMPORTANT: Use \033 (octal) for ESC and \007 for BEL - \e doesn't work reliably
  const zshIntegration = `# Noted Terminal Shell Integration
# This file is auto-generated - do not edit

# Capture our injected EDITOR/VISUAL BEFORE sourcing user's .zshrc — many user
# configs unconditionally export EDITOR=subl/vim/code, which would clobber the
# editor we wired up for Claude's chat:externalEditor (Prompt Queue grab feature).
__ct_injected_editor="$EDITOR"
__ct_injected_visual="$VISUAL"

# Load user's original .zshrc
if [[ -f "$HOME/.zshrc" ]]; then
  ZDOTDIR="$HOME" source "$HOME/.zshrc"
fi

# Capture user's real EDITOR (after their zshrc runs) so our helper can passthrough
# when no lock-file is set (user pressed Ctrl+G manually expecting their editor).
# Only do this if the user's zshrc actually set something non-trivial.
if [[ -n "$EDITOR" && "$EDITOR" != *noted-code-grab* ]]; then
  export NOTED_ORIGINAL_EDITOR="$EDITOR"
fi

# Restore our editor injection if the user's .zshrc clobbered it.
# Only override when we actually injected something AND the path points at our hook helper.
if [[ -n "$__ct_injected_editor" && "$__ct_injected_editor" == *noted-code-grab* ]]; then
  export EDITOR="$__ct_injected_editor"
fi
if [[ -n "$__ct_injected_visual" && "$__ct_injected_visual" == *noted-code-grab* ]]; then
  export VISUAL="$__ct_injected_visual"
fi
unset __ct_injected_editor __ct_injected_visual

# OSC 7 - Report current directory to terminal
__ct_osc7() {
  printf "\\033]7;file://%s%s\\033\\\\" "$HOST" "$PWD"
}

# ============ OSC 133 - Command Lifecycle (VS Code protocol) ============
# A - Prompt started
# B - Command started (after user presses Enter)
# C - Command executing
# D;exit_code - Command finished with exit code

__ct_precmd() {
  local ret=$?
  # Command finished (D)
  printf "\\033]133;D;%s\\007" "$ret"
  # Report cwd
  printf "\\033]7;file://%s%s\\033\\\\" "$HOST" "$PWD"
  # Prompt starting (A)
  printf "\\033]133;A\\007"
}

${AGENT_SHELL_TOOL_CLASSIFIER}

__ct_preexec() {
  local __ct_tool="$(__ct_agent_tool "$1")"
  # Command started (B)
  if [[ -n "$__ct_tool" ]]; then
    printf "\\033]133;B;tool=%s\\007" "$__ct_tool"
  else
    printf "\\033]133;B\\007"
  fi
  # Command executing (C)
  printf "\\033]133;C\\007"
}

# Install hooks
autoload -Uz add-zsh-hook 2>/dev/null
add-zsh-hook precmd __ct_precmd
add-zsh-hook preexec __ct_preexec

# Send initial prompt
printf "\\033]133;A\\007"
`;

  // Bash integration - use \033 (octal) for ESC
  const bashIntegration = `# Noted Terminal Shell Integration
# This file is auto-generated - do not edit

# Capture our injected EDITOR/VISUAL before user's bashrc clobbers them
__ct_injected_editor="$EDITOR"
__ct_injected_visual="$VISUAL"

# Load user's original .bashrc
if [[ -f "$HOME/.bashrc" ]]; then
  source "$HOME/.bashrc"
fi

# Restore our editor injection
if [[ -n "$__ct_injected_editor" && "$__ct_injected_editor" == *noted-code-grab* ]]; then
  export EDITOR="$__ct_injected_editor"
fi
if [[ -n "$__ct_injected_visual" && "$__ct_injected_visual" == *noted-code-grab* ]]; then
  export VISUAL="$__ct_injected_visual"
fi
unset __ct_injected_editor __ct_injected_visual

__ct_in_command=0

__ct_prompt_command() {
  local ret=$?
  if [[ "$__ct_in_command" == "1" ]]; then
    # Command finished (D)
    printf "\\033]133;D;%s\\007" "$ret"
    __ct_in_command=0
  fi
  # Report cwd (OSC 7)
  printf "\\033]7;file://%s%s\\033\\\\" "$HOSTNAME" "$PWD"
  # Prompt starting (A)
  printf "\\033]133;A\\007"
}

${AGENT_SHELL_TOOL_CLASSIFIER}

__ct_preexec() {
  local __ct_command="$1"
  if [[ "$__ct_command" != "__ct_prompt_command" && "$__ct_in_command" == "0" ]]; then
    local __ct_tool="$(__ct_agent_tool "$__ct_command")"
    # Command started (B) + executing (C)
    if [[ -n "$__ct_tool" ]]; then
      printf "\\033]133;B;tool=%s\\007" "$__ct_tool"
    else
      printf "\\033]133;B\\007"
    fi
    printf "\\033]133;C\\007"
    __ct_in_command=1
  fi
}

PROMPT_COMMAND="__ct_prompt_command"
trap '__ct_preexec "$BASH_COMMAND"' DEBUG

# Initial prompt
printf "\\033]133;A\\007"
`;

  // Write integration files
  fs.writeFileSync(path.join(shellIntegrationDir, '.zshrc'), zshIntegration);
  fs.writeFileSync(path.join(shellIntegrationDir, '.bashrc'), bashIntegration);

  console.log('[Shell Integration] Created at:', shellIntegrationDir);
}

function clearCodexDescendantExitRecheck(tabId, reason = 'clear') {
  if (!tabId || !codexDescendantExitRecheckTimers.has(tabId)) return;
  clearTimeout(codexDescendantExitRecheckTimers.get(tabId));
  codexDescendantExitRecheckTimers.delete(tabId);
  console.log('[CodexExitRecheck] clear tab=' + String(tabId).slice(-12) + ' reason=' + reason);
}

function clearCodexFinishDebounce(tabId, reason = 'clear') {
  if (!tabId || !codexFinishDebounceTimers.has(tabId)) return;
  clearTimeout(codexFinishDebounceTimers.get(tabId));
  codexFinishDebounceTimers.delete(tabId);
  console.log('[CodexFinishDebounce] clear tab=' + String(tabId).slice(-12) + ' reason=' + reason);
}

function getCodexExitObserverGeneration(tabId) {
  return Number(codexExitObserverGenerations.get(tabId) || 0);
}

function getCodexWriterObservationGeneration(tabId) {
  return Number(codexWriterObservationGenerations.get(tabId) || 0);
}

function invalidateCodexWriterObservations(tabId, reason = 'invalidate') {
  if (!tabId) return 0;
  if (codexProvisionalSourceObservations.delete(tabId)) {
    console.log('[CodexLaunchObservation] provisional source invalidated tab='
      + String(tabId).slice(-12)
      + ' reason=' + reason);
  }
  const generation = getCodexWriterObservationGeneration(tabId) + 1;
  codexWriterObservationGenerations.set(tabId, generation);
  console.log('[CodexWriterObservation] invalidate tab=' + String(tabId).slice(-12)
    + ' generation=' + generation
    + ' reason=' + reason);
  return generation;
}

function invalidateCodexExitObservers(tabId, reason = 'invalidate') {
  if (!tabId) return 0;
  const generation = getCodexExitObserverGeneration(tabId) + 1;
  codexExitObserverGenerations.set(tabId, generation);
  clearCodexFinishDebounce(tabId, reason);
  clearCodexDescendantExitRecheck(tabId, reason);
  console.log('[CodexExitObserver] invalidate tab=' + String(tabId).slice(-12)
    + ' generation=' + generation + ' reason=' + reason);
  return generation;
}

function isCodexExitObserverCurrent(tabId, expectedGeneration, expectedRunSeq = null) {
  if (aiStoppingTabs.get(tabId)?.toolType === 'codex') return false;
  if (expectedGeneration !== null
    && getCodexExitObserverGeneration(tabId) !== Number(expectedGeneration)) return false;
  if (expectedRunSeq !== null
    && Number(terminalCommandState.get(tabId)?.runSeq || 0) !== Number(expectedRunSeq)) return false;
  return true;
}

function finalizeCodexCommandFinished(tabId, exitCode = 0, reason = 'command-finished') {
  if (!tabId) return;
  clearCodexDescendantExitRecheck(tabId, reason);
  clearCodexFinishDebounce(tabId, reason);

  const prevState = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: exitCode };
  const wasRunning = prevState.isRunning === true;
  terminalCommandState.set(tabId, {
    ...prevState,
    isRunning: false,
    lastExitCode: Number.isFinite(Number(exitCode)) ? Number(exitCode) : 0,
  });
  clearTerminalCommandOrigin(tabId, terminalCommandState.get(tabId), reason);

  if (activityOpenIntervals.get(tabId)?.engine === 'codex') {
    recordActivity(tabId, false, 'codex');
  }
  // The caller reached this boundary only after a force-fresh absence proof.
  // Drop every pre-exit process-tree observation before publishing inactive;
  // otherwise the next status read can reuse a snapshot that still contains
  // the dead Codex descendant and resurrect the tab as STARTING.
  retireAgentInputCaptureForProcess(tabId, 'codex', reason);
  invalidateProcessTreeSnapshot('codex-exit:' + reason);
  invalidateAiProcessLookupCache(tabId, 'codex');
  clearCodexLaunchPayload(tabId, reason);
  clearCodexKnownSession(tabId, reason);
  clearCodexTuiReady(tabId, reason);
  closeCodexWatcher(tabId, reason);
  closeCodexTurnWatcher(tabId, reason);
  broadcastAiRuntimeStatus(tabId, 'codex', 'inactive', reason);

  console.log('[CodexExitRecheck] finalized tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' wasRunning=' + wasRunning
    + ' exitCode=' + (Number.isFinite(Number(exitCode)) ? Number(exitCode) : 0));

  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:command-finished', {
      tabId,
      exitCode: Number.isFinite(Number(exitCode)) ? Number(exitCode) : 0,
      reason,
      commandType: 'codex',
    });
  }
}

async function keepCodexRuntimeAliveFromProcessProof(tabId, matches, reason, {
  emitCommandStarted = false,
  expectedObserverGeneration = null,
  expectedRunSeq = null,
} = {}) {
  if (!tabId || !Array.isArray(matches) || matches.length === 0) return false;
  if (expectedObserverGeneration !== null
    && !isCodexExitObserverCurrent(tabId, expectedObserverGeneration, expectedRunSeq)) {
    console.log('[CodexRuntimeRecovery] stale proof ignored tab=' + String(tabId).slice(-12)
      + ' reason=' + reason + ' generation=' + expectedObserverGeneration);
    return false;
  }
  const state = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
  const wasRunning = state.isRunning === true;
  state.isRunning = true;
  terminalCommandState.set(tabId, state);
  aiProcessLookupCache.set(aiProcessLookupCacheKey(tabId, 'codex'), {
    at: nodePerformance.now(),
    matches,
  });

  // Process existence proves lifecycle only. Resolve the rollout held open by
  // that descendant before repairing session identity; DB/launch IDs are merely
  // resume intent and may be stale after native Codex rewind.
  const writer = await reconcileCodexWriterFromProcess(tabId, {
    reason: reason + '-writer-proof',
    sender: mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    expectedExitObserverGeneration: expectedObserverGeneration,
    expectedExitObserverRunSeq: expectedRunSeq,
  });
  if (expectedObserverGeneration !== null
    && !isCodexExitObserverCurrent(tabId, expectedObserverGeneration, expectedRunSeq)) {
    console.log('[CodexRuntimeRecovery] stale proof discarded after writer lookup tab=' + String(tabId).slice(-12)
      + ' reason=' + reason + ' generation=' + expectedObserverGeneration);
    return false;
  }
  const sessionId = writer?.status === 'adopted'
    ? (getCodexWriterProofSnapshot(tabId)?.sessionId || null)
    : null;
  if (sessionId && !codexTurnWatchers.has(tabId)) {
    try {
      await ensureCodexTurnWatcher(tabId, sessionId, terminalProjects.get(tabId), {
        catchUpReason: reason,
      });
    } catch (err) {
      // Process proof still repairs lifecycle truth even if the auxiliary JSONL
      // watcher cannot be reattached. Keep the failure observable for a later
      // poll instead of converting a live process back into an inactive state.
      console.warn('[CodexRuntimeRecovery] watcher reattach failed tab=' + String(tabId).slice(-12)
        + ' reason=' + reason
        + ' error=' + (err?.message || String(err)));
    }
  }
  if (emitCommandStarted && !wasRunning && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:command-started', { tabId, commandType: 'codex', reason });
  }
  return true;
}

function armCodexDescendantExitRecheck(
  tabId,
  exitCode = 0,
  reason = 'codex-descendant-alive',
  expectedRunSeq = null,
  expectedObserverGeneration = null,
) {
  if (!tabId || _gracefulShutdownInProgress) return;
  clearCodexDescendantExitRecheck(tabId, 'replace:' + reason);
  const startedAt = Date.now();
  const runSeq = expectedRunSeq ?? Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const observerGeneration = expectedObserverGeneration ?? getCodexExitObserverGeneration(tabId);
  let attempt = 0;
  console.warn('[CodexExitRecheck] arm tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' exitCode=' + (Number.isFinite(Number(exitCode)) ? Number(exitCode) : 0)
    + ' runSeq=' + runSeq
    + ' generation=' + observerGeneration);

  const schedule = (delayMs) => {
    const timer = setTimeout(async () => {
      codexDescendantExitRecheckTimers.delete(tabId);
      if (_gracefulShutdownInProgress || !terminals.has(tabId)) {
        console.log('[CodexExitRecheck] stop tab=' + String(tabId).slice(-12)
          + ' reason=' + (_gracefulShutdownInProgress ? 'shutdown' : 'no-terminal'));
        return;
      }
      if (!isCodexExitObserverCurrent(tabId, observerGeneration, runSeq)) {
        console.log('[CodexExitRecheck] stop tab=' + String(tabId).slice(-12)
          + ' reason=stale-observer runSeq=' + runSeq
          + ' generation=' + observerGeneration
          + ' currentRunSeq=' + Number(terminalCommandState.get(tabId)?.runSeq || 0));
        return;
      }

      attempt += 1;
      const lookup = await inspectAiDescendantProcessesByTab(tabId, 'codex', { forceFresh: true });
      if (!isCodexExitObserverCurrent(tabId, observerGeneration, runSeq)) {
        console.log('[CodexExitRecheck] stop tab=' + String(tabId).slice(-12)
          + ' reason=stale-observer-after-lookup runSeq=' + runSeq
          + ' generation=' + observerGeneration
          + ' currentRunSeq=' + Number(terminalCommandState.get(tabId)?.runSeq || 0));
        return;
      }
      const decision = decideCodexExitProbe(lookup);
      if (decision === 'retry') {
        console.warn('[CodexExitRecheck] lookup failed tab=' + String(tabId).slice(-12)
          + ' attempt=' + attempt
          + ' action=preserve-and-retry'
          + ' error=' + (lookup.error?.message || lookup.error || 'unknown'));
        schedule(Math.min(5000, 250 * Math.max(1, attempt + 1)));
        return;
      }

      if (decision === 'finalize') {
        finalizeCodexCommandFinished(tabId, exitCode, 'codex-descendants-exited');
        return;
      }

      const liveCodex = lookup.matches;
      const keptAlive = await keepCodexRuntimeAliveFromProcessProof(tabId, liveCodex, 'codex-exit-recheck-alive', {
        expectedObserverGeneration: observerGeneration,
        expectedRunSeq: runSeq,
      });
      if (!keptAlive) return;
      const ageMs = Date.now() - startedAt;
      const nextMs = Math.min(5000, 250 * Math.max(1, attempt + 1));
      if (attempt === 1 || attempt % 8 === 0) {
        console.warn('[CodexExitRecheck] still-alive tab=' + String(tabId).slice(-12)
          + ' matches=' + liveCodex.length
          + ' attempt=' + attempt
          + ' ageMs=' + ageMs
          + ' nextMs=' + nextMs
          + ' live=' + JSON.stringify(liveCodex.slice(0, 4).map((p) => String(p.pid || '?') + ':' + String(p.command || p.cmd || '').slice(0, 80)).join(' | ')));
      }
      schedule(nextMs);
    }, Math.max(100, delayMs));
    codexDescendantExitRecheckTimers.set(tabId, timer);
  };

  schedule(500);
}

// Parse OSC 133 sequences and emit events
// OSC 133 format: \x1b]133;X\x07 or \x1b]133;X;param\x07
// X can be: A (prompt start), B (command start), C (executing), D;exitcode (finished)
function parseOSC133AndEmit(tabId, data, terminalToken = null) {
  // Regex to match OSC 133 sequences
  // \x1b] = ESC ]
  // 133; = OSC 133
  // ([A-D]) = command type
  // (;[^]*?)? = optional params (like exit code for D)
  // [\x07\x1b\\] = terminator (BEL or ST)
  const osc133Regex = /\x1b\]133;([A-D])(;[^\x07\x1b]*)?(?:\x07|\x1b\\)/g;

  let match;
  while ((match = osc133Regex.exec(data)) !== null) {
    const type = match[1];
    const param = match[2] ? match[2].slice(1) : null; // Remove leading ';'

    const state = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };

    switch (type) {
      case 'A': // Prompt start - shell is waiting for input
        console.log(`[OSC 133] Tab ${tabId}: Prompt ready (A)`);
        terminalShellReadiness.markPromptReady(
          tabId,
          terminalToken,
          terminalToken?.pid,
        );
        const promptReadiness = terminalShellReadiness.snapshot(tabId, terminalToken);
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('terminal:prompt-ready', tabId, promptReadiness);
        }
        // Internal event for terminal:create initialCommand dispatch — fires on first A,
        // listener self-removes after one match. Decoupled from the renderer-facing IPC.
        ipcMain.emit('terminal:prompt-ready-internal', null, tabId);
        break;

      case 'B': { // Command start - user pressed Enter
        terminalShellReadiness.markCommandBoundary(tabId, terminalToken);
        const oscAgentTool = parseOsc133AgentTool(param);
        console.log(`[OSC 133] Tab ${tabId}: Command STARTED (B)`
          + (oscAgentTool ? ` tool=${oscAgentTool}` : ''));
        console.warn(`[RunAfterDiag] B tab=${tabId.slice(-8)} claudeCliActive=${claudeCliActive.has(tabId)} spinnerBusy=${claudeSpinnerBusy.get(tabId) === true}`);
        {
          const currentTerminal = terminals.get(tabId) || null;
          const startupIntent = claudeStartupIntents.get(tabId) || null;
          const hasMatchingStartupIntent = !!startupIntent
            && startupIntent.terminalToken === currentTerminal
            && (!terminalToken || startupIntent.terminalToken === terminalToken);
          const manualClaudeClaim = shouldClaimManualClaudeShellLaunch({
            oscTool: oscAgentTool,
            hasMatchingStartupIntent,
          });
          if (manualClaudeClaim.claim) {
            const staleDebounce = claudeDebounceTimers.get(tabId);
            if (staleDebounce) clearTimeout(staleDebounce);
            claudeDebounceTimers.delete(tabId);
            // A raw shell launch has no renderer-owned pending prompt. Never let
            // a failed older launch inject its stale prompt into this process.
            claudePendingPrompt.delete(tabId);
            claudeState.set(tabId, 'WAITING_PROMPT');
            const launchGeneration = markClaudeShellLaunchStarted(
              tabId,
              null,
              'claude-shell-osc',
              {
                expectsInterruptPrelude: false,
                sawOscCommandStart: true,
                // The generic OSC-B event below is the one renderer event.
                emitCommandStarted: false,
              },
            );
            console.log('[AgentShellLaunch] manual-claim tab=' + String(tabId).slice(-12)
              + ' tool=claude gen=' + launchGeneration
              + ' source=osc-133');
          }
          const activeStartupIntent = claudeStartupIntents.get(tabId);
          if (
            activeStartupIntent
            && activeStartupIntent.terminalToken === currentTerminal
            && (!terminalToken || activeStartupIntent.terminalToken === terminalToken)
          ) {
            activeStartupIntent.sawOscCommandStart = true;
          }
        }
        clearClaudeEditableLastPrompt(tabId, 'osc-command-started');
        if (codexFinishDebounceTimers.has(tabId)) {
          clearTimeout(codexFinishDebounceTimers.get(tabId));
          codexFinishDebounceTimers.delete(tabId);
          console.warn('[CodexTurn] suppress command-finished tab=' + tabId.slice(-8) + ' reason=osc-d-followed-by-b');
        }
        clearCodexDescendantExitRecheck(tabId, 'osc-b');
        state.isRunning = true;
        const preclaimedGeneration = codexPreclaimedCommandGenerations.get(tabId) || null;
        const generationAdvance = advanceOscCommandGeneration({
          runSeq: Number(state.runSeq || 0),
          preclaimedRunSeq: preclaimedGeneration?.runSeq,
          sameTerminal: !!preclaimedGeneration
            && terminals.get(tabId) === preclaimedGeneration.terminalToken,
          sameLaunch: !!preclaimedGeneration
            && codexLastRunCommandPayload.get(tabId)?.launchId === preclaimedGeneration.launchId,
        });
        if (!generationAdvance.consumed) {
          clearCodexServiceTierLaunchCandidate(tabId, 'shell-command-generation-started');
        }
        if (preclaimedGeneration) codexPreclaimedCommandGenerations.delete(tabId);
        state.runSeq = generationAdvance.runSeq;
        if (generationAdvance.consumed) {
          console.log('[CodexGeneration] first OSC-B confirmed preclaimed launch generation tab='
            + String(tabId).slice(-12)
            + ' runSeq=' + state.runSeq
            + ' launch=' + String(preclaimedGeneration?.launchId || '-'));
        }
        applyTerminalCommandStartMeta(tabId, state);
        const startedAt = Date.now();
        const freshLastCommand = state.lastCommand && (!state.lastCommandAt || startedAt - state.lastCommandAt < 15000)
          ? state.lastCommand
          : '';
        rememberTerminalCommandRun(
          tabId,
          state.activeCommand || freshLastCommand || terminalInitialCommand.get(tabId) || '',
          state.activeCommandSource || 'shell',
          startedAt
        );
        terminalCommandState.set(tabId, state);
        if (getCodexWriterProofSnapshot(tabId)) {
          // A shell command boundary starts a new PTY command generation. The
          // previous Codex identity remains the durable History binding, but
          // it is no longer proof of the process now owning this terminal. In
          // particular, ArrowUp + Enter may have launched an unrelated fork;
          // Escape must wait for that runtime writer to be identified instead
          // of arming Rewind against the old saved session.
          invalidateCodexWriterProof(tabId, 'shell-command-generation-started');
          invalidateCodexWriterObservations(tabId, 'shell-command-generation-started');
        }
        if (oscAgentTool === 'codex') {
          rearmCodexProcessActionBoundary(tabId, 'osc-command-started');
        }
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('terminal:command-started', {
            tabId,
            commandType: oscAgentTool || undefined,
          });
        }
        break;
      }

      case 'C': // Command executing
        terminalShellReadiness.markCommandBoundary(tabId, terminalToken);
        console.log(`[OSC 133] Tab ${tabId}: Executing (C)`);
        // Already handled by B
        break;

      case 'D': // Command finished
        // OSC D is only a candidate exit for Codex. During TUI redraws the shell
        // can emit D while the Codex descendant is still alive. Keep the last
        // confirmed lifecycle state until a successful process-tree snapshot
        // proves the descendant set is empty; a failed snapshot is UNKNOWN, not
        // evidence that Codex exited.
        const wasRunningBeforeD = state.isRunning === true;
        const runSeqAtD = Number(state.runSeq || 0);
        const exitCodeAtD = param ? parseInt(param, 10) : 0;
        console.log(`[OSC 133] Tab ${tabId}: Command FINISHED (D) exitCode=${exitCodeAtD}`);
        {
          const startupIntent = claudeStartupIntents.get(tabId);
          const sameTerminal = !!startupIntent
            && startupIntent.terminalToken === terminals.get(tabId)
            && (!terminalToken || startupIntent.terminalToken === terminalToken);
          if (isAgentShellLaunchInterruptPrelude({
            exitCode: exitCodeAtD,
            expectsInterruptPrelude: startupIntent?.expectsInterruptPrelude === true,
            sawOscCommandStart: startupIntent?.sawOscCommandStart === true,
            sameTerminal,
          })) {
            console.warn('[AgentShellLaunch] suppress interrupt prelude command-finished tab='
              + String(tabId).slice(-12)
              + ' exitCode=' + exitCodeAtD
              + ' runSeq=' + runSeqAtD
              + ' reason=' + (startupIntent?.reason || '-'));
            break;
          }
        }
        state.lastExitCode = exitCodeAtD;
        clearClaudeEditableLastPrompt(tabId, 'osc-command-finished');
        // [RunAfterDiag] Correlate D markers with Claude liveness. If a D fires
        // while claudeCliActive/claudeSpinnerBusy is true, the shell is claiming
        // "command finished" while Claude is actually still running → alive flips
        // false → Run-after overlay wrongly hides mid-answer. prevRunning shows
        // whether this is a real transition or a duplicate D.
        console.warn(`[RunAfterDiag] D tab=${tabId.slice(-8)} exit=${state.lastExitCode} prevRunning=${wasRunningBeforeD} claudeCliActive=${claudeCliActive.has(tabId)} spinnerBusy=${claudeSpinnerBusy.get(tabId) === true} turnBusy=${claudeTurnBusy.get(tabId) === true} hasState=${claudeState.has(tabId)} hasPending=${claudePendingPrompt.has(tabId)}`);
        const isCodexTab = codexLastRunCommandPayload.has(tabId)
          || codexKnownSessions.has(tabId)
          || codexTurnWatchers.has(tabId)
          || codexWatchers.has(tabId)
          || codexSessionDiscoveryIntents.has(tabId)
          || codexTuiReadyTabs.has(tabId)
          || activityOpenIntervals.get(tabId)?.engine === 'codex';
        if (isCodexTab && !_gracefulShutdownInProgress) {
          if (aiStoppingTabs.get(tabId)?.toolType === 'codex') {
            console.log('[CodexTurn] ignore OSC-D observer during explicit Stop tab=' + tabId.slice(-8));
            break;
          }
          clearCodexFinishDebounce(tabId, 'osc-d');
          clearCodexDescendantExitRecheck(tabId, 'osc-d');
          const exitCode = state.lastExitCode;
          const observerGenerationAtD = getCodexExitObserverGeneration(tabId);
          // Preserve the last confirmed state while the observer is pending.
          // finalizeCodexCommandFinished is the sole destructive transition.
          state.isRunning = wasRunningBeforeD;
          terminalCommandState.set(tabId, state);
          const timer = setTimeout(async () => {
            codexFinishDebounceTimers.delete(tabId);
            if (!isCodexExitObserverCurrent(tabId, observerGenerationAtD, runSeqAtD)) {
              console.warn('[CodexTurn] skip delayed command-finished tab=' + tabId.slice(-8)
                + ' reason=stale-observer runSeq=' + runSeqAtD
                + ' generation=' + observerGenerationAtD
                + ' currentRunSeq=' + Number(terminalCommandState.get(tabId)?.runSeq || 0));
              return;
            }
            const lookup = await inspectAiDescendantProcessesByTab(tabId, 'codex', { forceFresh: true });
            if (!isCodexExitObserverCurrent(tabId, observerGenerationAtD, runSeqAtD)) {
              console.warn('[CodexTurn] skip delayed command-finished tab=' + tabId.slice(-8)
                + ' reason=stale-observer-after-lookup runSeq=' + runSeqAtD
                + ' generation=' + observerGenerationAtD
                + ' currentRunSeq=' + Number(terminalCommandState.get(tabId)?.runSeq || 0));
              return;
            }
            const decision = decideCodexExitProbe(lookup);
            if (decision === 'retry') {
              console.warn('[CodexTurn] preserve delayed command-finished tab=' + tabId.slice(-8)
                + ' reason=process-lookup-unknown action=retry'
                + ' error=' + (lookup.error?.message || lookup.error || 'unknown'));
              armCodexDescendantExitRecheck(
                tabId,
                exitCode,
                'osc-d-lookup-unknown',
                runSeqAtD,
                observerGenerationAtD,
              );
              return;
            }
            if (decision === 'keep-alive') {
              const liveCodex = lookup.matches;
              const keptAlive = await keepCodexRuntimeAliveFromProcessProof(tabId, liveCodex, 'codex-descendant-alive', {
                emitCommandStarted: true,
                expectedObserverGeneration: observerGenerationAtD,
                expectedRunSeq: runSeqAtD,
              });
              if (!keptAlive) return;
              console.warn(
                '[CodexTurn] keep delayed command-finished tab=' + tabId.slice(-8) +
                ' reason=codex-descendant-alive matches=' + liveCodex.length
              );
              armCodexDescendantExitRecheck(
                tabId,
                exitCode,
                'codex-descendant-alive',
                runSeqAtD,
                observerGenerationAtD,
              );
              return;
            }
            finalizeCodexCommandFinished(tabId, exitCode, 'command-finished');
          }, 250);
          codexFinishDebounceTimers.set(tabId, timer);
          break;
        }
        state.isRunning = false;
        clearTerminalCommandOrigin(tabId, state, 'osc-d');
        terminalCommandState.set(tabId, state);
        const hadCodexRuntimeState = codexLastRunCommandPayload.has(tabId)
          || codexKnownSessions.has(tabId)
          || codexTurnWatchers.has(tabId)
          || codexTuiReadyTabs.has(tabId)
          || activityOpenIntervals.get(tabId)?.engine === 'codex';
        if (activityOpenIntervals.get(tabId)?.engine === 'codex') {
          recordActivity(tabId, false, 'codex');
        }
        // During graceful app quit, before-quit marks interrupted sessions early,
        // then sends Ctrl+C. If Codex exits cleanly and emits OSC D before
        // will-quit, clearing this map here would make will-quit clear the freshly
        // marked interrupted flag and not re-mark it. Keep the known session until
        // will-quit finishes its definitive clear+mark pass.
        if (_gracefulShutdownInProgress) {
          const sid = codexKnownSessions.get(tabId) || null;
          if (sid) {
            console.log('[Codex:Known] keep tab=' + String(tabId).slice(-12) +
              ' session=' + String(sid).slice(0, 8) +
              ' reason=command-finished shutdown=true');
          }
        } else {
          invalidateAiProcessLookupCache(tabId, 'codex');
          clearCodexLaunchPayload(tabId, 'command-finished');
          clearCodexKnownSession(tabId, 'command-finished');
          clearCodexTuiReady(tabId, 'command-finished');
        }
        closeCodexTurnWatcher(tabId, 'command-finished');
        if (!_gracefulShutdownInProgress && hadCodexRuntimeState) {
          broadcastAiRuntimeStatus(tabId, 'codex', 'inactive', 'command-finished');
        }
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('terminal:command-finished', {
            tabId,
            exitCode: state.lastExitCode
          });
        }
        // Clear bridge + claudeCliActive when the shell regains control.
        // Both managed and manual launches own their real B→D span. The init
        // Ctrl+C prelude is already excluded above; WAITING_PROMPT is not proof
        // that the process survived an exit (e.g. an empty --resume rejection).
        const completionIntent = claudeStartupIntents.get(tabId) || null;
        const completionSameTerminal = !!completionIntent
          && completionIntent.terminalToken === terminals.get(tabId)
          && (!terminalToken || completionIntent.terminalToken === terminalToken);
        const claudeShellFinish = shouldClearClaudeShellLaunchOnCommandFinished({
          hasClaudeState: claudeState.has(tabId),
          hasPendingPrompt: claudePendingPrompt.has(tabId),
          startupIntentReason: completionIntent?.reason,
          sawOscCommandStart: completionIntent?.sawOscCommandStart === true,
          sameTerminal: completionSameTerminal,
          gracefulShutdownInProgress: _gracefulShutdownInProgress,
        });
        if (claudeShellFinish.clear) {
          const hadPromptReady = claudePromptReady.delete(tabId);
          const hadLaunchGeneration = claudeLaunchGenerationByTab.has(tabId);
          if (claudeCliActive.has(tabId)) {
            claudeCliActive.delete(tabId);
          }
          if (bridgeKnownSessions.has(tabId) || findClaudePidByTab(tabId)) {
            clearBridgeTab(tabId, 'command-finished');
          } else {
            claudeStartupIntents.delete(tabId);
            claudeState.delete(tabId);
            claudePendingPrompt.delete(tabId);
            clearClaudeLaunchGeneration(tabId, 'command-finished-no-bridge');
            if (hadPromptReady || hadLaunchGeneration) {
              console.log('[MobBcast] busy+snapshot tab=' + String(tabId).slice(-12) + ' busy=false status=inactive src=command-finished-no-bridge');
              _webBroadcast(tabId, { type: 'busy', busy: false });
              _webBroadcast(tabId, {
                type: 'snapshot',
                sessionId: null,
                busy: false,
                sessionStatus: 'inactive',
                inputReady: false,
                toolType: 'claude',
                commandType: 'claude',
              });
              scheduleProjectActivityBroadcast('claude-command-finished-no-bridge');
            }
          }
        } else if (
          claudeShellFinish.reason === 'graceful-shutdown-preserve-session'
          && bridgeKnownSessions.has(tabId)
        ) {
          const sid = bridgeKnownSessions.get(tabId) || null;
          console.log('[Claude:Known] keep tab=' + String(tabId).slice(-12)
            + ' session=' + String(sid || '').slice(0, 8)
            + ' reason=command-finished shutdown=true');
        }
        clearClaudePendingJsonlOwnersForTab(tabId, 'command-finished');
        break;
    }
  }
}

function createWindow() {
  console.log('Plan Mode test OK');
  console.log('[Window] Creating main window...');

  const windowOptions = {
    width: 1900,
    height: 1000,
    show: !E2E_WINDOWED && process.env.NOTED_E2E_TEST === 'true',
    paintWhenInitiallyHidden: true,
    backgroundColor: '#1a1a1a', // Dark background instead of white flash
    titleBarStyle: 'hidden',
    titleBarOverlay: {
      color: 'rgba(0,0,0,0)',
      // Совпадает с TITLE_BAR_H из src/renderer/constants/layout.ts. Это
      // высота полосы, в которой macOS рисует кнопки закрыть/свернуть; если
      // числа разойдутся, кружки встанут не по центру нашей шапки. 2026-08-18:
      // шапка стала ниже (было 40), потому что вторая строка кнопок удалена.
      height: 30,
      symbolColor: '#ffffff'
    },
    webPreferences: {
      nodeIntegration: true,
      contextIsolation: false,
      ...(E2E_WINDOWED ? { backgroundThrottling: false } : {}),
      // webviewTag выключён 2026-08-17: его включали ради встроенной
      // browser-вкладки, а её больше нет. Тег даёт странице право встраивать
      // произвольный сайт внутрь окна приложения — не оставляем это включённым
      // без того, кто этим пользуется.
    },
  };

  mainWindow = new BrowserWindow(windowOptions);
  console.log('[Window] BrowserWindow created');

  // Открываем окно развёрнутым на весь рабочий стол (macOS zoom — как двойной
  // клик по титлбару), НЕ нативный полноэкранный режим: тот уводит окно в
  // отдельное пространство Spaces, прячет Dock/меню и ломает наши overlay-окна
  // (Global Dictation чип, tab-switcher), которые живут поверх обычного экрана.
  if (!E2E_WINDOWED) mainWindow.maximize();

  // Cmd+Tab focus restore: when macOS re-fronts our window via Cmd+Tab,
  // Chromium does NOT auto-restore DOM focus to any element. Side-effect:
  // the next Cmd+V from a paste-source app (e.g. Voice Record dictation
  // overlay) is swallowed because no focused input/terminal receives the
  // key event — AXFocusedUIElement returns -25212 / kAXErrorNoValue.
  // Tab-switching inside the app works because that codepath explicitly
  // re-focuses (terminalRegistry.get(tabId).focus / textareaRef.focus),
  // but window-level focus has no such hook.
  //
  // Fix: on every BrowserWindow 'focus' event, broadcast a window-event to
  // the renderer; per-tab components (Terminal.tsx, ClaudeSDKTab.tsx)
  // listen and refocus their own DOM element via the same path they use
  // for tab switching.
  mainWindow.on('focus', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      console.log('[Window:Focus] browser-window focus → broadcast window:refocus-active');
      mainWindow.webContents.send('window:refocus-active');
    }
  });

  // On macOS the red traffic-light button closes the BrowserWindow before
  // `window-all-closed` can route the app through `before-quit`.  By then the
  // renderer is already gone, so the shutdown overlay cannot be shown and the
  // user sees an abrupt disappearance even though main still has work to do.
  // Keep the window alive on the first close request and enter the same single
  // graceful path as Cmd+Q.  The second app.quit() is issued only after that
  // path has persisted interrupted owners and stopped the live CLIs; the
  // `_gracefulShutdownDone` guard then lets this close event pass through.
  mainWindow.on('close', (event) => {
    if (_gracefulShutdownDone) return;
    event.preventDefault();
    if (_gracefulShutdownInProgress) {
      console.log('[Shutdown:window-close] close already in progress');
      return;
    }
    console.log('[Shutdown:window-close] routing through graceful app quit'
      + ' terminals=' + terminals.size
      + ' ai=' + getInterruptedAiSessionEntries().size);
    app.quit();
  });

  // Show window when ready and force focus on macOS (Sequoia/Tahoe workaround)
  mainWindow.once('ready-to-show', () => {
    if (E2E_WINDOWED) {
      console.log('[Window] ready-to-show, retained hidden for background CDP test');
      return;
    }
    console.log('[Window] ready-to-show fired, showing window...');
    mainWindow.show();

    // macOS Sequoia/Tahoe: Triple activation для обхода focus stealing protection
    if (process.platform === 'darwin') {
      setTimeout(() => {
        console.log('[Window] Forcing focus (moveTop + focus + steal)...');
        mainWindow.moveTop();
        app.focus({ steal: true });
        mainWindow.focus();
      }, 50);
    }
  });

  // Set dev icon in Dock if in development mode (macOS specific)
  if (isDev && process.platform === 'darwin') {
    const devIconPath = path.join(__dirname, '..', '..', 'build-resources', 'icon-dev.png');
    if (require('fs').existsSync(devIconPath)) {
      app.dock.setIcon(devIconPath);
    }
  }

  // Load from Vite dev server in dev mode, or from built files in production.
  // Isolated E2E launches can use the freshly built renderer to avoid sharing
  // a developer's Vite navigation and DevTools target.
  const useBuiltRendererForE2E = process.env.NOTED_E2E_TEST === 'true'
    && process.env.NOTED_E2E_USE_BUILT_RENDERER === 'true';
  if (process.env.ELECTRON_RENDERER_URL && !useBuiltRendererForE2E) {
    console.log('[Window] Loading URL:', process.env.ELECTRON_RENDERER_URL);
    mainWindow.loadURL(process.env.ELECTRON_RENDERER_URL);
    if (process.env.NOTED_E2E_TEST !== 'true') mainWindow.webContents.openDevTools();
  } else if (isDev && !useBuiltRendererForE2E) {
    console.log('[Window] Loading fallback URL: http://localhost:5182');
    mainWindow.loadURL('http://localhost:5182');
    if (process.env.NOTED_E2E_TEST !== 'true') mainWindow.webContents.openDevTools();
  } else {
    const filePath = path.join(__dirname, '..', 'renderer', 'index.html');
    console.log('[Window] Loading file:', filePath);
    mainWindow.loadFile(filePath);
  }

  // Логи для отладки загрузки
  mainWindow.webContents.on('did-start-loading', () => {
    const abandonedClaims = claudeStartupMainRuntime.abandonPendingManualClaims(
      'renderer-navigation',
    );
    if (abandonedClaims > 0) {
      console.warn('[StartupTx] abandoned pending manual proofs count='
        + abandonedClaims + ' reason=renderer-navigation');
    }
    console.log('[Window] did-start-loading');
  });

  mainWindow.webContents.on('did-finish-load', () => {
    console.log('[Window] did-finish-load');
  });

  mainWindow.webContents.on('did-fail-load', (event, errorCode, errorDescription) => {
    console.error('[Window] did-fail-load:', errorCode, errorDescription);
  });

  // Renderer-crash safety net. The dictation mic path (deprecated
  // ScriptProcessorNode → AudioWorklet migration, see fix-mic-renderer-sigsegv.md)
  // could SIGSEGV the renderer, leaving a frozen white window the user had to
  // reload by hand. This auto-reloads on a genuine crash so the app recovers
  // itself. We skip:
  //   • normal teardown during quit (reason 'clean-exit', or our shutdown flags)
  //   • 'killed' (SIGTERM/SIGKILL — that's us or the OS tearing it down)
  // and we rate-limit reloads so a crash-on-load can't spin forever.
  let _lastRendererReload = 0;
  let _rendererReloadCount = 0;
  mainWindow.webContents.on('render-process-gone', (event, details) => {
    const reason = details?.reason || 'unknown';
    console.error('[Window] render-process-gone:', JSON.stringify(details));
    const abandonedClaims = claudeStartupMainRuntime.abandonPendingManualClaims(
      'renderer-gone:' + reason,
    );
    if (abandonedClaims > 0) {
      console.warn('[StartupTx] abandoned pending manual proofs count='
        + abandonedClaims + ' reason=renderer-gone:' + reason);
    }

    if (_gracefulShutdownInProgress || _gracefulShutdownDone) {
      console.log('[Window] render-process-gone during shutdown → no reload');
      return;
    }
    // 'clean-exit'/'killed' are intentional teardown, not a crash to recover from.
    if (reason === 'clean-exit' || reason === 'killed') {
      console.log('[Window] render-process-gone reason=' + reason + ' → no reload (intentional)');
      return;
    }
    if (!mainWindow || mainWindow.isDestroyed()) return;

    // Rate-limit: if we already reloaded <10s ago, the renderer is crashing on
    // load — reloading again just loops. Bail after 3 rapid attempts.
    const now = Date.now();
    if (now - _lastRendererReload < 10000) {
      _rendererReloadCount++;
    } else {
      _rendererReloadCount = 1;
    }
    _lastRendererReload = now;
    if (_rendererReloadCount > 3) {
      console.error('[Window] render-process-gone: ' + _rendererReloadCount +
        ' crashes in 10s — giving up auto-reload to avoid a loop');
      return;
    }

    console.log('[Window] render-process-gone reason=' + reason +
      ' → auto-reloading renderer (attempt ' + _rendererReloadCount + ')');
    try { mainWindow.webContents.reload(); } catch (e) {
      console.error('[Window] auto-reload failed:', e?.message || e);
    }
  });

  const rendererOrigins = new Set();
  try {
    if (process.env.ELECTRON_RENDERER_URL) {
      rendererOrigins.add(new URL(process.env.ELECTRON_RENDERER_URL).origin);
    }
  } catch {}
  if (isDev) {
    rendererOrigins.add('http://localhost:5182');
    rendererOrigins.add('http://127.0.0.1:5182');
  }
  const isRendererUrl = (url) => {
    try {
      return rendererOrigins.has(new URL(url).origin);
    } catch {
      return false;
    }
  };

  // Prevent the main window from navigating away (kills the renderer)
  mainWindow.webContents.on('will-navigate', (event, url) => {
    if (isRendererUrl(url)) {
      console.log('[Window] Ignored renderer-origin navigation:', url);
      event.preventDefault();
      return;
    }
    console.log('[Window] Blocked navigation to:', url);
    event.preventDefault();
    shell.openExternal(url);
  });

  // Intercept new window requests (target="_blank", window.open) → open in default browser
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    console.log('[Window] Intercepted new-window request:', url);
    if (isRendererUrl(url)) {
      return { action: 'deny' };
    }
    if (url.startsWith('http://') || url.startsWith('https://')) {
      shell.openExternal(url);
    }
    return { action: 'deny' };
  });
}

// Context Menu IPC
// Markdown links may point to web pages or to a local file mentioned in an AI
// reply.  Keep the OS actions in main: the shared markdown package only asks
// for this menu, so it remains usable in non-Electron consumers too.
function localPathFromMarkdownLink(rawHref) {
  const href = typeof rawHref === 'string' ? rawHref.trim() : '';
  if (!href || href.length > 16 * 1024) return null;

  if (href.startsWith('file:')) {
    try {
      const parsed = new URL(href);
      return parsed.protocol === 'file:' ? fileURLToPath(parsed) : null;
    } catch {
      return null;
    }
  }

  // A Markdown #fragment is a document anchor, not part of the local path.
  // Decode after removing it so an encoded literal # in a filename survives.
  const fragmentIndex = href.indexOf('#');
  const withoutFragment = fragmentIndex >= 0 ? href.slice(0, fragmentIndex) : href;
  let decoded = withoutFragment;
  try { decoded = decodeURIComponent(withoutFragment); } catch {}
  return path.isAbsolute(decoded) ? decoded : null;
}

function describeMarkdownLink(rawHref) {
  const href = typeof rawHref === 'string' ? rawHref.trim() : '';
  const filePath = localPathFromMarkdownLink(href);
  if (!filePath) return { href, kind: 'link' };
  try {
    const stat = fs.statSync(filePath);
    if (stat.isFile()) return { href, filePath, kind: 'file' };
    if (stat.isDirectory()) return { href, filePath, kind: 'directory' };
  } catch {
    // Copying a stale path is still useful; opening actions must not pretend
    // that a file which no longer exists can be opened.
  }
  return { href, filePath, kind: 'path' };
}

function openMarkdownFileInGtEditor(filePath, isDirectory) {
  const folder = isDirectory ? filePath : path.dirname(filePath);
  const query = new URLSearchParams({ folder });
  if (!isDirectory) query.set('file', path.basename(filePath));
  const target = 'gteditor://open?' + query.toString();
  void shell.openExternal(target).catch((error) => {
    console.error('[MarkdownLink] GT Editor open failed:', error?.message || error);
  });
}

ipcMain.on('show-markdown-link-context-menu', (event, payload = {}) => {
  const target = describeMarkdownLink(payload?.href);
  if (!target.href) return;

  const template = [];
  if (target.kind === 'file') {
    template.push(
      {
        label: 'Открыть в Finder',
        click: () => shell.showItemInFolder(target.filePath),
      },
      {
        label: 'Открыть в GT Editor',
        click: () => openMarkdownFileInGtEditor(target.filePath, false),
      },
      {
        label: 'Открыть в Sublime Text',
        click: () => {
          void openFileInSublime(target.filePath).then((result) => {
            if (!result?.success) {
              console.warn('[MarkdownLink] Sublime open failed:', result?.error || 'unknown error');
            }
          });
        },
      },
      { type: 'separator' },
      { label: 'Копировать путь', click: () => clipboard.writeText(target.filePath) },
    );
  } else if (target.kind === 'directory') {
    template.push(
      {
        label: 'Открыть в Finder',
        click: () => shell.showItemInFolder(target.filePath),
      },
      {
        label: 'Открыть в GT Editor',
        click: () => openMarkdownFileInGtEditor(target.filePath, true),
      },
      { type: 'separator' },
      { label: 'Копировать путь', click: () => clipboard.writeText(target.filePath) },
    );
  } else if (target.kind === 'path') {
    template.push({ label: 'Копировать путь', click: () => clipboard.writeText(target.filePath) });
  } else {
    template.push({ label: 'Копировать ссылку', click: () => clipboard.writeText(target.href) });
  }

  const menu = Menu.buildFromTemplate(template);
  menu.popup({ window: BrowserWindow.fromWebContents(event.sender) });
});

ipcMain.on('show-history-entry-context-menu', (event, payload = {}) => {
  const { copyText } = payload;
  if (typeof copyText !== 'string' || !copyText.trim()) return;

  const menu = Menu.buildFromTemplate([
    {
      label: 'Copy ID and details',
      click: async () => {
        const result = await copyHistoryEntryDetails(payload, {
          captureDiagnostic: captureTerminalHistoryPreviewDiagnostic,
          writeText: (text) => clipboard.writeText(text),
        });
        if (result.diagnosticRequested && result.success !== true) {
          console.warn('[HistoryEntryDiagnostic] COPY_FAILED'
            + ' tab=' + String(payload.diagnostic.tabId).slice(-12)
            + ' handoff=' + String(payload.diagnostic.handoffId || '-')
            + ' copied=' + (result.copied === true)
            + ' error=' + String(result.error || 'unknown'));
        }
        if (result.diagnosticRequested && !event.sender.isDestroyed()) {
          event.sender.send('history-entry:diagnostic-copy-result', {
            tabId: payload.diagnostic.tabId, toolType: payload.diagnostic.toolType,
            messageId: payload.diagnostic.messageId, ...result,
          });
        }
      },
    },
  ]);
  menu.popup({ window: BrowserWindow.fromWebContents(event.sender) });
});

ipcMain.on('show-terminal-history-preview-context-menu', (event, payload = {}) => {
  const sender = event.sender;
  const tabId = String(payload?.tabId || '');
  const toolType = payload?.toolType === 'claude' || payload?.toolType === 'codex'
    ? payload.toolType
    : null;
  if (!tabId || !toolType) return;
  const selectionText = typeof payload?.selectionText === 'string'
    ? payload.selectionText.slice(0, 1024 * 1024)
    : '';
  const reply = (detail) => {
    if (!sender.isDestroyed()) {
      sender.send('agent-transcript:terminal-preview-diagnostic-result', {
        tabId,
        toolType,
        ...detail,
      });
    }
  };
  const template = [];
  if (selectionText) {
    template.push({
      label: 'Copy selected text',
      click: () => clipboard.writeText(selectionText),
    });
    template.push({ type: 'separator' });
  }
  template.push({
    label: 'Save & copy diagnostic reference',
    click: async () => {
      try {
        const result = await captureTerminalHistoryPreviewDiagnostic(payload);
        // The clipboard is the acknowledgement boundary: never publish a
        // reference to an artifact which failed to reach disk.
        clipboard.writeText(result.reference);
        reply({ success: true, ...result });
      } catch (error) {
        console.error('[TerminalHistoryPreview] DIAGNOSTIC_SAVE_FAILED'
          + ' tab=' + tabId.slice(-12)
          + ' provider=' + toolType
          + ' error=' + (error?.message || String(error)));
        reply({
          success: false,
          error: error?.message || String(error),
        });
      }
    },
  });
  const menu = Menu.buildFromTemplate(template);
  menu.popup({ window: BrowserWindow.fromWebContents(sender) });
});

// Actions for a paste anchor sitting inside the composer text. The marker is
// painted by a click-through highlight layer, so it cannot host its own
// buttons; right-click on it opens this menu instead.
ipcMain.on('show-paste-chip-context-menu', (event, payload = {}) => {
  const chipId = String(payload.chipId || '');
  const chars = Number(payload.chars || 0);
  const preview = String(payload.preview || '');
  if (!chipId) return;
  const sender = event.sender;
  const reply = (action) => {
    if (!sender.isDestroyed()) sender.send('paste-chip-menu-action', { chipId, action });
  };
  const menu = Menu.buildFromTemplate([
    { label: 'Вставка · ' + chars.toLocaleString('ru-RU') + ' символов', enabled: false },
    { type: 'separator' },
    { label: 'Показать содержимое', click: () => reply('preview') },
    { label: 'Вернуть текстом в поле', click: () => reply('restore') },
    { label: 'Копировать содержимое', click: () => { if (preview) clipboard.writeText(preview); } },
    { type: 'separator' },
    { label: 'Удалить вставку', click: () => reply('discard') },
  ]);
  menu.popup({ window: BrowserWindow.fromWebContents(sender) });
});

ipcMain.on('show-terminal-context-menu', async (event, { hasSelection, prompts, tabId, projectId, cwd, shellActionsAllowed, focusInsertPrompt }) => {
  // Load dynamic AI prompts from DB
  let aiPrompts = [];
  try {
    aiPrompts = projectManager.getAIPrompts().filter(p => p.showInContextMenu);
  } catch (e) {
    console.error('[ContextMenu] Failed to load AI prompts:', e);
  }

  const template = [];

  // Dynamic AI prompt items
  for (const aiPrompt of aiPrompts) {
    template.push({
      label: `${aiPrompt.name}`,
      enabled: hasSelection,
      click: () => { event.sender.send('context-menu-command', 'ai-prompt', aiPrompt.id); }
    });
  }

  template.push({ type: 'separator' });

  // Add Insert Prompt submenu. The synthetic project group and the saved
  // library share one builder so PTY, SDK and the React picker cannot drift.
  let promptGroups = [];
  let projectCatalog = null;
  try { promptGroups = projectManager.getPromptGroups(); } catch {}
  try { if (projectId) projectCatalog = projectPromptCatalog.listProject(projectId); } catch (e) {
    console.warn('[ProjectPrompts] terminal menu load failed:', e.message);
  }
  const buildInsertData = (prompt) => ({
    content: prompt.content || '',
    filePaths: Array.isArray(prompt.file_paths) ? prompt.file_paths : [],
  });
  const promptsSubmenu = buildPromptMenuTemplate({
    prompts: prompts || [],
    groups: promptGroups,
    projectCatalog,
    onPick: (prompt) => {
      event.sender.send('context-menu-command', 'insert-prompt', buildInsertData(prompt));
    },
  });
  if (promptsSubmenu.length > 0) {
    template.push({
      label: 'Insert Prompt',
      submenu: promptsSubmenu,
      _insertPromptAnchor: true,
    });
    template.push({ type: 'separator' });
  }

  // Scripts submenu: npm scripts from package.json + .sh files
  const scripts = [];
  const liveAiOwners = getLiveAiRuntimeOwners(tabId);
  let persistedAiRole = false;
  try {
    const row = projectManager?.db?.db?.prepare(
      'SELECT command_type, claude_session_id, gemini_session_id, codex_session_id FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId);
    persistedAiRole = ['claude', 'gemini', 'codex'].includes(row?.command_type)
      || !!row?.claude_session_id
      || !!row?.gemini_session_id
      || !!row?.codex_session_id;
  } catch {}
  const allowShellScripts = shellActionsAllowed === true
    && liveAiOwners.length === 0
    && !persistedAiRole;
  if (cwd && allowShellScripts) {
    try {
      const fs = require('fs');
      const path = require('path');

      // 1. npm scripts from package.json
      const pkgPath = path.join(cwd, 'package.json');
      if (fs.existsSync(pkgPath)) {
        try {
          const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
          if (pkg.scripts) {
            Object.keys(pkg.scripts)
              .filter(name => !name.startsWith('_'))
              .forEach(name => {
                scripts.push({
                  label: `npm run ${name}`,
                  click: () => {
                    event.sender.send('context-menu-command', 'run-script', { tabId, command: `npm run ${name}\r` });
                  }
                });
              });
          }
        } catch (e) {
          console.error('[ContextMenu] Failed to parse package.json:', e);
        }
      }

      // 2. .sh files in CWD
      const shFiles = fs.readdirSync(cwd).filter(f => f.endsWith('.sh') && !f.startsWith('.'));
      if (shFiles.length > 0 && scripts.length > 0) {
        scripts.push({ type: 'separator' });
      }
      shFiles.forEach(file => {
        scripts.push({
          label: `./${file}`,
          click: () => {
            event.sender.send('context-menu-command', 'run-script', { tabId, command: `./${file}\r` });
          }
        });
      });
    } catch (e) {
      console.error('[ContextMenu] Failed to load scripts:', e);
    }
  }

  // Check if tab has a running devServer process
  const cmdState = terminalCommandState.get(tabId);
  const isRunning = cmdState && cmdState.isRunning;

  if (scripts.length > 0 || isRunning) {
    const submenu = [];

    // Active process — stop option at top
    if (isRunning) {
      submenu.push({
        label: '\u25CF Stop process (Ctrl+C)',
        click: () => {
          const term = terminals.get(tabId);
          if (term) term.write('\x03');
        }
      });
      if (scripts.length > 0) {
        submenu.push({ type: 'separator' });
      }
    }

    submenu.push(...scripts);

    template.push({
      label: isRunning ? `Scripts (\u25CF running)` : `Scripts (${scripts.length})`,
      submenu
    });
    template.push({ type: 'separator' });
  }

  // Removed: Add to Favorites (only in TabBar context menu)

  template.push({ role: 'copy' });
  template.push({ role: 'paste' });
  template.push({ type: 'separator' });
  template.push({ role: 'selectAll' });

  // Cmd+J path requests focus on Insert Prompt — positioningItem aligns that
  // index under the OS cursor, which on macOS lands the keyboard selection on
  // that item immediately (no extra ArrowDown press needed).
  const insertPromptIdx = focusInsertPrompt
    ? template.findIndex(t => t && t._insertPromptAnchor)
    : -1;
  const menu = Menu.buildFromTemplate(template);
  const popupOpts = { window: BrowserWindow.fromWebContents(event.sender) };
  if (insertPromptIdx >= 0) popupOpts.positioningItem = insertPromptIdx;
  menu.popup(popupOpts);
});

// SDK tab context menu — slim version, no Scripts / no Research / no Compact.
// Three sections only: Copy + Paste (system roles), separator, Insert Prompt
// submenu (same prompt-store data as the terminal menu uses). The "insert-prompt"
// command travels back through the existing `context-menu-command` channel —
// ClaudeSDKTab listens and routes the payload into its composer textarea.
ipcMain.on('show-sdk-context-menu', (event, { tabId, projectId, hasSelection, focusInsertPrompt } = {}) => {
  let prompts = [];
  let promptGroups = [];
  try { prompts = projectManager.getPrompts(); } catch {}
  try { promptGroups = projectManager.getPromptGroups(); } catch {}

  const template = [];
  template.push({ role: 'copy', enabled: !!hasSelection });
  template.push({ role: 'paste' });

  let projectCatalog = null;
  try { if (projectId) projectCatalog = projectPromptCatalog.listProject(projectId); } catch (e) {
    console.warn('[ProjectPrompts] SDK menu load failed:', e.message);
  }
  const buildInsertData = (prompt) => ({
    content: prompt.content || '',
    filePaths: Array.isArray(prompt.file_paths) ? prompt.file_paths : [],
    tabId,
    sdk: true,
  });
  const promptsSubmenu = buildPromptMenuTemplate({
    prompts,
    groups: promptGroups,
    projectCatalog,
    onPick: (prompt) => {
      event.sender.send('context-menu-command', 'insert-prompt', buildInsertData(prompt));
    },
  });
  if (promptsSubmenu.length > 0) {
    template.push({ type: 'separator' });
    template.push({ label: 'Insert Prompt', submenu: promptsSubmenu, _insertPromptAnchor: true });
  }

  template.push({ type: 'separator' });
  template.push({ role: 'selectAll' });

  const insertPromptIdx = focusInsertPrompt
    ? template.findIndex(t => t && t._insertPromptAnchor)
    : -1;
  const menu = Menu.buildFromTemplate(template);
  const popupOpts = { window: BrowserWindow.fromWebContents(event.sender) };
  if (insertPromptIdx >= 0) popupOpts.positioningItem = insertPromptIdx;
  menu.popup(popupOpts);
});

// ========== MCP HTTP SERVER (terminal + overseer) ==========

// Keep the terminal/overseer discovery record beside the Project API record.
// An isolated dev process must never publish one channel globally while its
// HTTP orchestration channel is scoped to NOTED_DISCOVERY_DIR.
const MCP_PORT_DIR = process.env.NOTED_DISCOVERY_DIR
  ? path.resolve(process.env.NOTED_DISCOVERY_DIR)
  : path.join(os.homedir(), '.noted-terminal');
const MCP_PORT_FILE = path.join(MCP_PORT_DIR, 'mcp-port-' + process.pid);

// ─── Overseer (orchestrator MCP) ──────────────────────────────────────────────
// Granular read-only inspection of Claude sessions for the orchestrator SDK
// tab. Endpoints under /overseer/* are designed so the agent can size requests
// before pulling content: list sessions → stats → turns map → fetch specific
// turn parts (user / thinking / text) with optional byte ranges.
//
// Turn = group of records produced after a user prompt (1 user record + N
// assistant records: thinking blocks, text blocks, tool_use blocks). Tool_use
// arguments and tool_result outputs are deliberately excluded from preview
// surfaces — overseer should not load file dumps or diffs into its context.
//
// `isCompactSummary` user records are auto-generated post /compact and are
// reported with role='compact_summary' so the agent does not confuse them with
// real user prompts. Compact boundaries are reported as their own turn type.

function _buildActiveBranch(recordMap, lastRecord) {
  const reversed = [];
  let cur = lastRecord ? lastRecord.uuid : null;
  const seen = new Set();
  while (cur && !seen.has(cur)) {
    seen.add(cur);
    const rec = recordMap.get(cur);
    if (!rec) break;
    reversed.push(rec);
    cur = rec.logicalParentUuid || rec.parentUuid;
  }
  reversed.reverse();
  return reversed;
}

function _isNoisePrompt(text) {
  if (!text || typeof text !== 'string') return true;
  return text.includes('<command-name>')
      || text.includes('<system-reminder>')
      || text.includes('<task-notification>')
      || text.includes('<local-command-stdout>')
      || text.includes('<local-command-stderr>')
      || text.includes('<local-command-caveat>')
      || text.startsWith('[Request interrupted');
}

// Extract user-prompt text from a user-type entry. Returns null for tool_result
// entries (those are assistant-tool responses, not user input).
function _extractUserText(entry) {
  if (entry?.type !== 'user') return null;
  const c = entry.message?.content;
  if (typeof c === 'string') return c;
  if (Array.isArray(c)) {
    if (c.some(b => b?.type === 'tool_result')) return null;
    const tb = c.find(b => b?.type === 'text' && b.text);
    return tb?.text || null;
  }
  return null;
}

// A Claude prompt can be persisted either as a normal user record or as an
// attachment/queued_command when it was submitted while Claude was busy.
// History readers must use the same carrier contract as orchestration proof;
// otherwise the exact notification that was processed appears as empty text.
function _extractTurnPromptText(entry) {
  return extractClaudePromptCarrier(entry)?.text || null;
}

function shortKnowledgeDocsPath(filePath) {
  if (!filePath || typeof filePath !== 'string') return null;
  const normalized = filePath.replace(/\\/g, '/').trim();
  if (!normalized) return null;
  const segs = normalized.split('/').filter(Boolean);
  const baseName = segs[segs.length - 1] || '';
  const docsIndex = segs.findIndex((seg) => seg.toLowerCase() === 'docs');
  const lower = normalized.toLowerCase();
  const semanticIndexSibling = (() => {
    if (docsIndex < 0 || !path.isAbsolute(normalized)) return false;
    try {
      const parent = path.join('/', ...segs.slice(0, docsIndex));
      return fs.existsSync(path.join(parent, '.semantic-index.json'));
    } catch {
      return false;
    }
  })();
  const isDocsPath = docsIndex >= 0 && (
    !path.isAbsolute(normalized) ||
    semanticIndexSibling ||
    lower === 'docs' ||
    lower.startsWith('docs/') ||
    lower.includes('/docs/')
  );
  const isClaudeMd = baseName === 'CLAUDE.md';
  if (!isDocsPath && !isClaudeMd) return null;
  return segs.length >= 2 ? segs.slice(-2).join('/') : segs[0];
}

function _sessionProgressToolDetail(input) {
  if (!input || typeof input !== 'object') return null;
  const keys = ['file_path', 'path', 'command', 'query', 'pattern', 'summary', 'description', 'url'];
  for (const key of keys) {
    const value = input[key];
    if (typeof value !== 'string' || !value.trim()) continue;
    const normalized = value.replace(/\s+/g, ' ').trim();
    return normalized.length > 200 ? normalized.slice(0, 199) + '…' : normalized;
  }
  return null;
}

// Group the active branch into turns. A turn starts at a user prompt (or a
// compact_boundary) and includes all subsequent assistant records until the
// next user prompt / boundary. Tool_result records are attached to the
// preceding assistant tool_use as `toolResults[id]` but their content is NOT
// included in the structural summary (too large by definition).
function _groupIntoTurns(branch) {
  const turns = [];
  let current = null;

  function flush() {
    if (current) turns.push(current);
    current = null;
  }

  for (const entry of branch) {
    if (entry.isSidechain) continue;
    if (entry.type === 'summary') continue;

    if (entry.type === 'user' || (entry.type === 'attachment' && entry.attachment?.type === 'queued_command')) {
      // tool_result branch — attach to last turn if possible, do not start new
      const arr = entry.message?.content;
      if (Array.isArray(arr) && arr.some(b => b?.type === 'tool_result')) {
        if (current) current.hasToolResults = true;
        continue;
      }
      const carrier = extractClaudePromptCarrier(entry);
      if (!carrier) {
        const internalKind = claudeInternalAgentContinuationKindFromEntry(entry);
        if (current && internalKind) {
          current.internalContinuationCount += 1;
          current.internalContinuationKinds.push(internalKind);
          // An end_turn before a background-agent notification is only the end
          // of that slice. Completion must be proven again after the newest
          // structural continuation carrier.
          current.completionAssistantUuids = [];
        }
        continue;
      }
      const text = carrier.text;
      flush();
      const isCompactSummary = carrier.kind === 'compact_summary';
      current = {
        kind: carrier.kind,
        promptCarrierKind: carrier.kind,
        userUuid: carrier.uuid,
        userTimestamp: carrier.timestamp,
        userChars: text.length,
        isNoise: !isCompactSummary && _isNoisePrompt(text),
        isMeta: entry.isMeta === true,
        // assistant accumulators
        thinkingBlocks: [],   // {idx, chars, preview}
        textBlocks: [],       // {idx, chars, preview}
        toolUses: [],         // {idx, name}
        assistantUuids: [],
        completionAssistantUuids: [],
        internalContinuationCount: 0,
        internalContinuationKinds: [],
        assistantModel: null,
      };
    } else if (entry.type === 'system' && entry.subtype === 'compact_boundary') {
      flush();
      current = {
        kind: 'compact_boundary',
        userUuid: entry.uuid,
        userTimestamp: entry.timestamp || null,
        userChars: 0,
        preTokens: entry.compactMetadata?.preTokens || null,
        postTokens: entry.compactMetadata?.postTokens || null,
        trigger: entry.compactMetadata?.trigger || null,
        thinkingBlocks: [],
        textBlocks: [],
        toolUses: [],
        assistantUuids: [],
      };
      flush();
    } else if (entry.type === 'assistant') {
      if (!current) continue;
      current.assistantUuids.push(entry.uuid);
      current.completionAssistantUuids.push(entry.uuid);
      if (entry.message?.model && !current.assistantModel) {
        current.assistantModel = entry.message.model;
      }
      const arr = entry.message?.content;
      if (!Array.isArray(arr)) continue;
      for (const block of arr) {
        if (!block || typeof block !== 'object') continue;
        if (block.type === 'thinking' && typeof block.thinking === 'string') {
          current.thinkingBlocks.push({
            idx: current.thinkingBlocks.length,
            chars: block.thinking.length,
            preview: block.thinking.slice(0, 160),
          });
        } else if (block.type === 'text' && typeof block.text === 'string') {
          current.textBlocks.push({
            idx: current.textBlocks.length,
            chars: block.text.length,
            preview: block.text.slice(0, 160),
          });
        } else if (block.type === 'tool_use' && block.name) {
          const toolIndex = current.toolUses.length;
          current.toolUses.push({
            idx: toolIndex,
            name: block.name,
            detail: _sessionProgressToolDetail(block.input),
            operationId: String(block.id || `${entry.uuid}:tool:${toolIndex}`),
            assistantUuid: entry.uuid || null,
            timestamp: entry.timestamp || null,
          });
          // Same forward-expand logic the Timeline uses to compute docsEdited
          // (green dot in UI). Tracked per turn so overseer can tell apart
          // doc-update turns from coding turns without inspecting tool args.
          if ((block.name === 'Edit' || block.name === 'Write')) {
            const fp = block.input?.file_path || '';
            const shortName = shortKnowledgeDocsPath(fp);
            if (shortName) {
              if (!current.docsEdited) current.docsEdited = new Set();
              current.docsEdited.add(shortName);
            }
          }
          if (block.name === 'mcp__knowledge__docs_search') {
            const q = block.input?.query || '';
            if (q) {
              if (!current.docsSearchQueries) current.docsSearchQueries = new Set();
              current.docsSearchQueries.add(q);
            }
          }
        }
      }
    }
  }
  flush();
  // Convert Sets to arrays before returning (Set is not JSON-serializable directly).
  for (const t of turns) {
    if (t.docsEdited instanceof Set) t.docsEdited = Array.from(t.docsEdited);
    if (t.docsSearchQueries instanceof Set) t.docsSearchQueries = Array.from(t.docsSearchQueries);
  }
  return turns;
}

// Load + cache turns for a session. Returns the same shape used by all
// /overseer/session/:id/* handlers.
const _overseerTurnsCache = new Map(); // sessionId → { size, turns, recordMap, ... }
// This cache retains the full parsed recordMap. Leaving it unbounded defeated
// claude-data's 192MB eviction budget: cross-session search over 45 tabs kept
// every evicted map strongly reachable here and could rebuild a multi-GB heap.
const OVERSEER_TURNS_CACHE_MAX_SOURCE_BYTES = 192 * 1024 * 1024;
const OVERSEER_TURNS_CACHE_MAX_ENTRIES = 64;
let _overseerTurnsCacheRawBytes = 0;

function _deleteOverseerTurnsCache(cacheKey) {
  const cached = _overseerTurnsCache.get(cacheKey);
  if (!cached) return false;
  _overseerTurnsCache.delete(cacheKey);
  _overseerTurnsCacheRawBytes = Math.max(
    0,
    _overseerTurnsCacheRawBytes - (Number(cached.retainedSourceBytes ?? cached.size) || 0),
  );
  return true;
}

function _getOverseerTurnsCache(cacheKey) {
  const cached = _overseerTurnsCache.get(cacheKey) || null;
  if (!cached) return null;
  _overseerTurnsCache.delete(cacheKey);
  _overseerTurnsCache.set(cacheKey, cached);
  return cached;
}

function _setOverseerTurnsCache(cacheKey, result) {
  _deleteOverseerTurnsCache(cacheKey);
  _overseerTurnsCache.set(cacheKey, result);
  _overseerTurnsCacheRawBytes += Number(result?.retainedSourceBytes ?? result?.size) || 0;
  while (_overseerTurnsCacheRawBytes > OVERSEER_TURNS_CACHE_MAX_SOURCE_BYTES
    || _overseerTurnsCache.size > OVERSEER_TURNS_CACHE_MAX_ENTRIES) {
    const oldest = _overseerTurnsCache.keys().next().value;
    if (oldest === undefined) break;
    _deleteOverseerTurnsCache(oldest);
  }
}

async function _loadCodexSessionTurns(sessionId, cwd, options = {}) {
  if (!codexDataModule?._api?.loadSessionRecords || !codexDataModule?._api?.buildCodexFullHistory) {
    const err = new Error('Codex overseer loader is unavailable');
    err.status = 500;
    throw err;
  }
  const cacheKey = 'codex:' + sessionId;
  if (options.forceFresh === true) _deleteOverseerTurnsCache(cacheKey);
  const loaded = await transcriptService.loadCodexOperationSource({
    sessionId, cwd, forceFresh: options.forceFresh === true, includeRecords: false,
  });
  if (!loaded?.success) {
    const err = new Error(loaded?.error || `Codex session ${sessionId} not found on disk`);
    err.status = loaded?.error === 'lineage_unresolved' ? 409 : 404;
    err.lineageReason = loaded?.lineageReason;
    throw err;
  }
  const stat = fs.statSync(loaded.filePath);
  const cached = _getOverseerTurnsCache(cacheKey);
  if (cached && cached.mtimeMs === stat.mtimeMs && cached.size === stat.size
    && cached.contentRevision === loaded.contentRevision) {
    const annotations = _loadSessionAnnotations(sessionId, cached.turns);
    return { ...cached, ...annotations, filePath: loaded.filePath };
  }

  const historyEntries = loaded.historyEntries || codexDataModule._api.buildCodexFullHistory(loaded.records, sessionId);
  const timelineEntries = loaded.timelineEntries || codexDataModule._api.buildCodexTimeline(loaded.records, sessionId);
  const sessionMeta = loaded.sessionMeta || codexDataModule._api.getTimelineSessionMeta(loaded.records);
  const codexTimelineUsersByUuid = new Map(
    (timelineEntries || [])
      .filter((entry) => entry?.type === 'user' && entry?.uuid)
      .map((entry) => [entry.uuid, entry]),
  );
  const turns = [];
  const recordMap = new Map();
  let current = null;

  const flush = () => {
    if (current) turns.push(current);
    current = null;
  };

  for (const entry of historyEntries || []) {
    if (!entry) continue;
    if (entry.role === 'user') {
      flush();
      const text = String(entry.content || '');
      const timelineUser = codexTimelineUsersByUuid.get(entry.uuid) || null;
      const rec = {
        uuid: entry.uuid,
        type: 'user',
        timestamp: entry.timestamp || null,
        sessionId,
        message: { content: text },
      };
      recordMap.set(entry.uuid, rec);
      current = {
        kind: 'user',
        userUuid: entry.uuid,
        userTimestamp: entry.timestamp || null,
        userChars: text.length,
        isNoise: _isNoisePrompt(text),
        thinkingBlocks: [],
        textBlocks: [],
        toolUses: [],
        assistantUuids: [],
        assistantModel: timelineUser?.responseModel || null,
        assistantEffort: timelineUser?.responseEffort || null,
        codexProviderTurnIndex: Number.isInteger(timelineUser?.turnIndex)
          ? timelineUser.turnIndex
          : (Number.isInteger(entry.turnIndex) ? entry.turnIndex : null),
        docsEdited: Array.isArray(timelineUser?.docsEdited) ? [...timelineUser.docsEdited] : undefined,
        docsSearchQueries: Array.isArray(timelineUser?.docsSearchQueries)
          ? [...timelineUser.docsSearchQueries]
          : undefined,
      };
      continue;
    }

    if (entry.role === 'compact') {
      flush();
      const text = String(entry.compactSummary || entry.content || 'Conversation compacted');
      const rec = {
        uuid: entry.uuid,
        type: 'user',
        isCompactSummary: true,
        timestamp: entry.timestamp || null,
        sessionId,
        message: { content: text },
      };
      recordMap.set(entry.uuid, rec);
      current = {
        kind: 'compact_summary',
        userUuid: entry.uuid,
        userTimestamp: entry.timestamp || null,
        userChars: text.length,
        isNoise: false,
        preTokens: entry.preTokens || null,
        thinkingBlocks: [],
        textBlocks: [],
        toolUses: [],
        assistantUuids: [],
        assistantModel: null,
      };
      flush();
      continue;
    }

    if (entry.role === 'assistant') {
      if (!current) {
        current = {
          kind: 'user',
          userUuid: null,
          userTimestamp: entry.timestamp || null,
          userChars: 0,
          isNoise: false,
          thinkingBlocks: [],
          textBlocks: [],
          toolUses: [],
          assistantUuids: [],
          assistantModel: null,
        };
      }
      const blocks = [];
      const thinking = String(entry.thinking || '');
      const text = String(entry.content || '');
      if (thinking) {
        current.thinkingBlocks.push({
          idx: current.thinkingBlocks.length,
          chars: thinking.length,
          preview: thinking.slice(0, 160),
        });
        blocks.push({ type: 'thinking', thinking });
      }
      if (text) {
        current.textBlocks.push({
          idx: current.textBlocks.length,
          chars: text.length,
          preview: text.slice(0, 160),
        });
        blocks.push({ type: 'text', text });
      }
      for (const action of entry.actions || []) {
        const name = action?.rawTool?.toolName || action?.tool || 'tool';
        const toolIndex = current.toolUses.length;
        current.toolUses.push({
          idx: toolIndex,
          name,
          detail: _sessionProgressToolDetail(action?.rawTool?.args),
          operationId: String(
            action?.id
            || action?.rawTool?.toolUseId
            || action?.rawTool?.toolCallId
            || `${entry.uuid}:action:${toolIndex}`,
          ),
          assistantUuid: entry.uuid || null,
          timestamp: entry.timestamp || null,
        });
        blocks.push({ type: 'tool_use', name });
      }
      const rec = {
        uuid: entry.uuid,
        type: 'assistant',
        timestamp: entry.timestamp || null,
        sessionId,
        message: { content: blocks },
      };
      recordMap.set(entry.uuid, rec);
      current.assistantUuids.push(entry.uuid);
    }
  }
  flush();

  const annotations = _loadSessionAnnotations(sessionId, turns);
  const result = {
    engine: 'codex',
    sessionId,
    composite: loaded.composite === true,
    contentRevision: loaded.contentRevision,
    retainedSourceBytes: loaded.retainedSourceBytes,
    mtimeMs: stat.mtimeMs,
    size: stat.size,
    sourceSnapshot: loaded.sourceSnapshot || {
      filePath: loaded.filePath,
      size: stat.size,
      mtimeMs: stat.mtimeMs,
      sessionId,
    },
    turns,
    branchLength: historyEntries.length,
    filePath: loaded.filePath,
    recordMap,
    timelineEntries,
    sessionMeta,
    ...annotations,
  };
  _setOverseerTurnsCache(cacheKey, result);
  return result;
}

async function _loadSessionTurns(sessionId, cwd, options = {}) {
  const located = findSessionFile(sessionId, cwd);
  if (!located) {
    return _loadCodexSessionTurns(sessionId, cwd, options);
  }
  const stat = fs.statSync(located.filePath);
  const cacheKey = 'claude:' + sessionId;
  if (options.forceFresh === true) _deleteOverseerTurnsCache(cacheKey);
  const cached = _getOverseerTurnsCache(cacheKey);
  if (cached && cached.mtimeMs === stat.mtimeMs && cached.size === stat.size) {
    // Annotations (notes, rewind markers) can change WITHOUT JSONL changing,
    // so we always re-read them per request — cheap point lookups on SQLite.
    const annotations = _loadSessionAnnotations(sessionId, cached.turns);
    return { ...cached, ...annotations, filePath: located.filePath };
  }
  const { recordMap, lastRecord, sourceSnapshot } = await loadJsonlRecords(located.filePath);
  const branch = _buildActiveBranch(recordMap, lastRecord);
  const turns = _groupIntoTurns(branch);
  const annotations = _loadSessionAnnotations(sessionId, turns);
  const observedSnapshot = sourceSnapshot || {
    filePath: located.filePath,
    size: stat.size,
    mtimeMs: stat.mtimeMs,
    sessionId,
  };
  const result = {
    sessionId,
    mtimeMs: observedSnapshot.mtimeMs,
    size: observedSnapshot.size,
    turns,
    branchLength: branch.length,
    filePath: located.filePath,
    sourceSnapshot: observedSnapshot,
    recordMap,
    branchUuids: new Set(branch.map((entry) => entry?.uuid).filter(Boolean)),
    ...annotations,
  };
  _setOverseerTurnsCache(cacheKey, result);
  return result;
}

function _sessionHistoryAppRelations(sessionId) {
  const empty = { openTabs: [], archivedTabs: [] };
  if (!sessionId || !projectManager?.db?.db) return empty;
  try {
    const rows = projectManager.db.db.prepare(`
      SELECT project_id, tab_id, name, command_type, visual_parent_tab_id,
             claude_session_id, codex_session_id, created_at
      FROM tabs
      WHERE claude_session_id = ? OR codex_session_id = ?
      ORDER BY created_at, id
    `).all(sessionId, sessionId);
    const openTabs = rows.map((row) => {
      const parent = row.visual_parent_tab_id
        ? projectManager.db.db.prepare(`
            SELECT tab_id, name, claude_session_id, codex_session_id
            FROM tabs
            WHERE project_id = ? AND tab_id = ?
            LIMIT 1
          `).get(row.project_id, row.visual_parent_tab_id)
        : null;
      return {
        projectId: row.project_id,
        tabId: row.tab_id,
        name: row.name,
        provider: row.command_type || null,
        visualParent: parent ? {
          tabId: parent.tab_id,
          name: parent.name,
          sessionId: parent.codex_session_id || parent.claude_session_id || null,
        } : null,
        createdAt: row.created_at ?? null,
      };
    });
    const archivedTabs = projectManager.db.db.prepare(`
      SELECT id, project_id, tab_id, name, command_type, created_at, closed_at
      FROM tab_history
      WHERE claude_session_id = ? OR codex_session_id = ?
      ORDER BY closed_at DESC, id DESC
    `).all(sessionId, sessionId).map((row) => ({
      historyId: row.id,
      projectId: row.project_id,
      tabId: row.tab_id,
      name: row.name,
      provider: row.command_type || null,
      createdAt: row.created_at ?? null,
      closedAt: row.closed_at ?? null,
    }));
    return { openTabs, archivedTabs };
  } catch (error) {
    console.warn('[SessionHistoryEvents] app relation lookup failed:', error.message);
    return empty;
  }
}

async function _reconcileSessionHistoryEvents(data, cwd = null) {
  const sessionId = data?.sessionId;
  const provider = data?.engine === 'codex' ? 'codex' : 'claude';
  if (!sessionId || !projectManager?.db) {
    return {
      totalIterations: decorateTurnsWithIterationCoordinates(data?.turns).totalIterations,
      historyEvents: { fork: null, children: [], compacts: [] },
      appRelations: { openTabs: [], archivedTabs: [] },
    };
  }

  try {
    if (provider === 'claude') {
      const snapshot = deriveClaudeForkSnapshot(data.turns, data.recordMap);
      if (snapshot) {
        projectManager.db.saveSessionForkEvent({
          provider: 'claude',
          sourceSessionId: snapshot.sourceSessionId,
          childSessionId: sessionId,
          entryUuids: snapshot.entryUuids,
          boundaryEntryUuid: snapshot.boundaryEntryUuid,
          snapshotComplete: snapshot.snapshotComplete,
          forkMode: 'full',
          origin: 'transcript',
          isDirect: true,
        });
      }
    }
    if (provider === 'codex' && !data.composite && data.sessionMeta?.forked_from_id) {
      const snapshot = deriveCodexForkSnapshot(data.timelineEntries, data.sessionMeta);
      projectManager.db.saveSessionForkEvent({
        provider: 'codex',
        sourceSessionId: snapshot.sourceSessionId,
        childSessionId: sessionId,
        entryUuids: snapshot.entryUuids,
        boundaryEntryUuid: snapshot.boundaryEntryUuid,
        snapshotComplete: snapshot.snapshotComplete,
        occurredAt: snapshot.occurredAt,
        forkMode: 'unknown',
        origin: 'transcript',
        isDirect: true,
      });
    }

    let historyEvents = projectManager.db.getSessionHistoryContext(sessionId);
    let forkParentData = null;
    if (historyEvents.fork && (
      historyEvents.fork.nextIterationIndex == null
      || (historyEvents.fork.provider === 'codex' && historyEvents.fork.metadataCopied !== true)
    )) {
      try {
        forkParentData = await _loadSessionTurns(historyEvents.fork.sourceSessionId, cwd);
        const parentCoordinates = decorateTurnsWithIterationCoordinates(forkParentData.turns);
        let nextIterationIndex = null;
        if (historyEvents.fork.nextIterationIndex == null && historyEvents.fork.provider === 'claude') {
          const inherited = new Set(historyEvents.fork.entryUuids || []);
          for (const turn of parentCoordinates.turns) {
            if (!inherited.has(turn.userUuid)) continue;
            if (turn.iterationIndex != null) nextIterationIndex = turn.iterationIndex + 1;
            else if (turn.nextIterationIndex != null) nextIterationIndex = turn.nextIterationIndex;
          }
        } else if (historyEvents.fork.nextIterationIndex == null) {
          const forkAtSeconds = historyEvents.fork.occurredAt;
          const forkAtMs = Number(forkAtSeconds) * 1000;
          if (forkAtSeconds != null && Number.isFinite(forkAtMs)) {
            nextIterationIndex = parentCoordinates.turns.filter((turn) => {
              if (turn.iterationIndex == null || !turn.userTimestamp) return false;
              const turnAtMs = Date.parse(String(turn.userTimestamp));
              return Number.isFinite(turnAtMs) && turnAtMs <= forkAtMs + 1000;
            }).length;
          }
        }
        if (nextIterationIndex != null) {
          projectManager.db.saveSessionForkEvent({
            provider: historyEvents.fork.provider,
            sourceSessionId: historyEvents.fork.sourceSessionId,
            childSessionId: sessionId,
            entryUuids: historyEvents.fork.entryUuids,
            snapshotComplete: historyEvents.fork.snapshotComplete,
            boundaryEntryUuid: historyEvents.fork.boundaryEntryUuid,
            forkMode: historyEvents.fork.forkMode || 'unknown',
            occurredAt: historyEvents.fork.occurredAt,
            origin: historyEvents.fork.origin || 'transcript',
            afterIterationIndex: nextIterationIndex > 0 ? nextIterationIndex - 1 : null,
            nextIterationIndex,
            isDirect: true,
          });
          historyEvents = projectManager.db.getSessionHistoryContext(sessionId);
        }
      } catch (coordinateError) {
        console.warn('[SessionHistoryEvents] fork iteration backfill failed child=' + String(sessionId).slice(0, 8) + ': ' + coordinateError.message);
      }
    }
    const inheritedUuids = new Set(historyEvents.fork?.entryUuids || []);
    const compactEvents = deriveCompactEvents({ provider, sessionId, turns: data.turns })
      .map((event) => ({
        ...event,
        inherited: inheritedUuids.has(event.boundaryEntryUuid)
          || inheritedUuids.has(event.summaryEntryUuid),
      }));
    if (compactEvents.length > 0) {
      projectManager.db.saveCompactHistoryEvents(compactEvents);
      historyEvents = projectManager.db.getSessionHistoryContext(sessionId);
    }
    let appRelations = _sessionHistoryAppRelations(sessionId);
    if (historyEvents.fork && appRelations.openTabs.length > 0) {
      const childTab = appRelations.openTabs[0];
      const sourceRelations = historyEvents.fork.sourceSessionId
        ? _sessionHistoryAppRelations(historyEvents.fork.sourceSessionId)
        : { openTabs: [] };
      const sourceTabId = sourceRelations.openTabs.length === 1
        ? sourceRelations.openTabs[0].tabId
        : null;
      projectManager.db.saveSessionForkEvent({
        provider: historyEvents.fork.provider,
        sourceSessionId: historyEvents.fork.sourceSessionId,
        childSessionId: sessionId,
        entryUuids: historyEvents.fork.entryUuids,
        snapshotComplete: historyEvents.fork.snapshotComplete,
        boundaryEntryUuid: historyEvents.fork.boundaryEntryUuid,
        sourceTabId,
        childTabId: childTab.tabId,
        visualParentTabId: childTab.visualParent?.tabId || null,
        orchestrationRunId: historyEvents.fork.orchestrationRunId,
        forkMode: historyEvents.fork.forkMode || 'unknown',
        occurredAt: historyEvents.fork.occurredAt,
        origin: historyEvents.fork.origin || 'transcript',
        isDirect: true,
      });
      historyEvents = projectManager.db.getSessionHistoryContext(sessionId);
      appRelations = _sessionHistoryAppRelations(sessionId);
    }
    if (
      historyEvents.fork?.provider === 'codex'
      && historyEvents.fork.metadataCopied !== true
      && forkParentData?.timelineEntries
      && data.timelineEntries
    ) {
      const mappings = mapTimelineEntryUuidsAcrossFork(
        forkParentData.timelineEntries,
        data.timelineEntries,
      );
      const copied = projectManager.db.copyTimelineMetadataForMappedFork(
        sessionId,
        mappings,
        historyEvents.fork.childTabId || appRelations.openTabs[0]?.tabId || null,
      );
      if (copied.notes > 0 || copied.rewindMarkers > 0) {
        console.log('[SessionHistoryEvents] copied Codex fork metadata child=' + String(sessionId).slice(0, 8)
          + ' notes=' + copied.notes + ' rewindMarkers=' + copied.rewindMarkers);
      }
      projectManager.db.markSessionForkMetadataCopied(historyEvents.fork.eventKey);
      historyEvents = projectManager.db.getSessionHistoryContext(sessionId);
    }
    return {
      totalIterations: decorateTurnsWithIterationCoordinates(data.turns).totalIterations,
      historyEvents,
      appRelations,
    };
  } catch (error) {
    console.warn('[SessionHistoryEvents] reconciliation failed sid=' + String(sessionId).slice(0, 8) + ':', error.message);
    return {
      totalIterations: decorateTurnsWithIterationCoordinates(data.turns).totalIterations,
      historyEvents: projectManager.db.getSessionHistoryContext?.(sessionId)
        || { fork: null, children: [], compacts: [] },
      appRelations: _sessionHistoryAppRelations(sessionId),
      reconciliationError: error.message,
    };
  }
}

function _sessionHistoryContextForApi(context) {
  const expose = (event) => {
    if (!event) return null;
    const { entryUuids, ...publicEvent } = event;
    const seconds = Number(event.occurredAt);
    return {
      ...publicEvent,
      snapshotEntryCount: Array.isArray(entryUuids) ? entryUuids.length : 0,
      occurredAtIso: Number.isFinite(seconds)
        ? new Date(seconds * 1000).toISOString()
        : null,
    };
  };
  return {
    fork: expose(context?.fork),
    children: (context?.children || []).map(expose),
    compacts: (context?.compacts || []).map(expose),
  };
}

function _markTerminalAsAiTab(tabId, engine, sessionId = null) {
  if (!tabId || !engine) return;
  const color = engine === 'codex' ? 'codex' : engine === 'gemini' ? 'gemini' : 'claude';
  try {
    // Codex resume/fork arguments name the requested source, not necessarily
    // the rollout that this process will write. Main adopts and persists Codex
    // identity only after process→writable-rollout proof. Claude/Gemini keep
    // their existing eager session contracts.
    const setSessionSql = engine === 'claude'
        ? 'claude_session_id = COALESCE(?, claude_session_id), '
        : engine === 'gemini'
          ? 'gemini_session_id = COALESCE(?, gemini_session_id), '
          : '';
    if (setSessionSql) {
      projectManager.db.db.prepare(
        `UPDATE tabs
         SET command_type = ?,
             ${setSessionSql}
             color = CASE WHEN color IS NULL OR color = '' OR color = 'default' THEN ? ELSE color END
         WHERE tab_id = ?`
      ).run(engine, sessionId || null, color, tabId);
    } else {
      projectManager.db.db.prepare(
        `UPDATE tabs
         SET command_type = ?,
             color = CASE WHEN color IS NULL OR color = '' OR color = 'default' THEN ? ELSE color END
         WHERE tab_id = ?`
      ).run(engine, color, tabId);
    }
  } catch (e) {
    console.warn('[MCP:Terminal] mark-ai-tab DB update failed tab=' + tabId + ' engine=' + engine + ': ' + e.message);
  }
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:mcp-ai-tab', {
      tabId,
      engine,
      sessionId: engine === 'codex' ? undefined : (sessionId || undefined),
      writerProven: false,
    });
  }
}

// Load timeline_notes + timeline_rewind_markers for a session and build maps
// keyed by turnIndex (so callers can join them with /turns output without
// scanning records again). entry_uuid in DB equals turn.userUuid for normal
// user-turns. For compact_boundary/compact_summary entries notes are rare but
// still supported (entry_uuid would match those uuids too).
function _loadSessionAnnotations(sessionId, turns) {
  let notesRows = [];
  let rewindRows = [];
  try {
    if (projectManager?.db?.db) {
      notesRows = projectManager.db.db.prepare(
        'SELECT entry_uuid, content, position, created_at, updated_at FROM timeline_notes WHERE session_id = ?'
      ).all(sessionId);
      rewindRows = projectManager.db.db.prepare(
        'SELECT entry_uuid, created_at FROM timeline_rewind_markers WHERE session_id = ?'
      ).all(sessionId);
    }
  } catch (e) {
    console.error('[MCP:Overseer] annotations DB error:', e.message);
  }
  // uuid → turnIndex map for join
  const uuidToTurn = new Map();
  for (let i = 0; i < turns.length; i++) {
    if (turns[i].userUuid) uuidToTurn.set(turns[i].userUuid, i);
  }
  const notesByTurn = new Map(); // turnIndex → {entryUuid, content, position, createdAt, updatedAt}
  const orphanNotes = []; // entry_uuid not in active branch (note from forked-out/edited records)
  for (const row of notesRows) {
    const idx = uuidToTurn.get(row.entry_uuid);
    if (idx == null) {
      orphanNotes.push({ entryUuid: row.entry_uuid, content: row.content, position: row.position });
      continue;
    }
    notesByTurn.set(idx, {
      entryUuid: row.entry_uuid,
      content: row.content,
      position: row.position,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    });
  }
  const rewindByTurn = new Map();
  for (const row of rewindRows) {
    const idx = uuidToTurn.get(row.entry_uuid);
    if (idx == null) continue;
    rewindByTurn.set(idx, { entryUuid: row.entry_uuid, createdAt: row.created_at });
  }
  return { notesByTurn, orphanNotes, rewindByTurn };
}

// Fetch the raw assistant blocks for one turn (so we can serve full thinking /
// text content on demand). Walks the recordMap by assistantUuids and rebuilds
// blocks in the same order as during grouping.
function _collectAssistantBlocks(turn, recordMap) {
  const thinking = [];
  const text = [];
  for (const uuid of turn.assistantUuids || []) {
    const rec = recordMap.get(uuid);
    if (!rec) continue;
    const arr = rec.message?.content;
    if (!Array.isArray(arr)) continue;
    for (const block of arr) {
      if (!block || typeof block !== 'object') continue;
      if (block.type === 'thinking' && typeof block.thinking === 'string') {
        thinking.push(block.thinking);
      } else if (block.type === 'text' && typeof block.text === 'string') {
        text.push(block.text);
      }
    }
  }
  return { thinking, text };
}

function _evidenceText(value) {
  if (typeof value === 'string') return value;
  if (value == null) return '';
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function _evidenceSlice(value, maxChars, previewOnly = false, start = null, end = null) {
  const text = _evidenceText(value);
  const limit = previewOnly ? Math.min(600, maxChars) : maxChars;
  const length = text.length;
  const resolveOffset = (value, fallback) => {
    if (!Number.isInteger(value)) return fallback;
    return Math.max(0, Math.min(length, value < 0 ? length + value : value));
  };
  const offsetStart = resolveOffset(start, 0);
  const requestedEnd = resolveOffset(end, length);
  const safeEnd = Math.max(offsetStart, requestedEnd);
  const offsetEnd = Math.min(safeEnd, offsetStart + limit);
  return {
    chars: length,
    start: offsetStart,
    end: offsetEnd,
    text: text.slice(offsetStart, offsetEnd),
    truncatedBefore: offsetStart > 0,
    truncatedAfter: offsetEnd < length,
    rangeClamped: offsetEnd < safeEnd,
  };
}

function _normalizeEvidenceOperation(operation, {
  maxChars,
  detail = false,
  inputStart = null,
  inputEnd = null,
  resultStart = null,
  resultEnd = null,
} = {}) {
  const resultState = operation.resultPresent
    ? (operation.isError ? 'error' : 'success')
    : 'missing';
  const base = {
    operationId: operation.operationId || null,
    callId: operation.callId || null,
    tool: {
      name: operation.toolName || null,
      server: operation.mcpServer || null,
      method: operation.mcpMethod || null,
    },
    callTimestamp: operation.callTimestamp || null,
    resultTimestamp: operation.resultTimestamp || null,
    resultSourceLine: operation.resultSourceLine ?? null,
    result: {
      state: resultState,
      ...(operation.resultPresent
        ? _evidenceSlice(operation.result, maxChars, !detail, resultStart, resultEnd)
        : {}),
    },
  };
  if (detail) base.input = _evidenceSlice(operation.input, maxChars, false, inputStart, inputEnd);
  else base.input = _evidenceSlice(operation.input, maxChars, true);
  return base;
}

function _claudeMcpIdentity(name) {
  const raw = typeof name === 'string' ? name : '';
  if (!raw.startsWith('mcp__')) return { server: null, method: null };
  const parts = raw.slice('mcp__'.length).split('__').filter(Boolean);
  return {
    server: parts.length > 1 ? parts[0] : null,
    method: parts.length > 1 ? parts.slice(1).join('__') : null,
  };
}

function _buildClaudeTurnEvidence(turn, recordMap, activeBranchUuids = null) {
  const operations = [];
  const resultsById = new Map();
  for (const record of recordMap.values()) {
    if (activeBranchUuids instanceof Set && !activeBranchUuids.has(record?.uuid)) continue;
    if (record?.type !== 'user') continue;
    for (const block of Array.isArray(record.message?.content) ? record.message.content : []) {
      if (block?.type !== 'tool_result' || !block.tool_use_id) continue;
      resultsById.set(String(block.tool_use_id), {
        result: block.content,
        isError: block.is_error === true,
        timestamp: record.timestamp || null,
      });
    }
  }
  const settingsFacts = [];
  for (const uuid of turn.assistantUuids || []) {
    const record = recordMap.get(uuid);
    if (!record) continue;
    const message = record.message || {};
    const model = typeof message.model === 'string' && message.model.trim() ? message.model.trim() : null;
    const effort = typeof (message.reasoning_effort || message.effort || message.model_reasoning_effort) === 'string'
      ? String(message.reasoning_effort || message.effort || message.model_reasoning_effort).trim()
      : null;
    if (model || effort) settingsFacts.push({
      source: 'assistant_message', timestamp: record.timestamp || null,
      ...(model ? { model } : {}), ...(effort ? { effort } : {}),
    });
    for (const block of Array.isArray(message.content) ? message.content : []) {
      if (block?.type !== 'tool_use') continue;
      const operationId = block.id ? String(block.id) : null;
      const result = operationId ? resultsById.get(operationId) : null;
      const mcp = _claudeMcpIdentity(block.name);
      operations.push({
        operationId,
        callId: operationId,
        toolName: block.name || null,
        mcpServer: mcp.server,
        mcpMethod: mcp.method,
        input: block.input || {},
        result: result?.result,
        resultPresent: !!result,
        isError: result?.isError === true,
        callTimestamp: record.timestamp || null,
        resultSourceLine: null,
        resultTimestamp: result?.timestamp || null,
      });
    }
  }
  const models = [...new Set(settingsFacts.map((fact) => fact.model).filter(Boolean))];
  const efforts = [...new Set(settingsFacts.map((fact) => fact.effort).filter(Boolean))];
  return {
    found: true,
    operations,
    settings: {
      status: settingsFacts.length === 0
        ? 'unknown'
        : (models.length > 1 || efforts.length > 1 ? 'changed_within_turn' : 'known_from_assistant_response'),
      model: models.length === 1 ? models[0] : null,
      effort: efforts.length === 1 ? efforts[0] : null,
      facts: settingsFacts,
      ...(settingsFacts.length === 0 ? { reason: 'provider_records_have_no_model_or_effort' } : {}),
    },
  };
}

async function _buildTurnEvidence(data, turn, cwd) {
  if (data.engine !== 'codex') return _buildClaudeTurnEvidence(turn, data.recordMap, data.branchUuids);
  if (!codexDataModule?._api?.buildCodexTurnEvidence) {
    return {
      found: false,
      reason: 'codex_turn_evidence_parser_unavailable',
      operations: [],
      settings: { status: 'unknown', reason: 'codex_turn_evidence_parser_unavailable' },
    };
  }
  const loaded = await transcriptService.loadCodexOperationSource({
    sessionId: data.sessionId,
    cwd,
    // Virtual Codex lineage exposes its frozen parent + child records only
    // when asked explicitly. Never fall back to the child rollout here: that
    // would turn a composite historical turn into a different physical source.
    includeRecords: true,
  });
  if (!loaded?.success) {
    return {
      found: false,
      reason: loaded?.error || 'codex_operation_source_unavailable',
      operations: [],
      settings: { status: 'unknown', reason: loaded?.error || 'codex_operation_source_unavailable' },
    };
  }
  if (!Array.isArray(loaded.records)) {
    return {
      found: false,
      reason: 'codex_operation_source_records_unavailable',
      operations: [],
      settings: { status: 'unknown', reason: 'codex_operation_source_records_unavailable' },
      sourceSnapshot: loaded.sourceSnapshot || null,
      contentRevision: loaded.contentRevision || null,
    };
  }
  return {
    ...codexDataModule._api.buildCodexTurnEvidence(loaded.records, data.sessionId, {
    userUuid: turn.userUuid,
    providerTurnIndex: turn.codexProviderTurnIndex,
    }),
    // This is the source just read for evidence, not the older overview cache.
    sourceSnapshot: loaded.sourceSnapshot || null,
    contentRevision: loaded.contentRevision || null,
  };
}

function _claudeTurnHasCompletionProof(turn, recordMap) {
  for (const uuid of turn?.assistantUuids || []) {
    const stopReason = String(recordMap.get(uuid)?.message?.stop_reason || '').trim();
    if (stopReason && stopReason !== 'tool_use' && stopReason !== 'pause_turn') return true;
  }
  return false;
}

function _sliceText(s, start, end) {
  if (start == null && end == null) return s;
  const len = s.length;
  let a = (start == null) ? 0 : (start < 0 ? Math.max(0, len + start) : Math.min(len, start));
  let b = (end == null) ? len : (end < 0 ? Math.max(0, len + end) : Math.min(len, end));
  if (b < a) b = a;
  return s.slice(a, b);
}

async function _getAgentTurnResultForOrchestration({
  sessionId,
  cwd,
  promptHash,
  promptUserUuid,
  promptSourceIdentity,
  requestedAt,
  resultAfterAt,
  resultBeforeAt,
  targetExecutionContext,
  forceFresh = false,
  maxChars = 100_000,
}) {
  const latestAfter = Number(resultAfterAt) > 0 ? Number(resultAfterAt) : 0;
  if (!sessionId || (!promptUserUuid && !promptSourceIdentity && !promptHash && !latestAfter)) {
    return {
      found: false,
      error: 'sessionId and promptUserUuid, promptSourceIdentity, promptHash, or resultAfterAt required',
    };
  }
  const data = await _loadSessionTurns(sessionId, cwd, { forceFresh });
  const exactCodexResultProof = data.engine === 'codex'
    && targetExecutionContext?.turnId
    && (promptUserUuid || promptSourceIdentity || promptHash)
    && codexDataModule?._api?.loadSessionRecords
    && codexDataModule?._api?.buildCodexProviderTurnAssistantResult;
  if (exactCodexResultProof) {
    const loaded = await codexDataModule._api.loadSessionRecords(sessionId, cwd);
    if (!loaded?.success) {
      return {
        found: false,
        error: loaded?.error || 'Codex provider turn transcript unavailable',
        sourceSnapshot: data.sourceSnapshot || loaded?.sourceSnapshot || null,
      };
    }
    const codexResult = codexDataModule._api.buildCodexProviderTurnAssistantResult(
      loaded.records,
      sessionId,
      {
        promptHash,
        promptUserUuid,
        promptSourceIdentity,
        requestedAt,
        resultAfterAt: latestAfter,
        resultBeforeAt,
        targetExecutionContext,
      },
      maxChars,
    );
    const logDetails = ' session=' + String(sessionId).slice(0, 12)
      + ' turn=' + String(targetExecutionContext.turnId).slice(0, 24)
      + ' generation=' + (targetExecutionContext.generation ?? '-')
      + ' boundary=' + (codexResult?.boundaryReason || '-')
      + ' complete=' + (codexResult?.complete === true)
      + ' blocks=' + (codexResult?.assistantBlockCount ?? 0);
    if (!codexResult?.success) {
      console.warn('[OrchestrationResultProof] Codex provider turn unproven' + logDetails
        + ' error=' + (codexResult?.error || 'unknown'));
      return {
        found: false,
        errorCode: codexResult?.errorCode || null,
        error: codexResult?.error || 'Codex provider turn result unproven',
        proofDefinitive: codexResult?.proofDefinitive === true,
        terminalEvent: codexResult?.terminalEvent || null,
        boundaryReason: codexResult?.boundaryReason || null,
        sourceSnapshot: data.sourceSnapshot || loaded.sourceSnapshot || null,
      };
    }
    console.log('[OrchestrationResultProof] Codex provider turn materialized' + logDetails);
    return {
      found: true,
      complete: codexResult.complete === true,
      turnIndex: codexResult.turnIndex,
      userUuid: codexResult.userUuid,
      sourceIdentity: codexResult.sourceIdentity || null,
      sourceIdentityAliases: codexResult.sourceIdentityAliases || [],
      promptCarrierKind: codexResult.promptCarrierKind || 'user',
      assistantText: codexResult.assistantText,
      assistantChars: codexResult.assistantChars,
      truncated: codexResult.truncated,
      assistantBlockCount: codexResult.assistantBlockCount,
      terminalEvent: codexResult.terminalEvent || null,
      terminalOutcomeReason: codexResult.terminalOutcomeReason || null,
      hasFinalResult: codexResult.hasFinalResult === true,
      proofDefinitive: codexResult.proofDefinitive === true,
      errorCode: codexResult.errorCode || null,
      error: codexResult.error || null,
      boundaryReason: codexResult.boundaryReason || null,
      executionContext: targetExecutionContext,
      sourceSnapshot: data.sourceSnapshot || loaded.sourceSnapshot || null,
    };
  }
  const match = findMatchingClaudePromptTurn({
    turns: data.turns,
    recordMap: data.recordMap,
    promptHash,
    promptUserUuid,
    requestedAt,
    resultAfterAt: latestAfter,
    resultBeforeAt,
  });
  if (!match) {
    return {
      found: false,
      error: latestAfter ? 'completed continuation turn not found' : 'matching user turn not found',
      sourceSnapshot: data.sourceSnapshot || null,
    };
  }
  if (
    data.engine === 'codex'
    && codexDataModule?._api?.loadSessionRecords
    && codexDataModule?._api?.buildCodexTurnAssistantResult
  ) {
    const loaded = await codexDataModule._api.loadSessionRecords(sessionId, cwd);
    if (loaded?.success) {
      const codexResult = codexDataModule._api.buildCodexTurnAssistantResult(
        loaded.records,
        sessionId,
        match.turn.userUuid,
        maxChars,
      );
      if (codexResult?.success) {
        const executionContext = typeof codexDataModule._api.findCodexPromptExecutionContext === 'function'
          ? codexDataModule._api.findCodexPromptExecutionContext(
              loaded.records,
              sessionId,
              match.turn.userUuid,
            )
          : null;
        return {
          found: true,
          complete: codexResult.complete === true,
          turnIndex: match.turnIndex,
          userUuid: match.turn.userUuid,
          promptCarrierKind: match.turn.promptCarrierKind || match.turn.kind,
          assistantText: codexResult.assistantText,
          assistantChars: codexResult.assistantChars,
          truncated: codexResult.truncated,
          assistantBlockCount: codexResult.assistantBlockCount,
          executionContext,
          sourceSnapshot: data.sourceSnapshot || loaded.sourceSnapshot || null,
        };
      }
    }
  }
  const exactClaudeExecutionProof = targetExecutionContext?.provider === 'claude'
    && !!targetExecutionContext.turnId
    && !!promptUserUuid
    && (!targetExecutionContext.sessionId || targetExecutionContext.sessionId === sessionId);
  const claudeResult = exactClaudeExecutionProof
    ? materializeClaudeOrchestrationExecution({
        turns: data.turns,
        startTurnIndex: match.turnIndex,
        recordMap: data.recordMap,
        resultBeforeAt,
        maxChars,
      })
    : materializeClaudeOrchestrationTurn(
        match.turn,
        data.recordMap,
        maxChars,
      );
  if (exactClaudeExecutionProof) {
    console.log('[OrchestrationResultProof] Claude execution materialized'
      + ' session=' + String(sessionId).slice(0, 12)
      + ' turn=' + String(targetExecutionContext.turnId).slice(0, 24)
      + ' start=' + match.turnIndex
      + ' end=' + claudeResult.endTurnIndex
      + ' queued=' + claudeResult.queuedContinuationCount
      + ' boundary=' + claudeResult.boundaryReason
      + ' complete=' + (claudeResult.complete === true)
      + ' blocks=' + claudeResult.assistantBlockCount);
  }
  return {
    found: true,
    complete: claudeResult.complete,
    turnIndex: match.turnIndex,
    userUuid: match.turn.userUuid,
    promptCarrierKind: match.turn.promptCarrierKind || match.turn.kind,
    assistantText: claudeResult.assistantText,
    assistantChars: claudeResult.assistantChars,
    truncated: claudeResult.truncated,
    assistantBlockCount: claudeResult.assistantBlockCount,
    internalContinuationCount: claudeResult.internalContinuationCount,
    queuedContinuationCount: claudeResult.queuedContinuationCount || 0,
    sourceSnapshot: data.sourceSnapshot || null,
  };
}

function sessionCatalogProjectMatches(candidate, projectFilter) {
  const wanted = String(projectFilter || '').trim().toLocaleLowerCase();
  if (!wanted) return true;
  return [candidate.projectId, candidate.projectName, candidate.projectPath]
    .some((value) => String(value || '').trim().toLocaleLowerCase() === wanted);
}

async function listSessionCatalogCandidates({
  includeOpen = true,
  includeClosed = true,
  project = '',
  dateField = 'activity',
  fromMs = null,
  toMs = null,
  maxCandidates = 100,
  candidateOffset = 0,
} = {}) {
  const candidates = [];
  const seen = new Set();
  if (includeOpen) {
    const rows = projectManager.db.db.prepare(`
      SELECT t.tab_id, t.name, t.cwd, t.command_type, t.tab_type,
             t.claude_session_id, t.codex_session_id, t.created_at,
             p.id AS project_id, p.name AS project_name, p.path AS project_path
        FROM tabs t
        JOIN projects p ON p.id = t.project_id
       WHERE t.claude_session_id IS NOT NULL
          OR t.codex_session_id IS NOT NULL
          OR t.command_type IN ('claude', 'claude-sdk', 'codex')
       ORDER BY COALESCE(t.created_at, 0) DESC, t.id DESC
    `).all();
    for (const row of rows) {
      const isCodex = row.command_type === 'codex' || !!row.codex_session_id;
      let sessionId = isCodex ? row.codex_session_id : row.claude_session_id;
      if (isCodex) {
        const runtime = await getCodexRuntimeSessionSnapshot(row.tab_id, {
          reason: 'terminal-mcp-session-search',
        }).catch(() => null);
        sessionId = runtime?.sessionId || sessionId;
      } else {
        sessionId = bridgeKnownSessions.get(row.tab_id) || sessionId;
      }
      if (!sessionId) continue;
      const candidate = {
        source: 'open',
        status: 'open',
        historyId: null,
        tabId: row.tab_id || null,
        title: row.name || row.tab_id || sessionId,
        projectId: row.project_id,
        projectName: row.project_name || null,
        projectPath: row.project_path || null,
        cwd: row.cwd || row.project_path || null,
        provider: isCodex ? 'codex' : 'claude',
        sessionId,
        createdAt: Number(row.created_at) || null,
        closedAt: null,
      };
      if (!sessionCatalogProjectMatches(candidate, project)) continue;
      if (!sessionMatchesDate(candidate, { dateField, fromMs, toMs })) continue;
      const key = candidate.provider + ':' + candidate.sessionId;
      if (seen.has(key)) continue;
      seen.add(key);
      candidates.push(candidate);
    }
  }
  if (includeClosed) {
    const rows = projectManager.db.db.prepare(`
      SELECT h.id AS history_id, h.tab_id, h.name, h.cwd, h.command_type,
             h.claude_session_id, h.codex_session_id, h.created_at, h.closed_at,
             p.id AS project_id, p.name AS project_name, p.path AS project_path
        FROM tab_history h
        JOIN projects p ON p.id = h.project_id
       WHERE (h.tab_type IS NULL OR h.tab_type != 'file')
         AND (h.claude_session_id IS NOT NULL OR h.codex_session_id IS NOT NULL)
       ORDER BY h.closed_at DESC, h.id DESC
    `).all();
    for (const row of rows) {
      const isCodex = row.command_type === 'codex' || !!row.codex_session_id;
      const sessionId = isCodex ? row.codex_session_id : row.claude_session_id;
      if (!sessionId) continue;
      const candidate = {
        source: 'history',
        status: 'closed',
        historyId: Number(row.history_id) || null,
        tabId: row.tab_id || null,
        title: row.name || row.tab_id || sessionId,
        projectId: row.project_id,
        projectName: row.project_name || null,
        projectPath: row.project_path || null,
        cwd: row.cwd || row.project_path || null,
        provider: isCodex ? 'codex' : 'claude',
        sessionId,
        createdAt: Number(row.created_at) || null,
        closedAt: Number(row.closed_at) || null,
      };
      if (!sessionCatalogProjectMatches(candidate, project)) continue;
      if (!sessionMatchesDate(candidate, { dateField, fromMs, toMs })) continue;
      const key = candidate.provider + ':' + candidate.sessionId;
      if (seen.has(key)) continue;
      seen.add(key);
      candidates.push(candidate);
    }
  }
  candidates.sort((left, right) => (
    Number(right.closedAt || right.createdAt || 0) - Number(left.closedAt || left.createdAt || 0)
  ));
  const limit = Math.max(1, Math.min(250, Number(maxCandidates) || 100));
  const offset = Math.max(0, Number(candidateOffset) || 0);
  return {
    candidates: candidates.slice(offset, offset + limit),
    total: candidates.length,
    offset,
    limit,
  };
}

function sessionCatalogTimestamp(value) {
  const seconds = Number(value);
  return Number.isFinite(seconds) && seconds > 0
    ? new Date(seconds * 1000).toISOString()
    : null;
}

async function searchSessionCatalog(options = {}) {
  const query = String(options.query || '').trim();
  const dateWindow = resolveSearchDateWindow({
    period: options.period,
    dateFrom: options.dateFrom,
    dateTo: options.dateTo,
  });
  const candidatePage = await listSessionCatalogCandidates({
    includeOpen: options.includeOpen !== false,
    includeClosed: options.includeClosed !== false,
    project: options.project || options.projectId || '',
    dateField: options.dateField,
    fromMs: dateWindow.fromMs,
    toMs: dateWindow.toMs,
    maxCandidates: options.maxCandidates,
    candidateOffset: options.candidateOffset,
  });
  const candidates = candidatePage.candidates;
  const maxMatches = Math.max(1, Math.min(200, Number(options.maxMatches) || 50));
  const matchesPerSession = Math.max(1, Math.min(10, Number(options.matchesPerSession) || 3));
  const matches = [];
  const sessions = [];
  const errors = [];

  for (const candidate of candidates) {
    let data;
    try {
      data = await _loadSessionTurns(candidate.sessionId, candidate.cwd);
    } catch (error) {
      errors.push({
        sessionId: candidate.sessionId,
        title: candidate.title,
        error: String(error?.message || error),
      });
      continue;
    }
    const iterations = [];
    for (const turn of data.turns || []) {
      if ((turn.kind !== 'user' && turn.kind !== 'queued_command') || turn.isNoise) continue;
      const userRecord = data.recordMap.get(turn.userUuid);
      const userText = _extractTurnPromptText(userRecord) || '';
      if (!String(userText).trim()) continue;
      const assistant = _collectAssistantBlocks(turn, data.recordMap).text.join('\n\n');
      iterations.push({
        turn,
        userText,
        assistantText: assistant,
      });
    }
    const totalIterations = iterations.length;
    sessions.push({ ...candidate, totalIterations });
    if (!query) continue;

    const sessionMatches = [];
    for (let iterationIndex = 0; iterationIndex < iterations.length; iterationIndex += 1) {
      const iteration = iterations[iterationIndex];
      const match = scoreSessionTurnMatch({
        query,
        title: '',
        userText: iteration.userText,
        assistantText: iteration.assistantText,
      });
      if (!match.matched) continue;
      sessionMatches.push({
        ...candidate,
        iterationIndex,
        totalIterations,
        turnIndex: (data.turns || []).indexOf(iteration.turn),
        entryUuid: iteration.turn.userUuid || null,
        timestamp: iteration.turn.userTimestamp || null,
        matchedIn: match.matchedIn,
        score: match.score,
        userPreview: iteration.userText.slice(0, 500),
        assistantPreview: iteration.assistantText.slice(0, 500),
      });
    }
    if (sessionMatches.length === 0) {
      const titleMatch = scoreSessionTurnMatch({ query, title: candidate.title });
      if (titleMatch.matched) {
        sessionMatches.push({
          ...candidate,
          iterationIndex: null,
          totalIterations,
          turnIndex: null,
          entryUuid: null,
          timestamp: null,
          matchedIn: ['title'],
          score: titleMatch.score,
          userPreview: '',
          assistantPreview: '',
        });
      }
    }
    sessionMatches.sort((left, right) => right.score - left.score || left.iterationIndex - right.iterationIndex);
    matches.push(...sessionMatches.slice(0, matchesPerSession));
  }

  matches.sort((left, right) => (
    right.score - left.score
    || Number(right.closedAt || right.createdAt || 0) - Number(left.closedAt || left.createdAt || 0)
    || Number(left.iterationIndex || 0) - Number(right.iterationIndex || 0)
  ));
  const publicSession = (session) => ({
    status: session.status,
    tabId: session.tabId,
    historyId: session.historyId,
    title: session.title,
    projectId: session.projectId,
    projectName: session.projectName,
    projectPath: session.projectPath,
    cwd: session.cwd,
    provider: session.provider,
    sessionId: session.sessionId,
    createdAt: sessionCatalogTimestamp(session.createdAt),
    closedAt: sessionCatalogTimestamp(session.closedAt),
    totalIterations: session.totalIterations,
  });
  const resultMatches = matches.slice(0, maxMatches).map((match) => ({
    ...publicSession(match),
    iterationIndex: match.iterationIndex,
    turnIndex: match.turnIndex,
    entryUuid: match.entryUuid,
    timestamp: match.timestamp,
    matchedIn: match.matchedIn,
    score: match.score,
    userPreview: match.userPreview,
    assistantPreview: match.assistantPreview,
  }));
  return {
    query,
    period: dateWindow.period,
    dateField: options.dateField || 'activity',
    dateFrom: Number.isFinite(dateWindow.fromMs) ? new Date(dateWindow.fromMs).toISOString() : null,
    dateTo: Number.isFinite(dateWindow.toMs) ? new Date(dateWindow.toMs).toISOString() : null,
    searchedSessions: sessions.length,
    candidateTotal: candidatePage.total,
    candidateOffset: candidatePage.offset,
    candidateLimit: candidatePage.limit,
    hasMoreCandidates: candidatePage.offset + candidates.length < candidatePage.total,
    totalIterationsAcrossSessions: sessions.reduce((sum, session) => sum + session.totalIterations, 0),
    returned: query ? resultMatches.length : sessions.length,
    sessions: query ? undefined : sessions.map(publicSession),
    matches: query ? resultMatches : undefined,
    errors,
  };
}

// Литеральный grep по СЫРЫМ файлам сессий.
//
// `searchSessionCatalog` выше отвечает на «где я это обсуждал» и сравнивает
// только текст промпта и видимый ответ ассистента. Правки файлов туда не
// попадают: `_collectAssistantBlocks` берёт лишь блоки thinking/text, а
// apply_patch, Edit/Write и их вывод остаются за кадром. Поэтому вопрос «какая
// сессия редактировала вот этот символ» тем поиском не решается в принципе, и
// это не настройка порога, а другой источник.
//
// Здесь turn-модель не строится вообще: `_loadSessionTurns` на один rollout в
// сотни мегабайт стоит дороже, чем побайтовый проход по всему корпусу. Файл
// читается чанками, JSON парсится только у совпавших строк.
async function searchTranscriptCatalog(options = {}) {
  const query = String(options.query || '');
  const dateWindow = resolveSearchDateWindow({
    period: options.period,
    dateFrom: options.dateFrom,
    dateTo: options.dateTo,
  });
  if (!query.trim()) {
    return {
      query,
      error: 'query_required',
      matches: [],
      errors: [],
    };
  }
  const candidatePage = await listSessionCatalogCandidates({
    includeOpen: options.includeOpen !== false,
    includeClosed: options.includeClosed !== false,
    project: options.project || options.projectId || '',
    // Окно намеренно НЕ передаётся в каталог: там оно означает дату создания
    // или закрытия вкладки. Здесь оно применяется ниже, по времени записи
    // транскрипта, иначе долгая сессия выпадает из «сегодня» вместе со своей
    // сегодняшней правкой.
    fromMs: null,
    toMs: null,
    maxCandidates: options.maxCandidates,
    candidateOffset: options.candidateOffset,
  });
  const pageCandidates = candidatePage.candidates;
  const maxMatches = Math.max(1, Math.min(200, Number(options.maxMatches) || 50));
  const matchesPerSession = Math.max(1, Math.min(10, Number(options.matchesPerSession) || 3));
  const caseSensitive = options.caseSensitive !== false;
  const requestedKinds = Array.isArray(options.kinds)
    ? options.kinds
    : String(options.kinds || '').split(',').map((value) => value.trim()).filter(Boolean);
  const kinds = requestedKinds.length > 0 ? requestedKinds : null;

  const resolved = await getAgentSessionAvailabilityService().resolveSessionFiles({
    sessions: pageCandidates.map((candidate) => ({
      provider: candidate.provider,
      sessionId: candidate.sessionId,
      tabId: candidate.tabId,
    })),
  });
  const fileBySession = new Map();
  for (const entry of resolved.results || []) {
    if (entry.filePath) fileBySession.set(entry.provider + ':' + entry.sessionId, entry);
  }

  const dateFiltered = await filterByTranscriptWindow({
    candidates: pageCandidates,
    fileBySessionKey: fileBySession,
    fromMs: dateWindow.fromMs,
    toMs: dateWindow.toMs,
  });
  const candidates = dateFiltered.candidates;

  const { matches, errors, unresolved, scannedSessions, bytesScanned } = await collectTranscriptMatches({
    candidates,
    fileBySessionKey: fileBySession,
    query,
    caseSensitive,
    kinds,
    matchesPerSession,
  });

  return {
    query,
    caseSensitive,
    kinds: kinds || null,
    period: dateWindow.period,
    // Явно называем, по какому времени отфильтровано: иначе «за сегодня» с
    // нулём совпадений читается как «правки не было».
    dateBasis: 'transcript-file-mtime',
    dateFrom: Number.isFinite(dateWindow.fromMs) ? new Date(dateWindow.fromMs).toISOString() : null,
    dateTo: Number.isFinite(dateWindow.toMs) ? new Date(dateWindow.toMs).toISOString() : null,
    outsideDateWindow: dateFiltered.dropped,
    scannedSessions,
    scannedMegabytes: Math.round(bytesScanned / (1024 * 1024)),
    // Сколько кандидатов вообще не имеют файла на диске. Это ограничение охвата,
    // а не ошибка: без числа агент прочитает частичную выдачу как полную.
    unresolvedSessions: unresolved.length,
    unresolvedSample: unresolved.slice(0, 5),
    candidateTotal: candidatePage.total,
    candidateOffset: candidatePage.offset,
    candidateLimit: candidatePage.limit,
    hasMoreCandidates: candidatePage.offset + pageCandidates.length < candidatePage.total,
    returned: Math.min(matches.length, maxMatches),
    totalMatches: matches.length,
    matches: matches.slice(0, maxMatches),
    errors,
  };
}

// ── Поиск по промптам ОТКРЫТЫХ вкладок (переключатель Cmd+P) ───────────────
//
// Отдельно от `searchSessionCatalog` выше, и это не дублирование: тот отвечает
// на «найди сессию по всему архиву» (для MCP: закрытые вместе с открытыми,
// диапазоны дат, оценка совпадения), а этот — на «в какой из моих открытых
// вкладок я это писал». Разные вопросы дают разные ответы почти во всём:
//
//   • здесь строка результата = ОДИН промпт, а не сессия с превью лучшего;
//   • здесь нужны смещения совпадений, чтобы подсветить найденное в тексте;
//   • здесь порядок задаёт не оценка, а сама вкладка: результаты сгруппированы
//     по вкладкам, внутри вкладки — по ходу разговора. Буквальный поиск не
//     умеет ранжировать честно, и делать вид, что умеет, значит переставлять
//     строки по причине, которую нельзя объяснить.
//
// Читает ровно те же turn'ы, что Timeline и History (`_loadSessionTurns`), —
// свой парсер разошёлся бы с ними по uuid, и переход «к найденному ходу»
// приводил бы не туда.
const ITERATION_SEARCH_MIN_QUERY = 2;

// Поиск ПОТОКОВЫЙ: каждая вкладка отдаётся отдельным событием, как только
// разобрана. Это не оптимизация, а разница между «десять секунд пустого экрана»
// и «первый ответ через полсекунды». Ждать общего конца незачем — порядок групп
// задаёт свежесть вкладок, она известна заранее, и ни одна поздняя вкладка не
// может переставить уже показанные.
//
// Стоимость решения — второй проход. Запасной режим («не нашлось фразой — ищем
// словами») можно объявить только когда точно известно, что фразы нет НИ В ОДНОЙ
// вкладке; в потоке этот момент наступает в самом конце. Поэтому второй проход
// идёт отдельным событием и помечен как замена, а не добавка: клиент выбрасывает
// показанное и рисует новое. Иначе список молча смешал бы точные совпадения с
// приблизительными.
async function searchOpenTabPrompts(options = {}) {
  const rawQuery = String(options.query || '').trim();
  const targets = Array.isArray(options.targets) ? options.targets : [];
  const emit = typeof options.onTab === 'function' ? options.onTab : null;
  if (rawQuery.length < ITERATION_SEARCH_MIN_QUERY) {
    return { success: true, query: rawQuery, mode: 'phrase', matches: [], total: 0, truncated: false, scanned: 0, errors: [] };
  }
  const maxMatches = Math.max(1, Math.min(500, Number(options.maxMatches) || 200));
  const maxPerTab = Math.max(1, Math.min(100, Number(options.maxPerTab) || 20));
  const startedAt = Date.now();
  const errors = [];

  const scanTab = async (target, mode) => {
    const sessionId = String(target?.sessionId || '');
    const tabId = String(target?.tabId || '');
    if (!sessionId || !tabId) return null;
    let data;
    try {
      data = await _loadSessionTurns(sessionId, target.cwd || null);
    } catch (error) {
      if (mode === 'phrase') {
        errors.push({ tabId, sessionId, error: String(error?.message || error) });
      }
      return null;
    }
    // Разбор сессии — синхронная работа процессора, а вкладок много. Без паузы
    // между ними десяток крупных сессий сложился бы в одну длинную остановку
    // интерфейса: главный процесс всё это время не отвечает ни на клики, ни на
    // ввод в терминале. Пауза между вкладками, а не внутри одной, — дробить
    // разбор одной сессии нечем, он атомарен.
    await new Promise((resolve) => setImmediate(resolve));

    const hits = [];
    let iterationIndex = -1;
    let truncatedHere = false;
    for (let turnIndex = 0; turnIndex < (data.turns || []).length; turnIndex += 1) {
      const turn = data.turns[turnIndex];
      if (!turn || (turn.kind !== 'user' && turn.kind !== 'queued_command')) continue;
      const record = data.recordMap.get(turn.userUuid);
      const text = _extractTurnPromptText(record) || '';
      if (!String(text).trim()) continue;
      // Номер хода считается по ВСЕМ пользовательским промптам вкладки, а не по
      // найденным: «#7» должно означать седьмой промпт разговора, иначе номер
      // меняется от запроса к запросу и перестаёт быть адресом.
      iterationIndex += 1;
      if (turn.isNoise) continue;
      if (hits.length >= maxPerTab) { truncatedHere = true; continue; }
      const offsets = findQueryOffsets(text, rawQuery, mode);
      if (offsets.length === 0) continue;
      const snippet = buildSnippet(text, offsets);
      hits.push({
        tabId,
        sessionId,
        projectId: target.projectId || null,
        toolType: target.toolType === 'codex' ? 'codex' : 'claude',
        entryUuid: turn.userUuid || null,
        turnIndex,
        iterationIndex,
        timestamp: turn.userTimestamp || null,
        matchCount: offsets.length,
        fullText: text,
        fullLines: countLines(text),
        fullOffsets: offsets,
        snippetText: snippet.text,
        snippetOffsets: snippet.offsets,
        snippetHeadTrimmed: snippet.headTrimmed,
        snippetTailTrimmed: snippet.tailTrimmed,
      });
    }
    // Всего промптов во вкладке — знаменатель для «#7/214». Считается ЗДЕСЬ, а
    // не на клиенте: клиент видит только найденное и знаменателя знать не может.
    const totalIterations = iterationIndex + 1;
    for (const hit of hits) hit.totalIterations = totalIterations;
    return { tabId, hits, totalIterations, truncated: truncatedHere };
  };

  const runPass = async (mode, replaces) => {
    const perTab = [];
    let scanned = 0;
    let emitted = 0;
    for (const target of targets) {
      const group = await scanTab(target, mode);
      if (!group) continue;
      scanned += 1;
      if (group.hits.length === 0) continue;
      perTab.push(group);
      if (emitted < maxMatches && emit) {
        // Событие на КАЖДУЮ вкладку с попаданиями — сразу, до конца обхода.
        emit({
          query: rawQuery,
          mode,
          replaces,
          tabId: group.tabId,
          hits: group.hits,
          totalIterations: group.totalIterations,
          truncated: group.truncated,
        });
      }
      emitted += group.hits.length;
    }
    return { perTab, scanned };
  };

  let mode = 'phrase';
  let pass = await runPass('phrase', false);
  if (pass.perTab.length === 0) {
    const words = queryWords(rawQuery);
    if (words.length > 1) {
      mode = 'words';
      // `replaces: true` — второй проход не дополняет первый, а заменяет его.
      // Первый ничего не нашёл, но клиент уже мог показать заголовки; смешать
      // два режима в одном списке значило бы соврать про половину строк.
      pass = await runPass('words', true);
    }
  }

  const matches = [];
  let total = 0;
  for (const group of pass.perTab) {
    total += group.hits.length;
    for (const hit of group.hits) {
      if (matches.length < maxMatches) matches.push(hit);
    }
  }
  console.log('[IterationSearch] query=' + JSON.stringify(rawQuery)
    + ' mode=' + mode
    + ' tabs=' + targets.length
    + ' scanned=' + pass.scanned
    + ' tabsWithHits=' + pass.perTab.length
    + ' matches=' + total
    + ' returned=' + matches.length
    + ' errors=' + errors.length
    + ' ms=' + (Date.now() - startedAt));
  return {
    success: true,
    query: rawQuery,
    mode,
    matches,
    total,
    truncated: total > matches.length,
    scanned: pass.scanned,
    errors,
  };
}

ipcMain.handle('iteration-search:open-tabs', async (event, payload = {}) => {
  // Номер запроса задаёт КЛИЕНТ и присылает обратно в каждом событии: ответы
  // приходят порознь, человек к этому времени уже дописал строку, и без номера
  // поздний кусок старого поиска дорисовался бы в свежий список.
  const requestId = String(payload.requestId || '');
  const sender = event?.sender;
  try {
    return await searchOpenTabPrompts({
      ...payload,
      onTab: requestId && sender && !sender.isDestroyed()
        ? (chunk) => {
          if (sender.isDestroyed()) return;
          sender.send('iteration-search:chunk', { requestId, ...chunk });
        }
        : null,
    });
  } catch (error) {
    console.warn('[IterationSearch] failed: ' + (error?.message || error));
    return { success: false, error: String(error?.message || error), matches: [], total: 0 };
  }
});

async function handleOverseerRequest(rawUrl) {
  const url = new URL(rawUrl, 'http://localhost');
  const p = url.pathname; // e.g. /overseer/sessions

  if (p === '/overseer/search-sessions') {
    const result = await searchSessionCatalog({
      query: url.searchParams.get('query') || '',
      project: url.searchParams.get('project') || url.searchParams.get('projectId') || '',
      period: url.searchParams.get('period') || '',
      dateField: url.searchParams.get('dateField') || 'activity',
      dateFrom: url.searchParams.get('dateFrom'),
      dateTo: url.searchParams.get('dateTo'),
      includeOpen: url.searchParams.get('includeOpen') !== '0',
      includeClosed: url.searchParams.get('includeClosed') !== '0',
      maxCandidates: url.searchParams.get('maxCandidates'),
      candidateOffset: url.searchParams.get('candidateOffset'),
      maxMatches: url.searchParams.get('maxMatches'),
      matchesPerSession: url.searchParams.get('matchesPerSession'),
    });
    console.log('[MCP:SessionSearch] query=' + JSON.stringify(result.query)
      + ' period=' + (result.period || '-')
      + ' sessions=' + result.searchedSessions
      + ' returned=' + result.returned
      + ' errors=' + result.errors.length);
    return { body: result };
  }

  if (p === '/overseer/search-transcripts') {
    const result = await searchTranscriptCatalog({
      query: url.searchParams.get('query') || '',
      project: url.searchParams.get('project') || url.searchParams.get('projectId') || '',
      period: url.searchParams.get('period') || '',
      dateFrom: url.searchParams.get('dateFrom'),
      dateTo: url.searchParams.get('dateTo'),
      includeOpen: url.searchParams.get('includeOpen') !== '0',
      includeClosed: url.searchParams.get('includeClosed') !== '0',
      caseSensitive: url.searchParams.get('caseSensitive') !== '0',
      kinds: url.searchParams.get('kinds') || '',
      maxCandidates: url.searchParams.get('maxCandidates'),
      candidateOffset: url.searchParams.get('candidateOffset'),
      maxMatches: url.searchParams.get('maxMatches'),
      matchesPerSession: url.searchParams.get('matchesPerSession'),
    });
    console.log('[MCP:TranscriptGrep] query=' + JSON.stringify(result.query)
      + ' kinds=' + (Array.isArray(result.kinds) ? result.kinds.join('|') : '-')
      + ' sessions=' + result.scannedSessions
      + ' scannedMB=' + result.scannedMegabytes
      + ' matches=' + (result.totalMatches || 0)
      + ' unresolved=' + (result.unresolvedSessions || 0)
      + ' errors=' + (result.errors || []).length);
    return { body: result };
  }

  if (p === '/overseer/sessions') {
    // Live tabs from DB (any project) with a known Claude/Codex sessionId.
    // bridgeKnownSessions wins over DB column (it reflects the currently active
    // CLI process, which may be a fork of the persisted id).
    const rows = projectManager.db.db.prepare(`
      SELECT t.tab_id, t.name, t.cwd, t.claude_session_id, t.gemini_session_id,
             t.codex_session_id, t.command_type,
             t.context_pct,
             t.created_at, p.path AS project_path, p.name AS project_title
      FROM tabs t LEFT JOIN projects p ON p.id = t.project_id
      WHERE t.tab_id IS NOT NULL
        AND (
          t.claude_session_id IS NOT NULL
          OR t.codex_session_id IS NOT NULL
          OR t.command_type IN ('claude', 'claude-sdk', 'codex')
        )
      ORDER BY t.created_at DESC
    `).all();

    const sessions = [];
    for (const r of rows) {
      const tabId = r.tab_id;
      const isCodex = r.command_type === 'codex' || !!r.codex_session_id || codexKnownSessions.has(tabId);
      const codexRuntime = isCodex
        ? await getCodexRuntimeSessionSnapshot(tabId, { reason: 'overseer-sessions-query' })
        : null;
      const provenCodexWriter = codexRuntime?.provenWriterSessionId || null;
      const codexWriterUsable = codexRuntime?.writerUsableForMutation === true;
      const sessionId = isCodex
        ? (codexRuntime?.sessionId || null)
        : (bridgeKnownSessions.get(tabId) || r.claude_session_id || null);
      if (!sessionId && !isCodex) continue;
      const isLive = isCodex ? codexRuntime?.liveLifecycle === true : terminals.has(tabId);
      const bridgeMeta = !isCodex ? (bridgeMetadata.get(tabId) || null) : null;
      const codexContextMeta = isCodex && sessionId
        ? agentContextUsageState.read(tabId, { provider: 'codex', sessionId })
        : null;
      const bridgeContextPct = bridgeMeta && typeof bridgeMeta.contextPct === 'number'
        ? bridgeMeta.contextPct
        : null;
      const persistedContextPct = typeof r.context_pct === 'number'
        ? r.context_pct
        : null;
      const liveContextPct = isCodex
        ? (codexContextMeta?.contextPct ?? null)
        : bridgeContextPct;
      const rawContextPct = typeof liveContextPct === 'number'
        ? liveContextPct
        : persistedContextPct;
      const contextUsedPct = typeof rawContextPct === 'number' && Number.isFinite(rawContextPct) && rawContextPct >= 0
        ? Math.min(100, Math.max(0, rawContextPct))
        : null;
      const model = bridgeMeta && bridgeMeta.model && bridgeMeta.model !== 'unknown'
        ? bridgeMeta.model
        : null;
      const codexTurnState = isCodex ? (codexTurnWatchers.get(tabId) || null) : null;
      const claudeLastEvent = !isCodex ? (claudeHookLastEvent.get(tabId) || null) : null;
      const claudeTurn = !isCodex && claudeTurnBusy.get(tabId) === true;
      const claudeSpinner = !isCodex && claudeSpinnerBusy.get(tabId) === true;
      const claudeLocal = !isCodex && claudeLocalCommandWatchers.has(tabId);
      const codexTurn = isCodex && codexTurnState?.busy === true;
      const sdkTurn = !isCodex && r.command_type === 'claude-sdk' && sdkSessions.has(tabId);
      // The animated Claude glyph is diagnostic only. It is not a turn
      // boundary and must not project BUSY through Terminal MCP/session lists.
      const busySources = [];
      if (claudeTurn) busySources.push('claude-turn');
      if (claudeLocal) busySources.push('claude-local-command');
      if (codexTurn) busySources.push('codex-turn');
      if (sdkTurn) busySources.push('claude-sdk');
      const isBusy = isCodex ? codexRuntime?.busy === true : busySources.length > 0;
      const sessionStatus = isCodex
        ? (codexRuntime?.sessionStatus === 'inactive' ? 'closed' : (codexRuntime?.sessionStatus || 'unknown'))
        : (isBusy ? 'busy' : (isLive ? 'active' : 'closed'));
      let claudeLastEventTs = null;
      if (!isCodex && claudeLastEvent?.ts) {
        const d = new Date(claudeLastEvent.ts);
        if (!Number.isNaN(d.getTime())) claudeLastEventTs = d.toISOString();
      }
      sessions.push({
        tabId,
        tabName: r.name,
        sessionId,
        savedSessionId: isCodex ? (r.codex_session_id || null) : (r.claude_session_id || null),
        writerConfirmed: isCodex ? !!provenCodexWriter : !!bridgeKnownSessions.get(tabId),
        writerUsableForMutation: isCodex ? codexWriterUsable : !!bridgeKnownSessions.get(tabId),
        writerStatus: isCodex ? (codexRuntime?.writerStatus || null) : null,
        liveLifecycle: isCodex ? (codexRuntime?.liveLifecycle ?? null) : isLive,
        engine: isCodex ? 'codex' : 'claude',
        status: sessionStatus,
        busy: isBusy,
        busySources,
        spinnerVisible: claudeSpinner,
        turnBusy: claudeTurn || codexTurn || sdkTurn,
        lastEventType: isCodex ? (codexTurnState?.lastEventType || null) : (claudeLastEvent?.event || null),
        lastEventTs: isCodex ? (codexTurnState?.lastEventTs || null) : claudeLastEventTs,
        model,
        contextUsedPct,
        contextRemainingPct: contextUsedPct == null ? null : Math.max(0, 100 - contextUsedPct),
        contextSource: contextUsedPct == null
          ? null
          : (typeof liveContextPct === 'number' ? (isCodex ? 'rollout' : 'bridge') : 'persisted'),
        cwd: terminalProjects.get(tabId) || r.cwd,
        projectPath: r.project_path || null,
        projectTitle: r.project_title || null,
        commandType: r.command_type || (isCodex ? 'codex' : 'claude'),
        isLive,
        createdAt: r.created_at || null,
      });
    }
    console.log('[MCP:Overseer] GET /overseer/sessions found=' + sessions.length);
    return { body: { sessions } };
  }

  // /overseer/session/:sessionId/...
  const m = p.match(/^\/overseer\/session\/([0-9a-f-]+)(\/.+)?$/i);
  if (!m) return { status: 404, body: { error: 'Unknown overseer route' } };
  const sessionId = m[1];
  const subpath = m[2] || '';
  const cwd = url.searchParams.get('cwd') || null;

  const data = await _loadSessionTurns(sessionId, cwd);
  const sessionHistoryProjection = (subpath === '/stats' || subpath === '' || subpath === '/turns')
    ? await _reconcileSessionHistoryEvents(data, cwd)
    : null;

  if (subpath === '/progress') {
    const progress = buildSessionProgress({
      sessionId,
      turns: data.turns,
      cursor: url.searchParams.get('cursor') || null,
      limit: url.searchParams.get('limit'),
    });
    return {
      body: {
        sessionId,
        engine: data.engine || 'claude',
        branchLength: data.branchLength,
        ...progress,
      },
    };
  }

  if (subpath === '/stats' || subpath === '') {
    // Aggregate counts so the agent can decide whether the session is worth
    // pulling turn-by-turn.
    let userTurns = 0, queuedCommandTurns = 0, compactSummaries = 0, compactBoundaries = 0;
    let totalUserChars = 0, totalThinkingChars = 0, totalTextChars = 0;
    let toolUseCount = 0, noisePromptCount = 0;
    let firstTs = null, lastTs = null;
    let largestUserTurn = { turnIndex: -1, chars: 0 };
    let largestThinkingTurn = { turnIndex: -1, chars: 0 };
    for (let i = 0; i < data.turns.length; i++) {
      const t = data.turns[i];
      if (t.userTimestamp) {
        if (!firstTs) firstTs = t.userTimestamp;
        lastTs = t.userTimestamp;
      }
      if (t.kind === 'user' || t.kind === 'queued_command') {
        userTurns++;
        if (t.kind === 'queued_command') queuedCommandTurns++;
        totalUserChars += t.userChars;
        if (t.isNoise) noisePromptCount++;
        if (t.userChars > largestUserTurn.chars) largestUserTurn = { turnIndex: i, chars: t.userChars };
      } else if (t.kind === 'compact_summary') {
        compactSummaries++;
        totalUserChars += t.userChars;
      } else if (t.kind === 'compact_boundary') {
        compactBoundaries++;
      }
      const tch = (t.thinkingBlocks || []).reduce((s, b) => s + b.chars, 0);
      const txc = (t.textBlocks || []).reduce((s, b) => s + b.chars, 0);
      totalThinkingChars += tch;
      totalTextChars += txc;
      toolUseCount += (t.toolUses || []).length;
      if (tch > largestThinkingTurn.chars) largestThinkingTurn = { turnIndex: i, chars: tch };
    }
    // Annotation counts — user-authored notes (purple), rewind markers (pink),
    // turns where docs/ or CLAUDE.md was edited (green Docs-update dot). These
    // are the persistent anchors the user actually navigates by.
    let docsEditedTurns = 0, docsSearchTurns = 0;
    for (const t of data.turns) {
      if (t.docsEdited && t.docsEdited.length) docsEditedTurns++;
      if (t.docsSearchQueries && t.docsSearchQueries.length) docsSearchTurns++;
    }
    return { body: {
      sessionId,
      filePath: data.filePath,
      sizeBytes: data.size,
      branchLength: data.branchLength,
      turnCount: data.turns.length,
      totalIterations: sessionHistoryProjection?.totalIterations ?? Math.max(0, userTurns - noisePromptCount),
      userTurns,
      queuedCommandTurns,
      compactSummaries,
      compactBoundaries,
      noisePromptCount,
      totalChars: { user: totalUserChars, assistantThinking: totalThinkingChars, assistantText: totalTextChars },
      toolUseCount,
      firstTimestamp: firstTs,
      lastTimestamp: lastTs,
      largestUserTurn,
      largestThinkingTurn,
      noteCount: data.notesByTurn.size,
      orphanNoteCount: data.orphanNotes.length,
      rewindMarkerCount: data.rewindByTurn.size,
      docsEditedTurns,
      docsSearchTurns,
      historyEvents: _sessionHistoryContextForApi(sessionHistoryProjection?.historyEvents),
      appRelations: sessionHistoryProjection?.appRelations || { openTabs: [], archivedTabs: [] },
      reconciliationError: sessionHistoryProjection?.reconciliationError || undefined,
    }};
  }

  if (subpath === '/notes') {
    // Dedicated endpoint for navigation by user anchors. Returns notes in
    // chronological turn order, each joined with the turn it sits on (so the
    // agent can answer "what was happening between note A and note B").
    const sorted = [];
    for (const [idx, note] of data.notesByTurn) {
      const t = data.turns[idx];
      if (!t) continue;
      sorted.push({
        turnIndex: idx,
        entryUuid: note.entryUuid,
        content: note.content,
        position: note.position, // 'before' | 'dot' | 'after'
        createdAt: note.createdAt,
        updatedAt: note.updatedAt,
        turnTimestamp: t.userTimestamp,
        turnKind: t.kind,
        turnPreview: (() => {
          if (t.kind === 'compact_boundary') return null;
          const rec = data.recordMap.get(t.userUuid);
          const txt = _extractTurnPromptText(rec) || '';
          return txt.slice(0, 160);
        })(),
      });
    }
    sorted.sort((a, b) => a.turnIndex - b.turnIndex);

    const rewindMarkers = [];
    for (const [idx, m] of data.rewindByTurn) {
      const t = data.turns[idx];
      if (!t) continue;
      rewindMarkers.push({
        turnIndex: idx,
        entryUuid: m.entryUuid,
        createdAt: m.createdAt,
        turnTimestamp: t.userTimestamp,
      });
    }
    rewindMarkers.sort((a, b) => a.turnIndex - b.turnIndex);

    return { body: {
      sessionId,
      notes: sorted,
      rewindMarkers,
      orphanNotes: data.orphanNotes,
    }};
  }

  if (subpath === '/turns') {
    const limit = Math.min(parseInt(url.searchParams.get('limit') || '50', 10) || 50, 500);
    const offset = Math.max(parseInt(url.searchParams.get('offset') || '0', 10) || 0, 0);
    const from = ['latest_compact', 'end', 'start'].includes(url.searchParams.get('from'))
      ? url.searchParams.get('from')
      : 'start';
    const includeNoise = url.searchParams.get('includeNoise') === '1';
    const kindFilter = url.searchParams.get('kind') || null; // user | queued_command | compact_summary | compact_boundary

    const coordinated = decorateTurnsWithIterationCoordinates(data.turns);
    const items = [];
    for (let i = 0; i < coordinated.turns.length; i++) {
      const t = coordinated.turns[i];
      if (kindFilter && t.kind !== kindFilter) continue;
      if (!includeNoise && t.kind === 'user' && t.isNoise) continue;
      const note = data.notesByTurn.get(i);
      const rewindMarker = data.rewindByTurn.get(i);
      items.push({
        turnIndex: i,
        iterationIndex: t.iterationIndex ?? null,
        afterIterationIndex: t.afterIterationIndex ?? null,
        nextIterationIndex: t.nextIterationIndex ?? null,
        compactEventIdentity: t.compactEventIdentity || undefined,
        compactPart: t.compactPart || undefined,
        kind: t.kind,
        timestamp: t.userTimestamp,
        userUuid: t.userUuid,
        userChars: t.userChars,
        userPreview: t.kind === 'user' || t.kind === 'queued_command' || t.kind === 'compact_summary'
          ? (() => {
              const rec = data.recordMap.get(t.userUuid);
              const txt = _extractTurnPromptText(rec) || '';
              return txt.slice(0, 220);
            })()
          : null,
        thinkingBlocks: (t.thinkingBlocks || []).map(b => ({ idx: b.idx, chars: b.chars })),
        textBlocks: (t.textBlocks || []).map(b => ({ idx: b.idx, chars: b.chars })),
        toolUses: (t.toolUses || []),
        hasToolResults: !!t.hasToolResults,
        model: t.assistantModel || null,
        preTokens: t.preTokens || undefined,
        postTokens: t.postTokens || undefined,
        trigger: t.trigger || undefined,
        // Annotations: user-authored note attached to this turn (purple),
        // rewind marker (pink dot from previous edit-range), docs-related
        // signals (green dot for any /docs/ or CLAUDE.md edit in this turn).
        note: note ? { content: note.content, position: note.position } : undefined,
        rewindMarker: rewindMarker ? true : undefined,
        docsEdited: t.docsEdited && t.docsEdited.length ? t.docsEdited : undefined,
        docsSearchQueries: t.docsSearchQueries && t.docsSearchQueries.length ? t.docsSearchQueries : undefined,
      });
    }
    const sourceTotal = items.length;
    let windowItems = items;
    let windowStart = 0;
    if (from === 'latest_compact') {
      const compactIndex = items.findLastIndex((item) => (
        item.kind === 'compact_summary' || item.kind === 'compact_boundary'
      ));
      if (compactIndex >= 0) {
        windowStart = compactIndex;
        windowItems = items.slice(compactIndex);
      } else {
        windowStart = Math.max(0, items.length - limit);
        windowItems = items.slice(windowStart);
      }
    } else if (from === 'end') {
      windowStart = Math.max(0, items.length - limit - offset);
      windowItems = items.slice(windowStart, Math.max(windowStart, items.length - offset));
    }
    const total = windowItems.length;
    const page = from === 'end'
      ? windowItems
      : windowItems.slice(offset, offset + limit);
    return { body: {
      sessionId,
      from,
      sourceTotal,
      totalIterations: coordinated.totalIterations,
      windowStartTurnIndex: items[windowStart]?.turnIndex ?? null,
      total,
      returned: page.length,
      offset,
      limit,
      turns: page,
    }};
  }

  // /overseer/session/:id/turn/:idx/(user|thinking|text)
  const tm = subpath.match(/^\/turn\/(\d+)\/(user|thinking|text)$/);
  if (tm) {
    const turnIndex = parseInt(tm[1], 10);
    const part = tm[2];
    const turn = data.turns[turnIndex];
    if (!turn) return { status: 404, body: { error: `turnIndex ${turnIndex} out of range (have ${data.turns.length})` } };
    const start = url.searchParams.has('start') ? parseInt(url.searchParams.get('start'), 10) : null;
    const end = url.searchParams.has('end') ? parseInt(url.searchParams.get('end'), 10) : null;
    const blockParam = url.searchParams.has('block') ? parseInt(url.searchParams.get('block'), 10) : null;

    if (part === 'user') {
      const rec = data.recordMap.get(turn.userUuid);
      const txt = _extractTurnPromptText(rec) || '';
      const sliced = _sliceText(txt, start, end);
      return { body: {
        sessionId, turnIndex, part, totalChars: txt.length,
        kind: turn.kind,
        start: start, end: end,
        text: sliced,
      }};
    }

    // thinking / text — collect blocks then either return one or array of all
    const { thinking, text } = _collectAssistantBlocks(turn, data.recordMap);
    const blocks = part === 'thinking' ? thinking : text;
    if (blockParam != null) {
      const b = blocks[blockParam];
      if (b == null) return { status: 404, body: { error: `block ${blockParam} out of range (have ${blocks.length})` } };
      return { body: {
        sessionId, turnIndex, part, blockIndex: blockParam,
        totalChars: b.length, start, end,
        text: _sliceText(b, start, end),
      }};
    }
    // No specific block requested → return array of {idx, chars, preview}
    // plus a `full` field carrying the joined content under a range slice
    // (so the agent can pull all blocks of one part with a single call when
    // they are small).
    const joined = blocks.join('\n\n[--- block break ---]\n\n');
    return { body: {
      sessionId, turnIndex, part,
      blockCount: blocks.length,
      blocks: blocks.map((b, i) => ({ idx: i, chars: b.length, preview: b.slice(0, 200) })),
      joinedTotalChars: joined.length,
      joinedText: (start != null || end != null) ? _sliceText(joined, start, end) : undefined,
    }};
  }

  // Evidence is intentionally a second, addressable pull. `/turns` remains a
  // compact navigation map and this route never returns every transcript tool
  // result by accident. Without operationId it returns a small operation map;
  // with one exact id it returns bounded input/result evidence for that call.
  const evidenceMatch = subpath.match(/^\/turn\/(\d+)\/evidence$/);
  if (evidenceMatch) {
    const turnIndex = parseInt(evidenceMatch[1], 10);
    const turn = data.turns[turnIndex];
    if (!turn) {
      return { status: 404, body: { error: `turnIndex ${turnIndex} out of range (have ${data.turns.length})` } };
    }
    const requestedOperationId = String(url.searchParams.get('operationId') || '').trim() || null;
    const requestedMaxChars = parseInt(url.searchParams.get('maxChars') || '12000', 10);
    const maxChars = Math.max(256, Math.min(64 * 1024,
      Number.isFinite(requestedMaxChars) ? requestedMaxChars : 12000));
    const parseOffset = (name) => {
      if (!url.searchParams.has(name)) return null;
      const value = parseInt(url.searchParams.get(name), 10);
      return Number.isFinite(value) ? value : null;
    };
    const operationOffset = Math.max(0, parseOffset('operationOffset') || 0);
    const requestedOperationLimit = parseOffset('operationLimit');
    const operationLimit = Math.max(1, Math.min(200,
      requestedOperationLimit == null ? 50 : requestedOperationLimit));
    const evidence = await _buildTurnEvidence(data, turn, cwd);
    const operations = Array.isArray(evidence.operations) ? evidence.operations : [];
    const evidenceSourceSnapshot = data.engine === 'codex'
      ? (evidence.sourceSnapshot || null)
      : (data.sourceSnapshot || null);
    const evidenceContentRevision = data.engine === 'codex'
      ? (evidence.contentRevision || null)
      : (data.contentRevision || null);
    if (requestedOperationId) {
      const operation = operations.find((candidate) => candidate?.operationId === requestedOperationId);
      if (!operation) {
        return {
          status: 404,
          body: {
            error: 'operation_not_found_in_turn',
            sessionId,
            turnIndex,
            operationId: requestedOperationId,
          },
        };
      }
      return { body: {
        sessionId,
        turnIndex,
        provider: data.engine || 'claude',
        userUuid: turn.userUuid || null,
        timestamp: turn.userTimestamp || null,
        settings: evidence.settings || { status: 'unknown' },
        operation: _normalizeEvidenceOperation(operation, {
          maxChars,
          detail: true,
          inputStart: parseOffset('inputStart'),
          inputEnd: parseOffset('inputEnd'),
          resultStart: parseOffset('resultStart'),
          resultEnd: parseOffset('resultEnd'),
        }),
        sourceSnapshot: evidenceSourceSnapshot,
        contentRevision: evidenceContentRevision,
      }};
    }
    const mapOperations = operations.slice(operationOffset, operationOffset + operationLimit)
      .map((operation) => _normalizeEvidenceOperation(operation, { maxChars: 240 }));
    return { body: {
      sessionId,
      turnIndex,
      provider: data.engine || 'claude',
      userUuid: turn.userUuid || null,
      timestamp: turn.userTimestamp || null,
      found: evidence.found !== false,
      ...(evidence.reason ? { reason: evidence.reason } : {}),
      settings: evidence.settings || { status: 'unknown' },
      operationCount: operations.length,
      operationOffset,
      operationLimit,
      operations: mapOperations,
      nextOperationOffset: operationOffset + mapOperations.length < operations.length
        ? operationOffset + mapOperations.length
        : null,
      operationsTruncated: operationOffset + mapOperations.length < operations.length,
      sourceSnapshot: evidenceSourceSnapshot,
      contentRevision: evidenceContentRevision,
    }};
  }

  return { status: 404, body: { error: 'Unknown overseer subpath: ' + subpath } };
}

// ─── Overseer mutations (fork / propose_edit / apply_edit) ────────────────────
// Wraps claude-data.js _api so the overseer agent never edits JSONL directly.
// propose_edit is a dry-run — computes which records would be removed using the
// same backtrace + forward-expand logic as the real edit-range, without touching
// disk. apply_edit invokes editRange or deleteRange. fork wraps forkSessionFile.

async function _resolveSessionFile(sessionId, cwd) {
  const located = findSessionFile(sessionId, cwd);
  if (!located) {
    const err = new Error(`Session ${sessionId} not found on disk`);
    err.status = 404;
    throw err;
  }
  return located;
}

async function _rejectUnsupportedOverseerMutation(sessionId, cwd, operation) {
  if (findSessionFile(sessionId, cwd)) return null;
  try {
    const loaded = await codexDataModule?._api?.loadSessionRecords?.(sessionId, cwd);
    if (loaded?.success) {
      return {
        status: 400,
        body: {
          error: `${operation} is Claude-only. Codex sessions are exposed through Overseer for read/navigation and through Terminal MCP for live start/send/stop, not JSONL rewrite.`,
          engine: 'codex',
          supported: ['read', 'terminal:start_ai', 'terminal:send_prompt', 'terminal:stop_ai'],
        },
      };
    }
  } catch {}
  return null;
}

// Mirror of edit-range's forward-expand logic but **read-only**.
// Returns: { removeUuids: Set, actualEnd: number, branch: array, entryBefore, entryAfter }
function _computeEditRangePlan(sessionId, cwd, startUuid, endUuid) {
  const located = findSessionFile(sessionId, cwd);
  if (!located) throw Object.assign(new Error(`Session ${sessionId} not found`), { status: 404 });
  const content = fs.readFileSync(located.filePath, 'utf-8');
  const lines = content.split('\n').filter(l => l.trim());
  const allRecords = [];
  const recordMap = new Map();
  for (const line of lines) {
    try {
      const e = JSON.parse(line);
      allRecords.push(e);
      if (e?.uuid) recordMap.set(e.uuid, e);
    } catch {}
  }
  const lastRecord = allRecords.filter(r => r?.uuid).pop();
  if (!lastRecord) throw new Error('Session has no records');

  const fileIndexMap = new Map();
  allRecords.forEach((r, i) => { if (r?.uuid) fileIndexMap.set(r.uuid, i); });

  const branch = [];
  let cur = lastRecord.uuid;
  const seen = new Set();
  while (cur && !seen.has(cur)) {
    seen.add(cur);
    const rec = recordMap.get(cur);
    if (!rec) break;
    branch.unshift(rec);
    cur = rec.logicalParentUuid || rec.parentUuid;
  }

  const startIdx = branch.findIndex(e => e.uuid === startUuid);
  const endIdx = branch.findIndex(e => e.uuid === endUuid);
  if (startIdx === -1 || endIdx === -1) {
    throw Object.assign(new Error(`Range UUIDs not in active branch (start=${startIdx}, end=${endIdx})`), { status: 400 });
  }
  const rangeStart = Math.min(startIdx, endIdx);
  const rangeEnd = Math.max(startIdx, endIdx);

  const removeUuids = new Set();
  for (let i = rangeStart; i <= rangeEnd; i++) removeUuids.add(branch[i].uuid);
  // forward-expand
  for (let i = rangeEnd + 1; i < branch.length; i++) {
    const e = branch[i];
    if (e.type === 'assistant' || e.type === 'system' || e.type === 'progress') {
      removeUuids.add(e.uuid);
    } else if (e.type === 'user') {
      const c = e.message?.content;
      const isToolResult = Array.isArray(c) && c.some(b => b.type === 'tool_result');
      const isTaskNotif = typeof c === 'string' && c.startsWith('<task-notification>');
      if (isToolResult || isTaskNotif) removeUuids.add(e.uuid);
      else break;
    } else {
      removeUuids.add(e.uuid);
    }
  }

  let actualEnd = rangeEnd;
  for (let i = rangeEnd + 1; i < branch.length; i++) {
    if (removeUuids.has(branch[i].uuid)) actualEnd = i;
    else break;
  }

  const entryBefore = rangeStart > 0 ? branch[rangeStart - 1] : null;
  const entryAfter = actualEnd < branch.length - 1 ? branch[actualEnd + 1] : null;

  let removedUsers = 0, removedAssistants = 0, removedOther = 0;
  let removedUserChars = 0, removedAssistantChars = 0;
  for (const uuid of removeUuids) {
    const e = recordMap.get(uuid);
    if (!e) continue;
    if (e.type === 'user') {
      removedUsers++;
      const c = e.message?.content;
      if (typeof c === 'string') removedUserChars += c.length;
      else if (Array.isArray(c)) {
        for (const b of c) {
          if (typeof b?.text === 'string') removedUserChars += b.text.length;
        }
      }
    } else if (e.type === 'assistant') {
      removedAssistants++;
      const arr = e.message?.content;
      if (Array.isArray(arr)) {
        for (const b of arr) {
          if (typeof b?.text === 'string') removedAssistantChars += b.text.length;
          else if (typeof b?.thinking === 'string') removedAssistantChars += b.thinking.length;
        }
      }
    } else {
      removedOther++;
    }
  }

  return {
    filePath: located.filePath,
    branchLength: branch.length,
    rangeStart, rangeEnd, actualEnd,
    removedCount: removeUuids.size,
    removedUsers, removedAssistants, removedOther,
    removedUserChars, removedAssistantChars,
    entryBeforeUuid: entryBefore?.uuid || null,
    entryBeforeType: entryBefore?.type || null,
    entryAfterUuid: entryAfter?.uuid || null,
    entryAfterType: entryAfter?.type || null,
    firstRemovedUuid: branch[rangeStart].uuid,
    firstRemovedType: branch[rangeStart].type,
    firstRemovedPreview: _extractUserText(branch[rangeStart])?.slice(0, 200) || null,
    lastRemovedUuid: branch[actualEnd].uuid,
    lastRemovedType: branch[actualEnd].type,
    nearTip: actualEnd >= branch.length - 3,
  };
}

async function handleOverseerMutation(rawUrl, payload) {
  const url = new URL(rawUrl, 'http://localhost');
  const p = url.pathname;

  if (p === '/overseer/fork') {
    const { sessionId, cwd } = payload;
    if (!sessionId) return { status: 400, body: { error: 'sessionId required' } };
    const unsupported = await _rejectUnsupportedOverseerMutation(sessionId, cwd, 'fork');
    if (unsupported) return unsupported;
    if (!claudeDataApi || !claudeDataApi.forkSessionFile) {
      return { status: 500, body: { error: 'claudeDataApi not initialised (register() not called yet)' } };
    }
    // skipChainResolve:true — overseer-fork is explicit, don't follow plan-mode bridges
    const result = await claudeDataApi.forkSessionFile({ sourceSessionId: sessionId, cwd, skipChainResolve: true });
    console.log('[MCP:Overseer] /fork sessionId=' + sessionId.slice(0,8) + ' → ' + (result.newSessionId?.slice(0,8) || 'FAILED'));
    return { body: result };
  }

  if (p === '/overseer/propose-edit') {
    const { sessionId, cwd, startUuid, endUuid, mode } = payload;
    if (!sessionId || !startUuid || !endUuid) {
      return { status: 400, body: { error: 'sessionId, startUuid, endUuid required' } };
    }
    if (!mode || !['compact', 'delete'].includes(mode)) {
      return { status: 400, body: { error: 'mode must be "compact" or "delete"' } };
    }
    const unsupported = await _rejectUnsupportedOverseerMutation(sessionId, cwd, 'propose_edit');
    if (unsupported) return unsupported;
    const plan = _computeEditRangePlan(sessionId, cwd, startUuid, endUuid);
    plan.mode = mode;
    plan.sessionId = sessionId;
    plan.startUuid = startUuid;
    plan.endUuid = endUuid;
    console.log('[MCP:Overseer] /propose-edit mode=' + mode + ' would remove ' + plan.removedCount + ' records (' +
      plan.removedUsers + ' user, ' + plan.removedAssistants + ' assistant)');
    return { body: { plan } };
  }

  if (p === '/overseer/apply-edit') {
    const { sessionId, cwd, startUuid, endUuid, mode, compactText, autoFork } = payload;
    if (!sessionId || !startUuid || !endUuid) {
      return { status: 400, body: { error: 'sessionId, startUuid, endUuid required' } };
    }
    if (!mode || !['compact', 'delete'].includes(mode)) {
      return { status: 400, body: { error: 'mode must be "compact" or "delete"' } };
    }
    if (mode === 'compact' && !compactText) {
      return { status: 400, body: { error: 'compactText required for mode="compact"' } };
    }
    const unsupported = await _rejectUnsupportedOverseerMutation(sessionId, cwd, 'apply_edit');
    if (unsupported) return unsupported;
    if (!claudeDataApi || !claudeDataApi.editRange || !claudeDataApi.deleteRange) {
      return { status: 500, body: { error: 'claudeDataApi not initialised' } };
    }

    let workingSessionId = sessionId;
    let forkResult = null;
    if (autoFork) {
      forkResult = await claudeDataApi.forkSessionFile({ sourceSessionId: sessionId, cwd, skipChainResolve: true, operationKind: mode === 'delete' ? 'delete' : 'edit' });
      if (!forkResult.success) {
        return { status: 500, body: { error: 'Auto-fork failed: ' + forkResult.error } };
      }
      workingSessionId = forkResult.newSessionId;
      console.log('[MCP:Overseer] /apply-edit auto-fork: ' + sessionId.slice(0,8) + ' → ' + workingSessionId.slice(0,8));
    }

    const editResult = mode === 'compact'
      ? await claudeDataApi.editRange({ sessionId: workingSessionId, cwd, startUuid, endUuid, compactText })
      : await claudeDataApi.deleteRange({ sessionId: workingSessionId, cwd, startUuid, endUuid });

    console.log('[MCP:Overseer] /apply-edit ' + mode + ' on ' + workingSessionId.slice(0,8) + ' → ' + JSON.stringify(editResult).slice(0, 200));

    // Invalidate overseer turns cache for the edited session (file mtime changed,
    // but explicit clear avoids one stale read).
    _deleteOverseerTurnsCache('claude:' + workingSessionId);

    return { body: {
      mode,
      sourceSessionId: sessionId,
      workingSessionId,
      wasForked: !!autoFork,
      forkResult: forkResult || undefined,
      editResult,
    }};
  }

  return { status: 404, body: { error: 'Unknown overseer mutation: ' + p } };
}

function emitTerminalMcpActivity(action, details = {}) {
  const id = details.id || ('mcp-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8));
  const { id: _ignoredId, ...rest } = details;
  const event = {
    id,
    at: Date.now(),
    action,
    status: 'ok',
    ...rest,
  };
  try {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('terminal:mcp-activity', event);
    }
  } catch (e) {
    console.warn('[MCP:Terminal] failed to emit activity:', e.message);
  }
  return id;
}

function rendererBridgeRequestForMcp(action, payload, timeoutMs = 60_000) {
  return new Promise((resolve, reject) => {
    if (!mainWindow || mainWindow.isDestroyed()) {
      reject(new Error('renderer bridge unavailable'));
      return;
    }
    const requestId = 'mcp-bridge-' + Date.now() + '-' + crypto.randomBytes(4).toString('hex');
    let settled = false;
    const cleanup = () => {
      clearTimeout(timer);
      ipcMain.removeListener('web:bridge-reply', onReply);
    };
    const finish = (err, data) => {
      if (settled) return;
      settled = true;
      cleanup();
      if (err) reject(err);
      else resolve(data);
    };
    const onReply = (_event, msg = {}) => {
      if (!msg || msg.requestId !== requestId) return;
      if (msg.ok === false) {
        finish(new Error(msg.error || 'renderer bridge request failed'));
      } else {
        finish(null, msg.data);
      }
    };
    const timer = setTimeout(() => {
      finish(new Error('renderer bridge timeout for ' + action));
    }, Math.max(1000, Number(timeoutMs) || 60_000));
    ipcMain.on('web:bridge-reply', onReply);
    mainWindow.webContents.send('web:bridge-request', { requestId, action, payload });
  });
}

function startMcpHttpServer() {
  mcpHttpServer = http.createServer(async (req, res) => {
    // CORS headers for local requests
    res.setHeader('Content-Type', 'application/json');

    // Resolve which project owns `tabId`. Preference:
    //   1. live map terminalProjectIds — set when PTY was spawned with explicit projectId.
    //   2. SQLite — DB row tabs.project_id (covers tabs whose PTY died and respawn
    //      paths that lost the env).
    // Returns null if unknown.
    // Used by /terminal/* handlers below to validate cross-project tabId access.
    // MUST live at callback-scope, not inside an else-if branch, so every handler
    // can see it (else: ReferenceError on /terminal/output etc. when caller pins parentProjectId).
    const resolveProjectForTab = (tabId, projectIdHint = null) => {
      if (typeof tabId !== 'string' || !tabId) return null;
      const live = terminalProjectIds.get(tabId);
      if (live) return live;
      try {
        if (projectIdHint) {
          const row = projectManager.db.db.prepare(
            'SELECT project_id FROM tabs WHERE project_id = ? AND tab_id = ? LIMIT 1'
          ).get(projectIdHint, tabId);
          return row?.project_id || null;
        }
        const rows = projectManager.db.db.prepare(
          'SELECT DISTINCT project_id FROM tabs WHERE tab_id = ? ORDER BY project_id'
        ).all(tabId);
        if (rows.length === 1) return rows[0].project_id || null;
      } catch {}
      return null;
    };

    const routeRejectsPinnedProject = (tabId, parentProjectId, routeName) => {
      if (!parentProjectId) return null;
      const scopedOwner = resolveProjectForTab(tabId, parentProjectId);
      if (scopedOwner === parentProjectId) return null;
      const owner = resolveProjectForTab(tabId);
      console.warn('[MCP:Terminal] ' + routeName + ' rejected: tab ' + tabId
        + ' does not exist in pinned project ' + parentProjectId
        + ' owner=' + (owner || 'unknown-or-ambiguous'));
      return {
        error: 'tab does not belong to the requested project',
        owner: owner || null,
        requested: parentProjectId,
      };
    };

    const detectAiEngineForTab = async (tabId, projectIdHint = null) => {
      let row = null;
      try {
        const projectId = resolveProjectForTab(tabId, projectIdHint);
        if (projectId) {
          row = projectManager.db.db.prepare(
            'SELECT command_type, claude_session_id, gemini_session_id, codex_session_id FROM tabs WHERE project_id = ? AND tab_id = ? LIMIT 1'
          ).get(projectId, tabId);
        }
      } catch {}
      if (row?.command_type === 'codex' || codexKnownSessions.has(tabId) || row?.codex_session_id) return 'codex';
      if (row?.command_type === 'claude' || row?.command_type === 'claude-sdk' || hasLiveClaudeInTab(tabId) || row?.claude_session_id) return 'claude';
      if (row?.command_type === 'gemini' || geminiActiveTabs.has(tabId) || row?.gemini_session_id) return 'gemini';
      const codexMatches = await findAiDescendantProcessesByTab(tabId, 'codex');
      if (codexMatches.length > 0) return 'codex';
      const claudeMatches = await findAiDescendantProcessesByTab(tabId, 'claude');
      if (claudeMatches.length > 0) return 'claude';
      const geminiMatches = await findAiDescendantProcessesByTab(tabId, 'gemini');
      if (geminiMatches.length > 0) return 'gemini';
      return null;
    };

    // ========== TERMINAL MANAGEMENT ENDPOINTS ==========
    // resolveProjectForTab is declared at callback scope above (see top of startMcpHttpServer).
    if (req.method === 'GET' && req.url?.startsWith('/terminal/tabs')) {
      // List terminal tabs for a project (by parentProjectId — preferred — or cwd path)
      (async () => {
        try {
          const urlObj = new URL(req.url, 'http://localhost');
          const parentProjectId = urlObj.searchParams.get('parentProjectId') || '';
          const projectPath = urlObj.searchParams.get('cwd') || '';
          const colorFilter = urlObj.searchParams.get('color') || '';

          if (!parentProjectId && !projectPath) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'parentProjectId or cwd parameter is required' }));
            return;
          }

          // parentProjectId wins. Resolves project by id (authoritative). Falls
          // back to cwd-path match only when id missing or unknown.
          let project = null;
          if (parentProjectId) {
            project = projectManager.db.db.prepare(
              'SELECT * FROM projects WHERE id = ? LIMIT 1'
            ).get(parentProjectId);
          }
          if (!project && projectPath) {
            project = projectManager.db.db.prepare(
              'SELECT * FROM projects WHERE path = ? ORDER BY updated_at DESC LIMIT 1'
            ).get(projectPath);
          }

          if (!project) {
            res.writeHead(200);
            res.end(JSON.stringify({ tabs: [] }));
            return;
          }

          // Get tabs from DB
          const dbTabs = projectManager.db.db.prepare(
            'SELECT * FROM tabs WHERE project_id = ? ORDER BY position'
          ).all(project.id);
          // A tab list is a passive projection, not a writer reconciliation.
          // Use the same event-owned batch as Project API: per-tab snapshots
          // perform process/rollout I/O and make large projects time out.
          const codexRuntimeByTab = getCodexRuntimeProjectionBatch(
            dbTabs
              .filter(t => t.tab_id && t.command_type === 'codex' && (!colorFilter || t.color === colorFilter))
              .map(t => ({ tabId: t.tab_id, savedSessionId: t.codex_session_id || null })),
            project.id,
          );

          const tabs = [];
          for (const t of dbTabs) {
            const tabId = t.tab_id;
            if (!tabId) continue;

            // Filter by color if requested
            if (colorFilter && t.color !== colorFilter) continue;

            const pty = terminals.get(tabId);
            const cmdState = terminalCommandState.get(tabId);
            const commandType = t.command_type || 'generic';
            const claudeSessionId = bridgeKnownSessions.get(tabId) || t.claude_session_id || null;
            const codexRuntime = commandType === 'codex'
              ? codexRuntimeByTab[tabId] || null
              : null;
            const codexSessionId = codexRuntime?.sessionId || null;
            const geminiSessionId = t.gemini_session_id || null;
            const sessionId = commandType === 'codex'
              ? codexSessionId
              : commandType === 'gemini'
                ? geminiSessionId
                : commandType === 'claude' || commandType === 'claude-sdk'
                  ? claudeSessionId
                  : (codexSessionId || claudeSessionId || geminiSessionId);

            tabs.push({
              tabId,
              name: t.name,
              color: t.color || 'default',
              commandType,
              sessionId,
              claudeSessionId,
              geminiSessionId,
              codexSessionId,
              codexSavedSessionId: t.codex_session_id || null,
              codexWriterConfirmed: codexRuntime?.writerConfirmed === true,
              codexWriterUsableForMutation: codexRuntime?.writerUsableForMutation === true,
              codexWriterStatus: codexRuntime?.writerStatus || null,
              codexLiveLifecycle: codexRuntime?.liveLifecycle ?? null,
              sessionStatus: codexRuntime?.sessionStatus || null,
              aiBusy: t.ai_busy === 1 || t.ai_busy === true,
              cwd: terminalProjects.get(tabId) || t.cwd,
              isAlive: !!pty,
              pid: pty ? pty.pid : null,
              isRunning: commandType === 'codex'
                ? codexRuntime?.liveLifecycle === true
                : (cmdState ? cmdState.isRunning : false),
              processLookupUnknown: commandType === 'codex'
                ? codexRuntime?.liveLifecycle === null
                : false,
              initialCommand: terminalInitialCommand.get(tabId) || null,
            });
          }

          console.log('[MCP:HTTP] GET /terminal/tabs projectId=' + (parentProjectId || project.id) + ' project=' + (project.path || '') + ' color=' + colorFilter + ' found=' + tabs.length);
          res.writeHead(200);
          res.end(JSON.stringify({ tabs }));
        } catch (e) {
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      })();

    } else if (req.method === 'GET' && req.url?.startsWith('/terminal/tab-plan')) {
      try {
        const urlObj = new URL(req.url, 'http://localhost');
        const tabId = urlObj.searchParams.get('tabId') || '';
        const parentProjectId = urlObj.searchParams.get('parentProjectId') || '';
        if (!tabId) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'tabId is required' }));
          return;
        }
        const rejected = routeRejectsPinnedProject(tabId, parentProjectId, '/terminal/tab-plan');
        if (rejected) {
          res.writeHead(403);
          res.end(JSON.stringify(rejected));
          return;
        }
        const row = projectManager.db.db.prepare(
          'SELECT project_id, name, cwd FROM tabs WHERE tab_id = ? LIMIT 1'
        ).get(tabId);
        if (!row) {
          res.writeHead(404);
          res.end(JSON.stringify({ error: 'tab not found' }));
          return;
        }
        const marker = projectManager.db.getAppState('noted-terminal-task-status-marker')
          || projectManager.db.getAppState('noted-terminal-status-marker')
          || { shape: 'dot', sizePx: 8 };
        res.writeHead(200);
        res.end(JSON.stringify({
          tab: { tabId, projectId: row.project_id, name: row.name, cwd: row.cwd },
          plan: projectManager.db.getTabTaskPlan(tabId),
          taskStatuses: getTaskStatusCatalog(),
          taskStatusMarker: marker,
        }));
      } catch (error) {
        res.writeHead(500);
        res.end(JSON.stringify({ error: error?.message || String(error) }));
      }

    } else if (req.method === 'POST' && req.url === '/terminal/tab-plan/apply') {
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', () => {
        try {
          const payload = body ? JSON.parse(body) : {};
          const { tabId, operations, parentProjectId } = payload;
          if (!tabId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId is required' }));
            return;
          }
          const rejected = routeRejectsPinnedProject(tabId, parentProjectId, '/terminal/tab-plan/apply');
          if (rejected) {
            res.writeHead(403);
            res.end(JSON.stringify(rejected));
            return;
          }
          const result = projectManager.db.applyTabTaskPlanOperations(tabId, operations, 'terminal-mcp');
          if (result.changed) {
            broadcastTabTaskPlan(tabId, result.document, 'terminal-mcp');
            console.log('[TaskPlan:MCP] apply tab=' + String(tabId).slice(-12) + ' revision=' + result.document.revision + ' operations=' + operations.length);
          }
          res.writeHead(200);
          res.end(JSON.stringify({ success: true, ...result }));
        } catch (error) {
          console.warn('[TaskPlan:MCP] apply failed: ' + (error?.message || error));
          res.writeHead(/not_found/.test(error?.message || '') ? 404 : 400);
          res.end(JSON.stringify({ error: error?.message || String(error) }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/restart') {
      // Soft restart: Ctrl+C → wait for prompt return (OSC 133;A) → re-run command
      // Same approach as UI restart button in TabBar.tsx. Shell stays alive.
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { tabId, command, parentProjectId, sourceMeta } = JSON.parse(body);
          if (!tabId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId is required' }));
            return;
          }

          if (parentProjectId) {
            const owner = resolveProjectForTab(tabId);
            if (owner && owner !== parentProjectId) {
              console.warn('[MCP:Terminal] /terminal/restart rejected: tab ' + tabId + ' belongs to project ' + owner + ', caller pinned ' + parentProjectId);
              res.writeHead(403);
              res.end(JSON.stringify({ error: 'tab does not belong to the requested project', owner, requested: parentProjectId }));
              return;
            }
          }

          const term = terminals.get(tabId);
          if (!term) {
            res.writeHead(404);
            res.end(JSON.stringify({ error: 'Terminal not alive for tab ' + tabId }));
            return;
          }

          const restartCmd = command || terminalInitialCommand.get(tabId);
          if (!restartCmd) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'No saved command for this tab. Pass "command" parameter explicitly.' }));
            return;
          }

          console.log('[MCP:Terminal] POST /terminal/restart tabId=' + tabId + ' cmd=' + restartCmd);
          activityId = emitTerminalMcpActivity('restart_process', {
            status: 'running',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            commandPreview: String(restartCmd).slice(0, 120),
            sourceMeta: sourceMeta || null,
          });

          const cmdState = terminalCommandState.get(tabId);
          const wasRunning = cmdState && cmdState.isRunning;

          // Step 1: Ctrl+C to stop current process (harmless if nothing running)
          term.write('\x03');

          if (wasRunning) {
            // Step 2: Wait for prompt return — OSC 133;D (command finished) then 133;A (prompt ready)
            // This is deterministic: no fixed timeouts for process shutdown.
            // Electron/Vite may take seconds to gracefully stop — we wait for the shell.
            await new Promise((resolve) => {
              let done = false;
              const check = setInterval(() => {
                const state = terminalCommandState.get(tabId);
                if (!state || !state.isRunning) {
                  clearInterval(check);
                  if (!done) { done = true; resolve(); }
                }
              }, 200);
              // Safety: 30s for very slow shutdowns (Electron graceful exit)
              setTimeout(() => { clearInterval(check); if (!done) { done = true; resolve(); } }, 30000);
            });

            // Small delay for shell prompt to fully render
            await new Promise(r => setTimeout(r, 300));
          }

          // Step 3: Re-run command
          term.write(restartCmd + '\r');
          emitTerminalMcpActivity('restart_process', {
            id: activityId,
            status: 'restarted',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            commandPreview: String(restartCmd).slice(0, 120),
            sourceMeta: sourceMeta || null,
          });

          res.writeHead(200);
          res.end(JSON.stringify({ status: 'restarted', tabId, command: restartCmd }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('restart_process', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/stop') {
      // Stop the foreground script/devServer while keeping the tab/shell alive.
      // External callers (Voice Record build-install preflight) need the same
      // behavior as the desktop Stop button: deterministic child-process stop,
      // not /terminal/kill which closes the PTY tab.
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        try {
          const { tabId, parentProjectId } = JSON.parse(body || '{}');
          if (!tabId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId is required' }));
            return;
          }

          const projectReject = routeRejectsPinnedProject(tabId, parentProjectId, '/terminal/stop');
          if (projectReject) {
            res.writeHead(403);
            res.end(JSON.stringify(projectReject));
            return;
          }

          console.log('[MCP:Terminal] POST /terminal/stop tabId=' + tabId);
          const result = await deterministicStopTerminal(tabId, false);
          res.writeHead(result?.success ? 200 : 500);
          res.end(JSON.stringify({ status: result?.success ? 'stopped' : 'error', tabId, ...result }));
        } catch (e) {
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/run') {
      // Run a command in an existing terminal tab
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { tabId, command, parentProjectId, sourceMeta } = JSON.parse(body);
          if (!tabId || !command) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId and command are required' }));
            return;
          }

          if (parentProjectId) {
            const owner = resolveProjectForTab(tabId);
            if (owner && owner !== parentProjectId) {
              console.warn('[MCP:Terminal] /terminal/run rejected: tab ' + tabId + ' belongs to project ' + owner + ', caller pinned ' + parentProjectId);
              res.writeHead(403);
              res.end(JSON.stringify({ error: 'tab does not belong to the requested project', owner, requested: parentProjectId }));
              return;
            }
          }

          const pty = terminals.get(tabId);
          if (!pty) {
            res.writeHead(404);
            res.end(JSON.stringify({ error: 'Terminal not alive for tab ' + tabId }));
            return;
          }

          console.log('[MCP:Terminal] POST /terminal/run tabId=' + tabId + ' cmd="' + command.substring(0, 80) + '"');
          activityId = emitTerminalMcpActivity('run_command', {
            status: 'running',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            commandPreview: String(command).slice(0, 120),
            sourceMeta: sourceMeta || null,
          });

          // Send command + Enter to PTY
          pty.write(command + '\r');
          emitTerminalMcpActivity('run_command', {
            id: activityId,
            status: 'sent',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            commandPreview: String(command).slice(0, 120),
            sourceMeta: sourceMeta || null,
          });

          res.writeHead(200);
          res.end(JSON.stringify({ status: 'sent', tabId }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('run_command', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/ai-prompt') {
      // Send/paste prompt to a live AI TUI via the same safe path as History/Replay.
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        const requestReceivedAt = nodePerformance.now();
        try {
          const { tabId, prompt, submit = true, parentProjectId, sourceMeta } = JSON.parse(body);
          if (!tabId || typeof prompt !== 'string') {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId and prompt are required' }));
            return;
          }

          const projectReject = routeRejectsPinnedProject(tabId, parentProjectId, '/terminal/ai-prompt');
          if (projectReject) {
            res.writeHead(403);
            res.end(JSON.stringify(projectReject));
            return;
          }

          const term = terminals.get(tabId);
          if (!term) {
            res.writeHead(404);
            res.end(JSON.stringify({ error: 'Terminal not alive for tab ' + tabId }));
            return;
          }

          // Retain the physical destination before engine/process discovery
          // yields. A queued draft must not adopt a replacement shell or run.
          const originalDraftTarget = submit === false ? captureClaudeDraftPasteTarget(tabId) : null;
          let claudeDraftPasteAdmission = null;
          let claudeProcessMatches = null;
          const engine = await detectAiEngineForTab(tabId, parentProjectId);
          if (!engine) {
            res.writeHead(409);
            res.end(JSON.stringify({ error: 'No live AI session detected in tab ' + tabId }));
            return;
          }

          if (engine === 'codex') {
            if (submit !== false) {
              const ready = await ensureCodexInputReadyForExternalPrompt(tabId, {
                reason: 'mcp-ai-prompt',
                timeoutMs: CODEX_EXTERNAL_PROMPT_READY_TIMEOUT_MS,
              });
              if (!ready?.success) {
                console.log('[MCP:Terminal] POST /terminal/ai-prompt codex not ready tabId=' + tabId
                  + ' reason=' + (ready?.reason || ready?.error || 'unknown')
                  + ' waitedMs=' + (ready?.waitedMs ?? '-')
                  + ' blockers=' + (Array.isArray(ready?.blockers) ? ready.blockers.join(',') : '-'));
                res.writeHead(409);
                res.end(JSON.stringify({
                  status: 'not_ready',
                  error: 'codex_not_input_ready',
                  reason: ready?.reason || ready?.error || 'unknown',
                  blockers: ready?.blockers || undefined,
                  ready: ready?.ready || undefined,
                  waitedMs: ready?.waitedMs || 0,
                }));
                return;
              }
            }
          } else if (engine === 'claude') {
            if (!hasLiveClaudeInTab(tabId)) {
              const candidates = await findAiDescendantProcessesByTab(tabId, 'claude');
              claudeProcessMatches = candidates;
              if (candidates.length === 0) {
                res.writeHead(409);
                res.end(JSON.stringify({ error: 'no_claude_session' }));
                return;
              }
            }
          } else if (engine === 'gemini') {
            const candidates = await findAiDescendantProcessesByTab(tabId, 'gemini');
            if (candidates.length === 0 && !geminiActiveTabs.has(tabId)) {
              res.writeHead(409);
              res.end(JSON.stringify({ error: 'no_gemini_session' }));
              return;
            }
          }

          if (engine === 'claude' && submit === false) {
            let currentTarget = captureClaudeDraftPasteTarget(tabId);
            if (!originalDraftTarget?.processId && !currentTarget.processId) {
              claudeProcessMatches ||= await findAiDescendantProcessesByTab(tabId, 'claude');
              currentTarget = captureClaudeDraftPasteTarget(tabId);
            }
            const admission = createClaudeDraftPasteAdmission(
              originalDraftTarget, currentTarget, claudeProcessMatches || [],
            );
            const validation = admission.available
              ? validateClaudeDraftPasteAtBoundary(admission.token, term)
              : { valid: false, reason: admission.reason };
            if (!validation.valid) {
              res.writeHead(409);
              res.end(JSON.stringify({ status: 'failed', tabId, engine, result: {
                success: false, accepted: false, submitted: false,
                pasteWritten: false, enterWritten: false, error: validation.reason,
              } }));
              return;
            }
            claudeDraftPasteAdmission = admission.token;
          }

          activityId = emitTerminalMcpActivity('send_prompt', {
            status: submit === false ? 'pasting' : 'sending',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            engine,
            promptChars: prompt.length,
            sourceMeta: sourceMeta || null,
          });

          if ((engine === 'claude' || engine === 'codex') && submit !== false) {
            // One shared send scenario for both agents. The direct
            // safePasteAndSubmit path below remains only for paste-without-
            // submit and for Gemini, which has no scenario runtime yet —
            // otherwise this MCP route would be the last Codex entrypoint
            // bypassing the launch/readiness/handoff contract.
            let result;
            try {
              result = await rendererBridgeRequestForMcp('sendAgentPromptScenario', {
                tabId,
                prompt,
                source: engine === 'codex' ? 'codex-mcp-ai-prompt' : 'mcp-ai-prompt',
                queue: false,
              }, 60_000);
            } catch (bridgeError) {
              const message = String(bridgeError?.message || bridgeError);
              if (/bridge timeout/i.test(message)) {
                // The renderer scenario keeps running after this deadline
                // (launch-if-needed + readiness + paste can legitimately
                // outlive it) and may still deliver the prompt. Answering
                // 500 here invites a blind client retry — a duplicate in a
                // live AI session, which is worse than an unknown status.
                console.warn('[MCP:Terminal] POST /terminal/ai-prompt bridge timeout tabId=' + tabId
                  + ' engine=' + engine + ' → 202 delivery_unknown (do not retry blindly)');
                const timeoutProjection = projectLegacyAiPromptReceipt({
                  success: null, submitted: null, status: 'delivery-unknown', deliveryUnknown: true,
                });
                emitTerminalMcpActivity('send_prompt', {
                  id: activityId,
                  status: timeoutProjection.activityStatus,
                  tabId,
                  targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
                  engine,
                  promptChars: prompt.length,
                  sourceMeta: sourceMeta || null,
                  error: 'bridge_timeout_delivery_unknown',
                });
                res.writeHead(timeoutProjection.httpStatus);
                res.end(JSON.stringify({
                  status: timeoutProjection.status,
                  error: 'bridge_timeout_delivery_unknown',
                  warning: 'The send scenario may still complete in the app; do not retry the same prompt without checking the session history first.',
                  tabId,
                  engine,
                }));
                return;
              }
              throw bridgeError;
            }
            const projection = projectLegacyAiPromptReceipt(result);
            const success = projection.success;
            const responseStatus = projection.status;
            console.log('[MCP:Terminal] POST /terminal/ai-prompt tabId=' + tabId + ' engine=' + engine + ' submit=true chars=' + prompt.length + ' status=' + responseStatus + ' success=' + success + ' via=scenario');
            emitTerminalMcpActivity('send_prompt', {
              id: activityId,
              status: projection.activityStatus,
              tabId,
              targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
              engine,
              promptChars: prompt.length,
              sourceMeta: sourceMeta || null,
              error: success === false ? (result?.error || 'sendAgentPromptScenario failed') : undefined,
            });
            res.writeHead(projection.httpStatus);
            res.end(JSON.stringify({
              status: responseStatus,
              tabId,
              engine,
              result,
            }));
            return;
          }

          const result = await safePasteAndSubmit(term, prompt, {
            submit: submit !== false,
            ctrlCFirst: false,
            stashFirst: false,
            claudeDraftPasteAdmission,
            fast: engine !== 'claude' && engine !== 'codex',
            source: engine === 'codex' ? 'codex-mcp-ai-prompt' : 'mcp-ai-prompt',
            skipRenderWait: engine === 'codex',
            awaitCodexUserMessageAudit: engine === 'codex' && submit !== false,
            codexAuditTimeoutMs: CODEX_PASTE_AUDIT_TIMEOUT_MS,
            verifyCodexVisibleDraftBeforeSubmit: engine === 'codex' && submit !== false,
            requestReceivedAt: engine === 'codex' ? requestReceivedAt : null,
            logPrefix: '[MCP:Terminal:ai-prompt:' + engine + ':' + tabId + ']',
          });
          const projection = projectLegacyAiPromptReceipt(result, { submit: submit !== false });
          const success = projection.success;
          const responseStatus = projection.status;
          console.log('[MCP:Terminal] POST /terminal/ai-prompt tabId=' + tabId + ' engine=' + engine + ' submit=' + (submit !== false) + ' chars=' + prompt.length + ' status=' + responseStatus + ' success=' + success);
          emitTerminalMcpActivity('send_prompt', {
            id: activityId,
            status: projection.activityStatus,
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            engine,
            promptChars: prompt.length,
            sourceMeta: sourceMeta || null,
            error: success === false ? (result?.error || 'safePasteAndSubmit failed') : undefined,
          });
          res.writeHead(projection.httpStatus);
          res.end(JSON.stringify({
            status: responseStatus,
            tabId,
            engine,
            result,
          }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('send_prompt', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/ai-stop') {
      // Stop an AI process without closing the shell tab.
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { tabId, parentProjectId, sourceMeta } = JSON.parse(body);
          if (!tabId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId is required' }));
            return;
          }
          const projectReject = routeRejectsPinnedProject(tabId, parentProjectId, '/terminal/ai-stop');
          if (projectReject) {
            res.writeHead(403);
            res.end(JSON.stringify(projectReject));
            return;
          }
          activityId = emitTerminalMcpActivity('stop_ai', {
            status: 'running',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            sourceMeta: sourceMeta || null,
          });
          const result = await stopAiProcessInTabSerialized(tabId);
          console.log('[MCP:Terminal] POST /terminal/ai-stop tabId=' + tabId + ' success=' + (result?.success === true) + ' process=' + (result?.processName || 'unknown'));
          emitTerminalMcpActivity('stop_ai', {
            id: activityId,
            status: result?.success === false ? 'not_stopped' : 'stopped',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            engine: result?.processName || undefined,
            sourceMeta: sourceMeta || null,
            error: result?.success === false ? (result?.error || 'not stopped') : undefined,
          });
          res.writeHead(result?.success === false ? 409 : 200);
          res.end(JSON.stringify({
            status: result?.success === false ? 'not_stopped' : 'stopped',
            tabId,
            ...result,
          }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('stop_ai', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/ai-start') {
      // Start/resume an AI process in an existing shell tab using app-native launch hooks.
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { tabId, agent, sessionId, mode, cwd, parentProjectId, model, effort, startupTimeoutMs, sourceMeta } = JSON.parse(body);
          const engine = String(agent || '').toLowerCase();
          if (!tabId || !['claude', 'codex', 'gemini'].includes(engine)) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId and agent=claude|codex|gemini are required' }));
            return;
          }
          if (engine === 'claude' || engine === 'codex') {
            try {
              assertAgentProviderModel({ provider: engine, model });
            } catch (validationError) {
              res.writeHead(Number(validationError?.statusCode) || 400);
              res.end(JSON.stringify({
                success: false,
                submitted: false,
                code: validationError?.code || 'agent_model_provider_mismatch',
                error: String(validationError?.message || validationError),
                tabId,
                agent: engine,
              }));
              return;
            }
          }
          const projectReject = routeRejectsPinnedProject(tabId, parentProjectId, '/terminal/ai-start');
          if (projectReject) {
            res.writeHead(403);
            res.end(JSON.stringify(projectReject));
            return;
          }
          const term = terminals.get(tabId);
          if (!term) {
            res.writeHead(404);
            res.end(JSON.stringify({ error: 'Terminal not alive for tab ' + tabId }));
            return;
          }

          const termCwd = cwd || terminalProjects.get(tabId);
          const startReadyTimeoutMs = Math.max(
            5_000,
            Math.min(120_000, Number(startupTimeoutMs) || 60_000),
          );
          let commandText = '';

          if (engine === 'codex') {
            if (mode === 'fork' && !sessionId) {
              res.writeHead(400);
              res.end(JSON.stringify({ error: 'Codex fork requires sessionId' }));
              return;
            }
            const command = mode === 'fork'
              ? 'codex-f'
              : mode === 'new'
                ? 'codex'
                : sessionId
                ? 'codex-c'
                : 'codex';
            activityId = emitTerminalMcpActivity('start_ai', {
              status: 'running',
              tabId,
              targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
              engine,
              mode: mode || (sessionId ? 'continue' : 'new'),
              resumeSourceSessionId: command === 'codex' ? null : (sessionId || null),
              sourceMeta: sourceMeta || null,
            });
            const runResult = await runCodexCommandFromPayload(
              mainWindow?.webContents || { send: () => {} },
              {
                tabId,
                command,
                sessionId: command === 'codex' ? null : (sessionId || null),
                cwd: termCwd,
                model,
                effort,
                settingsIntent: model && effort ? 'next-launch' : undefined,
              },
            );
            const launchStatus = runResult?.success === false
              ? 'error'
              : (runResult?.acceptancePending === true ? 'starting' : 'started');
            // A rejected shell admission must not turn the saved tab into a
            // Codex tab. `run-command` is the authority for whether launch
            // bytes reached a proven-idle shell; persist the UI metadata only
            // after that boundary accepts it.
            if (runResult?.success !== false) {
              _markTerminalAsAiTab(tabId, engine, mode === 'new' ? null : (sessionId || null));
            }
            let readyStatus = null;
            if (runResult?.success !== false) {
              try {
                readyStatus = await waitForMainAgentStartReady(
                  tabId,
                  engine,
                  startReadyTimeoutMs,
                );
              } catch (readyError) {
                const statusCode = readyError?.code === 'codex_auth_required'
                  || readyError?.code === 'agent_startup_defaults_failed'
                  ? 409
                  : 504;
                emitTerminalMcpActivity('start_ai', {
                  id: activityId,
                  status: 'error',
                  tabId,
                  targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
                  engine,
                  sourceMeta: sourceMeta || null,
                  error: readyError?.message || 'agent_ready_timeout',
                });
                res.writeHead(statusCode);
                res.end(JSON.stringify({
                  ...runResult,
                  status: 'not_ready',
                  success: false,
                  ready: false,
                  tabId,
                  agent: engine,
                  error: readyError?.code || 'agent_ready_timeout',
                  detail: readyError?.message || String(readyError),
                  runtime: readyError?.status || null,
                }));
                return;
              }
            }
            emitTerminalMcpActivity('start_ai', {
              id: activityId,
              status: runResult?.success === false ? launchStatus : 'started',
              tabId,
              targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
              engine,
              mode: mode || (sessionId ? 'continue' : 'new'),
              sessionId: runResult?.sessionId || null,
              resumeSourceSessionId: runResult?.resumeSourceSessionId || null,
              writerConfirmed: runResult?.writerConfirmed === true,
              sourceMeta: sourceMeta || null,
              error: runResult?.success === false ? (runResult.error || 'codex_start_failed') : undefined,
            });
            console.log('[MCP:Terminal] POST /terminal/ai-start tabId=' + tabId
              + ' engine=codex mode=' + (mode || (sessionId ? 'continue' : 'new'))
              + ' success=' + (runResult?.success !== false)
              + ' writer=' + (runResult?.sessionId ? String(runResult.sessionId).slice(0, 8) : 'pending'));
            res.writeHead(runResult?.success === false ? 409 : 200);
            res.end(JSON.stringify({
              ...runResult,
              status: runResult?.success === false
                ? 'not_started'
                : 'started',
              ready: runResult?.success !== false && readyStatus?.inputReady === true,
              inputReady: runResult?.success !== false && readyStatus?.inputReady === true,
              acceptancePending: runResult?.success === false
                ? runResult?.acceptancePending === true
                : false,
              tabId,
              agent: engine,
              mode: mode || (sessionId ? 'continue' : 'new'),
            }));
            return;
          } else if (engine === 'claude') {
            if (mode === 'fork') {
              res.writeHead(400);
              res.end(JSON.stringify({ error: 'Claude fork requires create_tab with command "claude-f <sessionId>" so the existing fork machinery can copy JSONL safely.' }));
              return;
            }
            activityId = emitTerminalMcpActivity('start_ai', {
              status: 'running',
              tabId,
              targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
              engine,
              mode: mode || (sessionId ? 'continue' : 'new'),
              sessionId: mode === 'new' ? null : (sessionId || null),
              sourceMeta: sourceMeta || null,
            });
            const claudeCommand = sessionId && mode !== 'new' ? 'claude-c' : 'claude';
            const requestedStartupIntent = normalizeClaudeStartupIntent({
              type: 'anthropic',
              startupModel: model,
              startupEffort: effort,
            });
            if (requestedStartupIntent) {
              updateProviderOptionsForTab(tabId, {
                ...(requestedStartupIntent.model ? { startupModel: requestedStartupIntent.model } : {}),
                ...(requestedStartupIntent.effort ? { startupEffort: requestedStartupIntent.effort } : {}),
              });
            }
            const runResult = await runClaudeCommandSerialized(
              { sender: mainWindow?.webContents || { send: () => {} } },
              {
                tabId,
                command: claudeCommand,
                sessionId: claudeCommand === 'claude-c' ? sessionId : null,
                cdTo: claudeCommand === 'claude-c' ? termCwd : null,
              },
            );
            // Keep an existing interrupted/session binding intact when the
            // launch is rejected. A fresh binding is saved only after main has
            // accepted the Ctrl+C + command write at the shell boundary.
            if (runResult?.success !== false) {
              _markTerminalAsAiTab(tabId, engine, mode === 'new' ? null : (sessionId || null));
            }
            let readyStatus = null;
            if (runResult?.success !== false) {
              try {
                readyStatus = await waitForMainAgentStartReady(
                  tabId,
                  engine,
                  startReadyTimeoutMs,
                );
              } catch (readyError) {
                const statusCode = readyError?.code === 'agent_startup_defaults_failed' ? 409 : 504;
                emitTerminalMcpActivity('start_ai', {
                  id: activityId,
                  status: 'error',
                  tabId,
                  targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
                  engine,
                  sourceMeta: sourceMeta || null,
                  error: readyError?.message || 'agent_ready_timeout',
                });
                res.writeHead(statusCode);
                res.end(JSON.stringify({
                  ...runResult,
                  status: 'not_ready',
                  success: false,
                  ready: false,
                  tabId,
                  agent: engine,
                  error: readyError?.code || 'agent_ready_timeout',
                  detail: readyError?.message || String(readyError),
                  runtime: readyError?.status || null,
                }));
                return;
              }
            }
            emitTerminalMcpActivity('start_ai', {
              id: activityId,
              status: runResult?.success === false ? 'error' : 'started',
              tabId,
              targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
              engine,
              mode: mode || (sessionId ? 'continue' : 'new'),
              sessionId: runResult?.sessionId || null,
              sourceMeta: sourceMeta || null,
              error: runResult?.success === false ? (runResult.error || 'claude_start_failed') : undefined,
            });
            res.writeHead(runResult?.success === false ? 409 : 200);
            res.end(JSON.stringify({
              ...runResult,
              status: runResult?.success === false ? 'not_started' : 'started',
              ready: runResult?.success !== false && readyStatus?.inputReady === true,
              inputReady: runResult?.success !== false && readyStatus?.inputReady === true,
              tabId,
              agent: engine,
              mode: mode || (sessionId ? 'continue' : 'new'),
            }));
            return;
          } else {
            _markTerminalAsAiTab(tabId, engine, mode === 'new' ? null : (sessionId || null));
            geminiActiveTabs.add(tabId);
            commandText = sessionId ? 'gemini -r ' + sessionId : 'gemini -y';
          }

          const state = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
          state.isRunning = true;
          // AI launches are runtime ownership, not reusable shell scripts. Keep the
          // previous plain-shell lastCommand so Restart-after / Play can still
          // resolve the last non-AI command for this cwd.
          clearTerminalCommandOrigin(tabId, state, 'terminal-mcp-start-ai');
          terminalCommandState.set(tabId, state);
          if (mainWindow && !mainWindow.isDestroyed()) {
            mainWindow.webContents.send('terminal:command-started', { tabId });
          }
          activityId = emitTerminalMcpActivity('start_ai', {
            status: 'running',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            engine,
            mode: mode || (sessionId ? 'continue' : 'new'),
            sessionId: mode === 'new' ? null : (sessionId || null),
            sourceMeta: sourceMeta || null,
          });
          term.write(commandText + '\r');
          emitTerminalMcpActivity('start_ai', {
            id: activityId,
            status: 'started',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            engine,
            mode: mode || (sessionId ? 'continue' : 'new'),
            sessionId: mode === 'new' ? null : (sessionId || null),
            sourceMeta: sourceMeta || null,
          });

          console.log('[MCP:Terminal] POST /terminal/ai-start tabId=' + tabId + ' engine=' + engine + ' mode=' + (mode || (sessionId ? 'continue' : 'new')) + ' cmd=' + commandText);
          res.writeHead(200);
          res.end(JSON.stringify({
            status: 'started',
            tabId,
            agent: engine,
            mode: mode || (sessionId ? 'continue' : 'new'),
            sessionId: mode === 'new' ? null : (sessionId || null),
          }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('start_ai', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/create') {
      // Create a new terminal tab with optional command
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { name, cwd, command, color, parentProjectId, sourceMeta, background } = JSON.parse(body);
          const openInBackground = background !== false;
          // When parentProjectId is set, cwd becomes optional — main can fall back
          // to the project's stored path. cwd-only flow (legacy callers) still works.
          let effectiveCwd = cwd;
          if (parentProjectId && !effectiveCwd) {
            try {
              const row = projectManager.db.db.prepare('SELECT path FROM projects WHERE id = ? LIMIT 1').get(parentProjectId);
              if (row && row.path && !row.path.startsWith('__unset__')) effectiveCwd = row.path;
            } catch {}
          }
          if (!effectiveCwd && !parentProjectId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'cwd or parentProjectId is required' }));
            return;
          }

          console.log('[MCP:Terminal] POST /terminal/create name=' + (name || 'auto') + ' projectId=' + (parentProjectId || '-') + ' cwd=' + effectiveCwd + ' cmd=' + (command || '(none)') + ' background=' + openInBackground);
          activityId = emitTerminalMcpActivity('create_tab', {
            status: 'creating',
            targetProjectId: parentProjectId || undefined,
            targetCwd: effectiveCwd || undefined,
            targetName: name || undefined,
            commandPreview: command ? String(command).slice(0, 120) : undefined,
            background: openInBackground,
            sourceMeta: sourceMeta || null,
          });

          // Tell renderer to create a new tab
          if (mainWindow && !mainWindow.isDestroyed()) {
            mainWindow.webContents.send('terminal:mcp-create', {
              name: name || undefined,
              cwd: effectiveCwd,
              command: command || undefined,
              color: color || undefined,
              parentProjectId: parentProjectId || undefined,
              background: openInBackground,
            });
          }
          emitTerminalMcpActivity('create_tab', {
            id: activityId,
            status: 'requested',
            targetProjectId: parentProjectId || undefined,
            targetCwd: effectiveCwd || undefined,
            targetName: name || undefined,
            commandPreview: command ? String(command).slice(0, 120) : undefined,
            background: openInBackground,
            sourceMeta: sourceMeta || null,
          });

          res.writeHead(200);
          res.end(JSON.stringify({ status: 'creating' }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('create_tab', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/kill') {
      // Kill a terminal process
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { tabId, parentProjectId, sourceMeta } = JSON.parse(body);
          if (!tabId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId is required' }));
            return;
          }

          if (parentProjectId) {
            const owner = resolveProjectForTab(tabId);
            if (owner && owner !== parentProjectId) {
              console.warn('[MCP:Terminal] /terminal/kill rejected: tab ' + tabId + ' belongs to project ' + owner + ', caller pinned ' + parentProjectId);
              res.writeHead(403);
              res.end(JSON.stringify({ error: 'tab does not belong to the requested project', owner, requested: parentProjectId }));
              return;
            }
          }

          const pty = terminals.get(tabId);
          if (!pty) {
            res.writeHead(404);
            res.end(JSON.stringify({ error: 'Terminal not alive for tab ' + tabId }));
            return;
          }

          console.log('[MCP:Terminal] POST /terminal/kill tabId=' + tabId);
          activityId = emitTerminalMcpActivity('kill_process', {
            status: 'running',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            sourceMeta: sourceMeta || null,
          });
          pty.kill();
          emitTerminalMcpActivity('kill_process', {
            id: activityId,
            status: 'killed',
            tabId,
            targetProjectId: resolveProjectForTab(tabId) || parentProjectId || undefined,
            sourceMeta: sourceMeta || null,
          });

          res.writeHead(200);
          res.end(JSON.stringify({ status: 'killed', tabId }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('kill_process', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'POST' && req.url === '/terminal/chain') {
      // Run a chain of sequential steps (e.g. build → restart)
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        let activityId = null;
        try {
          const { steps, parentProjectId, sourceMeta } = JSON.parse(body);
          if (!steps || !Array.isArray(steps) || steps.length === 0) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'steps array is required' }));
            return;
          }

          if (parentProjectId) {
            for (const step of steps) {
              if (!step || !step.tabId) continue;
              const owner = resolveProjectForTab(step.tabId);
              if (owner && owner !== parentProjectId) {
                console.warn('[MCP:Terminal] /terminal/chain rejected: tab ' + step.tabId + ' belongs to project ' + owner + ', caller pinned ' + parentProjectId);
                res.writeHead(403);
                res.end(JSON.stringify({ error: 'chain contains tabId from another project', tabId: step.tabId, owner, requested: parentProjectId }));
                return;
              }
            }
          }

          console.log('[MCP:Terminal] POST /terminal/chain projectId=' + (parentProjectId || '-') + ' steps=' + steps.length);
          activityId = emitTerminalMcpActivity('run_chain', {
            status: 'running',
            targetProjectId: parentProjectId || undefined,
            stepCount: steps.length,
            sourceMeta: sourceMeta || null,
          });
          const results = [];

          for (const step of steps) {
            try {
              if (step.action === 'run') {
                const pty = terminals.get(step.tabId);
                if (!pty) throw new Error('Terminal not alive: ' + step.tabId);
                pty.write(step.command + '\r');

                // Wait for command to finish (poll commandState)
                if (step.waitForCompletion !== false) {
                  await new Promise((resolve) => {
                    const checkInterval = setInterval(() => {
                      const state = terminalCommandState.get(step.tabId);
                      if (state && !state.isRunning) {
                        clearInterval(checkInterval);
                        resolve();
                      }
                    }, 500);
                    // Safety timeout: 5 min
                    setTimeout(() => { clearInterval(checkInterval); resolve(); }, 300000);
                  });
                }

                results.push({ step: step.action, tabId: step.tabId, status: 'completed' });
              } else if (step.action === 'restart') {
                const term = terminals.get(step.tabId);
                if (!term) throw new Error('Terminal not alive: ' + step.tabId);
                const cmd = step.command || terminalInitialCommand.get(step.tabId);
                if (!cmd) throw new Error('No saved command for tab ' + step.tabId + '. Pass "command" in step.');

                const cmdState = terminalCommandState.get(step.tabId);
                term.write('\x03');
                if (cmdState && cmdState.isRunning) {
                  await new Promise((resolve) => {
                    let done = false;
                    const check = setInterval(() => {
                      const state = terminalCommandState.get(step.tabId);
                      if (!state || !state.isRunning) {
                        clearInterval(check);
                        if (!done) { done = true; resolve(); }
                      }
                    }, 200);
                    setTimeout(() => { clearInterval(check); if (!done) { done = true; resolve(); } }, 30000);
                  });
                  await new Promise(r => setTimeout(r, 300));
                }
                term.write(cmd + '\r');

                results.push({ step: step.action, tabId: step.tabId, status: 'restarted' });
              } else if (step.action === 'kill') {
                const pty = terminals.get(step.tabId);
                if (pty) pty.kill();
                results.push({ step: step.action, tabId: step.tabId, status: 'killed' });
              } else {
                results.push({ step: step.action, status: 'unknown_action' });
              }
            } catch (stepErr) {
              results.push({ step: step.action, tabId: step.tabId, status: 'error', error: stepErr.message });
            }
          }

          res.writeHead(200);
          emitTerminalMcpActivity('run_chain', {
            id: activityId,
            status: results.some(r => r.status === 'error') ? 'completed_with_errors' : 'completed',
            targetProjectId: parentProjectId || undefined,
            stepCount: steps.length,
            sourceMeta: sourceMeta || null,
          });
          res.end(JSON.stringify({ status: 'completed', results }));
        } catch (e) {
          if (activityId) {
            emitTerminalMcpActivity('run_chain', { id: activityId, status: 'error', error: e.message });
          }
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else if (req.method === 'GET' && req.url?.startsWith('/terminal/output')) {
      // Read last N lines of terminal output
      (async () => {
        try {
          const urlObj = new URL(req.url, 'http://localhost');
          const tabId = urlObj.searchParams.get('tabId');
          const lines = parseInt(urlObj.searchParams.get('lines') || '50');
          const parentProjectId = urlObj.searchParams.get('parentProjectId') || '';

          if (!tabId) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: 'tabId parameter is required' }));
            return;
          }

          if (parentProjectId) {
            const owner = resolveProjectForTab(tabId);
            if (owner && owner !== parentProjectId) {
              console.warn('[MCP:Terminal] /terminal/output rejected: tab ' + tabId + ' belongs to project ' + owner + ', caller pinned ' + parentProjectId);
              res.writeHead(403);
              res.end(JSON.stringify({ error: 'tab does not belong to the requested project', owner, requested: parentProjectId }));
              return;
            }
          }

          const buf = terminalOutputBuffer.get(tabId);
          if (!buf) {
            res.writeHead(404);
            res.end(JSON.stringify({ error: 'No output buffer for tab ' + tabId }));
            return;
          }

          const output = buf.lines.slice(-lines).join('\n');
          console.log('[MCP:Terminal] GET /terminal/output tabId=' + tabId + ' lines=' + lines + ' chars=' + output.length);

          res.writeHead(200);
          res.end(JSON.stringify({ tabId, lines: Math.min(lines, buf.lines.length), output }));
        } catch (e) {
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      })();

    } else if (req.method === 'GET' && req.url?.startsWith('/overseer/')) {
      // Overseer: granular session inspection for the orchestrator SDK tab.
      // Reuses findSessionFile + loadJsonlRecords from claude-data.js (same
      // backtrace logic as parseTimelineEntries). All endpoints are read-only.
      (async () => {
        try {
          const out = await handleOverseerRequest(req.url);
          res.writeHead(out.status || 200);
          res.end(JSON.stringify(out.body));
        } catch (e) {
          console.error('[MCP:Overseer] Error:', e.message, e.stack);
          res.writeHead(Number(e?.statusCode || e?.status) || 500);
          res.end(JSON.stringify({ error: e.message, ...(e.lineageReason ? { lineageReason: e.lineageReason } : {}) }));
        }
      })();

    } else if (req.method === 'POST' && req.url?.startsWith('/overseer/')) {
      // Mutating overseer endpoints: propose_edit (dry-run preview),
      // apply_edit (real edit via claudeDataApi.editRange/deleteRange),
      // fork (creates session fork). All write paths go through the SAME
      // implementation as the renderer IPC handlers — overseer never touches
      // JSONL directly. This guarantees identical backtrace/orphan-cleanup
      // behaviour with the existing Timeline edit-range button.
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', async () => {
        try {
          const payload = body ? JSON.parse(body) : {};
          const out = await handleOverseerMutation(req.url, payload);
          res.writeHead(out.status || 200);
          res.end(JSON.stringify(out.body));
        } catch (e) {
          console.error('[MCP:Overseer:POST] Error:', e.message, e.stack);
          res.writeHead(500);
          res.end(JSON.stringify({ error: e.message }));
        }
      });

    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Not found' }));
    }
  });

  mcpHttpServer.listen(0, '127.0.0.1', () => {
    mcpHttpPort = mcpHttpServer.address().port;
    console.log('[MCP:HTTP] Server listening on 127.0.0.1:' + mcpHttpPort);
    // Cross-reference marker for [JsonlChainDiag:ChainBreak]: when this line
    // appears within a few seconds BEFORE a chain break, the orphan is almost
    // certainly mcp_instructions_delta caused by our own MCP server (re)start.
    console.log('[McpReconnect] terminal-mcp listening on port ' + mcpHttpPort + ' (pid=' + process.pid + ') — any active Claude session may now write attachment[mcp_instructions_delta]');

    // Write port to PID-specific file so MCP server can discover it
    try { fs.mkdirSync(MCP_PORT_DIR, { recursive: true }); } catch {}

    // Cleanup stale port files from dead processes
    try {
      const files = fs.readdirSync(MCP_PORT_DIR).filter(f => f.startsWith('mcp-port-'));
      for (const f of files) {
        const pid = parseInt(f.replace('mcp-port-', ''));
        if (!pid || pid === process.pid) continue;
        try {
          process.kill(pid, 0); // check if alive (signal 0 = no-op)
        } catch {
          // Process dead — remove stale port file
          try { fs.unlinkSync(path.join(MCP_PORT_DIR, f)); } catch {}
          console.log('[MCP:HTTP] Cleaned stale port file: ' + f);
        }
      }
    } catch {}

    // JSON format: { port, pid, openProjectPaths: string[] }. terminal-server.mjs
    // picks the instance whose openProjectPaths contains the request's cwd / CLAUDE_PROJECT_DIR
    // so dev + prod copies running in parallel each get the calls for their own projects,
    // instead of all calls going to whichever wrote the port file last.
    writeMcpPortFile();
    console.log('[MCP:HTTP] Port written to ' + MCP_PORT_FILE);
  });
}

// Renderer tells us which projects it currently has open. Kept up to date by an
// IPC ping on every openProject / closeProject in the workspace store.
//
// Race: discovery files (MCP port-file, Claude hook discovery) are written at
// listen-callback time, BEFORE renderer has mounted and pushed paths. Without
// the SQLite-hydration below, that initial write goes out with [] and any
// hook/MCP call in the first second(s) fails to cwd-route → falls back to
// most-recent mtime → may pick wrong instance. We persist last-known paths
// in app_state and rehydrate on boot so even the very first discovery write
// has the right list (snapshot from previous session). Updated on every push.
const OPEN_PROJECT_PATHS_KEY = 'mcpOpenProjectPaths';
const OPEN_PROJECTS_KEY = 'mcpOpenProjects';
let mcpOpenProjectPaths = [];
let mcpOpenProjects = []; // [{ id, path, name }]
try {
  const cached = projectManager.db.getAppState(OPEN_PROJECT_PATHS_KEY);
  if (typeof cached === 'string' && cached) {
    const parsed = JSON.parse(cached);
    if (Array.isArray(parsed)) {
      mcpOpenProjectPaths = parsed.filter(p => typeof p === 'string' && p);
      console.log('[MCP:HTTP] hydrated openProjectPaths from SQLite: ' + mcpOpenProjectPaths.length + ' entries');
    }
  }
} catch (e) { console.warn('[MCP:HTTP] hydrate openProjectPaths failed:', e.message); }
try {
  const cached = projectManager.db.getAppState(OPEN_PROJECTS_KEY);
  if (typeof cached === 'string' && cached) {
    const parsed = JSON.parse(cached);
    if (Array.isArray(parsed)) {
      mcpOpenProjects = parsed.filter(p => p && typeof p.id === 'string');
      console.log('[MCP:HTTP] hydrated openProjects from SQLite: ' + mcpOpenProjects.length + ' entries');
    }
  }
} catch (e) { console.warn('[MCP:HTTP] hydrate openProjects failed:', e.message); }

function writeMcpPortFile() {
  if (!mcpHttpPort) return;
  const payload = {
    port: mcpHttpPort,
    pid: process.pid,
    openProjectPaths: mcpOpenProjectPaths,
    openProjects: mcpOpenProjects,
    isPackaged: app.isPackaged,
    updatedAt: Date.now(),
  };
  try { fs.writeFileSync(MCP_PORT_FILE, JSON.stringify(payload)); } catch (e) {
    console.warn('[MCP:HTTP] failed to write port file: ' + e.message);
  }
}

// Second arg `meta` is optional, carries { projects: [{id, path, name}] }.
// Legacy renderer only sends one positional arg (array of paths) — we still
// accept that.
ipcMain.on('mcp:open-project-paths', (_e, paths, meta) => {
  if (!Array.isArray(paths)) return;
  mcpOpenProjectPaths = paths.filter(p => typeof p === 'string' && p);
  if (meta && Array.isArray(meta.projects)) {
    mcpOpenProjects = meta.projects.filter(p => p && typeof p.id === 'string').map(p => ({
      id: p.id,
      path: typeof p.path === 'string' ? p.path : '',
      name: typeof p.name === 'string' ? p.name : '',
    }));
  }
  writeMcpPortFile();
  // Mirror project paths into Claude hook discovery so the hook script can
  // route to the correct Electron instance the same way MCP does.
  try { refreshClaudeHookDiscovery(); } catch {}
  // Persist for next boot so the initial discovery write (before renderer pushes)
  // already has the correct list — see hydration block above.
  try { projectManager.db.setAppState(OPEN_PROJECT_PATHS_KEY, JSON.stringify(mcpOpenProjectPaths)); } catch {}
  try { projectManager.db.setAppState(OPEN_PROJECTS_KEY, JSON.stringify(mcpOpenProjects)); } catch {}
});

function stopMcpHttpServer() {
  if (mcpHttpServer) {
    mcpHttpServer.close();
    mcpHttpServer = null;
  }
  try { fs.unlinkSync(MCP_PORT_FILE); } catch {}
  console.log('[MCP:HTTP] Server stopped, port file removed');
  console.log('[McpReconnect] terminal-mcp STOPPED (pid=' + process.pid + ') — on next start active Claude sessions will write attachment[mcp_instructions_delta]');
}

app.whenReady().then(async () => {
  // Freeze the exact shutdown-owned target set before renderer restoration can
  // clear wasInterrupted during AutoResume. `build:i-cont` reads this immutable
  // boot snapshot after installing the new app and submits through Project API.
  captureStartupInterruptedAgentSnapshot();

  // Microphone permission for Soniox dictation (MicButton, mobile-web composer).
  // Without these two handlers Electron's default is "deny" — getUserMedia
  // rejects with AbortError "The user aborted a request" even when macOS itself
  // would prompt. Allow for our own origin (file:// in prod, http://localhost
  // in dev). On macOS the system-level mic permission prompt still fires on
  // first capture — this only opens the Electron-internal gate.
  try {
    const { session } = require('electron');
    session.defaultSession.setPermissionRequestHandler((_wc, permission, callback) => {
      if (permission === 'media' || permission === 'audioCapture' || permission === 'microphone') {
        return callback(true);
      }
      callback(false);
    });
    session.defaultSession.setPermissionCheckHandler((_wc, permission) => {
      if (permission === 'media' || permission === 'audioCapture' || permission === 'microphone') return true;
      return false;
    });
    console.log('[Startup] Microphone permission handlers installed');
  } catch (e) {
    console.error('[Startup] Failed to install permission handlers:', e.message);
  }

  // Диагностика для отладки проблемы с окном
  console.log('[Startup] ═══════════════════════════════════════');
  console.log('[Startup] Platform:', process.platform);
  console.log('[Startup] Is packaged:', app.isPackaged);
  console.log('[Startup] isDev:', isDev);
  console.log('[Startup] Process type:', process.type);
  console.log('[Startup] Parent PID:', process.ppid);
  console.log('[Startup] ELECTRON_RENDERER_URL:', process.env.ELECTRON_RENDERER_URL || '(not set)');
  console.log('[Startup] ═══════════════════════════════════════');

  // Setup shell integration (OSC 7 for cwd reporting)
  console.log('[Startup] Setting up shell integration...');
  setupShellIntegration();

  // A native Codex Rewind creates a child rollout. If Electron died after the
  // confirming Enter but before the live writer proof committed that child,
  // repair the exact journaled A→B edge before renderer restore/AutoResume can
  // observe and relaunch the stale source A.
  const rewindRecovery = await recoverPendingCodexNativeRewindHandoffs();
  if (rewindRecovery.recovered
    || rewindRecovery.stableSourceRecovered
    || rewindRecovery.unresolved
    || rewindRecovery.cleared) {
    console.log('[Startup] Codex rewind recovery:', rewindRecovery);
  }

  // Hydrate per-tab provider state Map from SQLite BEFORE any tab spawns.
  // Without this, first Claude request from a restored tab would hit the
  // fallback `{type:'anthropic'}` default in providerStates Map, ignoring
  // the DeepSeek/Zen selection the user made last session. The proxy reads
  // this Map synchronously on every request — needs to be populated before
  // any AutoResume/Continue path fires `claude --resume` in PTY env.
  try {
    const rows = projectManager.db.getAllTabProviderStates();
    let hydrated = 0;
    for (const r of rows) {
      if (!r.tab_id || !r.provider_state) continue;
      try {
        const state = JSON.parse(r.provider_state);
        providerStates.set(r.tab_id, state);
        hydrated++;
      } catch { /* corrupt row, skip */ }
    }
    console.log('[Startup] Hydrated providerStates: ' + hydrated + ' tab(s)');
  } catch (e) {
    console.warn('[Startup] providerStates hydration failed:', e.message);
  }

  void garbageCollectPromptQueueAssets(
    projectManager.db.getAppState('promptQueueByTab'),
    'app-start',
  );
  // Context belongs to the rollout session, not to whichever PTY happens to
  // be alive. Re-arm persisted Codex sessions sequentially so external compact
  // and token_count appends keep SQLite correct across renderer/app restarts.
  codexSessionContextObserver?.scheduleHydration();
  // Storage retention starts after the app has restored its runtime maps. The
  // first sweep is delayed and bounded; open sessions plus every physical
  // source required by them are protected by a fresh inventory at deletion.
  if (canOwnAutomaticStorageRetention({
    isPackaged: app.isPackaged,
    e2e: process.env.NOTED_E2E_TEST === 'true',
  })) {
    scheduleStorageRetentionSweep(90_000);
  } else {
    console.log('[StorageCleanup] automatic retention disabled owner=' + (app.isPackaged ? 'e2e' : 'development'));
  }

  // Initialize session manager with database from project manager
  console.log('[Startup] Initializing SessionManager...');
  try {
    sessionManager = new SessionManager(projectManager.db);
    console.log('[Startup] SessionManager OK');
  } catch (e) {
    console.error('[Startup] SessionManager ERROR:', e.message);
  }

  // Initialize Claude Manager
  console.log('[Startup] Initializing ClaudeManager...');
  try {
    claudeManager = new ClaudeManager(terminals, terminalProjects, claudeState);
    console.log('[Startup] ClaudeManager OK');
  } catch (e) {
    console.error('[Startup] ClaudeManager ERROR:', e.message);
    // Продолжаем без ClaudeManager — окно всё равно должно открыться
  }

  // Initialize Session Bridge (StatusLine-based Claude session detection)
  console.log('[Startup] Starting SessionBridge...');
  try {
    startSessionBridge();
    console.log('[Startup] SessionBridge OK');
  } catch (e) {
    console.error('[Startup] SessionBridge ERROR:', e.message);
  }

  // Initialize Claude Hook Bridge (Stop/UserPromptSubmit deterministic turn signal)
  console.log('[Startup] Starting ClaudeHookBridge...');
  try {
    startClaudeHookServer();
    console.log('[Startup] ClaudeHookBridge OK');
  } catch (e) {
    console.error('[Startup] ClaudeHookBridge ERROR:', e.message);
  }

  // ========== MCP HTTP SERVER ==========
  console.log('[Startup] Starting MCP HTTP server...');
  try {
    startMcpHttpServer();
    console.log('[Startup] MCP HTTP server OK');
  } catch (e) {
    console.error('[Startup] MCP HTTP server ERROR:', e.message);
  }

  // Renderer-driven hard reload. Direct location.reload() in Electron sometimes
  // routes through the OS default URL handler (file:// → Yandex/whatever) when
  // the page lives at a custom protocol; bouncing through main + webContents.reload()
  // stays inside the current BrowserWindow regardless.
  ipcMain.on('app:reload', (event) => {
    try {
      const win = BrowserWindow.fromWebContents(event.sender);
      if (win && !win.isDestroyed()) win.webContents.reload();
    } catch (e) {
      console.error('[app:reload] error', e.message);
    }
  });

  // ========== MOBILE WEB SERVER (HTTP+WS for phone access) ==========
  tabWorkContext.configure({
    transcriptService,
    decodeCodexCall: codexDataModule._api.codexHistoryActionsForCall,
    decodeCodexPatch: codexDataModule._api.parseCodexPatchApplyChanges,
    readReceipts: (tabId) => agentSendReceiptStore.list({ tabId }),
    resolveAttributionSource: (tab) => {
      if (tab?.commandType?.startsWith('codex')) {
        const sessionId = getCodexWriterProofSnapshot(tab.tabId)?.sessionId || null;
        return sessionId ? { toolType: 'codex', sessionId } : null;
      }
      if (tab?.commandType?.startsWith('claude')) {
        const sessionId = bridgeKnownSessions.get(tab.tabId) || null;
        return sessionId ? { toolType: 'claude', sessionId } : null;
      }
      return null;
    },
  });
  console.log('[Startup] Starting Mobile WebServer...');
  try {
    // Load from src/main, not dist/main — electron-vite only bundles main.js,
    // sibling modules live as raw .js files (same pattern as claude-agent etc).
    const webServer = require(path.join(srcMainDir, 'web-server'));
    // computeActiveLoaders is injected (not imported) so web-server stays a leaf
    // module with no back-reference into main — it only reads the live Maps that
    // already exist here. GET /api/active-loaders calls it on each poll.
    webServer.start({
      sdkSessions,
      tabWorkContext,
      computeActiveLoaders,
      computeProjectActivity,
      startupInterruptedAgentSnapshot,
      // Mobile question answering (PTY drives TUI keystrokes, SDK resolves the
      // parked canUseTool Promise) + snapshot read for connect-mid-question.
      answerClaudeQuestion: answerClaudeQuestionUnified,
      getClaudePendingQuestion,
      transcriptService,
      recoverCodexRewindPostEnter: recoverCodexRewindPostEnterOperation,
      readCodexRewindPostEnterResult,
      readCodexNativeRewindState: (tabId) => {
        const journal = readPendingCodexNativeRewindHandoff(tabId);
        return journal ? {
          pending: true,
          invalid: journal.invalid === true,
          phase: journal.phase,
          generation: journal.actionGeneration,
          sourceSessionId: journal.sourceSessionId,
          targetUuid: journal.targetUuid,
        } : { pending: false };
      },
      resolveCodexRuntimeSessionInfo: (tabId, reason, projectId = null) => getCodexRuntimeSessionSnapshot(tabId, {
        reason: reason || 'web-runtime-session-query',
        projectId,
        refreshTuiReady: true,
      }),
      resolveCodexRuntimeProjectionBatch: (tabIds, projectId = null) => (
        getCodexRuntimeProjectionBatch(tabIds, projectId)
      ),
      resolveAgentToolType: (tabId) => {
        const liveOwners = getLiveAiRuntimeOwners(tabId);
        return {
          observed: liveOwners.length > 0,
          toolType: liveOwners.length > 0
            ? resolveAiToolOwner({ runtimeOwners: liveOwners })
            : null,
        };
      },
      getAgentTurnResult: _getAgentTurnResultForOrchestration,
      getAgentExecutionContext: getActiveAgentExecutionContext,
      readAgentLifecycleIdentity: readAiLifecycleIdentityForTab,
      readAgentStartReadiness: readMainAgentStartReadinessForTab,
      registerTaskCompletionIntent,
      e2eBoundaryTestGate: aiBoundaryTestGate,
      agentSendReceiptStore,
      agentSendReceiptStartupReady,
      projectPromptCatalog,
      savedPromptService,
    });
    console.log('[Startup] Mobile WebServer OK');

    // Expose connection info to the renderer's StatusBar chip.
    ipcMain.handle('web:get-info', () => {
      try {
        return webServer.getInfo();
      } catch (e) {
        return { running: false, error: String(e.message) };
      }
    });
    ipcMain.handle('web:update-external-run-settings', (_event, payload = {}) => {
      try {
        return webServer.updateExternalRunSettings(payload);
      } catch (e) {
        return { ok: false, error: String(e.message || e) };
      }
    });
    ipcMain.handle('orchestration:list-for-tab', async (_event, tabId) => {
      if (!tabId) return [];
      return webServer.listOrchestrationRunsForTab(tabId);
    });
    ipcMain.handle('orchestration:list-active', async () => {
      return webServer.listActiveOrchestrationRuns();
    });
    ipcMain.handle('orchestration:acknowledge', async (_event, payload = {}) => {
      if (!payload.runId || !payload.tabId) return { ok: false, error: 'runId+tabId required' };
      const run = await webServer.acknowledgeOrchestrationRun(payload.runId, payload.tabId);
      return run ? { ok: true, run } : { ok: false, error: 'run not found' };
    });
    ipcMain.handle('orchestration:get-settings', async () => {
      return webServer.getOrchestrationSettings();
    });
    ipcMain.handle('orchestration:update-settings', async (_event, payload = {}) => {
      return webServer.updateOrchestrationSettings(payload);
    });
    ipcMain.handle('orchestration:action', async (_event, payload = {}) => {
      if (!payload.runId || !payload.action) return { ok: false, error: 'runId+action required' };
      return webServer.performOrchestrationAction(payload.runId, payload.action, {
        tabId: payload.tabId || '',
        cancelSendAccepted: payload.cancelSendAccepted === true,
      });
    });
    ipcMain.handle('orchestration:tab-closed', async (_event, payload = {}) => {
      if (!payload.tabId) return { ok: false, error: 'tabId required' };
      const runs = await webServer.handleOrchestrationTabClosed(payload.tabId);
      return { ok: true, runs };
    });
    // Renderer → web relay for prompt-queue deltas. usePromptQueueWebSync (App
    // root) fires this whenever a tab's queue core changes; we fan it out to any
    // phone subscribed to that tab as a `queue-update` SSE event. webBroadcast
    // no-ops when nobody's subscribed, so this is free on the desktop-only path.
    ipcMain.on('web:broadcast-queue', (_e, { tabId, queue }) => {
      if (!tabId) return;
      _webBroadcast(tabId, { type: 'queue-update', queue });
    });
    // Open the LAN URL in the user's default browser (the StatusBar chip uses
    // this so a single click works without the user having to copy+paste).
    ipcMain.handle('web:open-in-browser', () => {
      try {
        const info = webServer.getInfo();
        if (!info.running) return { ok: false, error: 'web-server not running' };
        // Prod (port 7878) → публичный URL через VPS-туннель.
        // Dev и любой другой порт → локальный LAN-IP.
        const isProd = info.port === 7878;
        const url = isProd
          ? `https://remote-control.f9922.tech/?token=${encodeURIComponent(info.token)}`
          : `http://${info.lanIp}:${info.port}/?token=${encodeURIComponent(info.token)}`;
        require('electron').shell.openExternal(url);
        return { ok: true };
      } catch (e) {
        return { ok: false, error: String(e.message) };
      }
    });
  } catch (e) {
    console.error('[Startup] Mobile WebServer ERROR:', e.message);
  }

  console.log('[Startup] Calling createWindow()...');
  createWindow();
  console.log('[Startup] createWindow() returned');

  // Boot-time JSONL auto-repair: scan recent session files, physically rewrite
  // any dangling parentUuid (slash-command orphans, attachment virtual parents,
  // mid-stream proxy crashes). This prevents the toast storm where each tab's
  // Timeline polls discover the same accumulated breaks and fire warning
  // notifications. After repair, recovery only triggers for genuinely NEW
  // breaks — i.e. things that happen during the running session.
  //
  // Run in background — must not block window creation.
  setTimeout(async () => {
    // A private UI test must not sweep or rewrite unrelated user transcripts.
    if (E2E_WINDOWED) return;
    try {
      const projectsRoot = path.join(require('os').homedir(), '.claude', 'projects');
      if (!fs.existsSync(projectsRoot)) return;
      const projects = fs.readdirSync(projectsRoot);
      let scanned = 0, repaired = 0, sessionsFixed = 0;
      let cutoff = Date.now() - 14 * 24 * 60 * 60 * 1000; // 14 days
      // Incremental sweep: a dangling parentUuid lives INSIDE the file, so a
      // file untouched since the last COMPLETED sweep cannot contain a new
      // break — it was either repaired then or had none. Raising the cutoff
      // to the previous sweep's start time shrinks the boot scan from ~1500
      // files (every session active in 14 days, re-read in full on EVERY
      // boot) to just the sessions that actually changed since last boot.
      // The mark is written only after DONE — an interrupted sweep falls back
      // to the wide window on next boot.
      const sweepStartWallMs = Date.now();
      try {
        const lastSweepStartMs = projectManager.db.getAppState('jsonl_auto_repair_last_sweep');
        if (typeof lastSweepStartMs === 'number' && lastSweepStartMs > cutoff) {
          cutoff = lastSweepStartMs;
          console.log('[Startup:AutoRepair] incremental cutoff from last sweep: ' + new Date(cutoff).toISOString());
        }
      } catch { /* app_state unavailable — keep 14-day window */ }
      // Startup-freeze attribution: repairJsonlChainBreaks reads + JSON.parses
      // the whole session file — one 100MB+ session = seconds of main-loop
      // block (CPU-bound parse) and ~10× transient heap (string split +
      // per-line objects). The sweep used to be invisible between its
      // setTimeout and the single DONE line; now every slow file is named,
      // each file is a perfOp (shows in MainLoopGap ops=/recentOps5s=), and
      // cumulative block-time + peak heap land in DONE. Forensics for
      // gapMs=7045 heapMb=975 at boot 2026-06-12 08:03:20.
      const sweepStartedAt = nodePerformance.now();
      let sweepBlockMs = 0;
      let peakHeapMb = 0;
      let slowFiles = 0;
      console.log('[Startup:AutoRepair] SWEEP-START pid=' + process.pid +
        ' cutoff=' + new Date(cutoff).toISOString() +
        ' startAbs=' + (nodePerformance.timeOrigin + sweepStartedAt).toFixed(1) +
        ' heapMb=' + Math.round(process.memoryUsage().heapUsed / 1024 / 1024));
      for (const proj of projects) {
        const projDir = path.join(projectsRoot, proj);
        let entries;
        try { entries = fs.readdirSync(projDir); } catch { continue; }
        for (const f of entries) {
          if (!f.endsWith('.jsonl')) continue;
          const full = path.join(projDir, f);
          let stat;
          try { stat = fs.statSync(full); } catch { continue; }
          if (stat.mtimeMs < cutoff) continue;
          scanned++;
          const sid = f.replace(/\.jsonl$/, '');
          const fileStartedAt = nodePerformance.now();
          const opId = beginPerfOp('autoRepairFile', { sessionId: sid, reason: Math.round(stat.size / 1024 / 1024) + 'mb' });
          try {
            const res = await repairJsonlChainBreaks(sid, projDir);
            if (res.repaired > 0) {
              repaired += res.repaired;
              sessionsFixed++;
            }
          } catch (e) {
            console.warn('[Startup:AutoRepair] err on ' + sid + ':', e.message);
          } finally {
            endPerfOp(opId);
          }
          const fileMs = nodePerformance.now() - fileStartedAt;
          sweepBlockMs += fileMs;
          const heapMb = Math.round(process.memoryUsage().heapUsed / 1024 / 1024);
          if (heapMb > peakHeapMb) peakHeapMb = heapMb;
          if (fileMs > 200) {
            slowFiles++;
            console.warn('[Startup:AutoRepair] SLOW-FILE session=' + sid.substring(0, 8) +
              ' sizeMb=' + (stat.size / 1024 / 1024).toFixed(1) +
              ' durMs=' + fileMs.toFixed(0) +
              ' heapMb=' + heapMb +
              ' endAbs=' + (nodePerformance.timeOrigin + nodePerformance.now()).toFixed(1));
          }
          // Yield between files: each repair call is internally synchronous
          // (readFileSync + full parse), so without this the whole sweep is one
          // uninterrupted event-loop turn — input/IPC starve for its entire
          // duration instead of only for the single largest file.
          await new Promise((resolve) => setImmediate(resolve));
        }
      }
      console.log('[Startup:AutoRepair] DONE pid=' + process.pid + ' scanned=' + scanned + ' sessionsFixed=' + sessionsFixed + ' totalDanglingRepaired=' + repaired +
        ' sweepWallMs=' + (nodePerformance.now() - sweepStartedAt).toFixed(0) +
        ' sweepBlockMs=' + sweepBlockMs.toFixed(0) +
        ' slowFiles=' + slowFiles +
        ' peakHeapMb=' + peakHeapMb +
        ' — every individual repair logged above with [JsonlAutoRepair] (grep "JsonlAutoRepair\\|JsonlChainDiag\\|McpReconnect" for full forensic view)');
      // Sweep completed — next boot only needs files modified after THIS sweep began.
      try { projectManager.db.setAppState('jsonl_auto_repair_last_sweep', sweepStartWallMs); } catch { /* non-fatal */ }
      // Notify renderer so user sees what was healed in the background.
      // Skip when nothing was repaired (silent boot path).
      if (sessionsFixed > 0 && mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('jsonl-auto-repair:summary', {
          sessionsFixed,
          totalRepaired: repaired,
          scanned,
        });
      }
    } catch (e) {
      console.warn('[Startup:AutoRepair] sweep failed:', e.message);
    }
  }, 3000);
});

// Interrupted session management: SINGLE source of truth in main process.
// Renderer's beforeunload ONLY saves UI state — never touches wasInterrupted.
//
// Uses bridge/codex known-session ownership first, then exact per-PTY process
// proof for the short bridge-less window after fresh start/resume.
// claudeCliActive = "currently processing" (empty when idle at prompt)
// bridgeKnownSessions = "CLI alive in this tab" (persists until terminal killed)
//
// before-quit: safety net — runs first, marks known sessions.
// will-quit: definitive — runs AFTER beforeunload, clears stale + marks active.
//
// CRITICAL: Electron does NOT await async before-quit handlers by default.
// Without event.preventDefault(), Electron continues teardown in parallel —
// our Ctrl+C polling races against renderer destruction and PTY SIGHUP,
// almost always losing. We use the standard pattern:
//   1. First entry: preventDefault, do the work, then app.quit() again.
//   2. Re-entry guard skips the handler on the second pass so app.quit()
//      really exits.
// See methodology/дизайн-принципы.md::Graceful exit через Ctrl+C, не SIGTERM первым.
let _gracefulShutdownInProgress = false;
let _gracefulShutdownDone = false;
let _gracefulShutdownAiSessions = null;
let _gracefulShutdownLiveTabIds = null;
const SHUTDOWN_OVERLAY_MIN_VISIBLE_MS = 400;

app.on('before-quit', async (event) => {
  if (_gracefulShutdownDone) return;          // second pass — let Electron quit
  if (_gracefulShutdownInProgress) {           // user mashed ⌘Q during shutdown
    event.preventDefault();
    return;
  }
  _gracefulShutdownInProgress = true;
  event.preventDefault();
  let activeAiSessions = getInterruptedAiSessionEntries();
  let liveAiTabIds = initialShutdownLiveTabIds(activeAiSessions);
  _gracefulShutdownAiSessions = new Map(activeAiSessions);
  _gracefulShutdownLiveTabIds = new Set(liveAiTabIds);
  let shutdownOverlayShownAt = 0;

  // Watchdog lame-duck FIRST: shutdown legitimately stalls the loop (drain,
  // Ctrl+C fan-out) — without this the watchdog would sample a "freeze" that
  // is just teardown.
  try { if (perfWatchdog && perfWatchdog.connected) perfWatchdog.send({ t: 'bye' }); } catch {}

  // CRITICAL ORDER: mark was_interrupted FIRST, before any slow/abortable step.
  // The drain + Ctrl+C fan-out below can stall for seconds (a Claude turn still
  // streaming through the keepAlive proxy holds the connection open → drain
  // never reaches size 0), and build:install's graceful-quit.sh pkills the
  // process on a short deadline. If marking sat after those steps (it used to,
  // post-GracefulCtrlC), a stalled drain meant the UPDATE never ran → all tabs
  // restored with was_interrupted=0 → AutoResume "No interrupted tabs", no
  // Continue overlay, despite intact JSONL on disk. This write is a synchronous
  // better-sqlite3 UPDATE (sub-ms) and survives any later abort of the chain.
  // will-quit repeats clear+mark as the definitive pass when it does run.
  // Forensic: 2026-05-26 16:06 restart — drain stalled on "1 active
  // connections", marking never reached, 6 tabs silently lost their resume.
  try {
    if (projectManager?.db?.db) {
      const marked = markInterruptedAiSessionEntries(activeAiSessions, 'before-quit');
      console.log('[Shutdown:before-quit] EARLY-MARK ai=' + activeAiSessions.size +
        ' bridge=' + bridgeKnownSessions.size +
        ' codex=' + codexKnownSessions.size +
        ' marked=' + marked +
        ' ids=[' + formatInterruptedAiSessionIds(activeAiSessions) + ']');
    }
  } catch (e) {
    console.error('[Shutdown] before-quit early-mark error:', e.message);
  }

  // Persist any still-open activity intervals (truncated at quit time) so a
  // turn that was in flight at shutdown isn't lost from the activity log.
  try { flushOpenActivityIntervals(); } catch (e) {
    console.error('[Activity] flush on quit failed:', e.message);
  }

  // Tell renderer to show shutdown overlay for live AI sessions.
  try {
    const tabsCount = liveAiTabIds.size;
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('shutdown:overlay', { show: true, tabsCount });
      shutdownOverlayShownAt = Date.now();
    }
  } catch {}

  // Process proof confirms live tabs for graceful stop. It may promote only a
  // causally-linked accepted Claude Resume identity; it never joins a random
  // stored session id to a provider process.
  try {
    const augmented = await augmentShutdownStateFromProcessProof(activeAiSessions, liveAiTabIds);
    const previousEntries = activeAiSessions;
    activeAiSessions = augmented.recoverableEntries;
    liveAiTabIds = augmented.liveTabIds;
    _gracefulShutdownAiSessions = new Map(activeAiSessions);
    _gracefulShutdownLiveTabIds = new Set(liveAiTabIds);
    const reconciled = reconcileInterruptedAiSessionEntries(
      previousEntries,
      activeAiSessions,
      'before-quit-process-proof',
    );
    console.log('[Shutdown:before-quit] PROCESS-MARK ai=' + activeAiSessions.size
      + ' live=' + liveAiTabIds.size
      + ' cleared=' + reconciled.cleared
      + ' marked=' + reconciled.marked
      + ' ids=[' + formatInterruptedAiSessionIds(activeAiSessions) + ']');
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('shutdown:overlay', {
        show: true,
        tabsCount: liveAiTabIds.size,
      });
    }
  } catch (error) {
    console.warn('[Shutdown:ProcessProof] augmentation failed:', error?.message || error);
  }

  // Drain active proxy connections before killing terminals
  try { await proxyGracefulShutdown(); } catch (e) {
    console.error('[Shutdown] proxyGracefulShutdown error:', e.message);
  }

  // Graceful Ctrl+C to every live AI CLI BEFORE PTY kill. Direct term.kill()
  // delivers SIGHUP, which bypasses Ink TUI and cancels any in-flight SSE chunk
  // → orphan parentUuid on next resume. Sending \x03 lets Claude flush the
  // current assistant entry to JSONL and exit cleanly. Concurrent fan-out:
  // ps lookups + Ctrl+C all start in parallel, then Promise.all with 1.5s
  // deadline so we don't hang shutdown when claude refuses to exit.
  // See fix-claude-busy-detection.md::Manual Stop and JsonlChainDiag traces.
  try {
    const tabs = Array.from(terminals.entries()).filter(([tabId]) => liveAiTabIds.has(tabId));
    if (tabs.length > 0) {
      console.log('[Shutdown:GracefulCtrlC] Sending Ctrl+C to ' + tabs.length + ' live AI tab(s) before kill');
      await Promise.race([
        Promise.all(tabs.map(async ([tabId, term]) => {
          const sessionInfo = activeAiSessions.get(tabId) || null;
          let childPid = null;
          try {
            const psOut = await execAsync('ps -eo pid,ppid,command', 1500);
            for (const line of (psOut || '').split('\n').filter(Boolean)) {
              const m = line.trim().match(/^(\d+)\s+(\d+)\s+(.+)$/);
              if (!m) continue;
              const [, pid, ppid, cmd] = m;
              if (cmd.includes('Electron') || cmd.includes('electron')) continue;
              const aiName = getAiProcessNameFromCommand(cmd);
              if (!aiName) continue;
              if (Number(ppid) === term.pid) { childPid = Number(pid); break; }
            }
          } catch {}
          if (!childPid) return;
          const sid = sessionInfo?.sessionId || null;
          console.log('[Shutdown:GracefulCtrlC] tabId=' + tabId.slice(-12) +
            ' engine=' + (sessionInfo?.engine || 'ai') +
            ' childPid=' + childPid +
            ' sessionId=' + (sid ? sid.substring(0, 8) : 'none') +
            ' — \\x03 → waiting for graceful exit');
          try { term.write('\x03'); } catch (err) { console.log('[Shutdown:GracefulCtrlC] write failed: ' + err.message); }
          // Poll until process is gone or 1200ms passes.
          await new Promise((resolve) => {
            const start = Date.now();
            const poll = () => {
              try {
                process.kill(childPid, 0);
                if (Date.now() - start >= 1200) {
                  console.log('[Shutdown:GracefulCtrlC] tabId=' + tabId.slice(-12) + ' childPid=' + childPid + ' — did NOT exit in 1200ms, term.kill() will SIGHUP it');
                  return resolve();
                }
                setTimeout(poll, 60);
              } catch {
                console.log('[Shutdown:GracefulCtrlC] tabId=' + tabId.slice(-12) + ' childPid=' + childPid + ' — exited cleanly in ' + (Date.now() - start) + 'ms');
                resolve();
              }
            };
            setTimeout(poll, 60);
          });
        })),
        new Promise((resolve) => setTimeout(resolve, 1500)),
      ]);
    }
  } catch (e) {
    console.error('[Shutdown:GracefulCtrlC] error:', e.message);
  }

  // IPC delivery is not paint. On an idle/fast exit the old code sent the
  // overlay and destroyed the renderer in the same perceptual instant, so the
  // user still saw no closing screen. Keep only the missing remainder; real
  // proxy drain / Ctrl+C work normally exceeds this and adds no extra delay.
  if (shutdownOverlayShownAt > 0) {
    const elapsed = Date.now() - shutdownOverlayShownAt;
    const remaining = Math.max(0, SHUTDOWN_OVERLAY_MIN_VISIBLE_MS - elapsed);
    if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
    console.log('[Shutdown:Overlay] visibleMs=' + (Date.now() - shutdownOverlayShownAt)
      + ' minimumMs=' + SHUTDOWN_OVERLAY_MIN_VISIBLE_MS);
  }

  // All graceful work done. Re-trigger quit; the guard above will let it pass.
  console.log('[Shutdown:GracefulCtrlC] graceful flow complete, calling app.quit()');
  _gracefulShutdownDone = true;
  app.quit();
});

app.on('will-quit', () => {
  try {
    if (projectManager?.db?.db) {
      // Step 1: Clear ALL stale interrupted states
      const cleared = projectManager.db.db.prepare(
        'UPDATE tabs SET was_interrupted = 0 WHERE was_interrupted = 1 AND overlay_dismissed = 0'
      ).run();

      // Step 2: Reapply the frozen pre-stop owner set. Ctrl+C may already have
      // removed bridge/runtime maps; recomputing here would erase the exact
      // process-proof session that shutdown just preserved.
      const activeAiSessions = _gracefulShutdownAiSessions || getInterruptedAiSessionEntries();
      const marked = markInterruptedAiSessionEntries(activeAiSessions, 'will-quit');

      console.log('[Shutdown:will-quit] cleared=' + cleared.changes + ' marked=' + marked +
        ' bridge=' + bridgeKnownSessions.size +
        ' codex=' + codexKnownSessions.size +
        ' ids=[' + formatInterruptedAiSessionIds(activeAiSessions) + ']');
    }
  } catch (e) {
    console.error('[Shutdown] will-quit error:', e.message);
  }
  try { projectPromptCatalog.close(); } catch (e) {
    console.warn('[ProjectPrompts] watcher shutdown failed:', e.message);
  }

  // ПОСЛЕДНЕЕ ДЕЙСТВИЕ ПЕРЕД ВЫХОДОМ: отвязать себя от всех терминалов.
  //
  // Дальше начинается разбор окружения JavaScript (в отчётах macOS это
  // `node::FreeEnvironment`). Терминалы в этот момент ещё умирают, и модуль
  // node-pty честно пытается позвать наши обработчики через мост между
  // потоками — а вызвать функцию в разбираемом окружении уже нельзя. Мост
  // получает отказ, пытается превратить его в обычную ошибку JavaScript,
  // выбросить её уже некуда — и это становится аварийным завершением всего
  // приложения (SIGABRT).
  //
  // Именно поэтому такое НЕ лечится защитой внутри обработчика: он к этому
  // моменту даже не начинает выполняться, ошибка возникает раньше, на самом
  // мосте. Проверено на живом приложении: сборка с защитой внутри обработчика
  // и с двумя слушателями ошибки всё равно упала дважды подряд (19.08, 04:44
  // и 04:53 местного времени), стек обоих отчётов обрывался в разборе
  // окружения, а не в нашем коде.
  //
  // Единственный настоящий ремонт — чтобы к этому моменту звать было НЕКОГО.
  // Снимаем свои обработчики: терминалы всё равно уже помечены, состояние
  // сохранено выше, и никакая уборка на этой стадии больше не нужна.
  try {
    let detached = 0;
    for (const [, term] of terminals) {
      try {
        term.removeAllListeners('data');
        term.removeAllListeners('exit');
        term.removeAllListeners('error');
        detached += 1;
      } catch {}
    }
    // Карту НЕ очищаем: если выход по какой-то причине будет отменён, пустая
    // карта при живых терминалах — это потерянные вкладки. Снятых обработчиков
    // достаточно: звать через мост уже некого.
    console.log('[Shutdown:will-quit] detached terminal listeners count=' + detached);
  } catch (e) {
    console.error('[Shutdown] detach terminal listeners failed:', e.message);
  }
});

app.on('window-all-closed', () => {
  // A plain window close does not emit before-quit. Route it through the same
  // shutdown path as Cmd+Q so live AI sessions are marked before PTYs exit.
  console.log('[Shutdown:window-all-closed] routing through graceful app quit' +
    ' terminals=' + terminals.size +
    ' ai=' + getInterruptedAiSessionEntries().size);
  app.quit();
});

app.on('activate', () => {
  if (E2E_WINDOWED) return;
  console.log('[Activate] Dock icon clicked');
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  } else if (mainWindow) {
    // Show and focus existing window when clicking dock icon
    mainWindow.show();
    if (process.platform === 'darwin') {
      mainWindow.moveTop();
      app.focus({ steal: true });
    }
  }
});

// Provider-neutral copy formatter used by Claude. Codex calls the same module
// after its raw rollout call has been normalized into canonical actions.
function formatSemanticToolAction(toolName, input, toolResult = null, includeEditing = false, includeReading = false, opts = {}) {
  const flags = opts.flags || null;
  const filters = flags ? {
    includeClaude: flags.includeClaude ?? true,
    includeActions: flags.actions ?? true,
    includeReading: !!flags.reading,
    includeSearch: !!flags.search,
    includeEditing: !!flags.editing,
    includeRun: !!flags.run,
    includeGit: !!flags.git,
    includeMcp: !!flags.mcp,
    includeWeb: !!flags.web,
    includePlan: !!flags.plan,
    includeOther: !!flags.other,
    includeSubagentResult: !!opts.includeSubagentResult,
    includeSubagentHistory: !!opts.includeSubagentHistory,
  } : {
    includeClaude: true,
    includeActions: true,
    includeReading: !!includeReading,
    includeSearch: false,
    includeEditing: !!includeEditing,
    includeRun: !!includeEditing,
    includeGit: false,
    includeMcp: false,
    includeWeb: false,
    includePlan: false,
    includeOther: false,
    includeSubagentResult: !!opts.includeSubagentResult,
    includeSubagentHistory: !!opts.includeSubagentHistory,
  };
  return formatCopyAction({
    toolName,
    args: input || {},
    result: toolResult,
    isError: !!toolResult?.is_error,
  }, filters, {
    progressEntries: opts.progressEntries || [],
  });
}

// claude:copy-range → ipc/claude-data.js

// Create new terminal for a tab
ipcMain.handle('terminal:create', async (event, { tabId, projectId, rows, cols, cwd, initialCommand }) => {
    // Guard: if PTY already exists (e.g. respawned by MCP continue_claude), reuse it
    const existingPty = terminals.get(tabId);
    if (existingPty) {
      const existingProjectId = terminalProjectIds.get(tabId) || null;
      if (existingProjectId && projectId && existingProjectId !== projectId) {
        const error = new Error('tab_id_runtime_collision:' + tabId);
        error.code = 'TAB_ID_RUNTIME_COLLISION';
        console.error('[terminal:create] refusing cross-project PTY reuse tab=' + tabId
          + ' existingProject=' + existingProjectId
          + ' requestedProject=' + projectId);
        throw error;
      }
      console.log('[terminal:create] PTY already exists for ' + tabId + ' (pid=' + existingPty.pid + '), reusing');
      if (!getHeadlessTerminalMirror(tabId)) {
        createHeadlessTerminalMirror(tabId, cols || 80, rows || 24, {
          complete: false,
          incompleteReason: 'existing-pty-mirror-missing',
        });
      }
      return { pid: existingPty.pid, cwd: terminalProjects.get(tabId) };
    }

    console.time(`[PERF:main] terminal:create ${tabId}`);
    const shell = process.env.SHELL || '/bin/bash';
    const shellName = path.basename(shell);
    const workingDir = cwd || process.env.HOME;
    const workingDirStat = await fs.promises.stat(workingDir).catch(() => null);
    if (!workingDirStat || !workingDirStat.isDirectory()) {
      const error = new Error('working_directory_missing:' + workingDir);
      error.code = 'WORKING_DIRECTORY_MISSING';
      console.error('[terminal:create] working directory missing tabId=' + tabId + ' cwd=' + workingDir);
      throw error;
    }

    disarmCodexProviderSemanticSource(tabId, 'terminal-generation-changed');

    // A new PTY gets a new editor owner token, independent of PID reuse.
    const grabTerminalId = crypto.randomUUID();
    const captureHelperPath = app.isPackaged
      ? path.join(os.homedir(), '.claude', 'hooks', CAPTURE_HELPER_BASENAME)
      : path.join(srcMainDir, CAPTURE_HELPER_BASENAME);
    // Build env with shell integration
    const shellEnv = buildChildProcessEnv({
      TERM: 'xterm-256color',
      COLORTERM: 'truecolor',  // Enable 24-bit colors for Ink-based CLIs (gemini, claude)
      CLICOLOR: '1',
      LANG: process.env.LANG || 'en_US.UTF-8',
      LC_ALL: process.env.LC_ALL || 'en_US.UTF-8',
      TERM_PROGRAM: 'vscode',  // Triggers xterm.js-optimized rendering in Claude Code's Ink
      TERM_PROGRAM_VERSION: '1.0.0',
      // Route Claude Code through our local proxy for dynamic provider switching.
      // Per-tab prefix /t/<tabId> lets the proxy keep independent provider state per tab.
      ANTHROPIC_BASE_URL: 'http://127.0.0.1:' + PROVIDER_PROXY_PORT + '/t/' + encodeURIComponent(tabId),
      // PromptQueue: Claude's chat:externalEditor (Ctrl+G) launches $EDITOR with the current
      // input as a tempfile. Our helper script reads the file → sends to our hook socket →
      // truncates → exits. Basename starts with "code" so promptEditor.ts classifies us
      // as GUI editor and skips the alt-screen flash. See fact-prompt-queue.md.
      //
      // NOTED_ORIGINAL_EDITOR carries the user's real $EDITOR (Sublime/vim/code/...) so the
      // helper can passthrough to it when no lock-file is set (user manually pressed Ctrl+G
      // expecting their normal editor to open).
      EDITOR: captureHelperPath,
      VISUAL: captureHelperPath,
      NOTED_GRAB_OWNER_ID: agentInputCaptureProtocol.ownerId,
      NOTED_GRAB_TERMINAL_ID: grabTerminalId,
      NOTED_ORIGINAL_EDITOR: process.env.EDITOR || process.env.VISUAL || '',
      // Always emit grab-helper diag to /tmp/noted-grab-helper.log. Without
      // this, when "Helper never reported back" fires we have zero independent
      // proof of whether the helper started, found the lock-file, or hit the
      // socket. Cost: ~5 short append lines per Ctrl+G; effectively free.
      NOTED_GRAB_DEBUG: '1',
      // Authoritative routing hint for the MCP server (terminal-server.mjs) and
      // any other child tool that wants to address THIS specific Electron main.
      // When dev+prod both have the same cwd in openProjectPaths, cwd-routing
      // ties — but Claude was spawned by exactly one main, so its env knows
      // which PID. terminal-server.mjs reads NOTED_MAIN_PID and prefers that
      // instance's port-file over cwd ambiguity. Same idea as #91 but applied
      // to MCP HTTP routing instead of hook-socket routing.
      NOTED_MAIN_PID: String(process.pid),
      // Project-level routing: tells terminal-server.mjs and other tools which
      // *project* in this main the PTY belongs to. cwd-based matching breaks
      // when two open projects share/nest a cwd, or when Claude `cd`'s away.
      // With NOTED_PARENT_PROJECT_ID set, MCP scopes list_tabs/create_tab/run/
      // restart/kill to this project unconditionally — no cwd heuristic, no
      // activeProjectId fallback. See methodology/дизайн-принципы.md::ID-pinned routing.
      NOTED_PARENT_PROJECT_ID: typeof projectId === 'string' && projectId ? projectId : '',
      NOTED_PARENT_TAB_ID: typeof tabId === 'string' ? tabId : '',
      // Claude Code 2.1.110+ uses an aggressive alternate-screen renderer by
      // default. Each alt-screen transition (\x1b[?1049h/l) drops Claude's own
      // DEC ?2004 (bracketed paste mode) — after a few transitions a large
      // Cmd+V arrives in xterm.js without \x1b[200~/\x1b[201~ wrapping, gets
      // fragmented by macOS TTYHOG (~1KB), and Ink renders one [Pasted text
      // #N] chip PER chunk. Setting this env disables the alt-screen path,
      // keeping DEC 2004 stable across renders and making big pastes show
      // as one chip again. Supported since Claude 2.1.132 (May 6, 2026).
      // See deep-research-paste.md §4.1 + research result §3.
      CLAUDE_CODE_DISABLE_ALTERNATE_SCREEN: '1',
      // Kill the mutating attribution header (cc_version=<v>.<fingerprint>; cch=00000;)
      // injected at the start of the system prompt. Without this kill the prefix drifts
      // on every request → server-side cache prefix mismatch → cache_read collapses.
      // Hurts long sessions (~20K system tokens re-billed per turn) AND breaks the
      // expected hit on fork/--resume where parent and child should share the same
      // prefix bytes. See packages/claude-code-src/constants/system.ts:52.
      CLAUDE_CODE_ATTRIBUTION_HEADER: '0',
    });

    // A running older Noted Terminal may have exported its retired private
    // Codex directory into this process tree. Merely stopping the new build
    // from prepending it is insufficient: a rebuild launched from that tree
    // would inherit the stale 0.147 path and keep resolving the old binary.
    // Remove only that app-private directory; the user's normal npm/brew PATH
    // remains intact and selects the current official Codex installation.
    const retiredCodexBinDir = path.join(os.homedir(), '.noted-terminal', 'bin');
    shellEnv.PATH = String(shellEnv.PATH || '')
      .split(path.delimiter)
      .filter((entry) => path.resolve(entry || '.') !== retiredCodexBinDir)
      .join(path.delimiter);
    delete shellEnv.NOTED_CODEX_BIN_DIR;
    delete shellEnv.NOTED_TERMINAL_CODEX_EVENTS_SOCKET;

    // Agent launchers can export NO_COLOR=1/FORCE_COLOR=0. Claude/Codex respect
    // those variables and emit no ANSI colors, which makes the whole TUI
    // monochrome even though xterm itself is configured for truecolor.
    delete shellEnv.NO_COLOR;
    if (shellEnv.FORCE_COLOR === '0') {
      delete shellEnv.FORCE_COLOR;
    }
    // Zsh: use ZDOTDIR to load our integration
    if (shellName === 'zsh') {
      shellEnv.ZDOTDIR = shellIntegrationDir;
    }

    // Bash: use BASH_ENV to source our integration
    if (shellName === 'bash') {
      shellEnv.BASH_ENV = path.join(shellIntegrationDir, '.bashrc');
    }

    console.time(`[PERF:main] pty.spawn ${tabId}`);

    // Always spawn plain interactive shell (no -c wrapper).
    //
    // Previously: when initialCommand was provided we ran `zsh -l -c "cmd; exec shell"`.
    // That broke OSC 133 — `-c` is non-interactive, so the precmd/preexec hooks from
    // shell-integration/.zshrc never fired for the command, and the `exec shell`
    // tail spawned a fresh shell that didn't re-source our integration either.
    // Net effect: tab was alive but green "command running" indicator never lit up
    // because [terminal:command-started] event never reached the renderer.
    //
    // New flow: spawn the shell empty (lets our ZDOTDIR/.zshrc load OSC 133 hooks
    // normally), then dispatch initialCommand via ptyProcess.write() once the first
    // OSC 133 A (prompt ready) arrives. preexec/precmd will fire on Enter — same
    // path as a user manually typing the command, same path as terminal/restart.
    // Deterministic: no timeouts, no `-c` non-interactive corner cases.
    const shellArgs = [];

    let ptyProcess;
    try {
      ptyProcess = pty.spawn(shell, shellArgs, {
        name: 'xterm-256color',
        cols: cols || 80,
        rows: rows || 24,
        cwd: workingDir,
        env: shellEnv
      });
    } catch (error) {
      disarmCodexProviderSemanticSource(tabId, 'pty-spawn-failed');
      throw error;
    }
    ptyProcess._notedGrabTerminalId = grabTerminalId;
    console.timeEnd(`[PERF:main] pty.spawn ${tabId}`);
    console.log(`[PTY:CREATED] tabId=${tabId} pid=${ptyProcess.pid} cwd=${workingDir} shell=${shell} args=${JSON.stringify(shellArgs)} initialCommand=${initialCommand ? JSON.stringify(initialCommand) : 'none'}`);

    terminalCwdChangeProofs.cancel(tabId, null, 'terminal_generation_changed');
    revokeCodexActionAuthoritiesForTab(tabId, 'terminal-replaced');
    aiBoundaryTestGate.cancelMatching({ tabId }, 'terminal-replaced');
    terminals.set(tabId, ptyProcess);
    terminalShellReadiness.reset(tabId, ptyProcess, ptyProcess.pid);
    terminalProjects.set(tabId, workingDir);
    if (typeof projectId === 'string' && projectId) {
      terminalProjectIds.set(tabId, projectId);
    }
    terminalCommandState.set(tabId, { isRunning: false, lastExitCode: 0 });
    claudeAutoModeDefaultPromptHintTabs.delete(tabId);
    claudeAutoModeDefaultPromptHintBuffers.delete(tabId);
    if (initialCommand) terminalInitialCommand.set(tabId, initialCommand);
    terminalOutputBuffer.set(tabId, { lines: [], maxLines: TERMINAL_OUTPUT_MAX_LINES });
    // A naturally exited PTY keeps its final headless frame so a late renderer
    // can still hydrate the completed screen. A new PTY is the ownership
    // boundary: dispose that retained frame and start a fresh generation.
    disposeHeadlessTerminalMirror(tabId, 'pty-recreate');
    createHeadlessTerminalMirror(tabId, cols || 80, rows || 24);

    // If initialCommand provided, wait for shell-integration's first OSC 133;A
    // (prompt ready) and then write the command. This guarantees:
    //   1) precmd/preexec hooks are loaded → OSC 133 B will fire on Enter
    //   2) we don't race the shell startup (writing too early ate by zsh init)
    //   3) command-finished (OSC 133 D) reaches renderer → green pill clears
    // Listener self-removes after one fire. Safety timeout 5s in case the user's
    // .zshrc throws and prompt never arrives — we then just leave the shell idle
    // (better than blocking forever).
    if (initialCommand) {
      let dispatched = false;
      const tryDispatch = (_evt, evtTabId) => {
        if (evtTabId !== tabId || dispatched) return;
        dispatched = true;
        ipcMain.removeListener('terminal:prompt-ready-internal', tryDispatch);
        clearTimeout(fallbackTimer);
        console.log(`[terminal:create] initialCommand dispatch for ${tabId} on OSC 133 A: ${initialCommand}`);
        rememberTerminalLastCommand(tabId, initialCommand);
        try { ptyProcess.write(initialCommand + '\r'); } catch (e) {
          console.warn(`[terminal:create] write failed: ${e.message}`);
        }
      };
      ipcMain.on('terminal:prompt-ready-internal', tryDispatch);
      const fallbackTimer = setTimeout(() => {
        if (dispatched) return;
        ipcMain.removeListener('terminal:prompt-ready-internal', tryDispatch);
        console.warn(`[terminal:create] OSC 133 A timeout 5s for ${tabId} — aborting initialCommand, shell left idle`);
        dispatched = true;
      }, 5000);
    }

    // ПОЧЕМУ ЗДЕСЬ НУЖЕН ЭТОТ СЛУШАТЕЛЬ, ХОТЯ ОН НИЧЕГО НЕ ДЕЛАЕТ.
    //
    // Модуль терминала внутри себя написан так: если на терминале меньше ДВУХ
    // слушателей ошибки, он выбрасывает её наружу из обработчика сокета
    // (node-pty/lib/unixTerminal.js: `if (listeners('error').length < 2) throw err`).
    // А этот обработчик живёт в фоновом потоке и вызывается через мост между
    // потоками — там ловить исключение уже некому, и обычная ошибка ввода-вывода
    // превращается в аварийное завершение ВСЕГО приложения без строки в логе.
    //
    // Слушателей у нас не было ни одного, то есть условие выполнялось всегда.
    // Отсюда пять падений 18–19.08 (18:10, 19:28, 20:28, 20:39, 03:32 местного
    // времени), все — в момент закрытия приложения, когда десятки терминалов
    // умирают разом и ошибки ввода-вывода на их сокетах неизбежны.
    //
    // Модуль считает слушателей, а не проверяет их полезность: ставим ДВА, и
    // тогда ветка с выбросом наружу физически недостижима. Второй — не
    // «на всякий случай», а обязательное условие, чтобы счётчик дошёл до 2.
    const swallowPtyError = (err) => {
      const code = err && err.code ? String(err.code) : '';
      // EIO при смерти дочернего процесса и EAGAIN на старте — штатные события
      // жизненного цикла терминала, а не поломка: молчим, чтобы не засорять лог
      // при каждом закрытии вкладки.
      if (code.includes('EIO') || code.includes('EAGAIN')) return;
      console.error('[PTY:SOCKET_ERROR] tab=' + String(tabId).slice(-12)
        + ' pid=' + (ptyProcess?.pid ?? '-')
        + ' code=' + (code || 'none')
        + ' — ' + (err && err.message ? err.message : String(err)));
    };
    try {
      ptyProcess.on('error', swallowPtyError);
      ptyProcess.on('error', swallowPtyError);
    } catch (err) {
      console.error('[PTY:SOCKET_ERROR_GUARD_FAILED] tab=' + String(tabId).slice(-12)
        + ' — ' + (err && err.message ? err.message : String(err)));
    }

    ptyProcess.onData((data) => {
      if (!ownsTerminalRuntime(terminals, tabId, ptyProcess)) {
        if (ptyProcess.__notedStaleDataReported !== true) {
          ptyProcess.__notedStaleDataReported = true;
          console.warn('[PTY:STALE_DATA] ignored tab=' + String(tabId).slice(-12)
            + ' oldPid=' + ptyProcess.pid
            + ' currentPid=' + (terminals.get(tabId)?.pid || '-'));
        }
        return;
      }
      // Capture output into ring buffer for MCP read_output
      const buf = terminalOutputBuffer.get(tabId);
      if (buf) {
        const newLines = data.split('\n');
        buf.lines.push(...newLines);
        if (buf.lines.length > buf.maxLines) {
          buf.lines.splice(0, buf.lines.length - buf.maxLines);
        }
      }

      // Parse OSC 133 for command lifecycle events (just spy, don't modify)
      parseOSC133AndEmit(tabId, data, ptyProcess);
      const outputToolType = resolveAiToolTypeForTab(tabId);
      let preparedCodexReadyFrame = null;
      let deferCodexLateMcpToCommittedFrame = false;
      if (outputToolType === 'codex') {
        observeCodexNativeSettingsIntentOutput(tabId, data, ptyProcess);
        observeCodexPendingCompactTuiFeedback(tabId, data, ptyProcess);
        tryCommitCodexModelMigrationAcknowledgement(tabId, data);
        tryHandleCodexStartupAutoEnter(tabId, data);
        preparedCodexReadyFrame = prepareCodexTuiReadyFrame(tabId, data);
        deferCodexLateMcpToCommittedFrame =
          shouldDeferCodexLateMcpCandidateToCommittedFrame(tabId, preparedCodexReadyFrame);
        void tryEmitCodexTuiReady(tabId, data, preparedCodexReadyFrame).catch((err) => {
          console.warn('[CodexTuiReady] probe failed tab=' + String(tabId).slice(-12) + ' ' + (err?.message || String(err)));
        });
      }

      // ========== CLAUDE HANDSHAKE (Prompt Injection) ==========
      // Wait for prompt to appear, debounce UI settling, then send pending prompt.
      // Note: Tab (\t) for thinking mode is NOT sent here — alwaysThinkingEnabled in
      // ~/.claude/settings.json handles it globally. Toggle is available via UI buttons.
      const DEBOUNCE_MS = 300;

      // Split slash-commands from prompt body and send sequentially.
      // e.g. "/model haiku\nDo something" → send "/model haiku", wait for prompt, send "Do something"
      async function sendHandshakePrompt(term, tabId, fullPrompt) {
        var lines = fullPrompt.split('\n');
        var slashCommands = [];
        var bodyLines = [];
        var hitBody = false;
        for (var li = 0; li < lines.length; li++) {
          if (!hitBody && lines[li].trim().startsWith('/')) {
            slashCommands.push(lines[li].trim());
          } else {
            hitBody = true;
            bodyLines.push(lines[li]);
          }
        }
        // Strip leading empty lines from body
        while (bodyLines.length > 0 && bodyLines[0].trim() === '') bodyLines.shift();
        var body = bodyLines.join('\n').trim();

        console.log('[Handshake:' + tabId + '] Parsed prompt: ' + slashCommands.length + ' slash commands, body=' + body.length + ' chars');
        if (slashCommands.length > 0) {
          console.log('[Handshake:' + tabId + '] Slash commands: ' + slashCommands.join(' | '));
        }

        if (slashCommands.length > 0) {
          // Send each slash command separately, waiting for prompt return after each
          for (var ci = 0; ci < slashCommands.length; ci++) {
            console.log('[Handshake:' + tabId + '] Sending slash command ' + (ci + 1) + '/' + slashCommands.length + ': ' + slashCommands[ci]);
            const slashResult = await submitWithClaudeLocalCommandLifecycle({
              command: slashCommands[ci],
              prepare: (command) => prepareClaudeLocalCommandWatcher(
                tabId,
                command,
                'handshake',
              ),
              submit: () => safePasteAndSubmit(term, slashCommands[ci], {
                submit: true,
                ctrlCFirst: ci > 0,
                logPrefix: '[Handshake:cmd:' + tabId + ']'
              }),
              activate: (preparation) => activateClaudeLocalCommandWatcher(preparation),
              discard: (preparation, detail) => discardClaudeLocalCommandWatcherPreparation(
                preparation,
                detail?.reason || 'handshake-submit-not-proven',
              ),
            });
            if (slashResult?.submitted !== true) {
              throw new Error('Claude handshake slash command was not submitted: '
                + (slashResult?.error || 'submit-not-proven'));
            }
            // Wait for Claude to process the command and show prompt again
            console.log('[Handshake:' + tabId + '] Slash command sent, waiting for prompt return...');
            await waitForPromptReturn(term, tabId, 10000);
            console.log('[Handshake:' + tabId + '] Prompt return resolved for slash command ' + (ci + 1));
          }
        }

        if (body) {
          console.log('[Handshake:' + tabId + '] Sending body prompt (' + body.length + ' chars)');
          await safePasteAndSubmit(term, body, {
            submit: true,
            logPrefix: '[Handshake:' + tabId + ']'
          });
          console.log('[Handshake:' + tabId + '] ✅ Body prompt sent successfully');
        } else if (slashCommands.length === 0) {
          console.log('[Handshake:' + tabId + '] Empty prompt, nothing to send');
        } else {
          console.log('[Handshake:' + tabId + '] No body after slash commands (slash-only prompt)');
        }
      }

      // Wait for Claude prompt char (⏵ or >) to reappear after a command
      function waitForPromptReturn(term, tabId, timeoutMs) {
        return new Promise(function(resolve) {
          var sub = null;
          var chunkCount = 0;
          console.log('[Handshake:wait:' + tabId + '] Waiting for prompt return (timeout=' + timeoutMs + 'ms)...');
          var timer = setTimeout(function() {
            if (sub) sub.dispose();
            console.log('[Handshake:wait:' + tabId + '] ⚠️ TIMEOUT after ' + timeoutMs + 'ms (' + chunkCount + ' chunks received, none matched ⏵ or >)');
            resolve();
          }, timeoutMs);
          sub = term.onData(function(d) {
            chunkCount++;
            var s = stripVTControlCharacters(d);
            var printable = s.replace(/[\x00-\x1f]/g, '').trim();
            if (s.includes('\u23F5') || s.includes('>')) {
              clearTimeout(timer);
              console.log('[Handshake:wait:' + tabId + '] ✅ Prompt detected in chunk #' + chunkCount + ': "' + printable.substring(0, 80) + '"');
              setTimeout(function() { if (sub) sub.dispose(); resolve(); }, 200);
            } else if (printable.length > 0) {
              console.log('[Handshake:wait:' + tabId + '] Chunk #' + chunkCount + ' (no prompt): "' + printable.substring(0, 120) + '"');
            }
          });
        });
      }

      function settleClaudeInitialPrompt(term, reason) {
        const generation = claudeLaunchGenerationByTab.get(tabId)?.generation || null;
        claudeState.delete(tabId);
        claudeDebounceTimers.delete(tabId);
        if (!generation) {
          console.warn('[ClaudePromptStable] skipped tab=' + String(tabId).slice(-12)
            + ' reason=no-launch-generation trigger=' + reason);
          return;
        }
        const pendingPrompt = claudePendingPrompt.get(tabId);
        if (!pendingPrompt) {
          console.log('[Claude Handshake] Tab ' + tabId + ': no pending prompt after stable startup frame');
          return;
        }

        // A launch prompt is user traffic and must never overtake /model and
        // /effort. Register a generation-owned dispatcher now; the main-owned
        // startup gate flushes it only after both settings are proven. If the
        // transaction fails, the prompt remains queued and a successful user
        // Retry wakes the same dispatcher instead of losing the message.
        claudePendingPromptDispatchers.set(tabId, {
          generation,
          term,
          prompt: pendingPrompt,
          inflight: null,
          send: () => sendHandshakePrompt(term, tabId, pendingPrompt),
        });
        const currentGate = claudeStartupDefaultsGateByTab.get(tabId) || null;
        if (currentGate?.generation === generation && currentGate?.status === 'ready') {
          void flushClaudePendingPromptAfterStartup(tabId, generation, 'prompt-stable-gate-already-ready');
        } else {
          console.log('[ClaudeHandshake] pending prompt waits for startup defaults tab='
            + String(tabId).slice(-12)
            + ' gen=' + generation
            + ' gate=' + (currentGate?.status || 'pending'));
        }
      }
      let currentState = claudeState.get(tabId);
      const claudeControlSurfaceOwner = claudeLaunchGenerationByTab.has(tabId)
        || bridgeKnownSessions.has(tabId)
        || claudeCliActive.get(tabId) === true;
      if (claudeControlSurfaceOwner && (
        !claudePromptReady.has(tabId)
        || claudeAutoModeDefaultPromptHintTabs.has(tabId)
        || claudeTrustFolderPromptHintTabs.has(tabId)
      )) {
        const strippedHint = stripVTControlCharacters(data);
        const nextAutoModeHint = (
          (claudeAutoModeDefaultPromptHintBuffers.get(tabId) || '') + strippedHint
        ).slice(-12000);
        claudeAutoModeDefaultPromptHintBuffers.set(tabId, nextAutoModeHint);
        if (looksLikeClaudeAutoModeDefaultPromptText(nextAutoModeHint)) {
          if (!claudeAutoModeDefaultPromptHintTabs.has(tabId)) {
            console.log('[ClaudeAutoModeDefault] output hint detected tab='
              + String(tabId).slice(-12) + '; waiting for committed-frame proof');
          }
          claudeAutoModeDefaultPromptHintTabs.add(tabId);
        }
        const nextTrustHint = (
          (claudeTrustFolderPromptHintBuffers.get(tabId) || '') + strippedHint
        ).slice(-12000);
        claudeTrustFolderPromptHintBuffers.set(tabId, nextTrustHint);
        if (looksLikeClaudeTrustFolderPromptHintText(nextTrustHint)) {
          if (!claudeTrustFolderPromptHintTabs.has(tabId)) {
            console.log('[ClaudeTrustFolder] output hint detected tab='
              + String(tabId).slice(-12) + '; waiting for committed-frame proof');
          }
          claudeTrustFolderPromptHintTabs.add(tabId);
        }
      }
      const autoModeDefaultPromptHint = claudeAutoModeDefaultPromptHintTabs.has(tabId);
      const trustFolderPromptHint = claudeTrustFolderPromptHintTabs.has(tabId);
      const onboardingPromptHint = autoModeDefaultPromptHint || trustFolderPromptHint;
      if (onboardingPromptHint && currentState === 'DEBOUNCE_PROMPT') {
        clearTimeout(claudeDebounceTimers.get(tabId));
        claudeDebounceTimers.delete(tabId);
        claudeState.set(tabId, 'WAITING_PROMPT');
        currentState = 'WAITING_PROMPT';
        console.log('[ClaudeOnboarding] cancelled false prompt debounce tab='
          + String(tabId).slice(-12)
          + ' owner=' + (trustFolderPromptHint ? 'trust-folder' : 'auto-mode-default'));
      }

      // GLOBAL prompt-ready detection — independent of Claude Handshake state.
      // Same character signal Handshake uses, but fired for every tab where a
      // Claude process exists (bridgeKnownSessions). First detection promotes
      // the tab to "input ready"; mobile-web reads this through claude:get-presence
      // and stops showing the "starting Claude..." loader on its composer.
      // Cheap path: skip the stripVT call when the flag is already set OR when
      // there's no Claude process for this tab.
      let emittedGlobalTuiReady = false;
      if (!onboardingPromptHint
        && !claudePromptReady.has(tabId)
        && bridgeKnownSessions.has(tabId)
        && !aiStoppingTabs.has(tabId)) {
        const checked = currentState ? null : stripVTControlCharacters(data);
        const hayStack = checked != null ? checked : data;
        const rewindMenuFrame = looksLikeClaudeRewindMenuText(hayStack);
        if (hasClaudeComposerPromptGlyph(hayStack) || (hasClaudeAsciiComposerPrompt(hayStack) && !rewindMenuFrame)) {
          console.log('[ClaudePromptReady] Tab ' + tabId.slice(-12) + ' — input ready (⏵ rendered)');
          emittedGlobalTuiReady = publishClaudePromptReady(tabId, 'global prompt-ready');
          // BUSY here must be the AUTHORITATIVE turn flag (claudeTurnBusy, the
          // Stop-hook), NOT claudeSpinnerBusy. On Resume the PTY replays old
          // scrollback containing a stale spinner glyph (`✻ Cooked for 13s`),
          // which false-fires claudeSpinnerBusy=true → this snapshot would send
          // busy:true to the phone the instant ⏵ renders → composer locks on
          // Stop until a manual refresh. Same conflation fixed in get-presence;
          // this is the second broadcast path that bypassed it. See
          // fact-mobile-claude-pty.md::Composer busy = turn, not spinner/alive.
        }
      }

      if (currentState) {
        const stripped = stripVTControlCharacters(data);
        const term = terminals.get(tabId);

        // STEP 1: WAITING_PROMPT -> See prompt char -> Start debounce
        // Claude v2.1.32+ uses ⏵ (U+23F5) instead of >
        if (currentState === 'WAITING_PROMPT'
          && !onboardingPromptHint
          && (hasClaudeComposerPromptGlyph(stripped) || hasClaudeAsciiComposerPrompt(stripped))) {
          console.log('[Claude Handshake] Tab ' + tabId + ': Prompt detected. Starting debounce...');
          claudeState.set(tabId, 'DEBOUNCE_PROMPT');
          // Early "TUI is ready for input" signal — fires as soon as Claude
          // renders ⏵ in the PTY stream. In production logs this lands
          // 2-6 seconds BEFORE Bridge:Fresh (which depends on bridge.json
          // appearing on disk, surviving DeadTranscript guard, then PID
          // resolve). Renderer uses this for auto /effort inject so the user
          // doesn't sit looking at a ready prompt for 3+ seconds before the
          // effort line appears. Bridge:Fresh stays as the fallback path.
          if (!emittedGlobalTuiReady) {
            publishClaudePromptReady(tabId, 'prompt rendered');
          }

          const timerId = setTimeout(async () => {
            console.log('[Claude Handshake] Tab ' + tabId + ': UI settled (' + DEBOUNCE_MS + 'ms silence). Sending prompt...');
            settleClaudeInitialPrompt(term, 'handshake-output-silence');
          }, DEBOUNCE_MS);
          claudeDebounceTimers.set(tabId, timerId);
        }

        // STEP 2: DEBOUNCE_PROMPT -> More data = Reset debounce
        else if (currentState === 'DEBOUNCE_PROMPT') {
          clearTimeout(claudeDebounceTimers.get(tabId));

          const timerId = setTimeout(async () => {
            console.log('[Claude Handshake] Tab ' + tabId + ': UI settled (debounce reset). Sending prompt...');
            settleClaudeInitialPrompt(term, 'handshake-output-silence-reset');
          }, DEBOUNCE_MS);
          claudeDebounceTimers.set(tabId, timerId);
        }
      }
      // ========== END HANDSHAKE ==========

      // Detect Session ID from /status TUI output → show toast in renderer
      // Only send if this tab is known to have an active Claude session to avoid Gemini false positives
      {
        const sc = stripVTControlCharacters(data);
        const m = sc.match(/Session\s*ID[:\s]*([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i);
        if (m && bridgeKnownSessions.has(tabId) && mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('claude:status-session-detected', { tabId, sessionId: m[1] });
        }
      }

      // ========== AUTO-CONFIRM CLAUDE SETTINGS DIALOGS ==========
      // After /effort N, Claude shows in new cwds (no saved permission):
      //   Change effort level?
      //   ❯ 1. Yes, switch to <X>
      //     2. No, go back
      // After /model N, Claude can show the same shape:
      //   Switch model?
      //   ❯ 1. Yes, switch to <X>
      //     2. No, go back
      // Default highlight is on "Yes" — pressing Enter confirms. We auto-press Enter so the user
      // doesn't have to touch the terminal after clicking Model/Effort in UI.
      // Prefer the unique title line — Ink TUI splits the menu into multiple PTY chunks,
      // and inside each line spaces are encoded as ANSI cursor-forward sequences (`[1C`) instead
      // of literal spaces, so "Yes, switch to low" after strip becomes "Yes,switchtolow".
      // When the title chunk is missed, the highlighted "1. Yes, switch to ..." option
      // is a safe model-dialog fallback. Cooldown is per dialog type: /model followed
      // by /effort can legitimately show two dialogs less than 2s apart.
      {
        const sc = stripVTControlCharacters(data);
        const modelConfirmOption = /❯\s*1\.\s*Yes\s*,?\s*switch\s*to/i.test(sc);
        const dialogType = sc.includes('Change effort level')
          ? 'EffortDialog'
          : sc.includes('Switch model')
            ? 'ModelDialog'
            : modelConfirmOption
              ? 'ModelDialog'
              : null;
        if (dialogType) {
          console.log('[' + dialogType + '] Tab ' + tabId
            + ': output hint detected; waiting for current-frame proof');
          // The output stream is only a wake-up hint: Ink can split or repaint
          // this menu across chunks. Re-read the current headless screen at the
          // write boundary so a stale chunk cannot submit a later user draft.
          setTimeout(() => {
            void confirmClaudeSettingsDialogFromCurrentFrame(
              tabId,
              dialogType,
              'pty-output-hint',
            ).catch((error) => {
              console.warn('[' + dialogType + '] Tab ' + tabId
                + ': current-frame confirmation failed: '
                + (error?.message || String(error)));
            });
          }, 120);
        }
      }

      // ========== CTRL-C DANGER ZONE DETECTION ==========
      // Claude shows "Press Ctrl-C again to exit" after first Ctrl+C.
      // If we send another Ctrl+C (e.g. from send-command ctrlCFirst), Claude exits.
      // Hybrid: ON when marker detected, OFF when prompt returns AFTER minimum hold (3s).
      // Why min hold: Claude's Ink TUI re-renders full screen immediately after Ctrl+C,
      // and that re-render includes ⏵ prompt char. Without min hold, DZ would be set ON
      // and cleared OFF within milliseconds — but Claude's warning lasts ~3-4 seconds.
      {
        const sc = stripVTControlCharacters(data);

        // ENTER danger zone: detected "Press Ctrl-C again to exit" in PTY output
        // Claude Ink TUI uses cursor motion codes — after stripping, text can be:
        //   "PresCtrl-C again to exit" (from ctrlCFirst \x03)
        //   "Press Ctrl-Cagain to exit" (from user keyboard \x03)
        // Match "again to exit" which is stable across all variants.
        if (sc.includes('again to exit')) {
          // Clean up previous if any
          const prev = claudeCtrlCDangerZone.get(tabId);
          if (prev) clearTimeout(prev.timer);

          let resolve;
          const promise = new Promise(r => { resolve = r; });
          const timer = setTimeout(() => {
            // Safety fallback: clear after Claude's warning expires (~4s)
            if (claudeCtrlCDangerZone.has(tabId)) {
              claudeCtrlCDangerZone.delete(tabId);
              resolve();
              console.log('[CtrlC-DangerZone] Tab ' + tabId + ': CLEARED (TTL expired)');
              if (mainWindow && !mainWindow.isDestroyed()) {
                mainWindow.webContents.send('claude:ctrlc-danger-zone', { tabId, active: false });
              }
            }
          }, 4000);
          claudeCtrlCDangerZone.set(tabId, { resolve, promise, timer, setAt: Date.now() });
          console.log('[CtrlC-DangerZone] Tab ' + tabId + ': ON — detected "Press Ctrl-C again to exit"');
          if (mainWindow && !mainWindow.isDestroyed()) {
            mainWindow.webContents.send('claude:ctrlc-danger-zone', { tabId, active: true });
          }
        } else {
          // EXIT danger zone: prompt returned (⏵ or >) while danger zone is active
          // CRITICAL: must be `else` — same PTY chunk can contain both marker and ⏵.
          // CRITICAL: minimum hold 3s — Claude re-renders ⏵ immediately after Ctrl-C
          // but warning lasts ~3-4 seconds. Only accept ⏵ after min hold.
          const dz = claudeCtrlCDangerZone.get(tabId);
          if (dz && (Date.now() - dz.setAt >= 3000) &&
              (hasClaudePromptGlyph(sc) || sc.includes('\u2335'))) {
            // ⏵ (U+23F5) = Claude prompt, ⌵ (U+2335) = alt prompt, ╰ (U+2570) = input box bottom
            clearTimeout(dz.timer);
            claudeCtrlCDangerZone.delete(tabId);
            dz.resolve();
            console.log('[CtrlC-DangerZone] Tab ' + tabId + ': OFF — prompt returned after hold (event-driven)');
            if (mainWindow && !mainWindow.isDestroyed()) {
              mainWindow.webContents.send('claude:ctrlc-danger-zone', { tabId, active: false });
            }
          }
        }
      }

      // ========== GEMINI SPINNER BUSY DETECTION ==========
      // Detect Braille spinner + "esc to cancel" → Gemini is thinking
      // No spinner for 1.5s → Gemini finished (idle)
      {
        if (geminiActiveTabs.has(tabId)) {
          var gsc = stripVTControlCharacters(data);
          var isGeminiSpinner = GEMINI_SPINNER_RE.test(gsc);

          if (isGeminiSpinner) {
            clearTimeout(geminiSpinnerIdleTimers.get(tabId));
            geminiSpinnerIdleTimers.delete(tabId);
            if (!geminiSpinnerBusy.get(tabId)) {
              geminiSpinnerBusy.set(tabId, true);
              // Gemini became busy → user submitted input → reset char counter
              updateGeminiCharCount(tabId, 0, 'Gemini BUSY');
              console.log('[GeminiSpinner] Tab ' + tabId + ': THINKING');
              recordActivity(tabId, true, 'gemini');
              if (mainWindow && !mainWindow.isDestroyed()) {
                mainWindow.webContents.send('gemini:busy-state', { tabId, busy: true });
              }
            }
          } else if (geminiSpinnerBusy.get(tabId)) {
            // Was busy, no spinner in this chunk — schedule idle after 500ms silence
            clearTimeout(geminiSpinnerIdleTimers.get(tabId));
            geminiSpinnerIdleTimers.set(tabId, setTimeout(function() {
              geminiSpinnerBusy.set(tabId, false);
              geminiSpinnerIdleTimers.delete(tabId);
              console.log('[GeminiSpinner] Tab ' + tabId + ': IDLE (response complete)');
              recordActivity(tabId, false, 'gemini');
              if (mainWindow && !mainWindow.isDestroyed()) {
                mainWindow.webContents.send('gemini:busy-state', { tabId, busy: false });
              }
            }, 500));
          }
        }
      }
      // ========== END GEMINI SPINNER BUSY DETECTION ==========

      // ========== PROMPT BOUNDARY MARKER INJECTION ==========
      // Detect Claude prompt (⏵ U+23F5 / ❯ U+276F) transitions to inject OSC 7777 markers.
      // State machine: IDLE → BUSY (non-prompt data) → IDLE (prompt returns = inject!)
      // Marker is injected into the data stream BEFORE IPC send, so xterm.js parser
      // fires registerOscHandler(7777) at the exact buffer position of the prompt line.
      //
      // FIX: Escape Carryover — PTY can split data mid-escape-sequence (e.g. \x1b[ in chunk1,
      // 38;2;153;153;153m❯ in chunk2). Blind prepend of OSC 7777 to chunk2 would abort the
      // in-progress CSI in xterm.js parser, rendering escape params as visible text.
      // Solution: buffer incomplete escape tails, reassemble before injection.
      {
        if (claudeSpinnerBusy.has(tabId) || promptBoundaryState.has(tabId)) {
          // Reassemble any carryover escape bytes from previous chunk
          const carryover = escapeCarryover.get(tabId);
          if (carryover) {
            data = carryover + data;
            escapeCarryover.delete(tabId);
          }

          const sc = stripVTControlCharacters(data);
          const hasPrompt = hasClaudePromptGlyph(sc);
          const state = promptBoundaryState.get(tabId) || 'idle';
          const substance = sc.replace(/\s/g, '').length;

          if (state === 'idle') {
            // Non-prompt data with substance while idle → Claude started processing
            if (!hasPrompt && sc.replace(/\s/g, '').length > 5) {
              promptBoundaryState.set(tabId, 'busy');
              console.log('[BoundarySM] Tab ' + tabId.slice(-8) + ': idle→busy (seq=' + (promptBoundarySeq.get(tabId) || 0) + ')');
            }
          } else if (state === 'busy' && hasPrompt) {
            // Prompt returned while busy → response complete, inject marker
            promptBoundaryState.set(tabId, 'idle');
            const seq = (promptBoundarySeq.get(tabId) || 0) + 1;
            promptBoundarySeq.set(tabId, seq);
            // Prepend OSC before data chunk so marker lands at start of prompt frame
            data = '\x1b]7777;prompt:' + seq + '\x07' + data;
            console.log('[BoundaryMarker] Tab ' + tabId + ': Injected prompt #' + seq);
            if (mainWindow && !mainWindow.isDestroyed()) {
              mainWindow.webContents.send('claude:prompt-boundary', { tabId, seq, ts: Date.now() });
            }
          }

          // While busy, buffer any trailing incomplete escape sequence.
          // Next chunk might trigger injection — reassembly ensures we don't split escapes.
          if ((promptBoundaryState.get(tabId) || 'idle') === 'busy') {
            const tail = detectIncompleteEscapeTail(data);
            if (tail > 0) {
              escapeCarryover.set(tabId, data.slice(data.length - tail));
              data = data.slice(0, data.length - tail);
            }
          }
        }
      }
      // ========== END PROMPT BOUNDARY MARKER INJECTION ==========

      // ========== CLAUDE BUSY DETECTION (Content Spinner) ==========
      // Strip OSC sequences (window title "✳ Claude Code" is branding, NOT thinking).
      // Then check stripped TUI content for spinner chars ✢✳✶✻✽.
      {
        var isKnownCodexTab = codexTurnWatchers.has(tabId) || codexKnownSessions.has(tabId);
        var isKnownGeminiTab = geminiActiveTabs.has(tabId);
        var shouldDetectClaudeSpinner = !isKnownCodexTab && !isKnownGeminiTab && (
          claudeCliActive.get(tabId) === true ||
          bridgeKnownSessions.has(tabId) ||
          claudeTurnBusy.get(tabId) === true ||
          claudeLocalCommandWatchers.has(tabId) ||
          claudeState.has(tabId)
        );

        if (!shouldDetectClaudeSpinner) {
          if ((isKnownCodexTab || isKnownGeminiTab) && claudeSpinnerBusy.get(tabId)) {
            clearTimeout(claudeSpinnerIdleTimer.get(tabId));
            claudeSpinnerIdleTimer.delete(tabId);
            claudeSpinnerBusy.delete(tabId);
            claudeSpinnerLastSeenAt.delete(tabId);
          }
        } else {
        var dataNoOsc = data.replace(OSC_RE, '');
        var contentStripped = stripVTControlCharacters(dataNoOsc);
        var hasContentSpinner = CONTENT_SPINNER_RE.test(contentStripped);
        var compactOutputPhase = detectClaudeCompactOutputPhase(contentStripped);
        if (compactOutputPhase === 'compacted') {
          noteClaudePtyCompactOutputCompletion(tabId);
        }

        if (hasContentSpinner) {
          if (compactOutputPhase === 'compacting') {
            observeClaudeCompactFromPtyWithTranscriptProof(tabId);
          }
          claudeSpinnerLastSeenAt.set(tabId, Date.now());
          // Diagnostic: log what triggered spinner when BoundarySM is already idle.
          // PERF (2026-04-21): hot path — this log fires hundreds of times per second
          // per active Claude TUI (~142K log lines per session). Dev-only; enable in
          // prod via DEBUG_SPINNER=1 when investigating busy-detection regressions.
          var _bsmState = promptBoundaryState.get(tabId) || 'idle';
          if ((isDev || process.env.DEBUG_SPINNER === '1') && _bsmState === 'idle') {
            var _match = contentStripped.match(/[\u2722\u2733\u2736\u273B\u273D]/);
            if (_match) {
              var _idx = contentStripped.indexOf(_match[0]);
              var _ctx = contentStripped.slice(Math.max(0, _idx - 25), _idx + 26).replace(/\n/g, '\\n');
              console.log('[Spinner:DIAG] Tab ' + tabId.slice(-8) + ' BoundarySM=idle but spinner char U+' + _match[0].charCodeAt(0).toString(16).toUpperCase() + ' at pos ' + _idx + '/' + contentStripped.length + ' ctx="' + _ctx + '"');
            }
          }
          // Spinner in content → BUSY, restart idle countdown.
          // FIX: Always restart the 500ms timer (not just clear it).
          // If PTY goes silent after this chunk (e.g. "✻ Churned for 2m" is the last output),
          // the timer fires on its own. Previously we cleared+deleted the timer here,
          // relying on a FUTURE no-spinner chunk to start debounce — but if no chunk came,
          // spinner stayed BUSY forever until user switched tabs (triggering Ink re-render).
          clearTimeout(claudeSpinnerIdleTimer.get(tabId));
          claudeSpinnerIdleTimer.set(tabId, setTimeout(function() {
            // If Stop hook is authoritative for this tab (turn currently in flight per UserPromptSubmit),
            // spinner-absence is NOT end-of-turn — Claude is just between thinking phases.
            // Drop this IDLE event; the hook will fire the real Stop later.
            if (claudeTurnBusy.get(tabId) === true) {
              claudeSpinnerIdleTimer.delete(tabId);
              return;
            }
            if (claudeLocalCommandWatchers.has(tabId)) {
              console.log('[Spinner] Tab ' + tabId + ': IDLE suppressed (local command ' + claudeLocalCommandWatchers.get(tabId).command + ' active)');
              claudeSpinnerIdleTimer.delete(tabId);
              return;
            }
            claudeSpinnerBusy.set(tabId, false);
            claudeSpinnerIdleTimer.delete(tabId);
            console.log('[Spinner] Tab ' + tabId + ': IDLE');
            // Presentation-only heuristic. Exact UserPromptSubmit/Stop hooks
            // and explicit local-command brackets own every public busy edge.
          }, 500));
          if (!claudeSpinnerBusy.get(tabId)) {
            claudeSpinnerBusy.set(tabId, true);
            console.log('[Spinner] Tab ' + tabId + ': BUSY');
          }
          if (compactOutputPhase === 'compacted') {
            const localCompact = claudeLocalCommandWatchers.get(tabId);
            if (localCompact?.command === '/compact') {
              const ownership = classifyCurrentClaudeLocalCommandOwner(tabId, localCompact);
              if (!ownership.matches) {
                console.warn('[ClaudeLocalCommand] PTY completion rejected tab='
                  + tabId.slice(-12) + ' owner=' + ownership.reason);
                completeClaudeLocalCommand(tabId, 'owner-changed:' + ownership.reason);
              } else if (localCompact.filePath) {
                // PTY text is a scan hint, never completion proof. The durable
                // manual boundary/stdout read from this watcher's exact offset
                // remains the source of truth.
                localCompact.requestTranscriptScan?.();
              } else {
                // No durable source exists. Preserve the command result as
                // unknown instead of letting ambiguous screen text advance the
                // queue or leaving the loader stuck for 30 minutes.
                completeClaudeLocalCommand(tabId, 'compact-proof-unavailable');
              }
            }
          }
        }
        }
      }
      // ========== END CLAUDE BUSY DETECTION ==========

      // Colorize UUIDs (MCP Task IDs) with purple before sending to renderer
      data = colorizeUUIDs(data);

      // Keep an authoritative xterm buffer in main. Background/API flows must
      // not depend on a mounted renderer terminal to prove the current TUI row.
      const headlessPresentationWrite = fanoutTerminalPresentationData(tabId, ptyProcess, data, {
        onHeadlessWriteReserved: preparedCodexReadyFrame?.rawMcpCandidate === true
          ? (writeIdentity) => armCodexLateMcpProofPending(
            tabId,
            writeIdentity,
            preparedCodexReadyFrame,
          )
          : null,
      });
      captureReadyShellPromptFrameAfterWrite(tabId, ptyProcess);
      if (deferCodexLateMcpToCommittedFrame
        && (!headlessPresentationWrite || !codexLateMcpProofPending.has(tabId))) {
        const preview = String(
          preparedCodexReadyFrame?.inspected?.sampleText
          || preparedCodexReadyFrame?.clean
          || '',
        ).replace(/\s+/g, ' ').trim().slice(-180);
        console.warn('[CodexLateMcpProof] headless reservation unavailable tab='
          + String(tabId).slice(-12));
        const invalidated = invalidateCodexTuiReadyForStartupBlocker(
          tabId,
          'late-mcp-headless-reservation',
          preview,
          ['mcp-startup-proof-unavailable'],
          { authoritativeCurrentFrame: true },
        );
        if (invalidated) {
          emitAgentReadinessChanged(tabId, {
            toolType: 'codex',
            source: 'late-mcp-headless-reservation',
            status: 'pending',
            reason: 'late-mcp-frame-proof-unavailable',
          });
          broadcastCodexPublicRuntimeSnapshot(tabId, 'late-mcp-frame-proof-unavailable');
        }
      }
    });

    // Смерть терминала приходит из ФОНОВОГО ПОТОКА модуля терминала, и её
    // обработчик — единственное место, где обычная ошибка убивает всё
    // приложение целиком, а не пишется в лог. Модуль вызывает наш обработчик
    // через мост между потоками; исключение, вылетевшее наружу, там уже некому
    // поймать — оно превращается в аварийное завершение процесса без единой
    // строки в логе (пять таких падений 18.08, все в момент закрытия
    // приложения: 18:10, 19:28, 20:28, 20:39 и 03:32 по местному времени;
    // отчёты macOS показывают обрыв ровно в этом мосте, а не нехватку памяти).
    //
    // Хуже всего это именно при закрытии: окно уже уничтожается, часть карт
    // состояния уже очищена соседними обработчиками, а сюда одновременно
    // прилетает выход десятков терминалов — и первая же ошибка уносит процесс
    // ДО того, как отметятся оборванные сессии. В логах за все пять падений
    // строки «[Shutdown:will-quit] cleared=» нет ни разу: приложение не дожило
    // до неё. Отсюда и потеря кнопки «Продолжить» после установки новой сборки.
    //
    // Поэтому тело обработчика целиком обёрнуто: уборка одной вкладки не имеет
    // права уронить приложение, а её отказ обязан быть видимым в логе.
    ptyProcess.onExit((exitCode) => {
      try {
        if (!ownsTerminalRuntime(terminals, tabId, ptyProcess)) {
          console.warn('[PTY:STALE_EXIT] ignored tab=' + String(tabId).slice(-12)
            + ' oldPid=' + ptyProcess.pid
            + ' currentPid=' + (terminals.get(tabId)?.pid || '-')
            + ' exitCode=' + JSON.stringify(exitCode));
          return;
        }
        aiBoundaryTestGate.cancelMatching({ tabId }, 'terminal-exited');
        // [JsonlChainDiag] PTY shell death — if Claude was streaming an assistant turn at
        // this moment, the in-flight assistant JSONL entry is lost. Surface session state
        // so we can correlate later breaks with this exit point.
        const _diagSid = bridgeKnownSessions.get(tabId) || null;
        const _diagLocalBusy = claudeLocalCommandWatchers.has(tabId);
        const _diagBusy = claudeTurnBusy.get(tabId) === true || claudeSpinnerBusy.get(tabId) === true || _diagLocalBusy;
        const _diagSpinBusy = claudeSpinnerBusy.get(tabId) === true;
        const _diagTurnBusy = claudeTurnBusy.get(tabId) === true;
        console.error(`[PTY:EXIT] tabId=${tabId} pid=${ptyProcess.pid} exitCode=${JSON.stringify(exitCode)} cwd=${workingDir} shell=${shell} args=${JSON.stringify(shellArgs)}`);
        console.error(`[JsonlChainDiag:PtyExit] tabId=${tabId} shellPid=${ptyProcess.pid} sessionId=${_diagSid ? _diagSid.substring(0, 8) : 'none'} spinnerBusy=${_diagSpinBusy} turnBusy=${_diagTurnBusy} localBusy=${_diagLocalBusy} ${_diagBusy ? '*** EXITED MID-TURN — likely JSONL chain break next user prompt ***' : '(idle, safe)'}`);
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('terminal:exit', tabId, exitCode);
        }
        deleteTerminalRuntimeIfOwned(terminals, tabId, ptyProcess);
        terminalCwdChangeProofs.cancel(tabId, null, 'terminal_generation_changed');
        terminalShellReadiness.remove(tabId, ptyProcess);
        terminalProjects.delete(tabId);
        terminalProjectIds.delete(tabId);
        terminalCommandState.delete(tabId);
        clearTimeout(codexFinishDebounceTimers.get(tabId));
        codexFinishDebounceTimers.delete(tabId);
        disarmCodexProviderSemanticSource(tabId, 'pty-exit');
        safelyObserveProviderSemantic(
          'pty-exit-clear',
          () => providerSemanticShadow.clear(tabId, 'pty-exit'),
        );
        clearCodexDescendantExitRecheck(tabId, 'pty-exit');
        terminalInitialCommand.delete(tabId);
        terminalOutputBuffer.delete(tabId);
        console.log('[HeadlessXterm] retain final snapshot tab='
          + String(tabId).slice(-12)
          + ' reason=pty-exit');
        invalidateAiProcessLookupCache(tabId);
        clearAiStopping(tabId, 'pty-exit');
        clearCodexLaunchPayload(tabId, 'pty-exit');
  	      claudeToolScreenHolds.clear(tabId);
  	      claudeCliActive.delete(tabId);
  	      clearBridgeTab(tabId, 'pty-exit');
  	      clearCodexKnownSession(tabId, 'pty-exit');
        clearCodexTuiReady(tabId, 'pty-exit');
  	      clearCodexStartupAutoEnter(tabId, 'pty-exit');
  	      taskCompletionIntents.abortTurn(tabId);
  	      clearTimeout(geminiSpinnerIdleTimers.get(tabId));
        geminiSpinnerBusy.delete(tabId);
        geminiSpinnerIdleTimers.delete(tabId);
        geminiActiveTabs.delete(tabId);
  	      geminiInputCharCount.delete(tabId);
  	      closeCodexWatcher(tabId);
  	      closeCodexTurnWatcher(tabId, 'pty-exit');
        // Close any open activity interval on PTY death (idempotent — covers
        // whichever engine, claude or gemini, was mid-turn when the shell died).
        recordActivity(tabId, false);
        // Claude spinner cleanup on PTY exit
        clearTimeout(claudeSpinnerIdleTimer.get(tabId));
        if (claudeSpinnerBusy.get(tabId)) {
          console.log('[Spinner] Tab ' + tabId + ': IDLE (PTY exit cleanup)');
          if (mainWindow && !mainWindow.isDestroyed()) {
            mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: _diagLocalBusy ? 'local-command' : undefined });
          }
        }
        // Notify mobile-web subscribers that the PTY+Claude session for this
        // tab is gone — without this the phone composer stays in "active" mode
        // even though the underlying Claude process exited (the WS doesn't see
        // a follow-up busy-state event because hooks won't fire after exit).
        console.log('[MobBcast] busy+snapshot tab=' + String(tabId).slice(-12) + ' busy=false status=inactive src=pty-exit');
        _webBroadcast(tabId, { type: 'busy', busy: false });
        _webBroadcast(tabId, { type: 'snapshot', sessionId: bridgeKnownSessions.get(tabId) || null, busy: false, sessionStatus: 'inactive', inputReady: false });
        claudePromptReady.delete(tabId);
        claudeSpinnerBusy.delete(tabId);
        claudeSpinnerIdleTimer.delete(tabId);
        clearClaudeConfirmDialogCooldown(tabId);
        claudeAutoModeDefaultPromptHintTabs.delete(tabId);
        claudeAutoModeDefaultPromptHintBuffers.delete(tabId);
      } catch (err) {
        // Именно console.error: он пишется в файл всегда, даже без тега.
        console.error('[PTY:EXIT_HANDLER_FAILED] tab=' + String(tabId).slice(-12)
          + ' pid=' + (ptyProcess?.pid ?? '-')
          + ' — уборка после выхода терминала не доведена до конца: '
          + (err && err.message ? err.message : String(err)));
        try { console.error(err && err.stack ? err.stack : ''); } catch {}
      }
    });

    console.timeEnd(`[PERF:main] terminal:create ${tabId}`);
    return { pid: ptyProcess.pid, cwd: workingDir };
  });

// Bracketed Paste Mode escape sequences
const PASTE_START = '\x1b[200~';
const PASTE_END = '\x1b[201~';

// Per-terminal serializer for safePasteAndSubmit. Two concurrent invocations
// on the same PTY interleave bytes (Ctrl+S, brackets, /commands, Enter from
// different sources mix together) → Claude TUI submits half-pasted text twice
// and slash commands get swallowed by an open bracketed-paste of another
// caller. Was observed in session bb95e71d (2026-05-16): queue runner started
// a 49156-char paste, user clicked Compact mid-stream — Enter from /compact
// landed inside the first paste, the big prompt got submitted twice in halves,
// /compact text ended up as part of the prompt. Fix: chain every safePaste
// for the same term on a single promise; second caller waits until first
// returns. WeakMap key on term (no manual cleanup needed when PTY dies).
const pasteInflight = new WeakMap();
const ptyActiveWriteOperation = new WeakMap();
const ptyLastQueuedWriteOperation = new WeakMap();
const ptyWriteOwners = new WeakMap();

function withPtyWriteLock(term, work, operation = null, reentrantOwner = null) {
  // Only a live, exact main-owned transaction can re-enter. Tokens never
  // cross IPC, and cannot be reused by late callbacks after the outer exits.
  if (reentrantOwner !== null) {
    if (ptyWriteOwners.get(term) !== reentrantOwner || reentrantOwner.active !== true) {
      return Promise.reject(new Error('pty_write_owner_expired'));
    }
    const previousOperation = ptyActiveWriteOperation.get(term) || null;
    if (operation) ptyActiveWriteOperation.set(term, operation);
    return Promise.resolve().then(() => {
      if (ptyWriteOwners.get(term) !== reentrantOwner || reentrantOwner.active !== true) {
        throw new Error('pty_write_owner_expired');
      }
      return work(reentrantOwner);
    }).finally(() => {
      if (operation && ptyActiveWriteOperation.get(term) === operation) {
        if (previousOperation) ptyActiveWriteOperation.set(term, previousOperation);
        else ptyActiveWriteOperation.delete(term);
      }
      if (operation?.submitted === true && previousOperation) previousOperation.submitted = true;
    });
  }
  const prev = pasteInflight.get(term) || Promise.resolve();
  if (operation) ptyLastQueuedWriteOperation.set(term, operation);
  const next = prev.catch(() => {}).then(async () => {
    const owner = { active: true };
    ptyWriteOwners.set(term, owner);
    if (operation) ptyActiveWriteOperation.set(term, operation);
    try {
      return await work(owner);
    } finally {
      owner.active = false;
      if (ptyWriteOwners.get(term) === owner) ptyWriteOwners.delete(term);
      if (operation && ptyActiveWriteOperation.get(term) === operation) {
        ptyActiveWriteOperation.delete(term);
      }
    }
  });
  pasteInflight.set(term, next);
  return next.finally(() => {
    if (pasteInflight.get(term) === next) {
      pasteInflight.delete(term);
    }
    if (operation && ptyLastQueuedWriteOperation.get(term) === operation) {
      ptyLastQueuedWriteOperation.delete(term);
    }
  });
}

function markActivePtySubmit(term, { identityPending = false } = {}) {
  const operation = ptyActiveWriteOperation.get(term) || null;
  if (!operation) return;
  operation.submitted = true;
  operation.identityPending = operation.identityPending === true || identityPending === true;
  operation.submittedAt = Date.now();
}

// Per-tab prompt delivery audits. Both agents own an ordered set: type-ahead,
// compact and queueing can delay confirmation of A until after B has already
// been submitted. A later expectation must never replace or fail an earlier
// one, and a bounded caller timeout means "not confirmed yet", never failure.
const pendingPasteAudit = new Map(); // tabId → Claude audit[] (ordered)
const pendingCodexPasteAudit = new Map();
const durableCodexAuditReconcileInflight = new Map();
const deferredCodexPromptAuditContexts = new Map(); // tabId → exact audit detail[] awaiting task_started
const CLAUDE_PASTE_AUDIT_TIMEOUT_MS = 8000;
const CODEX_PASTE_AUDIT_TIMEOUT_MS = 8000;
const CLAUDE_PASTE_AUDIT_MAX_AGE_MS = 30 * 60 * 1000;
const CLAUDE_PASTE_AUDIT_MAX_PENDING_PER_TAB = 32;
const CODEX_PASTE_AUDIT_MAX_AGE_MS = 30 * 60 * 1000;
const CODEX_PASTE_AUDIT_MAX_PENDING_PER_TAB = 32;

function claudePasteAuditTranscriptConsumerId(tabId, audit) {
  const identity = audit?.sendAttemptId
    || audit?.handoffId
    || String(audit?.sentAt || Date.now());
  return 'main:claude-prompt-audit:' + String(tabId) + ':' + String(identity);
}

async function retainClaudePasteAuditTranscriptObserver(tabId, audit) {
  const boundary = audit?.preSubmitBoundary || null;
  const sessionId = boundary?.sessionId || audit?.historySessionId || null;
  if (
    !audit
    || audit.finished === true
    || boundary?.available !== true
    || !boundary?.transcriptPath
    || !sessionId
  ) {
    return { retained: false, reason: 'exact-transcript-owner-unavailable' };
  }
  const consumerId = claudePasteAuditTranscriptConsumerId(tabId, audit);
  const cwd = terminalProjects.get(tabId) || null;
  try {
    const subscribed = await transcriptService.subscribe({
      tabId,
      consumerId,
      toolType: 'claude',
      sessionId,
      cwd,
    });
    if (subscribed?.success !== true) {
      return {
        retained: false,
        reason: subscribed?.error || 'transcript-subscribe-failed',
      };
    }
    audit.transcriptConsumerId = consumerId;
    console.log('[PasteAudit:Observer] retained tab=' + String(tabId).slice(-12)
      + ' handoff=' + (audit.handoffId || '-')
      + ' session=' + String(sessionId).slice(0, 8));
    return { retained: true, consumerId };
  } catch (error) {
    return {
      retained: false,
      reason: error?.message || String(error),
    };
  }
}

function releaseClaudePasteAuditTranscriptObserver(tabId, audit, reason) {
  const consumerId = audit?.transcriptConsumerId || null;
  if (!consumerId) return false;
  audit.transcriptConsumerId = null;
  void transcriptService.unsubscribe({ consumerId }).then((result) => {
    console.log('[PasteAudit:Observer] released tab=' + String(tabId).slice(-12)
      + ' handoff=' + (audit.handoffId || '-')
      + ' reason=' + reason
      + ' removed=' + (result?.removed === true));
  }).catch((error) => {
    console.warn('[PasteAudit:Observer] release failed tab=' + String(tabId).slice(-12)
      + ' handoff=' + (audit.handoffId || '-')
      + ' reason=' + reason
      + ' error=' + (error?.message || String(error)));
  });
  return true;
}

function dropClaudePasteAuditUnconfirmed(tabId, audit, reason) {
  if (!audit || audit.finished === true) return false;
  const audits = pendingPasteAudit.get(tabId);
  const index = Array.isArray(audits) ? audits.indexOf(audit) : -1;
  if (index >= 0) {
    audits.splice(index, 1);
    if (audits.length === 0) pendingPasteAudit.delete(tabId);
  }
  if (audit.timer) clearTimeout(audit.timer);
  audit.timer = null;
  audit.finished = true;
  audit.result = {
    success: false,
    error: 'claude_user_message_audit_unconfirmed_evicted',
    lateReconciliationPending: true,
    expectedLen: audit.expectedLen,
    expectedHash: audit.expectedHash,
  };
  wakeClaudePostEnterResolutionWaiter(audit, 'audit-evicted:' + reason);
  releaseClaudePasteAuditTranscriptObserver(tabId, audit, 'evicted:' + reason);
  if (typeof audit.resolve === 'function') {
    audit.resolve(audit.result);
    audit.resolve = null;
  }
  // Memory/observer bound, not a delivery verdict: publishing it as an audit
  // result would turn "we no longer know" into SEND FAILED on a delivered row.
  console.warn('[PasteAudit:EVICT_UNCONFIRMED] tab=' + String(tabId).slice(-12)
    + ' handoff=' + (audit.handoffId || '-')
    + ' reason=' + reason
    + ' ageMs=' + Math.max(0, Date.now() - Number(audit.sentAt || Date.now()))
    + ' expectedLen=' + Number(audit.expectedLen || 0));
  audit.expectedText = '';
  audit.presentationSnapshot = null;
  return true;
}

function pruneClaudePasteAudits(tabId, now = Date.now()) {
  const audits = pendingPasteAudit.get(tabId);
  if (!Array.isArray(audits) || audits.length === 0) return;
  const retention = partitionCodexPendingPromptAuditsForRetention(audits, {
    now,
    maxAgeMs: CLAUDE_PASTE_AUDIT_MAX_AGE_MS,
    maxPending: CLAUDE_PASTE_AUDIT_MAX_PENDING_PER_TAB,
  });
  for (const { audit, reason } of retention.evicted) {
    dropClaudePasteAuditUnconfirmed(tabId, audit, reason);
  }
}

function getPendingClaudePasteAudits(tabId) {
  pruneClaudePasteAudits(tabId);
  const audits = pendingPasteAudit.get(tabId);
  return Array.isArray(audits) ? audits : [];
}

function enqueueClaudePasteAudit(tabId, audit) {
  const audits = getPendingClaudePasteAudits(tabId);
  if (audits.length === 0) {
    pendingPasteAudit.set(tabId, [audit]);
    return;
  }
  audits.push(audit);
  pruneClaudePasteAudits(tabId);
}

// Bridge clear = the Claude process is gone. Run one final scan of the
// already-written tail for each pending expectation; anything still
// unconfirmed is evicted as unknown (lateReconciliationPending), never as a
// proven delivery failure — mirroring the Codex watcher-close contract.
function finalizeClaudePasteAuditsOnBridgeClear(tabId) {
  const audits = getPendingClaudePasteAudits(tabId);
  if (audits.length === 0) return;
  const snapshot = [...audits];
  (async () => {
    const claimedByteOffsets = new Set();
    for (const audit of snapshot) {
      if (audit.finished === true) continue;
      const transcriptPath = audit.preSubmitBoundary?.transcriptPath || null;
      if (transcriptPath) {
        try {
          const candidates = await readClaudeUserRecords(transcriptPath, audit.preSubmitBoundary);
          const selection = selectClaudePendingPromptAudit([audit], candidates, {
            hashText: pasteAuditHash,
            claimedByteOffsets,
          });
          try {
            observeClaudePromptShapeCandidates(tabId, [audit], candidates, {
              selection, claimedByteOffsets, source: 'bridge-clear-final-scan',
            });
          } catch {}
          if (selection) {
            claimedByteOffsets.add(selection.candidate.byteOffset);
            const actualText = selection.candidate.text;
            const record = selection.candidate.record;
            const actualHash = pasteAuditHash(actualText);
            const canonicalIdentity = claudeAuditCanonicalIdentity(
              audit,
              actualText,
              pasteAuditHash,
            );
            const auditSessionId = record?.sessionId || audit.historySessionId || null;
            const auditTimestamp = record?.timestamp || new Date(audit.sentAt).toISOString();
            const presentationSaved = saveAuditedPromptPresentation(projectManager?.db, {
              toolType: 'claude',
              sessionId: auditSessionId,
              entryUuid: record?.uuid || null,
              auditTimestamp,
              actualText,
              actualHash,
              snapshot: audit.presentationSnapshot,
            });
            console.log('[PasteAudit] bridge-clear final scan confirmed tab=' + String(tabId).slice(-12)
              + ' handoff=' + (audit.handoffId || '-')
              + ' presentationSaved=' + presentationSaved);
            finishClaudePasteAudit(tabId, audit, {
              success: true,
              actualLen: actualText.length,
              actualHash,
              sessionId: auditSessionId,
              entryUuid: record?.uuid || null,
              auditTimestamp,
              recordByteOffset: Number(selection.candidate.byteOffset),
              presentationSaved,
              expectedLen: audit.expectedLen,
              expectedHash: audit.expectedHash,
              canonicalized: canonicalIdentity.canonicalized,
              canonicalReason: canonicalIdentity.canonicalReason,
            });
            continue;
          }
        } catch (e) {
          console.warn('[PasteAudit] bridge-clear final scan failed tab=' + String(tabId).slice(-12)
            + ' handoff=' + (audit.handoffId || '-')
            + ' error=' + (e?.message || String(e)));
        }
      }
      dropClaudePasteAuditUnconfirmed(tabId, audit, 'bridge-clear');
    }
  })();
}

function dropCodexPasteAuditUnconfirmed(tabId, audit, reason) {
  if (!audit || audit.finished === true) return false;
  const audits = pendingCodexPasteAudit.get(tabId);
  const index = Array.isArray(audits) ? audits.indexOf(audit) : -1;
  if (index < 0) return false;
  audits.splice(index, 1);
  if (audits.length === 0) pendingCodexPasteAudit.delete(tabId);
  if (audit.timer) clearTimeout(audit.timer);
  audit.timer = null;
  audit.finished = true;
  audit.result = {
    success: false,
    error: 'codex_user_message_audit_unconfirmed_evicted',
    lateReconciliationPending: true,
    expectedLen: audit.expectedLen,
    expectedHash: audit.expectedHash,
  };
  if (typeof audit.resolve === 'function') {
    audit.resolve(audit.result);
    audit.resolve = null;
  }
  markCodexAuditDeliveryUnknown(
    tabId,
    audit,
    'codex-audit-retention-' + reason,
    { ageMs: Math.max(0, Date.now() - Number(audit.sentAt || Date.now())) },
  );
  publishAgentPromptAuditResult(tabId, audit, {
    success: false,
    status: 'delivery-unknown',
    deliveryUnknown: true,
    auditPending: false,
    error: 'codex_user_message_audit_unconfirmed_evicted',
    code: 'codex_user_message_audit_unconfirmed_evicted',
    expectedLen: audit.expectedLen,
    expectedHash: audit.expectedHash,
  }, 'codex');
  // This is a memory/observer bound, not a delivery verdict. Publishing it as
  // a delivery failure would be false. The finite delivery-unknown projection
  // remains replay-blocked and can still be promoted by durable late audit.
  console.warn('[CodexPasteAudit:EVICT_UNCONFIRMED] tab=' + String(tabId).slice(-12)
    + ' handoff=' + (audit.handoffId || '-')
    + ' reason=' + reason
    + ' ageMs=' + Math.max(0, Date.now() - Number(audit.sentAt || Date.now()))
    + ' expectedLen=' + Number(audit.expectedLen || 0));
  audit.expectedText = '';
  audit.actualPayload = null;
  audit.presentationSnapshot = null;
  return true;
}

function pruneCodexPasteAudits(tabId, now = Date.now()) {
  const audits = pendingCodexPasteAudit.get(tabId);
  if (!Array.isArray(audits) || audits.length === 0) return;
  const retention = partitionCodexPendingPromptAuditsForRetention(audits, {
    now,
    maxAgeMs: CODEX_PASTE_AUDIT_MAX_AGE_MS,
    maxPending: CODEX_PASTE_AUDIT_MAX_PENDING_PER_TAB,
  });
  for (const { audit, reason } of retention.evicted) {
    dropCodexPasteAuditUnconfirmed(tabId, audit, reason);
  }
}

function getPendingCodexPasteAudits(tabId) {
  pruneCodexPasteAudits(tabId);
  const audits = pendingCodexPasteAudit.get(tabId);
  return Array.isArray(audits) ? audits : [];
}

function hasPendingCodexPasteAudit(tabId, audit = null) {
  const audits = getPendingCodexPasteAudits(tabId);
  return audit ? audits.includes(audit) : audits.length > 0;
}

function enqueueCodexPasteAudit(tabId, audit) {
  pruneCodexPasteAudits(tabId);
  const audits = getPendingCodexPasteAudits(tabId);
  if (audits.length === 0) {
    pendingCodexPasteAudit.set(tabId, [audit]);
    return;
  }
  audits.push(audit);
  pruneCodexPasteAudits(tabId);
}

function removePendingCodexPasteAudit(tabId, audit) {
  const audits = getPendingCodexPasteAudits(tabId);
  const index = audits.indexOf(audit);
  if (index < 0) return false;
  audits.splice(index, 1);
  if (audits.length === 0) pendingCodexPasteAudit.delete(tabId);
  return true;
}

function captureCodexPromptAuditBoundary(tabId, capturedAt = Date.now()) {
  const watcher = codexTurnWatchers.get(tabId) || null;
  if (!watcher?.sessionId || !watcher?.filePath) {
    return {
      capturedAt,
      sessionId: null,
      filePath: null,
      fileSize: null,
    };
  }
  let fileSize = null;
  try {
    // Metadata only: the rollout itself is never synchronously read here.
    fileSize = fs.statSync(watcher.filePath).size;
  } catch (error) {
    console.warn('[CodexPasteAudit] pre-Enter boundary stat failed tab='
      + String(tabId).slice(-12)
      + ' session=' + String(watcher.sessionId).slice(0, 8)
      + ' error=' + (error?.message || String(error)));
  }
  return {
    capturedAt,
    sessionId: watcher.sessionId,
    filePath: watcher.filePath,
    fileSize: Number.isFinite(fileSize) ? Number(fileSize) : null,
  };
}

function resolveCodexPendingAuditCatchUpOffset(tabId, sessionId, filePath, fileSize) {
  const audits = getPendingCodexPasteAudits(tabId)
    .filter((audit) => audit?.awaitUserMessage === true);
  if (audits.length === 0) return fileSize;
  const boundaries = [];
  for (const audit of audits) {
    const boundary = audit?.preSubmitBoundary || null;
    if (
      !boundary
      || String(boundary.sessionId || '') !== String(sessionId || '')
      || String(boundary.filePath || '') !== String(filePath || '')
      || !Number.isFinite(boundary.fileSize)
    ) {
      // A linked child rollout can contain the awaited record after copied
      // history, so it must be scanned from its beginning. The causal matcher
      // rejects copied records by timestamp.
      return 0;
    }
    boundaries.push(Math.max(0, Math.min(fileSize, Number(boundary.fileSize))));
  }
  return Math.min(...boundaries);
}

function pasteAuditHash(text) {
  return promptAuditFingerprint(text);
}

function pasteAuditPreview(text, start = 0) {
  return String(text || '').substring(start, start + 80).replace(/\s+/g, ' ');
}

function isOrchestrationPromptAudit(detail) {
  const handoffId = typeof detail?.handoffId === 'string' ? detail.handoffId : '';
  return detail?.success === true
    && (handoffId.startsWith('orchestration:')
      || handoffId.startsWith('orchestration-complete:'));
}

function compatiblePromptAuditExecutionContext(detail, candidate) {
  if (!candidate || typeof candidate !== 'object') {
    return { context: null, reason: 'active-execution-context-unavailable' };
  }
  if (candidate.provider !== detail.toolType) {
    return { context: null, reason: 'active-execution-context-provider-mismatch' };
  }
  if (!detail.sessionId || !candidate.sessionId) {
    return { context: null, reason: 'active-execution-context-session-unproven' };
  }
  if (candidate.sessionId !== detail.sessionId) {
    return { context: null, reason: 'active-execution-context-session-mismatch' };
  }
  return { context: candidate, reason: null };
}

function routeAgentPromptAuditDetail(detail, {
  renderer = true,
  web = true,
} = {}) {
  if (renderer && mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('agent-prompt:audit-result', detail);
  }
  if (!web) return;
  try {
    const routeAudit = require(path.join(srcMainDir, 'web-server')).notifyAgentPromptAuditResult;
    const routed = typeof routeAudit === 'function' ? routeAudit(detail) : null;
    if (routed && typeof routed.catch === 'function') {
      void routed.catch((error) => {
        console.warn('[Orchestration] prompt audit routing failed handoff='
          + detail.handoffId + ' error=' + (error?.message || String(error)));
      });
    }
  } catch (error) {
    console.warn('[Orchestration] prompt audit router unavailable handoff='
      + detail.handoffId + ' error=' + (error?.message || String(error)));
  }
}

function deferCodexPromptAuditExecutionContext(detail) {
  const current = deferredCodexPromptAuditContexts.get(detail.tabId) || [];
  const existingIndex = current.findIndex((candidate) => candidate.handoffId === detail.handoffId);
  if (existingIndex >= 0) current[existingIndex] = detail;
  else current.push(detail);
  deferredCodexPromptAuditContexts.set(detail.tabId, current);
  console.warn('[Orchestration] exact Codex prompt audit awaits task_started context handoff='
    + detail.handoffId + ' tab=' + String(detail.tabId).slice(-12));
}

function replayDeferredCodexPromptAuditExecutionContext(tabId) {
  const pending = deferredCodexPromptAuditContexts.get(tabId) || [];
  if (pending.length === 0) return;
  const activeContext = getActiveAgentExecutionContext(tabId);
  const compatible = pending.filter((detail) => (
    compatiblePromptAuditExecutionContext(detail, activeContext).context
  ));
  if (compatible.length !== 1) {
    console.warn('[Orchestration] Codex prompt audit context replay refused tab='
      + String(tabId).slice(-12)
      + ' pending=' + pending.length
      + ' compatible=' + compatible.length);
    return;
  }
  const selected = compatible[0];
  const remaining = pending.filter((detail) => detail !== selected);
  if (remaining.length > 0) deferredCodexPromptAuditContexts.set(tabId, remaining);
  else deferredCodexPromptAuditContexts.delete(tabId);
  routeAgentPromptAuditDetail({
    ...selected,
    executionContext: activeContext,
    executionContextSource: 'codex-task-started',
    executionContextDiagnostic: null,
  }, { renderer: false, web: true });
}

function discardDeferredCodexPromptAuditExecutionContexts(tabId, reason) {
  const pending = deferredCodexPromptAuditContexts.get(tabId) || [];
  if (pending.length === 0) return;
  deferredCodexPromptAuditContexts.delete(tabId);
  console.warn('[Orchestration] Codex prompt audit context remained unbound tab='
    + String(tabId).slice(-12)
    + ' pending=' + pending.length
    + ' reason=' + reason);
}

function publishAgentPromptAuditResult(tabId, audit, result, toolType) {
  if (!audit?.handoffId) return;
  if (audit.sendOperationKey || audit.sendAttemptId) {
    const durable = audit.sendOperationKey
      ? agentSendReceiptStore.get(audit.sendOperationKey)
      : null;
    const exactDurableAttempt = durable
      && audit.sendAttemptId
      && durable.attemptId === audit.sendAttemptId
      && durable.state !== AGENT_SEND_DURABLE_STATES.NOT_SUBMITTED;
    if (!exactDurableAttempt) {
      console.warn('[AgentSendReceipt] ignore stale/foreign prompt audit before projections'
        + ' operation=' + String(audit.sendOperationKey || '-').slice(0, 72)
        + ' expectedAttempt=' + String(durable?.attemptId || '-').slice(0, 12)
        + ' actualAttempt=' + String(audit.sendAttemptId || '-').slice(0, 12)
        + ' state=' + (durable?.state || 'missing'));
      return;
    }
    if (result?.success === true) {
      if (toolType === 'codex' && durable.promptHash !== (result.expectedHash || audit.expectedHash)) {
        const projection = projectCodexImageAuditToRequest({ tabId, record: durable, audit, result });
        if (projection.applied) {
          // Original request identity and PTY image aliases are different
          // representations of this exact operation, not interchangeable hashes.
          result = {
            ...result,
            expectedHash: projection.requestHash,
            expectedLen: projection.requestLength,
            transportExpectedHash: projection.transportHash,
            transportExpectedLen: projection.transportLength,
            canonicalized: true,
            canonicalReason: projection.canonicalReason,
            imageRequestProjection: { kind: projection.kind, imageCount: projection.imageCount },
          };
          console.log('[CodexImageAuditProjection] request identity proven'
            + ' operation=' + String(audit.sendOperationKey).slice(0, 72)
            + ' attempt=' + String(audit.sendAttemptId).slice(0, 12)
            + ' images=' + projection.imageCount
            + ' requestHash=' + projection.requestHash
            + ' transportHash=' + projection.transportHash);
        } else if (audit.imageRequestProjection) {
          console.warn('[CodexImageAuditProjection] rejected reason=' + projection.reason
            + ' operation=' + String(audit.sendOperationKey).slice(0, 72));
        }
      }
      const durablePromotion = agentSendReceiptStore.promoteFromAudit({
        success: true,
        operationKey: audit.sendOperationKey,
        attemptId: audit.sendAttemptId,
        provider: toolType,
        sessionId: result.sessionId,
        promptHash: result.expectedHash || audit.expectedHash || result.actualHash,
        actualHash: result.actualHash,
        expectedHash: result.expectedHash || audit.expectedHash || null,
        canonicalized: result.canonicalized === true,
        canonicalReason: result.canonicalReason || null,
        entryUuid: result.entryUuid || null,
        sourceIdentity: result.sourceIdentity || null,
        transcriptBoundary: result.transcriptBoundary || null,
        auditTimestamp: result.auditTimestamp || null,
      });
      const durableAccepted = durablePromotion?.promoted === true
        || (durablePromotion?.idempotent === true
          && durablePromotion?.record?.state === AGENT_SEND_DURABLE_STATES.CONFIRMED);
      if (!durableAccepted) {
        console.warn('[AgentSendReceipt] ignore audit rejected by durable identity'
          + ' operation=' + String(audit.sendOperationKey).slice(0, 72)
          + ' attempt=' + String(audit.sendAttemptId).slice(0, 12)
          + ' reason=' + (durablePromotion?.reason || 'unknown')
          + ' mismatches=' + (durablePromotion?.mismatchedFields || []).join(','));
        return;
      }
    }
  }
  const baseDetail = {
    tabId,
    handoffId: audit.handoffId,
    sendAttemptId: audit.sendAttemptId || null,
    sendOperationKey: audit.sendOperationKey || null,
    toolType,
    source: audit.source || null,
    success: result?.success === true,
    cancelled: result?.cancelled === true,
    error: result?.error || null,
    code: result?.code || null,
    status: result?.status || null,
    semanticStatus: result?.semanticStatus || null,
    providerAccepted: typeof result?.providerAccepted === 'boolean'
      ? result.providerAccepted
      : null,
    providerTurnCreated: typeof result?.providerTurnCreated === 'boolean'
      ? result.providerTurnCreated
      : null,
    providerQueueReturned: result?.providerQueueReturned === true,
    providerQueueOperation: result?.providerQueueOperation || null,
    composerDraftState: result?.composerDraftState || null,
    draftPreserved: result?.draftPreserved === true,
    late: audit.callerTimedOut === true,
    auditTimestamp: result?.auditTimestamp || null,
    actualHash: result?.actualHash || null,
    actualLen: Number.isFinite(result?.actualLen) ? Number(result.actualLen) : null,
    sessionId: result?.sessionId || null,
    sourceIdentity: result?.sourceIdentity || null,
    canonicalized: result?.canonicalized === true,
    canonicalReason: result?.canonicalReason || null,
    entryUuid: result?.entryUuid || null,
    expectedHash: result?.expectedHash || audit.expectedHash || null,
    transportExpectedHash: result?.transportExpectedHash || null,
    transportExpectedLen: result?.transportExpectedLen ?? null,
    imageRequestProjection: result?.imageRequestProjection || null,
    expectedLen: Number.isFinite(result?.expectedLen)
      ? Number(result.expectedLen)
      : (Number.isFinite(audit.expectedLen) ? Number(audit.expectedLen) : null),
    queuedAtSubmit: audit.queuedAtSubmit === true,
  };
  const candidateContext = result?.executionContext
    || audit.executionContext
    || null;
  const contextVerdict = compatiblePromptAuditExecutionContext(baseDetail, candidateContext);
  const detail = {
    ...baseDetail,
    executionContext: contextVerdict.context,
    executionContextSource: contextVerdict.context
      ? (result?.executionContext ? 'audit-result' : 'audit-event')
      : null,
    executionContextDiagnostic: contextVerdict.context
      ? null
      : (result?.executionContextDiagnostic
        || audit.executionContextDiagnostic
        || contextVerdict.reason),
  };
  if (isOrchestrationPromptAudit(detail)
    && !detail.executionContext
    && toolType === 'codex') {
    // History may reconcile the exact local prompt immediately, but neither a
    // target run nor a completion follow-up may inherit the saved Resume source
    // (or the preceding source turn). Route to orchestration only after the
    // exact task_started supplies the adopted writer/turn.
    routeAgentPromptAuditDetail(detail, { renderer: true, web: false });
    deferCodexPromptAuditExecutionContext(detail);
    return;
  }
  routeAgentPromptAuditDetail(detail);
}

function holdPasteAuditCompletionForTest(toolType, tabId, audit, result, resume) {
  if (!audit || audit.finished === true || result?.success !== true) return false;
  if (audit.e2eCompletionHeld) return true;
  const identity = {
    tabId,
    provider: toolType,
    source: String(audit.source || 'unknown'),
    promptHash: String(result?.expectedHash || audit.expectedHash || 'unknown'),
    promptLength: Number(result?.expectedLen ?? audit.expectedLen ?? 0),
    ...(audit.handoffId ? { handoffId: audit.handoffId } : {}),
    ...(audit.sendAttemptId ? { sendAttemptId: audit.sendAttemptId } : {}),
    ...(audit.sendOperationKey ? { sendOperationKey: audit.sendOperationKey } : {}),
    ...(result?.sessionId ? { sessionId: result.sessionId } : {}),
  };
  const claimed = aiBoundaryTestGate.claim({
    kind: 'agent-post-enter-audit',
    identity,
  });
  if (claimed.claimed !== true) return false;
  if (claimed.action !== 'hold' || !claimed.released) {
    aiBoundaryTestGate.complete({
      armId: claimed.arm.armId,
      operationId: claimed.arm.operationId,
      reason: 'non-hold-audit-boundary-ignored',
      result: { success: true },
    });
    return false;
  }
  audit.e2eCompletionHeld = {
    armId: claimed.arm.armId,
    operationId: claimed.arm.operationId,
  };
  console.warn('[E2E:Boundary] action=hold kind=post-enter-audit'
    + ' provider=' + toolType
    + ' tab=' + String(tabId).slice(-12)
    + ' handoff=' + String(audit.handoffId || '-').slice(0, 24)
    + ' expectedHash=' + String(identity.promptHash).slice(0, 16));
  void claimed.released.then(() => {
    if (audit.finished === true) return;
    audit.e2eCompletionHeld = null;
    resume();
    aiBoundaryTestGate.complete({
      armId: claimed.arm.armId,
      operationId: claimed.arm.operationId,
      reason: 'late-audit-published',
      result: { success: true, late: audit.callerTimedOut === true },
    });
  });
  return true;
}

const claudePromptShapeObserver = createClaudePromptShapeObserver({
  reportIncident: (key, payload) => reportTerminalIncident(key, payload),
  hashText: pasteAuditHash,
});

function observeClaudePromptShapeCandidates(tabId, audits, candidates, details = {}) {
  return claudePromptShapeObserver({ tabId, audits, candidates, ...details,
    getScope: () => ({
      sessionId: bridgeKnownSessions.get(tabId) || null,
      launchGeneration: claudeLaunchGenerationByTab.get(tabId)?.generation || null,
      lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
      runSeq: terminalCommandState.get(tabId)?.runSeq,
      inputRevision: getTerminalInputRevision(tabId),
    }),
  });
}

function finishClaudePasteAudit(tabId, audit, result, e2eBypass = false) {
  if (!audit || audit.finished === true) return;
  if (!e2eBypass && holdPasteAuditCompletionForTest(
    'claude',
    tabId,
    audit,
    result,
    () => finishClaudePasteAudit(tabId, audit, result, true),
  )) return;
  audit.finished = true;
  audit.result = result;
  if (result?.success === true) {
    discardClaudePostEnterForensicArtifact(audit, 'exact-user-turn-confirmed');
  }
  wakeClaudePostEnterResolutionWaiter(audit, 'audit-finished');
  if (audit.timer) clearTimeout(audit.timer);
  audit.timer = null;
  const audits = pendingPasteAudit.get(tabId);
  if (Array.isArray(audits)) {
    const index = audits.indexOf(audit);
    if (index >= 0) audits.splice(index, 1);
    if (audits.length === 0) pendingPasteAudit.delete(tabId);
  }
  releaseClaudePasteAuditTranscriptObserver(tabId, audit, 'finished');
  publishAgentPromptAuditResult(tabId, audit, result, 'claude');
  if (typeof audit.resolve === 'function') {
    audit.resolve(result);
    audit.resolve = null;
  }
  audit.expectedText = '';
}

function settleClaudePasteAuditWithoutProjection(tabId, audit, result, reason) {
  if (!audit || audit.finished === true) return false;
  audit.finished = true;
  audit.result = result;
  wakeClaudePostEnterResolutionWaiter(audit, 'scenario-final:' + reason);
  if (audit.timer) clearTimeout(audit.timer);
  audit.timer = null;
  const audits = pendingPasteAudit.get(tabId);
  if (Array.isArray(audits)) {
    const index = audits.indexOf(audit);
    if (index >= 0) audits.splice(index, 1);
    if (audits.length === 0) pendingPasteAudit.delete(tabId);
  }
  releaseClaudePasteAuditTranscriptObserver(tabId, audit, reason);
  if (typeof audit.resolve === 'function') {
    audit.resolve(result);
    audit.resolve = null;
  }
  audit.expectedText = '';
  audit.presentationSnapshot = null;
  console.warn('[PasteAudit:SCENARIO_FINAL] tab=' + String(tabId).slice(-12)
    + ' handoff=' + (audit.handoffId || '-')
    + ' code=' + (result?.code || result?.error || 'unknown')
    + ' reason=' + reason);
  return true;
}

function confirmClaudePasteAuditFromTranscriptSelection(tabId, audit, selection, reason) {
  if (!selection?.candidate?.record || typeof selection.candidate.text !== 'string') return null;
  try {
    observeClaudePromptShapeCandidates(tabId, [audit], [selection.candidate], {
      selection, source: reason,
    });
  } catch {}
  const actualText = selection.candidate.text;
  const record = selection.candidate.record;
  const actualHash = pasteAuditHash(actualText);
  const canonicalIdentity = claudeAuditCanonicalIdentity(
    audit,
    actualText,
    pasteAuditHash,
  );
  const auditSessionId = record.sessionId
    || record.session_id
    || audit.historySessionId
    || null;
  const auditTimestamp = record.timestamp || new Date(audit.sentAt).toISOString();
  const presentationSaved = saveAuditedPromptPresentation(projectManager?.db, {
    toolType: 'claude',
    sessionId: auditSessionId,
    entryUuid: record.uuid || null,
    auditTimestamp,
    actualText,
    actualHash,
    snapshot: audit.presentationSnapshot,
  });
  const result = {
    success: true,
    actualLen: actualText.length,
    actualHash,
    sessionId: auditSessionId,
    entryUuid: record.uuid || null,
    auditTimestamp,
    ...(Number.isSafeInteger(Number(selection.candidate.byteOffset))
      && Number(selection.candidate.byteOffset) >= 0
      ? { recordByteOffset: Number(selection.candidate.byteOffset) }
      : {}),
    presentationSaved,
    expectedLen: audit.expectedLen,
    expectedHash: audit.expectedHash,
    canonicalized: true,
    canonicalReason: canonicalIdentity.canonicalized === true
      ? canonicalIdentity.canonicalReason
      : reason,
  };
  finishClaudePasteAudit(tabId, audit, result);
  return audit.finished === true && audit.result?.success === true
    ? audit.result
    : null;
}

async function inspectClaudePostEnterTimeoutAtWriteBoundary({
  tabId,
  term,
  audit,
  timeoutResult,
  expectedText,
}) {
  if (audit?.finished === true && audit.result?.success === true) return audit.result;

  // UserPromptSubmit is the authoritative loader/turn edge. While that turn
  // is active, a slow JSONL materialization is still a legitimate confirming
  // state and Ctrl+G must not disturb the TUI.
  if (claudeTurnBusy.get(tabId) === true) {
    const outcome = classifyClaudePostEnterOutcome({ turnBusy: true });
    return {
      ...timeoutResult,
      ...outcome,
      deferUntilClaudeTurnIdle: true,
    };
  }

  const capture = await captureAgentInputAtWriteBoundary(
    tabId,
    'copy',
    'claude',
    { proveExactEmpty: true },
    term,
  );
  if (audit?.finished === true && audit.result?.success === true) return audit.result;

  let transcriptRead = {
    success: false,
    userRecordCount: 0,
    error: 'claude_post_enter_transcript_unresolved',
  };
  const sessionId = bridgeKnownSessions.get(tabId) || audit?.historySessionId || null;
  const transcriptPath = audit?.freshHookTranscriptPath
    || resolveClaudeSessionFileForTab(tabId, sessionId)
    || audit?.preSubmitBoundary?.transcriptPath
    || null;
  if (transcriptPath) {
    try {
      const candidates = await readClaudeUserRecords(
        transcriptPath,
        audit?.preSubmitBoundary || null,
      );
      transcriptRead = {
        success: true,
        userRecordCount: candidates.length,
        transcriptPath,
      };
      const selection = selectClaudePendingPromptAudit([audit], candidates, {
        hashText: pasteAuditHash,
      });
      try {
        observeClaudePromptShapeCandidates(tabId, [audit], candidates, {
          selection, source: 'post-enter-timeout-scan',
        });
      } catch {}
      if (selection) {
        const accepted = confirmClaudePasteAuditFromTranscriptSelection(
          tabId,
          audit,
          selection,
          'post-timeout-exact-transcript-scan',
        );
        if (accepted?.success === true) return accepted;
      }
    } catch (error) {
      transcriptRead = {
        success: false,
        userRecordCount: 0,
        transcriptPath,
        error: error?.message || String(error),
      };
    }
  }

  if (audit?.finished === true && audit.result?.success === true) return audit.result;
  const outcome = classifyClaudePostEnterOutcome({
    expectedText,
    capture,
    transcriptRead,
    acceptedResult: audit?.finished === true ? audit.result : null,
    turnBusy: claudeTurnBusy.get(tabId) === true,
  });
  const retryPlan = planClaudePostEnterRetry({
    pasteReadyProof: audit?.pasteReadyProof || null,
    capture,
    transcriptRead,
    enterRetryCount: audit?.enterRetryCount || 0,
  });
  if (retryPlan.action === 'retry-enter') {
    audit.providerAcceptedText = retryPlan.providerAcceptedText;
    audit.providerAcceptedLen = retryPlan.providerAcceptedText.length;
    audit.providerAcceptedHash = pasteAuditHash(retryPlan.providerAcceptedText);
  }
  let result = {
    ...timeoutResult,
    ...outcome,
    pasteWritten: true,
    enterWritten: true,
    submitted: true,
    expectedLen: audit?.expectedLen,
    expectedHash: audit?.expectedHash,
    composerCapture: {
      success: capture?.success === true,
      proofOutcome: capture?.proofOutcome || null,
      textLength: typeof capture?.text === 'string' ? capture.text.length : null,
      images: Number(capture?.images || 0),
      terminalIdentityStable: capture?.terminalIdentityStable === true,
      editorReturnReady: capture?.editorReturnReady === true,
      error: capture?.error || null,
    },
    retryRecommended: retryPlan.action === 'retry-enter',
    retryReason: retryPlan.reason,
    retryInputRevision: retryPlan.inputRevision ?? null,
  };
  const diagnosticArtifactPath = await persistClaudePostEnterForensicArtifact({
    tabId,
    audit,
    result,
    capture,
    transcriptRead,
  });
  if (audit?.finished === true && audit.result?.success === true) return audit.result;
  if (diagnosticArtifactPath) {
    result = {
      ...result,
      diagnosticArtifactPath,
    };
  }
  if (
    retryPlan.action !== 'retry-enter'
    && outcome.final === true
    && outcome.semanticStatus === 'not-submitted'
  ) {
    const settlementReason = outcome.composerDraftState === 'exact-provider-image-transform'
      ? 'exact-provider-image-transform-remained-without-user-turn'
      : 'exact-original-draft-remained-without-user-turn';
    console.warn('[ClaudePostEnterOutcome] final-not-submitted tab=' + String(tabId).slice(-12)
      + ' state=' + outcome.composerDraftState
      + ' expectedImages=' + (outcome.expectedImagePathCount || 0)
      + ' capturedImages=' + (outcome.capturedImageCount || 0));
    settleClaudePasteAuditWithoutProjection(
      tabId,
      audit,
      result,
      settlementReason,
    );
  }
  return result;
}

function waitForClaudePasteAudit(tabId, audit, timeoutMs = CLAUDE_PASTE_AUDIT_TIMEOUT_MS) {
  if (!audit) {
    return Promise.resolve({ success: false, error: 'claude_audit_missing' });
  }
  if (audit.finished === true) {
    return Promise.resolve(audit.result || {
      success: false,
      error: 'claude_audit_finished_without_result',
    });
  }
  return new Promise((resolve) => {
    audit.resolve = resolve;
    audit.timer = setTimeout(() => {
      audit.timer = null;
      console.warn('[PasteAudit:TIMEOUT] tab=' + String(tabId).slice(-12)
        + ' handoff=' + (audit.handoffId || '-')
        + ' source=' + (audit.source || '-')
        + ' expectedLen=' + audit.expectedLen
        + ' expectedHash=' + audit.expectedHash
        + ' expectedHead=' + JSON.stringify(audit.headPreview)
        + ' expectedTail=' + JSON.stringify(audit.tailPreview)
        + ' waited=' + timeoutMs + 'ms'
        + ' sentAgeMs=' + (Date.now() - audit.sentAt));
      const timeoutResult = {
        success: false,
        error: 'claude_user_message_audit_timeout',
        expectedLen: audit.expectedLen,
        expectedHash: audit.expectedHash,
        lateReconciliationPending: true,
      };
      audit.callerTimedOut = true;
      audit.callerTimedOutAt = Date.now();
      if (typeof audit.resolve === 'function') {
        audit.resolve(timeoutResult);
        audit.resolve = null;
      }
      // Timeout bounds the caller, not the delivery truth. A slow JSONL flush
      // or type-ahead can delay UserPromptSubmit confirmation past this
      // window; the audit stays pending for late reconciliation instead of
      // turning "unconfirmed" into SEND FAILED on a delivered prompt.
    }, timeoutMs);
  });
}

function captureCodexQueuedMessageAuditBaseline(tabId, audit) {
  const mirror = getHeadlessTerminalMirror(tabId);
  const snapshot = mirror?.lastCommittedVisibleSnapshot || null;
  return captureCodexQueuedMessageBaseline(snapshot, audit);
}

function codexProviderQueueAcceptedResult(tabId, audit, proof, durableRecord = null) {
  const watcherSessionId = codexTurnWatchers.get(tabId)?.sessionId || null;
  const sessionId = watcherSessionId
    || audit?.preSubmitBoundary?.sessionId
    || audit?.historySessionId
    || null;
  return {
    success: null,
    accepted: true,
    submitted: true,
    queued: true,
    status: 'queued',
    receiptState: durableRecord?.state || AGENT_SEND_DURABLE_STATES.AUDIT_PENDING,
    providerQueueAccepted: true,
    canonicalPending: true,
    expectedLen: audit?.expectedLen,
    expectedHash: audit?.expectedHash,
    sessionId,
    sourceIdentity: proof.sourceIdentity,
    providerQueueProof: {
      sourceIdentity: proof.sourceIdentity,
      sessionId,
      committedFrameGeneration: proof.committedFrameGeneration,
      writeSeq: proof.writeSeq,
      textHash: proof.textHash,
      matchReason: proof.reason,
    },
  };
}

function publishCodexProviderQueueAccepted(tabId, audit, result) {
  if (!audit?.handoffId || !mainWindow || mainWindow.isDestroyed()) return;
  mainWindow.webContents.send('agent-prompt:audit-result', {
    tabId,
    handoffId: audit.handoffId,
    sendAttemptId: audit.sendAttemptId || null,
    sendOperationKey: audit.sendOperationKey || null,
    toolType: 'codex',
    source: audit.source || null,
    success: null,
    status: 'queued',
    providerQueueAccepted: true,
    sessionId: result.sessionId || null,
    sourceIdentity: result.sourceIdentity,
    providerQueueProof: result.providerQueueProof,
    expectedHash: audit.expectedHash || null,
    expectedLen: Number.isFinite(audit.expectedLen) ? Number(audit.expectedLen) : null,
    queuedAtSubmit: true,
  });
}

function acceptCodexQueuedMessageAudit(tabId, audit, proof) {
  if (!audit || audit.finished === true || audit.providerQueueAcceptedResult) return false;
  if (!audit.sendOperationKey || !audit.sendAttemptId) return false;
  const sessionId = codexTurnWatchers.get(tabId)?.sessionId
    || audit.preSubmitBoundary?.sessionId
    || audit.historySessionId
    || null;
  const queueReceipt = agentSendReceiptStore.markProviderQueueAccepted(
    audit.sendOperationKey,
    audit.sendAttemptId,
    {
      provider: 'codex',
      sessionId,
      sourceIdentity: proof.sourceIdentity,
      acceptedAt: new Date().toISOString(),
      evidence: {
        kind: 'committed-tui-queue-card',
        mirrorGeneration: audit.queueScreenBaseline?.mirrorGeneration || null,
        runSeq: audit.enterRunSeq,
        lifecycleGeneration: audit.enterLifecycleGeneration,
        inputRevision: audit.enterInputRevision,
        committedFrameGeneration: proof.committedFrameGeneration,
        writeSeq: proof.writeSeq,
        textHash: proof.textHash,
        matchReason: proof.reason,
        baselineMatchingCount: proof.baselineMatchingCount,
        matchingCount: proof.matchingCount,
      },
    },
  );
  if (queueReceipt?.ok !== true) {
    console.warn('[CodexPasteAudit:QUEUE_REJECTED] tab=' + String(tabId).slice(-12)
      + ' handoff=' + (audit.handoffId || '-')
      + ' reason=' + (queueReceipt?.reason || 'unknown'));
    return false;
  }
  const result = codexProviderQueueAcceptedResult(
    tabId,
    audit,
    proof,
    queueReceipt.record,
  );
  audit.providerQueueAcceptedResult = result;
  audit.providerQueueAcceptedAt = Date.now();
  if (audit.timer) clearTimeout(audit.timer);
  audit.timer = null;
  if (typeof audit.resolve === 'function') {
    audit.resolve(result);
    audit.resolve = null;
  }
  publishCodexProviderQueueAccepted(tabId, audit, result);
  console.log('[CodexPasteAudit:QUEUE_ACCEPTED] tab=' + String(tabId).slice(-12)
    + ' handoff=' + (audit.handoffId || '-')
    + ' source=' + proof.sourceIdentity
    + ' reason=' + proof.reason
    + ' frame=' + proof.committedFrameGeneration
    + ' matches=' + proof.baselineMatchingCount + '→' + proof.matchingCount);
  return true;
}

function observeCodexQueuedMessageCommittedFrame(tabId, mirror, snapshot) {
  const term = terminals.get(tabId) || null;
  if (!term || mirror !== getHeadlessTerminalMirror(tabId)) return false;
  const audits = getPendingCodexPasteAudits(tabId)
    .filter((audit) => audit?.queuedAtSubmit === true
      && audit?.submitWritten === true
      && audit?.finished !== true
      && !audit?.providerQueueAcceptedResult)
    .sort((left, right) => Number(left.sentAt || 0) - Number(right.sentAt || 0));
  let accepted = false;
  for (const audit of audits) {
    const proof = classifyCodexQueuedMessageFrame({
      baseline: audit.queueScreenBaseline,
      snapshot,
      audit,
      identity: {
        mirrorGeneration: mirror.generation,
        sameTerminal: terminals.get(tabId) === term,
        runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
        lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
        inputRevision: getTerminalInputRevision(tabId),
        writeQueueOwned: !ptyLastQueuedWriteOperation.get(term)
          || ptyLastQueuedWriteOperation.get(term) === audit.writeOperation,
      },
    });
    if (proof.accepted !== true) continue;
    accepted = acceptCodexQueuedMessageAudit(tabId, audit, proof) || accepted;
  }
  return accepted;
}

function finishCodexPasteAudit(tabId, audit, result, e2eBypass = false) {
  if (!audit || audit.finished === true) return;
  if (!e2eBypass && holdPasteAuditCompletionForTest(
    'codex',
    tabId,
    audit,
    result,
    () => finishCodexPasteAudit(tabId, audit, result, true),
  )) return;
  audit.finished = true;
  audit.result = result;
  if (audit.timer) clearTimeout(audit.timer);
  audit.timer = null;
  if (result?.success === true) {
    releaseCodexProvisionalSourceAfterMatchedAudit(tabId, audit, result);
  }
  removePendingCodexPasteAudit(tabId, audit);
  publishAgentPromptAuditResult(tabId, audit, result, 'codex');
  if (typeof audit.resolve === 'function') {
    audit.resolve(result);
    audit.resolve = null;
  }
}

function waitForCodexPasteAudit(tabId, audit, timeoutMs = CODEX_PASTE_AUDIT_TIMEOUT_MS) {
  if (!audit) {
    return Promise.resolve({ success: false, error: 'codex_audit_missing' });
  }
  if (audit.finished === true) {
    return Promise.resolve(audit.result || {
      success: false,
      error: 'codex_audit_finished_without_result',
    });
  }
  if (audit.providerQueueAcceptedResult) {
    return Promise.resolve(audit.providerQueueAcceptedResult);
  }
  return new Promise((resolve) => {
    audit.resolve = resolve;
    audit.timer = setTimeout(() => {
      audit.timer = null;
      console.warn('[CodexPasteAudit:TIMEOUT] tab=' + String(tabId).slice(-12)
        + ' source=' + (audit.source || '-')
        + ' expectedLen=' + audit.expectedLen
        + ' expectedHash=' + audit.expectedHash
        + ' expectedHead=' + JSON.stringify(audit.headPreview)
        + ' expectedTail=' + JSON.stringify(audit.tailPreview)
        + ' waited=' + timeoutMs + 'ms'
        + ' sentAgeMs=' + (Date.now() - audit.sentAt));
      const timeoutResult = {
        success: false,
        error: 'codex_user_message_audit_timeout',
        expectedLen: audit.expectedLen,
        expectedHash: audit.expectedHash,
        lateReconciliationPending: true,
      };
      audit.callerTimedOut = true;
      audit.callerTimedOutAt = Date.now();
      if (typeof audit.resolve === 'function') {
        audit.resolve(timeoutResult);
        audit.resolve = null;
      }
      // A timeout bounds the request, not the delivery truth. Compact/resume
      // can delay the rollout user_message for minutes, so the exact audit
      // remains pending until a causal record appears. No elapsed duration is
      // allowed to turn "unconfirmed" into SEND FAILED.
    }, timeoutMs);
  });
}

function markCodexAuditDeliveryUnknown(tabId, audit, reason, evidence = null, code = 'codex_user_message_audit_timeout') {
  if (!audit?.sendOperationKey || !audit?.sendAttemptId) return null;
  const transition = agentSendReceiptStore.markDeliveryUnknown(
    audit.sendOperationKey,
    audit.sendAttemptId,
    {
      source: 'runtime',
      decision: 'unknown',
      reason,
      code,
      evidence,
    },
  );
  if (transition?.record?.state !== AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN
    && transition?.reason !== 'already-confirmed') {
    console.warn('[AgentSendReceipt] runtime unconfirmed transition rejected tab='
      + String(tabId || '').slice(-12)
      + ' handoff=' + (audit.handoffId || '-')
      + ' reason=' + (transition?.reason || 'unknown'));
  }
  return transition;
}

async function retryCodexEnterAfterAuditTimeout({
  tabId,
  term,
  audit,
  timeoutResult,
  logPrefix,
} = {}) {
  const durableBefore = audit?.sendOperationKey
    ? agentSendReceiptStore.get(audit.sendOperationKey)
    : null;
  const turnBusyBefore = codexTurnWatchers.get(tabId)?.busy === true;
  const admission = classifyCodexPostEnterRetryAdmission({
    timeoutResult,
    audit,
    durableRecord: durableBefore,
    terminalSame: terminals.get(tabId) === term,
    currentRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    currentLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    currentInputRevision: getTerminalInputRevision(tabId),
    turnBusy: turnBusyBefore,
    writeQueueOwned: !ptyLastQueuedWriteOperation.get(term)
      || ptyLastQueuedWriteOperation.get(term) === audit?.writeOperation,
  });
  if (admission.retry !== true) {
    console.warn(logPrefix + ' [CodexEnterRetry] skipped reason=' + admission.reason);
    return admission;
  }

  // One timeout gets one exact, non-destructive Ctrl+G copy. The capture is
  // an app-owned input revision and returns the real composer text even when
  // Codex collapsed a long paste into a chip. It never authorizes a retry from
  // screen similarity alone.
  audit.enterRetryCount = 1;
  const captureInputRevision = getTerminalInputRevision(tabId);
  const capture = await captureAgentInputAtWriteBoundary(
    tabId,
    'copy',
    'codex',
    {},
    term,
  );
  const durableAfter = audit.sendOperationKey
    ? agentSendReceiptStore.get(audit.sendOperationKey)
    : null;
  const captureDecision = classifyCodexPostEnterRetryCapture({
    audit,
    durableRecord: durableAfter,
    capture,
    terminalSame: terminals.get(tabId) === term,
    turnBusy: codexTurnWatchers.get(tabId)?.busy === true,
    currentInputRevision: getTerminalInputRevision(tabId),
    captureInputRevision,
    currentRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    currentLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    writeQueueOwned: !ptyLastQueuedWriteOperation.get(term)
      || ptyLastQueuedWriteOperation.get(term) === audit?.writeOperation,
  });
  if (captureDecision.retry !== true) {
    console.warn(logPrefix + ' [CodexEnterRetry] exact capture refused reason='
      + captureDecision.reason
      + ' capture=' + (capture?.error || capture?.proofReason || '-'));
    return captureDecision;
  }

  recordComposerForensicPtyInput(tabId, '\r', {
    kind: 'programmatic-enter-retry',
    phase: 'pty-write-attempt',
    origin: 'safe-paste',
    source: audit.source || 'codex-post-enter-retry',
    operationKind: 'codex-post-enter-retry',
    handoffId: audit.handoffId,
    sendAttemptId: audit.sendAttemptId,
    sendOperationKey: audit.sendOperationKey,
    checkpoint: true,
  });
  if (!codexSubmitDropTestFault.consume(tabId, term, '\r', audit, 'retry')) term.write('\r');
  audit.enterInputRevision = getTerminalInputRevision(tabId);
  audit.enterRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  audit.enterLifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  audit.retryEnterWrittenAt = Date.now();
  markActivePtySubmit(term, { identityPending: true });
  console.warn(logPrefix + ' [CodexEnterRetry] Enter re-sent after exact owned draft proof'
    + ' reason=' + captureDecision.reason
    + ' handoff=' + (audit.handoffId || '-'));
  return { ...captureDecision, retried: true };
}

// Map of term → tabId for the busy broadcast. Filled lazily from `terminals`
// Map on first paste-busy emit per term.
function findTabIdForTerm(target) {
  for (const [tabId, t] of terminals) {
    if (t === target) return tabId;
  }
  return null;
}

// ============================================================
// Safe Paste + Echo Verification for PTY
// ============================================================
// Problem: macOS TTYHOG = 1024 bytes. Any single term.write() > 1024 bytes
// gets split by the kernel. Ink TUI can't reassemble fragmented bracketed paste.
// Old writeToPtySafe chunked the ENTIRE payload (including escape sequences),
// breaking them across writes.
//
// Solution: Split content into chunks < 900 bytes. Each chunk is a COMPLETE
// bracketed paste (\x1b[200~ + chunk + \x1b[201~), total < 1024 bytes.
// After each chunk, wait for echo in PTY output (event-driven, no fixed timeouts).
// Send \r only after last chunk's echo is confirmed.
// ============================================================

// Wait for Ink render cycle (sync marker \x1b[?2026l = end of synchronized output)
// Used for: Ctrl+C clear, paste chunk confirmation, post-action waits.
// WHY sync marker works for paste: with chunking < 1024 bytes, each paste is delivered
// intact to Ink (no TTYHOG split) → Ink processes it → state update → re-render → sync marker.
// WHY NOT text echo: Ink collapses long pastes into "[Pasted text #N +M lines]",
// so the actual pasted text never appears verbatim in PTY output.
function waitForRender(term, timeoutMs, logPrefix) {
  let baseTime = Date.now(); // Initial subscription time, replaced by markWriteTime()
  let resolved = false;
  let buf = '';
  let staleCount = 0;
  let cleanup, sub, timer;
  let resolveResult;
  const result = new Promise((resolve) => {
    resolveResult = resolve;
    cleanup = () => {
      if (!resolved) {
        resolved = true;
        clearTimeout(timer);
        sub.dispose();
      }
    };
    timer = setTimeout(() => {
      console.log(logPrefix + ' ⏱️ TIMEOUT (' + timeoutMs + 'ms), buf=' + buf.length + 'B, staleSkipped=' + staleCount);
      cleanup();
      resolve({ timedOut: true });
    }, timeoutMs);
    sub = term.onData((data) => {
      if (resolved) return;
      buf += data;
      if (buf.includes('\x1b[?2026l')) {
        const elapsed = Date.now() - baseTime;
        // 3ms threshold: anything that arrives within this window is a marker
        // ALREADY in the kernel buffer from a previous Ink render (Ctrl+S stash,
        // resize, periodic update) — our write hasn't propagated yet. baseTime
        // is reset by markWriteTime() right after term.write(), so a real
        // marker from our paste arriving in 5-20ms passes cleanly.
        const isStale = elapsed < 3;
        if (isStale) {
          staleCount++;
          console.log(logPrefix + ' ⚠️ STALE sync marker at +' + elapsed + 'ms — discarding, waiting for real marker (stale #' + staleCount + ')');
          buf = '';
          return;
        }
        console.log(logPrefix + ' ✅ sync marker at +' + elapsed + 'ms' + (staleCount > 0 ? ' (skipped ' + staleCount + ' stale)' : ''));
        cleanup();
        resolve({ timedOut: false, elapsedMs: elapsed, isStale: false });
      }
    });
  });
  // Caller must call this AFTER term.write() so the stale-threshold is measured
  // from when bytes actually leave us, not from subscription time. Without this,
  // markers that arrive faster than 15ms after subscription (but actually FROM
  // our write) get falsely tagged as stale.
  result.markWriteTime = () => { baseTime = Date.now(); buf = ''; };
  result.cancel = () => {
    if (resolved) return false;
    cleanup();
    resolveResult({ timedOut: false, cancelled: true });
    return true;
  };
  return result;
}

// Helper: drain any pending PTY data (wait for `quietMs` of silence).
//
// `maxWaitMs` (optional) is a HARD CEILING. drainPtyData resolves on whichever
// comes first: `quietMs` of silence, OR `maxWaitMs` total. Without a ceiling
// the "wait for silence" debounce never resolves while the PTY keeps emitting —
// which is exactly what happens during a Claude turn (Ink streams render frames
// continuously). The Replay ▶ button pastes into the input WHILE Claude streams
// (that's its purpose), so an uncapped pre-paste drain blocked for the entire
// turn: prod showed replays hanging 9.7s and 98s, all of it in this drain (the
// paste write + waitForRender after it resolved in <12ms). Pass a ceiling on any
// drain that can run mid-stream. See fix below in safePasteAndSubmit.
function drainPtyData(term, quietMs = 300, maxWaitMs = null) {
  return new Promise((resolve) => {
    let buf = '';
    let quietTimer = null;
    let hardTimer = null;
    const sub = term.onData((data) => {
      buf += data;
      if (quietTimer) clearTimeout(quietTimer);
      quietTimer = setTimeout(finish, quietMs);
    });
    function finish() {
      if (quietTimer) clearTimeout(quietTimer);
      if (hardTimer) clearTimeout(hardTimer);
      try { sub.dispose(); } catch {}
      resolve(buf);
    }
    quietTimer = setTimeout(finish, quietMs);
    if (maxWaitMs != null) hardTimer = setTimeout(finish, maxWaitMs);
  });
}

// Helper: wait for specific text/regex in PTY output (deterministic marker)
function waitForPtyText(term, textOrRegex, timeoutMs = 5000, logPrefix = '') {
  return new Promise((resolve) => {
    let buf = '';
    const stripped = require('node:util').stripVTControlCharacters;
    const timer = setTimeout(() => {
      sub.dispose();
      console.log(logPrefix + ' waitForPtyText TIMEOUT (' + timeoutMs + 'ms) waiting for "' + textOrRegex + '" (got ' + buf.length + 'B)');
      resolve(buf);
    }, timeoutMs);
    const sub = term.onData((data) => {
      buf += data;
      const found = typeof textOrRegex === 'string'
        ? stripped(buf).includes(textOrRegex)
        : textOrRegex.test(buf);
      if (found) {
        clearTimeout(timer);
        sub.dispose();
        resolve(buf);
      }
    });
  });
}

async function requestTerminalVisibleBufferSnapshot(webContents, tabId, reason, timeoutMs = 500) {
  const mirror = getHeadlessTerminalMirror(tabId);
  if (mirror) {
    const flush = await flushHeadlessTerminalMirror(tabId, Math.min(timeoutMs, HEADLESS_XTERM_FLUSH_TIMEOUT_MS));
    if (flush.success) {
      const snapshot = getHeadlessVisibleBufferSnapshot(tabId, reason);
      if (snapshot?.success) return snapshot;
      console.warn('[VisibleSnapshot] headless snapshot failed tab=' + String(tabId).slice(-12)
        + ' reason=' + reason
        + ' error=' + (snapshot?.error || 'unknown')
        + ' — falling back to renderer');
    } else {
      console.warn('[VisibleSnapshot] headless flush failed tab=' + String(tabId).slice(-12)
        + ' reason=' + reason
        + ' error=' + (flush?.error || 'unknown')
        + ' writeSeq=' + (flush?.writeSeq ?? '-')
        + ' flushedSeq=' + (flush?.flushedSeq ?? '-')
        + ' — falling back to renderer');
    }
  }

  return new Promise((resolve) => {
    if (!webContents || (typeof webContents.isDestroyed === 'function' && webContents.isDestroyed())) {
      resolve({ success: false, error: 'no-webcontents', tabId, reason, source: 'renderer' });
      return;
    }

    const requestId = crypto.randomUUID();
    let settled = false;
    const finish = (payload) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      ipcMain.removeListener('terminal:visible-buffer-response', handler);
      resolve({ ...(payload || { success: false, error: 'empty-response' }), requestId, tabId, reason, source: 'renderer' });
    };
    const handler = (_event, payload) => {
      if (!payload || payload.requestId !== requestId) return;
      finish(payload);
    };
    const timer = setTimeout(() => {
      finish({ success: false, error: 'timeout', requestId, tabId, reason });
    }, timeoutMs);

    ipcMain.on('terminal:visible-buffer-response', handler);
    try {
      webContents.send('terminal:visible-buffer-request', { requestId, tabId, reason });
    } catch (err) {
      finish({ success: false, error: err?.message || String(err), requestId, tabId, reason });
    }
  });
}

async function requestTerminalCodexDraftState(webContents, tabId, reason, timeoutMs = 700, options = {}) {
  let headlessState = null;
  const mergeRendererPositive = options.mergeRendererPositive === true;
  const headless = getHeadlessTerminalMirror(tabId);
  if (headless) {
    const expected = typeof options.waitFor === 'boolean' ? options.waitFor : null;
    const waitTimeoutMs = Math.max(100, Math.min(Number(options.waitTimeoutMs) || timeoutMs || 900, 2500));
    const flush = await flushHeadlessTerminalMirror(tabId, Math.min(timeoutMs, HEADLESS_XTERM_FLUSH_TIMEOUT_MS));
    if (flush.success) {
      headlessState = expected === null
        ? getHeadlessCodexDraftState(tabId, reason)
        : await waitForHeadlessCodexDraftState(
          tabId,
          expected,
          waitTimeoutMs,
          reason,
          { waitOnUnknownOnly: options.waitOnUnknownOnly === true },
        );
      if (hasDefinitiveDraftState(headlessState)) {
        const rendererAvailable = !!webContents
          && !(typeof webContents.isDestroyed === 'function' && webContents.isDestroyed());
        if (
          headlessState.hasDraft === true
          || mergeRendererPositive !== true
          || !rendererAvailable
        ) {
          return { requestId: null, tabId, reason, ...headlessState };
        }
        console.log('[CodexDraftState] headless empty, probing fresh renderer-positive tab='
          + String(tabId).slice(-12)
          + ' reason=' + reason
          + ' source=' + (headlessState.source || '-'));
      } else if (headlessState?.success && (headlessState.hasDraft !== null || expected === null)) {
        console.warn('[CodexDraftState] headless unknown tab=' + String(tabId).slice(-12)
          + ' reason=' + reason
          + ' source=' + (headlessState.source || '-')
          + ' — falling back to renderer');
      } else if (headlessState?.success && expected !== null && headlessState.hasDraft !== expected) {
        console.warn('[CodexDraftState] headless wait unresolved tab=' + String(tabId).slice(-12)
          + ' reason=' + reason
          + ' expected=' + expected
          + ' actual=' + headlessState.hasDraft
          + ' timedOut=' + !!headlessState.timedOut
          + ' — falling back to renderer');
      }
    } else {
      console.warn('[CodexDraftState] headless flush failed tab=' + String(tabId).slice(-12)
        + ' reason=' + reason
        + ' error=' + (flush?.error || 'unknown')
        + ' writeSeq=' + (flush?.writeSeq ?? '-')
        + ' flushedSeq=' + (flush?.flushedSeq ?? '-')
        + ' — falling back to renderer');
    }
  }

  const rendererState = await new Promise((resolve) => {
    if (!webContents || (typeof webContents.isDestroyed === 'function' && webContents.isDestroyed())) {
      resolve({ success: false, error: 'no-webcontents', tabId, reason, source: 'renderer' });
      return;
    }

    const requestId = crypto.randomUUID();
    let settled = false;
    const finish = (payload) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      ipcMain.removeListener('terminal:codex-draft-state-response', handler);
      resolve({ ...(payload || { success: false, error: 'empty-response' }), requestId, tabId, reason, source: payload?.source || 'renderer' });
    };
    const handler = (_event, payload) => {
      if (!payload || payload.requestId !== requestId) return;
      finish(payload);
    };
    const timer = setTimeout(() => {
      finish({ success: false, error: 'timeout', requestId, tabId, reason });
    }, timeoutMs);

    ipcMain.on('terminal:codex-draft-state-response', handler);
    try {
      webContents.send('terminal:codex-draft-state-request', {
        requestId,
        tabId,
        reason,
        waitFor: typeof options.waitFor === 'boolean' ? options.waitFor : undefined,
        waitOnUnknownOnly: options.waitOnUnknownOnly === true,
        timeoutMs: Number(options.waitTimeoutMs) || undefined,
      });
    } catch (err) {
      finish({ success: false, error: err?.message || String(err), requestId, tabId, reason });
    }
  });
  // The renderer request is asynchronous. Catch up the authoritative mirror
  // once more before comparing frame identities; request time alone cannot
  // make a hidden renderer's old picker snapshot current.
  if (headless) {
    if (getHeadlessTerminalMirror(tabId) !== headless) {
      return { success: false, hasDraft: null, preview: '', tabId, reason,
        source: 'headless-main:mirror-replaced-during-probe' };
    }
    const refreshed = await flushHeadlessTerminalMirror(tabId, Math.min(timeoutMs, HEADLESS_XTERM_FLUSH_TIMEOUT_MS));
    if (getHeadlessTerminalMirror(tabId) !== headless) {
      return { success: false, hasDraft: null, preview: '', tabId, reason,
        source: 'headless-main:mirror-replaced-during-probe' };
    }
    headlessState = refreshed.success
      ? getHeadlessCodexDraftState(tabId, reason + ':after-renderer')
      : { success: false, hasDraft: null, preview: '', tabId, reason,
        source: 'headless-main:post-renderer-flush-failed', error: refreshed.error };
  }
  const normalizedHeadlessState = headlessState
    ? { requestId: null, tabId, reason, ...headlessState }
    : null;
  const result = mergeCodexDraftAuthority(normalizedHeadlessState, rendererState, {
    mergeRendererPositive,
  });
  if (normalizedHeadlessState?.success === true && normalizedHeadlessState.hasDraft === false
    && rendererState?.success === true && rendererState.hasDraft === true) {
    void reportTerminalIncident('draft:' + tabId + ':' + JSON.stringify(rendererState.frameIdentity)
      + ':' + String(rendererState.preview), {
      tabId, toolType: 'codex', incidentReason: 'draft-screen-contradiction',
      context: { reason, mainProof: normalizedHeadlessState, rendererProof: rendererState,
        decision: result.rendererPositiveIgnored || 'renderer-positive-protected' },
      rendererSnapshot: rendererState.diagnosticSnapshot,
    });
  }
  if (result.rendererPositiveIgnored) {
    console.log('[CodexDraftState] renderer positive ignored tab=' + String(tabId).slice(-12)
      + ' reason=' + result.rendererPositiveIgnored
      + ' mainFrame=' + JSON.stringify(normalizedHeadlessState?.frameIdentity || null)
      + ' rendererFrame=' + JSON.stringify(rendererState?.frameIdentity || null)
      + ' rendererSource=' + String(rendererState?.source || 'unknown'));
  }
  return result;
}

// Stash-detect helper. Claude TUI's chat:stash binding is bi-directional:
//   - input has text + no existing stash  → Ctrl+S pushes input to stash, clears input
//   - input is empty + existing stash     → Ctrl+S pops stash BACK INTO the input
//   - input has text + existing stash     → Ctrl+S OVERWRITES stash with new text,
//                                           dropping what the user had saved
// We render "› Stashed (auto-restores after submit)" under the input whenever a
// stash exists. Detect that line in the recent PTY output and skip our own
// Ctrl+S — sending it would corrupt the user's already-saved draft (cases 2 + 3
// above). Caller still wants the rest of safePasteAndSubmit (paste + submit) to
// run normally — the existing stash will auto-restore after our slash-cmd
// submits, which is exactly the same outcome as the happy path.
//
// Three known gotchas with the matching strategy (see fact-claude-tui-control.md
// "Ink TUI: пробелы как ANSI-команды, текст разорван по чанкам"):
//   1. Ink emits spaces inside its bottom status row as `\x1b[<N>C` (cursor-
//      forward), so after stripVTControlCharacters the literal becomes
//      "Stashed(auto-restoresaftersubmit)" without spaces.
//   2. PTY data arrives in 3-5 chunks for a single Ink re-render; split('\n')
//      can land the marker across two ring-buffer entries.
//   3. Long assistant streams push the marker out of any small tail window;
//      the marker doesn't get re-rendered until input-box refreshes.
// Mitigations: join the entire ring buffer (capped at 500 lines = bounded
// work), strip ONCE on the joined string, then match a tolerant regex that
// accepts zero-or-more whitespace between tokens. The marker is unique enough
// in PTY output that false positives are not a realistic concern.
const STASH_MARKER_RE = /Stashed\s*\(\s*auto-restores\s*after\s*submit\s*\)/;
function hasStashedMarker(tabId) {
  if (!tabId) return false;
  const buf = terminalOutputBuffer.get(tabId);
  if (!buf || !buf.lines || buf.lines.length === 0) return false;
  const joined = buf.lines.join('\n');
  const stripped = stripVTControlCharacters(joined);
  return STASH_MARKER_RE.test(stripped);
}

async function validatePromptQueueImageMarkers(text) {
  const input = String(text || '');
  const paths = [];
  input.replace(/\[imagePath:\s*([^\]\r\n]+?)\s*\]/gi, (_match, rawPath) => {
    const imagePath = String(rawPath || '').trim();
    if (isPortableImagePath(imagePath)) paths.push(imagePath);
    return _match;
  });
  const missing = [];
  for (const imagePath of paths) {
    const stat = await fs.promises.stat(imagePath).catch(() => null);
    if (!stat?.isFile()) missing.push({ path: imagePath, error: 'image_path_missing' });
  }
  return { success: missing.length === 0, paths, missing };
}

function claudePasteAttemptIdentityCurrent(tabId, term, attempt) {
  const mirror = getHeadlessTerminalMirror(tabId);
  return !!attempt
    && terminals.get(tabId) === term
    && mirror === attempt.mirrorToken
    && mirror?.generation === attempt.mirrorGeneration
    && Number(terminalCommandState.get(tabId)?.runSeq || 0) === attempt.terminalRunSeq
    && getTerminalLifecycleGeneration(tabId) === attempt.terminalLifecycleGeneration
    && getTerminalInputRevision(tabId) === attempt.inputRevision
    && aiStoppingTabs.get(tabId)?.toolType !== 'claude';
}

async function waitForClaudePasteReadyBeforeSubmit({
  tabId,
  term,
  attempt,
  timeoutMs = 8000,
  cancellationRequested = null,
} = {}) {
  if (!tabId || !term || !attempt?.mirrorToken) {
    return { success: false, ready: false, error: 'claude_paste_ready_identity_missing' };
  }
  const mirror = attempt.mirrorToken;
  return await new Promise((resolve) => {
    let settled = false;
    let timer = null;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      mirror.synchronizedFrameWaiters?.delete(check);
      resolve(value);
    };
    const check = () => {
      if (settled) return;
      if (typeof cancellationRequested === 'function' && cancellationRequested()) {
        finish({ success: false, ready: false, error: 'agent_send_cancelled' });
        return;
      }
      const identityCurrent = claudePasteAttemptIdentityCurrent(tabId, term, attempt);
      const currentMirror = getHeadlessTerminalMirror(tabId);
      const snapshot = currentMirror?.lastCommittedVisibleSnapshot || null;
      const decision = classifyClaudePasteReadyFrame({
        snapshot,
        baselineCommittedFrameGeneration: attempt.baselineCommittedFrameGeneration,
        identityCurrent,
        expectedHasText: attempt.expectedHasText,
        expectedImageCount: attempt.expectedImageCount,
      });
      attempt.lastDecision = decision;
      if (decision.action === 'cancel') {
        finish({
          success: false,
          ready: false,
          error: 'claude_input_ownership_changed_after_paste',
          reason: decision.reason,
        });
        return;
      }
      if (decision.action !== 'ready') return;
      finish({
        success: true,
        ready: true,
        proof: {
          ready: true,
          reason: decision.reason,
          form: decision.form,
          committedFrameGeneration: decision.committedFrameGeneration,
          // Retry/capture checks must preserve the native image slots actually
          // observed, not demand a UI attachment to become a native chip.
          expectedImageCount: decision.observedImageCount,
          imageReferenceCount: attempt.expectedImageCount,
          observedImageCount: decision.observedImageCount,
          expectedHasText: attempt.expectedHasText,
          terminalRunSeq: attempt.terminalRunSeq,
          inputRevision: attempt.inputRevision,
          terminalLifecycleGeneration: attempt.terminalLifecycleGeneration,
          mirrorGeneration: attempt.mirrorGeneration,
        },
      });
    };
    mirror.synchronizedFrameWaiters?.add(check);
    timer = setTimeout(() => {
      finish({
        success: false,
        ready: false,
        error: 'claude_paste_not_ready_before_submit',
        reason: attempt.lastDecision?.reason || 'timeout',
      });
    }, Math.max(250, Number(timeoutMs) || 8000));
    queueMicrotask(check);
  });
}

// Main helper: chunked paste + sync marker verification + optional submit.
// Wraps the actual work in a per-term promise chain so two concurrent callers
// can't interleave bytes on the same PTY. See pasteInflight comment above.
async function safePasteAndSubmit(term, content, options = {}) {
  if (!term || typeof term.write !== 'function') {
    const logPrefix = options.logPrefix || '[safePaste]';
    console.log(logPrefix + ' ❌ Terminal not available');
    return { success: false, error: 'terminal not available' };
  }
  const operation = {
    kind: 'safe-paste',
    source: options.source || null,
    submitted: false,
    identityPending: false,
    queuedAt: Date.now(),
  };
  const operationTabId = findTabIdForTerm(term);
  const requestedInputRevision = operationTabId
    ? getTerminalInputRevision(operationTabId)
    : null;
  let result = await withPtyWriteLock(
    term,
    () => {
      let expectedInputRevision = requestedInputRevision;
      let claudeExactEmptyEvidence = options.claudeExactEmptyEvidence || null;
      if (operationTabId) {
        if (options.inputRevisionAlreadyReserved === true) {
          if (getTerminalInputRevision(operationTabId) !== requestedInputRevision) {
            return {
              success: false,
              submitted: false,
              error: 'terminal_input_ownership_changed_before_write',
              manualTakeover: true,
            };
          }
        } else {
          const inputRevisionBeforeReservation = getTerminalInputRevision(operationTabId);
          expectedInputRevision = bumpTerminalInputRevision(operationTabId);
          claudeExactEmptyEvidence = reserveClaudeExactEmptyEvidence({
            evidence: claudeExactEmptyEvidence,
            currentInputRevision: inputRevisionBeforeReservation,
            reservedInputRevision: expectedInputRevision,
            currentRunSeq: Number(terminalCommandState.get(operationTabId)?.runSeq || 0),
            currentLifecycleGeneration: getTerminalLifecycleGeneration(operationTabId),
            currentMirrorGeneration: getHeadlessTerminalMirror(operationTabId)?.generation || null,
          });
          operation.inputRevisionBeforeReservation = inputRevisionBeforeReservation;
          operation.inputRevision = expectedInputRevision;
        }
      }
      operation.claudeExactEmptyEvidence = claudeExactEmptyEvidence
        || options.startupExactEmptyEvidence
        || null;
      return _safePasteAndSubmitInner(term, content, {
        ...options,
        expectedInputRevision,
        claudeExactEmptyEvidence,
        sendOperationContext: operation,
      });
    },
    operation,
    options.ptyWriteOwner || null,
  );
  if (options.deferPostWriteResolution === true) {
    return { submitted: result?.submitted, enterWritten: operation.submitted === true,
      finishAfterPtyWrite: () => finishSafePasteAfterWrite(term, content, options, operation, result) };
  }
  return finishSafePasteAfterWrite(term, content, options, operation, result);
}

async function finishSafePasteAfterWrite(term, content, options, operation, result) {
  if (result?.__codexPostEnterDeferred) {
    result = await finishCodexPasteAuditAfterWrite(term, result.__codexPostEnterDeferred, true);
  }
  const deferredPostEnter = result?.__claudePostEnterDeferred || null;
  if (deferredPostEnter) {
    const {
      __claudePostEnterDeferred: _privateDeferred,
      deferUntilClaudeTurnIdle: _privateDeferFlag,
      ...baseResult
    } = result;
    await waitForClaudeAuditOrTurnIdle(
      deferredPostEnter.tabId,
      deferredPostEnter.audit,
    );
    let resolvedAudit = deferredPostEnter.audit?.finished === true
      && deferredPostEnter.audit?.result?.success === true
      ? deferredPostEnter.audit.result
      : null;
    if (!resolvedAudit) {
      const postEnterOperation = {
        kind: 'claude-post-enter-inspection',
        source: options.source || null,
        submitted: true,
        identityPending: true,
        manualInputYields: true,
        queuedAt: Date.now(),
      };
      resolvedAudit = await withPtyWriteLock(
        term,
        () => inspectClaudePostEnterTimeoutAtWriteBoundary({
          tabId: deferredPostEnter.tabId,
          term,
          audit: deferredPostEnter.audit,
          timeoutResult: deferredPostEnter.timeoutResult,
          expectedText: deferredPostEnter.expectedText,
        }),
        postEnterOperation,
      );
    }
    const {
      deferUntilClaudeTurnIdle: _secondDeferFlag,
      ...publicAudit
    } = resolvedAudit || {};
    if (publicAudit.success === true) {
      const { error: _timeoutError, semanticStatus: _timeoutSemantic, ...acceptedBase } = baseResult;
      result = {
        ...acceptedBase,
        success: true,
        submitted: true,
        pasteWritten: true,
        enterWritten: true,
        pasteAudit: publicAudit,
      };
    } else {
      result = {
        ...baseResult,
        ...publicAudit,
        success: false,
        error: publicAudit.error || baseResult.error || 'claude_user_message_audit_failed',
        submitted: true,
        pasteWritten: true,
        enterWritten: true,
        pasteAudit: publicAudit,
      };
    }
  }
  if (result && typeof result === 'object' && operation.sendOperationKey) {
    return {
      ...result,
      operationKey: result.operationKey || operation.sendOperationKey,
      sendOperationKey: result.sendOperationKey || operation.sendOperationKey,
      attemptId: result.attemptId || operation.sendAttemptId || null,
      sendAttemptId: result.sendAttemptId || operation.sendAttemptId || null,
    };
  }
  return result;
}

async function finishCodexPasteAuditAfterWrite(term, {
  tabId, audit, timeoutMs, logPrefix, startedAt, baseResult,
}, serializedRetry = false) {
  console.log(logPrefix + ' [+' + (Date.now() - startedAt)
    + 'ms] [CodexPasteAudit] waiting for rollout user_message timeout=' + timeoutMs
    + 'ms hash=' + audit.expectedHash);
  let auditResult = await waitForCodexPasteAudit(tabId, audit, timeoutMs);
  if (auditResult?.error === 'codex_user_message_audit_timeout') {
    const retryAtOwner = () => retryCodexEnterAfterAuditTimeout({
      tabId, term, audit, timeoutResult: auditResult, logPrefix,
    });
    // The initial settings+prompt transaction has released both queues. A
    // bounded exact-draft retry is a new input transaction, never a read-only
    // audit callback writing outside the common PTY serializer. The original
    // audit/input generation still guards it against intervening writers.
    const retry = serializedRetry
      ? await withPtyWriteLock(term, retryAtOwner, audit.writeOperation)
      : await retryAtOwner();
    if (retry?.retried === true) {
      console.log(logPrefix + ' [CodexPasteAudit] waiting after exact Enter retry timeout='
        + timeoutMs + 'ms hash=' + audit.expectedHash);
      auditResult = await waitForCodexPasteAudit(tabId, audit, timeoutMs);
    }
  }
  // Exact delivery or native queue evidence may have arrived while the
  // timeout recovery inspected the composer. Reuse that same attempt proof;
  // never overwrite it with the older timeout result.
  if (audit.finished === true && audit.result) auditResult = audit.result;
  else if (audit.providerQueueAcceptedResult) auditResult = audit.providerQueueAcceptedResult;

  if (auditResult?.error === 'codex_user_message_audit_timeout') {
    const commandState = terminalCommandState.get(tabId);
    const scopeFailure = terminals.get(tabId) !== term
      ? 'terminal-replaced-before-confirmation'
      : audit.enterRunSeq != null && Number(commandState?.runSeq) !== Number(audit.enterRunSeq)
        ? 'terminal-run-changed-before-confirmation'
        : audit.enterLifecycleGeneration
          && getTerminalLifecycleGeneration(tabId) !== audit.enterLifecycleGeneration
          ? 'terminal-lifecycle-changed-before-confirmation'
          : commandState?.isRunning === false
            ? 'process-exited-before-confirmation'
            : null;
    if (scopeFailure) {
      // Losing the process that accepted Enter is evidence, unlike the caller
      // deadline alone. Keep the old unresolved-operation recovery contract.
      markCodexAuditDeliveryUnknown(tabId, audit, scopeFailure, null, 'codex_confirmation_scope_lost');
      return {
        ...baseResult, success: null, accepted: true, submitted: true,
        pasteWritten: true, enterWritten: true,
        status: 'delivery-unknown', receiptState: AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN,
        deliveryUnknown: true, auditPending: false,
        code: 'codex_confirmation_scope_lost', pendingReason: scopeFailure, codexAudit: auditResult,
      };
    }
    // This deadline only releases the caller. The written attempt still has
    // its live transcript observer, so elapsed time is pending confirmation,
    // not evidence that delivery became unknown or failed.
    const pendingResult = {
      ...baseResult,
      success: null,
      accepted: true,
      submitted: true,
      pasteWritten: true,
      enterWritten: true,
      status: 'audit-pending',
      receiptState: AGENT_SEND_DURABLE_STATES.AUDIT_PENDING,
      auditPending: true,
      deliveryUnknown: false,
      exactAuditConfirmed: false,
      userMessageAuditPending: true,
      code: 'codex_user_message_audit_pending',
      pendingReason: 'codex_user_message_audit_timeout',
      codexAudit: auditResult,
    };
    if (audit.sendOperationKey && audit.sendAttemptId) {
      const settled = agentSendReceiptStore.settleAttempt(
        audit.sendOperationKey, audit.sendAttemptId, pendingResult,
      );
      const record = settled.record;
      if (record?.attemptId === audit.sendAttemptId) {
        if (record.state === AGENT_SEND_DURABLE_STATES.AUDIT_PENDING) {
          reportTerminalSendDiagnostic(record, 'send-confirmation-delayed');
        } else if (record.state === AGENT_SEND_DURABLE_STATES.CONFIRMED
          || record.state === AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN) {
          return desktopHistorySendReplayResult(record);
        }
      }
    }
    console.log(logPrefix + ' [CodexPasteAudit] confirmation still pending after caller deadline'
      + ' handoff=' + (audit.handoffId || '-'));
    return pendingResult;
  }
  const providerQueueAccepted = auditResult?.providerQueueAccepted === true
    && auditResult?.status === 'queued';
  if ((!auditResult || auditResult.success !== true) && !providerQueueAccepted) {
    console.error(logPrefix + ' [+' + (Date.now() - startedAt)
      + 'ms] [CodexPasteAudit] failed error=' + (auditResult?.error || 'unknown') + ' submitted=true');
    return {
      ...baseResult,
      success: false,
      error: auditResult?.error || 'codex_user_message_audit_failed',
      submitted: true, pasteWritten: true, enterWritten: true, codexAudit: auditResult || null,
    };
  }
  if (providerQueueAccepted) {
    console.log(logPrefix + ' [+' + (Date.now() - startedAt)
      + 'ms] [CodexPasteAudit] provider queue accepted source=' + (auditResult.sourceIdentity || '-'));
  } else {
    console.log(logPrefix + ' [+' + (Date.now() - startedAt)
      + 'ms] [CodexPasteAudit] confirmed user_message len='
      + auditResult.actualLen + ' hash=' + auditResult.actualHash);
  }
  return {
    ...baseResult,
    success: true,
    ...(providerQueueAccepted ? {
      accepted: true, queued: true, status: 'queued',
      receiptState: AGENT_SEND_DURABLE_STATES.AUDIT_PENDING,
      providerQueueAccepted: true, canonicalPending: true, auditPending: true,
      providerQueueProof: auditResult.providerQueueProof,
    } : {}),
    codexAudit: auditResult,
  };
}

function currentCodexAcceptedResumeSourceProof(tabId, writer, retained = null) {
  if (!writer?.launchId || writer.terminalToken !== terminals.get(tabId)
    || writer.runSeq !== Number(terminalCommandState.get(tabId)?.runSeq || 0)
    || writer.lifecycleGeneration !== getTerminalLifecycleGeneration(tabId)) return null;
  const activeLaunch = codexLastRunCommandPayload.get(tabId)
    || getCodexResumeReadIdentityLeaseForTab(tabId);
  const launch = activeLaunch || retained || writer.acceptedResumeSource;
  const currentLaunch = launch?.command === 'codex-c'
    && launch.materializedFresh !== true
    && launch.terminalToken === writer.terminalToken
    && launch.runSeq === writer.runSeq
    && launch.lifecycleGeneration === writer.lifecycleGeneration
    && launch.launchId === writer.launchId
    && launch.sessionId
    && (!activeLaunch || writer.sourceSessionId === launch.sessionId);
  return currentLaunch ? {
    command: 'codex-c', materializedFresh: false, sessionId: launch.sessionId,
    terminalToken: launch.terminalToken, runSeq: launch.runSeq,
    lifecycleGeneration: launch.lifecycleGeneration, launchId: launch.launchId,
  } : null;
}

function readAgentSendDestinationAtWriteBoundary(tabId, toolType, observedSessionId = null) {
  const terminal = terminals.get(tabId) || null;
  const lifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const terminalInstanceId = terminal ? terminalLifecycleEpochs.get(terminal) || null : null;
  if (toolType === 'codex') {
    const writer = getCodexWriterProofSnapshot(tabId);
    const acceptedResume = currentCodexAcceptedResumeSourceProof(tabId, writer);
    const writerOwnsRuntime = writer?.terminalToken === terminal
      && Number(writer?.runSeq) === Number(terminalCommandState.get(tabId)?.runSeq || 0)
      && writer?.lifecycleGeneration === lifecycleGeneration;
    const pendingLaunch = codexLastRunCommandPayload.get(tabId) || getCodexResumeReadIdentityLeaseForTab(tabId);
    const launchId = writerOwnsRuntime ? writer?.launchId || null
      : pendingLaunch?.terminalToken === terminal ? pendingLaunch?.launchId || null : null;
    return {
      toolType,
      terminalInstanceId,
      launchId,
      sessionId: writer?.sessionId || observedSessionId,
      acceptedResumeSourceSessionId: acceptedResume?.sessionId || null,
      lifecycleGeneration,
      turnId: codexTurnWatchers.get(tabId)?.currentTurnId || codexTurnWatchers.get(tabId)?.lastOutcomeTurnId || null,
    };
  }
  const sessionId = bridgeKnownSessions.get(tabId) || observedSessionId;
  const launch = claudeLaunchGenerationByTab.get(tabId);
  const firstBridge = launch?.firstAcceptedBridge;
  const currentResume = toolType === 'claude' && sessionId
    && launch?.launchMode === 'resume' && launch.generation
    && launch.pid && launch.pid === findClaudePidByTab(tabId)
    && bridgeKnownSessions.get(tabId) === sessionId
    && firstBridge?.sessionId === sessionId
    && firstBridge.pid === launch.pid && firstBridge.generation === launch.generation
    && firstBridge.terminalToken === terminals.get(tabId)
    && firstBridge.runSeq === Number(terminalCommandState.get(tabId)?.runSeq || 0)
    && firstBridge.lifecycleGeneration === getTerminalLifecycleGeneration(tabId);
  return {
    toolType, sessionId,
    terminalInstanceId,
    launchId: launch?.generation || null,
    acceptedResumeSourceSessionId: currentResume ? launch.sessionIdHint : null,
    lifecycleGeneration,
  };
}

function agentSendRequestExpectedTargets(request = {}) {
  const record = request.sendOperationKey && request.sendAttemptId
    ? agentSendReceiptStore?.get(request.sendOperationKey) : null;
  return [record?.attemptId === request.sendAttemptId ? record?.receipt?.expectedTarget : null,
    request.expectedTarget].filter(target => target && typeof target === 'object' && !Array.isArray(target));
}

function agentSendRequestTargetFailure(tabId, toolType, request = {}, observedSessionId = null, {
  allowUnresolved = false,
} = {}) {
  const targets = agentSendRequestExpectedTargets(request);
  if (!targets.length) return null;
  const actual = readAgentSendDestinationAtWriteBoundary(tabId, toolType, observedSessionId);
  for (const target of targets) {
    const expected = allowUnresolved && !actual.sessionId ? { ...target, sessionId: null } : target;
    const failure = agentSendTargetPreconditionFailure(expected, actual);
    if (failure) return failure;
  }
  return null;
}

function captureClaudeDraftPasteTarget(tabId) {
  const state = terminalCommandState.get(tabId) || null;
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const execution = getActiveAgentExecutionContext(tabId);
  const pids = [...new Set([
    findClaudePidByTab(tabId), launch?.pid,
    execution?.provider === 'claude' ? execution.processId : null,
  ].map(Number).filter(pid => Number.isSafeInteger(pid) && pid > 0))];
  return {
    tabId, terminal: terminals.get(tabId) || null,
    runSeq: Number(state?.runSeq || 0),
    lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    launchGeneration: launch?.generation || null,
    processId: pids[0] || null, processIdentityConflict: pids.length > 1,
    processRunning: state?.isRunning === true, stopping: aiStoppingTabs.has(tabId),
    inputRevision: getTerminalInputRevision(tabId),
  };
}

function validateClaudeDraftPasteAtBoundary(token, term, expectedInputRevision = null) {
  if (!token || token.terminal !== term) return { valid: false, reason: 'claude_draft_paste_admission_missing' };
  const current = captureClaudeDraftPasteTarget(token.tabId);
  let processAlive = false;
  if (Number.isSafeInteger(token.processId) && token.processId > 0) {
    try { process.kill(token.processId, 0); processAlive = true; } catch {}
  }
  return validateClaudeDraftPasteAdmission(token, current, { processAlive, expectedInputRevision });
}

async function _safePasteAndSubmitInner(term, content, options = {}) {
  const {
    submit = true,
    ctrlCFirst = false,
    stashFirst = false, // Send Ctrl+S to stash current user input (Claude restores after slash-cmd submit)
    dismissAutocomplete = false, // Send Esc after paste to close slash-cmd autocomplete dropdown
    logPrefix = '[safePaste]',
    handoffId = null,
    sendAttemptId: requestedSendAttemptId = null,
    sendOperationKey: requestedSendOperationKey = null,
    expectedTarget = null,
    source = null,
    safetyTimeoutMs = 8000,
    fast = false, // Turbo mode for Gemini/Bash (skip render waits)
    submitSequence = '\r',
    submitLabel = null,
    armPromptBoundaryOnSubmit = false,
    promptBoundaryReason = null,
    skipRenderWait = false,
    awaitClaudeUserMessageAudit = false,
    claudeAuditTimeoutMs = CLAUDE_PASTE_AUDIT_TIMEOUT_MS,
    awaitCodexUserMessageAudit: requestedCodexUserMessageAudit = false,
    codexAuditTimeoutMs = CODEX_PASTE_AUDIT_TIMEOUT_MS,
    verifyCodexVisibleDraftBeforeSubmit = false,
    verifyClaudeVisibleDraftBeforePaste = false,
    requireFreshClaudeExactEmptyBeforePaste = false,
    codexSubmissionPreflight = true,
    requestReceivedAt = null,
    expectedInputRevision = null,
    presentationSnapshot = null,
    startupPromptLease = null,
    claudeDraftPasteAdmission = null,
    startupExactEmptyEvidence = null,
    claudeExactEmptyEvidence = null,
    queuedAtSubmit = false,
    promptQueueAction = null,
    sendOperationContext = null,
  } = options;
  let sendAttemptId = requestedSendAttemptId;
  let sendOperationKey = requestedSendOperationKey;
  const durableRawPrompt = content;
  const destinationRecord = sendOperationKey && sendAttemptId
    ? agentSendReceiptStore.get(sendOperationKey) : null;
  const expectedDestination = (destinationRecord?.attemptId === sendAttemptId
    ? destinationRecord.receipt?.expectedTarget || null : null) || expectedTarget;

  // TTYHOG on macOS = 1024 bytes. Paste brackets = 12 bytes. Leave margin.
  // Only used in fast-mode (Gemini/bash) where Ink isn't involved and we don't
  // need per-chunk render confirmation. Slow-mode (Claude) writes the whole
  // payload as a single bracket pair — see "Single-write strategy" below.
  const CHUNK_MAX = 900;
  const splitUtf8Chunks = (text, maxBytes) => {
    const chunks = [];
    let current = '';
    let currentBytes = 0;
    for (const char of String(text || '')) {
      const charBytes = Buffer.byteLength(char, 'utf8');
      if (current && currentBytes + charBytes > maxBytes) {
        chunks.push(current);
        current = '';
        currentBytes = 0;
      }
      current += char;
      currentBytes += charBytes;
    }
    if (current || chunks.length === 0) chunks.push(current);
    return chunks;
  };

  // Broadcast paste-busy so UI buttons (Compact/Model/Effort/Think) can grey
  // out while another caller is mid-paste. Belt-and-braces fix on top of the
  // mutex: if a button click reaches send-command anyway, the mutex serializes
  // it — but a disabled button gives the user immediate feedback that nothing
  // will happen mid-stream.
  const broadcastTabId = findTabIdForTerm(term);
  const isCodexPasteSource = !!(source && String(source).startsWith('codex-'));
  const hasPromptQueueOrigin = isPromptQueueSource(source);
  const isPromptQueueAutomation = isPromptQueueAutomationSource(source, { promptQueueAction });
  const isHistoryComposerSource = typeof source === 'string'
    && (source === 'history-panel' || source === 'codex-history-panel');
  const shouldStageClaudeAudit = shouldStageClaudeUserPromptAudit({
    fast,
    broadcastTabId,
    submit,
    submitSequence,
    isCodexPasteSource,
    content,
  });
  const requiresImagePathValidation = hasPromptQueueOrigin || isHistoryComposerSource;
  const responsePreflightEngine = isCodexPasteSource ? 'codex' : (!fast ? 'claude' : null);
  const shouldTrackResponsePreflight = !!(
    submit
    && submitSequence !== '\t'
    && responsePreflightEngine
    && broadcastTabId
    && (hasPromptQueueOrigin || isHistoryComposerSource)
    && !String(content || '').trimStart().startsWith('/')
  );
  const responsePreflight = shouldTrackResponsePreflight
    ? {
        startTs: Date.now(),
        engine: responsePreflightEngine,
        source: source || null,
      }
    : null;
  if (responsePreflight && !activityOpenIntervals.has(broadcastTabId)) {
    responseActivityPreflights.set(broadcastTabId, responsePreflight);
  }
  let awaitCodexUserMessageAudit = requestedCodexUserMessageAudit;
  let codexPromptInFlightState = null;
  let codexSubmissionWatcher = null;
  let codexSubmitAuthority = null;
  let codexSubmitId = null;
  let codexPtyAdmission = null;
  let claudePromptQueuePtyAdmission = null;
  let stagedCodexImageRefs = [];
  let codexImagePasteSegments = null;
  let codexImageRequestProjection = null;
  let pasteBusyPublished = false;
  let confirmedClaudeAuditResult = null;
  let claudeAuditBoundary = null;
  let claudeHookRouteProof = null;
  // The Codex rollout audit is cleaned up from `finally`, so its reference
  // must live in the function scope rather than inside the `try` block.
  let stagedCodexAudit = null;
  // Same constraint for the Claude audit: `finally` finalizes an unsubmitted
  // staged audit, so the binding must be visible outside the `try` block.
  let stagedClaudeAudit = null;
  let pasteWritten = false;
  let autoDurableAttempt = null;
  let durablePreSubmitBoundary = null;
  let claudeDraftGuardInputRevision = null;
  let claudeDraftGuardProof = null;
  let claudePasteReadyAttempt = null;
  let claudePasteReadyProof = null;
  let effectiveClaudeExactEmptyEvidence = claudeExactEmptyEvidence || startupExactEmptyEvidence;
  const requiresClaudeDraftPasteAdmission = submit === false && !fast
    && source === 'mcp-ai-prompt' && !isCodexPasteSource;
  const draftPasteFailure = (stage, checkInput = true) => {
    if (!requiresClaudeDraftPasteAdmission) return null;
    const validation = validateClaudeDraftPasteAtBoundary(
      claudeDraftPasteAdmission, term, checkInput ? expectedInputRevision : null,
    );
    if (validation.valid) return null;
    console.warn(logPrefix + ' [ClaudeDraftPaste] rejected stage=' + stage + ' reason=' + validation.reason);
    return { success: false, accepted: false, submitted: false,
      pasteWritten, enterWritten: false, draftPasteRejected: true,
      error: validation.reason, rejectionStage: stage };
  };
  const destinationFailure = () => {
    if (!expectedDestination && !expectedTarget) return null;
    const actual = readAgentSendDestinationAtWriteBoundary(
      broadcastTabId,
      responsePreflightEngine,
      isCodexPasteSource
        ? codexSubmissionWatcher?.sessionId
        : bridgeKnownSessions.has(broadcastTabId)
          ? claudeAuditBoundary?.sessionId
          : null,
    );
    return agentSendTargetPreconditionFailure(expectedDestination, actual)
      || agentSendTargetPreconditionFailure(expectedTarget, actual);
  };
  const exactSendCancellationRequested = () => !!(
    sendOperationContext?.cancelRequested === true
    || (
      broadcastTabId
      && handoffId
      && agentSendCancellations.isCancelled(broadcastTabId, handoffId, sendAttemptId)
    )
  );
  const cancelledSendResult = (stage) => {
    console.warn(logPrefix + ' [AgentSendCancel] refuse tab=' + String(broadcastTabId || '').slice(-12)
      + ' handoff=' + (handoffId || '-')
      + ' stage=' + stage
      + ' pasteWritten=' + pasteWritten);
    return {
      success: false,
      error: 'agent_send_cancelled',
      submitted: false,
      pasteWritten,
      cancelStage: stage,
      handoffId: handoffId || null,
    };
  };
  const validateStartupPromptLease = (allowFrameAdvance = false) => {
    if (!startupPromptLease || !broadcastTabId) {
      return { valid: true, reason: 'startup-prompt-lease-not-required' };
    }
    return claudePromptStability.validate(
      broadcastTabId,
      startupPromptLease.generation,
      startupPromptLease,
      { allowFrameAdvance },
    );
  };
  const presentationHistorySessionId = promptPresentationHistorySessionId(presentationSnapshot);
  const normalizedPresentationSnapshot = normalizePromptPresentationSnapshot(presentationSnapshot);
  if (sendOperationContext && sendOperationKey && sendAttemptId) {
    sendOperationContext.sendOperationKey = sendOperationKey;
    sendOperationContext.sendAttemptId = sendAttemptId;
  }
  const emitBusy = (busy, phase = busy ? 'sending' : 'idle') => {
    if (pasteBusyPublished === busy) return;
    pasteBusyPublished = busy;
    if (!broadcastTabId) {
      console.warn(logPrefix + ' [PasteBusy] no-tab busy=' + busy + ' termPid=' + (term && term.pid ? term.pid : 'unknown'));
      return;
    }
    console.log(logPrefix + ' [PasteBusy] emit tab=' + String(broadcastTabId).slice(-12) + ' busy=' + busy + ' termPid=' + (term && term.pid ? term.pid : 'unknown'));
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('claude:paste-busy', {
        tabId: broadcastTabId,
        busy,
        phase,
        handoffId: handoffId || null,
        sendAttemptId: sendAttemptId || null,
        sendOperationKey: sendOperationKey || null,
      });
    }
  };
  emitBusy(true, 'sending');
  try {
  const draftAdmissionFailure = draftPasteFailure('write-owner-admission');
  if (draftAdmissionFailure) return draftAdmissionFailure;
  if (exactSendCancellationRequested()) {
    return cancelledSendResult('before-admission');
  }
  const startupAdmission = validateStartupPromptLease(false);
  if (!startupAdmission.valid) {
    return {
      success: false,
      error: 'claude_prompt_not_stable',
      reason: startupAdmission.reason,
      submitted: false,
      pasteWritten: false,
    };
  }
  if (
    isCodexPasteSource
    && broadcastTabId
    && codexSubmissionPreflight !== false
  ) {
    codexPtyAdmission = captureCodexPtySubmitAdmission(
      broadcastTabId,
      term,
      expectedInputRevision,
    );
    if (!codexPtyAdmission.available) {
      console.warn(logPrefix + ' [CodexSubmissionAdmission] refusing before paste reason='
        + (codexPtyAdmission.reason || 'unknown'));
      if (isPromptQueueAutomation) {
        return {
          success: false,
          accepted: false,
          deferred: true,
          error: 'codex_input_not_ready',
          detail: codexPtyAdmission.reason || 'codex_submit_not_admitted',
          submitted: false,
        };
      }
      return {
        success: false,
        error: codexPtyAdmission.reason || 'codex_submit_not_admitted',
        submitted: false,
      };
    }
    if (submit && submitSequence !== '\t') {
      codexSubmissionWatcher = armCodexSubmissionObservationWithoutProof(
        broadcastTabId,
        terminalProjects.get(broadcastTabId),
        'safe-paste-final:' + (source || 'codex-submit'),
        { reserveProvisional: true },
      );
      if (!codexSubmissionWatcher?.available) {
        console.warn(logPrefix + ' [CodexSubmissionObservation] refusing before paste status='
          + (codexSubmissionWatcher?.writerStatus || 'unknown')
          + ' error=' + (codexSubmissionWatcher?.error || '-'));
        return {
          success: false,
          error: codexSubmissionWatcher?.error || 'codex_turn_watcher_unavailable',
          writerStatus: codexSubmissionWatcher?.writerStatus || 'unknown',
          submitted: false,
        };
      }
      if (codexSubmissionWatcher.kind === 'provisional-source') {
        // This Enter is what can materialize the linked child. It is allowed only
        // once for the exact launch generation and must wait for rollout
        // `user_message` before callers may treat delivery/identity as confirmed.
        awaitCodexUserMessageAudit = true;
      }
    }
  }
  if (isPromptQueueAutomation && !isCodexPasteSource) {
    claudePromptQueuePtyAdmission = broadcastTabId
      ? captureClaudePromptQueuePtyAdmission(broadcastTabId, term)
      : { available: false, reason: 'claude_input_not_ready' };
    if (!claudePromptQueuePtyAdmission.available) {
      console.warn(logPrefix + ' [ClaudeQueueAdmission] waiting before paste reason='
        + (claudePromptQueuePtyAdmission.reason || 'claude_input_not_ready'));
      return {
        success: false,
        accepted: false,
        deferred: true,
        error: 'claude_input_not_ready',
        submitted: false,
      };
    }
  }
  if (requiresImagePathValidation) {
    const queueImages = await validatePromptQueueImageMarkers(content);
    if (!queueImages.success) {
      content = replaceUnavailableImagePathMarkers(
        content,
        queueImages.missing,
      );
      console.warn(logPrefix + ' [PromptQueueAssets] degraded transfer source=' + (source || '-')
        + ' missing=' + queueImages.missing.length
        + ' action=replace-with-imageError');
    }
  }
  if (isCodexPasteSource) {
    const prepared = prepareCodexImagePathMarkersForPaste(broadcastTabId, content, source || 'codex-paste');
    if (prepared.replaced > 0 || prepared.missing.length > 0) {
      console.log(logPrefix + ' [CodexImagePathPaste] markers=' + prepared.replaced
        + ' staged=' + prepared.staged.length
        + ' missing=' + prepared.missing.length
        + ' source=' + (source || '-'));
    }
    if (prepared.missing.length > 0) {
      console.warn(logPrefix + ' [CodexImagePathPaste] degraded missing paths source=' + (source || '-')
        + ' missing=' + prepared.missing.length
        + ' action=replace-with-imageError');
    }
    content = prepared.text;
    stagedCodexImageRefs = prepared.staged;
    codexImagePasteSegments = prepared.replaced > 0 ? prepared.segments : null;
  }
  if (!fast && !isCodexPasteSource) {
    try {
      const preparedClaudePrompt = prepareClaudePromptTransport(content);
      content = preparedClaudePrompt.transport.text;
    } catch (error) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        pasteWritten: false,
        error: error?.code || 'claude_prompt_transport_failed',
      };
    }
  }
  if (isDesktopHistorySendReceiptEligible({
    submit,
    tabId: broadcastTabId,
    handoffId,
    source,
    rawPrompt: durableRawPrompt,
    presentationSnapshot: normalizedPresentationSnapshot,
    sendOperationKey,
    sendAttemptId,
  })) {
    let identity;
    try {
      identity = buildDesktopHistorySendIdentity({
        tabId: broadcastTabId,
        handoffId,
        provider: isCodexPasteSource ? 'codex' : 'claude',
        source,
        sessionId: bridgeKnownSessions.get(broadcastTabId) || null,
        rawPrompt: durableRawPrompt,
        expectedTarget: expectedDestination,
        promptHash: pasteAuditHash(content),
        promptLength: content.length,
      });
    } catch (error) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        pasteWritten: false,
        error: error?.message || 'agent_send_durable_identity_invalid',
      };
    }
    const begun = agentSendReceiptStore.beginAttempt(identity);
    if (begun?.ok !== true) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        pasteWritten: false,
        error: begun?.code || 'agent_send_durable_attempt_unavailable',
      };
    }
    if (begun.action === 'replay') {
      return desktopHistorySendReplayResult(begun.record);
    }
    sendOperationKey = identity.operationKey;
    sendAttemptId = begun.attemptId;
    autoDurableAttempt = {
      operationKey: sendOperationKey,
      attemptId: sendAttemptId,
    };
    if (sendOperationContext) {
      sendOperationContext.sendOperationKey = sendOperationKey;
      sendOperationContext.sendAttemptId = sendAttemptId;
    }
    if (expectedDestination) {
      const stagedTarget = agentSendReceiptStore.stageAttemptContext(sendOperationKey, sendAttemptId, {
        expectedTarget: expectedDestination,
      });
      if (stagedTarget?.ok !== true) return {
        success: false, accepted: false, submitted: false, pasteWritten: false, enterWritten: false,
        code: 'agent_send_target_precondition_not_durable', error: 'The exact send target could not be recorded.',
      };
    }
    console.log('[AgentSendReceipt] desktop History attempt started'
      + ' tab=' + String(broadcastTabId).slice(-12)
      + ' handoff=' + String(handoffId).slice(0, 32)
      + ' attempt=' + String(sendAttemptId).slice(0, 12)
      + ' provider=' + (isCodexPasteSource ? 'codex' : 'claude'));
  }
  if (codexSubmissionWatcher?.reservation) {
    const expectedHash = pasteAuditHash(content);
    codexSubmitId = handoffId
      || ('codex-submit-' + Date.now() + '-' + crypto.randomBytes(6).toString('hex'));
    const submitTarget = {
      handoffId: handoffId || null,
      expectedHash,
      expectedLen: content.length,
    };
    const createdAuthority = createMainCodexActionAuthority({
      profile: CODEX_ACTION_PROFILE_RESUMED_ACTIVE_SUBMIT,
      tabId: broadcastTabId,
      launchId: codexSubmissionWatcher.launchId,
      sourceSessionId: codexSubmissionWatcher.sessionId,
      operationId: codexSubmitId,
      requestId: codexSubmitId,
      target: submitTarget,
    });
    if (!createdAuthority.success) {
      return {
        success: false,
        error: 'codex_submit_action_authority_unavailable',
        authorityError: createdAuthority.error,
        submitted: false,
      };
    }
    codexSubmitAuthority = createdAuthority.authority;
    codexSubmissionWatcher.reservation.actionAuthority = codexSubmitAuthority;
    codexSubmissionWatcher.reservation.submitId = codexSubmitId;
    codexSubmissionWatcher.reservation.expectedHash = expectedHash;
    codexSubmissionWatcher.reservation.expectedLen = content.length;
    codexSubmissionWatcher.reservation.handoffId = handoffId || null;
    transitionMainCodexActionAuthority(
      codexSubmitAuthority,
      'waiting',
      'awaiting-resume-submit-arm',
    );
    const authorityVerdict = validateMainCodexActionAuthority(codexSubmitAuthority, {
      phases: ['waiting'],
      profile: CODEX_ACTION_PROFILE_RESUMED_ACTIVE_SUBMIT,
      launchId: codexSubmissionWatcher.launchId,
      sourceSessionId: codexSubmissionWatcher.sessionId,
      target: submitTarget,
    });
    if (!authorityVerdict.valid) {
      transitionMainCodexActionAuthority(
        codexSubmitAuthority,
        'revoked',
        authorityVerdict.reason,
      );
      return {
        success: false,
        error: 'codex_submit_action_authority_revoked',
        authorityReason: authorityVerdict.reason,
        submitted: false,
      };
    }
    if (codexActionAuthorityTestHoldEnabled(codexSubmitAuthority.profile)) {
      const holdResult = await waitForCodexActionAuthorityTestRelease(codexSubmitAuthority);
      if (holdResult?.released !== true) {
        return {
          success: false,
          error: 'codex_submit_action_authority_revoked',
          authorityReason: codexSubmitAuthority.reason || holdResult?.reason || 'scope-changed',
          submitted: false,
        };
      }
      const authorityAfterHold = validateMainCodexActionAuthority(codexSubmitAuthority, {
        phases: ['waiting'],
        profile: CODEX_ACTION_PROFILE_RESUMED_ACTIVE_SUBMIT,
        launchId: codexSubmissionWatcher.launchId,
        sourceSessionId: codexSubmissionWatcher.sessionId,
        target: submitTarget,
      });
      if (!authorityAfterHold.valid) {
        transitionMainCodexActionAuthority(
          codexSubmitAuthority,
          'revoked',
          authorityAfterHold.reason,
        );
        return {
          success: false,
          error: 'codex_submit_action_authority_revoked',
          authorityReason: authorityAfterHold.reason,
          submitted: false,
        };
      }
    }
    transitionMainCodexActionAuthority(
      codexSubmitAuthority,
      'armed',
      'resume-submit-authority-armed',
    );
  }
  if (shouldStageClaudeAudit) {
    const sessionHints = [
      bridgeKnownSessions.get(broadcastTabId) || null,
      presentationHistorySessionId,
    ].filter((value, index, values) => value && values.indexOf(value) === index);
    let auditTranscriptPath = null;
    let auditSessionId = null;
    for (const sessionHint of sessionHints) {
      auditTranscriptPath = resolveClaudeSessionFileForTab(
        broadcastTabId,
        sessionHint,
      );
      if (auditTranscriptPath) {
        auditSessionId = sessionHint;
        break;
      }
    }
    claudeAuditBoundary = await captureClaudePromptAuditBoundary(auditTranscriptPath, {
      sessionId: auditSessionId,
    });
    if (
      claudeAuditBoundary?.available !== true
      && claudeAuditBoundary?.reason === 'transcript-unresolved'
      && !claudeAuditBoundary?.transcriptPath
    ) {
      // The first prompt creates its JSONL only after Enter. For this one case,
      // replace any cached PID mapping with a fresh process-tree proof from this
      // exact PTY; the later UserPromptSubmit must repeat the same PID + tab.
      claudeHookRouteProof = await prebindClaudeHookRouteForSubmit(
        broadcastTabId,
        logPrefix,
      );
    }
    const auditAdmission = classifyClaudePromptAuditAdmission({
      boundary: claudeAuditBoundary,
      hookRoute: claudeHookRouteProof,
      expectedTabId: broadcastTabId,
    });
    if (!auditAdmission.allowed) {
      console.warn(logPrefix + ' [PasteAudit] pre-submit boundary unavailable tab='
        + String(broadcastTabId).slice(-12)
        + ' reason=' + (claudeAuditBoundary.reason || 'unknown')
        + ' sessionHints=' + sessionHints.map(value => String(value).slice(0, 8)).join(',')
        + ' hookRoute=' + (claudeHookRouteProof?.bound === true ? 'bound' : 'unproven'));
      if (awaitClaudeUserMessageAudit) {
        return {
          success: false,
          accepted: false,
          deferred: true,
          error: 'claude_audit_boundary_unavailable',
          detail: claudeAuditBoundary.reason || 'transcript-unresolved',
          submitted: false,
        };
      }
    } else if (auditAdmission.mode === 'fresh-hook-route') {
      console.log(logPrefix + ' [PasteAudit] first prompt admitted by exact Claude hook route tab='
        + String(broadcastTabId).slice(-12)
        + ' pid=' + Number(claudeHookRouteProof.pid)
        + ' mode=' + auditAdmission.mode);
    }
  }

  const destinationAfterAdmission = destinationFailure();
  if (destinationAfterAdmission) return destinationAfterAdmission;

  // Chunking strategy:
  //   fast=true  (Gemini/bash) — split by CHUNK_MAX, write back-to-back, no waits.
  //   fast=false (Claude Ink)  — single write of the whole payload wrapped in one
  //                              bracket pair. Codex image plans are the exception:
  //                              every image/text segment is a separate paste event.
  //
  // Why slow-mode no longer chunks:
  //   Earlier implementation split the payload into 900-byte chunks and called
  //   waitForRender after each (up to safetyTimeoutMs=8000ms). On a 50 KB queue
  //   prompt (56 chunks), 53 of those waits hit the full 1000ms timeout because
  //   Ink does NOT emit \x1b[?2026l mid-paste while \x1b[200~ is still open —
  //   it batches the render until \x1b[201~ closes the paste. Net effect: 57 s
  //   gap between "Run after" firing and Claude receiving the prompt; user
  //   thought the queue silently failed.
  //
  //   node-pty 1.2.0-beta.13 (PR #831) reliably writes >TTYHOG via fs.write
  //   with EAGAIN retry, so a single 50 KB term.write() no longer drops bytes
  //   on macOS. Manual Cmd+V already takes this path and lands as one chip
  //   instantly — slow-mode now mirrors that behaviour.
  //
  //   Fact reference: docs/knowledge/fact-claude-tui-mechanics.md §4 (single
  //   bracket pair) + §9 (alt-screen DEC ?2004 loss). See also fix-claude-
  //   paste-stuck-queue.md for the 57s repro.
  // Codex recognizes an image only when one explicit paste event contains the
  // image path and nothing else. Queue payloads can interleave attachments and
  // editable text, so each planned segment becomes its own bracketed paste.
  // A normal prompt remains one paste group and keeps the existing behavior.
  const pasteGroups = codexImagePasteSegments?.length
    ? codexImagePasteSegments.map(segment => ({ kind: segment.kind, text: segment.text }))
    : [{ kind: 'text', text: content }];
  const chunks = [];
  for (let groupIndex = 0; groupIndex < pasteGroups.length; groupIndex++) {
    const group = pasteGroups[groupIndex];
    const groupChunks = fast ? splitUtf8Chunks(group.text, CHUNK_MAX) : [group.text];
    for (let chunkIndex = 0; chunkIndex < groupChunks.length; chunkIndex++) {
      chunks.push({
        text: groupChunks[chunkIndex],
        kind: group.kind,
        startsPaste: chunkIndex === 0,
        endsPaste: chunkIndex === groupChunks.length - 1,
      });
    }
  }

  const t0 = Date.now();
  const resolvedSubmitLabel = submitLabel || (submitSequence === '\t' ? 'Tab' : (submitSequence === '\r' ? 'Enter' : JSON.stringify(submitSequence)));
  const shouldVerifyCodexVisibleDraft = !!(verifyCodexVisibleDraftBeforeSubmit && submit && isCodexPasteSource && !fast && broadcastTabId);
  codexPromptInFlightState = submit && isCodexPasteSource && broadcastTabId && submitSequence !== '\t'
    ? beginCodexPromptInFlight(broadcastTabId, 'safe-paste-submit', { source, handoffId })
    : null;
  console.log(logPrefix + ' 🚀 Start: "' + content.substring(0, 40) + '" (' + content.length + ' chars → ' + pasteGroups.length + ' paste group(s), ' + chunks.length + ' chunk(s), fast=' + fast + ', ctrlCFirst=' + ctrlCFirst + ', stashFirst=' + stashFirst + ', submit=' + resolvedSubmitLabel + ', handoff=' + (handoffId || '-') + ', source=' + (source || '-') + ', skipRenderWait=' + skipRenderWait + ', codexVisibleDraftGuard=' + shouldVerifyCodexVisibleDraft + ')');

  if (shouldVerifyCodexVisibleDraft && mainWindow && !mainWindow.isDestroyed() && !ctrlCFirst && !stashFirst) {
    if (
      expectedInputRevision !== null
      && getTerminalInputRevision(broadcastTabId) !== expectedInputRevision
    ) {
      return {
        success: false,
        error: 'codex_input_ownership_changed',
        submitted: false,
        manualTakeover: true,
      };
    }
    const draftProbeInputRevision = getTerminalInputRevision(broadcastTabId);
    const beforeDraft = await requestTerminalCodexDraftState(
      mainWindow.webContents,
      broadcastTabId,
      'codex-pre-submit-before-paste',
      700,
      {
        waitFor: false,
        waitTimeoutMs: 2500,
        waitOnUnknownOnly: true,
        mergeRendererPositive: true,
      },
    );
    const afterDraftProbeInputRevision = getTerminalInputRevision(broadcastTabId);
    if (
      afterDraftProbeInputRevision !== draftProbeInputRevision
      || (
        expectedInputRevision !== null
        && afterDraftProbeInputRevision !== expectedInputRevision
      )
    ) {
      return {
        success: false,
        error: 'codex_input_ownership_changed',
        submitted: false,
        manualTakeover: true,
        codexDraftGuard: beforeDraft || null,
      };
    }
    console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexDraftGuard] before-paste success=' + !!beforeDraft?.success
      + ' hasDraft=' + beforeDraft?.hasDraft
      + ' source=' + (beforeDraft?.source || '-')
      + ' preview=' + JSON.stringify(String(beforeDraft?.preview || '').slice(0, 120))
      + (beforeDraft?.debug ? ' debug=' + JSON.stringify(String(beforeDraft.debug).slice(0, 700)) : '')
      + (beforeDraft?.error ? ' error=' + beforeDraft.error : ''));
    if (!beforeDraft?.success || beforeDraft.hasDraft !== false) {
      const error = beforeDraft?.hasDraft === true
        ? 'codex_existing_draft_before_paste'
        : 'codex_draft_state_unknown_before_paste';
      console.error(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexDraftGuard] ❌ refusing before paste error=' + error);
      return {
        success: false,
        error,
        submitted: false,
        chunksTotal: chunks.length,
        renderTimeMs: [],
        submitKey: null,
        codexDraftGuard: beforeDraft || null,
      };
    }
  }

  // Optional: Ctrl+S to stash any user input — Claude pushes it to stash and
  // clears the prompt; after our slash-cmd submits, Claude auto-restores stash.
  // No Ctrl+C needed → no danger-zone, no double-Ctrl+C exit risk.
  // Side effect: if input was empty AND a stash already existed, Ctrl+S pops
  // the stash back into the prompt. Our bracketed paste then prepends the
  // command — Esc + Enter still submits cleanly because slash-cmd takes the
  // whole input verbatim.
  if (stashFirst) {
    // Skip Ctrl+S if Claude is already showing the "Stashed (auto-restores)"
    // marker — sending another Ctrl+S in that state would either pop the saved
    // stash back into the input (empty-input case) or overwrite it with the
    // current input (non-empty case). Both destroy user-saved work. See
    // hasStashedMarker() above for the marker scan + fact-claude-tui-control.md
    // "Stash Flow" section for the bidirectional handleStash semantics.
    const alreadyStashed = broadcastTabId ? hasStashedMarker(broadcastTabId) : false;
    if (alreadyStashed) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Stash marker already present in PTY buffer → skip Ctrl+S (would corrupt existing stash)');
    } else {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Sending Ctrl+S (stash)...');
      term.write('\x13');
      if (!fast) {
        // 20ms drain just to let Ink ingest \x13 before our paste lands. If
        // input had text, Ink renders "Stashed (auto-restores after submit)"
        // ~40ms later — paste arrives after that render starts but Ink
        // processes our bytes in order regardless. Larger drain hurts the
        // empty-input case (Ctrl+S = no-op, no data, drain waits in vain).
        await drainPtyData(term, 20);
      } else {
        await new Promise(r => setTimeout(r, 10));
      }
    }
  }

  // Optional: Ctrl+C to clear input
  if (ctrlCFirst) {
    console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Sending Ctrl+C...');
    const ctrlCPromise = !fast ? waitForRender(term, 2000, logPrefix + ':ctrl-c') : null;
    term.write('\x03');
    if (ctrlCPromise && ctrlCPromise.markWriteTime) ctrlCPromise.markWriteTime();
    if (!fast) {
      const ctrlCResult = await ctrlCPromise;
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Ctrl+C render: timedOut=' + ctrlCResult.timedOut + ' stale=' + (ctrlCResult.isStale || false) + ' elapsed=' + (ctrlCResult.elapsedMs || 'n/a') + 'ms');
      await new Promise(r => setTimeout(r, 50));
    } else {
      // Tiny delay even in fast mode to let kernel process SIGINT
      await new Promise(r => setTimeout(r, 10));
    }
  }

  // Drain deferred renders (from focus loss/regain, periodic updates, etc.)
  // These would produce stale sync markers that pass the 15ms threshold.
  //
  // HARD CEILING is mandatory here: this is a "wait for 150ms of silence"
  // debounce, but the Replay ▶ button (and any send-during-stream path) pastes
  // WHILE Claude is streaming, when the PTY never goes quiet for 150ms — so an
  // uncapped drain blocks for the whole turn (prod: 9.7s and 98s replays, all
  // of it here; the paste + waitForRender after resolved in <12ms). 600ms is
  // ample to absorb a focus/resize render burst when idle, and bounds the
  // worst case when streaming. The post-write waitForRender still guards stale
  // markers, so bailing the drain early costs no correctness.
  if (!fast) {
    await drainPtyData(term, 150, 600);
  }

  const renderTimes = [];
  let pasteRenderAck = null;

  // Bracketed Paste wrapping strategy:
  //   Claude slow-mode has one paste group, so Ink still sees one atomic paste
  //   and emits one [Pasted text #N] chip. Codex image plans deliberately have
  //   multiple groups so its TUI receives every image path as a standalone
  //   paste event. Fast-mode can chunk within a group, but the brackets remain
  //   around the complete group rather than around every transport chunk.
  // Verified against fact-claude-tui-mechanics.md §4.

  if (isCodexPasteSource && broadcastTabId && stagedCodexImageRefs.length > 0) {
    codexImageBindings.beginDirect(broadcastTabId, stagedCodexImageRefs);
  }
  if (codexPtyAdmission) {
    const currentAdmission = revalidateCodexPtySubmitAdmission(codexPtyAdmission);
    if (!currentAdmission.valid) {
      console.warn(logPrefix + ' [CodexSubmissionAdmission] cancelled before paste reason='
        + currentAdmission.reason);
      if (isPromptQueueAutomation) {
        return {
          success: false,
          accepted: false,
          deferred: true,
          error: 'codex_input_not_ready',
          detail: currentAdmission.reason,
          submitted: false,
          chunksTotal: chunks.length,
        };
      }
      return {
        success: false,
        error: currentAdmission.reason,
        submitted: false,
        chunksTotal: chunks.length,
      };
    }
  }
  if (claudePromptQueuePtyAdmission) {
    const currentAdmission = revalidateClaudePromptQueuePtyAdmission(claudePromptQueuePtyAdmission);
    if (!currentAdmission.valid) {
      console.warn(logPrefix + ' [ClaudeQueueAdmission] cancelled before paste reason='
        + currentAdmission.reason);
      return {
        success: false,
        accepted: false,
        deferred: true,
        error: 'claude_input_not_ready',
        detail: currentAdmission.reason,
        submitted: false,
        chunksTotal: chunks.length,
      };
    }
  }
  if (exactSendCancellationRequested()) {
    return cancelledSendResult('before-paste');
  }
  const startupPasteBoundary = validateStartupPromptLease(false);
  if (!startupPasteBoundary.valid) {
    return {
      success: false,
      error: 'claude_prompt_not_stable',
      reason: startupPasteBoundary.reason,
      submitted: false,
      pasteWritten: false,
    };
  }
  if (
    verifyClaudeVisibleDraftBeforePaste
    && broadcastTabId
    && !isCodexPasteSource
    && !fast
    && !ctrlCFirst
    && !stashFirst
  ) {
    if (requireFreshClaudeExactEmptyBeforePaste) {
      const exactCapture = await captureAgentInputAtWriteBoundary(
        broadcastTabId,
        'copy',
        'claude',
        { proveExactEmpty: true },
        term,
      );
      const exactCaptureDecision = classifyClaudeFreshExactEmptyCapture(exactCapture);
      console.log(logPrefix + ' [ClaudeComposerWriteBoundary] fresh-exact-before-paste'
        + ' valid=' + exactCaptureDecision.valid
        + ' state=' + exactCaptureDecision.composerDraftState
        + ' reason=' + exactCaptureDecision.reason
        + ' chars=' + (typeof exactCapture?.text === 'string' ? exactCapture.text.length : 'unknown')
        + ' images=' + Number(exactCapture?.images || 0));
      if (!exactCaptureDecision.valid) {
        return {
          success: false,
          error: exactCaptureDecision.reason,
          reason: exactCaptureDecision.reason,
          submitted: false,
          pasteWritten: false,
          composerDraftState: exactCaptureDecision.composerDraftState,
          draftPreserved: true,
          claudeDraftGuard: exactCapture || null,
        };
      }
      effectiveClaudeExactEmptyEvidence = exactCaptureDecision.evidence;
      if (sendOperationContext) {
        sendOperationContext.claudeExactEmptyEvidence = effectiveClaudeExactEmptyEvidence;
      }
    }
    const draftBoundary = await verifyClaudeComposerEmptyAtWriteBoundary(
      broadcastTabId,
      term,
      'claude-write-boundary-before-paste:' + (source || 'unknown'),
      { exactEmptyEvidence: effectiveClaudeExactEmptyEvidence },
    );
    if (!draftBoundary.valid) {
      return {
        success: false,
        error: startupPromptLease
          ? 'claude_prompt_not_stable'
          : draftBoundary.reason,
        reason: draftBoundary.reason,
        submitted: false,
        pasteWritten: false,
        claudeDraftGuard: draftBoundary.proof || null,
      };
    }
    claudeDraftGuardInputRevision = Number(draftBoundary.proof?.inputRevision);
    claudeDraftGuardProof = draftBoundary.proof || null;
    if (exactSendCancellationRequested()) {
      return cancelledSendResult('after-claude-proof-before-paste');
    }
    const startupAfterComposerProof = validateStartupPromptLease(false);
    if (!startupAfterComposerProof.valid) {
      return {
        success: false,
        error: 'claude_prompt_not_stable',
        reason: startupAfterComposerProof.reason,
        submitted: false,
        pasteWritten: false,
      };
    }
  }
  const destinationBeforePaste = destinationFailure();
  if (destinationBeforePaste) return destinationBeforePaste;
  if (codexSubmitAuthority) {
    const exactReservation = codexSubmissionWatcher?.reservation || null;
    const currentDiscovery = codexWatchers.get(broadcastTabId) || null;
    const authorityAtPaste = validateMainCodexActionAuthority(codexSubmitAuthority, {
      phases: ['armed'],
      profile: CODEX_ACTION_PROFILE_RESUMED_ACTIVE_SUBMIT,
      launchId: codexSubmissionWatcher.launchId,
      sourceSessionId: codexSubmissionWatcher.sessionId,
      target: codexSubmitAuthority.target,
    });
    const exactObserverAtPaste = !!currentDiscovery
      && currentDiscovery.provisionalSubmitReservation === exactReservation
      && exactReservation?.actionAuthority === codexSubmitAuthority
      && currentDiscovery.launchId === codexSubmissionWatcher.launchId
      && currentDiscovery.sourceSessionId === codexSubmissionWatcher.sessionId;
    if (!authorityAtPaste.valid || !exactObserverAtPaste) {
      if (codexSubmitAuthority.phase !== 'revoked') {
        transitionMainCodexActionAuthority(
          codexSubmitAuthority,
          'revoked',
          authorityAtPaste.reason || 'resume-submit-observer-changed-before-paste',
        );
      }
      return {
        success: false,
        error: 'codex_submit_action_authority_revoked',
        authorityReason: authorityAtPaste.reason || 'resume-submit-observer-changed-before-paste',
        submitted: false,
        pasteWritten: false,
      };
    }
    const consumed = transitionMainCodexActionAuthority(
      codexSubmitAuthority,
      'consumed',
      'resume-submit-paste-boundary',
    );
    if (!consumed.success) {
      return {
        success: false,
        error: 'codex_submit_action_authority_not_consumed',
        submitted: false,
        pasteWritten: false,
      };
    }
  }
  if (sendOperationKey && sendAttemptId) {
    durablePreSubmitBoundary = isCodexPasteSource
      ? captureCodexPromptAuditBoundary(broadcastTabId, Date.now())
      : claudeAuditBoundary;
    codexImageRequestProjection = isCodexPasteSource
      ? createCodexImageRequestProjection({
        tabId: broadcastTabId,
        handoffId,
        operationKey: sendOperationKey,
        attemptId: sendAttemptId,
        requestText: durableRawPrompt,
        transportText: content,
        segments: codexImagePasteSegments,
        imageRefs: stagedCodexImageRefs,
      })
      : null;
    if (codexImageRequestProjection) {
      const projectionOwner = agentSendReceiptStore.get(sendOperationKey);
      // Desktop History may already name the final transport as its durable
      // identity. It needs no request->transport bridge. Persist a projection
      // only when this exact attempt actually owns its original request hash.
      if (projectionOwner?.attemptId !== sendAttemptId
        || projectionOwner.promptHash !== codexImageRequestProjection.requestHash
        || projectionOwner.promptLength !== codexImageRequestProjection.requestLength) {
        codexImageRequestProjection = null;
      }
    }
    const stagedDurableContext = agentSendReceiptStore.stageAttemptContext(
      sendOperationKey,
      sendAttemptId,
      {
        source: source || null,
        sessionId: durablePreSubmitBoundary?.sessionId || null,
        ...(expectedDestination ? { expectedTarget: expectedDestination } : {}),
        promptText: durableRawPrompt,
        transportText: content,
        expectedImagePaths: (codexImagePasteSegments || [])
          .filter((segment) => segment?.kind === 'image' && typeof segment.text === 'string')
          .map((segment) => segment.text),
        expectedImageRefs: stagedCodexImageRefs.map(ref => ({ ...ref })),
        imageRequestProjection: codexImageRequestProjection,
        presentationSnapshot: normalizedPresentationSnapshot,
        transcriptBoundary: durablePreSubmitBoundary || null,
      },
    );
    if (stagedDurableContext?.ok !== true) {
      console.warn('[AgentSendReceipt] refusing paste without durable pre-Enter context'
        + ' operation=' + String(sendOperationKey).slice(0, 72)
        + ' attempt=' + String(sendAttemptId).slice(0, 12)
        + ' reason=' + (stagedDurableContext?.reason || 'unknown'));
      return {
        success: false,
        accepted: false,
        submitted: false,
        pasteWritten: false,
        error: 'agent_send_context_not_durable',
      };
    }
  }
  if (shouldStageClaudeAudit && submit && !fast && !isCodexPasteSource && broadcastTabId) {
    const mirror = getHeadlessTerminalMirror(broadcastTabId);
    if (!mirror || mirror.failed === true || mirror.complete !== true) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        pasteWritten: false,
        error: 'claude_headless_mirror_unavailable_before_paste',
      };
    }
    const shape = expectedClaudePasteShape(content, normalizedPresentationSnapshot);
    claudePasteReadyAttempt = {
      mirrorToken: mirror,
      mirrorGeneration: mirror.generation,
      terminalRunSeq: Number(terminalCommandState.get(broadcastTabId)?.runSeq || 0),
      terminalLifecycleGeneration: getTerminalLifecycleGeneration(broadcastTabId),
      inputRevision: getTerminalInputRevision(broadcastTabId),
      baselineCommittedFrameGeneration: Number(
        mirror.lastCommittedVisibleSnapshot?.committedFrameGeneration || 0,
      ),
      expectedHasText: shape.expectedHasText,
      expectedImageCount: shape.expectedImageCount,
      transportLength: shape.transportLength,
      lastDecision: null,
    };
  }
  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    let payload = chunk.text;
    if (chunk.startsPaste) payload = PASTE_START + payload;
    if (chunk.endsPaste) payload = payload + PASTE_END;

    const startTime = Date.now();

    const draftWriteFailure = draftPasteFailure('before-paste-write');
    if (draftWriteFailure) return draftWriteFailure;
    if (broadcastTabId) {
      recordComposerForensicPtyInput(broadcastTabId, payload, {
        kind: 'programmatic-paste',
        phase: 'pty-write-attempt',
        origin: 'safe-paste',
        source,
        operationKind: sendOperationContext?.kind || 'safe-paste',
        handoffId,
        sendAttemptId,
        sendOperationKey,
        checkpoint: true,
      });
    }
    term.write(payload);
    pasteWritten = true;

    // Fast-mode: tiny tick every 10 chunks to prevent node-pty buffer flooding.
    // Slow-mode: nothing here — single chunk, post-write drain handled below.
    if (fast && i > 0 && i % 10 === 0) {
      await new Promise(r => setTimeout(r, 5));
    }

    renderTimes.push(Date.now() - startTime);
  }

  // Slow-mode: ONE waitForRender for the whole paste. This proves that Claude
  // produced a closed render frame after the bracketed write, but NOT that the
  // input is already final: current Claude versions can close `Pasting…`, paint
  // a temporary empty composer, and only then materialize the collapsed chip.
  // The semantic frame wait below owns the actual Enter boundary.
  if (!fast && skipRenderWait) {
    console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Paste render wait skipped — relying on PTY byte order + user_message audit');
  } else if (!fast) {
    const render = waitForRender(term, safetyTimeoutMs, logPrefix + ':paste');
    render.markWriteTime(); // baseline = post-write, not subscription-time
    const cancellationWait = broadcastTabId && handoffId
      ? agentSendCancellations.wait(broadcastTabId, handoffId, sendAttemptId)
      : null;
    const renderRaces = [render.then(value => ({ kind: 'render', value }))];
    if (cancellationWait) {
      renderRaces.push(cancellationWait.promise.then(value => ({ kind: 'cancel', value })));
    }
    if (sendOperationContext?.cancelPromise) {
      renderRaces.push(Promise.resolve(sendOperationContext.cancelPromise)
        .then(value => ({ kind: 'cancel', value })));
    }
    const renderOutcome = await Promise.race(renderRaces);
    cancellationWait?.dispose();
    if (renderOutcome.kind === 'cancel' && renderOutcome.value?.cancelled === true) {
      render.cancel?.();
      return cancelledSendResult('paste-render-wait');
    }
    const r = renderOutcome.value;
    console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Paste render: timedOut=' + r.timedOut + ' elapsed=' + (r.elapsedMs || 'n/a') + 'ms');
    if (r.timedOut) {
      console.error(logPrefix + ' [+' + (Date.now() - t0) + 'ms] ❌ Paste render timed out — aborting before submit');
      return {
        success: false,
        error: 'paste_render_timeout',
        submitted: false,
        pasteWritten,
        enterWritten: false,
        pasteRenderConfirmed: false,
        chunksTotal: chunks.length,
        renderTimeMs: renderTimes,
        submitKey: null,
      };
    }
    pasteRenderAck = r;
  }

  if (claudePasteReadyAttempt) {
    const semanticReady = await waitForClaudePasteReadyBeforeSubmit({
      tabId: broadcastTabId,
      term,
      attempt: claudePasteReadyAttempt,
      timeoutMs: safetyTimeoutMs,
      cancellationRequested: exactSendCancellationRequested,
    });
    console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [ClaudePasteReady]'
      + ' ready=' + !!semanticReady?.ready
      + ' form=' + (semanticReady?.proof?.form || '-')
      + ' frame=' + (semanticReady?.proof?.committedFrameGeneration ?? '-')
      + ' expectedImages=' + claudePasteReadyAttempt.expectedImageCount
      + ' observedImages=' + (semanticReady?.proof?.observedImageCount ?? '-')
      + ' reason=' + (semanticReady?.reason || semanticReady?.proof?.reason || semanticReady?.error || '-'));
    if (semanticReady?.ready !== true || !semanticReady.proof) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        pasteWritten,
        enterWritten: false,
        error: semanticReady?.error || 'claude_paste_not_ready_before_submit',
        reason: semanticReady?.reason || null,
        draftPreserved: true,
      };
    }
    claudePasteReadyProof = semanticReady.proof;
  }

  if (
    submit
    && handoffId
    && isHistoryComposerSource
    && agentSendTestFaultActive('hold-after-paste')
  ) {
    console.warn(logPrefix + ' [TestFault] hold-after-paste tab='
      + String(broadcastTabId || '').slice(-12)
      + ' handoff=' + handoffId
      + ' pasteWritten=' + pasteWritten);
    const cancellationWait = agentSendCancellations.wait(
      broadcastTabId,
      handoffId,
      sendAttemptId,
    );
    const cancellation = await cancellationWait.promise;
    cancellationWait.dispose();
    if (cancellation?.cancelled === true) {
      return cancelledSendResult('test-hold-after-paste');
    }
  }

  if (exactSendCancellationRequested()) {
    return cancelledSendResult('after-paste-before-enter');
  }

  if (submit && shouldVerifyCodexVisibleDraft && mainWindow && !mainWindow.isDestroyed()) {
    if (isCodexPasteSource && skipRenderWait) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexDraftGuard] after-paste UI guard skipped — Codex submit relies on ordered PTY write + rollout user_message audit');
    } else if (pasteRenderAck && pasteRenderAck.timedOut === false) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexDraftGuard] after-paste satisfied by main render ACK elapsed=' + (pasteRenderAck.elapsedMs || 'n/a') + 'ms');
    } else {
      const afterDraft = await requestTerminalCodexDraftState(
        mainWindow.webContents,
        broadcastTabId,
        'codex-pre-submit-after-paste',
        1400,
        {
          waitFor: true,
          waitTimeoutMs: 1200,
          mergeRendererPositive: true,
        },
      );
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexDraftGuard] after-paste success=' + !!afterDraft?.success
        + ' hasDraft=' + afterDraft?.hasDraft
        + ' source=' + (afterDraft?.source || '-')
        + ' timedOut=' + !!afterDraft?.timedOut
        + ' checks=' + (afterDraft?.checks ?? '-')
        + ' preview=' + JSON.stringify(String(afterDraft?.preview || '').slice(0, 120))
        + (afterDraft?.debug ? ' debug=' + JSON.stringify(String(afterDraft.debug).slice(0, 700)) : '')
        + (afterDraft?.error ? ' error=' + afterDraft.error : ''));
      if (!afterDraft?.success || afterDraft.hasDraft !== true) {
        const error = afterDraft?.hasDraft === false
          ? 'codex_paste_not_visible_before_submit'
          : 'codex_draft_state_unknown_after_paste';
        console.error(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexDraftGuard] ❌ refusing Enter error=' + error);
        return {
          success: false,
          error,
          submitted: false,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: null,
          codexDraftGuard: afterDraft || null,
        };
      }
    }
  }

  if (submit) {
    if (verifyClaudeVisibleDraftBeforePaste && broadcastTabId && claudeDraftGuardProof) {
      const mirror = getHeadlessTerminalMirror(broadcastTabId);
      const submitGeneration = validateClaudeComposerSubmitGeneration({
        proof: claudeDraftGuardProof,
        terminalMatches: terminals.get(broadcastTabId) === term,
        currentInputRevision: getTerminalInputRevision(broadcastTabId),
        currentRunSeq: Number(terminalCommandState.get(broadcastTabId)?.runSeq || 0),
        currentLifecycleGeneration: getTerminalLifecycleGeneration(broadcastTabId),
        currentMirrorGeneration: mirror?.generation || null,
      });
      if (!submitGeneration.valid) {
        console.warn(logPrefix + ' [ClaudeComposerWriteBoundary] refusing Enter reason='
          + submitGeneration.reason);
        return {
          success: false,
          error: submitGeneration.reason,
          submitted: false,
          pasteWritten,
          manualTakeover: true,
        };
      }
    } else if (
      verifyClaudeVisibleDraftBeforePaste
      && broadcastTabId
      && Number.isFinite(claudeDraftGuardInputRevision)
      && getTerminalInputRevision(broadcastTabId) !== claudeDraftGuardInputRevision
    ) {
      console.warn(logPrefix + ' [ClaudeComposerWriteBoundary] refusing Enter reason=input-changed-after-paste');
      return {
        success: false,
        error: 'claude_input_ownership_changed_after_paste',
        submitted: false,
        pasteWritten,
        manualTakeover: true,
      };
    }
    if (codexPtyAdmission) {
      const currentAdmission = revalidateCodexPtySubmitAdmission(codexPtyAdmission);
      if (!currentAdmission.valid) {
        console.warn(logPrefix + ' [CodexSubmissionAdmission] cancelled before Enter reason='
          + currentAdmission.reason);
        if (isPromptQueueAutomation) {
          return {
            success: false,
            accepted: false,
            deferred: true,
            error: 'codex_input_not_ready',
            detail: currentAdmission.reason,
            submitted: false,
            chunksTotal: chunks.length,
            renderTimeMs: renderTimes,
            submitKey: null,
          };
        }
        return {
          success: false,
          error: currentAdmission.reason,
          submitted: false,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: null,
        };
      }
    }
    if (claudePromptQueuePtyAdmission) {
      const currentAdmission = revalidateClaudePromptQueuePtyAdmission(claudePromptQueuePtyAdmission);
      if (!currentAdmission.valid) {
        console.warn(logPrefix + ' [ClaudeQueueAdmission] cancelled before Enter reason='
          + currentAdmission.reason);
        return {
          success: false,
          accepted: false,
          deferred: true,
          error: 'claude_input_not_ready',
          detail: currentAdmission.reason,
          submitted: false,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: null,
        };
      }
    }
    // Optional: Esc to dismiss Claude's slash-cmd autocomplete dropdown.
    // Without this, the next Enter hits an early-return in PromptInput.onSubmit
    // (suggestions.length > 0 guard) — user has to press any key to break the
    // prefix match before Enter works. With Esc → autocomplete:dismiss fires →
    // clearSuggestions() → next Enter submits cleanly.
    if (dismissAutocomplete) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Sending Esc (dismiss autocomplete)...');
      term.write('\x1b');
      if (!fast) {
        await drainPtyData(term, 50);
      } else {
        await new Promise(r => setTimeout(r, 10));
      }
    }

    // Stage paste audit BEFORE Enter. Claude consumes this via UserPromptSubmit
    // hook; Codex consumes the same shape from the next exact rollout user
    // carrier (normally event_msg/user_message, with response_item(role=user)
    // as the observed image-bearing Resume fallback).
    // Length + sha-prefix is enough to spot truncation/corruption without
    // writing the whole prompt to disk.
    if (broadcastTabId && isCodexPasteSource) {
      try {
        const expectedHash = pasteAuditHash(content);
        const sentAt = Date.now();
        stagedCodexAudit = {
          submitId: codexSubmitId
            || handoffId
            || ('codex-submit-' + sentAt + '-' + crypto.randomBytes(6).toString('hex')),
          handoffId: handoffId || null,
          sendAttemptId: sendAttemptId || null,
          sendOperationKey: sendOperationKey || null,
          source: source || null,
          expectedLen: content.length,
          expectedHash,
          expectedText: content,
          expectedImagePaths: (codexImagePasteSegments || [])
            .filter((segment) => segment?.kind === 'image' && typeof segment.text === 'string')
            .map((segment) => segment.text),
          expectedImageRefs: stagedCodexImageRefs.map((ref) => ({ ...ref })),
          imageRequestProjection: codexImageRequestProjection,
          headPreview: pasteAuditPreview(content),
          tailPreview: pasteAuditPreview(content, Math.max(0, content.length - 80)),
          sentAt,
          logPrefix,
          awaitUserMessage: !!awaitCodexUserMessageAudit,
          resolve: null,
          timer: null,
          callerTimedOut: false,
          callerTimedOutAt: null,
          finished: false,
          presentationSnapshot: normalizedPresentationSnapshot,
          historySessionId: presentationSnapshot?.historySessionId || null,
          preSubmitBoundary: durablePreSubmitBoundary
            || captureCodexPromptAuditBoundary(broadcastTabId, sentAt),
          submitWritten: false,
          enterRetryCount: 0,
          enterRunSeq: null,
          enterLifecycleGeneration: null,
          enterInputRevision: null,
          delayedStableSourceSubmit: null,
          actionAuthority: codexSubmitAuthority,
          actionAuthorityId: codexSubmitAuthority?.authorityId || null,
          queuedAtSubmit: queuedAtSubmit === true,
          // An atomic settings+prompt transaction owns the enclosing queue
          // slot. Keep that exact private operation for committed queue proof;
          // a different queued writer must still invalidate the proof.
          writeOperation: options.ptyWriteOwner?.active === true
            && ptyWriteOwners.get(term) === options.ptyWriteOwner
            && options.queueProofWriteOperation
            ? options.queueProofWriteOperation : sendOperationContext || null,
        };
        stagedCodexAudit.queueScreenBaseline = captureCodexQueuedMessageAuditBaseline(
          broadcastTabId,
          stagedCodexAudit,
        );
        enqueueCodexPasteAudit(broadcastTabId, stagedCodexAudit);
        const delayedStableSourceSubmit = armPendingCodexNativeRewindStableSourceSubmit(
          broadcastTabId,
          stagedCodexAudit,
        );
        if (delayedStableSourceSubmit.active) {
          if (delayedStableSourceSubmit.success !== true) {
            finishCodexPasteAudit(broadcastTabId, stagedCodexAudit, {
              success: false,
              error: delayedStableSourceSubmit.error
                || 'codex_stable_source_submit_not_durable',
              expectedLen: stagedCodexAudit.expectedLen,
              expectedHash: stagedCodexAudit.expectedHash,
            });
            console.warn(logPrefix + ' [CodexDelayedWriter] refusing Enter without durable'
              + ' stable-source submit proof error='
              + (delayedStableSourceSubmit.error || 'unknown'));
            return {
              success: false,
              error: delayedStableSourceSubmit.error
                || 'codex_stable_source_submit_not_durable',
              submitted: false,
              chunksTotal: chunks.length,
              renderTimeMs: renderTimes,
              submitKey: null,
            };
          }
          stagedCodexAudit.delayedStableSourceSubmit = delayedStableSourceSubmit;
          awaitCodexUserMessageAudit = true;
          armCodexDelayedWriterObserver(
            broadcastTabId,
            delayedStableSourceSubmit,
          );
          console.log(logPrefix + ' [CodexDelayedWriter] durable submit armed'
            + ' generation=' + delayedStableSourceSubmit.actionGeneration
            + ' source=' + String(delayedStableSourceSubmit.sourceSessionId).slice(0, 8)
            + ' submit=' + stagedCodexAudit.submitId);
        }
        console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexPasteAudit] staged source=' + (source || '-') + ' expectedLen=' + content.length + ' hash=' + expectedHash + ' await=' + !!awaitCodexUserMessageAudit + ' pending=' + getPendingCodexPasteAudits(broadcastTabId).length);
      } catch (e) {
        console.warn(logPrefix + ' [CodexPasteAudit] stage failed:', e.message);
      }
    } else if (isCodexPasteSource) {
      console.warn(logPrefix + ' [CodexPasteAudit] skipped: broadcastTab=' + (broadcastTabId || '-') + ' await=' + !!awaitCodexUserMessageAudit);
    } else if (shouldStageClaudeAudit) {
      try {
        const expectedHash = pasteAuditHash(content);
        // Ordered set, not a single slot: a second send must never replace or
        // fail an earlier pending expectation (tab-2004 class, Claude parity).
        // Staged only for calls that press Enter themselves: a paste-only call
        // would leave a dangling expectation that a later identical send's
        // record could be claimed by (oldest-first), stealing its confirmation.
        stagedClaudeAudit = {
          handoffId: handoffId || null,
          sendAttemptId: sendAttemptId || null,
          sendOperationKey: sendOperationKey || null,
          source: source || null,
          expectedLen: content.length,
          expectedHash,
          expectedText: content,
          headPreview: pasteAuditPreview(content),
          tailPreview: pasteAuditPreview(content, Math.max(0, content.length - 80)),
          sentAt: Date.now(),
          logPrefix,
          awaitUserMessage: !!awaitClaudeUserMessageAudit,
          resolve: null,
          timer: null,
          callerTimedOut: false,
          callerTimedOutAt: null,
          finished: false,
          submitWritten: false,
          result: null,
          presentationSnapshot: normalizedPresentationSnapshot,
          historySessionId: presentationSnapshot?.historySessionId || null,
          preSubmitBoundary: durablePreSubmitBoundary || claudeAuditBoundary,
          preSubmitRouteProof: claudeHookRouteProof?.bound === true
            ? {
                tabId: claudeHookRouteProof.tabId,
                pid: claudeHookRouteProof.pid,
                reason: claudeHookRouteProof.reason || null,
              }
            : null,
          freshHookRouteConfirmed: false,
          pasteReadyProof: claudePasteReadyProof,
          providerAcceptedText: null,
          providerAcceptedLen: null,
          providerAcceptedHash: null,
          enterRetryCount: 0,
          enterInputRevision: null,
          enterRunSeq: null,
          enterLifecycleGeneration: null,
          forensicEnterInputId: null,
          forensicEnterAt: null,
          postEnterForensicArtifactPromise: null,
          postEnterForensicArtifactPath: null,
          postEnterForensicDiscardRequested: false,
        };
        enqueueClaudePasteAudit(broadcastTabId, stagedClaudeAudit);
        const observer = await retainClaudePasteAuditTranscriptObserver(
          broadcastTabId,
          stagedClaudeAudit,
        );
        if (!observer.retained) {
          console.warn(logPrefix + ' [PasteAudit:Observer] not retained tab='
            + String(broadcastTabId).slice(-12)
            + ' handoff=' + (handoffId || '-')
            + ' reason=' + observer.reason);
        }
        console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [PasteAudit] staged handoff=' + (handoffId || '-') + ' source=' + (source || '-') + ' expectedLen=' + content.length + ' hash=' + expectedHash + ' await=' + !!awaitClaudeUserMessageAudit + ' pending=' + getPendingClaudePasteAudits(broadcastTabId).length);
      } catch (e) {
        console.warn(logPrefix + ' [PasteAudit] stage failed:', e.message);
      }
    }

    if (fast) {
      // Fast mode: fixed delay (Gemini/bash don't use Ink sync)
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Waiting 500ms before ' + resolvedSubmitLabel + ' (fast mode)...');
      await new Promise(r => setTimeout(r, 500));
    } else if (skipRenderWait) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Skipping pre-' + resolvedSubmitLabel + ' render drain');
    } else if (claudePasteReadyProof) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Semantic Claude paste proof owns pre-'
        + resolvedSubmitLabel + ' boundary form=' + claudePasteReadyProof.form
        + ' frame=' + claudePasteReadyProof.committedFrameGeneration);
    } else {
      // Slow mode: short drain for secondary React renders / re-layouts.
      // 50ms is enough because waitForRender already confirmed the primary
      // sync marker — this is just settling tail re-renders. Hard ceiling for
      // the same reason as the pre-paste drain above: if a submit lands while
      // the PTY is still streaming this debounce would never see 50ms of
      // silence; cap it so Enter isn't delayed for the rest of the turn.
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] Draining PTY before ' + resolvedSubmitLabel + ' (slow mode)...');
      await drainPtyData(term, 50, 600);
    }
    if (codexPtyAdmission) {
      const finalAdmission = revalidateCodexPtySubmitAdmission(codexPtyAdmission);
      if (!finalAdmission.valid) {
        console.warn(logPrefix + ' [CodexSubmissionAdmission] cancelled at Enter boundary reason='
          + finalAdmission.reason);
        if (isPromptQueueAutomation) {
          return {
            success: false,
            accepted: false,
            deferred: true,
            error: 'codex_input_not_ready',
            detail: finalAdmission.reason,
            submitted: false,
            chunksTotal: chunks.length,
            renderTimeMs: renderTimes,
            submitKey: null,
          };
        }
        return {
          success: false,
          error: finalAdmission.reason,
          submitted: false,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: null,
        };
      }
    }
    if (claudePromptQueuePtyAdmission) {
      const finalAdmission = revalidateClaudePromptQueuePtyAdmission(claudePromptQueuePtyAdmission);
      if (!finalAdmission.valid) {
        console.warn(logPrefix + ' [ClaudeQueueAdmission] cancelled at Enter boundary reason='
          + finalAdmission.reason);
        return {
          success: false,
          accepted: false,
          deferred: true,
          error: 'claude_input_not_ready',
          detail: finalAdmission.reason,
          submitted: false,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: null,
        };
      }
    }
    if (codexSubmitAuthority) {
      const exactReservation = codexSubmissionWatcher?.reservation || null;
      const currentDiscovery = codexWatchers.get(broadcastTabId) || null;
      const authorityAtEnter = validateMainCodexActionAuthority(codexSubmitAuthority, {
        phases: ['consumed'],
        profile: CODEX_ACTION_PROFILE_RESUMED_ACTIVE_SUBMIT,
        launchId: codexSubmissionWatcher.launchId,
        sourceSessionId: codexSubmissionWatcher.sessionId,
        target: codexSubmitAuthority.target,
      });
      if (!authorityAtEnter.valid
        || !currentDiscovery
        || currentDiscovery.provisionalSubmitReservation !== exactReservation
        || currentDiscovery.launchId !== codexSubmissionWatcher.launchId
        || currentDiscovery.sourceSessionId !== codexSubmissionWatcher.sessionId
        || exactReservation?.actionAuthority !== codexSubmitAuthority
        || stagedCodexAudit?.actionAuthority !== codexSubmitAuthority
        || stagedCodexAudit?.submitId !== exactReservation?.submitId
        || stagedCodexAudit?.expectedHash !== exactReservation?.expectedHash
        || Number(stagedCodexAudit?.expectedLen) !== Number(exactReservation?.expectedLen)) {
        if (codexSubmitAuthority.phase !== 'revoked') {
          transitionMainCodexActionAuthority(
            codexSubmitAuthority,
            'revoked',
            authorityAtEnter.reason || 'resume-submit-observer-or-audit-changed-before-enter',
          );
        }
        return {
          success: false,
          error: 'codex_submit_action_authority_revoked',
          authorityReason: authorityAtEnter.reason || 'resume-submit-observer-or-audit-changed-before-enter',
          submitted: false,
          pasteWritten,
        };
      }
    }
    if (stagedCodexAudit?.delayedStableSourceSubmit) {
      const written = markPendingCodexNativeRewindStableSourceSubmitWritten(
        broadcastTabId,
        stagedCodexAudit.delayedStableSourceSubmit,
      );
      if (written?.success !== true) {
        console.warn(logPrefix + ' [CodexDelayedWriter] refusing Enter because durable'
          + ' write boundary changed error=' + (written?.error || 'unknown'));
        return {
          success: false,
          error: written?.error || 'codex_stable_source_submit_write_not_durable',
          submitted: false,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: null,
        };
      }
      // The durable record is intentionally committed immediately before the
      // PTY write. From this point onward delivery is unknown until the exact
      // rollout user_message appears; never classify an exception as "not sent".
      stagedCodexAudit.submitWritten = true;
    }
    if (isCodexPasteSource && broadcastTabId && submitSequence !== '\t') {
      // Enter may materialize a fresh rollout or move the writer after Resume /
      // native Rewind. A ps/lsof observation that began before this boundary
      // must never publish after it, even if the temporary discovery intent has
      // already been cleared again (the null → generation → null ABA race).
      invalidateCodexWriterObservations(
        broadcastTabId,
        'submit-boundary:' + (source || 'codex'),
      );
    }
    if (verifyClaudeVisibleDraftBeforePaste && broadcastTabId && claudeDraftGuardProof) {
      const mirror = getHeadlessTerminalMirror(broadcastTabId);
      const finalSubmitGeneration = validateClaudeComposerSubmitGeneration({
        proof: claudeDraftGuardProof,
        terminalMatches: terminals.get(broadcastTabId) === term,
        currentInputRevision: getTerminalInputRevision(broadcastTabId),
        currentRunSeq: Number(terminalCommandState.get(broadcastTabId)?.runSeq || 0),
        currentLifecycleGeneration: getTerminalLifecycleGeneration(broadcastTabId),
        currentMirrorGeneration: mirror?.generation || null,
      });
      if (!finalSubmitGeneration.valid) {
        console.warn(logPrefix + ' [ClaudeComposerWriteBoundary] refusing final Enter reason='
          + finalSubmitGeneration.reason);
        return {
          success: false,
          error: finalSubmitGeneration.reason,
          submitted: false,
          pasteWritten,
          manualTakeover: true,
        };
      }
    }
    const startupEnterBoundary = startupPromptLease && broadcastTabId
      ? await verifyClaudeStartupCommandAtEnterBoundary({
        tabId: broadcastTabId,
        generation: startupPromptLease.generation,
        lease: startupPromptLease,
        term,
        command: content,
      })
      : validateStartupPromptLease(true);
    if (!startupEnterBoundary.valid) {
      console.warn(logPrefix + ' [StartupPromptLease] refusing Enter reason='
        + startupEnterBoundary.reason
        + ' proof=' + (startupEnterBoundary.proof?.proofOutcome || '-')
        + ' preview=' + JSON.stringify(
          String(startupEnterBoundary.proof?.preview || '').slice(0, 100),
        ));
      if (
        broadcastTabId
        && startupEnterBoundary.reason === 'claude-startup-command-not-proven-at-enter'
      ) {
        void captureAgentDraftForensicArtifact(
          broadcastTabId,
          'claude',
          startupEnterBoundary.proof || null,
          'claude-startup-command-not-proven-at-enter',
          {
            mode: 'startup-setting-before-enter',
            identityStable: true,
            command: content,
            source,
            startupGeneration: startupPromptLease?.generation || null,
            pasteWritten,
            enterWritten: false,
          },
        );
      }
      return {
        success: false,
        error: 'claude_prompt_not_stable',
        reason: startupEnterBoundary.reason,
        submitted: false,
        pasteWritten,
        enterWritten: false,
        startupPromptProof: startupEnterBoundary.proof || null,
      };
    }
    if (exactSendCancellationRequested()) {
      return cancelledSendResult('enter-boundary');
    }
    const e2eBeforeEnterIdentity = broadcastTabId ? {
      tabId: broadcastTabId,
      provider: isCodexPasteSource ? 'codex' : (!fast ? 'claude' : 'other'),
      source: String(source || 'unknown'),
      promptHash: pasteAuditHash(content),
      promptLength: content.length,
      terminalRunSeq: Number(terminalCommandState.get(broadcastTabId)?.runSeq || 0),
      inputRevision: getTerminalInputRevision(broadcastTabId),
      lifecycleGeneration: getTerminalLifecycleGeneration(broadcastTabId),
      ...(handoffId ? { handoffId } : {}),
      ...(sendAttemptId ? { sendAttemptId } : {}),
      ...(sendOperationKey ? { sendOperationKey } : {}),
    } : null;
    const e2eBeforeEnter = e2eBeforeEnterIdentity
      ? await aiBoundaryTestGate.waitIfArmed({
          kind: 'agent-before-enter',
          identity: e2eBeforeEnterIdentity,
        })
      : { claimed: false, reason: 'no-tab' };
    if (e2eBeforeEnter?.claimed === true) {
      console.warn('[E2E:Boundary] before-enter'
        + ' tab=' + String(broadcastTabId).slice(-12)
        + ' handoff=' + String(handoffId || '-').slice(0, 24)
        + ' pasteWritten=' + pasteWritten
        + ' enterWritten=false'
        + ' action=' + e2eBeforeEnter.action);
      if (e2eBeforeEnter.action === 'reject'
        || e2eBeforeEnter.state === 'cancelled') {
        aiBoundaryTestGate.complete({
          armId: e2eBeforeEnter.arm.armId,
          operationId: e2eBeforeEnter.arm.operationId,
          reason: 'rejected-before-enter',
          result: { pasteWritten, enterWritten: false },
        });
        return {
          success: false,
          error: 'e2e_before_enter_rejected',
          submitted: false,
          pasteWritten,
          handoffId: handoffId || null,
        };
      }
      const boundaryStillExact = terminals.get(broadcastTabId) === term
        && Number(terminalCommandState.get(broadcastTabId)?.runSeq || 0)
          === e2eBeforeEnterIdentity.terminalRunSeq
        && getTerminalInputRevision(broadcastTabId)
          === e2eBeforeEnterIdentity.inputRevision
        && getTerminalLifecycleGeneration(broadcastTabId)
          === e2eBeforeEnterIdentity.lifecycleGeneration
        && !exactSendCancellationRequested();
      if (!boundaryStillExact) {
        aiBoundaryTestGate.complete({
          armId: e2eBeforeEnter.arm.armId,
          operationId: e2eBeforeEnter.arm.operationId,
          reason: 'identity-changed-before-enter',
          result: { pasteWritten, enterWritten: false, success: false },
        });
        return {
          success: false,
          error: 'agent_send_boundary_identity_changed',
          submitted: false,
          pasteWritten,
          handoffId: handoffId || null,
        };
      }
    }
    if ((sendOperationKey && !sendAttemptId) || (!sendOperationKey && sendAttemptId)) {
      return {
        success: false,
        error: 'agent_send_durable_identity_incomplete',
        submitted: false,
        pasteWritten,
        handoffId: handoffId || null,
      };
    }
    if (sendOperationKey && sendAttemptId) {
      const armed = agentSendReceiptStore.markAttemptState(
        sendOperationKey,
        sendAttemptId,
        AGENT_SEND_DURABLE_STATES.ENTER_ARMED,
      );
      if (armed?.ok !== true) {
        console.warn('[AgentSendReceipt] refusing Enter without exact durable attempt'
          + ' operation=' + String(sendOperationKey).slice(0, 72)
          + ' attempt=' + String(sendAttemptId).slice(0, 12)
          + ' reason=' + (armed?.reason || 'unknown'));
        return {
          success: false,
          error: armed?.reason === 'stale-attempt'
            ? 'agent_send_stale_attempt'
            : 'agent_send_enter_not_durably_armed',
          submitted: false,
          pasteWritten,
          handoffId: handoffId || null,
        };
      }
    }
    if (broadcastTabId) {
      const forensicSubmitInput = recordComposerForensicPtyInput(
        broadcastTabId,
        submitSequence,
        {
          kind: submitSequence === '\r' || submitSequence === '\n'
            ? 'programmatic-enter'
            : 'programmatic-submit',
          phase: 'pty-write-attempt',
          origin: 'safe-paste',
          source,
          operationKind: sendOperationContext?.kind || 'safe-paste',
          handoffId,
          sendAttemptId,
          sendOperationKey,
          checkpoint: true,
        },
      );
      if (stagedClaudeAudit && forensicSubmitInput) {
        stagedClaudeAudit.forensicEnterInputId = forensicSubmitInput.id;
        stagedClaudeAudit.forensicEnterAt = forensicSubmitInput.at;
      }
    }
    try {
      if (!codexSubmitDropTestFault.consume(broadcastTabId, term, submitSequence, stagedCodexAudit, 'initial')) {
        term.write(submitSequence);
      }
    } catch (error) {
      if (sendOperationKey && sendAttemptId) {
        console.error('[AgentSendReceipt] Enter write threw after durable arm; delivery remains unknown'
          + ' operation=' + String(sendOperationKey).slice(0, 72)
          + ' attempt=' + String(sendAttemptId).slice(0, 12)
          + ' error=' + (error?.message || String(error)));
        return {
          success: null,
          accepted: true,
          submitted: null,
          status: AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN,
          deliveryUnknown: true,
          code: 'agent_send_enter_write_outcome_unknown',
          error: error?.message || String(error),
          pasteWritten,
          handoffId: handoffId || null,
          operationKey: sendOperationKey,
          attemptId: sendAttemptId,
        };
      }
      throw error;
    }
    if (stagedCodexAudit) {
      stagedCodexAudit.enterWrittenAt = Date.now();
      stagedCodexAudit.enterRunSeq = Number(
        terminalCommandState.get(broadcastTabId)?.runSeq || 0,
      );
      stagedCodexAudit.enterLifecycleGeneration = getTerminalLifecycleGeneration(
        broadcastTabId,
      );
      stagedCodexAudit.enterInputRevision = getTerminalInputRevision(broadcastTabId);
    }
    if (stagedClaudeAudit) {
      stagedClaudeAudit.enterWrittenAt = Date.now();
      stagedClaudeAudit.enterRunSeq = Number(
        terminalCommandState.get(broadcastTabId)?.runSeq || 0,
      );
      stagedClaudeAudit.enterLifecycleGeneration = getTerminalLifecycleGeneration(
        broadcastTabId,
      );
      stagedClaudeAudit.enterInputRevision = getTerminalInputRevision(broadcastTabId);
    }
    if (sendOperationKey && sendAttemptId) {
      const submittedReceipt = agentSendReceiptStore.settleAttempt(
        sendOperationKey,
        sendAttemptId,
        {
          success: null,
          accepted: true,
          submitted: true,
          status: AGENT_SEND_DURABLE_STATES.AUDIT_PENDING,
          auditPending: true,
          deliveryUnknown: false,
          code: 'agent_send_enter_written_audit_pending',
          operationKey: sendOperationKey,
          attemptId: sendAttemptId,
          tabId: broadcastTabId,
          handoffId: handoffId || null,
          promptHash: pasteAuditHash(content),
          transcriptBoundary: durablePreSubmitBoundary
            || stagedCodexAudit?.preSubmitBoundary
            || stagedClaudeAudit?.preSubmitBoundary
            || null,
        },
      );
      if (submittedReceipt?.ok !== true) {
        // Enter has physically crossed. Never report this as not-submitted:
        // the pre-Enter enter-armed record survives restart and reconciles to
        // delivery-unknown, so a retry cannot duplicate the prompt.
        console.error('[AgentSendReceipt] post-Enter settle failed; preserving enter-armed proof'
          + ' operation=' + String(sendOperationKey).slice(0, 72)
          + ' attempt=' + String(sendAttemptId).slice(0, 12)
          + ' reason=' + (submittedReceipt?.reason || 'unknown'));
      }
    }
    if (codexSubmissionWatcher?.reservation) {
      codexSubmissionWatcher.reservation.requiresUserMessageAudit = true;
      codexSubmissionWatcher.reservation.submitted = true;
      codexSubmissionWatcher.reservation.submittedAt = Date.now();
      codexSubmissionWatcher.reservation.enterWritten = true;
      codexSubmissionWatcher.reservation.enterWrittenAt = Date.now();
    }
    if (e2eBeforeEnter?.claimed === true) {
      aiBoundaryTestGate.complete({
        armId: e2eBeforeEnter.arm.armId,
        operationId: e2eBeforeEnter.arm.operationId,
        reason: 'enter-written',
        result: { pasteWritten: true, enterWritten: true },
      });
    }
    if (stagedCodexAudit) stagedCodexAudit.submitWritten = true;
    if (stagedClaudeAudit) stagedClaudeAudit.submitWritten = true;
    markActivePtySubmit(term, {
      identityPending: isCodexPasteSource
        && !!codexSubmissionWatcher
        && codexSubmissionWatcher.kind !== 'turn',
    });
    if (isCodexPasteSource && broadcastTabId && submitSequence !== '\t') {
      codexImageBindings.resetComposer(broadcastTabId);
    }
    if (codexPromptInFlightState && broadcastTabId) {
      markCodexPromptSubmitted(broadcastTabId, codexPromptInFlightState, resolvedSubmitLabel);
    }
    if (armPromptBoundaryOnSubmit && broadcastTabId) {
      armPromptBoundaryForSubmittedCommand(broadcastTabId, promptBoundaryReason || logPrefix);
    }
    console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] ✅ Sent ' + resolvedSubmitLabel + ' handoff=' + (handoffId || '-') + ' (total: ' + (Date.now() - t0) + 'ms)');
    // Physical paste ownership ends at Enter. The rollout/JSONL audit that
    // follows proves delivery identity, but it is not a paste and must not
    // keep model/effort controls or the terminal activity glyph in write-busy.
    emitBusy(false, 'confirming');
    if (isCodexPasteSource && broadcastTabId) {
      const receiveToEnterMs = Number.isFinite(requestReceivedAt)
        ? Math.max(0, nodePerformance.now() - requestReceivedAt)
        : null;
      console.warn('[CodexSubmitTiming] source=' + (source || 'safe-paste')
        + ' tab=' + String(broadcastTabId).slice(-12)
        + ' receiveToPtyEnterMs=' + (receiveToEnterMs === null ? 'na' : receiveToEnterMs.toFixed(1))
        + ' safePasteMs=' + (Date.now() - t0)
        + ' observer=' + (codexSubmissionWatcher?.kind || 'none'));
      void reconcileCodexWriterFromProcess(broadcastTabId, {
        reason: 'post-submit-observation:' + (source || 'safe-paste'),
        sender: mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
      }).catch((error) => {
        console.warn('[CodexSubmissionObservation] post-Enter reconcile failed tab='
          + String(broadcastTabId).slice(-12)
          + ' error=' + (error?.message || String(error)));
      });
    }

    if (stagedClaudeAudit && awaitClaudeUserMessageAudit && broadcastTabId) {
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [PasteAudit] waiting for Claude UserPromptSubmit audit timeout=' + claudeAuditTimeoutMs + 'ms hash=' + stagedClaudeAudit.expectedHash);
      let auditResult = await waitForClaudePasteAudit(broadcastTabId, stagedClaudeAudit, claudeAuditTimeoutMs);
      if (auditResult?.error === 'claude_user_message_audit_timeout') {
        auditResult = await inspectClaudePostEnterTimeoutAtWriteBoundary({
          tabId: broadcastTabId,
          term,
          audit: stagedClaudeAudit,
          timeoutResult: auditResult,
          expectedText: stagedClaudeAudit.expectedText || content,
        });
        if (auditResult?.retryRecommended === true) {
          const retryIdentityCurrent = terminals.get(broadcastTabId) === term
            && Number(terminalCommandState.get(broadcastTabId)?.runSeq || 0)
              === Number(stagedClaudeAudit.enterRunSeq || 0)
            && getTerminalLifecycleGeneration(broadcastTabId)
              === stagedClaudeAudit.enterLifecycleGeneration
            && getTerminalInputRevision(broadcastTabId)
              === Number(auditResult.retryInputRevision)
            && stagedClaudeAudit.finished !== true
            && stagedClaudeAudit.enterRetryCount === 0
            && !exactSendCancellationRequested()
            && aiStoppingTabs.get(broadcastTabId)?.toolType !== 'claude';
          if (retryIdentityCurrent) {
            stagedClaudeAudit.enterRetryCount = 1;
            stagedClaudeAudit.enterInputRevision = getTerminalInputRevision(broadcastTabId);
            const retryForensic = recordComposerForensicPtyInput(
              broadcastTabId,
              submitSequence,
              {
                kind: 'programmatic-enter-retry',
                phase: 'pty-write-attempt',
                origin: 'safe-paste',
                source,
                operationKind: sendOperationContext?.kind || 'safe-paste',
                handoffId,
                sendAttemptId,
                sendOperationKey,
                checkpoint: true,
              },
            );
            console.warn(logPrefix + ' [ClaudePasteAudit] retrying Enter once'
              + ' handoff=' + (handoffId || '-')
              + ' inputRevision=' + stagedClaudeAudit.enterInputRevision
              + ' proof=' + auditResult.retryReason);
            try {
              term.write(submitSequence);
            } catch (error) {
              auditResult = {
                ...auditResult,
                success: false,
                semanticStatus: 'unknown',
                lateReconciliationPending: true,
                retryRecommended: false,
                retryAttempted: true,
                error: 'claude_enter_retry_write_outcome_unknown',
                retryWriteError: error?.message || String(error),
              };
            }
            if (retryForensic) {
              stagedClaudeAudit.forensicRetryEnterInputId = retryForensic.id;
              stagedClaudeAudit.forensicRetryEnterAt = retryForensic.at;
            }
            if (auditResult?.error !== 'claude_enter_retry_write_outcome_unknown') {
              auditResult = await waitForClaudePasteAudit(
                broadcastTabId,
                stagedClaudeAudit,
                claudeAuditTimeoutMs,
              );
            }
            if (auditResult?.error === 'claude_user_message_audit_timeout') {
              auditResult = await inspectClaudePostEnterTimeoutAtWriteBoundary({
                tabId: broadcastTabId,
                term,
                audit: stagedClaudeAudit,
                timeoutResult: auditResult,
                expectedText: stagedClaudeAudit.expectedText || content,
              });
            }
          } else {
            auditResult = {
              ...auditResult,
              retryRecommended: false,
              retryReason: 'claude_retry_identity_changed',
            };
          }
        }
      }
      if (!auditResult || auditResult.success !== true) {
        console.error(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [PasteAudit] ❌ failed error=' + (auditResult?.error || 'unknown')
          + ' semantic=' + (auditResult?.semanticStatus || 'unknown')
          + ' submitted=true');
        return {
          ...(auditResult || {}),
          success: false,
          error: auditResult?.error || 'claude_user_message_audit_failed',
          submitted: true,
          pasteWritten: true,
          enterWritten: true,
          chunksTotal: chunks.length,
          renderTimeMs: renderTimes,
          submitKey: resolvedSubmitLabel,
          pasteAudit: auditResult || null,
          ...(auditResult?.deferUntilClaudeTurnIdle === true
            ? {
                __claudePostEnterDeferred: {
                  tabId: broadcastTabId,
                  audit: stagedClaudeAudit,
                  timeoutResult: auditResult,
                  expectedText: stagedClaudeAudit.expectedText || content,
                },
              }
            : {}),
        };
      }
      confirmedClaudeAuditResult = auditResult;
      console.log(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [PasteAudit] ✅ confirmed Claude user message len=' + auditResult.actualLen + ' hash=' + auditResult.actualHash);
    } else if (!isCodexPasteSource && awaitClaudeUserMessageAudit) {
      console.warn(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [PasteAudit] await requested but no Claude audit was staged broadcastTab=' + (broadcastTabId || '-'));
      return {
        success: false,
        error: 'claude_user_message_audit_not_staged',
        submitted: true,
        chunksTotal: chunks.length,
        renderTimeMs: renderTimes,
        submitKey: resolvedSubmitLabel,
      };
    }

    if (stagedCodexAudit && awaitCodexUserMessageAudit && broadcastTabId) {
      const deferred = {
        tabId: broadcastTabId, audit: stagedCodexAudit,
        timeoutMs: codexAuditTimeoutMs, logPrefix, startedAt: t0,
        baseResult: { success: true, submitted: submit, chunksTotal: chunks.length,
          renderTimeMs: renderTimes, submitKey: resolvedSubmitLabel },
      };
      if (options.deferPostWriteResolution === true) {
        return { ...deferred.baseResult, __codexPostEnterDeferred: deferred };
      }
      return await finishCodexPasteAuditAfterWrite(term, deferred);
    } else if (source && String(source).startsWith('codex-') && awaitCodexUserMessageAudit) {
      console.warn(logPrefix + ' [+' + (Date.now() - t0) + 'ms] [CodexPasteAudit] await requested but no audit was staged broadcastTab=' + (broadcastTabId || '-') + ' hasWatcher=' + (broadcastTabId && typeof codexTurnWatchers !== 'undefined' ? codexTurnWatchers.has(broadcastTabId) : false));
      return {
        success: false,
        error: 'codex_user_message_audit_not_staged',
        submitted: true,
        chunksTotal: chunks.length,
        renderTimeMs: renderTimes,
        submitKey: resolvedSubmitLabel,
      };
    }
  }

  const draftReceiptFailure = draftPasteFailure('paste-receipt', false);
  if (draftReceiptFailure) return draftReceiptFailure;
  return {
    success: true,
    submitted: submit,
    ...(requiresClaudeDraftPasteAdmission ? { pasteWritten, enterWritten: false } : {}),
    chunksTotal: chunks.length,
    renderTimeMs: renderTimes,
    submitKey: submit ? resolvedSubmitLabel : null,
    ...(confirmedClaudeAuditResult ? { pasteAudit: confirmedClaudeAuditResult } : {}),
  };

  } finally {
    if (stagedCodexAudit
      && hasPendingCodexPasteAudit(broadcastTabId, stagedCodexAudit)
      && stagedCodexAudit.submitWritten !== true
      && (!codexPromptInFlightState || codexPromptInFlightState.submitted !== true)) {
      finishCodexPasteAudit(broadcastTabId, stagedCodexAudit, {
        success: false,
        error: 'codex_submit_not_sent',
        expectedLen: stagedCodexAudit.expectedLen,
        expectedHash: stagedCodexAudit.expectedHash,
      });
    }
    if (stagedCodexAudit?.delayedStableSourceSubmit
      && stagedCodexAudit.submitWritten !== true) {
      const released = releasePendingCodexNativeRewindStableSourceSubmit(
        broadcastTabId,
        stagedCodexAudit.delayedStableSourceSubmit,
      );
      if (released) {
        closeCodexDelayedWriterObserver(broadcastTabId, 'submit-not-written');
      }
    }
    // A staged Claude expectation whose Enter never reached the PTY (guard
    // refusal, render timeout, thrown error) must not linger in the ordered
    // set: an identical later send would otherwise be claimed by this dead
    // expectation (oldest-first) and the real delivery would stay pending.
    if (stagedClaudeAudit
      && stagedClaudeAudit.finished !== true
      && stagedClaudeAudit.submitWritten !== true) {
      finishClaudePasteAudit(broadcastTabId, stagedClaudeAudit, {
        success: false,
        error: 'claude_submit_not_sent',
        expectedLen: stagedClaudeAudit.expectedLen,
        expectedHash: stagedClaudeAudit.expectedHash,
      });
    }
    if (codexPromptInFlightState && broadcastTabId && !codexPromptInFlightState.submitted) {
      clearCodexPromptInFlight(broadcastTabId, 'submit-not-sent');
    }
    if (codexSubmissionWatcher?.reservation
      && codexSubmissionWatcher.reservation.enterWritten !== true) {
      releaseCodexProvisionalSubmitReservation(
        broadcastTabId,
        codexSubmissionWatcher.reservation,
        'safe-paste-submit-not-sent',
      );
    }
    if (codexSubmitAuthority
      && codexSubmitAuthority.phase !== 'committed'
      && codexSubmitAuthority.phase !== 'revoked'
      && codexSubmissionWatcher?.reservation?.enterWritten !== true) {
      transitionMainCodexActionAuthority(
        codexSubmitAuthority,
        'revoked',
        'safe-paste-submit-not-sent',
      );
    }
    if (
      responsePreflight
      && responseActivityPreflights.get(broadcastTabId) === responsePreflight
    ) {
      responseActivityPreflights.delete(broadcastTabId);
    }
    if (autoDurableAttempt) {
      const durable = agentSendReceiptStore.get(autoDurableAttempt.operationKey);
      if (
        durable?.attemptId === autoDurableAttempt.attemptId
        && durable.state === AGENT_SEND_DURABLE_STATES.IN_FLIGHT
      ) {
        agentSendReceiptStore.settleAttempt(
          autoDurableAttempt.operationKey,
          autoDurableAttempt.attemptId,
          {
            success: false,
            accepted: false,
            submitted: false,
            status: AGENT_SEND_DURABLE_STATES.NOT_SUBMITTED,
            code: 'agent_send_stopped_before_enter',
            operationKey: autoDurableAttempt.operationKey,
            attemptId: autoDurableAttempt.attemptId,
            tabId: broadcastTabId,
            handoffId: handoffId || null,
          },
        );
      }
    }
    emitBusy(false, 'idle');
  }
}

// Send input to terminal
// Force command-started signal (for AI commands that bypass OSC 133 detection).
// Accepts legacy `tabId` string and `{ tabId, commandType, sessionId }`.
ipcMain.on('terminal:force-command-started', (event, payload) => {
  const request = payload && typeof payload === 'object' ? payload : { tabId: payload };
  const tabId = request.tabId;
  if (!tabId) return;
  if (request.commandType === 'claude' && request.sessionId) {
    const owner = getClaudeJsonlLiveOwner(request.sessionId, tabId);
    const ownPending = owner?.reason === 'pending-resume' && owner.tabId === tabId;
    if (owner && !ownPending) {
      console.warn('[Force Command Started] BLOCKED claude resume start tab=' + String(tabId).slice(-12)
        + ' session=' + String(request.sessionId).slice(0, 8)
        + ' ownerTab=' + String(owner.tabId || '').slice(-12)
        + ' reason=' + owner.reason);
      return;
    }
  }
  console.log('[Force Command Started] Tab:', tabId, 'commandType:', request.commandType || '-');
  clearClaudeEditableLastPrompt(tabId, 'force-command-started');
  clearAiStopping(tabId, 'command-started');
  clearCodexDescendantExitRecheck(tabId, 'force-command-started');
  const state = terminalCommandState.get(tabId) || { isRunning: false, lastCommand: null };
  state.isRunning = true;
  state.runSeq = Number(state.runSeq || 0) + 1;
  clearTerminalCommandOrigin(tabId, state, 'force-command-started');
  terminalCommandState.set(tabId, state);
  const commandType = resolveAiToolTypeForTab(tabId, request.commandType || null);
  if (commandType === 'codex') {
    rearmCodexProcessActionBoundary(tabId, 'force-command-started');
  }
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:command-started', { tabId, commandType: commandType || null });
  }
  if (commandType === 'claude' || commandType === 'codex') {
    // Renderer knows the requested Resume target, not the rollout currently
    // opened by Codex. Accept that ID for Claude's established contract only;
    // Codex live identity comes exclusively from main's process/file proof.
    const sessionId = commandType === 'codex'
      ? getCodexRuntimeSessionId(tabId)
      : (request.sessionId || bridgeKnownSessions.get(tabId) || null);
    if (commandType === 'claude') {
      claudeStartupIntents.set(tabId, { sessionId, at: Date.now(), reason: 'force-command-started' });
      if (sessionId) {
        markClaudePendingJsonlOwner(sessionId, tabId, 'force-command-started');
      }
    }
    _webBroadcast(tabId, {
      type: 'snapshot',
      sessionId,
      busy: false,
      sessionStatus: 'starting',
      starting: true,
      inputReady: false,
      toolType: commandType,
      commandType,
      ...(commandType === 'codex' ? getCodexPublicWriterFields(tabId) : {}),
    });
  }
});

// Renderer log forwarding → file logger
ipcMain.on('log:renderer', (event, payload) => {
  if (payload && typeof payload === 'object' && typeof payload.msg === 'string') {
    const mainAbs = nodePerformance.timeOrigin + nodePerformance.now();
    const emitAbs = Number(payload.emitAbs);
    const fileLagMs = Number.isFinite(emitAbs) ? mainAbs - emitAbs : NaN;
    console.log(
      '[R] [RendererLogMeta]' +
      ' rseq=' + (payload.seq || 'na') +
      ' rboot=' + (payload.boot || 'na') +
      ' emitAbs=' + (Number.isFinite(emitAbs) ? emitAbs.toFixed(1) : 'na') +
      ' emitIso=' + (payload.emitIso || 'na') +
      ' fileLagMs=' + (Number.isFinite(fileLagMs) ? fileLagMs.toFixed(1) : 'na') +
      ' wc=' + event.sender.id +
      ' ' + payload.msg
    );
    return;
  }
  console.log('[R] [RendererLogMeta] legacy=1 wc=' + event.sender.id + ' ' + String(payload || ''));
});

const deferredTerminalInputOwnerIncidents = new WeakSet();

async function handleTerminalInput(
  event,
  tabId,
  data,
  meta = null,
  internal = null,
) {
  const inputReceivedAt = nodePerformance.now();
  const term = terminals.get(tabId);
  if (!term) {
    console.error('[main] Terminal not found for tabId:', tabId);
    return;
  }
  const xtermInputOrigin = meta && typeof meta === 'object'
    ? meta.xtermInputOrigin
    : null;
  const isTerminalProtocolResponse = xtermInputOrigin === 'terminal-response';
  const lateMcpInputDecision = classifyLateMcpProofInput({
    proofPending: codexLateMcpProofPending.has(tabId),
    xtermInputOrigin,
  });
  if (lateMcpInputDecision.cancelProof) {
    clearCodexLateMcpProofPending(
      tabId,
      lateMcpInputDecision.reason,
      { notifyReady: false, settlementAction: 'manual-input' },
    );
    console.log('[terminal:input] manual input yielded late MCP proof tab='
      + String(tabId).slice(-12)
      + ' origin=' + (xtermInputOrigin || 'unknown')
      + ' len=' + String(data || '').length);
  }
  const isManualCodexSubmit = (data === '\r' || data === '\n')
    && terminalCommandState.get(tabId)?.isRunning === true
    && (
      codexTuiReadyTabs.has(tabId)
      || codexWatchers.has(tabId)
      || codexTurnWatchers.has(tabId)
      || codexKnownSessions.has(tabId)
      || codexLastRunCommandPayload.has(tabId)
    );

  // The desktop stopping status is intentionally non-modal so scroll,
  // selection, and terminal inspection remain available. Raw keyboard input
  // must still stop at the authoritative process lifecycle boundary: otherwise
  // bytes typed while the agent exits can land in the shell that appears next.
  const stoppingState = aiStoppingTabs.get(tabId);
  if (stoppingState) {
    if (!stoppingState.inputBlockedLogged) {
      stoppingState.inputBlockedLogged = true;
      console.warn('[terminal:input] BLOCKED while agent stopping tab=' + String(tabId).slice(-12)
        + ' tool=' + (stoppingState.toolType || 'unknown')
        + ' reason=' + (stoppingState.reason || '-'));
    }
    return;
  }

  const precedingWriteOperation = ptyLastQueuedWriteOperation.get(term) || null;
  const activeWriteOperation = ptyActiveWriteOperation.get(term) || null;
  if (shouldSerializeManualPtyInput({
    alreadySerialized: internal?.afterPtyWriteQueue === true,
    isTerminalProtocolResponse,
    isManualCodexSubmit,
    activeOperation: activeWriteOperation,
    queuedOperation: precedingWriteOperation,
  })) {
    const manualOperation = {
      kind: 'manual-terminal-input',
      source: 'terminal:input',
      submitted: false,
      identityPending: false,
      queuedAt: Date.now(),
      terminalGeneration: getTerminalLifecycleGeneration(tabId),
      toolType: resolveAiToolTypeForTab(tabId),
    };
    await withPtyWriteLock(term, async () => {
      const boundary = classifyManualPtyInputAtBoundary({
        data,
        precedingOperation: precedingWriteOperation,
      });
      if (boundary.action === 'suppress') {
        console.warn('[PtyInputOwnership] manual input suppressed tab='
          + String(tabId).slice(-12)
          + ' reason=' + boundary.reason
          + ' preceding=' + (precedingWriteOperation?.source
            || precedingWriteOperation?.kind
            || 'none'));
        return;
      }
      // The queue belongs to the captured PTY, not whichever PTY later takes
      // this tabId. Keep native typeahead within that same physical terminal;
      // turn/run changes alone do not revoke ordinary raw keyboard input.
      if (terminals.get(tabId) !== term) {
        if (!deferredTerminalInputOwnerIncidents.has(term)) {
          deferredTerminalInputOwnerIncidents.add(term);
          console.warn('[PtyInputOwnership] queued input refused tab=' + String(tabId).slice(-12)
            + ' reason=raw-input-terminal-replaced oldPid=' + String(term.pid || '-')
            + ' currentPid=' + String(terminals.get(tabId)?.pid || '-')
            + ' bytes=' + Buffer.byteLength(String(data || ''), 'utf8'));
          if (manualOperation.toolType === 'claude' || manualOperation.toolType === 'codex') {
            try {
              void Promise.resolve(reportTerminalIncident('raw-input-owner:' + tabId + ':'
                + String(manualOperation.terminalGeneration || term.pid || manualOperation.queuedAt), {
                tabId, toolType: manualOperation.toolType,
                incidentReason: 'raw-input-terminal-replaced',
                context: { queuedAt: manualOperation.queuedAt,
                  originalPid: term.pid || null, currentPid: terminals.get(tabId)?.pid || null,
                  originalGeneration: manualOperation.terminalGeneration,
                  currentGeneration: getTerminalLifecycleGeneration(tabId),
                  inputBytes: Buffer.byteLength(String(data || ''), 'utf8'), written: false },
              })).catch(error => console.warn('[PtyInputOwnership] diagnostic failed: ' + String(error?.message || error)));
            } catch (error) {
              console.warn('[PtyInputOwnership] diagnostic failed: ' + String(error?.message || error));
            }
          }
        }
        return;
      }
      await handleTerminalInput(event, tabId, data, meta, {
        afterPtyWriteQueue: true,
      });
    }, manualOperation);
    return;
  }

  // Revisions describe bytes that actually reached the user's PTY boundary.
  // A key queued behind safePaste must not invalidate that paste before its
  // own byte is deliverable; doing so leaves pasted text unsubmitted and makes
  // Run After retry the same content.
  const deferManualInputRevision = isManualCodexSubmit
    && !!precedingWriteOperation
    && activeWriteOperation?.manualInputYields !== true;
  const inputRevisionBeforeCurrentInput = getTerminalInputRevision(tabId);
  if (!isTerminalProtocolResponse && !deferManualInputRevision) {
    bumpTerminalInputRevision(tabId);
    revokeCodexActionAuthoritiesForManualInput(tabId);
    if (!isPureCodexEscapeBurst(data)) codexManualQueueInterrupts.delete(tabId);
  }
  const inputMirror = getHeadlessTerminalMirror(tabId);
  if (inputMirror?.redrawTrace) {
    recordTerminalInput(inputMirror.redrawTrace, data, {
      revision: getTerminalInputRevision(tabId),
      origin: xtermInputOrigin || (isTerminalProtocolResponse ? 'terminal-response' : 'manual'),
    });
  }
  recordComposerForensicPtyInput(tabId, data, {
    phase: 'renderer-received',
    origin: xtermInputOrigin || (isTerminalProtocolResponse ? 'terminal-response' : 'manual'),
    source: 'terminal:input',
    operationKind: isTerminalProtocolResponse ? 'terminal-response' : 'manual-terminal-input',
    checkpoint: false,
  });

  // A manually adopted startup action must immediately yield ownership back
  // to the user. This also covers input that arrives while the process-tree
  // proof is still in flight, before the one-shot state has been armed.
  const startupPromptProbeActive = codexStartupPromptAdoptionProbeTabs.has(tabId);
  const startupPromptState = codexStartupAutoEnter.get(tabId);
  if (
    !isTerminalProtocolResponse
    && !deferManualInputRevision
    && (data === '\r' || data === '\n')
  ) {
    const migrationEnter = tryHandleManualCodexModelMigrationEnter(tabId, term, data, meta);
    if (migrationEnter.handled) {
      if (!migrationEnter.submitted) {
        console.warn('[CodexModelMigration] manual Enter not sent tab='
          + String(tabId).slice(-12)
          + ' error=' + (migrationEnter.error || 'unknown'));
      }
      return;
    }
  }
  if ((startupPromptProbeActive || startupPromptState) && isTerminalProtocolResponse) {
    console.log('[CodexStartupPrompt] ignored terminal protocol response tab=' + String(tabId).slice(-12)
      + ' phase=' + (startupPromptProbeActive ? 'adoption-probe' : (startupPromptState?.source || 'armed'))
      + ' len=' + String(data || '').length);
  } else if (startupPromptProbeActive || startupPromptState) {
    // Keep ownership sticky for this startup lifecycle. The user's arrow makes
    // Codex redraw the same picker; without the latch that redraw would be
    // adopted again and an automatic Enter could race the user's next key.
    codexStartupPromptManualOwnershipTabs.add(tabId);
    console.log('[CodexStartupPrompt] manual input owns startup picker tab=' + String(tabId).slice(-12)
      + ' phase=' + (startupPromptProbeActive ? 'adoption-probe' : (startupPromptState?.source || 'armed'))
      + ' origin=' + (xtermInputOrigin || 'direct-or-unknown'));
  }
  if (startupPromptState && !isTerminalProtocolResponse) {
    clearCodexStartupAutoEnter(tabId, 'manual-input-owns-startup-picker');
  }

  // Anti-arrow-mash guard. Catches the failure mode where xterm.js emits a
  // huge run of identical arrow escape codes (e.g. user's keyboard auto-repeat
  // got stuck holding Left Arrow, a Magic Mouse fingerprint glitch, an OS
  // accessibility helper, etc). On 2026-05-21 a 2265-byte burst of \x1b[D
  // landed mid-Claude-turn, corrupted the JSONL, and forced a full session
  // recovery. Real paste never looks like this — paste always contains
  // printable chars; long key-hold never targets a Claude TUI prompt
  // intentionally. Drop on the floor with a forensic log so we can audit.
  //
  // Criteria: data length >= 200 AND data is a uniform run of one of the
  // 4 arrow escape sequences (\x1b[A/B/C/D). Conservative — won't trip on
  // legitimate input.
  if (data.length >= 200 && /^(\x1b\[[ABCD])\1{60,}$/.test(data)) {
    const arrow = data.substring(0, 3);
    const arrowName = { '\x1b[A': 'UP', '\x1b[B': 'DOWN', '\x1b[C': 'RIGHT', '\x1b[D': 'LEFT' }[arrow] || '?';
    const count = Math.floor(data.length / 3);
    console.error('[terminal:input] BLOCKED arrow-mash: tab=' + tabId + ' len=' + data.length + ' arrow=' + arrowName + ' count=' + count + ' — dropping (xterm.js stuck keyboard / accessibility helper / glitch)');
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('arrow-mash:blocked', { count, arrowName });
    }
    return;
  }

  // Pure Esc (one byte `\x1b`) or Ctrl+C (`\x03`) → arm idle-probe safety net.
  // Multi-byte ESC sequences (стрелки `\x1b[A`, F-keys, `\x1bO...`) пропускаем —
  // они не означают interrupt. См. armInterruptIdleProbe выше для подробностей.
  const isPureEscapeBurst = isPureCodexEscapeBurst(data);
  if (isPureEscapeBurst || data === '\x03') {
    cancelCodexManualCompactPending(
      tabId,
      isPureEscapeBurst ? 'input-escape' : 'input-ctrl-c',
    );
    const codexSid = getCodexRuntimeSessionId(tabId);
    const rewindSource = isPureEscapeBurst
      ? resolveCodexNativeRewindSourceContext(tabId)
      : null;
    if (codexSid || rewindSource?.allowed === true) {
      const codexTurnState = codexTurnWatchers.get(tabId) || null;
      const commandState = terminalCommandState.get(tabId) || null;
      if (isPureEscapeBurst && !isTerminalProtocolResponse) {
        const continuation = captureManualCodexQueueInterrupt({
          data,
          turnBusy: codexTurnState?.busy === true,
          turnId: codexTurnState?.currentTurnId || null,
          pendingPrompt: codexTurnState?.terminalHistoryPreviewPendingPrompt || null,
          terminal: term,
          lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
          runSeq: Number(commandState?.runSeq || 0),
          promptGeneration: Number(codexPromptGeneration.get(tabId) || 0),
          inputRevision: getTerminalInputRevision(tabId),
        });
        if (continuation) {
          codexManualQueueInterrupts.set(tabId, continuation);
          console.warn('[CodexInterruptContinuation] armed tab=' + String(tabId).slice(-12)
            + ' turn=' + String(continuation.turnId).slice(-18)
            + ' promptSeq=' + continuation.promptGeneration
            + ' sourceSeq=' + continuation.sourceSequence);
        } else {
          codexManualQueueInterrupts.delete(tabId);
        }
      }
      console.warn(
        '[CodexInterruptInput]' +
        ' tab=' + String(tabId).slice(-12) +
        ' key=' + (isPureEscapeBurst ? 'Escape×' + data.length : 'Ctrl+C') +
        ' session=' + String(codexSid || rewindSource?.runtimeSourceSessionId || 'none').slice(0, 8) +
        ' sourceMode=' + (rewindSource?.mode || (codexSid ? 'public-writer' : 'none')) +
        ' turnBusy=' + (codexTurnState?.busy === true) +
        ' lastEvent=' + (codexTurnState?.lastEventType || 'none') +
        ' lastEventTs=' + (codexTurnState?.lastEventTs || 'none') +
        ' commandRunning=' + (commandState?.isRunning === true)
      );
      if (isPureEscapeBurst && codexTurnState?.busy !== true && commandState?.isRunning === true) {
        armCodexWriterHandoffObservation(
          tabId,
          'manual-idle-escape',
          { manualPhysicalRewind: true },
        );
      }
    }
    const claudeSid = bridgeKnownSessions.get(tabId) || null;
    if (claudeSid || findClaudePidByTab(tabId)) {
      const audits = getPendingClaudePasteAudits(tabId);
      const newestAudit = audits[audits.length - 1] || null;
      console.warn(
        '[ClaudeInterruptInput]' +
        ' tab=' + String(tabId).slice(-12) +
        ' key=' + (isPureEscapeBurst ? 'Escape×' + data.length : 'Ctrl+C') +
        ' session=' + String(claudeSid || 'none').slice(0, 8) +
        ' turnBusy=' + (claudeTurnBusy.get(tabId) === true) +
        ' spinnerBusy=' + (claudeSpinnerBusy.get(tabId) === true) +
        ' pendingAudits=' + audits.length +
        ' handoff=' + (newestAudit?.handoffId || '-') +
        ' auditAgeMs=' + (newestAudit ? Date.now() - newestAudit.sentAt : 0)
      );
    }
    cancelClaudeLocalCommandFromInput(tabId, data);
    if (claudeTurnBusy.get(tabId) === true) {
      armInterruptIdleProbe(tabId);
    }
  }

  trackManualCodexRewindNavigationInput(tabId, data, {
    isTerminalProtocolResponse,
    inputRevisionBefore: inputRevisionBeforeCurrentInput,
  });

// User paste (Cmd+V) — direct passthrough, no chunking needed.
  if (data.length > 1 || data === '\x1b' || data === '\x03') {
    const endsWithR = data.endsWith('\r');
    const endsWithN = data.endsWith('\n');
    const hasNewline = data.includes('\r') || data.includes('\n');
    // Sanitize content for logging: show printable chars, hex for control codes
    var inputPreview = '';
    for (var ci = 0; ci < Math.min(data.length, 60); ci++) {
      var cc = data.charCodeAt(ci);
      inputPreview += cc < 32 || cc === 127 ? '\\x' + cc.toString(16).padStart(2, '0') : data[ci];
    }
    console.log(`[terminal:input] tabId=${tabId} len=${data.length} endsWithR=${endsWithR} endsWithN=${endsWithN} hasNewline=${hasNewline} content="${inputPreview}"${data.length > 60 ? '...' : ''}`);
  }

  if (isManualCodexSubmit) {
    const manualRewind = await handleManualCodexRewindConfirmationEnter(tabId, term, data);
    if (manualRewind.handled) {
      if (!manualRewind.submitted) {
        console.warn('[CodexWriterHandoff] manual Rewind Enter not sent tab='
          + String(tabId).slice(-12)
          + ' error=' + (manualRewind.error || 'unknown'));
      }
      return;
    }
    const precedingOperation = ptyLastQueuedWriteOperation.get(term) || null;
    const activeOperation = ptyActiveWriteOperation.get(term) || null;
    const immediateArbitration = classifyManualCodexSubmitAfterWriteQueue({
      precedingOperation,
      activeOperation,
      competingReservation: codexWatchers.get(tabId)?.provisionalSubmitReservation || null,
    });
    if (immediateArbitration.bypassQueue) {
      activeOperation.manualTakeover = true;
      activeOperation.manualTakeoverAt = Date.now();
      const pickerEnter = tryHandleManualCodexActivePickerEnter(
        tabId,
        term,
        data,
        'manual-enter-ui-control-takeover',
        xtermInputOrigin,
      );
      if (pickerEnter.handled) return;
      const manualCodexCompactPreparation = trackCodexInputLineForCompact(
        tabId,
        data,
        { xtermInputOrigin, isTerminalProtocolResponse },
      );
      const manualCompactIntentPending = !!manualCodexCompactPreparation
        || !!compactOperations.getPending(tabId, 'codex');
      const manualEnterSubmitsPrompt = activeOperation.manualEnterSubmitsPrompt !== false;
      const composerState = getHeadlessCodexDraftState(
        tabId,
        'manual-enter-ui-control-takeover',
      );
      const composerKnown = manualEnterSubmitsPrompt
        && composerState?.success === true
        && (composerState.hasDraft === true || composerState.hasDraft === false);
      const promptInFlight = composerKnown && !manualCompactIntentPending
        ? beginCodexPromptInFlight(tabId, 'manual-terminal-enter', {
          source: 'manual-terminal-enter-ui-control-takeover',
        })
        : null;
      const stableSourceSubmit = manualEnterSubmitsPrompt && !manualCompactIntentPending
        ? prepareManualCodexStableSourceSubmit(tabId, {
          source: 'manual-terminal-enter-ui-control-takeover',
          composerState,
        })
        : { active: false, success: true };
      if (stableSourceSubmit.active && stableSourceSubmit.success !== true) {
        console.warn('[CodexDelayedWriter] physical Enter continues without attribution proof tab='
          + String(tabId).slice(-12)
          + ' source=manual-terminal-enter-ui-control-takeover'
          + ' error=' + (stableSourceSubmit.error || 'unknown'));
      }
      if (composerKnown) {
        queueTerminalCommandMeta(tabId, meta);
        captureTerminalInputForLastCommand(tabId, data);
      }
      let stableSourceWriteProven = false;
      try {
        if (stableSourceSubmit.active && stableSourceSubmit.success === true) {
          const written = markManualCodexStableSourceSubmitWritten(tabId, stableSourceSubmit);
          stableSourceWriteProven = written?.success === true;
          if (written?.success !== true) {
            console.warn('[CodexDelayedWriter] manual takeover Enter attribution held tab='
              + String(tabId).slice(-12)
              + ' error=' + (written?.error || 'unknown'));
          }
        }
        recordComposerForensicPtyInput(tabId, data, {
          phase: 'pty-write-attempt',
          origin: xtermInputOrigin || 'manual',
          source: 'manual-terminal-enter-ui-control-takeover',
          operationKind: activeOperation.kind || 'manual-terminal-input',
          checkpoint: true,
        });
        const nativeSettings = prepareCodexNativeSettingsIntentInput(tabId, term, data, xtermInputOrigin);
        term.write(data);
        markCodexNativeSettingsIntentInputWritten(tabId, nativeSettings);
        if (promptInFlight) {
          markCodexPromptSubmitted(tabId, promptInFlight, 'manual-enter-written');
        }
        activateCodexManualCompactAfterPtyWrite(manualCodexCompactPreparation);
      } catch (error) {
        if (promptInFlight) clearCodexPromptInFlight(tabId, 'manual-write-failed');
        throw error;
      }
      console.warn('[CodexSubmitTiming] source=manual-terminal-enter-ui-control-takeover'
        + ' tab=' + String(tabId).slice(-12)
        + ' receiveToPtyWriteMs=' + (nodePerformance.now() - inputReceivedAt).toFixed(1)
        + ' operation=' + (activeOperation.kind || '-')
        + ' operationPhase=' + (activeOperation.phase || '-')
        + ' promptSubmit=' + manualEnterSubmitsPrompt
        + ' composerKnown=' + composerKnown
        + ' stableSourceProof=' + stableSourceWriteProven
        + ' draftSource=' + (composerState?.source || '-'));
      if (composerKnown) {
        void ensureCodexSubmissionWatcher(
          tabId,
          terminalProjects.get(tabId),
          'manual-terminal-enter-ui-control-takeover-post-write',
        ).catch((error) => {
          console.warn('[Codex Watcher] immediate manual Enter observer failed tab='
            + String(tabId).slice(-12)
            + ' error=' + (error?.message || String(error)));
        });
      }
      return;
    }
    const manualOperation = {
      kind: 'manual-codex-enter',
      source: 'manual-terminal-enter',
      submitted: false,
      identityPending: !getCodexWriterProofSnapshot(tabId)
        || codexWatchers.has(tabId)
        || codexLastRunCommandPayload.has(tabId),
      queuedAt: Date.now(),
    };
    await withPtyWriteLock(term, async () => {
      // The PTY write boundary is the only synchronous admission gate for a
      // physical user key. Process/lsof/session reconciliation is observation,
      // not permission to press Enter, and may take seconds on a loaded Mac.
      // It is armed after the byte is written and can only affect attribution,
      // never delivery of this user action.
      const boundaryArbitration = classifyManualCodexSubmitAfterWriteQueue({
        precedingOperation,
        activeOperation: ptyActiveWriteOperation.get(term) || null,
        competingReservation: codexWatchers.get(tabId)?.provisionalSubmitReservation || null,
      });
      if (boundaryArbitration.suppress) {
        console.warn('[CodexSubmitArbitration] manual Enter suppressed tab=' + String(tabId).slice(-12)
          + ' reason=' + boundaryArbitration.reason
          + ' priorSource=' + (precedingOperation?.source || '-')
          + ' receiveToDecisionMs=' + (nodePerformance.now() - inputReceivedAt).toFixed(1));
        return;
      }
      if (deferManualInputRevision) {
        bumpTerminalInputRevision(tabId);
      }
      if (deferManualInputRevision) {
        const migrationEnter = tryHandleManualCodexModelMigrationEnter(
          tabId,
          term,
          data,
          meta,
        );
        if (migrationEnter.handled) return;
      }
      const pickerEnter = tryHandleManualCodexActivePickerEnter(
        tabId,
        term,
        data,
        'manual-enter-write-boundary',
        xtermInputOrigin,
      );
      if (pickerEnter.handled) return;

      const manualCodexCompactPreparation = trackCodexInputLineForCompact(
        tabId,
        data,
        { xtermInputOrigin, isTerminalProtocolResponse },
      );

      // Exact manual /compact owns a separate invisible intent until rollout
      // task_started. Do not manufacture generic prompt/SENT activity while
      // the first Enter may merely be choosing the slash suggestion.
      const manualCompactIntentPending = !!manualCodexCompactPreparation
        || !!compactOperations.getPending(tabId, 'codex');
      const stableSourceJournal = readPendingCodexNativeRewindHandoff(tabId);
      const stableSourceComposerState = !manualCompactIntentPending
        && stableSourceJournal?.invalid !== true
        && isCodexRewindDraftSubmitPhase(stableSourceJournal?.phase)
        ? getHeadlessCodexDraftState(tabId, 'manual-stable-source-enter-boundary')
        : null;
      const stableSourceSubmit = prepareManualCodexStableSourceSubmit(tabId, {
        source: 'manual-terminal-enter',
        composerState: stableSourceComposerState,
      });
      if (stableSourceSubmit.active && stableSourceSubmit.success !== true) {
        console.warn('[CodexDelayedWriter] physical Enter continues without attribution proof tab='
          + String(tabId).slice(-12)
          + ' source=manual-terminal-enter'
          + ' error=' + (stableSourceSubmit.error || 'unknown'));
      }
      const promptInFlight = manualCompactIntentPending
        ? null
        : beginCodexPromptInFlight(tabId, 'manual-terminal-enter', {
          source: 'manual-terminal-enter',
        });

      queueTerminalCommandMeta(tabId, meta);
      captureTerminalInputForLastCommand(tabId, data);
      const codexImageStageToken = meta && typeof meta.codexImageStageToken === 'string'
        ? meta.codexImageStageToken
        : null;
      if (codexImageStageToken) {
        const began = codexImageBindings.begin(tabId, codexImageStageToken);
        console.log('[CodexImageBinding] tab=' + String(tabId).slice(-12)
          + ' begin=' + began + ' token=' + codexImageStageToken.slice(-12));
      }
      let stableSourceWriteProven = false;
      try {
        if (stableSourceSubmit.active && stableSourceSubmit.success === true) {
          const written = markManualCodexStableSourceSubmitWritten(tabId, stableSourceSubmit);
          stableSourceWriteProven = written?.success === true;
          if (written?.success !== true) {
            console.warn('[CodexDelayedWriter] manual Enter attribution held tab='
              + String(tabId).slice(-12)
              + ' error=' + (written?.error || 'unknown'));
          }
        }
        recordComposerForensicPtyInput(tabId, data, {
          phase: 'pty-write-attempt',
          origin: xtermInputOrigin || 'manual',
          source: 'manual-terminal-enter',
          operationKind: manualOperation.kind,
          checkpoint: true,
        });
        const nativeSettings = prepareCodexNativeSettingsIntentInput(tabId, term, data, xtermInputOrigin);
        term.write(data);
        markCodexNativeSettingsIntentInputWritten(tabId, nativeSettings);
        markActivePtySubmit(term, { identityPending: manualOperation.identityPending });
        if (promptInFlight) {
          markCodexPromptSubmitted(tabId, promptInFlight, 'manual-enter-written');
        }
        activateCodexManualCompactAfterPtyWrite(manualCodexCompactPreparation);
      } catch (error) {
        clearCodexPromptInFlight(tabId, 'manual-write-failed');
        throw error;
      }
      codexImageBindings.handleTerminalInput(tabId, data);
      console.warn('[CodexSubmitTiming] source=manual-terminal-enter tab=' + String(tabId).slice(-12)
        + ' receiveToPtyWriteMs=' + (nodePerformance.now() - inputReceivedAt).toFixed(1)
        + ' writeQueueMs=' + Math.max(0, Date.now() - manualOperation.queuedAt)
        + ' preceding=' + (precedingOperation?.source || precedingOperation?.kind || 'none')
        + ' stableSourceProof=' + stableSourceWriteProven
        + ' identityPending=' + manualOperation.identityPending);

      // Observation deliberately starts after term.write. Launch-time
      // discovery/turn watchers normally already exist; this background call
      // only heals an expired observer and adopts the post-Enter writer.
      void ensureCodexSubmissionWatcher(
        tabId,
        terminalProjects.get(tabId),
        'manual-terminal-enter-post-write',
      ).then((observer) => {
        if (!observer?.available) {
          console.warn('[Codex Watcher] manual Enter delivered; post-write observer unresolved tab='
            + String(tabId).slice(-12)
            + ' status=' + (observer?.writerStatus || 'unknown'));
        }
      }).catch((error) => {
        console.warn('[Codex Watcher] manual Enter delivered; post-write observer failed tab='
          + String(tabId).slice(-12)
          + ' error=' + (error?.message || String(error)));
      });
    }, manualOperation);
    return;
  }

  // Last-line defense for direct renderer/manual resume paths. Some surfaces
  // write `claude --resume <sid>` straight through terminal:input instead of
  // going through `claude:run-command` / `claude:repair-jsonl-before-resume`.
  // Tail-trim is safe only before a new Claude process starts; if a Claude child
  // is currently alive in this tab, skip rather than touching a file it may own.
  try {
    const resumeCommand = !isTerminalProtocolResponse
      ? classifyClaudeResumeShellInput({
          pendingLine: terminalInputLineBuffers.get(tabId) || '',
          data,
          commandRunning: terminalCommandState.get(tabId)?.isRunning === true,
          liveRuntimeOwners: getLiveAiRuntimeOwners(tabId).length,
        })
      : { matched: false, reason: 'terminal-protocol-response' };
    if (resumeCommand.matched) {
      const resumeSessionId = resumeCommand.sessionId;
      const liveOwner = getClaudeJsonlLiveOwner(resumeSessionId, tabId)
        || await getClaudeJsonlExternalOwner(resumeSessionId, terminalProjects.get(tabId));
      if (liveOwner) {
        console.warn('[terminal:input] BLOCKED duplicate claude resume session=' + resumeSessionId.slice(0, 8) +
          ' tab=' + String(tabId).slice(-12) +
          ' ownerTab=' + String(liveOwner.tabId || '').slice(-12) +
          ' reason=' + liveOwner.reason);
        return;
      }
      const r = trimTrailingEffortEntries(resumeSessionId, terminalProjects.get(tabId));
      if (r?.trimmed > 0) {
        console.log('[terminal:input] pre-resume trimmed ' + r.trimmed +
          ' trailing startup slash line(s) session=' + resumeSessionId.slice(0, 8) +
          ' (model=' + (r.model || 0) + ', effort=' + (r.effort || 0) + ')');
      }
      if (!markClaudePendingJsonlOwner(resumeSessionId, tabId, 'terminal-input-resume')) {
        console.warn('[terminal:input] BLOCKED claude resume pending-lock session=' + resumeSessionId.slice(0, 8) +
          ' tab=' + String(tabId).slice(-12));
        return;
      }
    }
  } catch (e) {
    console.warn('[terminal:input] pre-resume startup slash trim failed (non-fatal): ' + (e?.message || String(e)));
  }

  // Capture the transcript boundary before Enter, but keep the observation
  // inert until this exact input burst has crossed the PTY write boundary.
  // This mirrors programmatic /compact submission and prevents an intercepted
  // or failed Enter from publishing a command that never started.
  const manualClaudeLocalCommandPreparation = trackClaudeInputLineForLocalCommands(
    tabId,
    data,
    { isTerminalProtocolResponse },
  );
  trackCodexInputLineForCompact(
    tabId,
    data,
    { xtermInputOrigin, isTerminalProtocolResponse },
  );

  queueTerminalCommandMeta(tabId, meta);
  captureTerminalInputForLastCommand(tabId, data);

  // ========== GEMINI INPUT STATE TRACKING ==========
  // Track character count in Gemini input field for response queue system.
  // Uses counter (not boolean) to correctly handle backspace → auto-deliver when empty.
  if (geminiActiveTabs.has(tabId)) {
    const count = geminiInputCharCount.get(tabId) || 0;

    if (data === '\r' || data === '\x03') {
      // Enter or Ctrl+C → input submitted/cleared → reset counter
      updateGeminiCharCount(tabId, 0, 'submit/cancel');
    } else if (data === '\x7f' || data === '\x08') {
      // Backspace (DEL) or BS → decrement counter
      updateGeminiCharCount(tabId, count - 1, 'backspace');
    } else if (data === '\x15') {
      // Ctrl+U (kill line) → clear all
      updateGeminiCharCount(tabId, 0, 'kill-line');
    } else if (data === '\x1b' || (data.length >= 2 && data.startsWith('\x1b['))) {
      // Escape or escape sequence (arrow keys, etc.) — don't change state
    } else if (data.length === 1 && data.charCodeAt(0) >= 32) {
      // Printable character → increment counter
      updateGeminiCharCount(tabId, count + 1, 'typing');
    } else if (data.length > 1 && !data.startsWith('\x1b')) {
      // Multi-char paste (not escape sequence) → add paste length
      updateGeminiCharCount(tabId, count + data.length, 'paste');
    }
  }
  // ========== END GEMINI INPUT STATE TRACKING ==========

  // === [PasteDiag] Detailed paste diagnostics for >1KB input ===
  // No rerouting — we just pass the bytes through to term.write() exactly like
  // iTerm2 does. The diagnostics tell us, on the next paste race, what state
  // Claude TUI saw: whether xterm.js wrapped this in \x1b[200~ at all, how many
  // bracket markers ended up inside (e.g. partial earlier paste leaking out),
  // and how many \r bytes are embedded (each one is a potential Enter submit
  // inside a non-bracketed long paste). Goes to a single [PasteDiag] line that
  // dev.log dedupe groups cleanly.
  if (data.length > 1000) {
    const startsWithB = data.startsWith('\x1b[200~');
    const endsWithB = data.endsWith('\x1b[201~');
    let startCount = 0, endCount = 0, crCount = 0, lfCount = 0;
    for (let pdi = 0; pdi < data.length; pdi++) {
      const cc = data.charCodeAt(pdi);
      if (cc === 13) crCount++;
      else if (cc === 10) lfCount++;
      else if (cc === 27 && pdi + 5 < data.length) {
        // Cheap escape check: \x1b[200~ or \x1b[201~
        if (data.charCodeAt(pdi + 1) === 91 /* [ */ &&
            data.charCodeAt(pdi + 2) === 50 /* 2 */ &&
            data.charCodeAt(pdi + 3) === 48 /* 0 */ &&
            data.charCodeAt(pdi + 5) === 126 /* ~ */) {
          const fourth = data.charCodeAt(pdi + 4);
          if (fourth === 48) startCount++; // 0
          else if (fourth === 49) endCount++; // 1
        }
      }
    }
    const head = [];
    for (let hi = 0; hi < Math.min(40, data.length); hi++) {
      const cc = data.charCodeAt(hi);
      head.push(cc < 32 || cc === 127 ? 'x' + cc.toString(16) : data[hi]);
    }
    const tail = [];
    for (let ti = Math.max(0, data.length - 40); ti < data.length; ti++) {
      const cc = data.charCodeAt(ti);
      tail.push(cc < 32 || cc === 127 ? 'x' + cc.toString(16) : data[ti]);
    }
    console.log('[PasteDiag] tab=' + tabId + ' len=' + data.length
      + ' startsWith200=' + startsWithB + ' endsWith201=' + endsWithB
      + ' embed200=' + startCount + ' embed201=' + endCount
      + ' cr=' + crCount + ' lf=' + lfCount
      + ' head=[' + head.join('') + ']'
      + ' tail=[' + tail.join('') + ']');
  }

  // Pass-through. iTerm2 and friends do exactly this. If Claude TUI has bracketed
  // paste mode enabled (DEC 2004), it sees \x1b[200~...\x1b[201~ around the
  // payload and produces ONE [Pasted text #N] chip regardless of how the kernel
  // chunked the bytes. If DEC 2004 is OFF on Claude's side at the moment of
  // paste, that's a Claude TUI quirk we don't paper over here — it's the same
  // behavior the user would see in iTerm2 / Terminal.app.
  const codexImageStageToken = meta && typeof meta.codexImageStageToken === 'string'
    ? meta.codexImageStageToken
    : null;
  if (codexImageStageToken) {
    const began = codexImageBindings.begin(tabId, codexImageStageToken);
    console.log('[CodexImageBinding] tab=' + String(tabId).slice(-12)
      + ' begin=' + began + ' token=' + codexImageStageToken.slice(-12));
  }
  try {
    recordComposerForensicPtyInput(tabId, data, {
      phase: 'pty-write-attempt',
      origin: xtermInputOrigin || (isTerminalProtocolResponse ? 'terminal-response' : 'manual'),
      source: 'terminal:input',
      operationKind: isTerminalProtocolResponse ? 'terminal-response' : 'manual-terminal-input',
      checkpoint: data === '\r' || data === '\n',
    });
    const nativeSettings = prepareCodexNativeSettingsIntentInput(tabId, term, data, xtermInputOrigin);
    term.write(data);
    markCodexNativeSettingsIntentInputWritten(tabId, nativeSettings);
    activateClaudeLocalCommandWatcher(manualClaudeLocalCommandPreparation);
  } catch (error) {
    discardClaudeLocalCommandWatcherPreparation(
      manualClaudeLocalCommandPreparation,
      'terminal-input-write-failed',
    );
    throw error;
  }
  codexImageBindings.handleTerminalInput(tabId, data);
}

ipcMain.on('terminal:input', handleTerminalInput);

function resolveAgentSendCancellationAttempt(tabId, handoffId, requestedAttemptId) {
  const requested = typeof requestedAttemptId === 'string' && requestedAttemptId.trim()
    ? requestedAttemptId.trim()
    : null;
  const durableRecords = tabId && handoffId
    ? agentSendReceiptStore.list({ tabId }).filter((record) => record.handoffId === handoffId)
    : [];
  if (requested || durableRecords.length === 0) {
    return { accepted: true, attemptId: requested, durableRecords };
  }
  // Desktop History creates a fresh handoff UUID for every click. Before the
  // async send result returns, Stop knows that exact handoff but cannot yet
  // know the main-generated attempt UUID. Resolving the sole current desktop
  // receipt is therefore exact; API/orchestration surfaces and ambiguous rows
  // still require their explicit attempt identity.
  if (
    durableRecords.length === 1
    && durableRecords[0].surface === DESKTOP_HISTORY_SEND_SURFACE
    && durableRecords[0].attemptId
  ) {
    return {
      accepted: true,
      attemptId: durableRecords[0].attemptId,
      durableRecords,
      resolvedFromDesktopHandoff: true,
    };
  }
  return { accepted: false, attemptId: null, durableRecords };
}

ipcMain.handle('agent:cancel-send', (_event, { tabId, handoffId, sendAttemptId = null } = {}) => {
  const resolved = resolveAgentSendCancellationAttempt(tabId, handoffId, sendAttemptId);
  const durableAttemptId = resolved.attemptId;
  if (!resolved.accepted) {
    console.warn('[AgentSendCancel] reject ambiguous durable cancellation tab='
      + String(tabId || '').slice(-12)
      + ' handoff=' + String(handoffId || '-')
      + ' reason=send-attempt-required');
    return {
      cancelled: false,
      reason: 'send-attempt-required',
      currentAttemptId: resolved.durableRecords
        .sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0))[0]?.attemptId
        || null,
    };
  }
  const result = agentSendCancellations.cancel(tabId, handoffId, {
    attemptId: durableAttemptId,
  });
  console.warn('[AgentSendCancel] request tab=' + String(tabId || '').slice(-12)
    + ' handoff=' + String(handoffId || '-')
    + ' cancelled=' + result.cancelled
    + ' deduped=' + !!result.deduped
    + ' attempt=' + String(result.attemptId || '-').slice(0, 12)
    + ' reason=' + (result.reason || '-'));
  return result;
});

ipcMain.handle('agent:clear-send-cancel', (_event, { tabId, handoffId, sendAttemptId = null } = {}) => {
  const resolved = resolveAgentSendCancellationAttempt(tabId, handoffId, sendAttemptId);
  const durableAttemptId = resolved.attemptId;
  if (!resolved.accepted) {
    return { success: false, cleared: false, reason: 'send-attempt-required' };
  }
  return {
    success: true,
    cleared: agentSendCancellations.clear(tabId, handoffId, durableAttemptId),
  };
});

ipcMain.handle('agent:get-send-activity', () => agentSendActivity.snapshot());

ipcMain.handle('agent:list-send-receipts', async (_event, { tabId, surface = null } = {}) => {
  const exactTabId = typeof tabId === 'string' ? tabId.trim() : '';
  if (!exactTabId) return { success: false, error: 'tab_id_required', records: [] };
  await agentSendReceiptStartupReady;
  const exactSurface = typeof surface === 'string' && surface.trim()
    ? surface.trim()
    : null;
  const records = agentSendReceiptStore.list({
    tabId: exactTabId,
    ...(exactSurface ? { surface: exactSurface } : {}),
  }).map((record) => ({
    operationKey: record.operationKey,
    surface: record.surface,
    tabId: record.tabId,
    handoffId: record.handoffId,
    provider: record.provider,
    sessionId: record.sessionId,
    promptHash: record.promptHash,
    promptLength: record.promptLength,
    state: record.state,
    attemptId: record.attemptId,
    receipt: record.receipt,
    transcriptBoundary: record.transcriptBoundary,
    auditIdentity: record.auditIdentity,
    presentation: record.presentation,
    createdAt: record.createdAt,
    updatedAt: record.updatedAt,
  }));
  return { success: true, records };
});

ipcMain.handle('agent:acknowledge-send-receipt-presentation', async (_event, input = {}) => {
  await agentSendReceiptStartupReady;
  const result = agentSendReceiptStore.acknowledgePresentation({
    operationKey: input.operationKey,
    attemptId: input.attemptId,
    surface: DESKTOP_HISTORY_SEND_SURFACE,
    tabId: input.tabId,
    handoffId: input.handoffId,
    provider: input.provider,
    sessionId: input.sessionId,
    entryUuid: input.entryUuid,
    sourceIdentity: input.sourceIdentity,
  });
  if (!result.ok) {
    console.warn('[AgentSendReceipt] presentation ACK rejected'
      + ' tab=' + String(input.tabId || '').slice(-12)
      + ' handoff=' + String(input.handoffId || '-')
      + ' attempt=' + String(input.attemptId || '-').slice(0, 12)
      + ' reason=' + (result.reason || 'unknown'));
  }
  return {
    success: result.ok === true,
    applied: result.applied === true,
    idempotent: result.idempotent === true,
    reason: result.reason || null,
    presentation: result.record?.presentation || null,
  };
});

ipcMain.handle('agent:dismiss-send-receipt-presentation', async (_event, input = {}) => {
  await agentSendReceiptStartupReady;
  const tabId = typeof input.tabId === 'string' ? input.tabId.trim() : '';
  const handoffId = typeof input.handoffId === 'string' ? input.handoffId.trim() : '';
  if (!tabId || !handoffId) {
    return { success: false, dismissed: false, reason: 'handoff-identity-required' };
  }
  // The immutable receipt surface describes where the send originated
  // (History, Project API, iOS, Inbox). Dismissal belongs to the desktop
  // History presentation and therefore must resolve the same handoff across
  // every origin without rewriting that origin.
  const matches = agentSendReceiptStore.list({ tabId })
    .filter((record) => record.handoffId === handoffId);
  if (matches.length !== 1) {
    console.warn('[AgentSendReceipt] presentation dismiss rejected'
      + ' tab=' + tabId.slice(-12)
      + ' handoff=' + handoffId
      + ' reason=' + (matches.length === 0 ? 'receipt-not-found' : 'receipt-ambiguous'));
    return {
      success: false,
      dismissed: false,
      reason: matches.length === 0 ? 'receipt-not-found' : 'receipt-ambiguous',
    };
  }
  const record = matches[0];
  const result = agentSendReceiptStore.dismissPresentation({
    operationKey: record.operationKey,
    attemptId: record.attemptId,
    surface: DESKTOP_HISTORY_SEND_SURFACE,
    tabId,
    handoffId,
  });
  console.warn('[AgentSendReceipt] presentation dismiss'
    + ' tab=' + tabId.slice(-12)
    + ' handoff=' + handoffId
    + ' applied=' + (result.applied === true ? '1' : '0')
    + ' idempotent=' + (result.idempotent === true ? '1' : '0')
    + ' reason=' + (result.reason || '-'));
  return {
    success: result.ok === true,
    dismissed: result.applied === true || result.idempotent === true,
    idempotent: result.idempotent === true,
    reason: result.reason || null,
  };
});

ipcMain.handle('agent:record-history-context', async (_event, input = {}) => {
  const tabId = typeof input.tabId === 'string' ? input.tabId.trim() : '';
  const handoffId = typeof input.handoffId === 'string' ? input.handoffId.trim() : '';
  const toolType = input.toolType === 'codex' ? 'codex' : input.toolType === 'claude' ? 'claude' : null;
  const cwd = typeof input.cwd === 'string' && path.isAbsolute(input.cwd) ? input.cwd : null;
  const prompt = typeof input.prompt === 'string' ? input.prompt : '';
  const source = typeof input.source === 'string' && input.source.trim()
    ? input.source.trim()
    : 'history-panel';
  if (!tabId || !handoffId || !toolType || !cwd || !prompt.trim()) {
    return {
      success: false,
      accepted: false,
      submitted: false,
      historyOnly: true,
      error: 'history_context_request_invalid',
    };
  }
  if (!isOwnedDesktopHistorySendSource(source)) {
    return {
      success: false,
      accepted: false,
      submitted: false,
      historyOnly: true,
      error: 'history_context_source_unowned',
    };
  }

  await agentSendReceiptStartupReady;

  return runKeyedExclusive(aiLifecycleActionInflight, tabId, async () => {
    const resolvedOwner = resolveAiToolTypeForTab(tabId, toolType);
    if (resolvedOwner !== toolType) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        historyOnly: true,
        error: 'history_context_provider_owner_unproven',
      };
    }
    const commandState = await resolveTerminalCommandState({
      tabId,
      caller: 'record-history-context',
      expectedProcess: toolType,
      allowProcessTreeLookup: true,
      requireProviderProof: toolType === 'claude',
    });
    if (commandState?.processLookupUnknown) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        historyOnly: true,
        error: 'history_context_process_state_unknown',
      };
    }
    if (commandState?.isRunning) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        historyOnly: true,
        error: 'history_context_process_still_running',
      };
    }

    let targetSessionId = typeof input.sessionId === 'string' && input.sessionId
      ? input.sessionId
      : null;
    const sessionAuthority = input.sessionAuthority === 'live-writer'
      ? 'live-writer'
      : input.sessionAuthority === 'history-hint'
        ? 'history-hint'
        : 'fresh';
    if (toolType === 'claude' && targetSessionId) {
      if (sessionAuthority !== 'live-writer') {
        targetSessionId = resolveLatestSessionInChain(targetSessionId, cwd);
      }
      const jsonlOwner = getClaudeJsonlLiveOwner(targetSessionId, tabId)
        || await getClaudeJsonlExternalOwner(targetSessionId, cwd);
      if (jsonlOwner) {
        return {
          success: false,
          accepted: false,
          submitted: false,
          historyOnly: true,
          error: 'claude_history_context_writer_alive',
          ownerTabId: jsonlOwner.tabId || null,
          ownerReason: jsonlOwner.reason || null,
        };
      }
    }

    const normalizedPresentationSnapshot = normalizePromptPresentationSnapshot(
      input.presentationSnapshot,
    );
    const promptHash = pasteAuditHash(prompt);
    let identity;
    try {
      identity = buildDesktopHistorySendIdentity({
        tabId,
        handoffId,
        provider: toolType,
        source,
        // The exact provider session is intentionally bound only after the
        // history API commits. Claude may resolve a linked child and a fresh
        // Codex injection creates a brand-new thread.
        sessionId: null,
        rawPrompt: prompt,
        promptHash,
        promptLength: prompt.length,
      });
    } catch (error) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        historyOnly: true,
        error: error?.message || 'history_context_identity_invalid',
      };
    }
    const begun = agentSendReceiptStore.beginAttempt(identity);
    if (begun?.ok !== true) {
      return {
        success: false,
        accepted: false,
        submitted: false,
        historyOnly: true,
        error: begun?.code || begun?.reason || 'history_context_receipt_unavailable',
      };
    }
    if (begun.action === 'replay') {
      return {
        ...desktopHistorySendReplayResult(begun.record),
        historyOnly: true,
        modelTurnStarted: false,
      };
    }
    const operationKey = identity.operationKey;
    const attemptId = begun.attemptId;
    const staged = agentSendReceiptStore.stageAttemptContext(operationKey, attemptId, {
      source,
      sessionId: identity.sessionId,
      promptText: prompt,
      transportText: prompt,
      presentationSnapshot: normalizedPresentationSnapshot,
      historyOnly: true,
      modelTurnStarted: false,
    });
    if (staged?.ok !== true) {
      agentSendReceiptStore.settleAttempt(operationKey, attemptId, {
        success: false,
        accepted: false,
        submitted: false,
        status: AGENT_SEND_DURABLE_STATES.NOT_SUBMITTED,
        code: 'history_context_receipt_stage_failed',
      });
      return {
        success: false,
        accepted: false,
        submitted: false,
        historyOnly: true,
        error: 'history_context_receipt_stage_failed',
        sendOperationKey: operationKey,
        sendAttemptId: attemptId,
      };
    }

    const armMutation = async () => {
      if (agentSendCancellations.isCancelled(tabId, handoffId, attemptId)) {
        const error = new Error('agent_send_cancelled');
        error.code = 'agent_send_cancelled';
        throw error;
      }
      const armed = agentSendReceiptStore.markAttemptState(
        operationKey,
        attemptId,
        AGENT_SEND_DURABLE_STATES.ENTER_ARMED,
      );
      if (armed?.ok !== true) {
        throw new Error(armed?.reason || 'history_context_mutation_not_armed');
      }
    };
    let providerCommitProof = null;
    let historyContextAudit = null;
    try {
      const providerApi = toolType === 'claude'
        ? claudeDataApi?.appendHistoryContext
        : codexDataModule?._api?.injectHistoryContext;
      if (typeof providerApi !== 'function') {
        throw new Error('history_context_provider_api_unavailable');
      }
      let claimedClaudeOwner = false;
      if (toolType === 'claude' && targetSessionId) {
        claimedClaudeOwner = markClaudePendingJsonlOwner(
          targetSessionId,
          tabId,
          'history-context',
        );
        if (!claimedClaudeOwner) throw new Error('claude_history_context_owner_claim_failed');
      }
      let providerResult;
      try {
        providerResult = await providerApi({
          sessionId: targetSessionId,
          sessionAuthority,
          cwd,
          prompt,
          imagePaths: normalizedPresentationSnapshot?.imagePaths || [],
          model: typeof input.model === 'string' ? input.model : null,
          effort: typeof input.effort === 'string' ? input.effort : null,
          onBeforeCommit: armMutation,
        });
      } finally {
        if (claimedClaudeOwner) {
          clearClaudePendingJsonlOwner(targetSessionId, tabId, 'history-context-finished');
        }
      }
      if (providerResult?.success !== true || providerResult?.committed !== true) {
        throw new Error(providerResult?.error || 'history_context_provider_rejected');
      }
      if (toolType === 'codex' && providerResult.sessionId) {
        codexConversationMaterializationCache.set(providerResult.sessionId, {
          materialized: true,
          metadataOnly: false,
          userRecords: 2,
          userTurns: 1,
          reason: 'user-history-present',
        });
      }
      providerCommitProof = providerResult;
      const auditTimestamp = providerResult.auditTimestamp || new Date().toISOString();
      let presentationSaved = false;
      try {
        presentationSaved = saveAuditedPromptPresentation(projectManager?.db, {
          toolType,
          sessionId: providerResult.sessionId,
          entryUuid: providerResult.entryUuid || null,
          auditTimestamp,
          actualText: prompt,
          actualHash: promptHash,
          snapshot: normalizedPresentationSnapshot,
        });
      } catch (presentationError) {
        console.warn('[HistoryContext] presentation sidecar save failed tab=' + tabId.slice(-12)
          + ' tool=' + toolType
          + ' error=' + (presentationError?.message || String(presentationError)));
      }
      const audit = {
        success: true,
        historyOnly: true,
        modelTurnStarted: false,
        operationKey,
        attemptId,
        provider: toolType,
        sessionId: providerResult.sessionId,
        promptHash,
        actualHash: promptHash,
        expectedHash: promptHash,
        entryUuid: providerResult.entryUuid || null,
        sourceIdentity: providerResult.sourceIdentity || null,
        recordByteOffset: providerResult.recordByteOffset,
        auditTimestamp,
        transcriptBoundary: {
          filePath: providerResult.filePath || null,
          recordByteOffset: providerResult.recordByteOffset ?? null,
        },
        presentationSaved,
      };
      historyContextAudit = audit;
      const promoted = agentSendReceiptStore.promoteFromAudit(audit);
      if (promoted?.promoted !== true && promoted?.idempotent !== true) {
        agentSendReceiptStore.settleAttempt(operationKey, attemptId, {
          success: null,
          accepted: true,
          submitted: false,
          historyOnly: true,
          historyRecorded: true,
          modelTurnStarted: false,
          status: AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN,
          deliveryUnknown: true,
          code: 'history_context_receipt_promotion_failed',
        });
        console.warn('[HistoryContext] exact provider record could not promote receipt'
          + ' tab=' + tabId.slice(-12)
          + ' tool=' + toolType
          + ' reason=' + (promoted?.reason || 'unknown'));
        return {
          success: null,
          accepted: true,
          submitted: false,
          historyOnly: true,
          historyRecorded: true,
          modelTurnStarted: false,
          deliveryUnknown: true,
          status: AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN,
          error: 'history_context_receipt_promotion_failed',
          handoffId,
          operationKey,
          sendOperationKey: operationKey,
          attemptId,
          sendAttemptId: attemptId,
          sessionId: providerResult.sessionId,
          pasteAudit: audit,
        };
      }
      console.log('[HistoryContext] recorded without turn'
        + ' tab=' + tabId.slice(-12)
        + ' tool=' + toolType
        + ' session=' + String(providerResult.sessionId || '').slice(0, 8)
        + ' entry=' + String(providerResult.entryUuid || providerResult.sourceIdentity || '-').slice(0, 32));
      return {
        success: true,
        accepted: true,
        submitted: false,
        historyOnly: true,
        historyRecorded: true,
        modelTurnStarted: false,
        exactAuditConfirmed: true,
        handoffId,
        operationKey,
        sendOperationKey: operationKey,
        attemptId,
        sendAttemptId: attemptId,
        sessionId: providerResult.sessionId,
        fresh: providerResult.fresh === true,
        pasteAudit: audit,
        presentationSaved,
      };
    } catch (error) {
      const commitMayHaveHappened = !!providerCommitProof
        || error?.historyContextCommitted === true
        || error?.historyContextOutcomeUnknown === true;
      const status = commitMayHaveHappened
        ? AGENT_SEND_DURABLE_STATES.DELIVERY_UNKNOWN
        : AGENT_SEND_DURABLE_STATES.NOT_SUBMITTED;
      agentSendReceiptStore.settleAttempt(operationKey, attemptId, {
        success: commitMayHaveHappened ? null : false,
        accepted: commitMayHaveHappened,
        submitted: false,
        historyOnly: true,
        historyRecorded: !!providerCommitProof || error?.historyContextCommitted === true,
        modelTurnStarted: false,
        status,
        deliveryUnknown: commitMayHaveHappened,
        code: error?.code || error?.message || 'history_context_failed',
      });
      return {
        success: commitMayHaveHappened ? null : false,
        accepted: commitMayHaveHappened,
        submitted: false,
        historyOnly: true,
        historyRecorded: !!providerCommitProof || error?.historyContextCommitted === true,
        modelTurnStarted: false,
        deliveryUnknown: commitMayHaveHappened,
        status,
        error: error?.message || String(error),
        handoffId,
        operationKey,
        sendOperationKey: operationKey,
        attemptId,
        sendAttemptId: attemptId,
        sessionId: providerCommitProof?.sessionId || null,
        ...(historyContextAudit ? { pasteAudit: historyContextAudit } : {}),
      };
    }
  });
});

// Programmatic paste (used for automated tools like Update Docs)
// Uses safePasteAndSubmit to ensure Bracketed Paste Mode and avoid TTYHOG issues.
ipcMain.handle('terminal:paste', async (event, {
  tabId,
  content,
  submit = true,
  fast = true,
  handoffId = null,
  sendAttemptId = null,
  sendOperationKey = null,
  expectedTarget = null,
  source = null,
  promptQueueAction = null,
  verifyClaudeVisibleDraftBeforePaste = false,
  requireFreshClaudeExactEmptyBeforePaste = false,
  claudeExactEmptyEvidence = null,
  awaitClaudeUserMessageAudit = false,
  presentationSnapshot = null,
} = {}) => {
  const term = terminals.get(tabId);
  if (!term) {
    return { success: false, error: 'terminal not found' };
  }
  const stoppingState = aiStoppingTabs.get(tabId);
  if (stoppingState) {
    console.warn('[terminal:paste] BLOCKED while agent stopping tab=' + String(tabId).slice(-12)
      + ' tool=' + (stoppingState.toolType || 'unknown')
      + ' source=' + (source || '-'));
    return { success: false, error: 'agent_stopping' };
  }
  const pasteProfile = classifyTerminalPasteProfile({
    submit,
    liveClaude: hasLiveClaudeInTab(tabId),
    fast,
    verifyClaudeVisibleDraftBeforePaste,
    awaitClaudeUserMessageAudit,
    handoffId,
    source,
  });
  if (!pasteProfile.allowed) {
    console.warn('[terminal:paste] BLOCKED ambiguous live Claude submit tab='
      + String(tabId).slice(-12)
      + ' source=' + (source || '-')
      + ' fast=' + fast
      + ' handoff=' + (handoffId || '-'));
    return {
      success: false,
      accepted: false,
      submitted: false,
      error: pasteProfile.error,
    };
  }
  console.log('[terminal:paste] Pasting ' + content.length + ' chars to tab ' + tabId + ' (submit=' + submit + ', fast=' + fast + ', handoff=' + (handoffId || '-') + ', source=' + (source || '-') + ')');
  
  try {
    const result = await safePasteAndSubmit(term, content, {
      submit,
      ctrlCFirst: false, // Don't clear by default
      logPrefix: '[paste:' + tabId + (handoffId ? ':' + handoffId : '') + ']',
      handoffId,
      sendAttemptId,
      sendOperationKey,
      expectedTarget,
      source,
      promptQueueAction,
      verifyClaudeVisibleDraftBeforePaste,
      requireFreshClaudeExactEmptyBeforePaste,
      claudeExactEmptyEvidence,
      awaitClaudeUserMessageAudit,
      presentationSnapshot,
      fast // Enable fast mode by default for general paste
    });
    if (result && typeof result === 'object') {
      // `null` is an authoritative post-boundary unknown. Only legacy results
      // that omit the field entirely may inherit the caller's submit intent.
      if (!Object.prototype.hasOwnProperty.call(result, 'submitted')) {
        result.submitted = !!submit;
      }
      result.handoffId = handoffId || null;
    }
    return result;
  } catch (error) {
    console.error('[terminal:paste] Error:', error);
    return { success: false, error: error.message };
  }
});

function mediaTypeFromImagePath(filePath) {
  const lower = String(filePath || '').toLowerCase();
  if (/\.jpe?g$/.test(lower)) return 'image/jpeg';
  if (/\.gif$/.test(lower)) return 'image/gif';
  if (/\.webp$/.test(lower)) return 'image/webp';
  if (/\.bmp$/.test(lower)) return 'image/bmp';
  if (/\.tiff?$/.test(lower)) return 'image/tiff';
  return 'image/png';
}

async function saveClipboardImageAsset() {
  const image = clipboard.readImage();
  if (!image || image.isEmpty()) {
    return { success: false, error: 'clipboard_image_empty' };
  }
  const png = image.toPNG();
  if (!Buffer.isBuffer(png) || png.length === 0) {
    return { success: false, error: 'clipboard_png_empty' };
  }

  const ref = await promptQueueAssetStore.materializeBuffer(png, {
    id: 0,
    mediaType: 'image/png',
    size: png.length,
  });
  if (ref.availability !== 'available') {
    return { success: false, error: ref.error || 'save_failed' };
  }
  leasePromptQueueAssetRefs([ref]);
  return { success: true, ...ref };
}

ipcMain.handle('prompt-queue:save-clipboard-image', async (_event, { tabId } = {}) => {
  try {
    const ref = await saveClipboardImageAsset();
    console.log('[prompt-queue:save-clipboard-image] tab=' + String(tabId || 'unknown').slice(-12)
      + ' success=' + ref.success
      + ' asset=' + (ref.assetId || '-')
      + ' bytes=' + (ref.size || 0)
      + ' error=' + (ref.error || '-'));
    return ref;
  } catch (error) {
    console.warn('[prompt-queue:save-clipboard-image] failed:', error?.message || error);
    return { success: false, error: error?.code || 'save_failed' };
  }
});

ipcMain.handle('codex:save-clipboard-image', async (_event, { tabId } = {}) => {
  try {
    const ref = await saveClipboardImageAsset();
    if (!ref.success) return ref;
    const transport = codexImageTransport.stageSync(ref);
    if (!transport.success) {
      return { success: false, error: transport.error || 'image_alias_failed' };
    }
    const staged = stageCodexImageRefs(tabId, [ref]);
    console.log('[codex:save-clipboard-image] tab=' + String(tabId || 'unknown').slice(-12)
      + ' asset=' + ref.assetId + ' bytes=' + ref.size + ' token=' + String(staged.token || '-').slice(-12));
    return { success: true, ...ref, inputPath: transport.path, stageToken: staged.token };
  } catch (error) {
    console.warn('[codex:save-clipboard-image] failed:', error?.message || error);
    return { success: false, error: error?.code || 'save_failed' };
  }
});

async function stageCodexImagePathForTab(tabId, filePath) {
  const candidate = typeof filePath === 'string' ? filePath.trim() : '';
  if (!candidate || !path.isAbsolute(candidate)) {
    return { success: false, error: 'invalid_path', path: candidate || null };
  }
  if (!/\.(png|jpe?g|gif|webp|bmp|tiff?)$/i.test(candidate)) {
    return { success: false, error: 'unsupported_image_path', path: candidate };
  }
  const ref = await promptQueueAssetStore.materializeRef({
    id: 0,
    path: candidate,
    mediaType: mediaTypeFromImagePath(candidate),
    size: 0,
  });
  if (ref.availability !== 'available') {
    return { success: false, error: ref.error || 'image_path_missing', path: candidate };
  }
  const transport = codexImageTransport.stageSync(ref);
  if (!transport.success) {
    return { success: false, error: transport.error || 'image_alias_failed', path: candidate };
  }
  const staged = stageCodexImageRefs(tabId, [ref]);
  return { success: true, ...ref, inputPath: transport.path, stageToken: staged.token };
}

function stageCodexImagePathForPasteSync(tabId, filePath) {
  const candidate = typeof filePath === 'string' ? filePath.trim() : '';
  if (!candidate || !path.isAbsolute(candidate)) {
    return { success: false, error: 'invalid_path', path: candidate || null };
  }
  if (!/\.(png|jpe?g|gif|webp|bmp|tiff?)$/i.test(candidate)) {
    return { success: false, error: 'unsupported_image_path', path: candidate };
  }
  let st = null;
  try { st = fs.statSync(candidate); } catch {}
  if (!st || !st.isFile()) {
    return { success: false, error: 'image_path_missing', path: candidate };
  }
  const ref = {
    success: true,
    path: candidate,
    size: st.size,
    mediaType: mediaTypeFromImagePath(candidate),
    assetId: path.basename(candidate).match(/^[a-f0-9]{64}\./i) ? path.basename(candidate) : undefined,
    availability: 'available',
  };
  const transport = codexImageTransport.stageSync(ref);
  if (!transport.success) {
    return { success: false, error: transport.error || 'image_alias_failed', path: candidate };
  }
  return { ...ref, inputPath: transport.path };
}

function prepareCodexImagePathMarkersForPaste(tabId, text, source = 'codex-paste') {
  const plan = buildCodexImagePastePlan(text, rawPath => stageCodexImagePathForPasteSync(tabId, rawPath));
  const staged = plan.staged.map(result => ({
    id: 0,
    path: result.path,
    size: result.size,
    mediaType: result.mediaType,
    assetId: result.assetId,
    availability: 'available',
  }));
  const { replaced, missing } = plan;
  if (replaced > 0) {
    console.log('[codex:image-path-paste] tab=' + String(tabId || 'unknown').slice(-12)
      + ' source=' + source
      + ' markers=' + replaced
      + ' staged=' + staged.length
      + ' missing=' + missing.length);
  }
  return { text: plan.text, segments: plan.segments, replaced, staged, missing };
}

ipcMain.handle('codex:stage-image-path', async (_event, { tabId, filePath } = {}) => {
  try {
    const result = await stageCodexImagePathForTab(tabId, filePath);
    if (result.success) {
      console.log('[codex:stage-image-path] tab=' + String(tabId || 'unknown').slice(-12) + ' path=' + result.path + ' bytes=' + result.size);
    }
    return result;
  } catch (error) {
    console.warn('[codex:stage-image-path] failed:', error?.message || error);
    return { success: false, error: error?.code || 'stage_failed' };
  }
});

ipcMain.handle('codex:stage-image-paths', async (_event, { tabId, filePaths } = {}) => {
  try {
    const candidates = Array.isArray(filePaths) ? filePaths : [];
    if (candidates.length === 0) {
      return { success: false, error: 'no_paths', paths: [], results: [] };
    }
    const refs = await promptQueueAssetStore.materializeRefs(candidates.map((filePath) => ({
      id: 0,
      path: filePath,
      mediaType: mediaTypeFromImagePath(filePath),
      size: 0,
    })));
    const transported = refs.map((ref) => ({
      ref,
      transport: ref.availability === 'available'
        ? codexImageTransport.stageSync(ref)
        : { success: false, error: ref.error || 'stage_failed' },
    }));
    const available = transported
      .filter((entry) => entry.ref.availability === 'available' && entry.transport.success)
      .map((entry) => entry.ref);
    const staged = stageCodexImageRefs(tabId, available);
    const results = transported.map(({ ref, transport }) => (
      ref.availability === 'available' && transport.success
        ? { success: true, ...ref, inputPath: transport.path, stageToken: staged.token }
        : { success: false, ...ref, error: transport.error || ref.error || 'stage_failed' }
    ));
    const paths = results.filter((result) => result?.success && result.path);
    const success = paths.length === results.length;
    const error = paths.length === 0
      ? (results.find((result) => result?.error)?.error || 'stage_failed')
      : undefined;
    console.log('[codex:stage-image-paths] tab=' + String(tabId || 'unknown').slice(-12) + ' requested=' + candidates.length + ' staged=' + paths.length + (error ? ' error=' + error : ''));
    return { success, error, paths, results, stageToken: staged.token };
  } catch (error) {
    console.warn('[codex:stage-image-paths] failed:', error?.message || error);
    return { success: false, error: error?.code || 'stage_failed', paths: [], results: [] };
  }
});
