ipcMain.handle('__test:ai-boundary', async (_event, request = {}) => {
  const action = String(request?.action || '').trim();
  if (action === 'arm') {
    return aiBoundaryTestGate.arm({
      ...request,
      action: String(request?.gateAction || '').trim(),
    });
  }
  if (action === 'release') return aiBoundaryTestGate.release(request);
  if (action === 'complete') return aiBoundaryTestGate.complete(request);
  if (action === 'inject-residual-empty-frame') {
    return injectResidualEmptyClaudeFrameForTest(request);
  }
  if (action === 'inject-missing-prompt-empty-frame') {
    return injectMissingPromptEmptyClaudeFrameForTest(request);
  }
  if (action === 'inject-provider-error') {
    return require(path.join(srcMainDir, 'web-server')).performE2eBoundaryAction(request);
  }
  if (action === 'snapshot') {
    return {
      success: aiBoundaryTestGate.enabled,
      enabled: aiBoundaryTestGate.enabled,
      arms: aiBoundaryTestGate.snapshot(),
    };
  }
  if (action === 'clear') {
    return aiBoundaryTestGate.clear(String(request?.reason || 'e2e-rollback'));
  }
  return {
    success: false,
    error: aiBoundaryTestGate.enabled ? 'unsupported action' : 'test_hook_disabled',
  };
});

// Runtime-only Claude presence. Keep this projection in one place so every
// consumer (History, Project API and renderer restore) agrees on whether the
// current PTY owns an active turn. Transcript/materialization fields are added
// by the public `claude:get-presence` handler below; they are intentionally not
// needed by the batched renderer restore path.
function getClaudePtyRuntimePresence(tabId, evidence = {}) {
  const hasBridge = bridgeKnownSessions.has(tabId);
  const turnBusy = claudeTurnBusy.get(tabId) === true;
  const localCommandActive = claudeLocalCommandWatchers.has(tabId);
  const hasTerm = terminals.has(tabId);
  const promptReady = claudePromptReady.has(tabId);
  const stopping = aiStoppingTabs.get(tabId);
  const startupIntent = claudeStartupIntents.get(tabId);
  const startupIntentFresh = !!startupIntent && (Date.now() - startupIntent.at) < 45_000;
  if (startupIntent && !startupIntentFresh) {
    claudeStartupIntents.delete(tabId);
  }
  const awaiting = !!claudeAwaitingInput.get(tabId);
  const launch = claudeLaunchGenerationByTab.get(tabId) || null;
  const startupGate = claudeStartupDefaultsGateByTab.get(tabId) || null;
  const startupGatePending = !!launch?.generation
    && startupGate?.generation === launch.generation
    && startupGate?.status !== 'ready'
    && startupGate?.status !== 'cleared';
  const projected = projectClaudePtyPresence({
    hasTerm,
    hasBridge,
    promptReady,
    cliActive: claudeCliActive.get(tabId) === true,
    processAlive: evidence.providerProcessAlive === true,
    processLookupUnknown: evidence.processLookupUnknown === true,
    turnBusy,
    localCommandActive,
    stopping: stopping?.toolType === 'claude',
    startupIntentFresh,
    startupGatePending,
  });
  return {
    ...projected,
    hasBridge,
    hasTerm,
    awaiting,
    runtimeSessionId: bridgeKnownSessions.get(tabId) || null,
    launchId: launch?.generation || null,
    launchGeneration: launch?.generation || null,
    providerProcessAlive: evidence.providerProcessAlive === true,
    processLookupUnknown: evidence.processLookupUnknown === true,
  };
}

ipcMain.handle('claude:get-presence', async (event, tabIdArg, requestContext = null) => {
  const tabId = typeof tabIdArg === 'string'
    ? tabIdArg
    : String(tabIdArg?.tabId || '');
  const context = typeof tabIdArg === 'object' && tabIdArg !== null
    ? (tabIdArg.context || requestContext)
    : requestContext;
  // In-memory bridge/prompt flags are deliberately empty for a short window
  // after a main-process restart. The live PTY process is the stronger fact:
  // resolve it through the same provider-aware process proof used by every
  // other lifecycle surface before projecting Start/Stop.
  const commandState = await resolveTerminalCommandState({
    tabId,
    caller: 'claude:get-presence',
    expectedProcess: 'claude',
    allowProcessTreeLookup: true,
    requireProviderProof: true,
  });
  const runtimePresence = getClaudePtyRuntimePresence(tabId, {
    providerProcessAlive: commandState?.expectedProcess === 'claude'
      && commandState?.providerProcessAlive === true,
    processLookupUnknown: commandState?.processLookupUnknown === true,
  });
  const persisted = (() => {
    try {
      return projectManager?.db?.db?.prepare(
        'SELECT claude_session_id, cwd FROM tabs WHERE tab_id = ? LIMIT 1'
      ).get(tabId) || null;
    } catch {
      return null;
    }
  })();
  // BUSY = "Claude is generating a turn right now", NOT "Claude is alive" and
  // NOT "the glyph-spinner blinked". This status drives the MOBILE COMPOSER's
  // Send↔Stop swap — the button is a TURN/loader control, so busy must be the
  // AUTHORITATIVE operation signals only: claudeTurnBusy (Stop-hook pipeline,
  // UserPromptSubmit→true / Stop→false) OR local slash-command brackets that
  // have their own durable JSONL completion signal (currently /compact).
  //
  // Deliberately EXCLUDES:
  //   - claudeCliActive — process-liveness, true the whole session incl. idle
  //     at the ⏵ prompt (was the first bug: idle-alive → 'busy' forever).
  //   - claudeSpinnerBusy — the glyph (`✻✳…`) heuristic. It FALSE-FIRES on
  //     stale scrollback: when a tab is reopened the PTY replays history that
  //     still contains an old "✻ Brewed for 15m" frame → detector flips BUSY
  //     with BoundarySM=idle, and its IDLE edge only sends `claude:busy-state`
  //     to the desktop renderer (never _webBroadcast) → the phone latched
  //     busy:true with no busy:false to clear it → composer stuck on Stop.
  //     The glyph is desktop-only liveness flavor; the hook is the truth.
  // Process-running ("Claude is up in this PTY") is conveyed by the 'active'
  // status + the navbar Stop button (claudeStatus), NOT by this busy flag.
  // See fact-mobile-claude-pty.md::Composer busy = turn, not spinner/alive.
  const materializationSessionId = persisted?.claude_session_id || runtimePresence.runtimeSessionId || null;
  const materialization = materializationSessionId && getSessionMaterialization
    ? getSessionMaterialization(materializationSessionId, persisted?.cwd || null)
    : null;
  const conversationMaterialized = materialization?.materialized === true;
  const presence = {
    status: runtimePresence.status,
    hasBridge: runtimePresence.hasBridge,
    isBusy: runtimePresence.isBusy,
    hasTerm: runtimePresence.hasTerm,
    providerProcessAlive: runtimePresence.providerProcessAlive,
    processLookupUnknown: runtimePresence.processLookupUnknown,
    inputReady: runtimePresence.inputReady,
    awaiting: runtimePresence.awaiting,
    sessionId: materializationSessionId,
    sendTarget: readAgentSendDestinationAtWriteBoundary(tabId, 'claude'),
    launchId: runtimePresence.launchId,
    launchGeneration: runtimePresence.launchGeneration,
    conversationMaterialized,
    // Именно `runtimePresence.status`, а не голое `status`: такой переменной в
    // этом обработчике нет, и обращение к ней роняло ВЕСЬ ответ о состоянии
    // Claude с ошибкой (281 падение в логе за одну сессию, 2026-08-18).
    //
    // Цена ошибки была непропорциональна опечатке. Ответ о состоянии — общий
    // источник для трёх поверхностей сразу, и падал он молча для пользователя:
    // на кнопке терминала не появлялось ни «запустить», ни «остановить» —
    // наведение не давало ничего, клик не делал ничего; плашка запуска/ошибки
    // не могла построиться; значок действия сессии не обновлялся. Claude при
    // этом был жив — сломан был только рассказ о нём.
    canResume: runtimePresence.status === 'inactive' && conversationMaterialized,
    canCopySessionId: conversationMaterialized,
    timelineCount: typeof materialization?.timelineCount === 'number' ? materialization.timelineCount : null,
    materializationReason: materialization?.reason || null,
  };
  await historyPresenceTestGate.waitIfArmed({
    tabId,
    consumer: context?.consumer,
    ownerKey: context?.ownerKey,
    generation: context?.generation,
  });
  return presence;
});

// Operational phases are runtime facts, not transcript fields. History asks
// main on every mount so tab switches and renderer reloads see the current
// operation, while a full app restart naturally starts with an empty registry.
ipcMain.handle('agent:get-operational-phase', (_event, request = {}) => {
  const tabId = typeof request === 'string' ? request : request?.tabId;
  const provider = typeof request === 'object' ? request?.provider : null;
  return compactOperations.snapshot(tabId, provider || null);
});

ipcMain.handle('claude:startup-slash-proof', (event, payload = {}) => {
  return readClaudeStartupSlashProof(payload);
});

ipcMain.handle('claude:confirm-settings-dialog', async (_event, payload = {}) => {
  const tabId = String(payload?.tabId || '');
  const kind = String(payload?.kind || '').toLowerCase();
  const expectedDialogType = kind === 'model'
    ? 'ModelDialog'
    : kind === 'effort'
      ? 'EffortDialog'
      : null;
  if (!tabId || !expectedDialogType) {
    return { success: false, confirmed: false, error: 'invalid_arguments' };
  }
  return confirmClaudeSettingsDialogFromCurrentFrame(
    tabId,
    expectedDialogType,
    String(payload?.reason || 'renderer-setting-transaction'),
  );
});

ipcMain.handle('agent:get-stopping-state', async (_event, tabId) => {
  const state = aiStoppingTabs.get(tabId) || null;
  const publicState = state?.publicLifecycle === false ? null : state;
  return {
    success: true,
    stopping: !!publicState,
    toolType: publicState?.toolType || null,
    reason: publicState?.reason || null,
    since: publicState?.since || null,
    sessionId: publicState?.sessionId || null,
  };
});

ipcMain.handle('agent:get-launch-preparation-state', (_event, tabId) => ({
  success: true,
  state: agentLaunchPreparations.get(String(tabId || '')),
}));

ipcMain.handle('agent:clear-launch-preparation-state', (_event, payload = {}) => {
  const tabId = String(payload?.tabId || '');
  const token = Number(payload?.token || 0);
  if (!tabId || !Number.isInteger(token) || token <= 0) {
    return { success: false, cleared: false, error: 'tabId and token required' };
  }
  const cleared = agentLaunchPreparations.clear(tabId, token, {
    reason: String(payload?.reason || 'renderer-dismissed'),
  });
  return {
    success: true,
    cleared,
    state: agentLaunchPreparations.get(tabId),
  };
});

// Prepare a JSONL file before `claude --resume`: first trim safe tail-only
// startup slash wrappers, then repair dangling parentUuid so Claude CLI and the
// history panel render full pre-orphan history. This is shared by the public
// diagnostic IPC and the main-owned Resume transaction below.
async function prepareClaudeJsonlBeforeResume({ sessionId, cwd, tabId }) {
  if (!sessionId) return { success: false, error: 'sessionId required' };
  let trimResult = { success: true, trimmed: 0 };
  const liveOwner = getClaudeJsonlLiveOwner(sessionId, tabId)
    || await getClaudeJsonlExternalOwner(sessionId, cwd);
  if (!liveOwner) {
    try {
      trimResult = trimTrailingEffortEntries(sessionId, cwd);
      if (trimResult?.trimmed > 0) {
        console.log('[ClaudePrepareResume] Trimmed ' + trimResult.trimmed +
          ' trailing startup slash line(s) before repair/resume of ' + sessionId.slice(0, 8) +
          ' tab=' + String(tabId).slice(-12) +
          ' (model=' + (trimResult.model || 0) + ', effort=' + (trimResult.effort || 0) + ')');
      }
    } catch (e) {
      trimResult = { success: false, trimmed: 0, error: e.message };
      console.warn('[ClaudePrepareResume] trimTrailingEffortEntries failed (non-fatal): ' + e.message);
    }
  } else {
    trimResult = {
      success: false,
      trimmed: 0,
      skipped: true,
      reason: 'claude-jsonl-owner-alive',
      ownerTabId: liveOwner.tabId,
      ownerReason: liveOwner.reason
    };
    console.warn('[ClaudePrepareResume] block trim+repair for session=' + sessionId.slice(0, 8) +
      ' tab=' + String(tabId || '').slice(-12) +
      ': JSONL owner alive tab=' + String(liveOwner.tabId || '').slice(-12) +
      ' reason=' + liveOwner.reason +
      ' ownerPid=' + (liveOwner.pid || '-') +
      ' proofKind=' + (liveOwner.proofKind || liveOwner.reason || '-'));
    return {
      success: false,
      repaired: 0,
      trimmed: 0,
      trim: trimResult,
      skipped: true,
      reason: trimResult.reason,
      error: 'Claude session is already starting/running',
      ownerTabId: liveOwner.tabId,
      ownerReason: liveOwner.reason
    };
  }
  try {
    const result = await repairJsonlChainBreaks(sessionId, cwd);
    if (result?.error) {
      return {
        success: false,
        trimmed: trimResult.trimmed || 0,
        trim: trimResult,
        ...result,
      };
    }
    return { success: true, trimmed: trimResult.trimmed || 0, trim: trimResult, ...result };
  } catch (e) {
    return { success: false, trimmed: trimResult.trimmed || 0, trim: trimResult, error: e.message };
  }
}

ipcMain.handle('claude:repair-jsonl-before-resume', async (_event, payload = {}) => {
  return await prepareClaudeJsonlBeforeResume(payload);
});

// PromptQueue: grab the current Claude input via the chat:externalEditor flow.
//
// Flow:
//  1. Renderer calls this IPC.
//  2. We send Ctrl+G (0x07) to Claude's PTY → triggers chat:externalEditor binding.
//  3. Claude writes the current input to a tempfile and execSync-launches our EDITOR
//     (env-injected to noted-code-grab.js). Claude waits synchronously.
//  4. noted-code-grab reads the file, posts JSON {event:'GrabInput', ppid, text} to our socket,
//     truncates the file, exits.
//  5. Claude reads the now-empty file → sets input to empty (clears).
//  6. Socket handler resolves grabInputPending[tabId] with the text we captured.
//
// Caveats (from research):
//  - Image attachments are dropped — only [Image #N] placeholder tokens survive (counted, not carried).
//  - Brief "Save and close editor…" hint may flash in TUI for ~50ms.
//  - If Claude is currently busy (no draft input), Ctrl+G is a no-op and we time out.
// Resolve tabId → claude-process PID via bridgePidCache (Claude PID → tabId).
// O(N) scan but bridgePidCache rarely has >5 entries; not a hot path.
function findClaudePidByTab(tabId) {
  for (const [pid, tid] of bridgePidCache) {
    if (tid === tabId) return pid;
  }
  return null;
}

async function prebindClaudeHookRouteForSubmit(tabId, logPrefix = '[safePaste]') {
  if (!tabId || !terminals.has(tabId)) {
    return { bound: false, tabId: null, pid: null, reason: 'tab-unavailable' };
  }

  const preferredPids = [];
  for (const [pid, candidateTabId] of bridgePidCache) {
    if (candidateTabId === tabId) preferredPids.push(Number(pid));
  }
  invalidateAiProcessLookupCache(tabId, 'claude');
  const lookup = await inspectAiDescendantProcessesByTab(
    tabId,
    'claude',
    { forceFresh: true },
  );
  if (lookup.status !== AI_PROCESS_LOOKUP_STATUS.FOUND) {
    const reason = lookup.status === AI_PROCESS_LOOKUP_STATUS.UNKNOWN
      ? 'process-lookup-unknown'
      : 'claude-process-absent';
    console.warn(logPrefix + ' [ClaudeHookRoute] pre-submit proof unavailable tab='
      + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' error=' + (lookup.error?.message || '-'));
    return { bound: false, tabId, pid: null, reason };
  }

  const binding = prebindClaudeHookPid({
    tabId,
    matches: lookup.matches,
    tabByPid: bridgePidCache,
    hasTab: candidateTabId => terminals.has(candidateTabId),
    preferredPids,
  });
  if (binding.bound) {
    console.log(logPrefix + ' [ClaudeHookRoute] prebound tab='
      + String(tabId).slice(-12)
      + ' ppid=' + binding.pid
      + ' source=pre-submit-process-proof');
  }
  return binding;
}

// Liveness check for "is Claude running in this tab's PTY" — the guard every
// input-write handler (grab / copy / clear / append / replay) needs before
// pasting into the terminal (refusing protects against bracketed paste landing
// in a bare bash/zsh prompt).
//
// `bridgeKnownSessions.has(tabId)` alone is INSUFFICIENT: when the user `cd`s
// into another project inside the shell before launching claude (cwd-drift),
// CwdGuard in processFile deliberately skips `bridgeKnownSessions.set` to avoid
// stale-bridge takeover (see fix-bridge-stale-takeover.md + fix-cwdguard-
// session-not-detected.md) — yet Claude is genuinely alive and the renderer
// store DID get the sessionId. The guards then refused grab/replay with
// "No Claude session running in this tab" even though Claude was answering.
//
// The drift-immune signal is bridgePidCache: it is populated only AFTER `ps`
// confirmed a real `claude` process parented by THIS tab's shell, either at
// launch acceptance or in processFile (PID + command-name validated, not cwd).
// A live claude child is authoritative liveness regardless of cwd. We still
// verify the cached PID is alive so a shell-side restart that left a stale
// cache entry doesn't read as alive.
// A pure bash/zsh tab has neither a bridge session nor a claude child → still
// refused, so the anti-rm-rf intent is preserved.
function hasLiveClaudeInTab(tabId) {
  if (bridgeKnownSessions.has(tabId)) return true;
  // Fresh Claude can render the input prompt before StatusLine bridge metadata
  // writes the first session file. That state is still safe for slash commands:
  // the TUI is on-screen and the process was launched by our Claude runner.
  if (terminals.has(tabId) && claudeCliActive.get(tabId) === true && claudePromptReady.has(tabId)) return true;
  const pid = findClaudePidByTab(tabId);
  if (!pid) return false;
  try { process.kill(pid, 0); return true; } catch { return false; }
}

// Read the EDITOR env of a running process via `ps -wwwE`. Returns null if process
// is gone or ps doesn't expose env (different user, sandboxed, etc).
async function readProcessEditor(pid) {
  try {
    const { execFile } = require('child_process');
    const out = await new Promise((resolve, reject) => {
      execFile('/bin/ps', ['-p', String(pid), '-wwwE', '-o', 'command='], {
        timeout: 1000,
        encoding: 'utf8',
        env: buildChildProcessEnv(),
      }, (error, stdout) => error ? reject(error) : resolve(stdout));
    });
    const m = out.match(/(?:^|\s)EDITOR=([^\s]+(?:\s+[^=\s][^=]*)?)/);
    return m ? m[1] : null;
  } catch {
    return null;
  }
}

// Resolve [Image #N] placeholders in grabbed text to actual files on disk.
//
// HOW CLAUDE STORES PASTED IMAGES (from decompiled v2.x source — packages/claude-code-src/utils/imageStore.ts):
//   1. Cmd+V image into PromptInput → onImagePaste(base64, mediaType) assigns numeric id (nextPasteIdRef++)
//   2. Placeholder [Image #N] inserted at caret in the text input
//   3. Background: storeImage() writes ~/.claude/image-cache/<sessionId>/<N>.<ext>
//      where ext = mediaType.split('/')[1]  (png|jpeg|jpg|gif|webp|bmp), 0o600
//   4. Files are NEVER deleted while the session is alive — pruning a [Image #N]
//      from the input only removes the in-memory pastedContents entry, the file stays
//   5. cleanupOldImageCaches() runs ONCE at Claude boot — wipes all session subdirs
//      except the current sessionId
//
// Our external-editor grab gets the EXPANDED text (expandPastedTextRefs leaves image
// refs as-is — only text refs are inlined). So the file extensions
// noted-code-grab sends back contains literal "[Image #N]" tokens and the actual
// images are still on disk under the current sessionId. We resolve N → filesystem
// path by trying known extensions until one exists.
function resolveGrabbedImagePaths(sessionId, text) {
  if (!sessionId || !text) return [];
  const ids = [];
  const seen = new Set();
  const re = /\[Image\s+#?(\d+)\]/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const id = parseInt(m[1], 10);
    if (!isNaN(id) && !seen.has(id)) { seen.add(id); ids.push(id); }
  }
  if (ids.length === 0) return [];
  const baseDir = path.join(os.homedir(), '.claude', 'image-cache', sessionId);
  const exts = ['png', 'jpeg', 'jpg', 'gif', 'webp', 'bmp'];
  const mediaByExt = { png: 'image/png', jpeg: 'image/jpeg', jpg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', bmp: 'image/bmp' };
  const resolved = [];
  for (const id of ids) {
    let hit = null;
    for (const ext of exts) {
      const p = path.join(baseDir, id + '.' + ext);
      try {
        const st = fs.statSync(p);
        if (st.isFile()) { hit = { id, path: p, mediaType: mediaByExt[ext], size: st.size }; break; }
      } catch {}
    }
    resolved.push(hit || { id, path: null, mediaType: null, size: 0, missing: true });
  }
  return resolved;
}

function commandLooksLikeAiProcess(cmd, expectedName) {
  if (expectedName === 'claude') return !!classifyClaudeProcessCommand(cmd);
  const text = String(cmd || '');
  const tokens = text.split(/\s+/).filter(Boolean);
  const firstBase = tokens[0] ? path.basename(tokens[0]) : '';
  const secondBase = tokens[1] ? path.basename(tokens[1]) : '';
  if (expectedName === 'codex') {
    return firstBase === 'codex'
      || text.includes('@openai/codex')
      || (firstBase === 'node' && secondBase === 'codex');
  }
  if (expectedName === 'gemini') return firstBase === 'gemini' || (firstBase === 'node' && secondBase === 'gemini');
  return !!getAiProcessNameFromCommand(text);
}

function invalidateProcessTreeSnapshot(reason = 'lifecycle-boundary') {
  processTreeSnapshotCache = null;
  const generation = processTreeSnapshotSingleFlight.invalidate();
  console.log('[ProcessTreeSnapshot] invalidate generation=' + generation + ' reason=' + reason);
  return generation;
}

async function captureProcessTreeSnapshot({ forceFresh, getWaiterCount, generation, isCurrent }) {
  const opId = beginPerfOp('psSnapshot', {});
  const startedAt = nodePerformance.now();
  const startAbs = nodePerformance.timeOrigin + startedAt;
  try {
    const psOut = await execAsync('ps -eo pid=,ppid=,pgid=,tpgid=,command=', 2000);
    const psMs = nodePerformance.now() - startedAt;
    const parseStartedAt = nodePerformance.now();
    const children = new Map();
    const processesByPid = new Map();
    const lines = (psOut || '').split('\n').filter(Boolean);
    for (const line of lines) {
      const m = line.trim().match(/^(\d+)\s+(\d+)\s+(\d+)\s+(-?\d+)\s+(.+)$/);
      if (!m) continue;
      const [, pid, ppid, pgid, tpgid, cmd] = m;
      if (cmd.includes('Electron') || cmd.includes('electron')) continue;
      const child = {
        pid: Number(pid),
        ppid: Number(ppid),
        pgid: Number(pgid),
        tpgid: Number(tpgid),
        cmd,
      };
      processesByPid.set(child.pid, child);
      if (!children.has(child.ppid)) children.set(child.ppid, []);
      children.get(child.ppid).push(child);
    }
    const snapshot = {
      children,
      processesByPid,
      linesCount: lines.length,
      createdAt: nodePerformance.now(),
      startAbs,
      psMs,
      parseMs: nodePerformance.now() - parseStartedAt,
    };
    if (typeof isCurrent !== 'function' || isCurrent()) {
      processTreeSnapshotCache = snapshot;
    } else {
      console.log('[ProcessTreeSnapshot] discard stale capture generation=' + generation);
    }
    const totalMs = nodePerformance.now() - startedAt;
    const waiters = getWaiterCount();
    if (totalMs > 50 || psMs > 50 || waiters > 0) {
      console.warn(
        '[Perf:ProcessTreeSnapshot]' +
        ' startAbs=' + startAbs.toFixed(1) +
        ' endAbs=' + (nodePerformance.timeOrigin + nodePerformance.now()).toFixed(1) +
        ' source=' + (forceFresh ? 'force-fresh' : 'spawn') +
        ' lines=' + lines.length +
        ' waiters=' + waiters +
        ' psMs=' + psMs.toFixed(1) +
        ' parseMs=' + snapshot.parseMs.toFixed(1) +
        ' totalMs=' + totalMs.toFixed(1)
      );
    }
    return snapshot;
  } finally {
    endPerfOp(opId);
  }
}

async function getProcessTreeSnapshot({ forceFresh = false } = {}) {
  const now = nodePerformance.now();
  if (!forceFresh && processTreeSnapshotCache && (now - processTreeSnapshotCache.createdAt) < PROCESS_TREE_SNAPSHOT_TTL_MS) {
    return { ...processTreeSnapshotCache, source: 'cache', waiters: 0 };
  }

  const result = await processTreeSnapshotSingleFlight.get({ forceFresh });
  return {
    ...result.value,
    source: result.source,
    waitMs: result.waitMs,
    waiters: result.waiters,
  };
}

async function findAiDescendantProcessesByTab(tabId, expectedName, options = {}) {
  const term = terminals.get(tabId);
  if (!term) return [];
  const startedAt = nodePerformance.now();
  const startAbs = nodePerformance.timeOrigin + startedAt;
  const opId = beginPerfOp('psLookup', { tabId, expectedName });
  try {
    const snapshot = await getProcessTreeSnapshot(options);
    if (typeof options.onSnapshot === 'function') options.onSnapshot(snapshot);
    const parseStartedAt = nodePerformance.now();
    const matches = [];
    const stack = [{ pid: term.pid, depth: 0 }];
    const seen = new Set();
    while (stack.length > 0) {
      const cur = stack.pop();
      if (!cur || seen.has(cur.pid)) continue;
      seen.add(cur.pid);
      const kids = snapshot.children.get(cur.pid) || [];
      for (const child of kids) {
        const depth = cur.depth + 1;
        if (commandLooksLikeAiProcess(child.cmd, expectedName)) {
          matches.push({ ...child, depth, processName: expectedName || getAiProcessNameFromCommand(child.cmd) });
        }
        stack.push({ pid: child.pid, depth });
      }
    }
    matches.sort((a, b) => b.depth - a.depth || b.pid - a.pid);
    const parseMs = nodePerformance.now() - parseStartedAt;
    const totalMs = nodePerformance.now() - startedAt;
    if (totalMs > 50 || snapshot.psMs > 50) {
      console.warn(
        '[Perf:ProcessTreeLookup] tab=' + tabId.slice(-8) +
        ' expected=' + expectedName +
        ' shellPid=' + term.pid +
        ' startAbs=' + startAbs.toFixed(1) +
        ' endAbs=' + (nodePerformance.timeOrigin + nodePerformance.now()).toFixed(1) +
        ' snapshotSource=' + snapshot.source +
        ' snapshotAgeMs=' + (nodePerformance.now() - snapshot.createdAt).toFixed(1) +
        ' waitMs=' + (snapshot.waitMs || 0).toFixed(1) +
        ' matches=' + matches.length +
        ' lines=' + snapshot.linesCount +
        ' psMs=' + snapshot.psMs.toFixed(1) +
        ' snapshotParseMs=' + snapshot.parseMs.toFixed(1) +
        ' parseMs=' + parseMs.toFixed(1) +
        ' totalMs=' + totalMs.toFixed(1)
      );
    }
    return matches;
  } catch (err) {
    console.warn(
      '[Perf:ProcessTreeLookup] failed tab=' + tabId.slice(-8) +
      ' expected=' + expectedName +
      ' startAbs=' + startAbs.toFixed(1) +
      ' endAbs=' + (nodePerformance.timeOrigin + nodePerformance.now()).toFixed(1) +
      ' durMs=' + (nodePerformance.now() - startedAt).toFixed(1) +
      ' error=' + (err?.message || String(err))
    );
    console.warn('[capture-input:' + expectedName + '] ps lookup failed for tab ' + tabId.slice(-12) + ': ' + (err?.message || String(err)));
    throw new AiProcessLookupError(err?.message || String(err), {
      cause: err,
      tabId,
      expectedName,
    });
  }
  finally {
    endPerfOp(opId);
  }
}

async function inspectAiDescendantProcessesByTab(tabId, expectedName, options = {}) {
  return inspectProcessLookup(
    () => findAiDescendantProcessesByTab(tabId, expectedName, options),
    { tabId, expectedName },
  );
}

function aiProcessLookupFailureResult(lookup) {
  return {
    success: false,
    error: 'process_lookup_failed',
    lookupUnknown: true,
    detail: lookup?.error?.message || String(lookup?.error || 'process_lookup_failed'),
  };
}

function aiProcessLookupCacheKey(tabId, expectedName) {
  return String(tabId || '') + ':' + String(expectedName || 'any');
}

function invalidateAiProcessLookupCache(tabId, expectedName = null) {
  if (!tabId) return;
  if (expectedName) {
    aiProcessLookupCache.delete(aiProcessLookupCacheKey(tabId, expectedName));
    return;
  }
  const prefix = String(tabId) + ':';
  for (const key of aiProcessLookupCache.keys()) {
    if (key.startsWith(prefix)) aiProcessLookupCache.delete(key);
  }
}

async function findAiDescendantProcessesByTabCached(tabId, expectedName, maxAgeMs = AI_PROCESS_LOOKUP_CACHE_MS) {
  const key = aiProcessLookupCacheKey(tabId, expectedName);
  const result = await inspectProcessLookupCached({
    cache: aiProcessLookupCache,
    key,
    maxAgeMs,
    now: () => nodePerformance.now(),
    query: () => findAiDescendantProcessesByTab(tabId, expectedName),
    meta: { tabId, expectedName },
  });
  return requireKnownProcessLookup(result);
}

async function inspectAiDescendantProcessesByTabCached(tabId, expectedName, maxAgeMs = AI_PROCESS_LOOKUP_CACHE_MS) {
  return inspectProcessLookupCached({
    cache: aiProcessLookupCache,
    key: aiProcessLookupCacheKey(tabId, expectedName),
    maxAgeMs,
    now: () => nodePerformance.now(),
    query: () => findAiDescendantProcessesByTab(tabId, expectedName),
    meta: { tabId, expectedName },
  });
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function waitForAiLaunchAccepted(tabId, expectedName, options = {}) {
  const timeoutMs = Math.max(300, Math.min(10_000, Number(options.timeoutMs) || 5000));
  const intervalMs = Math.max(50, Math.min(500, Number(options.intervalMs) || 120));
  const startedAt = Date.now();
  const deadline = startedAt + timeoutMs;
  let lastMatches = [];
  let attempts = 0;
  let lastError = null;
  let lastLookupStatus = null;

  while (Date.now() <= deadline) {
    attempts += 1;
    if (!terminals.has(tabId)) {
      return {
        accepted: false,
        error: 'terminal_not_found',
        reason: 'terminal_not_found',
        attempts,
        elapsedMs: Date.now() - startedAt,
      };
    }
    invalidateAiProcessLookupCache(tabId, expectedName);
    const lookup = await inspectAiDescendantProcessesByTab(tabId, expectedName);
    lastLookupStatus = lookup.status;
    if (lookup.status === AI_PROCESS_LOOKUP_STATUS.UNKNOWN) {
      lastError = lookup.error;
      lastMatches = [];
    } else {
      lastError = null;
      lastMatches = lookup.matches;
    }
    if (lookup.status === AI_PROCESS_LOOKUP_STATUS.FOUND) {
      const match = lastMatches[0];
      if (expectedName === 'claude') {
        const preferredPids = [];
        for (const [pid, candidateTabId] of bridgePidCache) {
          if (candidateTabId === tabId) preferredPids.push(Number(pid));
        }
        const routeBinding = prebindClaudeHookPid({
          tabId,
          matches: lastMatches,
          tabByPid: bridgePidCache,
          hasTab: candidateTabId => terminals.has(candidateTabId),
          preferredPids,
        });
        if (routeBinding.bound) {
          console.log(
            '[ClaudeHookRoute] prebound tab=' + String(tabId).slice(-12) +
            ' ppid=' + routeBinding.pid +
            ' source=launch-accepted-process-proof'
          );
        } else {
          console.warn('[ClaudeHookRoute] launch accepted without unique hook owner tab='
            + String(tabId).slice(-12)
            + ' matches=' + lastMatches.length
            + ' reason=' + routeBinding.reason);
        }
      }
      console.log(
        '[AgentLaunchAccepted] tab=' + String(tabId).slice(-12) +
        ' tool=' + expectedName +
        ' pid=' + match.pid +
        ' attempts=' + attempts +
        ' elapsedMs=' + (Date.now() - startedAt) +
        ' reason=' + (options.reason || '-')
      );
      return {
        accepted: true,
        pid: match.pid,
        processName: match.processName || expectedName,
        attempts,
        elapsedMs: Date.now() - startedAt,
      };
    }
    if (Date.now() >= deadline) break;
    await sleep(intervalMs);
  }

  console.warn(
    '[AgentLaunchAccepted] failed tab=' + String(tabId).slice(-12) +
    ' tool=' + expectedName +
    ' attempts=' + attempts +
    ' elapsedMs=' + (Date.now() - startedAt) +
    ' hasTerminal=' + terminals.has(tabId) +
    ' lastLookupStatus=' + (lastLookupStatus || '-') +
    ' lastMatches=' + lastMatches.length +
    ' error=' + (lastError?.message || '-')
  );
  return {
    accepted: false,
    error: lastLookupStatus === AI_PROCESS_LOOKUP_STATUS.UNKNOWN
      ? 'process_lookup_failed'
      : expectedName + '_launch_not_accepted',
    reason: lastError?.message || ('no_' + expectedName + '_process'),
    lookupUnknown: lastLookupStatus === AI_PROCESS_LOOKUP_STATUS.UNKNOWN,
    attempts,
    elapsedMs: Date.now() - startedAt,
  };
}

ipcMain.handle('agent:get-launch-accepted', async (_event, request = {}) => {
  const tabId = request?.tabId;
  const toolType = request?.toolType === 'claude' ? 'claude' : (request?.toolType === 'codex' ? 'codex' : null);
  if (!tabId) return { accepted: false, success: false, error: 'tabId required' };
  if (!toolType) return { accepted: false, success: false, error: 'toolType required' };
  const result = await waitForAiLaunchAccepted(tabId, toolType, {
    timeoutMs: request?.timeoutMs,
    intervalMs: request?.intervalMs,
    reason: request?.reason || 'agent:get-launch-accepted',
  });
  return { success: !!result.accepted, ...result };
});

async function resolveAgentInputProcess(tabId, agent, logPrefix) {
  const expectedName = agent === 'claude' ? 'claude' : (agent === 'codex' ? 'codex' : null);
  if (!expectedName) {
    return { success: false, error: 'unsupported_agent', candidates: [], cliPid: null, lockPids: [] };
  }

  // Session bridge identity and process liveness are deliberately separate.
  // A fresh Claude TUI can already accept a startup slash command before its
  // first conversation JSONL exists, so bridgePidCache is not guaranteed to
  // contain the process yet. Resolve the input helper from this tab's PTY tree,
  // the same authoritative boundary already used by Codex.
  const lookup = await inspectAiDescendantProcessesByTab(tabId, expectedName);
  if (lookup.status === AI_PROCESS_LOOKUP_STATUS.UNKNOWN) {
    console.warn(logPrefix + ' Tab ' + tabId.slice(-12) + ': ' + expectedName + ' process lookup unavailable');
    return { ...aiProcessLookupFailureResult(lookup), candidates: [], cliPid: null, lockPids: [] };
  }

  const candidates = lookup.matches;
  if (candidates.length === 0) {
    console.log(logPrefix + ' Tab ' + tabId.slice(-12) + ': no active ' + expectedName + ' process under PTY');
    return {
      success: false,
      error: 'no_' + expectedName + '_session',
      candidates: [],
      cliPid: null,
      lockPids: [],
    };
  }

  // Matches are deepest-first. The external-editor helper is parented by the
  // leaf CLI process; writing locks for every matching wrapper also preserves
  // compatibility with launchers whose final executable shape changes.
  const cliPid = candidates[0].pid;
  const lockPids = [...new Set(candidates.map((candidate) => candidate.pid))];
  console.log(
    logPrefix + ' Tab ' + tabId.slice(-12) +
    ': matched ' + expectedName + ' pids=' +
    candidates.map((candidate) => candidate.pid + '@d' + candidate.depth).join(',') +
    ' leaf=' + cliPid
  );
  return { success: true, candidates, cliPid, lockPids };
}

function captureAgentInputIdentity(tabId, term) {
  const mirror = getHeadlessTerminalMirror(tabId);
  return {
    terminalToken: term,
    mirrorToken: mirror || null,
    terminalRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
    inputRevision: getTerminalInputRevision(tabId),
    terminalLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    mirrorGeneration: mirror?.generation || null,
    mirrorWriteSeq: mirror?.writeSeq ?? null,
    mirrorFlushedSeq: mirror?.flushedSeq ?? null,
    mirrorSynchronizedOutputOpen: mirror?.redrawTrace?.synchronizedOutputOpen === true,
    synchronizedOutputGeneration: Number(
      mirror?.redrawTrace?.synchronizedOutputGeneration || 0,
    ),
  };
}

function validateAgentInputIdentity(tabId, identity) {
  if (!identity) return false;
  const mirror = getHeadlessTerminalMirror(tabId);
  return terminals.get(tabId) === identity.terminalToken
    && mirror === identity.mirrorToken
    && Number(terminalCommandState.get(tabId)?.runSeq || 0) === identity.terminalRunSeq
    && getTerminalInputRevision(tabId) === identity.inputRevision
    && getTerminalLifecycleGeneration(tabId) === identity.terminalLifecycleGeneration
    && (mirror?.generation || null) === identity.mirrorGeneration;
}

function validateAgentInputFrameIdentity(tabId, identity) {
  if (!validateAgentInputIdentity(tabId, identity)) return false;
  const mirror = getHeadlessTerminalMirror(tabId);
  return Number(mirror?.writeSeq) === Number(identity.mirrorWriteSeq)
    && Number(mirror?.flushedSeq) === Number(identity.mirrorFlushedSeq)
    && (mirror?.redrawTrace?.synchronizedOutputOpen === true)
      === (identity.mirrorSynchronizedOutputOpen === true)
    && Number(mirror?.redrawTrace?.synchronizedOutputGeneration || 0)
      === Number(identity.synchronizedOutputGeneration || 0);
}

function agentDraftProofMatchesCaptureIdentity(proof, identity) {
  if (!proof || !identity) return false;
  const fields = [
    'terminalRunSeq',
    'inputRevision',
    'terminalLifecycleGeneration',
    'mirrorGeneration',
  ];
  const generationMatches = fields.every((field) => (
    proof[field] !== null
    && proof[field] !== undefined
    && proof[field] === identity[field]
  ));
  if (!generationMatches) return false;
  if (proof.proofReason !== 'active-prompt-not-found') return true;
  const frameFields = [
    'mirrorWriteSeq',
    'mirrorFlushedSeq',
    'mirrorSynchronizedOutputOpen',
    'synchronizedOutputGeneration',
  ];
  return frameFields.every((field) => (
    proof[field] !== null
    && proof[field] !== undefined
    && proof[field] === identity[field]
  ));
}

async function dismissCodexSlashCompletionBeforeExternalEditor(
  tabId,
  term,
  draftProof,
  logPrefix,
) {
  const mirror = getHeadlessTerminalMirror(tabId);
  if (!mirror || mirror.complete !== true) {
    return { success: true, dismissed: false, draftProof };
  }

  let before = getHeadlessVisibleBufferSnapshot(
    tabId,
    'codex-external-editor:slash-completion-preflight',
    { preferCommitted: false },
  );
  let completion = inspectCodexSlashCompletionSnapshot(before);
  if (completion.visible !== true) {
    return { success: true, dismissed: false, draftProof };
  }

  const closed = await waitForHeadlessSynchronizedOutputClose(tabId, mirror, 900);
  if (closed.ready !== true) {
    return {
      success: false,
      dismissed: false,
      error: 'codex_slash_completion_frame_unconfirmed',
      reason: closed.reason,
    };
  }
  before = getHeadlessVisibleBufferSnapshot(
    tabId,
    'codex-external-editor:slash-completion-committed',
    { preferCommitted: false },
  );
  completion = inspectCodexSlashCompletionSnapshot(before);
  if (completion.visible !== true) {
    return { success: true, dismissed: false, draftProof };
  }

  const beforeIdentity = captureAgentInputIdentity(tabId, term);
  if (!validateAgentInputIdentity(tabId, beforeIdentity)) {
    return {
      success: false,
      dismissed: false,
      error: 'codex_slash_completion_identity_changed',
    };
  }

  const ownedInputRevision = bumpTerminalInputRevision(tabId);
  const escapeIdentity = captureAgentInputIdentity(tabId, term);
  if (
    escapeIdentity.inputRevision !== ownedInputRevision
    || !validateAgentInputIdentity(tabId, escapeIdentity)
  ) {
    return {
      success: false,
      dismissed: false,
      error: 'codex_slash_completion_identity_changed',
    };
  }

  console.log(logPrefix + ' Tab ' + tabId.slice(-12)
    + ': slash completion owns Ctrl+G; dismissing before external editor'
    + ' draft=' + JSON.stringify(completion.draftText.slice(0, 120))
    + ' suggestions=' + completion.suggestionRows.map((row) => row.command).join(','));
  const observed = await waitForCommittedSemanticFrame({
    subscribe(listener) {
      mirror.synchronizedFrameWaiters.add(listener);
      return () => mirror.synchronizedFrameWaiters.delete(listener);
    },
    readSnapshot() {
      return getHeadlessVisibleBufferSnapshot(
        tabId,
        'codex-external-editor:slash-completion-dismiss',
        { preferCommitted: false },
      );
    },
    inspectSnapshot(snapshot) {
      return inspectCodexSlashCompletionDismissal(snapshot, completion.draftText);
    },
    acceptInspection(inspection) {
      return inspection.dismissed === true && inspection.draftPreserved === true;
    },
    trigger() {
      if (!validateAgentInputIdentity(tabId, escapeIdentity)) {
        throw new Error('codex_slash_completion_identity_changed');
      }
      recordComposerForensicPtyInput(tabId, '\x1b', {
        kind: 'escape',
        phase: 'pty-write-attempt',
        origin: 'agent-input-capture',
        source: 'codex-slash-completion-dismiss',
        operationKind: 'agent-input-capture',
        checkpoint: true,
      });
      term.write('\x1b');
    },
    getAbortReason() {
      if (!validateAgentInputIdentity(tabId, escapeIdentity)) {
        return 'codex_slash_completion_identity_changed';
      }
      if (getHeadlessTerminalMirror(tabId) !== mirror) {
        return 'codex_slash_completion_mirror_changed';
      }
      if (mirror.failed === true) return 'codex_slash_completion_mirror_failed';
      return null;
    },
    afterWriteSeq: before.writeSeq,
    timeoutMs: 1800,
  });

  if (observed.ready !== true) {
    const inspection = observed.lastInspection || null;
    const error = inspection && inspection.draftPreserved === false
      ? 'codex_slash_draft_changed_during_dismiss'
      : 'codex_slash_completion_dismiss_unconfirmed';
    console.warn(logPrefix + ' Tab ' + tabId.slice(-12)
      + ': slash completion dismiss failed reason=' + observed.reason
      + ' error=' + error
      + ' draftPreserved=' + (inspection?.draftPreserved === true)
      + ' stillVisible=' + (inspection?.completion?.visible === true));
    return {
      success: false,
      dismissed: false,
      error,
      reason: observed.reason,
    };
  }

  const rebasedDraftProof = decorateAgentDraftProofIdentity(tabId, {
    ...(draftProof || {}),
    success: true,
    hasDraft: true,
    proofOutcome: 'found',
    proofReason: 'codex-slash-completion-dismissed-draft-preserved',
    source: 'headless-main:slash-completion-dismissed',
    preview: completion.draftText.slice(0, 160),
    promptRow: observed.inspection?.completion?.promptRow ?? null,
  });
  console.log(logPrefix + ' Tab ' + tabId.slice(-12)
    + ': slash completion dismissed; draft preserved'
    + ' writeSeq=' + observed.writeSeq
    + ' inputRevision=' + rebasedDraftProof.inputRevision);
  return {
    success: true,
    dismissed: true,
    draftProof: rebasedDraftProof,
  };
}

function validateAgentExactCaptureInputTransition(pending) {
  const before = pending?.draftProofCaptureIdentity;
  const after = pending?.captureIdentity;
  if (
    pending?.draftProofIdentityAtWrite !== true
    || !before
    || !after
    || !agentDraftProofMatchesCaptureIdentity(pending?.draftProof, before)
  ) return false;
  return before.terminalToken === after.terminalToken
    && before.mirrorToken === after.mirrorToken
    && before.terminalRunSeq === after.terminalRunSeq
    && before.terminalLifecycleGeneration === after.terminalLifecycleGeneration
    && before.mirrorGeneration === after.mirrorGeneration
    && Number.isFinite(Number(before.inputRevision))
    && Number(after.inputRevision) === Number(before.inputRevision) + 1;
}

function publicAgentInputIdentity(identity, stable) {
  return {
    terminalIdentityStable: stable === true,
    terminalRunSeq: identity?.terminalRunSeq ?? null,
    inputRevision: identity?.inputRevision ?? null,
    terminalLifecycleGeneration: identity?.terminalLifecycleGeneration ?? null,
    mirrorGeneration: identity?.mirrorGeneration ?? null,
    mirrorWriteSeq: identity?.mirrorWriteSeq ?? null,
    mirrorFlushedSeq: identity?.mirrorFlushedSeq ?? null,
    mirrorSynchronizedOutputOpen: identity?.mirrorSynchronizedOutputOpen === true,
    synchronizedOutputGeneration: identity?.synchronizedOutputGeneration ?? null,
  };
}

// Shared by claude/codex grab/copy/restore input operations. All fire Ctrl+G
// after writing a lock-file telling noted-code-grab.js which mode to run in.
async function captureAgentInputAtWriteBoundary(
  tabId,
  mode,
  agent = 'claude',
  options = {},
  ownedTerm = null,
) {
  const term = ownedTerm || terminals.get(tabId);
  if (!term) return { success: false, error: 'no_terminal' };
  if (terminals.get(tabId) !== term) {
    return { success: false, error: 'terminal_generation_changed' };
  }
  // Internal operation owners (not renderer-provided proofs) may retain a
  // stricter boundary, e.g. the already-written Native Rewind being resumed.
  if (typeof options.captureGuard === 'function' && !options.captureGuard()) {
    return { success: false, error: 'capture_operation_scope_changed', draftPreserved: true };
  }
  // Codex's startup draft can accept paste while ignoring Ctrl+G. It is not
  // the initialized composer. Do not create an ambiguous editor intent there;
  // a previously initialized composer remains eligible during a busy turn.
  if (agent === 'codex' && !isCodexTuiEffectivelyReady(tabId)) {
    return { success: false, error: 'codex_input_not_ready', draftPreserved: true };
  }

  const logPrefix = agent === 'claude'
    ? '[capture-input:' + mode + ']'
    : '[capture-input:' + agent + ':' + mode + ']';

  let cliPid = null;
  let lockPids = [];
  const processResolution = await resolveAgentInputProcess(tabId, agent, logPrefix);
  if (!processResolution.success) return processResolution;
  cliPid = processResolution.cliPid;
  lockPids = processResolution.lockPids;

  // This identity belongs to the screen proof that authorized the capture.
  // Ctrl+G itself is an input mutation, so the identity returned to callers is
  // captured separately after we reserve the new input revision below.
  let draftProofCaptureIdentity = captureAgentInputIdentity(tabId, term);
  let draftProof = options?.draftProof && typeof options.draftProof === 'object'
    ? options.draftProof
    : null;
  let draftProofMatchesAtCapture = draftProof
    ? agentDraftProofMatchesCaptureIdentity(draftProof, draftProofCaptureIdentity)
    : null;
  if (draftProof && !draftProofMatchesAtCapture) {
    console.warn(logPrefix + ' Tab ' + tabId.slice(-12)
      + ': screen proof identity changed before Ctrl+G; grab may preserve a real draft but cannot authorize empty');
  }

  if (cliPid) {
    // Verify the cached PID still maps to a live process. If user restarted Claude in shell
    // (Ctrl+C → claude --resume) without going through our Bridge:Fresh path, bridgePidCache
    // holds a dead PID — the lock-file would be written under the dead PID's name and the
    // live CLI would never find it. Result: silent timeout → "Helper not reachable".
    let alive = true;
    try { process.kill(cliPid, 0); } catch (e) { if (e.code === 'ESRCH') alive = false; }
    if (!alive) {
      console.warn(logPrefix + ' Tab ' + tabId.slice(-12) + ': stale ' + agent + 'Pid=' + cliPid + ' (process gone)');
      return { success: false, error: 'stale_pid', pid: cliPid };
    }
    const editor = await readProcessEditor(cliPid);
    if (!editor || !editor.includes(CAPTURE_HELPER_BASENAME)) {
      console.warn(logPrefix + ' Tab ' + tabId.slice(-12) + ': wrong EDITOR=' + editor + ' — restart ' + agent + ' in this tab');
      return { success: false, error: 'wrong_editor', editor };
    }
  }

  if (grabInputPending.has(tabId)) {
    const previous = grabInputPending.get(tabId);
    const terminalRetired = previous.captureIdentity?.terminalToken !== term;
    const helperReturned = agentInputCaptureProtocol.reconcileReturned(previous.captureOperation);
    if (terminalRetired || helperReturned) {
      if (terminalRetired) releaseAgentInputCapturePending(tabId, previous, { processRetired: true });
      else if (grabInputPending.get(tabId) === previous) grabInputPending.delete(tabId);
      clearTimeout(previous.timer);
      previous.resolve({ success: false, error: 'capture_operation_cancelled', draftPreserved: true });
    } else {
      return {
        success: false,
        error: previous.timedOut ? 'external_editor_pending_drain' : 'already_in_progress',
        operationId: previous.captureOperation.operationId,
      };
    }
  }
  if (agent === 'codex') {
    const slashCompletion = await dismissCodexSlashCompletionBeforeExternalEditor(
      tabId,
      term,
      draftProof,
      logPrefix,
    );
    if (slashCompletion.success !== true) return slashCompletion;
    if (slashCompletion.dismissed === true) {
      draftProof = slashCompletion.draftProof;
      draftProofCaptureIdentity = captureAgentInputIdentity(tabId, term);
      draftProofMatchesAtCapture = draftProof
        ? agentDraftProofMatchesCaptureIdentity(draftProof, draftProofCaptureIdentity)
        : null;
    }
  }
  const isClaudeMissingPromptCapture = agent === 'claude'
    && draftProof?.proofOutcome === 'unknown'
    && draftProof?.proofReason === 'active-prompt-not-found';
  if (isClaudeMissingPromptCapture) {
    const currentSnapshot = getHeadlessVisibleBufferSnapshot(
      tabId,
      'before-missing-prompt-exact-capture',
      { preferCommitted: false },
    );
    const currentProof = currentSnapshot?.success === true
      ? parseClaudeDraftFromVisibleSnapshot(currentSnapshot)
      : {
          proofOutcome: 'unknown',
          proofReason: 'headless-current-frame-unavailable',
        };
    const admission = classifyClaudeMissingPromptCaptureForTab(
      tabId,
      currentSnapshot,
      currentProof,
      options?.ownedWriteOperation || null,
    );
    const exactFrameStillCurrent = draftProofMatchesAtCapture === true
      && validateAgentInputFrameIdentity(tabId, draftProofCaptureIdentity);
    if (admission.recommended !== true || !exactFrameStillCurrent) {
      const blockedReason = !exactFrameStillCurrent
        ? 'claude-current-frame-changed-before-exact-capture'
        : admission.reason;
      console.warn(logPrefix + ' Tab ' + tabId.slice(-12)
        + ': missing-prompt exact capture refused reason=' + blockedReason);
      return {
        success: false,
        error: 'claude_draft_state_unknown_before_paste',
        proofReason: blockedReason,
      };
    }
  }
  const draftProofMatchesAtWrite = draftProof
    ? draftProofMatchesAtCapture === true
      && validateAgentInputIdentity(tabId, draftProofCaptureIdentity)
      && (!isClaudeMissingPromptCapture
        || validateAgentInputFrameIdentity(tabId, draftProofCaptureIdentity))
    : null;
  if (draftProof && !draftProofMatchesAtWrite) {
    console.warn(logPrefix + ' Tab ' + tabId.slice(-12)
      + ': terminal identity changed before Ctrl+G write; exact-empty override disabled');
  }
  // Intentionally do NOT pre-block on claudeSpinnerBusy: Claude's Ctrl+G
  // binding works mid-stream as long as there is a draft in the input box —
  // that's the whole point of the queue (grab + queue while Claude is still
  // typing). Only block when the Stop-hook actually reports turn-in-flight,
  // because in that very narrow window Ctrl+G IS a no-op. If timeout fires,
  // the warn-log below classifies the cause (turn/spinner/silent helper) so
  // the toast can be honest.

  // Arm an immutable request before Ctrl+G. Timeout cancels this request but
  // does NOT remove it: an editor process starting a few milliseconds later
  // must still know that the app, not the user, requested this invocation.
  if (lockPids.length === 0) {
    console.warn(logPrefix + ' Tab ' + tabId.slice(-12) + ': no ' + agent + ' PID — cannot write lock');
    return { success: false, error: 'no_' + agent + '_pid' };
  }
  if (terminals.get(tabId) !== term) return { success: false, error: 'terminal_generation_changed' };
  if (typeof options.captureGuard === 'function' && !options.captureGuard()) {
    return { success: false, error: 'capture_operation_scope_changed', draftPreserved: true };
  }
  if (agent === 'codex' && !isCodexTuiEffectivelyReady(tabId)) {
    return { success: false, error: 'codex_input_not_ready', draftPreserved: true };
  }
  let captureOperation;
  try {
    captureOperation = agentInputCaptureProtocol.arm({
      tabId,
      terminalId: term._notedGrabTerminalId,
      agent,
      mode,
      pids: lockPids,
      sock: CLAUDE_HOOK_SOCK,
      generation: publicAgentInputIdentity(captureAgentInputIdentity(tabId, term), true),
      text: options.text,
    });
  } catch (error) {
    console.warn(logPrefix + ' capture arm failed:', error.message);
    return {
      success: false,
      error: error.message === 'external_editor_pending_drain' ? error.message : 'lock_write_failed',
      ...(error.operationId ? { operationId: error.operationId } : {}),
    };
  }

  // Ctrl+G is a real composer mutation. Reserve its revision only after the
  // helper contract is armed and immediately before the serialized PTY write:
  // a capture queued behind a paste must not invalidate that paste before it
  // submits, while a later paste must never reuse proof captured before this
  // external-editor roundtrip.
  const ownedInputRevision = bumpTerminalInputRevision(tabId);
  const captureIdentity = captureAgentInputIdentity(tabId, term);
  if (captureIdentity.inputRevision !== ownedInputRevision) {
    agentInputCaptureProtocol.cancel(captureOperation, 'terminal_input_ownership_changed');
    agentInputCaptureProtocol.release(captureOperation, { processRetired: true });
    return { success: false, error: 'terminal_input_ownership_changed' };
  }
  try {
    options.onCaptureArmed?.(captureOperation, captureIdentity);
  } catch (error) {
    agentInputCaptureProtocol.cancel(captureOperation, 'capture_owner_persist_failed');
    agentInputCaptureProtocol.release(captureOperation, { processRetired: true });
    return { success: false, error: error?.message || 'capture_owner_persist_failed', draftPreserved: true };
  }

  return new Promise((resolve) => {
    let settled = false;
    const settle = result => {
      if (settled) return;
      settled = true;
      try { options.onCaptureResult?.(result); }
      catch (error) {
        console.error('[RewindPostEnter] capture result persistence failed:', error);
        result = { ...result, success: false, error: 'capture_result_persist_failed', pending: true };
      }
      resolve(result);
    };
    const pending = {
      resolve: settle,
      timer: null,
      captureOperation,
      captureRequestId: typeof options.captureRequestId === 'string' ? options.captureRequestId : null,
      mode,
      agent,
      pid: cliPid,
      pids: lockPids,
      captureIdentity,
      draftProofCaptureIdentity,
      draftProof,
      prepareOwnedDraft: typeof options.prepareOwnedDraft === 'function' ? options.prepareOwnedDraft : null,
      preserveOutcomeBeforeRelease: typeof options.preserveOutcomeBeforeRelease === 'function'
        ? options.preserveOutcomeBeforeRelease : null,
      draftProofIdentityAtWrite: draftProofMatchesAtWrite,
      draftProofDiagnostic: draftProof
        ? buildHeadlessDraftProofDiagnostic(tabId, draftProof, 'before-exact-empty-grab')
        : null,
    };
    if (pending.prepareOwnedDraft) {
      let prepared = null;
      Object.defineProperty(pending, 'preparedDraft', {
        enumerable: true,
        get: () => prepared,
        set: draft => {
          // The helper callback stages this value before granting clear.
          // Preserve it even if a later return barrier/request times out.
          pending.prepareOwnedDraft(draft, { captureOperation, helperId: pending.helperId });
          prepared = draft;
        },
      });
    }
    const timer = setTimeout(() => {
      if (grabInputPending.get(tabId) !== pending) return;
      const decision = agentInputCaptureProtocol.cancel(captureOperation, 'external_editor_timeout');
      if (decision.decision === 'commit') return; // authorized callback owns the return barrier
      pending.timedOut = true;
      const helperReturned = agentInputCaptureProtocol.reconcileReturned(captureOperation);
      if (helperReturned && grabInputPending.get(tabId) === pending) grabInputPending.delete(tabId);
      // A timeout is not proof Ctrl+G was ignored. No global log-size heuristic,
      // retry, Escape or newer intent is permitted to guess away this ambiguity.
      console.warn(logPrefix + ' Tab ' + tabId.slice(-12)
        + ': timeout (3000ms), cancellation retained operation=' + captureOperation.operationId
        + ' helperReturned=' + helperReturned + ' pid=' + cliPid);
      settle({ success: false, error: 'external_editor_timeout', draftPreserved: true, operationId: captureOperation.operationId });
    }, 3000);
    pending.timer = timer;
    grabInputPending.set(tabId, pending);
    console.log(logPrefix + ' Tab ' + tabId.slice(-12) + ': sending Ctrl+G pid=' + cliPid
      + ' operation=' + captureOperation.operationId + ' lockPids=' + lockPids.join(','));
    recordComposerForensicPtyInput(tabId, '\x07', {
      kind: 'ctrl-g',
      phase: 'pty-write-attempt',
      origin: 'agent-input-capture',
      source: agent + ':' + mode + '-input',
      operationKind: 'agent-input-capture',
      checkpoint: true,
    });
    try {
      term.write('\x07'); // Ctrl+G → chat:externalEditor
    } catch (error) {
      clearTimeout(timer);
      pending.timedOut = true;
      agentInputCaptureProtocol.cancel(captureOperation, 'capture_pty_write_failed');
      settle({ success: false, error: 'capture_pty_write_failed', draftPreserved: true });
    }
  });
}

async function captureAgentInput(tabId, mode, agent = 'claude', options = {}) {
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no_terminal' };
  const operation = {
    kind: 'agent-input-capture',
    source: agent + ':' + mode + '-input',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: false,
    queuedAt: Date.now(),
  };
  return withPtyWriteLock(
    term,
    () => captureAgentInputAtWriteBoundary(
      tabId,
      mode,
      agent,
      { ...options, ownedWriteOperation: operation },
      term,
    ),
    operation,
  );
}

async function captureClaudeInput(tabId, mode) {
  return captureAgentInput(tabId, mode, 'claude');
}

async function restoreAgentInput(tabId, text, agent = 'claude') {
  if (typeof text !== 'string') return { success: false, error: 'invalid_text' };
  return captureAgentInput(tabId, 'restore', agent, { text });
}

async function replaceAgentInputIfUnchanged(tabIdValue, expectedText, text, agent) {
  const tabId = String(tabIdValue || '');
  if (
    !tabId
    || (agent !== 'claude' && agent !== 'codex')
    || typeof expectedText !== 'string'
    || typeof text !== 'string'
  ) {
    return { success: false, replaced: false, error: 'invalid_arguments' };
  }
  const term = terminals.get(tabId);
  if (!term) return { success: false, replaced: false, error: 'no_terminal' };
  const operation = {
    kind: 'agent-input-compare-and-swap',
    source: agent + ':replace-input-if-unchanged',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: false,
    queuedAt: Date.now(),
  };
  return withPtyWriteLock(term, () => replaceAgentInputIfUnchangedAtBoundary({
    expectedText,
    replacementText: text,
    capture: () => captureAgentInputAtWriteBoundary(
      tabId,
      'copy',
      agent,
      {},
      term,
    ),
    restore: replacement => captureAgentInputAtWriteBoundary(
      tabId,
      'restore',
      agent,
      { text: replacement },
      term,
    ),
    isCurrent: () => terminals.get(tabId) === term,
  }), operation);
}

