ipcMain.handle('claude:send-prompt-with-settings', async (_event, request = {}) => {
  if (!request.tabId || typeof request.content !== 'string' || !request.content.trim()) {
    return { success: false, submitted: false, error: 'tabId and prompt required' };
  }
  try {
    return await claudeSettingsSendRuntime.sendPrompt({
      tabId: request.tabId,
      content: request.content,
      model: request.model,
      effort: request.effort,
      thinking: request.thinking,
      handoffId: request.handoffId || null,
      sendAttemptId: request.sendAttemptId || null,
      sendOperationKey: request.sendOperationKey || null,
      expectedTarget: request.expectedTarget || null,
      source: request.source || 'claude-settings-send',
      claudeExactEmptyEvidence: request.claudeExactEmptyEvidence || null,
      presentationSnapshot: request.presentationSnapshot || null,
      submit: true,
      fast: false,
      verifyClaudeVisibleDraftBeforePaste: true,
      awaitClaudeUserMessageAudit: true,
      logPrefix: '[ClaudeSettingsSend:' + request.tabId + ']',
    });
  } catch (error) {
    console.warn('[ClaudeSettingsSend] failed tab=' + request.tabId + ' error=' + (error?.message || error));
    // sendPrompt returns a typed negative receipt when it proves the user
    // prompt has not reached paste(). A thrown error has no such proof: the
    // physical Enter or its deferred audit may already have happened. Return
    // the uncertainty as IPC data, not an Error whose receipt fields Electron
    // may strip. In particular, an Enter-armed durable attempt must not become
    // retryable merely because this outer handler lost the transport result.
    return {
      success: null,
      accepted: true,
      submitted: null,
      status: 'delivery-unknown',
      deliveryUnknown: true,
      code: 'claude_settings_send_delivery_unknown',
      error: error?.message || String(error),
      handoffId: request.handoffId || null,
      tabId: request.tabId,
    };
  }
});

// PromptQueue replay (▶ chip button): paste text into Claude's input WITHOUT
// stashing the user's current draft. Default mode does NOT press Enter — user
// reviews and submits manually. Cmd+click passes { submit:true } and behaves
// like "paste, then press Enter" through the same safePasteAndSubmit path.
// Goes through safePasteAndSubmit so bracketed-paste + sync marker logic still
// guarantees Ink ingests the chip atomically (no [Pasted text #N] fragments).
ipcMain.handle('claude:append-input', async (event, tabId, text, options = {}) => {
  const handoffId = options && typeof options.handoffId === 'string' ? options.handoffId : null;
  const source = options && typeof options.source === 'string' ? options.source : null;
  console.log('[append-input] 📩 Received: tabId=' + tabId + ' chars=' + (text || '').length + ' submit=' + !!options?.submit + ' handoff=' + (handoffId || '-') + ' source=' + (source || '-') + ' ts=' + Date.now());
  const term = terminals.get(tabId);
  if (!term) {
    console.log('[append-input] ❌ Terminal not found for tabId=' + tabId);
    return { success: false, error: 'no_terminal' };
  }
  if (!text || typeof text !== 'string') {
    return { success: false, error: 'empty_text' };
  }
  // Hard refusal when Claude isn't running in this tab — overlay is gated by
  // claudeProcessAlive but the IPC can race a Claude exit. Without this guard,
  // bracketed paste lands in a bash/zsh prompt (modern zsh supports bracketed
  // paste mode) → the chip text becomes one shell command-line. Chip starting
  // with "rm -rf" / "sudo …" would execute on the user's machine. Refuse loud.
  //
  // Liveness source = bridgeKnownSessions, NOT claudeCliActive. claudeCliActive
  // means "Claude is PROCESSING right now" and is set ONLY by the explicit spawn
  // paths (claude:run-command, MCP, handshake) — it is empty at an idle prompt
  // and, crucially, is NEVER set when a tab is AutoResumed (App.tsx writes
  // `claude --resume <id>` straight into the PTY via terminal:input; that path
  // populates bridgeKnownSessions through handleSessionDetected but never touches
  // claudeCliActive). Net effect on a resumed/restored tab: auto-run's
  // claude:send-command (no guard) lands fine, but manual Replay ▶ here refused
  // with no_claude_session even though Claude was alive and idle at the prompt.
  // Prod-confirmed tab-5 (59cf2ebf) 2026-06-03 19:34: 4× "Claude not active"
  // from append-input, then send-command paste succeeded 12s later on the SAME
  // live Claude. bridgeKnownSessions is the same liveness check captureClaudeInput
  // (grab/copy) already uses, and it still refuses a pure bash/zsh tab (no bridge
  // session) so the anti-rm-rf intent is preserved. See fact-prompt-queue.md.
  if (!hasLiveClaudeInTab(tabId)) {
    console.log('[append-input] ❌ No live Claude session (bridge/pid) in tab ' + tabId + ' — refusing to paste into non-Claude PTY');
    return { success: false, error: 'no_claude_session' };
  }
  const shouldSubmit = !!(options && options.submit === true);
  const isSlashCommand = String(text || '').trimStart().startsWith('/');
  const awaitClaudeUserMessageAudit = shouldSubmit && !isSlashCommand;
  const result = await safePasteAndSubmit(term, text, {
    submit: shouldSubmit,
    stashFirst: false, // never stash on replay — user wants append, not replace
    ctrlCFirst: false,
    awaitClaudeUserMessageAudit,
    claudeAuditTimeoutMs: CLAUDE_PASTE_AUDIT_TIMEOUT_MS,
    logPrefix: '[append-input:' + tabId + (handoffId ? ':' + handoffId : '') + ']',
    handoffId,
    source,
    presentationSnapshot: options?.presentationSnapshot || null,
  });
  if (result && typeof result === 'object') {
    if (!Object.prototype.hasOwnProperty.call(result, 'submitted')) {
      result.submitted = shouldSubmit;
    }
    result.handoffId = handoffId || null;
  }
  return result;
});

// PromptQueue replay for Codex: same UI contract as Claude replay — paste text
// into Codex input, submit only when renderer passes { submit:true }. Hard
// refusal when there is no live Codex descendant under this PTY, otherwise a
// queued chip could become a shell command.
ipcMain.handle('codex:append-input', async (_event, tabId, text, options = {}) => {
  const requestReceivedAt = nodePerformance.now();
  const shouldSubmit = !!(options && options.submit === true);
  const rawSource = options && typeof options.source === 'string' && options.source.trim()
    ? options.source.trim()
    : 'codex-append-input';
  const codexSource = rawSource.startsWith('codex-') ? rawSource : 'codex-' + rawSource;
  console.log('[codex:append-input] 📩 Received: tabId=' + tabId + ' chars=' + (text || '').length + ' submit=' + shouldSubmit + ' source=' + codexSource + ' ts=' + Date.now());
  const term = terminals.get(tabId);
  if (!term) {
    console.log('[codex:append-input] ❌ Terminal not found for tabId=' + tabId);
    return { success: false, error: 'no_terminal' };
  }
  if (!text || typeof text !== 'string') {
    return { success: false, error: 'empty_text' };
  }
  const result = await safePasteAndSubmit(term, text, {
    submit: shouldSubmit,
    stashFirst: false,
    ctrlCFirst: false,
    fast: false,
    source: codexSource,
    skipRenderWait: true,
    awaitCodexUserMessageAudit: shouldSubmit,
    codexAuditTimeoutMs: CODEX_PASTE_AUDIT_TIMEOUT_MS,
    verifyCodexVisibleDraftBeforeSubmit: shouldSubmit,
    requestReceivedAt,
    presentationSnapshot: options?.presentationSnapshot || null,
    logPrefix: '[codex:append-input:' + tabId + ']',
  });
  if (result && typeof result === 'object'
    && !Object.prototype.hasOwnProperty.call(result, 'submitted')) {
    result.submitted = shouldSubmit;
  }
  return result;
});

// ========== Soniox temporary API key ==========
// Mint a short-lived (5 min) key bound to websocket-transcribe usage. Renderer
// uses this for dictation in Claude PTY/SDK tabs. Mobile-web has its own
// equivalent endpoint (POST /api/soniox-token) in web-server.js.
ipcMain.handle('soniox:mint-token', async () => {
  const key = process.env.SONIOX_API_KEY;
  if (!key) throw new Error('SONIOX_API_KEY not configured');
  const r = await fetch('https://api.soniox.com/v1/auth/temporary-api-key', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ usage_type: 'transcribe_websocket', expires_in_seconds: 300 }),
  });
  if (!r.ok) {
    const txt = await r.text().catch(() => '');
    throw new Error(`soniox ${r.status}: ${txt.slice(0, 200)}`);
  }
  const data = await r.json();
  return { api_key: data.api_key, expires_at: data.expires_at };
});

// ========== LLM Provider Switching (per-tab) ==========
// All three handlers accept (event, { tabId, ... }). tabId is required so that
// switching the provider in one tab does NOT affect any other tab.
// For backward compatibility (legacy call shape without tabId) the change
// applies to the 'global' bucket — used by external Claude spawned without
// /t/<tabId> prefix.
function broadcastProviderState(tabId, state) {
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('provider:state-changed', { tabId: tabId || 'global', state });
  }
  if (tabId) _webBroadcast(tabId, { type: 'params-changed' });
}

ipcMain.handle('provider:switch', (event, opts) => {
  // opts: { tabId, type, model? }
  const tabId = opts?.tabId || null;
  const prev = JSON.stringify(getProviderState(tabId));
  const next = { type: opts.type };
  if (opts.model) next.model = opts.model;
  // Preserve thinking/effort across model switches inside same provider; reset on provider change.
  const oldState = getProviderState(tabId);
  if (oldState.type === next.type) {
    if (oldState.thinking) next.thinking = oldState.thinking;
    if (oldState.effort) next.effort = oldState.effort;
    if (oldState.startupModel) next.startupModel = oldState.startupModel;
    if (oldState.startupEffort) next.startupEffort = oldState.startupEffort;
  }
  if (typeof oldState.codexFastIntent === 'boolean') {
    next.codexFastIntent = oldState.codexFastIntent;
    const fastRevision = Number(oldState.codexFastIntentRevision || 0);
    next.codexFastIntentRevision = Number.isInteger(fastRevision) && fastRevision > 0
      ? fastRevision
      : 1;
  }
  for (const key of [
    'codexSettingsIntentModel',
    'codexSettingsIntentEffort',
    'codexSettingsIntentRevision',
    'codexSettingsIntentAppliedRevision',
    'codexSettingsIntentAppliedOwnerId',
    'codexSettingsIntentActionSequence',
    'codexSettingsIntentScope',
    'codexSettingsIntentNativeProof',
    'codexSettingsIntentSource',
  ]) {
    if (oldState[key] !== undefined && oldState[key] !== null) next[key] = oldState[key];
  }
  setProviderState(tabId, next);
  // Persist to SQLite immediately (real tabs only — skip 'global' bucket which
  // doesn't correspond to a DB row). DB write is synchronous via better-sqlite3,
  // so the row is committed before the IPC handler returns.
  if (tabId && projectManager?.db) {
    projectManager.db.updateTabProviderState(tabId, next);
  }
  console.log('[ProviderProxy] Switched[' + (tabId ? tabId.slice(-12) : 'global') + ']: ' + prev + ' → ' + JSON.stringify(next));
  broadcastProviderState(tabId, next);
  return next;
});

ipcMain.handle('provider:get-status', (event, opts) => {
  // opts: { tabId } | undefined (legacy → global)
  const tabId = opts?.tabId || null;
  return getProviderState(tabId);
});

// Update provider knobs and optional next-launch choices for one tab without
// changing global defaults or provider routing. UI and Terminal MCP share it.
function updateProviderOptionsForTab(tabId, opts) {
  const cur = { ...getProviderState(tabId) };
  if (typeof opts?.thinking === 'string') cur.thinking = opts.thinking;
  if (typeof opts?.effort === 'string') cur.effort = opts.effort;
  if (typeof opts?.startupModel === 'string') cur.startupModel = opts.startupModel;
  if (typeof opts?.startupEffort === 'string') cur.startupEffort = opts.startupEffort;
  setProviderState(tabId, cur);
  if (tabId && projectManager?.db) {
    projectManager.db.updateTabProviderState(tabId, cur);
  }
  console.log('[ProviderProxy] Options[' + (tabId ? tabId.slice(-12) : 'global') + ']: ' + JSON.stringify(cur));
  broadcastProviderState(tabId, cur);
  return cur;
}

ipcMain.handle('provider:set-options', (event, opts) =>
  updateProviderOptionsForTab(opts?.tabId || null, opts));

// Native selections have a dedicated business owner in main. A plain footer,
// config read or renderer-local cache is never a new user intent.
const codexNativeSettingsIntentTracker = createCodexNativeSettingsIntentTracker({
  getScope: getCodexNativeSettingsIntentScope,
  getIntent: getCodexModelEffortIntentRecord,
  commit: commitCodexNativeSettingsIntent,
});

function getCodexNativeSettingsIntentScope(tabId) {
  if (terminalCommandState.get(tabId)?.isRunning !== true) return null;
  const identity = getCurrentCodexServiceTierProofIdentity(tabId);
  const mirror = getHeadlessTerminalMirror(tabId);
  if (identity?.success !== true || !identity.ownerId || !mirror || mirror.complete !== true) return null;
  return { terminal: identity.terminalToken, mirror, ownerId: identity.ownerId,
    runSeq: identity.terminalRunSeq, lifecycleGeneration: identity.terminalLifecycleGeneration,
    inputRevision: getTerminalInputRevision(tabId) };
}

function prepareCodexNativeSettingsIntentInput(tabId, term, data, origin, snapshot = null) {
  if ((origin != null && origin !== 'user' && origin !== 'unknown')
    || (data !== '\r' && data !== '\n')) return null;
  try {
    return codexNativeSettingsIntentTracker.prepare(tabId, { terminal: term, data, origin,
      snapshot: snapshot || getHeadlessVisibleBufferSnapshot(tabId, 'native-settings-enter', { preferCommitted: false }) });
  } catch (error) {
    console.warn('[CodexNativeSettingsIntent] input proof unavailable tab=' + String(tabId).slice(-12)
      + ' error=' + (error?.message || error));
    return null;
  }
}

function markCodexNativeSettingsIntentInputWritten(tabId, candidate) {
  if (!candidate) return false;
  return codexNativeSettingsIntentTracker.written(tabId, candidate);
}

function observeCodexNativeSettingsIntentOutput(tabId, data, term) {
  codexNativeSettingsIntentTracker.output(tabId, term, data);
}

function observeCodexNativeSettingsIntentFrame(tabId, mirror, snapshot) {
  try {
    return codexNativeSettingsIntentTracker.frame(tabId, mirror, snapshot);
  } catch (error) {
    console.warn('[CodexNativeSettingsIntent] commit failed tab=' + String(tabId).slice(-12)
      + ' error=' + (error?.message || error));
    return null;
  }
}

function commitCodexNativeSettingsIntent(tabId, observation) {
  const current = getCodexModelEffortIntentRecord(tabId);
  const planned = planCodexNativeModelEffortIntent(current, observation);
  if (!planned.valid) return { success: false, reason: planned.reason };
  const ownState = providerStates.get(tabId) || { type: 'anthropic' };
  const conversationOnly = observation.applicationMode === 'conversation-only';
  const ownerId = observation.scope.ownerId;
  const proof = { source: observation.proof, ownerId, confirmedAt: observation.confirmedAt,
    runSeq: observation.scope.runSeq, lifecycleGeneration: observation.scope.lifecycleGeneration,
    inputRevision: observation.scope.inputRevision, writeSeq: observation.writeSeq };
  const next = { ...ownState, codexSettingsIntentModel: planned.model,
    codexSettingsIntentEffort: planned.effort, codexSettingsIntentRevision: planned.revision,
    codexSettingsIntentAppliedRevision: planned.revision, codexSettingsIntentAppliedOwnerId: ownerId,
    codexSettingsIntentActionSequence: Number(ownState.codexSettingsIntentActionSequence || 0) + 1,
    codexSettingsIntentSource: 'native-picker', codexSettingsIntentNativeProof: proof,
    codexSettingsIntentError: null,
    codexSettingsIntentStateVersion: Number(ownState.codexSettingsIntentStateVersion || 0) + 1 };
  if (conversationOnly) {
    next.codexSettingsIntentScope = { ownerId, runSeq: proof.runSeq, lifecycleGeneration: proof.lifecycleGeneration };
  } else delete next.codexSettingsIntentScope;
  let persistenceError = null;
  try {
    const db = projectManager?.db;
    const row = db?.db?.prepare('SELECT project_id FROM tabs WHERE tab_id = ? LIMIT 1').get(tabId);
    if (!row?.project_id || !db?.updateTabProviderState) throw new Error('native-settings-tab-persistence-unavailable');
    const persist = () => {
      db.updateTabProviderState(tabId, next);
      // This legacy DB method logs and swallows write errors. Verify its exact
      // row inside the same transaction before claiming B survives a restart.
      const stored = db.db.prepare('SELECT provider_state FROM tabs WHERE project_id = ? AND tab_id = ? LIMIT 1')
        .get(row.project_id, tabId);
      if (stored?.provider_state !== JSON.stringify(next)) throw new Error('native-settings-intent-persistence-unconfirmed');
      if (!conversationOnly && db.updateTabCodexSettings(row.project_id, tabId, {
        model: planned.model, effort: planned.effort, proofAt: observation.confirmedAt,
        proofSessionId: ownerId.startsWith('launch:') || ownerId.startsWith('terminal-run:') ? null : ownerId,
      }) !== true) throw new Error('native-settings-tab-persistence-failed');
    };
    if (typeof db.db.transaction === 'function') db.db.transaction(persist)();
    else persist();
  } catch (error) {
    persistenceError = error?.message || String(error);
    next.codexSettingsIntentError = 'native-settings-persistence-failed: ' + persistenceError;
  }
  // Native B is already applied even if disk persistence failed. Preserve that
  // fact in memory/UI; never roll it back or replay keys to repair a DB error.
  setProviderState(tabId, next);
  const result = { success: !persistenceError, applied: true, queued: false, intentPending: false,
    model: planned.model, effort: planned.effort, applicationMode: observation.applicationMode,
    applicationProofSource: observation.proof, proofAt: observation.confirmedAt,
    codexSettingsProofSessionId: ownerId.startsWith('launch:') || ownerId.startsWith('terminal-run:') ? null : ownerId,
    ...(ownerId.startsWith('launch:') ? { codexProvisionalSettingsOwnerId: ownerId } : {}),
    intentRevision: planned.revision, providerState: next, persistenceSaved: !persistenceError,
    ...(persistenceError ? { error: next.codexSettingsIntentError } : {}) };
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:model-effort-intent-applied', {
      tabId, model: planned.model, effort: planned.effort, revision: planned.revision, result,
    });
  }
  broadcastProviderState(tabId, next);
  if (ownerId.startsWith('launch:')) {
    armCodexCurrentLaunchSettingsProof(tabId, { model: planned.model, effort: planned.effort,
      proof: observation.proof }, { expectedLaunchId: ownerId.slice(7),
      expectedTerminal: observation.scope.terminal, expectedRunSeq: observation.scope.runSeq });
  }
  if (conversationOnly) {
    void refreshCodexNativeConversationFallback(tabId, observation, {
      revision: planned.revision, actionSequence: next.codexSettingsIntentActionSequence,
      result,
    });
  }
  console.log('[CodexNativeSettingsIntent] applied tab=' + String(tabId).slice(-12)
    + ' model=' + planned.model + ' effort=' + planned.effort + ' mode=' + observation.applicationMode
    + ' revision=' + planned.revision + ' persisted=' + !persistenceError);
  return result;
}

async function refreshCodexNativeConversationFallback(tabId, observation, expected) {
  try {
    const fallback = await readCodexPersistentModelEffortProofForTab(tabId);
    const current = getCodexModelEffortIntentRecord(tabId);
    const scope = getCodexNativeSettingsIntentScope(tabId);
    if (fallback?.success !== true || fallback.effort === 'ultra'
      || !current || current.revision !== expected.revision || current.actionSequence !== expected.actionSequence
      || !scope || scope.terminal !== observation.scope.terminal || scope.ownerId !== observation.scope.ownerId
      || scope.runSeq !== observation.scope.runSeq || scope.lifecycleGeneration !== observation.scope.lifecycleGeneration
      || codexNativeSettingsIntentTracker.hasPending(tabId)
      || (fallback.codexSettingsProofSessionId && fallback.codexSettingsProofSessionId !== scope.ownerId)) return;
    const row = projectManager?.db?.db?.prepare('SELECT project_id FROM tabs WHERE tab_id = ? LIMIT 1').get(tabId);
    if (!row?.project_id || projectManager.db.updateTabCodexSettings(row.project_id, tabId, {
      model: fallback.model, effort: fallback.effort, proofAt: Date.now(), proofSessionId: null,
    }) !== true) throw new Error('native-conversation-fallback-persistence-failed');
    // This is the existing future-process fallback, never a superseding user
    // choice. The exact live Ultra overlay and its operation intent stay intact.
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('codex:model-effort-intent-applied', {
        tabId, model: current.model, effort: current.effort, revision: current.revision,
        result: { ...expected.result, providerState: current.providerState,
          persistentModel: fallback.model, persistentEffort: fallback.effort },
      });
    }
  } catch (error) {
    console.warn('[CodexNativeSettingsIntent] fallback unavailable tab=' + String(tabId).slice(-12)
      + ' error=' + (error?.message || error));
  }
}

function retireCodexScopedModelEffortIntent(tabId, reason = 'runtime-check') {
  const current = getCodexModelEffortIntentRecord(tabId);
  const owned = current?.scope;
  // Unapplied choices (including Ultra selected while stopped) have no scope
  // yet and remain queued for their first native application.
  if (!owned || current.appliedRevision !== current.revision) return false;
  const command = terminalCommandState.get(tabId);
  const lifecycle = getTerminalLifecycleGeneration(tabId);
  const scope = getCodexNativeSettingsIntentScope(tabId);
  const differentKnownOwner = scope?.ownerId && !scope.ownerId.startsWith('terminal-run:')
    && scope.ownerId !== owned.ownerId;
  if (terminals.has(tabId) && command?.isRunning !== false
    && (!lifecycle || lifecycle === owned.lifecycleGeneration)
    && (!Number(command?.runSeq) || Number(command.runSeq) === owned.runSeq)
    && !differentKnownOwner) return false;
  const next = { ...current.providerState,
    codexSettingsIntentStateVersion: Number(current.providerState.codexSettingsIntentStateVersion || 0) + 1 };
  for (const key of ['codexSettingsIntentModel', 'codexSettingsIntentEffort', 'codexSettingsIntentRevision',
    'codexSettingsIntentAppliedRevision', 'codexSettingsIntentAppliedOwnerId', 'codexSettingsIntentScope',
    'codexSettingsIntentNativeProof', 'codexSettingsIntentSource', 'codexSettingsIntentError']) delete next[key];
  // Retire only the completed operation. Resume/Fork continue to restore
  // Ultra from exact source-settings proof; fresh threads keep their persistent
  // non-Ultra fallback. No rollout or per-tab model/effort value is rewritten.
  setProviderState(tabId, next);
  try { projectManager?.db?.updateTabProviderState(tabId, next); }
  catch (error) { console.warn('[CodexSettingsIntent] retirement persistence failed tab='
    + String(tabId).slice(-12) + ' error=' + (error?.message || error)); }
  broadcastProviderState(tabId, next);
  console.log('[CodexSettingsIntent] conversation operation retired tab=' + String(tabId).slice(-12)
    + ' owner=' + owned.ownerId + ' reason=' + reason);
  return true;
}

function getCodexModelEffortIntentRecord(tabId) {
  const state = providerStates.get(tabId) || null;
  if (!state) return null;
  const model = String(state.codexSettingsIntentModel || '').trim();
  const effort = String(state.codexSettingsIntentEffort || '').trim().toLowerCase();
  const revision = Number(state.codexSettingsIntentRevision || 0);
  if (!model || !effort || !Number.isInteger(revision) || revision <= 0) return null;
  return {
    model,
    effort,
    revision,
    appliedRevision: Number(state.codexSettingsIntentAppliedRevision || 0),
    appliedOwnerId: String(state.codexSettingsIntentAppliedOwnerId || '').trim() || null,
    actionSequence: Number(state.codexSettingsIntentActionSequence || 0),
    scope: state.codexSettingsIntentScope || null,
    providerState: state,
  };
}

function persistCodexModelEffortIntent(tabId, model, effort, source = 'explicit', control = 'model') {
  retireCodexScopedModelEffortIntent(tabId, 'before-explicit-selection');
  const ownState = providerStates.get(tabId) || { type: 'anthropic' };
  const intent = nextCodexModelEffortIntent({
    currentModel: ownState.codexSettingsIntentModel,
    currentEffort: ownState.codexSettingsIntentEffort,
    currentRevision: ownState.codexSettingsIntentRevision,
    model,
    effort,
  });
  if (!intent.valid) return { success: false, error: intent.reason };
  const nativePending = codexNativeSettingsIntentTracker.hasPending(tabId);
  const mirror = getHeadlessTerminalMirror(tabId);
  const frame = mirror?.lastCommittedVisibleSnapshot;
  const footer = frame?.authoritativeFrameCommitted === true && frame.writeSeq === mirror?.writeSeq
    ? parseCodexVerifiedComposerFooter((frame.lines || []).map(line => String(line?.text || '')).join('\n')) : null;
  // This explicit UI action already chose the pair. A contrary footer only
  // refutes the old "applied" marker; it never creates a different user intent.
  const currentPairContradicts = footer && (footer.model !== intent.model || footer.effort !== intent.effort);
  const next = {
    ...ownState,
    codexSettingsIntentModel: intent.model,
    codexSettingsIntentEffort: intent.effort,
    codexSettingsIntentRevision: intent.revision,
    codexSettingsIntentControl: ['model', 'effort', 'quick'].includes(control) ? control : 'model',
    codexSettingsIntentError: null,
    codexSettingsIntentActionSequence: Number(ownState.codexSettingsIntentActionSequence || 0) + 1,
    codexSettingsIntentSource: source,
    codexSettingsIntentStateVersion: Number(ownState.codexSettingsIntentStateVersion || 0) + 1,
  };
  if (intent.changed || nativePending || currentPairContradicts) {
    delete next.codexSettingsIntentAppliedRevision;
    delete next.codexSettingsIntentAppliedOwnerId;
  }
  if (intent.changed || intent.effort !== 'ultra') delete next.codexSettingsIntentScope;
  delete next.codexSettingsIntentNativeProof;
  setProviderState(tabId, next);
  if (projectManager?.db) projectManager.db.updateTabProviderState(tabId, next);
  broadcastProviderState(tabId, next);
  console.log('[CodexSettingsIntent] saved tab=' + String(tabId).slice(-12)
    + ' model=' + intent.model
    + ' effort=' + intent.effort
    + ' revision=' + intent.revision
    + ' source=' + source);
  return {
    success: true,
    changed: intent.changed,
    model: intent.model,
    effort: intent.effort,
    revision: intent.revision,
    providerState: next,
  };
}

function markCodexModelEffortIntentApplied(tabId, intent, ownerId, source = 'picker', { publish = true } = {}) {
  const current = getCodexModelEffortIntentRecord(tabId);
  if (!current
    || current.revision !== intent.revision
    || current.actionSequence !== Number(intent.actionSequence || 0)
    || current.model !== intent.model
    || current.effort !== intent.effort) {
    return { applied: false, reason: 'newer-intent-present', providerState: current?.providerState || null };
  }
  const next = {
    ...current.providerState,
    codexSettingsIntentAppliedRevision: intent.revision,
    codexSettingsIntentAppliedOwnerId: ownerId,
    codexSettingsIntentError: null,
    codexSettingsIntentStateVersion: Number(current.providerState.codexSettingsIntentStateVersion || 0) + 1,
  };
  if (intent.effort === 'ultra') {
    next.codexSettingsIntentScope = { ownerId,
      runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
      lifecycleGeneration: getTerminalLifecycleGeneration(tabId) };
  } else delete next.codexSettingsIntentScope;
  setProviderState(tabId, next);
  if (projectManager?.db) projectManager.db.updateTabProviderState(tabId, next);
  if (publish) broadcastProviderState(tabId, next);
  console.log('[CodexSettingsIntent] applied tab=' + String(tabId).slice(-12)
    + ' model=' + intent.model
    + ' effort=' + intent.effort
    + ' revision=' + intent.revision
    + ' owner=' + String(ownerId || '-').slice(0, 8)
    + ' source=' + source);
  return { applied: true, providerState: next };
}

function updateCodexSettingsIntentError(tabId, revision, error, actionSequence = null) {
  const current = getCodexModelEffortIntentRecord(tabId);
  if (!current || current.revision !== revision
    || (actionSequence !== null && current.actionSequence !== actionSequence)
    || current.providerState.codexSettingsIntentError === error) return;
  const next = { ...current.providerState, codexSettingsIntentError: error,
    codexSettingsIntentStateVersion: Number(current.providerState.codexSettingsIntentStateVersion || 0) + 1 };
  setProviderState(tabId, next);
  if (projectManager?.db) projectManager.db.updateTabProviderState(tabId, next);
  broadcastProviderState(tabId, next);
}

function scheduleCodexModelEffortIntentReconcile(tabId, reason = 'scheduled', sender = null) {
  if (tabId) retireCodexScopedModelEffortIntent(tabId, reason);
  if (!tabId || !getCodexModelEffortIntentRecord(tabId)) return null;
  const existing = codexModelEffortIntentReconcileInflight.get(tabId) || null;
  if (existing) {
    codexModelEffortIntentReconcileRequested.add(tabId);
    return existing;
  }
  let observedRevision = null;
  let observedActionSequence = null;
  const work = (async () => {
    for (let pass = 0; pass < 4; pass += 1) {
      const intent = getCodexModelEffortIntentRecord(tabId);
      if (!intent) return { success: true, applied: false, reason: 'intent-missing' };
      observedRevision = intent.revision;
      observedActionSequence = intent.actionSequence;
      const writerProof = getCodexWriterProofSnapshot(tabId);
      const provisionalSettings = writerProof
        ? null
        : getCodexProvisionalSettingsSnapshot(tabId);
      const settingsOwnerId = writerProof?.sessionId
        || provisionalSettings?.codexProvisionalSettingsOwnerId
        || null;
      const plan = planCodexModelEffortIntentReconcile({
        ...intent,
        // A verified composer footer belongs to one exact launch generation
        // before the first rollout user_message exists. That launch is already
        // sufficient to own a picker; waiting for the first prompt creates the
        // false "settings apply only after send" behaviour.
        writerOwnerId: settingsOwnerId,
        processRunning: terminalCommandState.get(tabId)?.isRunning === true
          && codexHasLivePtySubmitEvidence(tabId),
        tuiReady: isCodexTuiEffectivelyReady(tabId),
      });
      console.log('[CodexSettingsIntent] reconcile tab=' + String(tabId).slice(-12)
        + ' model=' + intent.model
        + ' effort=' + intent.effort
        + ' revision=' + intent.revision
        + ' action=' + plan.action
        + ' reason=' + plan.reason
        + ' source=' + reason);
      if (plan.action === 'none' || plan.action === 'queue') {
        return {
          success: true,
          queued: plan.action === 'queue',
          intentPending: plan.action === 'queue',
          model: intent.model,
          effort: intent.effort,
          intentRevision: intent.revision,
          reason: plan.reason,
          providerState: intent.providerState,
        };
      }
      if (plan.action === 'settled') {
        return {
          success: true,
          queued: false,
          applied: true,
          model: intent.model,
          effort: intent.effort,
          intentRevision: intent.revision,
          reason: plan.reason,
          providerState: intent.providerState,
        };
      }
      const targetSender = sender && !sender.isDestroyed?.()
        ? sender
        : mainWindow && !mainWindow.isDestroyed() && !mainWindow.webContents.isDestroyed()
          ? mainWindow.webContents
          : null;
      if (!targetSender) {
        return {
          success: true,
          queued: true,
          intentPending: true,
          model: intent.model,
          effort: intent.effort,
          intentRevision: intent.revision,
          reason: 'renderer-unavailable',
          providerState: intent.providerState,
        };
      }
      updateCodexSettingsIntentError(tabId, intent.revision, null, intent.actionSequence);
      const result = await executeCodexSelectModelEffortRequest(targetSender, {
        tabId,
        model: intent.model,
        effort: intent.effort,
        expectedWriterSessionId: plan.writerOwnerId,
        allowTurnBusy: true,
        hasDraft: false,
        draftSource: 'settings-intent-reconcile',
        visualHasDraft: false,
        visualSource: 'settings-intent-reconcile',
        settingsControl: intent.providerState.codexSettingsIntentControl,
      });
      if (!codexModelEffortIntentApplicationProven(intent, result)) {
        updateCodexSettingsIntentError(tabId, intent.revision, result?.error || 'settings-application-unconfirmed', intent.actionSequence);
        console.warn('[CodexSettingsIntent] apply deferred tab=' + String(tabId).slice(-12)
          + ' model=' + intent.model
          + ' effort=' + intent.effort
          + ' revision=' + intent.revision
          + ' error=' + (result?.error || 'unknown'));
        const deferredResult = {
          ...result,
          queued: true,
          intentPending: true,
          model: intent.model,
          effort: intent.effort,
          intentRevision: intent.revision,
          providerState: getCodexModelEffortIntentRecord(tabId)?.providerState || intent.providerState,
        };
        if (result?.draftTransfer && mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('codex:model-effort-intent-deferred', {
            tabId, revision: intent.revision, result: deferredResult,
          });
        }
        return deferredResult;
      }
      const ownerId = result.codexSettingsProofSessionId
        || getCodexWriterProofSnapshot(tabId)?.sessionId
        || plan.writerOwnerId;
      const applied = markCodexModelEffortIntentApplied(
        tabId,
        intent,
        ownerId,
        'reconcile:' + reason,
        { publish: false },
      );
      if (applied.applied !== true) {
        if (result?.draftTransfer && mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('codex:model-effort-intent-deferred', {
            tabId, revision: intent.revision, result,
          });
        }
        continue;
      }
      const appliedResult = {
        ...result,
        applied: true,
        queued: false,
        intentPending: false,
        intentRevision: intent.revision,
        providerState: applied.providerState,
      };
      if (mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('codex:model-effort-intent-applied', {
          tabId,
          model: intent.model,
          effort: intent.effort,
          revision: intent.revision,
          result: appliedResult,
        });
      }
      // Publish the proved values before releasing their pending indicator.
      // Otherwise the provider-state event unlocks the old label for one
      // frame while the actual applied-pair event is still in transit.
      broadcastProviderState(tabId, applied.providerState);
      const latest = getCodexModelEffortIntentRecord(tabId);
      if (latest?.revision !== intent.revision) continue;
      return appliedResult;
    }
    return { success: true, queued: true, intentPending: true, reason: 'settings-intent-pass-limit' };
  })().catch(error => {
    updateCodexSettingsIntentError(tabId, observedRevision, error?.message || String(error), observedActionSequence);
    return { success: false, queued: true, intentPending: true, error: error?.message || String(error),
      ...(error?.draftTransfer ? { draftTransfer: error.draftTransfer } : {}) };
  }).finally(() => {
    if (codexModelEffortIntentReconcileInflight.get(tabId) === work) {
      codexModelEffortIntentReconcileInflight.delete(tabId);
    }
    if (codexModelEffortIntentReconcileRequested.delete(tabId)) {
      setImmediate(() => scheduleCodexModelEffortIntentReconcile(tabId, 'newer-intent'));
    }
  });
  codexModelEffortIntentReconcileInflight.set(tabId, work);
  return work;
}

ipcMain.handle('codex:set-model-effort-intent', async (event, {
  tabId,
  model,
  effort,
  control,
} = {}) => {
  if (!tabId) return { success: false, error: 'tabId required' };
  if (!terminals.has(tabId)) return { success: false, error: 'terminal not found' };
  const saved = persistCodexModelEffortIntent(tabId, model, effort, 'user-selection', control);
  if (!saved.success) return saved;
  clearCodexLifecycleWarning(tabId, 'model-effort-selection');
  const reconciliation = scheduleCodexModelEffortIntentReconcile(
    tabId,
    'user-selection',
    event.sender,
  );
  void reconciliation?.catch?.((error) => {
    console.warn('[CodexSettingsIntent] async reconcile failed tab='
      + String(tabId).slice(-12)
      + ' revision=' + saved.revision
      + ' error=' + (error?.message || String(error)));
  });
  return {
    success: true,
    queued: true,
    intentPending: true,
    reason: 'intent-saved',
    model: saved.model,
    effort: saved.effort,
    intentRevision: saved.revision,
    providerState: getCodexModelEffortIntentRecord(tabId)?.providerState || saved.providerState,
  };
});

function getCodexFastIntentRecord(tabId) {
  const state = providerStates.get(tabId) || null;
  if (!state || typeof state.codexFastIntent !== 'boolean') return null;
  const revision = Number(state.codexFastIntentRevision || 0);
  if (!Number.isInteger(revision) || revision <= 0) return null;
  return {
    desiredFast: state.codexFastIntent,
    revision,
    providerState: state,
  };
}

function persistNextCodexFastIntent(tabId) {
  const ownState = providerStates.get(tabId) || { type: 'anthropic' };
  const currentProof = codexTuiReadyMeta.get(tabId)?.serviceTierProof || null;
  const desiredFast = nextCodexFastIntent({
    currentIntent: ownState.codexFastIntent,
    serviceTier: currentProof?.serviceTier,
  });
  return persistCodexFastIntentValue(tabId, desiredFast, 'user-toggle');
}

function persistCodexFastIntentValue(tabId, desiredFast, source = 'explicit') {
  const ownState = providerStates.get(tabId) || { type: 'anthropic' };
  const previousRevision = Number(ownState.codexFastIntentRevision || 0);
  if (ownState.codexFastIntent === desiredFast
    && Number.isInteger(previousRevision)
    && previousRevision > 0) {
    return {
      desiredFast,
      revision: previousRevision,
      providerState: ownState,
      changed: false,
    };
  }
  const revision = Number.isInteger(previousRevision) && previousRevision > 0
    ? previousRevision + 1
    : 1;
  const next = {
    ...ownState,
    codexFastIntent: desiredFast,
    codexFastIntentRevision: revision,
  };
  setProviderState(tabId, next);
  if (projectManager?.db) projectManager.db.updateTabProviderState(tabId, next);
  broadcastProviderState(tabId, next);
  console.log('[CodexFastIntent] saved tab=' + String(tabId).slice(-12)
    + ' desired=' + desiredFast
    + ' revision=' + revision
    + ' source=' + source);
  return { desiredFast, revision, providerState: next, changed: true };
}

function scheduleCodexFastIntentReconcile(tabId, reason = 'scheduled') {
  if (!tabId || !getCodexFastIntentRecord(tabId)) return null;
  const existing = codexFastIntentReconcileInflight.get(tabId) || null;
  if (existing) {
    codexFastIntentReconcileRequested.add(tabId);
    return existing;
  }
  const work = (async () => {
    for (let pass = 0; pass < 4; pass += 1) {
      const intent = getCodexFastIntentRecord(tabId);
      if (!intent) return { success: true, applied: false, reason: 'intent-missing' };
      const retainedTier = reconcileCodexServiceTierProofIdentity(
        tabId,
        'fast-intent:' + reason,
      );
      const serviceTierProof = retainedTier.preserved
        ? retainedTier.proof
        : codexTuiReadyMeta.get(tabId)?.serviceTierProof || null;
      const plan = planCodexFastIntentReconcile({
        desiredFast: intent.desiredFast,
        revision: intent.revision,
        processRunning: terminalCommandState.get(tabId)?.isRunning === true
          && codexHasLivePtySubmitEvidence(tabId),
        tuiReady: isCodexTuiEffectivelyReady(tabId),
        serviceTier: serviceTierProof?.serviceTier,
      });
      console.log('[CodexFastIntent] reconcile tab=' + String(tabId).slice(-12)
        + ' desired=' + intent.desiredFast
        + ' revision=' + intent.revision
        + ' action=' + plan.action
        + ' reason=' + plan.reason
        + ' source=' + reason);
      if (plan.action === 'none' || plan.action === 'queue') {
        return { success: true, queued: plan.action === 'queue', ...plan };
      }
      if (plan.action === 'settled') {
        return { success: true, applied: true, ...plan };
      }
      if (!mainWindow || mainWindow.isDestroyed() || mainWindow.webContents.isDestroyed()) {
        return { success: true, queued: true, reason: 'renderer-unavailable' };
      }
      const result = await executeCodexLiveSlashCommandRequest({
        sender: mainWindow.webContents,
        tabId,
        command: '/fast',
        source: 'codex-fast-intent',
        hasDraft: false,
        draftSource: 'intent-reconcile',
        visualHasDraft: false,
        visualSource: 'intent-reconcile',
        turnBusy: hasCodexPromptOrTurnInFlight(tabId),
      });
      if (result?.success !== true) {
        console.warn('[CodexFastIntent] apply deferred tab=' + String(tabId).slice(-12)
          + ' desired=' + intent.desiredFast
          + ' revision=' + intent.revision
          + ' error=' + (result?.error || 'unknown'));
        return {
          success: true,
          queued: true,
          desiredFast: intent.desiredFast,
          revision: intent.revision,
          reason: result?.error || 'fast-apply-unconfirmed',
        };
      }
      // `/fast` is a toggle. Re-read the durable intent before the next pass:
      // clicks that arrived while the TUI transaction was in flight win.
    }
    return { success: true, queued: true, reason: 'fast-intent-pass-limit' };
  })().finally(() => {
    if (codexFastIntentReconcileInflight.get(tabId) === work) {
      codexFastIntentReconcileInflight.delete(tabId);
    }
    if (codexFastIntentReconcileRequested.delete(tabId)) {
      setImmediate(() => scheduleCodexFastIntentReconcile(tabId, 'newer-intent'));
    }
  });
  codexFastIntentReconcileInflight.set(tabId, work);
  return work;
}

ipcMain.handle('codex:toggle-fast-intent', async (_event, { tabId } = {}) => {
  if (!tabId) return { success: false, error: 'tabId required' };
  if (!terminals.has(tabId)) return { success: false, error: 'terminal not found' };
  const saved = persistNextCodexFastIntent(tabId);
  void scheduleCodexFastIntentReconcile(tabId, 'user-toggle');
  return {
    success: true,
    queued: true,
    ...saved,
  };
});

// Toggle thinking mode reactively: open picker → detect state → navigate → confirm
const { createClaudeThinkingProofStore } = require(path.join(srcMainDir, 'claude-thinking-proof'));
const claudeThinkingProofs = createClaudeThinkingProofStore();

function readClaudeThinkingProofScope(tabId) {
  const command = terminalCommandState.get(tabId);
  return {
    terminal: terminals.get(tabId) || null,
    runSeq: Number(command?.runSeq || 0),
    lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
    inputRevision: getTerminalInputRevision(tabId),
    sessionId: bridgeKnownSessions.get(tabId) || null,
    processAlive: command?.isRunning === true,
  };
}

ipcMain.handle('claude:get-thinking-state', (_event, tabId) => (
  claudeThinkingProofs.read(readClaudeThinkingProofScope(tabId))
));

async function toggleClaudeThinkingInternal(tabId, desiredThinking = null, ptyWriteOwner = null) {
  let term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no terminal' };

  // Wait for danger zone to clear (event-driven: resolves when prompt returns)
  const dz = claudeCtrlCDangerZone.get(tabId);
  if (dz) {
    console.log('[Think] ⚠️ Danger zone active — waiting for prompt...');
    await dz.promise;
    console.log('[Think] ✅ Prompt returned, proceeding');
  }

  // The PTY may have been replaced while the prior turn was settling.
  term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no terminal' };

  const expectedRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
  const expectedLifecycleGeneration = getTerminalLifecycleGeneration(tabId);
  const requestedInputRevision = getTerminalInputRevision(tabId);
  const pickerOperation = {
    kind: 'claude-thinking-picker',
    source: 'claude-toggle-thinking',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: true,
    manualEnterSubmitsPrompt: true,
    phase: 'queued',
    queuedAt: Date.now(),
  };

  return await withPtyWriteLock(term, async () => {
    if (
      terminals.get(tabId) !== term
      || Number(terminalCommandState.get(tabId)?.runSeq || 0) !== expectedRunSeq
      || getTerminalLifecycleGeneration(tabId) !== expectedLifecycleGeneration
      || getTerminalInputRevision(tabId) !== requestedInputRevision
    ) {
      return { success: false, error: 'think_input_ownership_changed' };
    }

    const pickerMirrorState = getHeadlessTerminalMirror(tabId);
    if (!pickerMirrorState) {
      return {
        success: false,
        submitted: false,
        error: 'think_headless_snapshot_unavailable',
      };
    }
    const ownedInputRevision = bumpTerminalInputRevision(tabId);
    const stillOwnsPicker = () => (
      terminals.get(tabId) === term
      && Number(terminalCommandState.get(tabId)?.runSeq || 0) === expectedRunSeq
      && getTerminalLifecycleGeneration(tabId) === expectedLifecycleGeneration
      && getTerminalInputRevision(tabId) === ownedInputRevision
      && getHeadlessTerminalMirror(tabId) === pickerMirrorState
    );
    const fail = (error, detail = {}) => ({
      success: false,
      submitted: false,
      error,
      ...detail,
    });
    const readCurrentFrame = async (phase, timeoutMs = 1200) => {
      const closed = await waitForHeadlessSynchronizedOutputClose(
        tabId,
        pickerMirrorState,
        timeoutMs,
      );
      if (!closed.ready) {
        return fail('think_' + phase + '_' + closed.reason, { phase });
      }
      if (!stillOwnsPicker()) return fail('think_input_ownership_changed', { phase });
      const snapshot = getHeadlessVisibleBufferSnapshot(
        tabId,
        'claude-thinking-picker:' + phase,
        { preferCommitted: false },
      );
      if (!snapshot?.success || snapshot.authoritativeFrameCommitted !== true) {
        return fail(snapshot?.error || 'think_frame_not_committed', { phase });
      }
      return { success: true, phase, snapshot, writeSeq: snapshot.writeSeq };
    };
    const inspectPickerFrame = (snapshot) => (
      inspectClaudeThinkingPickerSnapshot(snapshot)
    );
    const pickerFrameReady = (picker) => (
      picker?.visible === true && picker.stateKnown === true
    );
    const inspectPostPickerFrame = (snapshot) => {
      const picker = inspectClaudeThinkingPickerSnapshot(snapshot);
      const proceed = inspectClaudeThinkingProceedSnapshot(snapshot);
      const composer = parseClaudeDraftFromVisibleSnapshot(snapshot);
      return {
        picker,
        proceed,
        composer,
        closed: picker.modalPresent !== true
          && picker.visible !== true
          && proceed.visible !== true
          && (composer.proofOutcome === 'absent' || composer.proofOutcome === 'found'),
      };
    };
    const captureFrameAfterWrite = async (data, phase, timeoutMs, {
      inspectSnapshot = () => ({ ready: true }),
      acceptInspection = () => true,
      afterWriteSeq = null,
    } = {}) => {
      if (!stillOwnsPicker()) return fail('think_input_ownership_changed', { phase });
      const mirrorState = pickerMirrorState;
      const beforeWriteSeq = Number.isFinite(Number(afterWriteSeq))
        ? Number(afterWriteSeq)
        : Number(mirrorState.writeSeq || 0);
      const mutationWritten = typeof data === 'string' && data.length > 0;
      pickerOperation.phase = phase;
      pickerOperation.manualEnterSubmitsPrompt = false;
      const observed = await waitForCommittedSemanticFrame({
        subscribe(listener) {
          mirrorState.synchronizedFrameWaiters.add(listener);
          return () => mirrorState.synchronizedFrameWaiters.delete(listener);
        },
        readSnapshot() {
          return getHeadlessVisibleBufferSnapshot(
            tabId,
            'claude-thinking-picker:' + phase,
            { preferCommitted: false },
          );
        },
        inspectSnapshot,
        acceptInspection,
        trigger: mutationWritten ? () => term.write(data) : null,
        getAbortReason() {
          if (!stillOwnsPicker()) return 'think_input_ownership_changed';
          if (getHeadlessTerminalMirror(tabId) !== mirrorState) {
            return 'think_headless_generation_changed';
          }
          if (mirrorState.failed === true) return 'think_headless_mirror_failed';
          return null;
        },
        afterWriteSeq: beforeWriteSeq,
        timeoutMs,
      });
      if (!observed.ready) {
        return fail('think_' + phase + '_' + observed.reason, {
          phase,
          mutationWritten,
          observedFrames: observed.observedFrames,
          inspection: observed.lastInspection || null,
        });
      }
      return {
        success: true,
        phase,
        snapshot: observed.snapshot,
        writeSeq: observed.writeSeq,
        inspection: observed.inspection,
        observedFrames: observed.observedFrames,
        mutationWritten,
      };
    };
    const closePicker = async (phase) => {
      const closed = await captureFrameAfterWrite('\x1b', phase, 2500, {
        inspectSnapshot: inspectPostPickerFrame,
        acceptInspection: (inspection) => inspection.closed === true,
      });
      return {
        frame: closed,
        closed: closed.success === true && closed.inspection?.closed === true,
      };
    };
    const cleanupUncertainPicker = async (frame, phase) => {
      if (!stillOwnsPicker()) return { closed: false, skipped: 'ownership-changed' };
      const inspection = frame?.inspection?.picker || frame?.inspection || null;
      if (frame?.mutationWritten !== true && inspection?.modalPresent !== true) {
        return { closed: false, skipped: 'modal-not-proven' };
      }
      return await closePicker(phase);
    };

    let pickerFrame = await readCurrentFrame('think_picker_preflight');
    if (!pickerFrame.success) return pickerFrame;
    let picker = inspectClaudeThinkingPickerSnapshot(pickerFrame.snapshot);

    // A current title/options surface without its footer is a modal still being
    // painted, not an ordinary composer. Keep the observer installed across
    // later committed frames instead of toggling the half-drawn picker closed.
    if (!pickerFrameReady(picker) && picker.modalPresent === true) {
      const settlingFrame = await captureFrameAfterWrite(
        null,
        'think_picker_existing_settle',
        2500,
        {
          inspectSnapshot: inspectPickerFrame,
          acceptInspection: pickerFrameReady,
          afterWriteSeq: pickerFrame.writeSeq,
        },
      );
      if (!settlingFrame.success) {
        const cleanup = await cleanupUncertainPicker(
          { ...settlingFrame, inspection: settlingFrame.inspection || picker },
          'think_picker_existing_unknown_close',
        );
        console.warn('[ThinkPickerProof] tab=' + String(tabId).slice(-12)
          + ' outcome=failed reason=' + (settlingFrame.inspection?.reason || picker.reason)
          + ' cause=' + settlingFrame.error
          + ' frames=' + Number(settlingFrame.observedFrames || 0)
          + ' modalClosed=' + cleanup.closed);
        return fail('think_picker_state_unknown', {
          cause: settlingFrame.error,
          modalVisible: cleanup.closed !== true,
          modalKind: 'thinking-picker',
          modalClosed: cleanup.closed === true,
          proofReason: settlingFrame.inspection?.reason || picker.reason,
        });
      }
      pickerFrame = settlingFrame;
      picker = settlingFrame.inspection;
    }

    if (!pickerFrameReady(picker)) {
      const pendingProceed = inspectClaudeThinkingProceedSnapshot(pickerFrame.snapshot);
      if (pendingProceed.visible === true) {
        console.warn('[ThinkPickerProof] tab=' + String(tabId).slice(-12)
          + ' outcome=failed reason=preexisting-proceed-dialog');
        return fail('think_confirmation_state_unknown', {
          modalVisible: true,
          modalKind: 'thinking-proceed',
        });
      }
      pickerFrame = await captureFrameAfterWrite('\x1bt', 'think_picker_open', 5000, {
        inspectSnapshot: inspectPickerFrame,
        acceptInspection: pickerFrameReady,
      });
      if (!pickerFrame.success || !stillOwnsPicker()) {
        const cleanup = await cleanupUncertainPicker(
          pickerFrame,
          'think_picker_open_unknown_close',
        );
        const proofReason = pickerFrame.inspection?.reason || picker.reason;
        console.warn('[ThinkPickerProof] tab=' + String(tabId).slice(-12)
          + ' outcome=failed reason=' + proofReason
          + ' cause=' + (pickerFrame.error || 'think_input_ownership_changed')
          + ' frames=' + Number(pickerFrame.observedFrames || 0)
          + ' modalClosed=' + cleanup.closed);
        return fail('think_picker_state_unknown', {
          cause: pickerFrame.error || 'think_input_ownership_changed',
          modalVisible: cleanup.closed !== true,
          modalKind: 'thinking-picker',
          modalClosed: cleanup.closed === true,
          proofReason,
        });
      }
      picker = pickerFrame.inspection;
    }

    if (!pickerFrameReady(picker)) {
      const cleanup = await cleanupUncertainPicker(
        { ...pickerFrame, inspection: picker },
        'think_picker_unknown_close',
      );
      console.warn('[ThinkPickerProof] tab=' + String(tabId).slice(-12)
        + ' outcome=failed reason=' + picker.reason
        + ' modalClosed=' + cleanup.closed);
      return fail('think_picker_state_unknown', {
        modalVisible: picker.modalPresent === true && cleanup.closed !== true,
        modalKind: picker.modalPresent === true ? 'thinking-picker' : null,
        modalClosed: cleanup.closed === true,
        proofReason: picker.reason,
      });
    }

    const wasEnabled = picker.thinking;
    const hasDesiredState = typeof desiredThinking === 'boolean';
    const newState = hasDesiredState ? desiredThinking : !wasEnabled;
    console.log('[ThinkPickerProof] tab=' + String(tabId).slice(-12)
      + ' current=' + (wasEnabled ? 'enabled' : 'disabled')
      + ' requested=' + (newState ? 'enabled' : 'disabled')
      + ' source=' + (pickerFrame.phase === 'think_picker_preflight' ? 'existing-picker' : 'opened-picker')
      + ' frames=' + Number(pickerFrame.observedFrames || 0));

    if (newState === wasEnabled) {
      const cleanup = await closePicker('think_picker_close');
      if (!cleanup.closed || !stillOwnsPicker()) {
        return fail(cleanup.frame?.error || 'think_picker_close_unproven', {
          modalVisible: cleanup.closed !== true,
          modalKind: 'thinking-picker',
        });
      }
      const thinkingProof = claudeThinkingProofs.confirm(readClaudeThinkingProofScope(tabId), wasEnabled);
      return { success: true, thinking: wasEnabled, changed: false, thinkingProof };
    }

    const arrow = wasEnabled ? '\x1b[B' : '\x1b[A';
    const arrowFrame = await captureFrameAfterWrite(arrow, 'think_arrow', 2500, {
      inspectSnapshot: inspectPickerFrame,
      acceptInspection: (inspection) => (
        pickerFrameReady(inspection) && inspection.selectedThinking === newState
      ),
    });
    if (!arrowFrame.success || !stillOwnsPicker()) {
      const cleanup = await cleanupUncertainPicker(
        arrowFrame,
        'think_arrow_unknown_close',
      );
      return fail('think_picker_selection_unknown', {
        cause: arrowFrame.error || 'think_input_ownership_changed',
        modalVisible: cleanup.closed !== true,
        modalKind: 'thinking-picker',
        modalClosed: cleanup.closed === true,
        proofReason: arrowFrame.inspection?.reason || null,
      });
    }
    const arrowPicker = arrowFrame.inspection;
    if (arrowPicker.visible !== true || arrowPicker.selectedThinking !== newState) {
      const cleanup = await cleanupUncertainPicker(
        { ...arrowFrame, inspection: arrowPicker },
        'think_arrow_mismatch_close',
      );
      return fail('think_picker_selection_unknown', {
        modalVisible: arrowPicker.modalPresent === true && cleanup.closed !== true,
        modalKind: arrowPicker.modalPresent === true ? 'thinking-picker' : null,
        modalClosed: cleanup.closed === true,
        proofReason: arrowPicker.reason,
      });
    }

    let finalFrame = await captureFrameAfterWrite('\r', 'think_confirm', 2500, {
      inspectSnapshot: inspectPostPickerFrame,
      acceptInspection: (inspection) => (
        inspection.proceed.visible === true || inspection.closed === true
      ),
    });
    if (!finalFrame.success || !stillOwnsPicker()) {
      const cleanup = await cleanupUncertainPicker(
        finalFrame,
        'think_confirm_unknown_close',
      );
      return fail('think_confirmation_incomplete', {
        cause: finalFrame.error || 'think_input_ownership_changed',
        modalVisible: cleanup.closed !== true,
        modalKind: 'thinking-confirmation',
        modalClosed: cleanup.closed === true,
      });
    }

    if (finalFrame.inspection.proceed.visible === true) {
      finalFrame = await captureFrameAfterWrite('\r', 'think_proceed', 2500, {
        inspectSnapshot: inspectPostPickerFrame,
        acceptInspection: (inspection) => inspection.closed === true,
      });
      if (!finalFrame.success || !stillOwnsPicker()) {
        const cleanup = await cleanupUncertainPicker(
          finalFrame,
          'think_proceed_unknown_close',
        );
        return fail('think_confirmation_incomplete', {
          cause: finalFrame.error || 'think_input_ownership_changed',
          modalVisible: cleanup.closed !== true,
          modalKind: 'thinking-confirmation',
          modalClosed: cleanup.closed === true,
        });
      }
    }
    if (finalFrame.inspection.closed !== true) {
      const cleanup = await cleanupUncertainPicker(
        finalFrame,
        'think_confirm_incomplete_close',
      );
      return fail('think_confirmation_incomplete', {
        modalVisible: cleanup.closed !== true,
        modalKind: 'thinking-confirmation',
        modalClosed: cleanup.closed === true,
      });
    }

    // Re-open the picker once to prove the setting that Claude actually
    // committed. Action ordering alone is not enough: a dropped Arrow or Enter
    // must not authorize the following user prompt.
    const verifyFrame = await captureFrameAfterWrite('\x1bt', 'think_verify_open', 3500, {
      inspectSnapshot: inspectPickerFrame,
      acceptInspection: pickerFrameReady,
    });
    const verified = verifyFrame.success ? verifyFrame.inspection : null;
    if (!verifyFrame.success
      || verified?.visible !== true
      || verified.stateKnown !== true
      || verified.thinking !== newState) {
      const cleanup = await cleanupUncertainPicker(
        { ...verifyFrame, inspection: verified || verifyFrame.inspection },
        'think_verify_failed_close',
      );
      return fail(verifyFrame.error || 'think_final_state_mismatch', {
        modalVisible: verified?.modalPresent === true && cleanup.closed !== true,
        modalKind: verified?.modalPresent === true ? 'thinking-picker' : null,
        modalClosed: cleanup.closed === true,
        proofReason: verified?.reason || null,
      });
    }
    const verificationClose = await closePicker('think_verify_close');
    if (!verificationClose.closed || !stillOwnsPicker()) {
      return fail(verificationClose.frame?.error || 'think_verify_close_unproven', {
        modalVisible: verificationClose.closed !== true,
        modalKind: 'thinking-picker',
      });
    }

    const thinkingProof = claudeThinkingProofs.confirm(readClaudeThinkingProofScope(tabId), newState);
    return { success: true, thinking: newState, changed: true, thinkingProof };
  }, pickerOperation, ptyWriteOwner);
}

ipcMain.handle('claude:toggle-thinking', (_event, tabId, desiredThinking = null) => (
  toggleClaudeThinkingInternal(tabId, desiredThinking)
));

// Claude rewind through the native `/rewind` slash command.
// Flow: preflight current input → stash if needed → `/rewind` → UP to target → Enter.
// Native mode lets History own the selected prompt draft; after Claude restores it into
// the TUI composer, we grab+clear that composer so there is a single input source.
// Optional `pasteAfter` keeps the AI-assisted compact path, but it now shares the same rewind selector.
const rewindCancelTabs = new Set();

function beginActiveRewindOperation(tabId, toolType, opId) {
  const claim = claimRewindOperation(activeRewindOperations, { tabId, toolType, opId });
  if (claim.success) {
    let resolve;
    const promise = new Promise((done) => { resolve = done; });
    rewindOperationSettlements.set(claim.operation, { promise, resolve });
  }
  return claim;
}

function finishActiveRewindOperation(operation) {
  const finished = finishRewindOperation(activeRewindOperations, operation);
  if (finished) {
    const settlement = rewindOperationSettlements.get(operation);
    rewindOperationSettlements.delete(operation);
    settlement?.resolve?.({ settled: true });
  }
  return finished;
}

async function waitForActiveRewindSettlement(operation, timeoutMs = 12000) {
  const settlement = rewindOperationSettlements.get(operation);
  if (!settlement) return true;
  let timer = null;
  const outcome = await Promise.race([
    settlement.promise.then(() => true),
    new Promise((resolve) => {
      timer = setTimeout(() => resolve(false), timeoutMs);
    }),
  ]);
  if (timer) clearTimeout(timer);
  return outcome === true;
}

function markActiveRewindMutationStarted(operation, sender) {
  if (!markRewindMutationStarted(activeRewindOperations, operation)) return false;
  try {
    if (sender && !sender.isDestroyed?.()) {
      sender.send('rewind:mutation-started', {
        tabId: operation.tabId,
        toolType: operation.toolType,
        opId: operation.opId,
      });
    }
  } catch (error) {
    console.warn('[Rewind] mutation-started notification failed tab='
      + String(operation.tabId).slice(-12)
      + ' error=' + (error?.message || error));
  }
  return true;
}

ipcMain.handle('rewind:cancel', async (_event, { tabId, toolType, opId } = {}) => {
  if (!tabId) return { success: false, error: 'no_tab_id' };
  // Gemini compaction is renderer-owned and has its own AbortController. There
  // is no native terminal mutation to cancel here.
  if (toolType === 'gemini') {
    return { success: true, accepted: true, rendererOwned: true };
  }
  const cancelDecision = classifyRewindCancel(activeRewindOperations, { tabId, toolType, opId });
  const operation = cancelDecision.operation;
  if (cancelDecision.status === 'not-active') {
    return cancelDecision.response;
  }
  if (cancelDecision.status === 'stale') {
    console.warn('[Rewind:Cancel] stale request tab=' + String(tabId).slice(-12)
      + ' requestedOp=' + String(opId || '-')
      + ' activeOp=' + operation.opId);
    return cancelDecision.response;
  }
  if (cancelDecision.status === 'too-late') {
    console.log('[Rewind:Cancel] too late after mutation boundary tab='
      + String(tabId).slice(-12) + ' op=' + operation.opId);
    return cancelDecision.response;
  }
  rewindCancelTabs.add(tabId);
  // A native Rewind owns the shared PTY write boundary until its handler
  // observes this cancellation. Do not tell the renderer that Cancel finished
  // before that transaction actually releases: otherwise the UI unlocks while
  // physical keys are still queued behind the old owner.
  if (operation.ptyWriteOperation) {
    operation.ptyWriteOperation.cancelRequested = true;
    operation.ptyWriteOperation.resolveCancel?.({ cancelled: true });
  }
  if (operation.toolType === 'codex') {
    revokeCodexActionAuthoritiesForTab(tabId, 'rewind-cancelled', {
      profile: CODEX_ACTION_PROFILE_NATIVE_REWIND,
    });
  }
  const term = terminals.get(tabId);
  // The transaction that opened a picker is the only owner allowed to close
  // it. Writing Esc/q here would bypass the PTY serializer and can race that
  // transaction's own finally-cleanup (a second q becomes user text in a clean
  // Codex composer). The cancellation signal wakes/bounds its current wait;
  // its catch/finally performs the one protocol-specific close.
  console.log('[Rewind:Cancel] accepted tab=' + String(tabId).slice(-12)
    + ' tool=' + operation.toolType
    + ' op=' + operation.opId
    + ' hasTerm=' + !!term
    + ' protocolUiOpen=' + operation.protocolUiOpen);
  const settled = await waitForActiveRewindSettlement(operation);
  if (!settled) {
    console.warn('[Rewind:Cancel] settlement timeout tab=' + String(tabId).slice(-12)
      + ' tool=' + operation.toolType
      + ' op=' + operation.opId);
    return {
      success: false,
      accepted: false,
      cancellationPending: true,
      error: 'rewind_cancel_settlement_timeout',
    };
  }
  return cancelDecision.response;
});

function makeRewindCancelledError(stage) {
  const err = new Error('rewind_cancelled');
  err.code = 'rewind_cancelled';
  err.stage = stage;
  return err;
}

ipcMain.handle('claude:open-history-menu', async (event, { tabId, opId, targetIndex, targetText, targetMenuText, targetFullText, targetUuid, rewindableCount, skipDuplicates = 0, pasteAfter, deadlineMs }) => {
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no terminal' };
  if (!hasLiveClaudeInTab(tabId)) return { success: false, error: 'no_claude_session' };
  if (claudeTurnBusy.get(tabId) === true) return { success: false, error: 'claude_busy' };
  const activeRewindClaim = beginActiveRewindOperation(tabId, 'claude', opId);
  if (!activeRewindClaim.success) return activeRewindClaim;
  const activeRewindOperation = activeRewindClaim.operation;
  let resolveClaudeRewindCancel;
  const claudeRewindCancelPromise = new Promise((resolve) => {
    resolveClaudeRewindCancel = resolve;
  });
  const claudeRewindPtyOperation = {
    kind: 'claude-native-rewind',
    source: 'claude-native-rewind',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: false,
    cancelRequested: false,
    cancelPromise: claudeRewindCancelPromise,
    resolveCancel: resolveClaudeRewindCancel,
    queuedAt: Date.now(),
  };
  activeRewindOperation.ptyWriteOperation = claudeRewindPtyOperation;
  rewindCancelTabs.delete(tabId);
  const rewindDeadlineAt = Date.now() + Math.max(3000, Math.min(180000, Number(deadlineMs) || 18000));
  let rewindDeadlineHit = false;
  const selectionMarkerRe = /^[●❯›]\s*/u;
  const selectionMarkerAnywhereRe = /^\s*[●❯›]\s*(.+)$/u;
  const selectionSignalRe = /\x1b\[38;2;\d+;\d+;\d+m|[●❯›]|\x1b\[\?2026l/;

  function cleanBuffer(raw) {
    const spaced = String(raw || '').replace(/\x1b\[(\d*)C/g, (_, n) => ' '.repeat(parseInt(n) || 1));
    const normalized = spaced
      .replace(/\x1b\[\d*[ABD]/g, '')
      .replace(/\x1b\[\d+;\d+[Hf]/g, '\n');
    return stripVTControlCharacters(normalized);
  }

  function normalizeCandidate(text) {
    return String(text || '')
      .replace(selectionMarkerRe, '')
      .replace(/^\(current\)\s*/, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function claudePromptHasImageMarker(text) {
    return /\[(?:Image(?:\s+#?\d+)?|imageError:\s*[^\]\r\n]+?)\]/i.test(String(text || ''));
  }

  function normalizeClaudePromptImageSlots(text) {
    return normalizeCandidate(String(text || '')
      .replace(/\[imageError:\s*[^\]\r\n]+?\]/gi, ' [Image] ')
      .replace(/\[Image(?:\s+#?\d+)?\]/gi, ' [Image] '));
  }

  function buildClaudeHistoryDraftFromGrab(text, imagePaths = []) {
    const resolvedById = new Map();
    for (const ref of Array.isArray(imagePaths) ? imagePaths : []) {
      const id = Number(ref?.id);
      if (Number.isFinite(id) && ref?.path) resolvedById.set(id, ref);
    }
    let imageCount = 0;
    let resolvedImages = 0;
    let missingImages = 0;
    const draftText = String(text || '').replace(/\[Image\s+#?(\d+)\]/g, (match, rawId) => {
      imageCount += 1;
      const id = Number(rawId);
      if (Number.isFinite(id) && resolvedById.has(id)) {
        resolvedImages += 1;
        return match;
      }
      missingImages += 1;
      return '[imageError: claude_image_path_unavailable #' + rawId + ']';
    });
    const draftImages = [...resolvedById.values()].filter((ref) => draftText.includes('[Image #' + ref.id + ']'));
    return {
      text: draftText,
      images: draftImages,
      imageCount,
      resolvedImages,
      missingImages,
      warning: missingImages > 0
        ? 'Claude Rewind вернул prompt с картинкой, но файл картинки уже недоступен. В draft оставлен imageError вместо тихой отправки текста.'
        : imageCount > 0
          ? 'Claude Rewind вернул prompt с картинкой. History сохранила маркер, но не отправит его как обычный текст; проверь вложение перед отправкой.'
          : '',
    };
  }

  function compareClaudeRestoredPrompt(expectedText, restoredText, grabResult) {
    const expected = normalizeCandidate(expectedText);
    const restored = normalizeCandidate(restoredText);
    const draft = buildClaudeHistoryDraftFromGrab(restoredText, grabResult?.imagePaths || []);
    if (expected && restored === expected) {
      return {
        matched: true,
        mode: draft.imageCount > 0 ? 'exact-with-image-slots' : 'exact',
        historyDraftText: draft.text,
        historyDraftImages: draft.images,
        historyDraftWarning: draft.warning,
      };
    }
    const hasImageShape = claudePromptHasImageMarker(expectedText)
      || claudePromptHasImageMarker(restoredText)
      || draft.imageCount > 0;
    if (hasImageShape) {
      const expectedImageIdentity = normalizeClaudePromptImageSlots(expectedText);
      const restoredImageIdentity = normalizeClaudePromptImageSlots(restoredText);
      if (expectedImageIdentity && expectedImageIdentity === restoredImageIdentity) {
        return {
          matched: true,
          mode: draft.resolvedImages > 0 ? 'image-slot-with-cache-path' : 'image-slot',
          historyDraftText: draft.text,
          historyDraftImages: draft.images,
          historyDraftWarning: draft.warning,
        };
      }
    }
    return {
      matched: !expected && restored.length === 0,
      mode: !expected && restored.length === 0 ? 'empty' : 'mismatch',
      historyDraftText: draft.text,
      historyDraftImages: draft.images,
      historyDraftWarning: draft.warning,
    };
  }

  function isMenuChrome(text) {
    const t = normalizeCandidate(text);
    const packed = t.replace(/\s+/g, '').toLowerCase();
    if (!t) return true;
    return t === '●'
      || t === '❯'
      || t === '›'
      || /^[─━╌═-]{5,}$/.test(t)
      || /^[↑↓]\s*\d+\s*more\s*(above|below)$/i.test(t)
      || /^\d+\s*more\s*(above|below)$/i.test(t)
      || t === 'Rewind'
      || t === 'Do nothing'
      || t === 'Rewind conversation'
      || t.startsWith('Stay at current position')
      || t.startsWith('Enter to continue')
      || packed.startsWith('entertocontinue')
      || packed.includes('esctocancel')
      || t.startsWith('Restore and fork');
  }

  function extractRgbCandidates(raw) {
    const results = [];
    const colorRe = /\x1b\[38;2;\d+;\d+;\d+m/g;
    let match;
    while ((match = colorRe.exec(raw)) !== null) {
      let i = colorRe.lastIndex;
      let text = '';
      while (i < raw.length) {
        const rest = raw.slice(i);
        if (rest.startsWith('\x1b[39m') || rest.startsWith('\x1b[0m') || rest.startsWith('\x1b[38;2;')) break;
        if (raw[i] === '\x1b') {
          const esc = rest.match(/^\x1b\[[0-9;?]*[ -/]*[@-~]/);
          if (esc) {
            i += esc[0].length;
            continue;
          }
        }
        text += raw[i];
        i++;
      }
      const candidate = normalizeCandidate(cleanBuffer(text));
      if (!isMenuChrome(candidate)) results.push(candidate);
      colorRe.lastIndex = Math.max(i, colorRe.lastIndex);
    }
    return results;
  }

  function extractPointerCandidates(raw) {
    const clean = cleanBuffer(raw);
    const lines = clean.split(/[\r\n]+/).map(l => l.trim()).filter(Boolean);
    const results = [];
    for (const line of lines) {
      const m = line.match(selectionMarkerAnywhereRe);
      if (!m) continue;
      const candidate = normalizeCandidate(m[1]);
      if (!isMenuChrome(candidate)) results.push(candidate);
    }
    return results;
  }

  function extractSelectedCandidates(raw) {
    const rgb = extractRgbCandidates(raw);
    if (rgb.length > 0) return rgb;
    return extractPointerCandidates(raw);
  }

  function stripPickerSelectionMarker(text) {
    return normalizeCandidate(text)
      .replace(selectionMarkerRe, '')
      .trim();
  }

  function stripVisualTruncation(text) {
    return stripPickerSelectionMarker(text)
      .replace(/\s*(?:…|\.{3})\s*$/g, '')
      .trim();
  }

  function compareSelectedToTarget(selectedText, targetText) {
    const selected = stripVisualTruncation(selectedText);
    const target = normalizeCandidate(targetText);
    if (!selected || !target) return { matched: false, reason: 'empty', selected, target };

    const selectedSnippet = selected;
    const targetSnippet = target;
    const shortLimit = 12;

    if (selectedSnippet === targetSnippet) {
      return { matched: true, reason: 'exact-snippet', selected: selectedSnippet, target: targetSnippet };
    }

    if (targetSnippet.length <= shortLimit || selectedSnippet.length <= shortLimit) {
      return { matched: selectedSnippet === targetSnippet, reason: 'short-exact', selected: selectedSnippet, target: targetSnippet };
    }

    if (targetSnippet.startsWith(selectedSnippet)) {
      return { matched: true, reason: 'selected-visible-prefix', selected: selectedSnippet, target: targetSnippet };
    }
    if (selectedSnippet.startsWith(targetSnippet)) {
      return { matched: true, reason: 'target-prefix', selected: selectedSnippet, target: targetSnippet };
    }

    return { matched: false, reason: 'prefix-mismatch', selected: selectedSnippet, target: targetSnippet };
  }

  function textMatchesTarget(selectedText, targetText) {
    const match = compareSelectedToTarget(selectedText, targetText);
    if (match.matched) {
      console.log('[Claude:Rewind] MATCH(' + match.reason + '): TUI="' + match.selected.substring(0, 100) + '" vs Target="' + match.target.substring(0, 100) + '"');
    }
    return match.matched;
  }

  function textMatchesTargetSilent(selectedText, targetText) {
    return compareSelectedToTarget(selectedText, targetText).matched;
  }

  function snapshotLines(snapshot) {
    if (!Array.isArray(snapshot?.lines)) return [];
    return snapshot.lines
      .map((line) => {
        const rawText = String(line?.text || '')
          .replace(/\u00a0/g, ' ')
          .trim();
        return {
          row: Number(line?.row),
          rawText,
          text: normalizeCandidate(rawText),
          wrapped: !!line?.wrapped,
          firstTextStyle: line?.firstTextStyle || '',
          styles: Array.isArray(line?.styles) ? line.styles : [],
          hasInverse: !!line?.hasInverse,
          hasNonDefaultBg: !!line?.hasNonDefaultBg,
          hasNonDefaultFg: !!line?.hasNonDefaultFg,
        };
      })
      .filter(line => line.text && !/^[─━╌═-]{5,}$/.test(line.text));
  }

  function isRewindPickerItemLine(line) {
    const text = stripPickerSelectionMarker(line?.text || '');
    if (!text) return false;
    if (/^[↑↓]\s*\d+\s*more\s*(above|below)$/i.test(text)) return false;
    if (/^Enter\s+to\s+continue\b/i.test(text)) return false;
    if (/^Esc\s+to\s+cancel\b/i.test(text)) return false;
    return !isMenuChrome(text);
  }

  function isClaudeSlashCommandRow(text) {
    const clean = normalizeCandidate(stripPickerSelectionMarker(text || ''));
    return /^\/[A-Za-z][\w:-]*(?:\s|$)/.test(clean);
  }

  function extractSnapshotSelectedCandidates(snapshot) {
    const results = [];
    for (const line of snapshotLines(snapshot)) {
      const m = String(line.rawText || line.text || '').match(selectionMarkerAnywhereRe);
      if (!m) continue;
      const candidate = normalizeCandidate(m[1]);
      if (!isMenuChrome(candidate)) results.push(candidate);
    }
    return results;
  }

  function extractScopedSelectedCandidates(lines) {
    const results = [];
    for (const line of lines || []) {
      const m = String(line.rawText || line.text || '').match(selectionMarkerAnywhereRe);
      if (!m) continue;
      const candidate = normalizeCandidate(m[1]);
      if (!isMenuChrome(candidate)) results.push(candidate);
    }
    return results;
  }

  async function writeAndWait(key, waitFor, timeoutMs, logPrefix) {
    const wait = waitForPtyText(term, waitFor, timeoutMs, logPrefix);
    term.write(key);
    return await wait;
  }

  function throwIfRewindCancelled(stage) {
    if (rewindCancelTabs.has(tabId)) {
      console.log('[Claude:Rewind] Cancelled at stage=' + stage);
      throw makeRewindCancelledError(stage);
    }
  }

  function hasRewindDeadlineExpired(stage) {
    if (Date.now() < rewindDeadlineAt) return false;
    rewindDeadlineHit = true;
    console.warn('[Claude:Rewind] Deadline expired stage=' + stage);
    return true;
  }

  async function grabRestoredRewindInput(expectedText) {
    const delays = [0, 180, 420, 900];
    let lastResult = null;
    for (let attempt = 0; attempt < delays.length; attempt++) {
      if (delays[attempt] > 0) await new Promise(resolve => setTimeout(resolve, delays[attempt]));
      // Native Rewind already owns the PTY serializer. Calling the public
      // serialized capture wrapper here would enqueue behind this transaction and
      // deadlock it forever. Use the at-boundary primitive, exactly like the
      // Codex Rewind path below.
      const result = await captureAgentInputAtWriteBoundary(
        tabId,
        'grab',
        'claude',
        { ownedWriteOperation: claudeRewindPtyOperation },
        term,
      );
      lastResult = result;
      const text = typeof result?.text === 'string' ? result.text : '';
      const normalized = normalizeCandidate(text);
      const comparison = compareClaudeRestoredPrompt(expectedText, text, result);
      const matched = comparison.matched;
      console.log('[Claude:Rewind] Grab restored input attempt=' + (attempt + 1)
        + ' success=' + (result?.success === true)
        + ' chars=' + text.length
        + ' matchedTarget=' + matched
        + ' matchMode=' + (comparison.mode || '-')
        + ' images=' + Number(result?.images || 0)
        + ' imagePaths=' + (Array.isArray(result?.imagePaths) ? result.imagePaths.length : 0)
        + ' expectedHash=' + pasteAuditHash(expectedText)
        + ' actualHash=' + pasteAuditHash(text)
        + ' expectedHead="' + pasteAuditPreview(expectedText) + '"'
        + ' actualHead="' + pasteAuditPreview(text) + '"'
        + ' actualTail="' + pasteAuditPreview(text, Math.max(0, text.length - 80)) + '"'
        + ' error=' + (result?.error || '-'));

      if (result?.success && normalized.length > 0) {
        return {
          success: true,
          text,
          attempt: attempt + 1,
          matchedTarget: matched,
          matchMode: comparison.mode,
          historyDraftText: comparison.historyDraftText,
          historyDraftImages: comparison.historyDraftImages,
          historyDraftWarning: comparison.historyDraftWarning,
        };
      }
      if (result?.success && attempt === delays.length - 1) {
        return {
          success: true,
          text,
          attempt: attempt + 1,
          matchedTarget: matched,
          empty: true,
          matchMode: comparison.mode,
          historyDraftText: comparison.historyDraftText,
          historyDraftImages: comparison.historyDraftImages,
          historyDraftWarning: comparison.historyDraftWarning,
        };
      }
      if (!result?.success && !['already_in_progress', 'claude_busy', 'editor_not_wired'].includes(result?.error)) {
        break;
      }
    }
    return {
      success: false,
      error: lastResult?.error || 'rewind_input_grab_failed',
      text: typeof lastResult?.text === 'string' ? lastResult.text : '',
      matchedTarget: false
    };
  }

  try {
    return await withPtyWriteLock(term, async () => {
      throwIfRewindCancelled('locked-before-preflight');
      const dz = claudeCtrlCDangerZone.get(tabId);
      if (dz) {
        console.log('[Claude:Rewind] DangerZone active — waiting for prompt return...');
        await dz.promise;
        throwIfRewindCancelled('after-danger-zone');
        console.log('[Claude:Rewind] DangerZone cleared');
      }

      // This callback is already inside the one Rewind PTY transaction. A
      // second lock through the public serialized capture wrapper waits for itself and
      // is the exact production deadlock from tab-3604/tab-3748.
      const inputCheck = await captureAgentInputAtWriteBoundary(
        tabId,
        'copy',
        'claude',
        { ownedWriteOperation: claudeRewindPtyOperation },
        term,
      );
      throwIfRewindCancelled('after-input-preflight');
      if (!inputCheck.success) {
        console.log('[Claude:Rewind] Input preflight failed: ' + (inputCheck.error || 'unknown'));
        return { success: false, error: inputCheck.error || 'input_check_failed' };
      }

      const copiedText = typeof inputCheck.text === 'string' ? inputCheck.text : '';
      const imageCount = Number(inputCheck.images || 0);
      const hasInput = copiedText.trim().length > 0 || imageCount > 0;
      const alreadyStashed = hasStashedMarker(tabId);
      console.log('[Claude:Rewind] Input preflight: hasInput=' + hasInput + ' chars=' + copiedText.length + ' images=' + imageCount + ' alreadyStashed=' + alreadyStashed);

      if (hasInput && alreadyStashed) {
        return {
          success: false,
          error: 'input_not_empty_with_existing_stash',
          message: 'Current input is not empty while Claude already has a stash'
        };
      }

      const targetInputText = String(targetFullText || targetText || '').trim();
      const targetMatchText = String(targetMenuText || targetText || targetInputText).trim();
      const targetPrefix = normalizeCandidate(targetMatchText);
      if (!targetPrefix) return { success: false, error: 'empty_target' };
      console.log('[Claude:Rewind] Target match key chars=' + targetPrefix.length
        + ' fullChars=' + targetInputText.length
        + ' matchHash=' + pasteAuditHash(targetMatchText)
        + ' fullHash=' + pasteAuditHash(targetInputText)
        + ' matchHead="' + pasteAuditPreview(targetMatchText) + '"'
        + ' fullHead="' + pasteAuditPreview(targetInputText) + '"');

      async function readRendererSelection(reason) {
        const snapshot = await requestTerminalVisibleBufferSnapshot(event.sender, tabId, reason, 700);
        const lines = snapshotLines(snapshot);
        const menuScope = inspectClaudeRewindMenuScope(lines);
        const selectionLines = menuScope.scopeFound ? menuScope.scopedLines : [];
        const itemLines = selectionLines.filter(isRewindPickerItemLine);
        const markerOrBgSelectedLine = findClaudeRewindPrimarySelectedLine(selectionLines);
        const fgHighlightedItemLines = itemLines.filter(line => line.hasNonDefaultFg === true);
        const colorOnlySelectedLine = fgHighlightedItemLines.length === 1 ? fgHighlightedItemLines[0] : null;
        const selectedLine = markerOrBgSelectedLine || colorOnlySelectedLine || null;
        const selectedItemIndex = selectedLine
          ? itemLines.findIndex(line => line.row === selectedLine.row && line.text === selectedLine.text)
          : -1;
        const previousItemLine = Number.isFinite(selectedLine?.row)
          ? [...itemLines].reverse().find(line => Number.isFinite(line?.row) && line.row < selectedLine.row) || null
          : (selectedItemIndex > 0 ? itemLines[selectedItemIndex - 1] : null);
        const selectedIsSlashCommand = !!selectedLine && isClaudeSlashCommandRow(selectedLine.rawText || selectedLine.text);
        const targetBeforeSelectedRaw = !!previousItemLine && textMatchesTargetSilent(previousItemLine.text, targetPrefix);
        const selectedCandidates = extractScopedSelectedCandidates(selectionLines)
          .slice(-5)
          .map(candidate => normalizeCandidate(candidate).substring(0, 140));
        const selectedText = selectedLine
          ? stripPickerSelectionMarker(selectedLine.rawText || selectedLine.text)
          : (selectedCandidates.length > 0 ? selectedCandidates[selectedCandidates.length - 1] : null);
        const selectedTextForBeforeMatch = normalizeCandidate(selectedText || '');
        const targetBeforeSelected = targetBeforeSelectedRaw && !selectedIsSlashCommand && selectedTextForBeforeMatch.length === 0;
        const selectedMatchesTarget = menuScope.scopeFound && textMatchesTarget(selectedText, targetPrefix);
        const targetAuthorization = authorizeClaudeRewindTargetSelection({
          menuScopeFound: menuScope.scopeFound,
          selectedText,
          selectedMatchesTarget,
          targetBeforeSelected,
          selectedIsSlashCommand,
        });
        const matchedTarget = targetAuthorization.matchedTarget;
        const visibleTargetLineObjects = selectionLines
          .filter(line => textMatchesTargetSilent(line.text, targetPrefix))
          .slice(-5);
        const selectedRow = Number.isFinite(selectedLine?.row) ? selectedLine.row : null;
        const targetAfterSelected = selectedRow != null
          && visibleTargetLineObjects.some(line => Number.isFinite(line.row) && line.row > selectedRow);
        const hasMoreAbove = menuScope.hasMoreAbove === true;
        const hasMoreBelow = menuScope.hasMoreBelow === true;
        const selectedAtFirstItem = selectedItemIndex === 0;
        const selectedAtLastItem = selectedItemIndex >= 0 && selectedItemIndex === itemLines.length - 1;
        const visibleTargetLines = visibleTargetLineObjects
          .map(line => ({ row: line.row, text: line.text.substring(0, 140), wrapped: line.wrapped }));
        const visibleLines = lines
          .slice(-16)
          .map(line => ({
            row: line.row,
            rawText: String(line.rawText || '').substring(0, 140),
            text: line.text.substring(0, 140),
            wrapped: line.wrapped,
            firstTextStyle: line.firstTextStyle || undefined,
            hasInverse: line.hasInverse || undefined,
            hasNonDefaultBg: line.hasNonDefaultBg || undefined,
            hasNonDefaultFg: line.hasNonDefaultFg || undefined,
          }));
        console.log('[Claude:Rewind:Snapshot] ' + JSON.stringify({
          tab: String(tabId).slice(-12),
          reason,
          success: snapshot?.success === true,
          error: snapshot?.error || null,
          rows: snapshot?.rows,
          cols: snapshot?.cols,
          viewportY: snapshot?.viewportY,
          baseY: snapshot?.baseY,
          menuScopeFound: menuScope.scopeFound,
          menuScopeReason: menuScope.reason,
          menuScopeStartRow: menuScope.scopeStartRow,
          menuScopeEndRow: menuScope.scopeEndRow,
          cursorX: snapshot?.cursorX,
          cursorY: snapshot?.cursorY,
          selectedCandidates,
          selectedRow,
          selectedRawText: (selectedLine?.rawText || '').substring(0, 140),
          selectedText: (selectedText || '').substring(0, 140),
          selectedMatchesTarget,
          matchedTarget,
          targetAuthorizationReason: targetAuthorization.reason,
          targetBeforeSelected,
          targetBeforeSelectedRaw,
          targetAfterSelected,
          selectedIsSlashCommand,
          selectedAtFirstItem,
          selectedAtLastItem,
          itemCount: itemLines.length,
          hasMoreAbove,
          hasMoreBelow,
          previousItemText: (previousItemLine?.text || '').substring(0, 140),
          selectedFirstTextStyle: selectedLine?.firstTextStyle || null,
          selectedStyles: selectedLine?.styles || [],
          selectedByColorOnly: !!colorOnlySelectedLine && !markerOrBgSelectedLine,
          fgHighlightedRows: fgHighlightedItemLines.map(line => ({ row: line.row, text: line.text.substring(0, 80) })),
          visibleTargetLines,
          visibleLines
        }));
        return {
          selectedText,
          selectedMatchesTarget,
          matchedTarget,
          targetBeforeSelected,
          targetBeforeSelectedRaw,
          targetAfterSelected,
          menuScopeFound: menuScope.scopeFound,
          menuScopeReason: menuScope.reason,
          selectedIsSlashCommand,
          selectedAtFirstItem,
          selectedAtLastItem,
          hasMoreAbove,
          hasMoreBelow,
          selectedCandidates,
          visibleTargetLines,
          previousItemText: previousItemLine?.text || '',
          snapshot
        };
      }

      const menuReadyRe = /Stay\s*at\s*current\s*position|Restore\s*and\s*fork|Rewind\s*conversation|Do\s*nothing|Enter\s*to\s*continue|Esc\s*to\s*cancel|↑\s*\d+\s*more\s*above|↓\s*\d+\s*more\s*below/i;
      function isClaudeRewindSlashHelpOpen(clean) {
        const text = String(clean || '');
        return /\/rewind\s+Restore\s+the\s+code\s+and\/or\s+conversation/i.test(text);
      }
      const menuWait = waitForPtyText(
        term,
        menuReadyRe,
        7000,
        '[Claude:Rewind:menu]'
      );

      throwIfRewindCancelled('before-rewind-command');
      console.log('[Claude:Rewind] Sending /rewind via slash command');
      const commandResult = await _safePasteAndSubmitInner(term, '/rewind', {
        submit: true,
        stashFirst: true,
        ctrlCFirst: false,
        dismissAutocomplete: true,
        fast: false,
        sendOperationContext: claudeRewindPtyOperation,
        logPrefix: '[Claude:Rewind:command]'
      });
      throwIfRewindCancelled('after-rewind-command');
      if (!commandResult || commandResult.success === false) {
        return { success: false, error: commandResult?.error || 'rewind_command_failed' };
      }

      const afterSlashSnapshot = await requestTerminalVisibleBufferSnapshot(
        event.sender,
        tabId,
        'claude-rewind-after-slash-enter',
        700
      );
      const afterSlashLines = snapshotLines(afterSlashSnapshot).slice(-12);
      const afterSlashClean = afterSlashLines.map(line => line.text).join('\n');
      console.log('[Claude:Rewind:SlashAfterEnter] success=' + (afterSlashSnapshot?.success === true)
        + ' error=' + (afterSlashSnapshot?.error || '-')
        + ' slashHelpOpen=' + isClaudeRewindSlashHelpOpen(afterSlashClean)
        + ' menuLooksOpen=' + menuReadyRe.test(afterSlashClean)
        + ' selectedCandidates=' + JSON.stringify(extractSnapshotSelectedCandidates(afterSlashSnapshot).slice(-5))
        + ' lines=' + JSON.stringify(afterSlashLines.map(line => ({
          row: line.row,
          text: line.text.substring(0, 120),
          wrapped: line.wrapped
        }))));

      if (isClaudeRewindSlashHelpOpen(afterSlashClean) && !menuReadyRe.test(afterSlashClean)) {
        throwIfRewindCancelled('before-slash-help-confirm');
        console.warn('[Claude:Rewind] Slash help still visible after /rewind Enter; sending confirm Enter');
        term.write('\r');
        await drainPtyData(term, 80, 500);
        const afterConfirmSnapshot = await requestTerminalVisibleBufferSnapshot(
          event.sender,
          tabId,
          'claude-rewind-after-slash-confirm-enter',
          700
        );
        const afterConfirmLines = snapshotLines(afterConfirmSnapshot).slice(-12);
        const afterConfirmClean = afterConfirmLines.map(line => line.text).join('\n');
        console.log('[Claude:Rewind:SlashConfirmEnter] success=' + (afterConfirmSnapshot?.success === true)
          + ' error=' + (afterConfirmSnapshot?.error || '-')
          + ' slashHelpOpen=' + isClaudeRewindSlashHelpOpen(afterConfirmClean)
          + ' menuLooksOpen=' + menuReadyRe.test(afterConfirmClean)
          + ' selectedCandidates=' + JSON.stringify(extractSnapshotSelectedCandidates(afterConfirmSnapshot).slice(-5))
          + ' lines=' + JSON.stringify(afterConfirmLines.map(line => ({
            row: line.row,
            text: line.text.substring(0, 120),
            wrapped: line.wrapped
          }))));
      }

      const menuRaw = await menuWait;
      throwIfRewindCancelled('after-menu-wait');
      const menuClean = cleanBuffer(menuRaw);
      const moreAboveMatch = menuClean.match(/↑\s*(\d+)\s*more\s*above/i);
      const moreAboveCount = moreAboveMatch ? Number(moreAboveMatch[1]) : 0;
      const initialCandidates = extractSelectedCandidates(menuRaw);
      const menuLooksOpen = menuReadyRe.test(menuClean);
      const slashHelpOpen = isClaudeRewindSlashHelpOpen(menuClean);
      if (!menuRaw || !menuLooksOpen) {
        console.error('[Claude:Rewind] Menu did not open. raw=' + menuRaw.length + ' candidates=' + initialCandidates.length + ' menuLooksOpen=' + menuLooksOpen + ' slashHelpOpen=' + slashHelpOpen + ' clean="' + menuClean.substring(0, 240) + '"');
        return { success: false, error: 'Rewind menu did not open' };
      }
      if (initialCandidates.length > 0) {
        console.log('[Claude:Rewind] Menu opened initial="' + initialCandidates[initialCandidates.length - 1].substring(0, 70) + '"');
      }

      let found = false;
      let rewindMenuLostReason = null;
      let pressCount = 0;
      let maxPresses = 40;
      const count = Number(rewindableCount);
      const idx = Number(targetIndex);
      if (Number.isFinite(count) && Number.isFinite(idx) && count > 0 && idx >= 0) {
        const duplicateSkipCount = Math.max(0, Number(skipDuplicates) || 0);
        const expectedDistance = Math.max(0, count - idx);
        const slashCommandSlack = Math.min(24, count + 12);
        maxPresses = Math.max(
          12,
          Math.min(
            120,
            expectedDistance + duplicateSkipCount + (Number.isFinite(moreAboveCount) ? moreAboveCount : 0) + slashCommandSlack
          )
        );
      }

      const hasDeterministicIndex = Number.isFinite(count) && Number.isFinite(idx) && count > 0 && idx >= 0 && idx < count;
      function getScrollCount(clean, direction) {
        const arrow = direction === 'above' ? '↑' : '↓';
        const match = String(clean || '').match(new RegExp(arrow + '\\s*(\\d+)\\s*more\\s*' + direction, 'i'));
        return match ? Number(match[1]) : 0;
      }

      function rewindFrameLines(clean) {
        return String(clean || '')
          .split(/[\r\n]+/)
          .map(line => normalizeCandidate(line))
          .filter(Boolean)
          .filter(line => !/^[─━╌═-]{5,}$/.test(line))
          .slice(-16)
          .map(line => line.substring(0, 140));
      }

      function logRewindFrame(raw, reason, extra = {}) {
        try {
          const clean = cleanBuffer(raw || '');
          const selectedCandidates = extractSelectedCandidates(raw || '')
            .slice(-5)
            .map(candidate => normalizeCandidate(candidate).substring(0, 140));
          const payload = {
            tab: String(tabId).slice(-12),
            reason,
            rawBytes: String(raw || '').length,
            target: targetPrefix.substring(0, 80),
            count,
            targetIndex: idx,
            skipDuplicates,
            pressCount,
            moreAbove: getScrollCount(clean, 'above'),
            moreBelow: getScrollCount(clean, 'below'),
            selectedCandidates,
            visibleLines: rewindFrameLines(clean),
            ...extra
          };
          console.log('[Claude:Rewind:Frame] ' + JSON.stringify(payload));
        } catch (err) {
          console.warn('[Claude:Rewind:Frame] log failed reason=' + reason + ' error=' + (err?.message || err));
        }
      }

      logRewindFrame(menuRaw, 'menu-open', {
        selectedText: (initialCandidates.length > 0 ? initialCandidates[initialCandidates.length - 1] : '').substring(0, 140),
        menuLooksOpen,
        moreAboveCount
      });

      async function readCurrentSelection(reason) {
        const raw = await drainPtyData(term, 80, 250);
        let candidates = extractSelectedCandidates(raw);
        let frameRaw = raw;
        if (candidates.length === 0 && raw.length === 0) {
          const probeRaw = await writeAndWait(
            '',
            selectionSignalRe,
            250,
            '[Claude:Rewind:probe]'
          );
          frameRaw = probeRaw;
          candidates = extractSelectedCandidates(probeRaw);
        }
        const ptySelectedText = candidates.length > 0 ? candidates[candidates.length - 1] : null;
        const screenSelection = await readRendererSelection(reason);
        const selectedText = screenSelection.menuScopeFound ? screenSelection.selectedText : null;
        const matchedTarget = screenSelection.menuScopeFound && screenSelection.matchedTarget;
        logRewindFrame(frameRaw, 'selected-check:' + reason, {
          ptySelectedText: (ptySelectedText || '').substring(0, 140),
          screenSelectedText: (screenSelection.selectedText || '').substring(0, 140),
          screenMatchedTarget: screenSelection.matchedTarget,
          selectedMatchesTarget: screenSelection.selectedMatchesTarget,
          targetBeforeSelected: screenSelection.targetBeforeSelected,
          targetBeforeSelectedRaw: screenSelection.targetBeforeSelectedRaw,
          selectedIsSlashCommand: screenSelection.selectedIsSlashCommand,
          menuScopeFound: screenSelection.menuScopeFound,
          menuScopeReason: screenSelection.menuScopeReason,
          selectedText: (selectedText || '').substring(0, 140),
          matchedTarget
        });
        console.log('[Claude:Rewind] Selected check (' + reason + ') -> "' + (selectedText || 'null').substring(0, 70) + '"');
        return selectedText;
      }

      async function scanForTarget(key, label, maxSteps, duplicateOffset, reason) {
        let duplicatesRemaining = duplicateOffset;
        let navKey = key;
        let navLabel = label;
        let suppressReverseAfterSkippedDuplicate = false;
        let menuLostReason = null;
        console.log('[Claude:Rewind] Navigating ' + reason + ': target="' + targetPrefix.substring(0, 180) + '" key=' + label + ' maxPresses=' + maxSteps + ' skipDuplicates=' + duplicateOffset);

        for (let i = 0; i < maxSteps; i++) {
          throwIfRewindCancelled(reason + '#' + i);
          if (hasRewindDeadlineExpired(reason + '#' + i)) break;
          const remainingMs = rewindDeadlineAt - Date.now();
          if (remainingMs < 250) {
            hasRewindDeadlineExpired(reason + '#remaining');
            break;
          }
          const navRaw = await writeAndWait(
            navKey,
            selectionSignalRe,
            Math.min(1200, remainingMs),
            '[Claude:Rewind:nav]'
          );
          const settleRaw = await drainPtyData(term, 80, 250);
          const frameRaw = navRaw + settleRaw;
          pressCount++;

          const candidates = extractSelectedCandidates(frameRaw);
          const ptySelectedText = candidates.length > 0 ? candidates[candidates.length - 1] : null;
          const screenSelection = await readRendererSelection(reason + ':' + label + '#' + pressCount);
          const selectedText = screenSelection.menuScopeFound ? screenSelection.selectedText : null;
          const matchedTarget = screenSelection.menuScopeFound && screenSelection.matchedTarget;
          logRewindFrame(frameRaw, reason + ':' + label + '#' + pressCount, {
            key: navLabel,
            ptySelectedText: (ptySelectedText || '').substring(0, 140),
            screenSelectedText: (screenSelection.selectedText || '').substring(0, 140),
            screenMatchedTarget: screenSelection.matchedTarget,
            selectedMatchesTarget: screenSelection.selectedMatchesTarget,
            targetBeforeSelected: screenSelection.targetBeforeSelected,
            targetBeforeSelectedRaw: screenSelection.targetBeforeSelectedRaw,
            targetAfterSelected: screenSelection.targetAfterSelected,
            selectedIsSlashCommand: screenSelection.selectedIsSlashCommand,
            menuScopeFound: screenSelection.menuScopeFound,
            menuScopeReason: screenSelection.menuScopeReason,
            selectedAtFirstItem: screenSelection.selectedAtFirstItem,
            selectedAtLastItem: screenSelection.selectedAtLastItem,
            hasMoreAbove: screenSelection.hasMoreAbove,
            hasMoreBelow: screenSelection.hasMoreBelow,
            previousItemText: (screenSelection.previousItemText || '').substring(0, 140),
            visibleTargetLines: screenSelection.visibleTargetLines,
            selectedText: (selectedText || '').substring(0, 140),
            matchedTarget,
            duplicatesRemaining
          });
          console.log('[Claude:Rewind] ' + navLabel + ' #' + pressCount + ' -> "' + (selectedText || 'null').substring(0, 70) + '"');

          if (!screenSelection.menuScopeFound) {
            menuLostReason = screenSelection.snapshot?.success === true
              ? 'claude_rewind_menu_lost'
              : 'claude_rewind_menu_unproven';
            console.error('[Claude:Rewind] Current picker proof disappeared during navigation reason='
              + screenSelection.menuScopeReason
              + ' snapshotSuccess=' + (screenSelection.snapshot?.success === true)
              + '; refusing further keys');
            break;
          }
          if (!selectedText && !matchedTarget) continue;
          if (!matchedTarget && screenSelection.targetAfterSelected && navKey !== '\x1b[B' && !suppressReverseAfterSkippedDuplicate) {
            navKey = '\x1b[B';
            navLabel = 'DOWN';
            console.warn('[Claude:Rewind] target is visible below selected row; switching direction to DOWN');
            continue;
          }
          if (!matchedTarget && navKey === '\x1b[A' && screenSelection.selectedAtFirstItem && !screenSelection.hasMoreAbove) {
            navKey = '\x1b[B';
            navLabel = 'DOWN';
            duplicatesRemaining = 0;
            suppressReverseAfterSkippedDuplicate = false;
            console.warn('[Claude:Rewind] reached top of rewind menu without target; switching direction to DOWN and clearing duplicate skip');
            continue;
          }
          if (!matchedTarget && navKey === '\x1b[B' && screenSelection.selectedAtLastItem && !screenSelection.hasMoreBelow) {
            navKey = '\x1b[A';
            navLabel = 'UP';
            suppressReverseAfterSkippedDuplicate = false;
            console.warn('[Claude:Rewind] reached bottom of rewind menu without target; switching direction to UP');
            continue;
          }
          if (!matchedTarget) continue;

          if (duplicatesRemaining > 0) {
            duplicatesRemaining--;
            suppressReverseAfterSkippedDuplicate = true;
            console.log('[Claude:Rewind] Skipping duplicate (' + duplicatesRemaining + ' remaining); keeping scan direction to avoid re-selecting skipped duplicate');
            continue;
          }

          return true;
        }
        if (menuLostReason) {
          rewindMenuLostReason = menuLostReason;
        }
        return false;
      }

      if (hasDeterministicIndex) {
        console.log('[Claude:Rewind] Timeline index is advisory only: Claude /rewind menu also contains slash-command rows; scanning selected rows by text. count=' + count + ' targetIndex=' + idx + ' skipDuplicates=' + skipDuplicates);
      }
      found = await scanForTarget('\x1b[A', 'UP', maxPresses, skipDuplicates, hasDeterministicIndex ? 'text-scan-index-advisory' : 'fallback');

      if (!found) {
        if (rewindMenuLostReason) {
          return {
            success: false,
            error: rewindMenuLostReason,
            pressCount,
            deadlineHit: rewindDeadlineHit,
          };
        }
        const notFoundError = rewindDeadlineHit
          ? 'Target not found in Claude /rewind menu before deadline'
          : 'Target not found in Claude /rewind menu';
        console.error('[Claude:Rewind] Target not found after ' + pressCount + ' presses. Verifying menu before close. deadlineHit=' + rewindDeadlineHit);
        try {
          const closeSelection = await readRendererSelection('not-found-close-preflight');
          if (closeSelection.menuScopeFound) {
            term.write('\x1b');
            await drainPtyData(term, 150, 500);
          } else {
            console.warn('[Claude:Rewind] Picker no longer proven at not-found cleanup; skipping Escape');
          }
        } catch {}
        return { success: false, error: notFoundError, pressCount, deadlineHit: rewindDeadlineHit };
      }

      throwIfRewindCancelled('before-confirm-preflight');
      const confirmSelection = await readRendererSelection('confirm-preflight');
      throwIfRewindCancelled('after-confirm-preflight');
      if (!confirmSelection.menuScopeFound) {
        console.error('[Claude:Rewind] Picker proof missing immediately before Enter; refusing mutation reason='
          + confirmSelection.menuScopeReason);
        return {
          success: false,
          error: confirmSelection.snapshot?.success === true
            ? 'claude_rewind_menu_lost_before_confirm'
            : 'claude_rewind_menu_unproven_before_confirm',
          pressCount,
        };
      }
      if (!confirmSelection.matchedTarget) {
        console.error('[Claude:Rewind] Selected row changed before Enter; refusing mutation selected="'
          + (confirmSelection.selectedText || '').substring(0, 100) + '"');
        try {
          term.write('\x1b');
          await drainPtyData(term, 150, 500);
        } catch {}
        return {
          success: false,
          error: 'claude_rewind_selection_changed_before_confirm',
          pressCount,
        };
      }

      console.log('[Claude:Rewind] Confirming target with Enter');
      throwIfRewindCancelled('before-confirm');
      markActiveRewindMutationStarted(activeRewindOperation, event.sender);
      await writeAndWait('\r', /\x1b\[\?2026l|\x1b\]7777;prompt:|[⏵❯╰]/, 6000, '[Claude:Rewind:confirm]');
      await waitForPtyText(term, /\x1b\]7777;prompt:|[⏵❯╰]|\x1b\[\?2026l/, 5000, '[Claude:Rewind:prompt]');

      let restoredHistoryDraft = null;
      if (pasteAfter && typeof pasteAfter === 'string' && pasteAfter.length > 0) {
        console.log('[Claude:Rewind] Pasting AI compact text (' + pasteAfter.length + ' chars)');
        const pasteResult = await _safePasteAndSubmitInner(term, pasteAfter, {
          submit: true,
          ctrlCFirst: true,
          stashFirst: false,
          fast: false,
          logPrefix: '[Claude:Rewind:paste]'
        });
        if (!pasteResult || pasteResult.success === false) {
          return { success: false, error: pasteResult?.error || 'paste_after_failed', pressCount };
        }
      } else if (targetInputText) {
        console.log('[Claude:Rewind] Moving clicked prompt out of terminal input into History draft (' + targetInputText.length + ' chars)');
        const grabResult = await grabRestoredRewindInput(targetInputText);
        if (!grabResult || grabResult.success === false) {
          console.warn('[Claude:Rewind] Could not verify terminal input clear after native rewind: ' + (grabResult?.error || 'unknown'));
          return {
            success: false,
            error: grabResult?.error || 'claude_rewind_restored_input_grab_failed',
            rollbackMayHaveApplied: true,
            pressCount,
          };
        }
        if (!grabResult.matchedTarget) {
          console.error('[Claude:Rewind] Restored input mismatch after confirmed selection; refusing success. expectedHash='
            + pasteAuditHash(targetInputText)
            + ' actualHash=' + pasteAuditHash(grabResult.text || '')
            + ' expectedHead="' + pasteAuditPreview(targetInputText) + '"'
            + ' actualHead="' + pasteAuditPreview(grabResult.text || '') + '"');
          return {
            success: false,
            error: grabResult.empty ? 'claude_rewind_restored_input_empty' : 'claude_rewind_restored_input_mismatch',
            rollbackMayHaveApplied: true,
            pressCount,
            grabbedChars: grabResult.text ? grabResult.text.length : 0,
            targetHash: pasteAuditHash(targetInputText),
            grabbedHash: pasteAuditHash(grabResult.text || ''),
          };
        } else {
          console.log('[Claude:Rewind] Terminal input grabbed+cleared chars=' + (grabResult.text ? grabResult.text.length : 0)
            + ' matchedTarget=' + grabResult.matchedTarget
            + ' matchMode=' + (grabResult.matchMode || '-')
            + ' attempt=' + grabResult.attempt);
          restoredHistoryDraft = grabResult;
          markClaudeEditableLastPrompt(tabId, {
            sessionId: bridgeKnownSessions.get(tabId) || null,
            targetUuid,
            targetText: targetInputText,
            source: 'claude-native-rewind',
          });
        }
      }

      return {
        success: true,
        found,
        targetIndex,
        targetUuid: targetUuid || null,
        pressCount,
        restoredInput: false,
        historyInputDraft: !pasteAfter && !!targetInputText,
        deliveryStatus: !pasteAfter && !!targetInputText ? 'editable-last-prompt' : undefined,
        historyDraftText: restoredHistoryDraft?.historyDraftText || restoredHistoryDraft?.text || targetInputText,
        historyDraftImages: Array.isArray(restoredHistoryDraft?.historyDraftImages) ? restoredHistoryDraft.historyDraftImages : undefined,
        historyDraftWarning: restoredHistoryDraft?.historyDraftWarning || '',
        restoredMatchMode: restoredHistoryDraft?.matchMode || '',
      };
    }, claudeRewindPtyOperation);
  } catch (err) {
    if (err?.code === 'rewind_cancelled') {
      try { term.write('\x1b'); } catch {}
      return { success: false, cancelled: true, error: 'rewind_cancelled', stage: err.stage };
    }
    console.log('[Claude:Rewind] Error:', err.message);
    try { term.write('\x1b'); } catch {}
    return { success: false, error: err.message };
  } finally {
    rewindCancelTabs.delete(tabId);
    finishActiveRewindOperation(activeRewindOperation);
  }
});

// Codex rewind through the native TUI backtrack flow.
// Codex does not expose `/rewind`: Esc primes backtrack, the second Esc opens
// the transcript overlay at the latest user prompt. Inside the overlay Codex's
// footer advertises "esc/← to edit prev" and "→ to edit next"; use Left Arrow
// for programmatic navigation so Esc remains only the open/prime key.
// After Codex prefills its composer, we move that text into History input via
// the existing Ctrl+G grab path so terminal composer stays empty.
function buildCodexHistoryDraftFromPayload(tabId, payload, fallbackText) {
  const baseText = String(payload?.message || fallbackText || '');
  const imagePaths = collectCodexPayloadImagePaths(payload);
  let seen = 0;
  let resolved = 0;
  let missing = 0;
  let text = baseText.replace(/\[Image(?:\s+#?(\d+))?\]/gi, (match, rawId) => {
    const explicitIndex = rawId ? Number(rawId) - 1 : NaN;
    const pathIndex = Number.isFinite(explicitIndex) && explicitIndex >= 0 ? explicitIndex : seen;
    const imagePath = imagePaths[pathIndex] || imagePaths[seen] || '';
    seen += 1;
    const staged = stageCodexImagePathForPasteSync(tabId, imagePath);
    if (staged.success) {
      resolved += 1;
      return '[imagePath: ' + staged.path + ']';
    }
    missing += 1;
    return '[imageError: codex_image_path_unavailable' + (rawId ? ' #' + rawId : '') + ']';
  });
  if (imagePaths.length > seen) {
    const extra = [];
    for (let i = seen; i < imagePaths.length; i++) {
      const staged = stageCodexImagePathForPasteSync(tabId, imagePaths[i]);
      if (staged.success) {
        resolved += 1;
        extra.push('[imagePath: ' + staged.path + ']');
      } else {
        missing += 1;
        extra.push('[imageError: codex_image_path_unavailable #' + (i + 1) + ']');
      }
    }
    if (extra.length > 0) text = [text, ...extra].filter(Boolean).join('\n');
  }
  return {
    text,
    imageCount: Math.max(imagePaths.length, seen),
    resolvedImages: resolved,
    missingImages: missing,
  };
}

function compareCodexRestoredPromptForTab(tabId, expectedText, restoredText, targetPayload) {
  const normalizeCandidate = text => String(text || "").replace(/\s+/g, " ").trim();
  const expected = normalizeCandidate(expectedText);
  const restored = normalizeCandidate(restoredText);
  const extraChars = Math.max(0, restored.length - expected.length);
  const containsExpected = !!(expected && restored.includes(expected));
  if (expected && restored === expected) {
    return { matched: true, mode: 'exact', containsExpected, extraChars };
  }
  if (expected && containsExpected && extraChars <= Math.max(80, Math.floor(expected.length * 0.5))) {
    return { matched: true, mode: 'contains-target', containsExpected, extraChars };
  }

  const expectedImageIdentity = normalizeCodexPromptImageSlots(expectedText, collectCodexPayloadImagePaths(targetPayload));
  const restoredImageIdentity = normalizeCodexPromptImageSlots(restoredText, collectCodexPayloadImagePaths(targetPayload));
  const hasImageShape = codexPromptHasImageMarker(expectedText)
    || codexPromptHasImageMarker(restoredText)
    || collectCodexPayloadImagePaths(targetPayload).length > 0;
  if (hasImageShape && expectedImageIdentity && expectedImageIdentity === restoredImageIdentity) {
    const draft = buildCodexHistoryDraftFromPayload(tabId, targetPayload, expectedText);
    return {
      matched: true,
      mode: draft.resolvedImages > 0 ? 'image-slot-with-rollout-path' : 'image-slot',
      containsExpected,
      extraChars,
      historyDraftText: draft.text,
      historyDraftWarning: draft.missingImages > 0
        ? 'Codex вернул prompt с картинкой, но сохранённый путь картинки недоступен. В draft оставлен явный imageError.'
        : '',
      imageCount: draft.imageCount,
      resolvedImages: draft.resolvedImages,
      missingImages: draft.missingImages,
    };
  }

  return { matched: false, mode: 'mismatch', containsExpected, extraChars };
}

function codexRewindPostEnterKey(tabId, generation) {
  return 'codex.rewind-post-enter.v1:' + tabId + ':' + generation;
}

function readCodexRewindPostEnterResult({ tabId, operationId, actionGeneration } = {}) {
  if (!tabId || !operationId || !actionGeneration) {
    return { success: false, error: 'codex_rewind_recovery_identity_required' };
  }
  const saved = projectManager.db.getAppState(codexRewindPostEnterKey(tabId, actionGeneration));
  if (!saved || saved.operationId !== operationId || saved.actionGeneration !== actionGeneration) {
    return { success: false, pending: true, error: 'codex_rewind_recovery_result_missing' };
  }
  return saved.result?.success === true ? saved.result : {
    success: false, pending: true, rollbackMayHaveApplied: !!saved.enterWrittenAt,
    operationId, handoffGeneration: actionGeneration, phase: saved.phase,
    error: saved.lastError || saved.captureResult?.error || 'codex_rewind_post_enter_pending',
  };
}

function persistCodexRewindPostEnter(record, patch) {
  const next = { ...record.durable, ...patch, updatedAt: Date.now() };
  let persisted = false;
  if (record.durable === null) {
    if (!projectManager.db.getAppState(record.key)) {
      projectManager.db.setAppState(record.key, next);
      persisted = JSON.stringify(projectManager.db.getAppState(record.key)) === JSON.stringify(next);
    }
  } else {
    persisted = projectManager.db.compareAndSetAppState(record.key, record.durable, next);
  }
  if (!persisted) {
    throw new Error('codex_rewind_post_enter_journal_changed');
  }
  record.durable = next;
  record.expectedInputRevision = next.expectedInputRevision;
  return next;
}

function createCodexRewindPostEnterOperation(tabId, {
  authority, expectation, expectedText, targetPayload, entered = false,
} = {}) {
  const key = codexRewindPostEnterKey(tabId, expectation.actionGeneration);
  const existing = codexRewindPostEnterOperations.get(key);
  if (existing) {
    if (existing.durable.operationId !== expectation.operationId
      || existing.durable.requestId !== expectation.requestId) {
      throw new Error('codex_rewind_post_enter_operation_changed');
    }
    return existing;
  }
  const prior = projectManager.db.getAppState(key);
  if (prior) throw new Error('codex_rewind_post_enter_requires_exact_recovery');
  const mirror = getHeadlessTerminalMirror(tabId);
  const record = {
    key, durable: null, authority, expectation: { ...expectation },
    terminalToken: expectation.terminalToken, mirror,
    operationId: expectation.operationId, requestId: expectation.requestId,
    actionGeneration: expectation.actionGeneration,
    originalLaunchId: authority.identity.launchId,
    mirrorGeneration: mirror?.generation || null,
    expectedInputRevision: getTerminalInputRevision(tabId),
  };
  persistCodexRewindPostEnter(record, {
    version: 1, phase: entered ? 'entered' : 'prepared', tabId,
    projectId: expectation.projectId, sourceSessionId: expectation.sourceSessionId,
    operationId: expectation.operationId, requestId: expectation.requestId,
    actionGeneration: expectation.actionGeneration,
    sourceLifecycleGeneration: expectation.sourceLifecycleGeneration,
    sourceRunSeq: expectation.sourceRunSeq,
    originalLaunchId: record.originalLaunchId,
    authorityId: authority.authorityId,
    expectedInputRevision: record.expectedInputRevision,
    mirrorGeneration: record.mirrorGeneration,
    actionWriteSeq: Number(mirror?.writeSeq || 0),
    expectedText, targetPayload,
    targetUuid: expectation.targetUuid, targetSourceLine: expectation.targetSourceLine,
    targetTextHash: expectation.targetTextHash, rollbackTurns: expectation.rollbackTurns,
    enterWrittenAt: entered ? Date.now() : null,
  });
  codexRewindPostEnterOperations.set(key, record);
  return record;
}

function isCodexRewindPostEnterCurrent(record) {
  if (!record || record.durable.phase === 'prepared') return false;
  const { tabId } = record.durable;
  const expectation = record.expectation;
  if (terminals.get(tabId) !== record.terminalToken
    || terminalCommandState.get(tabId)?.isRunning !== true
    || codexActionAuthorities.get(codexActionAuthorityKey(CODEX_ACTION_PROFILE_NATIVE_REWIND, tabId)) !== record.authority
    || getHeadlessTerminalMirror(tabId) !== record.mirror
    || getTerminalLifecycleGeneration(tabId) !== expectation.sourceLifecycleGeneration
    || Number(terminalCommandState.get(tabId)?.runSeq || 0) !== expectation.sourceRunSeq
    || codexLastRunCommandPayload.get(tabId)?.launchId !== record.originalLaunchId
    || resolveAuthoritativeTabProjectId(tabId) !== expectation.projectId
    || getTerminalInputRevision(tabId) !== record.expectedInputRevision
    || aiStoppingTabs.get(tabId)?.toolType === 'codex'
    || codexTurnWatchers.get(tabId)?.busy === true) return false;
  const receipt = inspectCodexNativeRewindCommitReceipt(tabId, expectation);
  if (receipt.committed === true) return true;
  const journal = readPendingCodexNativeRewindHandoff(tabId);
  const observed = currentCodexActionAuthorityIdentity(tabId, record.authority, {
    launchId: codexLastRunCommandPayload.get(tabId)?.launchId,
    sourceSessionId: codexWatchers.get(tabId)?.sourceSessionId,
  });
  return classifyCodexRewindPostEnterRecovery({
    journal, authority: record.authority, record,
    current: { ...observed, actionGeneration: codexWatchers.get(tabId)?.launchId,
      isRunning: terminalCommandState.get(tabId)?.isRunning === true,
      stopping: false, busy: false, mirrorGeneration: record.mirror?.generation },
  }).accepted === true;
}

function waitForCodexRewindPostEnterComposer(record, cancelPromise) {
  const { tabId } = record.durable;
  const mirror = record.mirror;
  return waitForCodexRewindInitializedComposer({
    readSnapshot: () => {
      const snapshot = mirror?.lastCommittedVisibleSnapshot;
      const captureBoundary = record.durable.captureOperation?.generation?.mirrorWriteSeq;
      const afterWriteSeq = Number.isFinite(captureBoundary) ? captureBoundary
        : record.durable.legacyRecovery ? -1 : record.durable.actionWriteSeq;
      return mirror?.failed !== true && snapshot?.writeSeq === mirror?.writeSeq
        && Number(snapshot?.writeSeq) > Number(afterWriteSeq)
        ? snapshot : null;
    },
    inspectReady: snapshot => {
      const ready = inspectCodexInputReadyVisibleText('', 'rewind-post-enter-capture', {
        lines: snapshot.lines, activePromptRow: snapshot.codexActivePrompt?.row,
      });
      return { ...ready, ready: ready.ready === true && isCodexTuiEffectivelyReady(tabId) };
    },
    isCurrent: () => isCodexRewindPostEnterCurrent(record),
    subscribe: check => {
      const onReady = (_event, change) => { if (change?.tabId === tabId) check(); };
      mirror?.synchronizedFrameWaiters?.add(check);
      ipcMain.on('agent:readiness-changed-internal', onReady);
      ipcMain.on('agent:tui-ready-internal', onReady);
      return () => {
        mirror?.synchronizedFrameWaiters?.delete(check);
        ipcMain.removeListener('agent:readiness-changed-internal', onReady);
        ipcMain.removeListener('agent:tui-ready-internal', onReady);
      };
    },
    cancelPromise,
  });
}

async function captureCodexRewindPostEnterInput(record, { cancelPromise, compare } = {}) {
  const { tabId } = record.durable;
  const ready = await waitForCodexRewindPostEnterComposer(record, cancelPromise);
  if (!ready.success) return ready;
  const saved = record.durable.captureResult;
  if (saved?.success === true) return saved;
  if (record.durable.captureOperation) {
    // An already-written Ctrl+G is never repeated. Reconcile its exact helper
    // outcome, including a late return after the original request timed out.
    const outcome = record.durable.captureAppliedProof || readCaptureOutcome(record.durable.captureOperation);
    const transfer = buildAgentDraftTransfer(record.durable.captureOperation, outcome,
      record.durable.preparedDraft, record.durable.helperId);
    if (transfer && isCodexRewindPostEnterCurrent(record)) {
      const result = { success: true, ...record.durable.preparedDraft,
        captureOperationId: record.durable.captureOperation.operationId,
        draftTransfer: transfer, editorReturnReady: true,
        inputRevision: record.expectedInputRevision, lateRecovery: true };
      persistCodexRewindPostEnter(record, { phase: 'captured', captureResult: result });
      const pending = grabInputPending.get(tabId);
      if (pending?.captureOperation?.operationId === record.durable.captureOperation.operationId) {
        releaseAgentInputCapturePending(tabId, pending, { parentReturned: true });
      }
      return result;
    }
    return { success: false, pending: true, rollbackMayHaveApplied: true,
      error: 'codex_rewind_capture_outcome_pending' };
  }
  return captureAgentInputAtWriteBoundary(tabId, 'grab', 'codex', {
    captureRequestId: record.requestId,
    captureGuard: () => isCodexRewindPostEnterCurrent(record),
    onCaptureArmed: (operation, identity) => {
      persistCodexRewindPostEnter(record, { phase: 'capture-armed',
        expectedInputRevision: identity.inputRevision, captureOperation: operation });
      record.captureOperation = operation;
    },
    prepareOwnedDraft: (draft, { helperId }) => {
      const comparison = compare(draft.capturedText);
      if (!isCodexRewindPostEnterCurrent(record) || comparison.matched !== true) {
        const error = new Error('codex_rewind_restored_input_mismatch');
        error.code = 'codex_rewind_restored_input_mismatch';
        throw error;
      }
      persistCodexRewindPostEnter(record, { phase: 'capture-prepared',
        preparedDraft: draft, helperId, comparison });
    },
    preserveOutcomeBeforeRelease: outcome => {
      if (captureOperationMatches(outcome, record.durable.captureOperation)
        && outcome.helperId === record.durable.helperId) {
        persistCodexRewindPostEnter(record, { captureAppliedProof: outcome });
      }
    },
    onCaptureResult: result => persistCodexRewindPostEnter(record, {
      phase: result?.draftTransfer ? 'captured' : 'capture-pending', captureResult: result,
    }),
  }, record.terminalToken);
}

async function completeCodexRewindPostEnterRecord(record, captureResult) {
  const { tabId, targetTextHash, actionGeneration } = record.durable;
  if (!isCodexRewindPostEnterCurrent(record)) {
    return { success: false, pending: true, rollbackMayHaveApplied: true,
      error: 'codex_rewind_post_enter_scope_changed' };
  }
  if (record.durable.result?.success === true) return record.durable.result;
  if (captureResult?.success !== true || !captureResult.draftTransfer
    || record.durable.comparison?.matched !== true) {
    return { success: false, pending: true, rollbackMayHaveApplied: true,
      error: captureResult?.error || 'codex_rewind_capture_outcome_pending' };
  }
  let receipt = inspectCodexNativeRewindCommitReceipt(tabId, record.expectation);
  let settlement = null;
  if (receipt.committed !== true) {
    settlement = await settleCodexWriterHandoffObservation(tabId,
      'programmatic-rewind-await-child', { waitForBranchMs: 8000 });
    receipt = inspectCodexNativeRewindCommitReceipt(tabId, record.expectation);
  }
  if (receipt.committed !== true) {
    if (!isCodexRewindPostEnterCurrent(record)) {
      return { success: false, pending: true, rollbackMayHaveApplied: true,
        error: 'codex_rewind_post_enter_scope_changed' };
    }
    const journal = readPendingCodexNativeRewindHandoff(tabId);
    if (journal?.phase === 'branch-draft-restored') {
      settlement = { bindingCommitted: true, handoffStatus: 'branch-draft-restored',
        sourceSessionId: journal.sourceSessionId, activeSessionId: journal.sourceSessionId };
    } else {
      const stable = await inspectManualCodexStableSourceRollbackOutcome(tabId, record.expectation);
      if (stable.proven === true) {
        const marked = markCodexWriterHandoffRollbackApplied(tabId, {
          actionGeneration, restoredTextHash: targetTextHash, appliedAtMs: stable.rollbackTimestampMs,
        });
        if (marked.success) settlement = await settleCodexWriterHandoffObservation(tabId,
          'programmatic-rewind-post-enter-recovery', { waitForBranchMs: 0 });
      } else {
        const marked = markCodexWriterHandoffBranchDraftRestored(tabId, {
          actionGeneration, restoredTextHash: targetTextHash, restoredAtMs: Date.now(),
        });
        if (marked.success) settlement = { bindingCommitted: true,
          handoffStatus: 'branch-draft-restored', sourceSessionId: record.durable.sourceSessionId,
          activeSessionId: record.durable.sourceSessionId };
      }
      // Child commit can race either CAS and consume the transient journal.
      receipt = inspectCodexNativeRewindCommitReceipt(tabId, record.expectation);
    }
  }
  if (receipt.committed === true) {
    settlement = { bindingCommitted: true, handoffStatus: 'adopted-child',
      sourceSessionId: receipt.sourceSessionId, activeSessionId: receipt.childSessionId,
      commitReceiptId: receipt.receiptId };
  }
  if (settlement?.bindingCommitted !== true) {
    return { success: false, pending: true, rollbackMayHaveApplied: true,
      error: 'codex_rewind_writer_handoff_unresolved', handoffGeneration: actionGeneration };
  }
  const comparison = record.durable.comparison;
  const result = {
    success: true, ...settlement, operationId: record.operationId,
    handoffGeneration: actionGeneration, restoredInput: false, historyInputDraft: true,
    historyDraftText: comparison.historyDraftText || captureResult.text,
    historyDraftWarning: comparison.historyDraftWarning || '',
    restoredMatchMode: comparison.mode || 'exact', rollbackTurns: record.durable.rollbackTurns,
    captureOperationId: captureResult.captureOperationId,
  };
  persistCodexRewindPostEnter(record, { phase: 'completed', result });
  if (receipt.committed === true) {
    finalizeCodexNativeRewindCommitReceipt(tabId, record.expectation, receipt);
  }
  return result;
}

async function recoverCodexRewindPostEnterOperation({ tabId, operationId, actionGeneration } = {}) {
  if (!tabId || !operationId || !actionGeneration) {
    return { success: false, error: 'codex_rewind_recovery_identity_required' };
  }
  const key = codexRewindPostEnterKey(tabId, actionGeneration);
  const term = terminals.get(tabId);
  if (!term) return { success: false, pending: true, error: 'codex_rewind_recovery_process_missing' };
  const operation = { kind: 'codex-rewind-post-enter', source: 'codex-rewind-recovery',
    tabId, manualInputYields: false, submitted: false, queuedAt: Date.now() };
  return withPtyWriteLock(term, async () => {
    let record = codexRewindPostEnterOperations.get(key);
    if (!record) {
      // Migration of the old failure: the original, revoked object still owns
      // the exact live PTY. Do not revive it or arm another action generation.
      const journal = readPendingCodexNativeRewindHandoff(tabId);
      const authority = codexActionAuthorities.get(codexActionAuthorityKey(
        CODEX_ACTION_PROFILE_NATIVE_REWIND, tabId));
      let observer = codexWatchers.get(tabId);
      const retainedIntent = codexSessionDiscoveryIntents.get(tabId);
      const discovery = observer || retainedIntent;
      const current = { ...currentCodexActionAuthorityIdentity(tabId, authority, {
        launchId: codexLastRunCommandPayload.get(tabId)?.launchId,
        sourceSessionId: discovery?.sourceSessionId,
      }), actionGeneration: discovery?.launchId,
      isRunning: terminalCommandState.get(tabId)?.isRunning === true,
      stopping: aiStoppingTabs.get(tabId)?.toolType === 'codex',
      busy: codexTurnWatchers.get(tabId)?.busy === true };
      const admitted = classifyCodexRewindPostEnterRecovery({ journal, authority, current });
      if (!admitted.accepted || journal.operationId !== operationId
        || journal.actionGeneration !== actionGeneration
        || discovery?.sourceMode !== 'writer-handoff'
        || (observer ? observer.sourceTerminalToken : authority?.identity?.terminalToken) !== term
        || discovery?.sourceLifecycleGeneration !== journal.sourceLifecycleGeneration
        || Number(discovery?.sourceRunSeq) !== journal.sourceRunSeq) {
        return { success: false, pending: true, error: admitted.reason || 'codex_rewind_recovery_owner_changed' };
      }
      const loaded = await codexDataModule._api.loadSessionRecords(journal.targetPhysicalSessionId, journal.cwd);
      const target = loaded?.records?.find(row => Number(row.__line) === journal.targetSourceLine);
      const expectedText = target ? codexUserMessagePresentationText(target) : '';
      if (!expectedText || hashCodexRewindTargetText(expectedText) !== journal.targetTextHash) {
        return { success: false, pending: true, error: 'codex_rewind_recovery_target_changed' };
      }
      // Close the await-to-admission gap with the same immutable scope.
      if (terminals.get(tabId) !== term || getTerminalInputRevision(tabId) !== current.inputRevision
        || codexWatchers.get(tabId) !== observer
        || codexSessionDiscoveryIntents.get(tabId) !== retainedIntent
        || readPendingCodexNativeRewindHandoff(tabId)?.actionGeneration !== actionGeneration) {
        return { success: false, pending: true, error: 'codex_rewind_recovery_owner_changed' };
      }
      const processProof = await inspectAiDescendantProcessesByTab(tabId, 'codex', { forceFresh: true });
      if (processProof?.status !== AI_PROCESS_LOOKUP_STATUS.FOUND
        || terminals.get(tabId) !== term || getTerminalInputRevision(tabId) !== current.inputRevision
        || codexLastRunCommandPayload.get(tabId)?.launchId !== current.launchId
        || getTerminalLifecycleGeneration(tabId) !== current.lifecycleGeneration) {
        return { success: false, pending: true, error: 'codex_rewind_recovery_process_unproven' };
      }
      if (!observer) {
        // Watcher expiry is not retirement of this still-running action. Reuse
        // its retained immutable intent/generation, never a new Rewind arm.
        startCodexSessionWatcher(mainWindow.webContents, {
          ...retainedIntent, tabId, sourceTerminalToken: term, handoffPending: true,
        });
        observer = codexWatchers.get(tabId);
        if (!observer) return { success: false, pending: true, error: 'codex_rewind_observer_restore_failed' };
        Object.assign(observer, {
          actionAuthority: authority, handoffActionStartedAtMs: journal.actionStartedAtMs,
          handoffActionGeneration: actionGeneration, handoffTerminalToken: term,
          handoffRunSeq: journal.sourceRunSeq, handoffPending: true,
          handoffSourceIncumbent: Object.freeze({
            kind: 'native-rewind-source-incumbent', sessionId: journal.sourceSessionId,
            filePath: retainedIntent.sourceFilePath, expectedBindingSessionId: journal.expectedBindingSessionId,
            actionGeneration, terminalToken: term, lifecycleGeneration: journal.sourceLifecycleGeneration,
            runSeq: journal.sourceRunSeq, actionAuthorityId: authority.authorityId,
            operationId, requestId: journal.requestId, capturedAtMs: journal.actionStartedAtMs,
          }),
        });
        codexSessionDiscoveryIntents.set(tabId, { ...retainedIntent });
      }
      record = createCodexRewindPostEnterOperation(tabId, {
        authority, expectation: { ...journal, terminalToken: term }, expectedText,
        targetPayload: target.payload, entered: true,
      });
      record.authorizedLegacyRecoveryAt = Date.now();
      record.authorizedLegacyRecoveryInputRevision = current.inputRevision;
      persistCodexRewindPostEnter(record, {
        authorizedLegacyRecoveryAt: record.authorizedLegacyRecoveryAt,
        authorizedLegacyRecoveryInputRevision: current.inputRevision,
        enterWrittenAt: journal.actionStartedAtMs, legacyRecovery: true,
      });
      observer.postEnterContinuation = record;
    }
    if (record.operationId !== operationId || record.actionGeneration !== actionGeneration) {
      return { success: false, pending: true, error: 'codex_rewind_recovery_owner_changed' };
    }
    if (record.durable.result?.success === true) return record.durable.result;
    const captured = await captureCodexRewindPostEnterInput(record, {
      compare: text => compareCodexRestoredPromptForTab(tabId,
        record.durable.expectedText, text, record.durable.targetPayload),
    });
    if (captured.success !== true) return { ...captured, pending: true, rollbackMayHaveApplied: true };
    return completeCodexRewindPostEnterRecord(record, captured);
  }, operation);
}

ipcMain.handle('codex:recover-post-enter-rewind', (_event, request = {}) => (
  recoverCodexRewindPostEnterOperation(request)
));
ipcMain.handle('codex:get-post-enter-rewind-result', (_event, request = {}) => (
  readCodexRewindPostEnterResult(request)
));

ipcMain.handle('codex:open-history-menu', async (_event, {
  tabId,
  opId,
  viewOwnerSessionId,
  expectedContentRevision,
  targetEntryRef,
  targetIndex,
  targetText,
  targetFullText,
  targetUuid,
  writerSessionId,
  writerAuthorization,
  writerLaunchId,
  rewindableCount,
  skipDuplicates = 0,
  pasteAfter,
}) => {
  const term = terminals.get(tabId);
  console.log('[Codex:Rewind] handler enter tab=' + String(tabId || '').slice(-12)
    + ' hasTerm=' + !!term
    + ' targetIndex=' + targetIndex
    + ' count=' + rewindableCount
    + ' skipDuplicates=' + skipDuplicates
    + ' pasteAfter=' + (typeof pasteAfter === 'string' ? pasteAfter.length : 0));
  if (!term) return { success: false, error: 'no_terminal' };
  if (codexRewindReservations.has(tabId)) {
    console.warn('[Codex:Rewind] refusing concurrent request tab=' + String(tabId).slice(-12));
    return { success: false, error: 'codex_rewind_already_in_progress' };
  }
  rewindCancelTabs.delete(tabId);

  let writer = null;
  let provisionalResumeRewind = false;
  let rewindActionAuthority = null;

  async function authorizeCodexRewindAtWriteBoundary(stage) {
    const readOperationScope = () => ({
      terminalToken: terminals.get(tabId) || null,
      lifecycleGeneration: getTerminalLifecycleGeneration(tabId),
      runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
      inputRevision: getTerminalInputRevision(tabId),
      observationGeneration: getCodexWriterObservationGeneration(tabId),
      launchId: codexLastRunCommandPayload.get(tabId)?.launchId || null,
      discoveryLaunchId: codexSessionDiscoveryIntents.get(tabId)?.launchId || null,
      sourceSessionId: writerSessionId,
    });
    const operationScope = readOperationScope();
    const operationCurrent = () => isSameCodexUnwrittenOperationScope(operationScope, readOperationScope());
    const projectCurrentWriter = () => {
      const proof = getCodexWriterProofSnapshot(tabId);
      if (!operationCurrent() || proof?.sessionId !== writerSessionId
        || !isCodexWriterUsableForMutation(tabId)) return null;
      return projectCodexWriterInspectionFromProof({
        proof, knownSessionId: codexKnownSessions.get(tabId),
        terminalToken: proof.terminalToken, currentTerminalToken: terminals.get(tabId),
        lifecycleGeneration: proof.lifecycleGeneration,
        currentLifecycleGeneration: getTerminalLifecycleGeneration(tabId),
        runSeq: proof.runSeq,
        currentRunSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
        commandRunning: terminalCommandState.get(tabId)?.isRunning === true,
      });
    };
    if (terminals.get(tabId) !== term) {
      return { success: false, error: 'codex_terminal_changed_before_rewind' };
    }
    if (aiStoppingTabs.get(tabId)?.toolType === 'codex') {
      return { success: false, error: 'codex_stopping' };
    }
    const lookup = await inspectAiDescendantProcessesByTab(tabId, 'codex');
    if (lookup.status === AI_PROCESS_LOOKUP_STATUS.UNKNOWN) {
      console.warn('[Codex:Rewind] process lookup unavailable stage=' + stage + ' tab=' + tabId);
      return aiProcessLookupFailureResult(lookup);
    }
    const candidates = lookup.matches;
    if (candidates.length === 0) {
      console.log('[Codex:Rewind] no live Codex process stage=' + stage + ' shellPid=' + term.pid + ' tab=' + tabId);
      return { success: false, error: 'no_codex_session' };
    }
    if (!isCodexTuiEffectivelyReady(tabId)) {
      console.log('[Codex:Rewind] TUI input-ready missing stage=' + stage + ' tab=' + String(tabId).slice(-12));
      return { success: false, error: 'codex_not_input_ready' };
    }
    const readyMeta = codexTuiReadyMeta.get(tabId) || null;
    console.log('[Codex:Rewind] authorization stage=' + stage + ' tab=' + String(tabId).slice(-12)
      + ' readyAgeMs=' + (readyMeta?.at ? Date.now() - readyMeta.at : 'unknown')
      + ' readySource=' + (readyMeta?.source || '-')
      + ' readyReason=' + (readyMeta?.reason || '-')
      + ' readyPreview=' + JSON.stringify(String(readyMeta?.preview || '').slice(0, 180))
      + ' pids=' + candidates.map(p => p.pid).join(','));

    let authorizedWriter = await reconcileCodexWriterFromProcess(tabId, {
      reason: 'codex-rewind-' + stage,
      sender: mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    });
    if (!operationCurrent()) return { success: false, error: 'codex_operation_changed_before_rewind' };
    const currentProof = getCodexWriterProofSnapshot(tabId);
    if (canUseCodexProofAfterDiscoveryCompletion({
      observation: authorizedWriter,
      captured: operationScope,
      current: readOperationScope(),
      proof: currentProof,
      proofUsable: isCodexWriterUsableForMutation(tabId),
      processPids: candidates.map(candidate => candidate.pid),
    })) {
      // The stale observation remains stale. Only project the separately
      // accepted current proof; never replay its adoption or a PTY action.
      const projected = projectCurrentWriter();
      if (projected) {
        console.log('[Codex:Rewind] current same-source proof after discovery completion'
          + ' stage=' + stage + ' tab=' + String(tabId).slice(-12)
          + ' source=' + String(projected.sessionId).slice(0, 8));
        authorizedWriter = projected;
      }
    }
    let provisional = false;
    let provisionalAuthorization = null;
    if (authorizedWriter?.status === 'provisional-source') {
      const authorization = await ensureCodexSubmissionWatcher(
        tabId,
        terminalProjects.get(tabId),
        'rewind-main-' + stage,
      );
      const strengthened = projectCurrentWriter();
      if (authorization?.available === true
        && authorization.sessionId === writerSessionId
        && writerAuthorization === 'provisional-resume-source'
        && !!writerLaunchId && strengthened?.launchId === writerLaunchId) {
        authorizedWriter = strengthened;
      }
      provisional = authorization?.available === true
        && authorization.kind === 'provisional-source'
        && authorizedWriter.status === 'provisional-source'
        && authorization.sessionId === authorizedWriter.sessionId
        && writerAuthorization === 'provisional-resume-source'
        && writerSessionId === authorizedWriter.sessionId
        && writerLaunchId === authorization.launchId;
      if (provisional) provisionalAuthorization = authorization;
    }
    let exactSourceContext = null;
    let actionLaunchId = null;
    if (authorizedWriter?.status === 'adopted') {
      const proof = getCodexWriterProofSnapshot(tabId);
      const sameLaunchStrengthening = writerAuthorization === 'provisional-resume-source'
        && !!writerLaunchId && proof?.launchId === writerLaunchId;
      if ((writerAuthorization !== 'confirmed-writer' && !sameLaunchStrengthening)
        || writerSessionId !== authorizedWriter.sessionId
        || proof?.sessionId !== authorizedWriter.sessionId
        || !isCodexWriterUsableForMutation(tabId)) {
        return { success: false, error: 'codex_writer_changed_before_rewind' };
      }
      exactSourceContext = resolveCodexNativeRewindSourceContext(tabId);
      actionLaunchId = resolveCodexNativeRewindActionGeneration({
        writerActionGeneration: proof?.actionGeneration,
        writerLaunchId: proof?.launchId,
        lifecycleGeneration: exactSourceContext?.lifecycleGeneration,
        runSeq: exactSourceContext?.runSeq,
        allowLiveRunFallback: true,
      });
    } else if (!provisional) {
      console.warn('[Codex:Rewind] writer proof unavailable stage=' + stage
        + ' tab=' + String(tabId).slice(-12)
        + ' status=' + (authorizedWriter?.status || 'unknown')
        + ' error=' + (authorizedWriter?.error || '-'));
      return {
        success: false,
        error: 'codex_writer_unproven',
        writerStatus: authorizedWriter?.status || 'unknown',
        writerError: authorizedWriter?.error || null,
      };
    } else {
      // Reuse the exact action-scoped Resume observation rather than
      // reconstructing only its ids. The pre-Enter journal also needs the
      // proven rollout file path; dropping it here produced
      // rewind-source-incumbent-context-missing after an otherwise valid
      // provisional Resume (the 09.09 iOS Inbox incident).
      exactSourceContext = resolveCodexNativeRewindSourceContext(tabId);
      actionLaunchId = provisionalAuthorization?.launchId || writerLaunchId || null;
    }
    if (exactSourceContext?.allowed !== true
      || exactSourceContext.runtimeSourceSessionId !== authorizedWriter.sessionId
      || !actionLaunchId) {
      console.warn('[Codex:Rewind] action source rejected stage=' + stage
        + ' tab=' + String(tabId).slice(-12)
        + ' writer=' + String(authorizedWriter?.sessionId || 'none').slice(0, 8)
        + ' mode=' + (exactSourceContext?.mode || '-')
        + ' source=' + String(exactSourceContext?.runtimeSourceSessionId || 'none').slice(0, 8)
        + ' reason=' + (exactSourceContext?.reason || (!actionLaunchId ? 'action-generation-unproven' : 'source-mismatch'))
        + ' lifecycle=' + (exactSourceContext?.lifecycleGeneration || '-')
        + ' run=' + (exactSourceContext?.runSeq ?? '-'));
      return {
        success: false,
        error: 'codex_rewind_action_source_unproven',
        writerStatus: authorizedWriter?.status || 'unknown',
        sourceReason: exactSourceContext?.reason || 'launch-generation-unproven',
      };
    }
    if (!provisional) {
      await ensureCodexTurnWatcher(tabId, authorizedWriter.sessionId, terminalProjects.get(tabId));
    }
    const turnState = codexTurnWatchers.get(tabId);
    if (!operationCurrent()) return { success: false, error: 'codex_operation_changed_before_rewind' };
    if (!isCodexTuiEffectivelyReady(tabId)) return { success: false, error: 'codex_not_input_ready' };
    if (aiStoppingTabs.get(tabId)?.toolType === 'codex') {
      return { success: false, error: 'codex_stopping' };
    }
    if (turnState?.busy === true || hasCodexPromptOrTurnInFlight(tabId)) {
      console.log('[Codex:Rewind] refusing busy turn stage=' + stage + ' tab=' + String(tabId).slice(-12));
      return { success: false, error: 'codex_busy' };
    }
    return {
      success: true,
      writer: authorizedWriter,
      provisionalResumeRewind: provisional,
      sourceContext: exactSourceContext,
      launchId: actionLaunchId,
    };
  }

  function normalizeCandidate(text) {
    return String(text || '').replace(/\s+/g, ' ').trim();
  }

  function findCodexRollbackFailureLine(text) {
    const failureLine = String(text || '')
      .split(/\r?\n/)
      .map(line => line.trim())
      .find(line => /^■\s*(?:Cannot rollback while a turn is in progress\.?|num_turns must be >= 1|thread rollback requires persisted thread history|failed to (?:flush|load) thread persistence for rollback replay)/i.test(line));
    return failureLine || '';
  }

  async function inspectCodexRollbackFailureAfterConfirm(confirmClean) {
    const flushed = await flushHeadlessTerminalMirror(tabId);
    const snapshot = flushed.success
      ? getHeadlessVisibleBufferSnapshot(tabId, 'codex-rewind-confirm-result')
      : { success: false, error: flushed.error || 'headless-flush-failed' };
    const visibleText = snapshot.success
      ? (snapshot.lines || []).map(line => String(line?.text || '')).join('\n')
      : '';
    // A Codex error cell is rendered with a leading solid square. Searching
    // arbitrary PTY deltas is unsafe because the user's restored prompt can
    // itself contain words such as "Cannot rollback".
    const failureLine = findCodexRollbackFailureLine(visibleText)
      || (!snapshot.success ? findCodexRollbackFailureLine(confirmClean) : '');
    return {
      rejected: !!failureLine,
      failureLine,
      proofSource: snapshot.success ? 'headless-current-screen' : 'fresh-confirm-frame',
      snapshotError: snapshot.success ? '' : (snapshot.error || 'headless-snapshot-unavailable'),
    };
  }

  function codexUserUuidForRecord(sessionId, record) {
    return 'codex-user-' + (sessionId || 'unknown') + '-' + record.__line;
  }

  async function buildCodexResponseUserRewindPayload(record) {
    const payload = record?.payload || {};
    if (record?.type !== 'response_item'
      || payload.type !== 'message'
      || payload.role !== 'user') {
      return null;
    }
    const message = codexUserMessagePresentationText(record);
    if (!message) return null;
    const refs = [];
    const parts = Array.isArray(payload.content) ? payload.content : [];
    for (let index = 0; index < parts.length; index += 1) {
      const part = parts[index] || {};
      const type = String(part.type || '').toLowerCase();
      if (!type.includes('image')) continue;
      const imageUrl = typeof part.image_url === 'string'
        ? part.image_url
        : (typeof part.imageUrl === 'string' ? part.imageUrl : '');
      if (imageUrl && path.isAbsolute(imageUrl)) {
        refs.push({ path: imageUrl, availability: 'available' });
        continue;
      }
      const match = imageUrl.match(/^data:(image\/[a-z0-9.+-]+);base64,([a-z0-9+/=_-]+)$/i);
      if (!match) continue;
      const bytes = Buffer.from(match[2], 'base64');
      if (bytes.length === 0 || bytes.length > 32 * 1024 * 1024) continue;
      const ref = await promptQueueAssetStore.materializeBuffer(bytes, {
        id: index + 1,
        mediaType: match[1].toLowerCase(),
        size: bytes.length,
      });
      if (ref?.availability === 'available' && ref.path) refs.push(ref);
    }
    if (refs.length > 0) leasePromptQueueAssetRefs(refs);
    return {
      type: 'user_message',
      message,
      local_images: refs.map((ref) => ref.path),
      images: [],
      text_elements: [],
    };
  }

  async function loadCodexRewindTargetPayload(compositeTarget = null) {
    const resolvedSessionId = compositeTarget?.entry?.physicalSessionId || writer.sessionId;
    const resolvedTargetUuid = compositeTarget?.entry?.rawUuid
      || compositeTarget?.entry?.uuid
      || targetUuid;
    if (!resolvedSessionId || !resolvedTargetUuid) return null;
    const cwd = terminalProjects.get(tabId);
    try {
      const loaded = await codexDataModule._api.loadSessionRecords(resolvedSessionId, cwd);
      if (!loaded?.success) {
        console.warn('[Codex:Rewind] target payload load failed session=' + String(resolvedSessionId).slice(0, 8)
          + ' error=' + (loaded?.error || 'unknown'));
        return null;
      }
      for (const record of loaded.records || []) {
        const payload = record?.payload || {};
        const eventUser = record?.type === 'event_msg' && payload.type === 'user_message';
        const responseUser = record?.type === 'response_item'
          && payload.type === 'message'
          && payload.role === 'user';
        if (!eventUser && !responseUser) continue;
        if (codexUserUuidForRecord(resolvedSessionId, record) === resolvedTargetUuid) {
          const targetPayload = eventUser
            ? {
                ...payload,
                message: codexUserMessagePresentationText(record),
              }
            : await buildCodexResponseUserRewindPayload(record);
          if (!targetPayload) continue;
          const imagePaths = collectCodexPayloadImagePaths(targetPayload);
          console.log('[Codex:Rewind] target payload found uuid=' + String(resolvedTargetUuid).slice(0, 48)
            + ' line=' + record.__line
            + ' carrier=' + (eventUser ? 'event_msg' : 'response_item')
            + ' messageLen=' + String(targetPayload.message || '').length
            + ' images=' + imagePaths.length
            + ' textElements=' + (Array.isArray(targetPayload.text_elements) ? targetPayload.text_elements.length : 0));
          return { sessionId: resolvedSessionId, sourceLine: record.__line, payload: targetPayload };
        }
      }
      console.warn('[Codex:Rewind] target payload not found uuid=' + String(resolvedTargetUuid).slice(0, 80)
        + ' session=' + String(resolvedSessionId).slice(0, 8));
    } catch (error) {
      console.warn('[Codex:Rewind] target payload lookup error:', error?.message || error);
    }
    return null;
  }

  function compareCodexRestoredPrompt(expectedText, restoredText, targetPayload) {
    return compareCodexRestoredPromptForTab(tabId, expectedText, restoredText, targetPayload);
  }

  function stripCodexRewindOverlayChrome(clean) {
    return normalizeCandidate(String(clean || '')
      .replace(/\/\s*T\s*R\s*A\s*N\s*S\s*C\s*R\s*I\s*P\s*T\s*\/[\s/\\|_-]*/gi, ' ')
      .replace(/[─━-]{10,}\s*\d+%\s*[─━-]{0,}/g, ' ')
      .replace(/↑\/↓\s+to\s+scroll.*$/gmi, ' ')
      .replace(/pgup\/pgdn\s+to\s+page.*$/gmi, ' ')
      .replace(/home\/end\s+to\s+jump.*$/gmi, ' ')
      .replace(/q\s+to\s+quit.*$/gmi, ' ')
      .replace(/esc\/←\s+to\s+edit\s+prev.*$/gmi, ' ')
      .replace(/→\s+to\s+edit\s+next.*$/gmi, ' ')
      .replace(/enter\s+to\s+edit\s+message.*$/gmi, ' ')
      .replace(/\bgpt-[^\n]*Context\s+\d+%[^\n]*/gi, ' '));
  }

  function buildCodexRewindAnchors(expectedText) {
    const normalized = normalizeCandidate(expectedText);
    const anchors = [];
    const seen = new Set();
    const push = (value, options = {}) => {
      const anchor = normalizeCandidate(value);
      const words = anchor.split(/\s+/).filter(Boolean);
      const allowShortFullTarget = options.allowShortFullTarget === true
        && anchor.length >= 8
        && words.length >= 2;
      if ((!allowShortFullTarget && anchor.length < 24) || seen.has(anchor)) return;
      seen.add(anchor);
      anchors.push(anchor);
    };
    push(normalized.slice(0, 96));
    push(normalized.slice(0, 56));
    if (normalized.length <= 140) push(normalized, { allowShortFullTarget: true });

    const words = normalized.split(/\s+/).filter(Boolean);
    for (const size of [12, 10, 8, 6]) {
      if (words.length < size) continue;
      const step = Math.max(2, Math.floor(size / 2));
      for (let i = 0; i <= words.length - size; i += step) {
        const phrase = words.slice(i, i + size).join(' ');
        if (phrase.length >= 48) push(phrase);
      }
    }
    return anchors;
  }

  function buildCodexShortRewindAnchors(expectedText) {
    const normalized = normalizeCandidate(expectedText);
    const words = normalized.split(/\s+/).filter(Boolean);
    if (normalized.length < 2 || normalized.length > 32 || words.length > 4) return [];
    return [normalized];
  }

  function findCodexOverlayAnchorRole(visible, anchor) {
    const normalizedAnchor = normalizeCandidate(anchor);
    if (!normalizedAnchor) return null;
    if (!visible.includes(normalizedAnchor)) return null;
    // Codex transcript overlay uses `›` as the prompt/cursor marker. Dev logs
    // from 019edc60 show a valid selected target rendered as `› <target>`, so
    // `›` must not be treated as proof that the target is only the next row.
    return { selected: true, nextPrompt: false };
  }

  function matchCodexRewindOverlayFrame(frame, expectedText) {
    const clean = String(frame?.clean || '');
    const visible = stripCodexRewindOverlayChrome(clean);
    const anchors = buildCodexRewindAnchors(expectedText);
    const shortAnchors = buildCodexShortRewindAnchors(expectedText);
    let matchedAnchor = '';
    let nextPromptAnchor = '';
    for (const anchor of anchors) {
      const role = findCodexOverlayAnchorRole(visible, anchor);
      if (!role) continue;
      if (role.selected && !matchedAnchor) matchedAnchor = anchor;
      if (role.nextPrompt && !nextPromptAnchor) nextPromptAnchor = anchor;
      if (matchedAnchor) break;
    }
    const matchedShortAnchor = matchedAnchor
      ? ''
      : shortAnchors.find(anchor => {
        const role = findCodexOverlayAnchorRole(visible, anchor);
        if (role?.selected) return true;
        if (role?.nextPrompt && !nextPromptAnchor) nextPromptAnchor = anchor;
        return false;
      });
    return {
      matched: !!(matchedAnchor || matchedShortAnchor),
      anchor: matchedAnchor || matchedShortAnchor || '',
      anchorCount: anchors.length + shortAnchors.length,
      anchorMode: matchedAnchor ? 'long' : (matchedShortAnchor ? 'short-prompt' : 'none'),
      targetAfterSelected: !!nextPromptAnchor && !(matchedAnchor || matchedShortAnchor),
      nextPromptAnchor,
      visiblePreview: visible.slice(0, 220),
      visibleText: visible,
      targetPreview: normalizeCandidate(expectedText).slice(0, 220),
      visibleLength: visible.length,
      rawLength: String(frame?.raw || '').length,
    };
  }

  function matchCodexRewindActivePromptSnapshot(snapshot, expectedText) {
    const active = snapshot?.codexActivePrompt || null;
    const rowMatch = matchCodexRewindSelectedRows(snapshot, expectedText);
    const activeText = normalizeCandidate(rowMatch?.matched ? rowMatch.text : (active?.text || ''));
    const activePromptText = stripLeadingCodexComposerPromptGlyph(activeText);
    const expected = normalizeCandidate(expectedText);
    const anchors = buildCodexRewindAnchors(expectedText);
    const shortAnchors = buildCodexShortRewindAnchors(expectedText);
    const activePrefix = activePromptText.slice(0, Math.min(96, activePromptText.length)).trim();
    const activePrefixWords = activePrefix.split(/\s+/).filter(Boolean);
    const prefixContradictsTarget = rowMatch?.matched === false || (activePrefix.length >= 16
      && activePrefixWords.length >= 3
      && !expected.startsWith(activePrefix));
    const matchedAnchor = prefixContradictsTarget
      ? ''
      : anchors.find(anchor => activeText.includes(normalizeCandidate(anchor))) || '';
    const matchedShortAnchor = matchedAnchor
      ? ''
      : (prefixContradictsTarget ? '' : shortAnchors.find(anchor => activeText.includes(normalizeCandidate(anchor))) || '');
    const activeWords = activePromptText.split(/\s+/).filter(Boolean);
    const matchedVisibleLineAnchor = (matchedAnchor || matchedShortAnchor)
      ? ''
      : (
        activePromptText.length >= 16
        && activeWords.length >= 3
        && expected.startsWith(activePromptText)
          ? activePromptText
          : ''
      );
    return {
      success: snapshot?.success === true,
      error: snapshot?.error || '',
      matched: !prefixContradictsTarget && !!(matchedAnchor || matchedShortAnchor || matchedVisibleLineAnchor),
      anchor: matchedAnchor || matchedShortAnchor || matchedVisibleLineAnchor || '',
      anchorCount: anchors.length + shortAnchors.length,
      anchorMode: prefixContradictsTarget ? 'active-prefix-contradicts-target' : (matchedAnchor ? 'active-long' : (matchedShortAnchor ? 'active-short-prompt' : (matchedVisibleLineAnchor ? 'active-visible-prefix' : 'active-none'))),
      targetAfterSelected: false,
      nextPromptAnchor: '',
      activePromptRow: active?.row ?? null,
      activePromptPreview: activeText.slice(0, 220),
      activePromptStyles: Array.isArray(active?.styles) ? active.styles.slice(0, 4) : [],
      prefixContradictsTarget,
    };
  }

  function getCodexPromptRowsFromSnapshot(snapshot) {
    const lines = Array.isArray(snapshot?.lines) ? snapshot.lines : [];
    return lines
      .filter(line => hasCodexComposerPromptGlyph(String(line?.text || '')))
      .map(line => ({
        row: line?.row ?? null,
        text: normalizeCandidate(line?.text || '').slice(0, 120),
        firstTextStyle: String(line?.firstTextStyle || ''),
        styles: Array.isArray(line?.styles) ? line.styles.slice(0, 4) : [],
        hasInverse: line?.hasInverse === true,
        hasNonDefaultBg: line?.hasNonDefaultBg === true,
        activeByInverse: line?.activeByInverse === true,
      }))
      .slice(-12);
  }

  function getCodexTargetRowsFromSnapshot(snapshot, expectedText) {
    const lines = Array.isArray(snapshot?.lines) ? snapshot.lines : [];
    const target = normalizeCandidate(expectedText);
    const targetPrefix = target.slice(0, Math.min(90, target.length));
    const anchors = [
      targetPrefix,
      ...buildCodexShortRewindAnchors(expectedText),
      ...buildCodexRewindAnchors(expectedText),
    ]
      .map(anchor => stripLeadingCodexComposerPromptGlyph(normalizeCandidate(anchor)))
      .filter(anchor => anchor.length >= 2);
    return lines
      .filter(line => hasCodexComposerPromptGlyph(String(line?.text || '')))
      .map(line => {
        const text = normalizeCandidate(line?.text || '');
        const promptText = stripLeadingCodexComposerPromptGlyph(text);
        const matchesTarget = anchors.some(anchor => (
          promptText.includes(anchor)
          || anchor.includes(promptText.slice(0, Math.min(90, promptText.length)))
        ));
        return {
          row: line?.row ?? null,
          text: text.slice(0, 180),
          firstTextStyle: String(line?.firstTextStyle || ''),
          styles: Array.isArray(line?.styles) ? line.styles.slice(0, 6) : [],
          hasInverse: line?.hasInverse === true,
          hasNonDefaultBg: line?.hasNonDefaultBg === true,
          activeByInverse: line?.activeByInverse === true,
          matchesTarget,
        };
      })
      .filter(row => row.matchesTarget || row.hasInverse || row.hasNonDefaultBg)
      .slice(-16);
  }

  async function matchCodexRewindSelection(frame, expectedText, reason) {
    const rawMatch = matchCodexRewindOverlayFrame(frame, expectedText);
    const snapshot = await requestTerminalVisibleBufferSnapshot(
      _event.sender,
      tabId,
      'codex-rewind-' + reason,
      700
    );
    const activeMatch = matchCodexRewindActivePromptSnapshot(snapshot, expectedText);
    const promptRows = getCodexPromptRowsFromSnapshot(snapshot);
    const targetRows = getCodexTargetRowsFromSnapshot(snapshot, expectedText);
    const activeRowNumber = Number(activeMatch.activePromptRow);
    const hasActiveRow = Number.isFinite(activeRowNumber);
    const matchingTargetRows = targetRows
      .filter(row => row?.matchesTarget === true && Number.isFinite(Number(row.row)))
      .map(row => ({ ...row, rowNumber: Number(row.row) }));
    const targetRowsAfterActive = hasActiveRow
      ? matchingTargetRows
        .filter(row => row.rowNumber > activeRowNumber)
        .sort((a, b) => a.rowNumber - b.rowNumber)
      : [];
    const targetRowsBeforeActive = hasActiveRow
      ? matchingTargetRows
        .filter(row => row.rowNumber < activeRowNumber)
        .sort((a, b) => b.rowNumber - a.rowNumber)
      : [];
    const targetAfterActiveByRows = targetRowsAfterActive.length > 0;
    const targetBeforeActiveByRows = targetRowsBeforeActive.length > 0;
    console.log('[Codex:Rewind:ActiveSnapshot] reason=' + reason
      + ' success=' + activeMatch.success
      + ' error=' + (activeMatch.error || '-')
      + ' matched=' + activeMatch.matched
      + ' row=' + (activeMatch.activePromptRow ?? 'none')
      + ' mode=' + activeMatch.anchorMode
      + ' anchor=' + JSON.stringify(String(activeMatch.anchor || '').slice(0, 80))
      + ' active=' + JSON.stringify(activeMatch.activePromptPreview.slice(0, 160))
      + ' styles=' + JSON.stringify(activeMatch.activePromptStyles)
      + ' rawMatched=' + rawMatch.matched
      + ' rawAfter=' + rawMatch.targetAfterSelected
      + ' rowAfter=' + targetAfterActiveByRows
      + ' rowBefore=' + targetBeforeActiveByRows
      + ' prompts=' + JSON.stringify(promptRows)
      + ' targetRows=' + JSON.stringify(targetRows));
    if (activeMatch.success) {
      if (activeMatch.activePromptRow == null && rawMatch.matched) {
        console.log('[Codex:Rewind:ActiveSnapshot] raw match ignored because snapshot has no active prompt row'
          + ' reason=' + reason
          + ' visible=' + JSON.stringify(String(rawMatch.visiblePreview || rawMatch.visibleText || '').slice(0, 160)));
      }
      let targetAfterActive = targetAfterActiveByRows;
      let targetBeforeActive = targetBeforeActiveByRows;
      if (!activeMatch.matched && rawMatch.matched) {
        const visible = normalizeCandidate(rawMatch.visibleText || rawMatch.visiblePreview || '');
        const active = normalizeCandidate(activeMatch.activePromptPreview || '');
        const activeWithoutMarker = stripLeadingCodexComposerPromptGlyph(active);
        const target = normalizeCandidate(expectedText);
        const targetAnchors = [
          target,
          ...buildCodexShortRewindAnchors(expectedText),
          ...buildCodexRewindAnchors(expectedText),
        ].map(normalizeCandidate).filter(Boolean);
        let activePos = active ? visible.indexOf(active) : -1;
        if (activePos < 0 && activeWithoutMarker) activePos = visible.indexOf(activeWithoutMarker);
        let targetPos = -1;
        for (const anchor of targetAnchors) {
          targetPos = visible.indexOf(anchor);
          if (targetPos >= 0) break;
        }
        const targetAfterActiveByText = activePos >= 0 && targetPos > activePos;
        const targetBeforeActiveByText = activePos >= 0 && targetPos >= 0 && targetPos < activePos;
        targetAfterActive = targetAfterActive || targetAfterActiveByText;
        targetBeforeActive = targetBeforeActive || targetBeforeActiveByText;
        console.log('[Codex:Rewind:VisibleTargetHint] reason=' + reason
          + ' activePos=' + activePos
          + ' targetPos=' + targetPos
          + ' targetAfterActive=' + targetAfterActiveByText
          + ' targetBeforeActive=' + targetBeforeActiveByText
          + ' rowAfter=' + targetAfterActiveByRows
          + ' rowBefore=' + targetBeforeActiveByRows
          + ' active=' + JSON.stringify(active.slice(0, 80))
          + ' target=' + JSON.stringify(target.slice(0, 80))
          + ' visible=' + JSON.stringify(visible.slice(0, 180)));
      }
      return {
        ...rawMatch,
        matched: activeMatch.matched,
        anchor: activeMatch.anchor,
        anchorCount: activeMatch.anchorCount,
        anchorMode: activeMatch.anchorMode,
        targetAfterSelected: targetAfterActive,
        targetBeforeSelected: targetBeforeActive,
        nextPromptAnchor: '',
        activePromptRow: activeMatch.activePromptRow,
        activePromptPreview: activeMatch.activePromptPreview,
        activePromptStyles: activeMatch.activePromptStyles,
        promptRows,
        rawMatched: rawMatch.matched,
        rawTargetAfterSelected: rawMatch.targetAfterSelected,
      };
    }
    return {
      ...rawMatch,
      activePromptRow: null,
      activePromptPreview: '',
      activePromptStyles: [],
      promptRows,
      targetBeforeSelected: false,
      snapshotError: activeMatch.error || 'snapshot-unavailable',
    };
  }

  function codexOverlayFrameHasNoSelectableText(match) {
    return Number(match?.visibleLength || 0) === 0
      && normalizeCandidate(match?.visiblePreview || '').length === 0;
  }

  function codexPrimeHintObserved(clean) {
    return /esc\s+again\s+to\s+edit\s+previous\s+message/i.test(String(clean || ''));
  }

  function codexTranscriptOverlayObserved(clean) {
    return /No previous message to edit|T R A N S C R I P T|enter to edit message/i.test(String(clean || ''));
  }

  function codexRewindProtocolChromeObserved(clean) {
    const compact = normalizeCandidate(clean).toLowerCase();
    if (!compact) return false;
    return codexPrimeHintObserved(clean)
      || codexTranscriptOverlayObserved(clean)
      || compact === 'q'
      || /^q\s+to\s+quit\b/i.test(compact)
      || /edit prev|edit next|esc\/←|enter to edit message/i.test(compact);
  }

  function getCodexSnapshotVisibleText(snapshot) {
    const lines = Array.isArray(snapshot?.lines) ? snapshot.lines : [];
    return lines.map(line => String(line?.text || '')).join('\n');
  }

  async function probeCodexRewindStartState(reason) {
    const snapshot = await requestTerminalVisibleBufferSnapshot(
      _event.sender,
      tabId,
      'codex-rewind-start-' + reason,
      700
    );
    const visibleText = snapshot?.success ? getCodexSnapshotVisibleText(snapshot) : '';
    const readyInspection = visibleText
      ? inspectCodexInputReadyVisibleText(visibleText, 'codex-rewind-start-' + reason)
      : null;
    const hasTranscript = codexTranscriptOverlayObserved(visibleText);
    const hasPrimeHint = codexPrimeHintObserved(visibleText);
    const hasProtocolChrome = codexRewindProtocolChromeObserved(visibleText);
    const mcpOwnsEscape = readyInspection?.ignoredBlockers?.includes('mcp-startup')
      || readyInspection?.blockers?.includes('mcp-startup');
    const state = !snapshot?.success
      ? 'snapshot-unavailable'
      : mcpOwnsEscape
        ? 'mcp-startup'
      : hasTranscript
        ? 'rewind-overlay'
        : (hasPrimeHint || hasProtocolChrome)
          ? 'rewind-protocol'
          : readyInspection?.ready === true
            ? 'clean-composer'
            : 'not-ready';
    return {
      state,
      snapshotSuccess: snapshot?.success === true,
      snapshotError: snapshot?.error || '',
      snapshotSource: snapshot?.source || '',
      ready: readyInspection?.ready === true,
      readyReason: readyInspection?.reason || '',
      blockers: Array.isArray(readyInspection?.blockers) ? readyInspection.blockers.slice() : [],
      hasTranscript,
      hasPrimeHint,
      hasProtocolChrome,
      preview: normalizeCandidate(visibleText).slice(0, 260),
    };
  }

  async function closeCodexRewindProtocolUi(reason) {
    console.log('[Codex:Rewind] closing stale protocol UI with q reason=' + reason);
    try { term.write('q'); } catch {}
    const raw = await drainPtyData(term, 120, 600);
    console.log('[Codex:Rewind] close protocol UI done reason=' + reason + ' rawBytes=' + String(raw || '').length);
  }

  async function ensureCodexRewindCleanStart(reason) {
    let startState = await probeCodexRewindStartState(reason);
    console.log('[Codex:Rewind] start-state reason=' + reason
      + ' state=' + startState.state
      + ' snapshot=' + startState.snapshotSuccess
      + ' source=' + (startState.snapshotSource || '-')
      + ' ready=' + startState.ready
      + ' readyReason=' + (startState.readyReason || '-')
      + ' blockers=' + (startState.blockers.length ? startState.blockers.join('+') : '-')
      + ' preview=' + JSON.stringify(startState.preview));
    if (startState.state === 'rewind-overlay' || startState.state === 'rewind-protocol') {
      await closeCodexRewindProtocolUi('preflight-' + reason);
      startState = await probeCodexRewindStartState(reason + '-after-close');
      console.log('[Codex:Rewind] start-state after close reason=' + reason
        + ' state=' + startState.state
        + ' snapshot=' + startState.snapshotSuccess
        + ' source=' + (startState.snapshotSource || '-')
        + ' ready=' + startState.ready
        + ' readyReason=' + (startState.readyReason || '-')
        + ' preview=' + JSON.stringify(startState.preview));
    }
    if (startState.state === 'snapshot-unavailable') {
      console.warn('[Codex:Rewind] start-state snapshot unavailable; falling back to first-Esc proof tab=' + String(tabId).slice(-12)
        + ' error=' + (startState.snapshotError || '-'));
      return { success: true, startState };
    }
    if (startState.state !== 'clean-composer') {
      return {
        success: false,
        error: 'codex_rewind_start_state_not_clean',
        startState: startState.state,
        readyReason: startState.readyReason,
        blockers: startState.blockers,
        preview: startState.preview,
        rollbackMayHaveApplied: false,
      };
    }
    return { success: true, startState };
  }

  function throwIfCodexRewindCancelled(stage) {
    if (rewindCancelTabs.has(tabId)) {
      console.log('[Codex:Rewind] Cancelled at stage=' + stage);
      throw makeRewindCancelledError(stage);
    }
  }

  async function grabRestoredCodexRewindInput(expectedText, targetPayload) {
    const expected = normalizeCandidate(expectedText);
      // The post-Enter owner waits on committed frames/readiness events before
      // issuing ONE Ctrl+G. It also retains a late helper result for this exact
      // operation; neither timeout nor a short/empty capture permits a retry.
      const result = await captureCodexRewindPostEnterInput(rewindPostEnterRecord, {
        cancelPromise: codexRewindCancelPromise,
        compare: text => compareCodexRestoredPrompt(expectedText, text, targetPayload),
      });
      const text = typeof result?.text === 'string' ? result.text : '';
      const normalized = normalizeCandidate(text);
      const comparison = expected
        ? compareCodexRestoredPrompt(expectedText, text, targetPayload)
        : { matched: normalized.length === 0, mode: normalized.length === 0 ? 'empty-expected' : 'mismatch', containsExpected: false, extraChars: normalized.length };
      const matched = comparison.matched === true;
      console.log('[Codex:Rewind] Grab restored input attempt=1'
        + ' success=' + (result?.success === true)
        + ' chars=' + text.length
        + ' matchedTarget=' + matched
        + ' mode=' + (comparison.mode || '-')
        + ' containsTarget=' + !!comparison.containsExpected
        + ' extraChars=' + (comparison.extraChars || 0)
        + ' images=' + (comparison.imageCount || 0)
        + ' resolvedImages=' + (comparison.resolvedImages || 0)
        + ' missingImages=' + (comparison.missingImages || 0)
        + ' error=' + (result?.error || '-'));

      if (result?.success && normalized.length > 0) {
        return {
          success: true,
          text,
          attempt: 1,
          matchedTarget: matched,
          matchMode: comparison.mode,
          historyDraftText: comparison.historyDraftText,
          historyDraftWarning: comparison.historyDraftWarning,
        };
      }
      if (result?.success) {
        return {
          success: true,
          text,
          attempt: 1,
          matchedTarget: matched,
          matchMode: comparison.mode,
          historyDraftText: comparison.historyDraftText,
          historyDraftWarning: comparison.historyDraftWarning,
          empty: true,
        };
      }
    return {
      ...result,
      success: false,
      error: result?.error || 'codex_rewind_input_grab_failed',
      text: typeof result?.text === 'string' ? result.text : '',
      matchedTarget: false,
    };
  }

  let codexRewindOverlayOpen = false;
  let handoffObservationArmed = false;
  let handoffObserver = null;
  let handoffMutationStarted = false;
  let handoffSettlementResult = null;
  let codexRewindOperationResult = null;
  let rewindCommitExpectation = null;
  let durableCommittedChildProof = null;
  let rewindPostEnterRecord = null;
  const settleAppliedCodexRewindWriter = async (stage) => {
    if (!handoffObservationArmed || !handoffMutationStarted) {
      return {
        success: false,
        error: 'codex_rewind_writer_handoff_not_armed',
        rollbackMayHaveApplied: handoffMutationStarted,
      };
    }
    if (!handoffSettlementResult?.bindingCommitted) {
      handoffSettlementResult = await settleCodexWriterHandoffObservation(
        tabId,
        stage,
        { waitForBranchMs: 8000 },
      );
    }
    if (handoffSettlementResult?.bindingCommitted !== true
      || !['adopted-child', 'stable-source', 'branch-draft-restored'].includes(handoffSettlementResult?.handoffStatus)
      || !handoffSettlementResult?.activeSessionId) {
      return {
        success: false,
        error: handoffSettlementResult?.error || 'codex_rewind_writer_handoff_unresolved',
        writerStatus: handoffSettlementResult?.status || 'unknown',
        handoffStatus: handoffSettlementResult?.handoffStatus || 'unresolved',
        sourceSessionId: handoffSettlementResult?.sourceSessionId || writer?.sessionId || null,
        activeSessionId: null,
        bindingCommitted: false,
        handoffGeneration: handoffSettlementResult?.handoffGeneration || null,
        rollbackMayHaveApplied: true,
      };
    }
    return {
      success: true,
      sourceSessionId: handoffSettlementResult.sourceSessionId,
      activeSessionId: handoffSettlementResult.activeSessionId,
      bindingCommitted: true,
      handoffStatus: handoffSettlementResult.handoffStatus,
      handoffGeneration: handoffSettlementResult.handoffGeneration || null,
    };
  };
  const inspectCommittedCodexRewindChild = (actionGeneration) => {
    const receiptProof = rewindCommitExpectation
      ? inspectCodexNativeRewindCommitReceipt(tabId, rewindCommitExpectation)
      : { available: false, committed: false };
    if (receiptProof.committed) {
      durableCommittedChildProof = receiptProof;
      return receiptProof;
    }
    if (receiptProof.available) {
      return {
        committed: false,
        sourceSessionId: null,
        childSessionId: null,
        error: receiptProof.error || 'codex_rewind_commit_receipt_unproven',
      };
    }
    const intent = codexSessionDiscoveryIntents.get(tabId) || null;
    const boundSessionId = codexSessionIdFromDb(tabId);
    const committed = isCommittedCodexNativeRewindReplay({
      intent,
      candidateSessionId: boundSessionId,
      proof: getCodexWriterProofSnapshot(tabId),
      boundSessionId,
      terminalToken: terminals.get(tabId) || null,
      runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
      currentIntentGeneration: intent?.launchId || null,
      observerCurrent: !!handoffObserver
        && codexWatchers.get(tabId) === handoffObserver
        && handoffObserver.launchId === actionGeneration,
    });
    return {
      committed,
      sourceSessionId: committed ? intent?.sourceSessionId || null : null,
      childSessionId: committed ? boundSessionId || null : null,
    };
  };
  // PTY serialization alone is insufficient for destructive intents: a
  // second click queued behind the first would otherwise execute later with
  // the writer/target proof captured before the first rollback. Reject it
  // instead of turning two concurrent clicks into two sequential rollbacks.
  const rewindRequestId = 'codex-rewind-' + Date.now() + '-' + (++codexRewindReservationSeq);
  const rewindReservationClaim = claimExclusiveActionReservation(codexRewindReservations, {
    key: tabId,
    requestId: rewindRequestId,
    action: 'codex-rewind',
  });
  if (!rewindReservationClaim.success) {
    console.warn('[Codex:Rewind] reservation lost tab=' + String(tabId).slice(-12)
      + ' request=' + rewindRequestId
      + ' active=' + (rewindReservationClaim.active?.requestId || '-'));
    return { success: false, error: 'codex_rewind_already_in_progress' };
  }
  const rewindReservation = rewindReservationClaim.reservation;
  const activeRewindClaim = beginActiveRewindOperation(tabId, 'codex', opId);
  if (!activeRewindClaim.success) {
    releaseExclusiveActionReservation(codexRewindReservations, rewindReservation);
    return activeRewindClaim;
  }
  const activeRewindOperation = activeRewindClaim.operation;
  let resolveCodexRewindCancel;
  const codexRewindCancelPromise = new Promise((resolve) => {
    resolveCodexRewindCancel = resolve;
  });
  const codexRewindPtyOperation = {
    kind: 'codex-native-rewind',
    source: 'codex-native-rewind',
    tabId,
    submitted: false,
    identityPending: false,
    manualInputYields: false,
    cancelRequested: false,
    cancelPromise: codexRewindCancelPromise,
    resolveCancel: resolveCodexRewindCancel,
    queuedAt: Date.now(),
  };
  activeRewindOperation.ptyWriteOperation = codexRewindPtyOperation;

  try {
    codexRewindOperationResult = await withPtyWriteLock(term, async () => {
      throwIfCodexRewindCancelled('locked-before-authorization');
      const count = Number(rewindableCount);
      const idx = Number(targetIndex);
      if (!Number.isFinite(count) || !Number.isFinite(idx) || count <= 0 || idx < 0 || idx >= count) {
        return { success: false, error: 'invalid_target_index', targetIndex, rewindableCount };
      }

      const targetInputText = String(targetFullText || targetText || '').trim();
      if (!targetInputText) return { success: false, error: 'empty_target' };
      const hasPasteAfter = typeof pasteAfter === 'string' && pasteAfter.length > 0;
      const actionMirror = getHeadlessTerminalMirror(tabId);
      const actionScope = {
        lifecycle: getTerminalLifecycleGeneration(tabId),
        runSeq: Number(terminalCommandState.get(tabId)?.runSeq || 0),
        inputRevision: getTerminalInputRevision(tabId),
        launchId: codexLastRunCommandPayload.get(tabId)?.launchId,
      };
      const actionReady = await waitForCodexRewindActionReady({
        readSnapshot: () => {
          const snapshot = actionMirror?.lastCommittedVisibleSnapshot;
          return actionMirror?.failed !== true
            && snapshot?.writeSeq === actionMirror?.writeSeq ? snapshot : null;
        },
        inspectReady: snapshot => inspectCodexInputReadyVisibleText('', 'rewind-escape-boundary', {
          lines: snapshot.lines, activePromptRow: snapshot.codexActivePrompt?.row,
        }),
        isCurrent: () => terminals.get(tabId) === term
          && getHeadlessTerminalMirror(tabId) === actionMirror
          && getTerminalLifecycleGeneration(tabId) === actionScope.lifecycle
          && Number(terminalCommandState.get(tabId)?.runSeq || 0) === actionScope.runSeq
          && getTerminalInputRevision(tabId) === actionScope.inputRevision
          && codexLastRunCommandPayload.get(tabId)?.launchId === actionScope.launchId
          && aiStoppingTabs.get(tabId)?.toolType !== 'codex',
        subscribe: listener => {
          actionMirror?.synchronizedFrameWaiters?.add(listener);
          return () => actionMirror?.synchronizedFrameWaiters?.delete(listener);
        },
        cancelPromise: codexRewindCancelPromise,
      });
      if (!actionReady.success) return actionReady;
      // Ready for text != ready for Escape. Re-authorize the exact source
      // after startup settles, before arming its handoff or writing a key.
      // This is the mutation boundary. The request may have waited behind a
      // paste/model action, so renderer preflight is stale by definition here.
      // Re-prove process, writer/provisional launch, readiness and idle state
      // while holding the same lock that guards the first Escape.
      const targetAuthorization = await authorizeCodexRewindAtWriteBoundary('locked-before-target-load');
      throwIfCodexRewindCancelled('after-target-authorization');
      if (!targetAuthorization.success) return targetAuthorization;
      writer = targetAuthorization.writer;
      provisionalResumeRewind = targetAuthorization.provisionalResumeRewind;
      let compositeTarget = null;
      const targetIdentity = classifyCodexRewindEntryIdentity({
        viewOwnerSessionId,
        writerSessionId: writer.sessionId,
        expectedContentRevision,
        targetEntryRef,
      });
      if (!targetIdentity.valid) {
        return {
          success: false,
          error: 'ambiguous_entry_identity',
          identityReason: targetIdentity.reason,
        };
      }
      if (targetIdentity.mode === 'composite') {
        compositeTarget = await transcriptService.resolveCodexPhysicalRow({
          sessionId: viewOwnerSessionId,
          cwd: terminalProjects.get(tabId),
          expectedContentRevision,
          entryRef: targetEntryRef,
        });
        if (compositeTarget?.success !== true) return compositeTarget;
        if (compositeTarget.logicalUserIndex !== idx
          || compositeTarget.rewindableCount !== count
          || compositeTarget.entry?.type !== 'user') {
          return { success: false, error: 'stale_transcript_revision' };
        }
      }
      const targetPayloadContext = await loadCodexRewindTargetPayload(compositeTarget);
      const targetPayload = targetPayloadContext?.payload || null;
      if (!targetPayloadContext
        || !Number.isInteger(targetPayloadContext.sourceLine)
        || targetPayloadContext.sourceLine < 1) {
        return {
          success: false,
          error: 'codex_rewind_target_not_in_current_writer',
          writerSessionId: writer.sessionId,
          targetUuid,
        };
      }
      const writeAuthorization = await authorizeCodexRewindAtWriteBoundary('locked-before-first-write');
      if (!writeAuthorization.success) return writeAuthorization;
      if (compositeTarget) {
        const currentTarget = await transcriptService.resolveCodexPhysicalRow({
          sessionId: viewOwnerSessionId,
          cwd: terminalProjects.get(tabId),
          expectedContentRevision,
          entryRef: targetEntryRef,
        });
        if (currentTarget?.success !== true
          || currentTarget.logicalUserIndex !== compositeTarget.logicalUserIndex
          || currentTarget.entry?.uuid !== compositeTarget.entry?.uuid) {
          return currentTarget?.success === false
            ? currentTarget
            : { success: false, error: 'stale_transcript_revision' };
        }
      }
      if (writeAuthorization.writer?.sessionId !== writer?.sessionId
        || writeAuthorization.provisionalResumeRewind !== provisionalResumeRewind
        || writeAuthorization.launchId !== targetAuthorization.launchId
        || writeAuthorization.sourceContext?.terminalToken !== targetAuthorization.sourceContext?.terminalToken
        || writeAuthorization.sourceContext?.lifecycleGeneration !== targetAuthorization.sourceContext?.lifecycleGeneration
        || Number(writeAuthorization.sourceContext?.runSeq) !== Number(targetAuthorization.sourceContext?.runSeq)
        || writeAuthorization.sourceContext?.expectedPersistedSessionId
          !== targetAuthorization.sourceContext?.expectedPersistedSessionId) {
        return {
          success: false,
          error: 'codex_writer_changed_before_rewind',
          writerSessionId: writeAuthorization.writer?.sessionId || null,
        };
      }
      writer = writeAuthorization.writer;
      provisionalResumeRewind = writeAuthorization.provisionalResumeRewind;
      const authoritativeTargetText = String(
        targetPayload?.message
        || codexDataModule._api.extractTextContent(targetPayload?.content)
        || '',
      ).trim();
      const actionTarget = {
        targetUuid,
        targetPhysicalSessionId: targetPayloadContext.sessionId,
        targetSourceLine: targetPayloadContext.sourceLine,
        targetTextHash: hashCodexRewindTargetText(authoritativeTargetText),
      };
      const createdAuthority = createMainCodexActionAuthority({
        profile: CODEX_ACTION_PROFILE_NATIVE_REWIND,
        tabId,
        launchId: writeAuthorization.launchId,
        sourceSessionId: writer.sessionId,
        operationId: String(opId || rewindRequestId),
        requestId: rewindRequestId,
        target: actionTarget,
      });
      if (!createdAuthority.success) {
        return {
          success: false,
          error: 'codex_rewind_action_authority_unavailable',
          authorityError: createdAuthority.error,
        };
      }
      rewindActionAuthority = createdAuthority.authority;
      rewindReservation.actionAuthority = rewindActionAuthority;
      transitionMainCodexActionAuthority(rewindActionAuthority, 'waiting', 'awaiting-exact-rewind-arm');
      const holdResult = await waitForCodexActionAuthorityTestRelease(rewindActionAuthority);
      if (holdResult?.released !== true) {
        return {
          success: false,
          error: 'codex_rewind_action_authority_revoked',
          authorityReason: rewindActionAuthority.reason || holdResult?.reason || 'scope-changed',
        };
      }
      if (holdResult.held === true) {
        const heldAuthorization = await authorizeCodexRewindAtWriteBoundary('held-before-rewind-arm');
        if (!heldAuthorization.success) return heldAuthorization;
        if (heldAuthorization.writer?.sessionId !== writer.sessionId
          || heldAuthorization.launchId !== writeAuthorization.launchId
          || heldAuthorization.sourceContext?.terminalToken !== writeAuthorization.sourceContext?.terminalToken
          || heldAuthorization.sourceContext?.lifecycleGeneration
            !== writeAuthorization.sourceContext?.lifecycleGeneration
          || Number(heldAuthorization.sourceContext?.runSeq)
            !== Number(writeAuthorization.sourceContext?.runSeq)) {
          return { success: false, error: 'codex_writer_changed_while_rewind_waited' };
        }
      }
      const authorityBeforeArm = validateMainCodexActionAuthority(rewindActionAuthority, {
        phases: ['waiting'],
        profile: CODEX_ACTION_PROFILE_NATIVE_REWIND,
        launchId: writeAuthorization.launchId,
        sourceSessionId: writer.sessionId,
        target: actionTarget,
      });
      if (!authorityBeforeArm.valid) {
        transitionMainCodexActionAuthority(
          rewindActionAuthority,
          'revoked',
          authorityBeforeArm.reason,
        );
        return {
          success: false,
          error: 'codex_rewind_action_authority_revoked',
          authorityReason: authorityBeforeArm.reason,
        };
      }
      handoffObservationArmed = armCodexWriterHandoffObservation(
        tabId,
        'programmatic-rewind',
        {
          blockMutations: true,
          sourceContext: writeAuthorization.sourceContext,
          actionAuthority: rewindActionAuthority,
        },
      );
      handoffObserver = codexWatchers.get(tabId) || null;
      if (!handoffObservationArmed || handoffObserver?.sourceMode !== 'writer-handoff') {
        return { success: false, error: 'codex_rewind_writer_handoff_not_armed' };
      }

      async function pasteCodexRewindAiCompact(reason) {
        console.log('[Codex:Rewind] Pasting AI compact text (' + pasteAfter.length + ' chars, reason=' + reason + ', preview=' + JSON.stringify(String(pasteAfter).slice(0, 120)) + ')');
        const pasteResult = await _safePasteAndSubmitInner(term, pasteAfter, {
          submit: true,
          ctrlCFirst: false,
          stashFirst: false,
          // Codex is a crossterm TUI with explicit bracketed-paste events.
          // Use the TUI-safe path: one complete bracketed paste, wait for the
          // synchronized render marker, then Enter. Fast multi-write paste can
          // make crossterm/Codex record only the tail of Cyrillic markdown.
          fast: false,
          submitSequence: '\r',
          submitLabel: 'Enter',
          source: 'codex-rewind-ai',
          // Native Rewind has already adopted and durably bound its child
          // writer before this follow-up submit.
          codexSubmissionPreflight: false,
          awaitCodexUserMessageAudit: true,
          codexAuditTimeoutMs: CODEX_PASTE_AUDIT_TIMEOUT_MS,
          logPrefix: '[Codex:Rewind:paste]',
        });
        if (!pasteResult || pasteResult.success === false) {
          return {
            success: false,
            error: pasteResult?.error || 'paste_after_failed',
            rollbackMayHaveApplied: true,
          };
        }
        return { success: true };
      }

      const olderSteps = Math.max(0, count - 1 - idx);
      let rollbackTurns = count - idx;
      let escPressCount = 2 + olderSteps;
      console.log('[Codex:Rewind] Starting native backtrack tab=' + String(tabId).slice(-12)
        + ' targetIndex=' + idx
        + ' count=' + count
        + ' olderSteps=' + olderSteps
        + ' rollbackTurns=' + rollbackTurns
        + ' target=' + JSON.stringify(String(targetText || targetInputText).slice(0, 80)));

      const authorityAtFirstWrite = validateMainCodexActionAuthority(rewindActionAuthority, {
        phases: ['armed'],
        profile: CODEX_ACTION_PROFILE_NATIVE_REWIND,
        launchId: writeAuthorization.launchId,
        sourceSessionId: writer.sessionId,
        actionGeneration: handoffObserver.launchId,
        target: actionTarget,
      });
      if (!authorityAtFirstWrite.valid) {
        transitionMainCodexActionAuthority(
          rewindActionAuthority,
          'revoked',
          authorityAtFirstWrite.reason,
        );
        return {
          success: false,
          error: 'codex_rewind_action_authority_revoked',
          authorityReason: authorityAtFirstWrite.reason,
        };
      }
      const consumedAuthority = transitionMainCodexActionAuthority(
        rewindActionAuthority,
        'consumed',
        'first-rewind-control-write',
      );
      if (!consumedAuthority.success) {
        return { success: false, error: 'codex_rewind_action_authority_not_consumed' };
      }

      const initialStartState = await ensureCodexRewindCleanStart('before-prime');
      if (!initialStartState.success) return initialStartState;

      async function openCodexRewindOverlayFromComposer(attemptLabel) {
        throwIfCodexRewindCancelled('before-prime-' + attemptLabel);
        const primeFrame = await sendCodexKeyAndCapture(
          term,
          '\x1b',
          2200,
          '[Codex:Rewind:prime:' + attemptLabel + ']',
          (clean) => codexPrimeHintObserved(clean)
            || codexTranscriptOverlayObserved(clean)
            || codexRewindProtocolChromeObserved(clean)
        );
        throwIfCodexRewindCancelled('after-prime-' + attemptLabel);
        const hasPrimeHint = !primeFrame.timedOut && codexPrimeHintObserved(primeFrame.clean);
        const openedDirectly = !primeFrame.timedOut && codexTranscriptOverlayObserved(primeFrame.clean);
        const protocolChrome = codexRewindProtocolChromeObserved(primeFrame.clean);
        console.log('[Codex:Rewind] prime ' + attemptLabel
          + ' timedOut=' + primeFrame.timedOut
          + ' hint=' + hasPrimeHint
          + ' directOpen=' + openedDirectly
          + ' protocolChrome=' + protocolChrome
          + ' clean=' + JSON.stringify(primeFrame.clean.slice(0, 220)));

        if (/No previous message to edit/i.test(primeFrame.clean)) {
          return { success: false, error: 'no_previous_message', rollbackMayHaveApplied: false };
        }
        if (openedDirectly) {
          return { success: true, openFrame: primeFrame, directOpen: true };
        }
        if (!hasPrimeHint) {
          console.warn('[Codex:Rewind] prime hint missing without clearing Codex readiness tab=' + String(tabId).slice(-12)
            + ' attempt=' + attemptLabel
            + ' timedOut=' + primeFrame.timedOut
            + ' protocolChrome=' + protocolChrome
            + ' rawBytes=' + String(primeFrame.raw || '').length);
          return {
            success: false,
            error: 'codex_rewind_prime_hint_not_observed',
            clean: primeFrame.clean.slice(0, 800),
            protocolChrome,
            rollbackMayHaveApplied: false,
          };
        }

        throwIfCodexRewindCancelled('before-open-' + attemptLabel);
        const openFrame = await sendCodexKeyAndCapture(
          term,
          '\x1b',
          4000,
          '[Codex:Rewind:open:' + attemptLabel + ']',
          (clean) => codexTranscriptOverlayObserved(clean)
        );
        throwIfCodexRewindCancelled('after-open-' + attemptLabel);
        console.log('[Codex:Rewind] open Esc ' + attemptLabel + ' timedOut=' + openFrame.timedOut + ' clean=' + JSON.stringify(openFrame.clean.slice(0, 260)));
        if (/No previous message to edit/i.test(openFrame.clean)) {
          return { success: false, error: 'no_previous_message', rollbackMayHaveApplied: false };
        }
        if (openFrame.timedOut || !codexTranscriptOverlayObserved(openFrame.clean || '')) {
          if (codexRewindProtocolChromeObserved(openFrame.clean)) {
            await closeCodexRewindProtocolUi('transcript-not-observed-' + attemptLabel);
          }
          return {
            success: false,
            error: 'codex_rewind_transcript_not_observed',
            clean: openFrame.clean.slice(0, 800),
            rollbackMayHaveApplied: false,
          };
        }
        return { success: true, openFrame };
      }

      let openAttempt = await openCodexRewindOverlayFromComposer('initial');
      if (!openAttempt.success
        && openAttempt.error === 'codex_rewind_prime_hint_not_observed'
        && openAttempt.protocolChrome === true) {
        await closeCodexRewindProtocolUi('prime-missing-initial');
        const retryStartState = await ensureCodexRewindCleanStart('before-prime-retry');
        if (!retryStartState.success) {
          return {
            ...retryStartState,
            success: false,
            error: 'codex_rewind_start_state_unstable',
            cause: retryStartState.error,
            rollbackMayHaveApplied: false,
          };
        }
        openAttempt = await openCodexRewindOverlayFromComposer('retry');
      }
      if (!openAttempt.success) return openAttempt;

      const openFrame = openAttempt.openFrame;
      codexRewindOverlayOpen = true;
      activeRewindOperation.protocolUiOpen = true;

      let selectedOlderSteps = null;
      let selectedMatch = await matchCodexRewindSelection(openFrame, targetInputText, 'open');
      let duplicatesRemaining = Math.max(0, Number(skipDuplicates || 0));
      const maxOlderSteps = Math.min(60, Math.max(count + 8, olderSteps + 12, duplicatesRemaining + 8));
      function ignorePrematureRawOnlyCodexRewindMatch(match, step, label) {
        if (!match?.matched || !match?.rawMatched || match?.activePromptRow != null || step >= olderSteps) {
          return match;
        }
        console.warn('[Codex:Rewind] ignoring raw-only match before planned step'
          + ' label=' + label
          + ' step=' + step
          + ' plannedOlderSteps=' + olderSteps
          + ' snapshotError=' + (match.snapshotError || '-')
          + ' anchor=' + JSON.stringify(String(match.anchor || '').slice(0, 80)));
        return {
          ...match,
          matched: false,
          ignoredRawOnlyBeforePlanned: true,
        };
      }
      selectedMatch = ignorePrematureRawOnlyCodexRewindMatch(selectedMatch, 0, 'open');
      console.log('[Codex:Rewind] overlay match step=0/' + maxOlderSteps
        + ' matched=' + selectedMatch.matched
        + ' targetAfterSelected=' + selectedMatch.targetAfterSelected
        + ' duplicatesRemaining=' + duplicatesRemaining
        + ' anchors=' + selectedMatch.anchorCount
        + ' mode=' + selectedMatch.anchorMode
        + ' anchor=' + JSON.stringify(selectedMatch.anchor.slice(0, 80))
        + ' nextPromptAnchor=' + JSON.stringify(String(selectedMatch.nextPromptAnchor || '').slice(0, 80))
        + ' visible=' + JSON.stringify(selectedMatch.visiblePreview.slice(0, 160))
        + ' target=' + JSON.stringify(selectedMatch.targetPreview.slice(0, 160)));
      if (selectedMatch.matched) {
        if (duplicatesRemaining > 0) {
          duplicatesRemaining--;
          console.log('[Codex:Rewind] overlay target duplicate at step=0 skipped, remaining=' + duplicatesRemaining);
        } else {
          selectedOlderSteps = 0;
        }
      } else if (selectedMatch.targetAfterSelected) {
        console.warn('[Codex:Rewind] target appears as next prompt at step=0; refusing to commit without selectable target');
      } else if (olderSteps === 0 && codexOverlayFrameHasNoSelectableText(selectedMatch)) {
        selectedOlderSteps = 0;
        console.log('[Codex:Rewind] overlay initial frame has no selectable text; using latest prompt position and verifying restored composer after Enter');
      }

      if (selectedOlderSteps === null && maxOlderSteps > 0) {
        console.log('[Codex:Rewind] Navigating older with Left Arrow search max=' + maxOlderSteps + ' planned=' + olderSteps);
        for (let step = 1; step <= maxOlderSteps; step++) {
          throwIfCodexRewindCancelled('nav-left#' + step);
          const navFrame = await sendCodexKeyAndCapture(
            term,
            '\x1b[D',
            2600,
            '[Codex:Rewind:nav:left#' + step,
            (clean, raw) => raw.includes(CODEX_SYNC_MARKER)
              || /enter to edit message|edit prev|edit next|Context\s+\d+%/i.test(clean)
          );
          selectedMatch = await matchCodexRewindSelection(navFrame, targetInputText, 'left#' + step);
          selectedMatch = ignorePrematureRawOnlyCodexRewindMatch(selectedMatch, step, 'left#' + step);
          console.log('[Codex:Rewind] nav left step=' + step + '/' + maxOlderSteps
            + ' planned=' + olderSteps
            + ' timedOut=' + navFrame.timedOut
            + ' raw=' + navFrame.raw.length + 'B'
            + ' matched=' + selectedMatch.matched
            + ' targetAfterSelected=' + selectedMatch.targetAfterSelected
            + ' duplicatesRemaining=' + duplicatesRemaining
            + ' anchors=' + selectedMatch.anchorCount
            + ' mode=' + selectedMatch.anchorMode
            + ' anchor=' + JSON.stringify(selectedMatch.anchor.slice(0, 80))
            + ' nextPromptAnchor=' + JSON.stringify(String(selectedMatch.nextPromptAnchor || '').slice(0, 80))
            + ' visible=' + JSON.stringify(selectedMatch.visiblePreview.slice(0, 160)));
          if (navFrame.timedOut) {
            try { term.write('q'); } catch {}
            return {
              success: false,
              error: 'codex_rewind_navigation_timeout',
              rollbackTurns,
              pressCount: 2 + step,
              clean: navFrame.clean.slice(0, 800),
              rollbackMayHaveApplied: false,
            };
          }
          if (selectedMatch.matched) {
            if (duplicatesRemaining > 0) {
              duplicatesRemaining--;
              console.log('[Codex:Rewind] overlay target duplicate at step=' + step + ' skipped, remaining=' + duplicatesRemaining);
            } else {
              selectedOlderSteps = step;
              break;
            }
          } else if (selectedMatch.targetAfterSelected) {
            if (duplicatesRemaining > 0) {
              duplicatesRemaining--;
              console.log('[Codex:Rewind] overlay next-prompt target duplicate at step=' + step + ' skipped, remaining=' + duplicatesRemaining);
            } else if (step > 0) {
              const correctedOlderSteps = step - 1;
              console.log('[Codex:Rewind] target is next prompt after selected row; moving Right once to commit target correctedOlderSteps=' + correctedOlderSteps + ' fromStep=' + step);
              throwIfCodexRewindCancelled('before-correct-right#' + step);
              const rightFrame = await sendCodexKeyAndCapture(
                term,
                '\x1b[C',
                2600,
                '[Codex:Rewind:nav:right#1',
                (clean, raw) => raw.includes(CODEX_SYNC_MARKER)
                  || /enter to edit message|edit prev|edit next|Context\s+\d+%/i.test(clean)
              );
              throwIfCodexRewindCancelled('after-correct-right#' + step);
              if (rightFrame.timedOut) {
                try { term.write('q'); } catch {}
                return {
                  success: false,
                  error: 'codex_rewind_navigation_timeout',
                  rollbackTurns,
                  pressCount: 2 + step + 1,
                  clean: rightFrame.clean.slice(0, 800),
                  rollbackMayHaveApplied: false,
                };
              }
              const correctedMatch = await matchCodexRewindSelection(rightFrame, targetInputText, 'right#1');
              console.log('[Codex:Rewind] nav right correction done correctedOlderSteps=' + correctedOlderSteps
                + ' matched=' + correctedMatch.matched
                + ' targetAfterSelected=' + correctedMatch.targetAfterSelected
                + ' anchors=' + correctedMatch.anchorCount
                + ' mode=' + correctedMatch.anchorMode
                + ' anchor=' + JSON.stringify(correctedMatch.anchor.slice(0, 80))
                + ' nextPromptAnchor=' + JSON.stringify(String(correctedMatch.nextPromptAnchor || '').slice(0, 80))
                + ' visible=' + JSON.stringify(correctedMatch.visiblePreview.slice(0, 160)));
              if (!correctedMatch.matched) {
                try {
                  term.write('q');
                  await drainPtyData(term, 120, 500);
                } catch {}
                return {
                  success: false,
                  error: 'codex_rewind_target_not_selected_before_enter',
                  rollbackTurns,
                  pressCount: 2 + step + 1,
                  rollbackMayHaveApplied: false,
                  anchorCount: correctedMatch.anchorCount,
                  visiblePreview: correctedMatch.visiblePreview,
                  targetPreview: correctedMatch.targetPreview,
                  correctionFailed: true,
                };
              }
              selectedOlderSteps = correctedOlderSteps;
              selectedMatch = correctedMatch;
              break;
            }
          }
          await drainPtyData(term, 20, 120);
        }
      }

      if (selectedOlderSteps === null) {
        console.warn('[Codex:Rewind] target not selected before Enter plannedOlderSteps=' + olderSteps
          + ' searchedOlderSteps=' + maxOlderSteps
          + ' anchors=' + selectedMatch.anchorCount
          + ' visiblePreview=' + JSON.stringify(selectedMatch.visiblePreview)
          + ' targetPreview=' + JSON.stringify(selectedMatch.targetPreview));
        try {
          term.write('q');
          await drainPtyData(term, 120, 500);
        } catch {}
        return {
          success: false,
          error: 'codex_rewind_target_not_selected_before_enter',
          rollbackTurns,
          pressCount: 2 + maxOlderSteps,
          rollbackMayHaveApplied: false,
          anchorCount: selectedMatch.anchorCount,
          visiblePreview: selectedMatch.visiblePreview,
          targetPreview: selectedMatch.targetPreview,
        };
      }

      rollbackTurns = selectedOlderSteps + 1;
      escPressCount = 2 + selectedOlderSteps;
      console.log('[Codex:Rewind] selected target before Enter olderSteps=' + selectedOlderSteps
        + ' plannedOlderSteps=' + olderSteps
        + ' rollbackTurns=' + rollbackTurns
        + ' anchor=' + JSON.stringify(selectedMatch.anchor.slice(0, 120)));

      console.log('[Codex:Rewind] Confirming backtrack with Enter');
      throwIfCodexRewindCancelled('before-confirm');
      const rewindSourceSnapshot = await transcriptService.captureCodexRewindSourceSnapshot({
        viewSessionId: handoffObserver.sourceSessionId,
        physicalSessionId: targetPayloadContext.sessionId,
        targetSourceLine: targetPayloadContext.sourceLine,
        cwd: terminalProjects.get(tabId),
      }).catch((error) => {
        console.warn('[CodexForkLineage] pre-Enter Rewind snapshot failed tab='
          + String(tabId).slice(-12)
          + ' source=' + String(handoffObserver?.sourceSessionId || '').slice(0, 8)
          + ' targetPhysical=' + String(targetPayloadContext?.sessionId || '').slice(0, 8)
          + ' targetLine=' + (targetPayloadContext?.sourceLine ?? '-')
          + ' error=' + (error?.message || String(error)));
        return null;
      });
      throwIfCodexRewindCancelled('after-source-snapshot');
      if (!rewindSourceSnapshot?.snapshotComplete) {
        try {
          term.write('q');
          await drainPtyData(term, 120, 500);
        } catch {}
        return {
          success: false,
          error: 'codex_rewind_source_snapshot_unavailable',
          rollbackMayHaveApplied: false,
        };
      }
      const handoffActionStartedAtMs = Date.now();
      const handoffActionGeneration = codexWatchers.get(tabId)?.launchId || null;
      const authoritativeTargetTextHash = actionTarget.targetTextHash;
      if (!markCodexWriterHandoffActionBoundary(tabId, handoffActionStartedAtMs, {
        operationId: String(opId || rewindRequestId),
        requestId: rewindRequestId,
        targetUuid,
        targetPhysicalSessionId: targetPayloadContext.sessionId,
        targetSourceLine: targetPayloadContext?.sourceLine,
        targetTextHash: authoritativeTargetTextHash,
        rollbackTurns,
        rewindSourceSnapshot,
        actionAuthority: rewindActionAuthority,
      })) {
        return {
          success: false,
          error: 'codex_rewind_writer_handoff_boundary_failed',
          rollbackMayHaveApplied: false,
        };
      }
      rewindCommitExpectation = {
        projectId: resolveAuthoritativeTabProjectId(tabId),
        tabId,
        operationId: String(opId || rewindRequestId),
        requestId: rewindRequestId,
        actionGeneration: handoffActionGeneration,
        sourceSessionId: handoffObserver?.sourceSessionId || writer?.sessionId || null,
        sourceLifecycleGeneration: handoffObserver?.sourceLifecycleGeneration || null,
        sourceRunSeq: Number(handoffObserver?.sourceRunSeq || 0),
        terminalToken: term,
        targetUuid,
        targetSourceLine: targetPayloadContext?.sourceLine,
        targetTextHash: authoritativeTargetTextHash,
        rollbackTurns,
      };
      rewindPostEnterRecord = createCodexRewindPostEnterOperation(tabId, {
        authority: rewindActionAuthority, expectation: rewindCommitExpectation,
        expectedText: targetInputText, targetPayload,
      });
      handoffMutationStarted = true;
      markActiveRewindMutationStarted(activeRewindOperation, _event.sender);
      const targetNeedle = normalizeCandidate(targetInputText).slice(0, 40);
      const confirmFrame = await sendCodexKeyAndCapture(
        term,
        '\r',
        3200,
        '[Codex:Rewind:confirm]',
        (clean) => !!findCodexRollbackFailureLine(clean)
          || (targetNeedle.length > 0 && normalizeCandidate(clean).includes(targetNeedle)),
        { onWritten: () => persistCodexRewindPostEnter(rewindPostEnterRecord, {
          phase: 'entered', enterWrittenAt: Date.now(),
        }) },
      );
      const confirmClean = confirmFrame.clean || '';
      console.log('[Codex:Rewind] confirm timedOut=' + confirmFrame.timedOut + ' clean=' + JSON.stringify(confirmClean.slice(0, 320)));
      codexRewindOverlayOpen = false;
      activeRewindOperation.protocolUiOpen = false;
      const rollbackFailure = await inspectCodexRollbackFailureAfterConfirm(confirmClean);
      console.log('[Codex:Rewind] rollback rejection proof rejected=' + rollbackFailure.rejected
        + ' source=' + rollbackFailure.proofSource
        + ' line=' + JSON.stringify(rollbackFailure.failureLine)
        + ' snapshotError=' + (rollbackFailure.snapshotError || '-'));
      const confirmStartupBlockers = inspectCodexStartupBlockersText(confirmClean);
      const confirmExposedStartupFrame = confirmStartupBlockers.length > 0;
      const surfaceConfirmStartupFrameIfUnrecovered = (reason = 'codex-rewind-confirm-startup-frame-unrecovered') => {
        if (!confirmExposedStartupFrame) return false;
        const hadReady = codexTuiReadyTabs.delete(tabId);
        clearCodexServiceTierProof(tabId, reason);
        codexTuiReadyMeta.delete(tabId);
        codexTuiReadyBuffers.set(tabId, String(confirmFrame.raw || '').slice(-CODEX_STARTUP_AUTO_ENTER_BUFFER_LIMIT));
        console.warn('[Codex:Rewind] confirm startup frame unrecovered; cleared input-ready tab=' + String(tabId).slice(-12)
          + ' hadReady=' + hadReady
          + ' blockers=' + confirmStartupBlockers.join('+')
          + ' preview=' + JSON.stringify(confirmClean.replace(/\s+/g, ' ').trim().slice(0, 220)));
        _webBroadcast(tabId, {
          type: 'snapshot',
          sessionId: getCodexRuntimeSessionId(tabId),
          busy: false,
          sessionStatus: 'starting',
          toolType: 'codex',
          commandType: 'codex',
          inputReady: false,
          reason,
        });
        return true;
      };
      if (confirmExposedStartupFrame) {
        console.warn('[Codex:Rewind] confirm exposed startup-like frame; deferring input-ready clear until grab outcome tab=' + String(tabId).slice(-12)
          + ' blockers=' + confirmStartupBlockers.join('+')
          + ' preview=' + JSON.stringify(confirmClean.replace(/\s+/g, ' ').trim().slice(0, 220)));
      }
      if (rollbackFailure.rejected) {
        surfaceConfirmStartupFrameIfUnrecovered('codex-rewind-confirm-thread-rollback-failed-startup-frame');
        cancelCodexWriterHandoffAfterRejectedAction(tabId, 'codex-thread-rollback-rejected');
        return {
          success: false,
          error: 'codex_thread_rollback_failed',
          rejectionProof: rollbackFailure.proofSource,
          rejectionLine: rollbackFailure.failureLine,
          clean: confirmClean.slice(0, 800),
        };
      }
      if (confirmFrame.timedOut || (targetNeedle.length > 0 && !normalizeCandidate(confirmClean).includes(targetNeedle))) {
        console.warn('[Codex:Rewind] confirm frame did not include target prefill; verifying composer via grab'
          + ' timedOut=' + confirmFrame.timedOut
          + ' targetNeedle=' + JSON.stringify(targetNeedle)
          + ' clean=' + JSON.stringify(confirmClean.slice(0, 220)));
      }
      await drainPtyData(term, 120, 700);

      console.log('[Codex:Rewind] ' + (hasPasteAfter ? 'Clearing restored prompt before AI compact paste' : 'Moving clicked prompt out of terminal input into History draft') + ' (' + targetInputText.length + ' chars)');
      const grabResult = await grabRestoredCodexRewindInput(targetInputText, targetPayload);
      if (!grabResult || grabResult.success === false) {
        console.warn('[Codex:Rewind] Could not verify terminal input clear after native backtrack: ' + (grabResult?.error || 'unknown'));
        surfaceConfirmStartupFrameIfUnrecovered('codex-rewind-confirm-grab-failed-startup-frame');
        return {
          success: false,
          error: grabResult?.error || 'codex_rewind_restored_input_grab_failed',
          pending: true,
          operationId: rewindPostEnterRecord.operationId,
          rollbackTurns,
          pressCount: escPressCount,
          rollbackMayHaveApplied: true,
        };
      }
      console.log('[Codex:Rewind] Terminal input grabbed+cleared chars=' + (grabResult.text ? grabResult.text.length : 0)
        + ' matchedTarget=' + grabResult.matchedTarget
        + ' matchMode=' + (grabResult.matchMode || '-')
        + ' attempt=' + grabResult.attempt);
      if (!grabResult.matchedTarget) {
        console.warn('[Codex:Rewind] restored input mismatch restoredPreview='
          + JSON.stringify(String(grabResult.text || '').slice(0, 180))
          + ' targetPreview=' + JSON.stringify(targetInputText.slice(0, 180)));
        await markCodexTuiReadyAfterVerifiedComposer(tabId, 'codex-rewind-grab-mismatch-recovered');
        return {
          success: false,
          error: 'codex_rewind_restored_input_mismatch',
          rollbackTurns,
          pressCount: escPressCount,
          rollbackMayHaveApplied: true,
          restoredPreview: String(grabResult.text || '').slice(0, 160),
          targetPreview: targetInputText.slice(0, 160),
        };
      }
      if (grabResult.empty || !grabResult.text || normalizeCandidate(grabResult.text).length === 0) {
        surfaceConfirmStartupFrameIfUnrecovered('codex-rewind-confirm-empty-grab-startup-frame');
        return {
          success: false,
          error: 'codex_rewind_restored_input_empty',
          rollbackTurns,
          pressCount: escPressCount,
          rollbackMayHaveApplied: true,
        };
      }

      await markCodexTuiReadyAfterVerifiedComposer(tabId, 'codex-rewind-grab-success');
      const committedChildBeforeStableProof = inspectCommittedCodexRewindChild(
        handoffActionGeneration,
      );
      let stableSourceProof = null;
      let branchDraftProof = null;
      let committedChildAfterStableProof = {
        committed: false,
        sourceSessionId: null,
        childSessionId: null,
      };
      if (!committedChildBeforeStableProof.committed) {
        // Give the provider-owned child its full event-driven handoff window
        // before classifying the restored composer. A returned draft is only
        // proof that the native picker prepared an edit; it is NOT proof that
        // the source rollout was durably rolled back in place.
        handoffSettlementResult = await settleCodexWriterHandoffObservation(
          tabId,
          'programmatic-rewind-await-child',
          { waitForBranchMs: 8000 },
        );
        committedChildAfterStableProof = inspectCommittedCodexRewindChild(
          handoffActionGeneration,
        );
        if (!committedChildAfterStableProof.committed) {
          const stableOutcome = await inspectManualCodexStableSourceRollbackOutcome(
            tabId,
            rewindCommitExpectation,
          );
          if (stableOutcome.proven === true) {
            stableSourceProof = markCodexWriterHandoffRollbackApplied(tabId, {
              actionGeneration: handoffActionGeneration,
              restoredTextHash: authoritativeTargetTextHash,
              appliedAtMs: stableOutcome.rollbackTimestampMs,
            });
          } else {
            branchDraftProof = markCodexWriterHandoffBranchDraftRestored(tabId, {
              actionGeneration: handoffActionGeneration,
              restoredTextHash: authoritativeTargetTextHash,
              restoredAtMs: Date.now(),
            });
            if (branchDraftProof?.success === true) {
              handoffSettlementResult = {
                status: 'branch-draft-restored',
                sourceSessionId: handoffObserver?.sourceSessionId || writer?.sessionId || null,
                activeSessionId: handoffObserver?.sourceSessionId || writer?.sessionId || null,
                bindingCommitted: true,
                handoffStatus: 'branch-draft-restored',
                handoffGeneration: handoffActionGeneration,
              };
            }
          }
          if (stableSourceProof?.success !== true
            && branchDraftProof?.success !== true) {
            // The exact child may atomically commit and consume the journal
            // while the source/branch-draft CAS is in flight.
            committedChildAfterStableProof = inspectCommittedCodexRewindChild(
              handoffActionGeneration,
            );
          }
        }
      }
      const completionProof = branchDraftProof?.success === true
        ? {
            success: true,
            proofMode: 'branch-draft-restored',
            racedWithStableSourceProof: false,
          }
        : resolveCodexRewindCompletionProof({
            committedChildBeforeStableProof: committedChildBeforeStableProof.committed,
            stableSourceProof,
            committedChildAfterStableProof: committedChildAfterStableProof.committed,
          });
      if (completionProof.success !== true) {
        return {
          success: false,
          error: completionProof.error || 'codex_rewind_completion_proof_missing',
          rollbackTurns,
          pressCount: escPressCount,
          rollbackMayHaveApplied: true,
        };
      }
      const committedChildProof = committedChildBeforeStableProof.committed
        ? committedChildBeforeStableProof
        : committedChildAfterStableProof;
      if (committedChildProof?.receiptId) {
        handoffSettlementResult = {
          status: 'adopted',
          sourceSessionId: committedChildProof.sourceSessionId,
          activeSessionId: committedChildProof.childSessionId,
          bindingCommitted: true,
          handoffStatus: 'adopted-child',
          handoffGeneration: handoffActionGeneration,
          proofMode: 'durable-commit-receipt',
          receiptId: committedChildProof.receiptId,
        };
      }
      console.log('[CodexWriterHandoff] post-grab completion proof tab='
        + String(tabId).slice(-12)
        + ' mode=' + completionProof.proofMode
        + ' raced=' + completionProof.racedWithStableSourceProof
        + ' source=' + String(
          committedChildProof.sourceSessionId || handoffObserver?.sourceSessionId || 'none',
        ).slice(0, 8)
        + ' child=' + String(committedChildProof.childSessionId || 'none').slice(0, 8)
        + ' generation=' + handoffActionGeneration
        + ' receipt=' + (committedChildProof.receiptId || 'none'));
      const writerHandoff = await settleAppliedCodexRewindWriter('programmatic-rewind-applied');
      if (!writerHandoff.success) {
        return {
          ...writerHandoff,
          rollbackTurns,
          pressCount: escPressCount,
        };
      }

      if (hasPasteAfter) {
        const pasteResult = await pasteCodexRewindAiCompact('after-grab');
        if (!pasteResult?.success) {
          return {
            success: false,
            error: pasteResult?.error || 'paste_after_failed',
            rollbackTurns,
            pressCount: escPressCount,
            rollbackMayHaveApplied: true,
          };
        }
        return {
          success: true,
          targetIndex: idx,
          rewindableCount: count,
          rollbackTurns,
          pressCount: escPressCount,
          restoredInput: false,
          historyInputDraft: false,
          compactPasted: true,
          ...writerHandoff,
        };
      }

      return {
        success: true,
        targetIndex: idx,
        rewindableCount: count,
        rollbackTurns,
        pressCount: escPressCount,
        restoredInput: false,
        historyInputDraft: true,
        historyDraftText: typeof grabResult.historyDraftText === 'string' && grabResult.historyDraftText.trim()
          ? grabResult.historyDraftText
          : grabResult.text,
        historyDraftWarning: grabResult.historyDraftWarning || '',
        restoredMatchMode: grabResult.matchMode || '',
        ...writerHandoff,
      };
    }, codexRewindPtyOperation);
    return codexRewindOperationResult;
  } catch (err) {
    if (err?.code === 'rewind_cancelled') {
      codexRewindOperationResult = { success: false, cancelled: true, error: 'rewind_cancelled', stage: err.stage,
        rollbackMayHaveApplied: handoffMutationStarted, pending: handoffMutationStarted };
      return codexRewindOperationResult;
    }
    console.log('[Codex:Rewind] Error:', err?.message || String(err));
    codexRewindOperationResult = { success: false, error: err?.message || String(err),
      rollbackMayHaveApplied: handoffMutationStarted, pending: handoffMutationStarted };
    return codexRewindOperationResult;
  } finally {
    try {
      // Any normal return before the confirm Enter (journal failure, target
      // mismatch, cancellation) must leave the proven-open native protocol UI.
      // Once Enter may have been written, do not guess with another key.
      if (shouldCloseCodexRewindProtocolUi({
        protocolUiOpen: codexRewindOverlayOpen,
        handoffMutationStarted,
      })) {
        await closeCodexRewindProtocolUi('finally-before-confirm-enter');
        codexRewindOverlayOpen = false;
        activeRewindOperation.protocolUiOpen = false;
      }
      if (handoffObservationArmed) {
        if (!handoffMutationStarted) {
          cancelCodexWriterHandoffBeforeAction(tabId, 'programmatic-rewind-not-applied');
        } else if (!handoffSettlementResult?.bindingCommitted) {
          handoffSettlementResult = await settleCodexWriterHandoffObservation(
            tabId,
            'programmatic-rewind-finally',
            // The normal path already performed the full event-driven wait.
            // `finally` only takes one last point-in-time proof in that case;
            // failures before settlement still receive the single full wait.
            { waitForBranchMs: handoffSettlementResult ? 0 : 8000 },
          );
        }
        if (handoffMutationStarted && codexRewindOperationResult && handoffSettlementResult) {
          Object.assign(codexRewindOperationResult, {
            sourceSessionId: handoffSettlementResult.sourceSessionId || writer?.sessionId || null,
            activeSessionId: handoffSettlementResult.activeSessionId || null,
            bindingCommitted: handoffSettlementResult.bindingCommitted === true,
            handoffStatus: handoffSettlementResult.handoffStatus || 'unresolved',
            handoffGeneration: handoffSettlementResult.handoffGeneration || null,
          });
          if (codexRewindOperationResult.success === true
            && handoffSettlementResult.bindingCommitted !== true) {
            Object.assign(codexRewindOperationResult, {
              success: false,
              error: handoffSettlementResult.error || 'codex_rewind_writer_handoff_unresolved',
              rollbackMayHaveApplied: true,
            });
          }
        }
      }
      if (codexRewindOperationResult?.success === true
        && rewindCommitExpectation
        && durableCommittedChildProof?.committed === true) {
        const finalizedReceipt = finalizeCodexNativeRewindCommitReceipt(
          tabId,
          rewindCommitExpectation,
          durableCommittedChildProof,
        );
        codexRewindOperationResult.commitReceiptFinalized = finalizedReceipt?.success === true;
        codexRewindOperationResult.commitReceiptId = durableCommittedChildProof.receiptId;
        if (finalizedReceipt?.success === true) {
          console.log('[CodexWriterHandoff] final callback consumed commit receipt tab='
            + String(tabId).slice(-12)
            + ' source=' + String(durableCommittedChildProof.sourceSessionId || 'none').slice(0, 8)
            + ' child=' + String(durableCommittedChildProof.childSessionId || 'none').slice(0, 8)
            + ' generation=' + rewindCommitExpectation.actionGeneration
            + ' updated=' + (finalizedReceipt.updated === true));
        } else {
          // The exact result is already proven and must not be downgraded just
          // because audit closure could not be persisted. A later exact retry
          // or restart can still consume the unchanged committed receipt.
          console.warn('[CodexWriterHandoff] commit receipt finalization deferred tab='
            + String(tabId).slice(-12)
            + ' generation=' + rewindCommitExpectation.actionGeneration
            + ' error=' + (finalizedReceipt?.error || 'unknown'));
        }
      }
      if (rewindPostEnterRecord?.durable.enterWrittenAt) {
        try {
          persistCodexRewindPostEnter(rewindPostEnterRecord,
            codexRewindOperationResult?.success === true
              ? { phase: 'completed', result: codexRewindOperationResult }
              : { lastError: codexRewindOperationResult?.error || 'rewind-result-pending' });
        } catch (error) {
          console.error('[RewindPostEnter] retaining in-memory operation after journal failure:', error);
        }
      }
      if (rewindActionAuthority
        && rewindActionAuthority.phase !== 'committed'
        && rewindActionAuthority.phase !== 'revoked') {
        if (codexRewindOperationResult?.success === true
          && codexRewindOperationResult?.bindingCommitted === true
          && rewindActionAuthority.phase === 'consumed'
          && codexRewindOperationResult?.handoffStatus !== 'branch-draft-restored') {
          transitionMainCodexActionAuthority(
            rewindActionAuthority,
            'committed',
            'rewind-result-committed',
          );
        } else if (codexRewindOperationResult?.success === true
          && codexRewindOperationResult?.handoffStatus === 'branch-draft-restored') {
          // The same consumed authority remains attached to the exact next
          // submit. The branch is not durable until that submit materializes
          // a child (or a provider-owned same-source user_message).
        } else if (rewindPostEnterRecord?.durable.enterWrittenAt
          && isCodexRewindPostEnterCurrent(rewindPostEnterRecord)) {
          // Enter already happened. An unfinished transfer is not revocation
          // of the native action. Only this operation's continuation may use
          // the remaining lease; it has no path back to Rewind or Enter.
          console.warn('[RewindPostEnter] pending operation retained tab=' + tabId
            + ' operation=' + rewindPostEnterRecord.operationId
            + ' phase=' + rewindPostEnterRecord.durable.phase);
        } else {
          transitionMainCodexActionAuthority(
            rewindActionAuthority,
            'revoked',
            codexRewindOperationResult?.error || 'rewind-not-committed',
          );
        }
      }
    } finally {
      releaseExclusiveActionReservation(codexRewindReservations, rewindReservation);
      rewindCancelTabs.delete(tabId);
      finishActiveRewindOperation(activeRewindOperation);
    }
  }
});

ipcMain.on('claude:prompt-boundary-ack', (_event, data = {}) => {
  const tabId = data?.tabId;
  const seq = Number(data?.seq);
  console.log('[BoundaryMarkerAck] tab=' + String(tabId || '').slice(-12)
    + ' seq=' + (Number.isFinite(seq) ? seq : 'invalid')
    + ' source=renderer-direct');
});

ipcMain.handle('terminal:get-headless-buffer-snapshot', async (_event, request = {}) => {
  const tabId = typeof request === 'string' ? request : request?.tabId;
  if (!tabId) return { success: false, error: 'missing-tab-id' };
  return getHeadlessSerializedTerminalSnapshot(tabId, 'renderer-hydration');
});

// Resize terminal. Renderer includes the PTY identity so a delayed layout
// callback from an old surface cannot resize a replacement process for the
// same tabId.
ipcMain.on('terminal:resize', (event, requestOrTabId, legacyCols, legacyRows) => {
  const request = requestOrTabId && typeof requestOrTabId === 'object'
    ? requestOrTabId
    : {
        tabId: requestOrTabId,
        cols: legacyCols,
        rows: legacyRows,
        expectedPid: null,
      };
  const tabId = request?.tabId;
  const cols = request?.cols;
  const rows = request?.rows;
  const expectedPid = Number.isFinite(request?.expectedPid)
    ? Number(request.expectedPid)
    : null;
  const term = terminals.get(tabId);
  if (term) {
    if (expectedPid !== null && Number(term.pid) !== expectedPid) {
      console.warn('[terminal:resize] stale renderer ignored tabId=' + tabId
        + ' expectedPid=' + expectedPid
        + ' currentPid=' + term.pid
        + ' cols=' + cols
        + ' rows=' + rows);
      return;
    }
    console.log('[terminal:resize] tabId=' + tabId + ' cols=' + cols + ' rows=' + rows + ' ts=' + Date.now());
    resizeHeadlessTerminalMirror(tabId, cols, rows);
    term.resize(cols, rows);
  }
});

// Kill terminal
ipcMain.on('terminal:kill', async (event, tabId) => {
  const startedAt = Date.now();
  const term = terminals.get(tabId);
  revokeCodexActionAuthoritiesForTab(tabId, 'terminal-kill');
  cancelCodexManualCompactPending(tabId, 'terminal-kill');
  clearClaudeEditableLastPrompt(tabId, 'terminal-kill');
  const bridgeSessionId = bridgeKnownSessions.get(tabId) || null;
  const turnBusyAtKill = claudeTurnBusy.get(tabId) === true;
  const spinnerBusyAtKill = claudeSpinnerBusy.get(tabId) === true;
  const localBusyAtKill = claudeLocalCommandWatchers.has(tabId);
  // Codex has no bridge file and never appears in the claude|gemini scan below,
  // so the graceful flush was structurally unreachable for it: a busy Codex turn
  // went straight to SIGHUP and lost its in-flight rollout write. Its liveness
  // proof is the rollout watcher, which is the same source the loader reads.
  const codexTurnStateAtKill = codexTurnWatchers.get(tabId) || null;
  const codexBusyAtKill = codexTurnStateAtKill?.busy === true;
  const codexSessionAtKill = codexBusyAtKill ? getCodexRuntimeSessionId(tabId) : null;
  const gracefulOwner = (bridgeSessionId && (turnBusyAtKill || localBusyAtKill))
    ? 'claude'
    : codexBusyAtKill
      ? 'codex'
      : null;
  console.log('[TerminalKill] start tab=' + String(tabId).slice(-12) +
    ' hasTerm=' + !!term +
    ' bridge=' + (bridgeSessionId ? bridgeSessionId.slice(0, 8) : 'none') +
    ' turnBusy=' + turnBusyAtKill +
    ' spinnerBusy=' + spinnerBusyAtKill +
    ' localBusy=' + localBusyAtKill +
    ' codexBusy=' + codexBusyAtKill +
    ' codexSession=' + (codexSessionAtKill ? String(codexSessionAtKill).slice(0, 8) : 'none') +
    ' graceful=' + (gracefulOwner || 'none'));
  if (term) {
    // Graceful Ctrl+C to live claude before SIGHUP via term.kill().
    // Same reasoning as before-quit and terminal:stop-ai-process: term.kill()
    // delivers SIGHUP through the PTY which propagates to children and
    // bypasses Ink TUI, dropping any in-flight JSONL write. \x03 lets Claude
    // flush the current assistant entry first.
    //
    // Only wait when a Claude turn is actually active. At idle prompt a single
    // Ctrl+C opens Claude's danger-zone instead of exiting, so the old logic
    // burned the full 1200ms on nearly every close-tab despite no JSONL write
    // being in flight.
    if (gracefulOwner) {
      // One shared process-tree observation for every agent. The old inline
      // `ps | grep -E " (claude|gemini)( |$)"` could not match Codex at all:
      // its wrapper shows up as `node /opt/homebrew/bin/codex` or under
      // `@openai/codex`, and it often sits one level below the shell. The
      // shared lookup already encodes those shapes and the depth fallback.
      let childPid = null;
      try {
        const lookup = await inspectAiDescendantProcessesByTab(tabId, null, { forceFresh: true });
        const candidate = lookup.status === AI_PROCESS_LOOKUP_STATUS.FOUND
          ? selectAiProcessForStop(lookup.matches)
          : null;
        if (candidate) childPid = Number(candidate.pid);
      } catch (err) {
        console.log('[TerminalKill:GracefulCtrlC] lookup failed tab=' + String(tabId).slice(-12)
          + ': ' + (err?.message || err));
      }
      if (childPid) {
        const sid = gracefulOwner === 'codex'
          ? codexSessionAtKill
          : bridgeKnownSessions.get(tabId);
        console.log('[TerminalKill:GracefulCtrlC] tabId=' + tabId.slice(-12) + ' owner=' + gracefulOwner + ' childPid=' + childPid + ' sessionId=' + (sid ? String(sid).substring(0, 8) : 'none') + ' — \\x03 → waiting for graceful exit');
        try { term.write('\x03'); } catch (err) { console.log('[TerminalKill:GracefulCtrlC] write failed: ' + err.message); }
        await new Promise((resolve) => {
          const start = Date.now();
          const poll = () => {
            try {
              process.kill(childPid, 0);
              if (Date.now() - start >= 1200) {
                console.log('[TerminalKill:GracefulCtrlC] tabId=' + tabId.slice(-12) + ' childPid=' + childPid + ' — did NOT exit in 1200ms, term.kill() will SIGHUP it');
                return resolve();
              }
              setTimeout(poll, 60);
            } catch {
              console.log('[TerminalKill:GracefulCtrlC] tabId=' + tabId.slice(-12) + ' childPid=' + childPid + ' — exited cleanly in ' + (Date.now() - start) + 'ms');
              resolve();
            }
          };
          setTimeout(poll, 60);
        });
      } else {
        console.log('[TerminalKill:GracefulCtrlC] tabId=' + tabId.slice(-12) +
          ' owner=' + gracefulOwner +
          ' busy turn but no AI child found; skipping wait and killing PTY');
      }
    } else if (bridgeSessionId || codexSessionAtKill) {
        console.log('[TerminalKill:FastClose] tabId=' + tabId.slice(-12) +
        ' idle agent bridge=' + (bridgeSessionId ? bridgeSessionId.slice(0, 8) : 'none') +
        ' turnBusy=' + turnBusyAtKill +
        ' spinnerBusy=' + spinnerBusyAtKill +
        ' localBusy=' + localBusyAtKill +
        ' codexBusy=' + codexBusyAtKill +
        ' — skip 1200ms Ctrl+C wait');
    }
    const termination = terminateCapturedTerminalRuntime(terminals, tabId, term);
    if (!termination.released) {
      console.warn('[TerminalKill] ownership changed while stopping; preserving replacement tab='
        + String(tabId).slice(-12)
        + ' oldPid=' + term.pid
        + ' currentPid=' + (terminals.get(tabId)?.pid || '-')
        + ' oldKilled=' + termination.killed);
      terminalShellReadiness.remove(tabId, term);
      return;
    }
    console.log('[TerminalKill] term.kill sent tab=' + String(tabId).slice(-12) +
      ' durMs=' + (Date.now() - startedAt));
  }
  clearBridgeTab(tabId, 'terminal-kill');
  clearAiStopping(tabId, 'terminal-kill');
  clearTimeout(codexFinishDebounceTimers.get(tabId));
  codexFinishDebounceTimers.delete(tabId);
  clearCodexDescendantExitRecheck(tabId, 'terminal-kill');
  disposeHeadlessTerminalMirror(tabId, 'terminal-kill');
  invalidateAiProcessLookupCache(tabId);
  clearCodexLaunchPayload(tabId, 'terminal-kill');
  clearCodexKnownSession(tabId, 'terminal-kill');
  clearCodexTuiReady(tabId, 'terminal-kill');
  claudeToolScreenHolds.clear(tabId);
  disarmCodexProviderSemanticSource(tabId, 'terminal-kill');
  safelyObserveProviderSemantic(
    'terminal-kill-clear',
    () => providerSemanticShadow.clear(tabId, 'terminal-kill'),
  );
  codexImageBindings.clear(tabId);
  geminiActiveTabs.delete(tabId);
  geminiInputCharCount.delete(tabId);
  closeCodexWatcher(tabId, 'terminal-kill');
  closeCodexTurnWatcher(tabId, 'terminal-kill');
  // Close any open activity interval on kill (idempotent, either engine).
  recordActivity(tabId, false);
  // Claude spinner cleanup on kill
  clearTimeout(claudeSpinnerIdleTimer.get(tabId));
  if (claudeSpinnerBusy.get(tabId)) {
    console.log('[Spinner] Tab ' + tabId + ': IDLE (terminal kill cleanup)');
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: localBusyAtKill ? 'local-command' : undefined });
    }
  }
  // Same as PTY exit path — make mobile-web subscribers aware that this
  // PTY+Claude tab has been killed. Without this the phone shows composer
  // as still active and Send fails with terminal:paste "no PTY" silently.
  console.log('[MobBcast] busy+snapshot tab=' + String(tabId).slice(-12) + ' busy=false status=inactive src=terminal-kill');
  _webBroadcast(tabId, { type: 'busy', busy: false });
  _webBroadcast(tabId, { type: 'snapshot', sessionId: null, busy: false, sessionStatus: 'inactive', inputReady: false });
  claudePromptReady.delete(tabId);
  claudeSpinnerBusy.delete(tabId);
  claudeSpinnerIdleTimer.delete(tabId);
  console.log('[TerminalKill] done tab=' + String(tabId).slice(-12) +
    ' durMs=' + (Date.now() - startedAt));
});

// Helper: async exec with timeout
const execAsync = (cmd, timeout = 1000) => {
  return new Promise((resolve, reject) => {
    const { exec } = require('child_process');
    const child = exec(cmd, {
      encoding: 'utf-8',
      timeout,
      env: buildChildProcessEnv(),
    }, (err, stdout) => {
      if (err) reject(err);
      else resolve(stdout.trim());
    });
  });
};

// ========== MCP PID MATCHING ==========
// Resolve childPid → parent shell PID → match pty.pid → tabId
// Same logic as Bridge: claudePid → shellPid → pty.pid → tabId
async function findTabByChildPid(childPid) {
  try {
    const ppidStr = await execAsync('ps -p ' + childPid + ' -o ppid=');
    const shellPid = parseInt(ppidStr.trim());
    for (const [tid, pty] of terminals) {
      if (pty.pid === shellPid) return tid;
    }
    // Try one more level up (gemini CLI → node → shell → pty)
    const ppidStr2 = await execAsync('ps -p ' + shellPid + ' -o ppid=');
    const grandParentPid = parseInt(ppidStr2.trim());
    for (const [tid, pty] of terminals) {
      if (pty.pid === grandParentPid) return tid;
    }
  } catch {}
  return null;
}

// Bug 3 fix: cached version — ppid is stable within MCP server lifetime,
// but findTabByChildPid can fail on subsequent calls if process tree shifts
async function findTabByChildPidCached(childPid) {
  if (!childPid) return null;
  const cached = ppidToGeminiTab.get(childPid);
  if (cached && terminals.has(cached)) {
    return cached;
  }
  const resolved = await findTabByChildPid(childPid);
  if (resolved) {
    console.log('[MCP:PIDCache] Cached ppid ' + childPid + ' → geminiTabId ' + resolved);
    ppidToGeminiTab.set(childPid, resolved);
  }
  return resolved;
}

async function observeProcessCwd(pid, options = {}) {
  if (!Number.isInteger(Number(pid)) || Number(pid) <= 1) {
    return { status: 'absent', reason: 'process-missing', pid: Number(pid) || null };
  }
  try {
    if (process.platform === 'darwin') {
      // macOS: field mode returns the full path. Plain lsof table output can
      // truncate NAME, which corrupts persisted tab cwd on long project paths.
      const result = await execAsync(`lsof -a -p ${Number(pid)} -d cwd -Fn`);
      const cwdLine = String(result || '').split(/\r?\n/).find(line => line.startsWith('n'));
      const cwd = cwdLine ? cwdLine.slice(1).trim() : '';

      if (cwd) {
        try {
          if (path.isAbsolute(cwd) && fs.statSync(cwd).isDirectory()) {
            return { status: 'found', cwd, pid: Number(pid) };
          }
          if (!options.quiet) console.warn('[terminal:getCwd] Ignoring non-directory cwd from lsof pid=' + pid + ' cwd=' + cwd);
        } catch {
          if (!options.quiet) console.warn('[terminal:getCwd] Ignoring missing cwd from lsof pid=' + pid + ' cwd=' + cwd);
        }
        return { status: 'unknown', reason: 'observed-cwd-invalid', cwd, pid: Number(pid) };
      }
      return { status: 'absent', reason: 'successful-empty-snapshot', pid: Number(pid) };
    } else if (process.platform === 'linux') {
      // Linux: read /proc/<pid>/cwd symlink (fs.promises for async)
      const cwd = await fs.promises.readlink(`/proc/${pid}/cwd`);
      return { status: 'found', cwd, pid: Number(pid) };
    }
  } catch (e) {
    if (!options.quiet) console.error('[main] Failed to get cwd for pid ' + pid + ':', e.message);
    return {
      status: 'unknown',
      reason: e?.killed ? 'lookup-timeout' : 'lookup-error',
      pid: Number(pid),
    };
  }

  return { status: 'unknown', reason: 'unsupported-platform', pid: Number(pid) };
}

async function observeTerminalProcessCwd(tabId, options = {}) {
  const term = terminals.get(tabId);
  if (!term) return { status: 'absent', reason: 'terminal-missing' };

  const rootObservation = await observeProcessCwd(term.pid, options);
  const candidate = typeof options.candidate === 'string' ? options.candidate : null;
  if (!candidate || rootObservation.cwd === candidate) {
    return {
      ...rootObservation,
      source: rootObservation.status === 'found' ? 'pty-root' : null,
    };
  }

  let snapshot;
  try {
    snapshot = await getProcessTreeSnapshot({ forceFresh: true });
  } catch (error) {
    return {
      status: 'unknown',
      reason: 'process-tree-lookup-error',
      error: error?.message || String(error),
      rootCwd: rootObservation.cwd || null,
    };
  }

  const descendants = collectDescendantProcessEntries(snapshot.children, term.pid);
  const rootProcess = snapshot.processesByPid?.get(term.pid) || null;
  const foregroundPgid = Number(rootProcess?.tpgid);
  const hasForegroundPgid = Number.isInteger(foregroundPgid) && foregroundPgid > 0;
  const rootIsForeground = hasForegroundPgid && Number(rootProcess?.pgid) === foregroundPgid;
  const scopedDescendants = hasForegroundPgid
    ? descendants.filter((entry) => Number(entry.pgid) === foregroundPgid)
    : descendants;
  const foregroundProcessMissing = hasForegroundPgid
    && !rootIsForeground
    && scopedDescendants.length === 0;
  const descendantObservations = await Promise.all(scopedDescendants.map(async (entry) => ({
    entry,
    observation: await observeProcessCwd(entry.pid, options),
  })));
  const observations = [];
  if (rootObservation.status === 'found') {
    observations.push({
      pid: term.pid,
      depth: 0,
      cwd: rootObservation.cwd,
    });
  }
  for (const { entry, observation } of descendantObservations) {
    if (observation.status !== 'found') continue;
    observations.push({
      pid: entry.pid,
      depth: entry.depth,
      cwd: observation.cwd,
      cmd: entry.cmd,
    });
  }
  const descendantsComplete = descendantObservations.every(({ observation }) => (
    observation.status === 'found' || observation.status === 'absent'
  )) && !foregroundProcessMissing;
  const selected = await selectTerminalCwdObservation({
    candidate,
    rootPid: term.pid,
    observations,
    descendantsComplete,
  });
  return {
    ...selected,
    rootCwd: rootObservation.cwd || null,
    descendantsObserved: descendantObservations.filter(({ observation }) => observation.status === 'found').length,
    descendantsTotal: scopedDescendants.length,
    foregroundPgid: hasForegroundPgid ? foregroundPgid : null,
    foregroundScope: hasForegroundPgid ? 'terminal-foreground-pgid' : 'all-descendants',
    snapshotSource: snapshot.source,
  };
}

async function getTerminalCurrentCwd(tabId, options = {}) {
  const observed = await observeTerminalProcessCwd(tabId, options);
  if (observed.status === 'found') return observed.cwd;
  // Read callers may use the last accepted value as a fallback. OSC updates do
  // not: they call observeTerminalProcessCwd directly and require live proof.
  return terminalProjects.get(tabId) || null;
}

// Get current working directory of terminal process
ipcMain.handle('terminal:getCwd', async (event, tabId) => {
  return getTerminalCurrentCwd(tabId);
});

ipcMain.on('terminal:remember-detected-command', (event, { tabId, command } = {}) => {
  rememberDetectedTerminalCommand(tabId, command);
});

ipcMain.handle('terminal:updateCwd', async (event, { tabId, cwd } = {}) => {
  const retainedCwd = tabId ? (terminalProjects.get(tabId) || null) : null;
  if (!tabId || !terminals.has(tabId)) {
    return { accepted: false, reason: 'terminal-missing', retainedCwd };
  }

  let liveObservation = null;
  const result = await validateTerminalCwdCandidate({
    candidate: cwd,
    readLiveCwd: async () => {
      liveObservation = await observeTerminalProcessCwd(tabId, {
        quiet: true,
        candidate: cwd,
      });
      if (liveObservation.status !== 'found') {
        const error = new Error(liveObservation.reason || 'live-cwd-unknown');
        error.code = liveObservation.status;
        throw error;
      }
      return liveObservation.cwd;
    },
  });

  if (!result.accepted) {
    console.warn('[TerminalCwdProof] rejected ' + JSON.stringify({
      tabId,
      candidate: typeof cwd === 'string' ? cwd : null,
      reason: result.reason,
      observedCwd: result.observedCwd || null,
      lookupStatus: liveObservation?.status || null,
      lookupReason: liveObservation?.reason || null,
      lookupSource: liveObservation?.source || null,
      lookupPid: liveObservation?.pid || null,
      lookupRootCwd: liveObservation?.rootCwd || null,
      retainedCwd,
    }));
    return {
      ...result,
      retainedCwd,
      lookupStatus: liveObservation?.status || null,
      lookupReason: liveObservation?.reason || null,
    };
  }

  let persisted = false;
  try {
    persisted = projectManager.db.updateTabCwd(tabId, result.cwd);
  } catch (error) {
    console.warn('[TerminalCwdProof] point-persist failed ' + JSON.stringify({
      tabId,
      cwd: result.cwd,
      error: error?.message || String(error),
    }));
  }
  terminalProjects.set(tabId, result.cwd);
  const cwdChangeProof = terminalCwdChangeProofs.observe({
    tabId,
    terminalToken: terminals.get(tabId),
    cwd: result.cwd,
    persisted,
  });
  console.log('[TerminalCwdProof] accepted ' + JSON.stringify({
    tabId,
    candidate: cwd,
    observedCwd: result.observedCwd,
    lookupSource: liveObservation?.source || null,
    lookupPid: liveObservation?.pid || null,
    lookupRootCwd: liveObservation?.rootCwd || null,
    persisted,
    cwdChangeOperationId: cwdChangeProof.matched ? cwdChangeProof.operationId : null,
  }));
  return { ...result, persisted };
});

// Change only this tab's working directory. The command is written at the same
// proven-idle shell boundary as an AI launch, then completion is tied to the
// exact OSC 7 value that main validates against the live PTY process. A timer
// can surface missing observability, but it never commits cwd by itself.
ipcMain.handle('terminal:change-working-directory', async (_event, request = {}) => {
  const tabId = String(request?.tabId || '');
  const requestedTarget = normalizeDirectoryTarget(request?.targetCwd);
  if (!tabId || !requestedTarget) {
    return { success: false, accepted: false, error: 'invalid_directory_change_request' };
  }

  let targetCwd;
  try {
    const stat = await fs.promises.stat(requestedTarget);
    if (!stat.isDirectory()) {
      return { success: false, accepted: false, error: 'working_directory_not_directory' };
    }
    targetCwd = await fs.promises.realpath(requestedTarget);
  } catch (error) {
    return {
      success: false,
      accepted: false,
      error: 'working_directory_unavailable',
      detail: error?.message || String(error),
    };
  }

  return runKeyedExclusive(aiLifecycleActionInflight, tabId, async () => {
    const term = terminals.get(tabId);
    if (!term) {
      return { success: false, accepted: false, error: 'terminal_not_found' };
    }
    const fromCwd = terminalProjects.get(tabId) || null;
    if (normalizeDirectoryTarget(fromCwd) === targetCwd) {
      return {
        success: true,
        accepted: true,
        unchanged: true,
        cwd: targetCwd,
        fromCwd,
        proof: 'already-current-live-cwd',
      };
    }
    const shellDraft = String(terminalInputLineBuffers.get(tabId) || '');
    if (shellDraft) {
      return {
        success: false,
        accepted: false,
        error: 'terminal_has_unsent_input',
        draftChars: shellDraft.length,
      };
    }

    const expectedRunSeq = Number(terminalCommandState.get(tabId)?.runSeq || 0);
    const admission = await proveIdleShellForAgentLaunch(tabId, 'cwd-change', {
      expectedTerm: term,
      expectedRunSeq,
    });
    if (!admission.allowed) {
      return {
        success: false,
        accepted: false,
        error: agentShellLaunchError(admission, 'foreground_command_running'),
        reason: admission.reason,
        lookupStatus: admission.lookup?.status || null,
      };
    }

    const pending = terminalCwdChangeProofs.begin({
      tabId,
      terminalToken: term,
      fromCwd,
      targetCwd,
      timeoutMs: 10_000,
    });
    if (!pending.success) return pending;

    try {
      writeAgentLaunchCommandToIdleShell(term, {
        tabId,
        toolType: 'cwd-change',
        command: `cd -- ${shellQuote(targetCwd)}`,
        launchId: pending.operationId,
        admission,
      });
    } catch (error) {
      terminalCwdChangeProofs.cancel(
        tabId,
        pending.operationId,
        error?.message || 'cwd_change_write_failed',
      );
    }

    const proof = await pending.promise;
    console.log('[TerminalCwdChange] settled ' + JSON.stringify({
      tabId,
      operationId: pending.operationId,
      fromCwd,
      targetCwd,
      success: proof.success === true,
      error: proof.error || null,
      waitedMs: proof.waitedMs,
    }));
    return proof;
  });
});

// Renderer components can mount after the shell already emitted its first
// OSC 133;A. Return the retained main-owned boundary for the exact live PTY so
// one-shot restore/fork launches do not depend on replaying renderer bytes.
ipcMain.handle('terminal:get-shell-prompt-readiness', (_event, request) => {
  const tabId = typeof request === 'string' ? request : request?.tabId;
  if (!tabId) return { ready: false, pid: null, readyAt: null };
  return terminalShellReadiness.snapshot(tabId, terminals.get(tabId) || null);
});

// Get command state (is command running?) - uses OSC 133 tracking
async function resolveTerminalCommandState(requestOptions = {}) {
  const tabId = requestOptions.tabId;
  const caller = requestOptions.caller || 'legacy';
  const requestedExpectedProcess = requestOptions.expectedProcess || null;
  // A renderer hint is not ownership proof. A single live/persisted Claude
  // binding must beat callers left over from the Codex-only implementation;
  // otherwise every Claude tab asks the OS for `codex`, finds none, and offers
  // Resume over an already-running Claude process.
  const expectedProcess = resolveAiToolTypeForTab(tabId, requestedExpectedProcess);
  const requireProviderProof = requestOptions.requireProviderProof === true
    || expectedProcess === 'claude';
  const allowProcessTreeLookup = requestOptions.allowProcessTreeLookup !== false
    || requireProviderProof;
  const ignoreBridgeAlive = requestOptions.ignoreBridgeAlive === true;
  const startedAt = nodePerformance.now();
  const startAbs = nodePerformance.timeOrigin + startedAt;
  const opId = beginPerfOp('getCommandState', { tabId, source: caller });
  const state = terminalCommandState.get(tabId);
  // OSC 133 B/D drives terminalCommandState.isRunning — but that marker is
  // MISSED when Claude was launched while this tab's Terminal component wasn't
  // mounted (restored on boot, started in a background tab, resumed without the
  // claude-c hotkey that force-emits command-started). In that case isRunning
  // stays false even though Claude is fully alive, and the Run-after overlay
  // (gated on claudeProcessAlive) never shows until the user Stop+continues.
  //
  // bridgeKnownSessions is the authoritative Claude "CLI alive in this tab,
  // persists until terminal killed" signal (see comment @ before-quit). If the
  // bridge knows a live session for this tab, Claude IS running regardless of
  // whether we captured the OSC B — report alive so the gate is correct.
  //
  // Process-tree proof closes two restart gaps. Codex has no Claude-style
  // bridge at all; Claude temporarily has no fresh bridge/statusline record
  // after main restarts. In both cases a provider descendant under this exact
  // PTY proves process liveness. This is not a busy signal; it only answers
  // "is the AI process running?".
  const bridgeAlive = !ignoreBridgeAlive && bridgeKnownSessions.has(tabId);
  const oscRunning = !!(state && state.isRunning);
  if (expectedProcess === 'codex' && codexManualActionRequired.has(tabId)) {
    return {
      isRunning: false,
      lastExitCode: state ? state.lastExitCode : 0,
      manualActionRequired: true,
      manualActionType: codexManualActionRequired.get(tabId)?.type || null,
    };
  }
  let providerProcessAlive = false;
  let providerLookupMs = 0;
  let providerMatches = 0;
  let didProviderLookup = false;
  let processLookupUnknown = false;
  let processLookupError = null;
  if (!bridgeAlive && allowProcessTreeLookup && (!oscRunning || requireProviderProof)) {
    didProviderLookup = true;
    const lookupStartedAt = nodePerformance.now();
    const lookup = await inspectAiDescendantProcessesByTabCached(tabId, expectedProcess);
    providerLookupMs = nodePerformance.now() - lookupStartedAt;
    const establishedCodexRuntime = expectedProcess === 'codex' && (
      codexKnownSessions.has(tabId)
      || codexTurnWatchers.has(tabId)
      || codexTuiReadyTabs.has(tabId)
      || codexLastRunCommandPayload.has(tabId)
      || activityOpenIntervals.get(tabId)?.engine === 'codex'
    );
    const presence = resolveProcessPresence(lookup, { established: establishedCodexRuntime });
    providerProcessAlive = presence.present;
    processLookupUnknown = presence.lookupUnknown;
    processLookupError = presence.error?.message || null;
    if (processLookupUnknown) {
      console.warn('[RunAfterDiag] getCommandState tab=' + tabId.slice(-8)
        + ' processLookup=unknown'
        + ' expected=' + expectedProcess
        + ' preserveEstablished=' + establishedCodexRuntime
        + ' error=' + processLookupError);
    } else {
      providerMatches = lookup.matches.length;
      if (providerProcessAlive && expectedProcess === 'codex') {
        await keepCodexRuntimeAliveFromProcessProof(tabId, lookup.matches, 'get-command-state-process-proof', {
          emitCommandStarted: true,
        });
      }
    }
  }
  if (bridgeAlive && !oscRunning) {
    console.warn(`[RunAfterDiag] getCommandState tab=${tabId.slice(-8)} oscRunning=false BUT bridgeAlive=true → reporting isRunning=true (OSC B was missed)`);
  }
  if (providerProcessAlive && !oscRunning) {
    console.warn(`[RunAfterDiag] getCommandState tab=${tabId.slice(-8)} oscRunning=false BUT providerProcessAlive=true expected=${expectedProcess || 'any'} → reporting isRunning=true (OSC B was missed)`);
  }
  const durMs = nodePerformance.now() - startedAt;
  if (durMs > 50 || providerLookupMs > 50 || didProviderLookup) {
    console.warn(
      '[Perf:GetCommandState] tab=' + tabId.slice(-8) +
      ' caller=' + caller +
      ' durMs=' + durMs.toFixed(1) +
      ' startAbs=' + startAbs.toFixed(1) +
      ' endAbs=' + (nodePerformance.timeOrigin + nodePerformance.now()).toFixed(1) +
      ' oscRunning=' + oscRunning +
      ' bridgeAlive=' + bridgeAlive +
      ' ignoreBridgeAlive=' + ignoreBridgeAlive +
      ' allowProcessTreeLookup=' + allowProcessTreeLookup +
      ' expected=' + expectedProcess +
      ' providerLookup=' + didProviderLookup +
      ' providerLookupMs=' + providerLookupMs.toFixed(1) +
      ' providerMatches=' + providerMatches +
      ' processLookupUnknown=' + processLookupUnknown +
      ' result=' + (oscRunning || bridgeAlive || providerProcessAlive)
    );
  }
  try {
    return {
      isRunning: oscRunning || bridgeAlive || providerProcessAlive,
      lastExitCode: state ? state.lastExitCode : 0,
      expectedProcess: expectedProcess || null,
      providerProcessAlive,
      processLookupUnknown,
      processLookupError,
    };
  } finally {
    endPerfOp(opId);
  }
}

ipcMain.handle('terminal:getCommandState', async (event, request) => {
  const requestOptions = (request && typeof request === 'object')
    ? request
    : { tabId: request };
  return resolveTerminalCommandState(requestOptions);
});

/**
 * Batched tab status for the tab strip.
 *
 * The strip used to ask per tab, so showing a project with 44 tabs fired 44
 * command-state calls plus one turn-state call per Codex tab — 76-90 concurrent
 * main-process operations that stalled the main loop for up to 1.8s and made
 * the switch itself feel frozen. The project already learned this lesson once
 * (see the OSC 133 scar: 2s status polling → events); this restores that rule
 * for the initial hydrate.
 *
 * Semantics are UNCHANGED: each tab resolves through the exact same
 * resolveTerminalCommandState / codex turn-state path the single call used, so
 * three-state process lookup (found/absent/unknown) and every liveness class
 * keep their meaning. What changed is the transport — one request, one shared
 * process-tree snapshot, sequential resolution instead of a stampede.
 */
ipcMain.handle('terminal:getCommandStates', async (_event, request = {}) => {
  const requested = Array.isArray(request?.tabs) ? request.tabs : [];
  const caller = request?.caller || 'batch';
  if (requested.length === 0) return { success: true, states: {} };
  const startedAt = nodePerformance.now();
  // Warm the shared process-tree snapshot once for the whole batch: every
  // per-tab lookup below reads it (single-flight + TTL) instead of racing to
  // spawn its own `ps`.
  try {
    await getProcessTreeSnapshot();
  } catch {}
  const states = {};
  let turnStates = 0;
  // Sequential on purpose. These resolve from in-memory maps plus the shared
  // snapshot; running them concurrently is what produced the stampede.
  for (const entry of requested) {
    const tabId = typeof entry === 'string' ? entry : entry?.tabId;
    if (!tabId) continue;
    const requestedCommandType = typeof entry === 'object' ? entry?.commandType : null;
    const resolvedToolType = resolveAiToolTypeForTab(tabId, requestedCommandType || null);
    const wantsCodex = resolvedToolType === 'codex';
    const wantsClaude = resolvedToolType === 'claude';
    let commandState = null;
    try {
      commandState = await resolveTerminalCommandState({
        tabId,
        caller,
        expectedProcess: resolvedToolType,
        allowProcessTreeLookup: wantsCodex || wantsClaude,
        requireProviderProof: wantsClaude,
      });
    } catch (error) {
      commandState = { isRunning: false, error: String(error?.message || error) };
    }
    let codexTurn = null;
    if (wantsCodex) {
      try {
        codexTurn = await resolveCodexTurnState(tabId);
        turnStates += 1;
      } catch {
        codexTurn = null;
      }
    }
    const claudePresence = wantsClaude
      ? getClaudePtyRuntimePresence(tabId, {
        providerProcessAlive: commandState?.expectedProcess === 'claude'
          && commandState?.providerProcessAlive === true,
        processLookupUnknown: commandState?.processLookupUnknown === true,
      })
      : null;
    if (claudePresence) turnStates += 1;
    states[tabId] = {
      ...commandState,
      resolvedToolType,
      codexTurn,
      claudePresence,
    };
  }
  const durMs = nodePerformance.now() - startedAt;
  if (durMs > 50) {
    console.warn('[Perf:GetCommandStates] caller=' + caller
      + ' tabs=' + requested.length
      + ' turnStates=' + turnStates
      + ' durMs=' + durMs.toFixed(1));
  }
  return { success: true, states };
});

ipcMain.handle('terminal:get-last-project-command', async (event, request = {}) => {
  const requestedProjectId = typeof request?.projectId === 'string' && request.projectId ? request.projectId : null;
  const ownerTabId = typeof request?.tabId === 'string' && request.tabId ? request.tabId : null;
  const cwd = typeof request?.cwd === 'string' && request.cwd ? request.cwd : null;
  let best = null;

  const resolveProjectId = (tabId) => {
    if (terminalProjectIds.has(tabId)) return terminalProjectIds.get(tabId);
    try {
      return projectManager?.db?.db
        ?.prepare('SELECT project_id FROM tabs WHERE tab_id = ? LIMIT 1')
        .get(tabId)?.project_id || null;
    } catch {
      return null;
    }
  };

  const ownerProjectId = ownerTabId ? resolveProjectId(ownerTabId) : null;
  const projectId = ownerProjectId || requestedProjectId;
  if (ownerProjectId && requestedProjectId && ownerProjectId !== requestedProjectId) {
    console.warn(
      '[LastCommand] project-mismatch tab=' + String(ownerTabId).slice(-12)
      + ' requested=' + requestedProjectId
      + ' owner=' + ownerProjectId
      + ' cwd=' + JSON.stringify(cwd || '')
    );
  }

  const consider = (candidate) => {
    if (!candidate?.command) return;
    const command = normalizeRememberedShellCommand(candidate.command);
    if (!command) return;
    if (isAiLaunchShellCommand(command)) return;
    const at = Number(candidate.at || candidate.lastCommandAt || 0);
    if (!best || at > best.at) {
      best = {
        tabId: candidate.tabId || null,
        projectId: candidate.projectId || null,
        cwd: candidate.cwd || cwd || null,
        command,
        at,
      };
    }
  };

  for (const [tabId, state] of terminalCommandState) {
    if (!state?.lastCommand) continue;
    const tabCwd = state.lastCommandCwd || terminalProjects.get(tabId) || null;
    if (cwd && tabCwd !== cwd) continue;
    const ownerProjectId = resolveProjectId(tabId);
    if (projectId && ownerProjectId !== projectId) continue;
    consider({
      tabId,
      projectId: ownerProjectId,
      cwd: tabCwd,
      command: state.lastCommand,
      at: state.lastCommandAt,
    });
  }

  try {
    const saved = projectManager?.db?.getAppState?.(LAST_COMMANDS_BY_CWD_KEY);
    if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
      if (cwd) {
        const row = saved[cwd];
        if (row && (!projectId || !row.projectId || row.projectId === projectId)) {
          consider(row);
        }
      } else {
        for (const row of Object.values(saved)) {
          if (projectId && row?.projectId && row.projectId !== projectId) continue;
          consider(row);
        }
      }
    }
  } catch (e) {
    console.warn('[LastCommand] read failed: ' + (e?.message || e));
  }

  return best
    ? { success: true, ...best }
    : { success: false, error: 'no-last-command' };
});

ipcMain.handle('terminal:get-command-run-history', async (event, request = {}) => {
  const tabId = typeof request?.tabId === 'string' && request.tabId ? request.tabId : null;
  const cwd = typeof request?.cwd === 'string' && request.cwd ? request.cwd : null;
  const projectId = typeof request?.projectId === 'string' && request.projectId ? request.projectId : null;
  const limit = Math.max(1, Math.min(50, Number(request?.limit || 20)));
  try {
    const saved = projectManager?.db?.getAppState?.(COMMAND_RUN_HISTORY_KEY);
    const map = saved && typeof saved === 'object' && !Array.isArray(saved) ? saved : {};
    let rows = tabId
      ? (Array.isArray(map[tabId]) ? map[tabId] : [])
      : Object.values(map).flatMap((items) => Array.isArray(items) ? items : []);
    rows = rows
      .filter((row) => row && typeof row.command === 'string' && row.command.trim())
      .filter((row) => !cwd || row.cwd === cwd)
      .filter((row) => !projectId || !row.projectId || row.projectId === projectId)
      .sort((a, b) => Number(b?.at || 0) - Number(a?.at || 0))
      .slice(0, limit)
      .map((row) => ({
        id: row.id || `${row.at || 0}:${row.tabId || ''}`,
        tabId: row.tabId || null,
        projectId: row.projectId || null,
        cwd: row.cwd || null,
        command: normalizeRememberedShellCommand(row.command) || row.command,
        source: row.source || 'shell',
        at: Number(row.at || 0),
      }));
    return { success: true, history: rows };
  } catch (e) {
    console.warn('[CommandRunHistory] read failed: ' + (e?.message || e));
    return { success: false, error: e?.message || String(e), history: [] };
  }
});

