// Get current working directory
ipcMain.handle('app:select-directory', async (event, request = {}) => {
  const { dialog } = require('electron');
  const requestedDefault = typeof request === 'string'
    ? request
    : request?.defaultPath;
  const defaultPath = normalizeDirectoryTarget(requestedDefault);
  const parent = BrowserWindow.fromWebContents(event.sender) || mainWindow || null;
  const options = {
    properties: ['openDirectory'],
    ...(defaultPath ? { defaultPath } : {}),
  };
  const result = parent
    ? await dialog.showOpenDialog(parent, options)
    : await dialog.showOpenDialog(options);
  if (result.canceled) return null;
  return result.filePaths[0];
});

ipcMain.handle('app:check-path-exists', (event, targetPath) => {
  const fs = require('fs');
  try {
    return fs.existsSync(targetPath) && fs.lstatSync(targetPath).isDirectory();
  } catch (err) {
    return false;
  }
});

function resolveNearestExistingDirectory(targetPath) {
  let raw = String(targetPath || '').trim();
  if (!raw) return null;
  if (raw === '~') raw = os.homedir();
  else if (raw.startsWith('~/')) raw = path.join(os.homedir(), raw.slice(2));

  let current = path.resolve(raw);
  while (current) {
    try {
      const stat = fs.statSync(current);
      if (stat.isDirectory()) return current;
      current = path.dirname(current);
      continue;
    } catch {}
    const parent = path.dirname(current);
    if (!parent || parent === current) break;
    current = parent;
  }
  return null;
}

ipcMain.handle('app:nearest-existing-directory', (_event, targetPath) => {
  const original = String(targetPath || '').trim();
  const resolved = resolveNearestExistingDirectory(original);
  return {
    originalPath: original,
    path: resolved,
    exact: !!resolved && path.resolve(original || resolved) === resolved,
  };
});

