let promptQueueAssetGcTimer = null;
async function garbageCollectPromptQueueAssets(queueState, reason = 'state-save') {
  try {
    const referenced = collectReferencedAssetIds(queueState);
    const composerDraftAssets = collectComposerDraftAssetIds(
      projectManager.db.getAppState('noted-terminal-history-composer-drafts'),
    );
    for (const assetId of composerDraftAssets) referenced.add(assetId);
    const historyPresentationAssets = projectManager.db.getHistoryPromptPresentationAssetIds?.() || [];
    for (const assetId of historyPresentationAssets) referenced.add(assetId);
    for (const assetId of promptQueueAssetSessionLeases) referenced.add(assetId);
    const result = await promptQueueAssetStore.garbageCollect(referenced);
    if (result.removed.length > 0) {
      console.log('[PromptQueueAssets] gc reason=' + reason
        + ' referenced=' + referenced.size + ' removed=' + result.removed.length);
    }
  } catch (error) {
    console.warn('[PromptQueueAssets] gc failed reason=' + reason + ':', error?.message || error);
  }
}

function schedulePromptQueueAssetGc(queueState, reason = 'state-save') {
  if (promptQueueAssetGcTimer) clearTimeout(promptQueueAssetGcTimer);
  promptQueueAssetGcTimer = setTimeout(() => {
    promptQueueAssetGcTimer = null;
    void garbageCollectPromptQueueAssets(queueState, reason);
  }, 1000);
}

ipcMain.handle('prompt-queue:materialize-image-refs', async (_event, { refs } = {}) => {
  try {
    const materialized = await promptQueueAssetStore.materializeRefs(refs);
    leasePromptQueueAssetRefs(materialized);
    const available = materialized.filter((ref) => ref.availability === 'available').length;
    return {
      success: available === materialized.length,
      refs: materialized,
      available,
      missing: materialized.length - available,
    };
  } catch (error) {
    console.warn('[PromptQueueAssets] materialize IPC failed:', error?.message || error);
    return { success: false, refs: [], available: 0, missing: Array.isArray(refs) ? refs.length : 0, error: error?.message || 'materialize_failed' };
  }
});

ipcMain.handle('prompt-queue:get-image-preview-data-url', async (_event, ref = {}) => {
  try {
    // Preview bytes are exposed only for files already owned by the durable
    // prompt-queue asset store.  In particular this must not become a generic
    // renderer primitive for reading arbitrary absolute paths.
    const managed = await promptQueueAssetStore.existingManagedRef(ref);
    if (!managed) {
      return { success: false, error: 'managed_image_missing' };
    }
    const source = nativeImage.createFromPath(managed.path);
    if (!source || source.isEmpty()) {
      return { success: false, assetId: managed.assetId, error: 'image_decode_failed' };
    }
    const variant = ref?.variant === 'detail' ? 'detail' : 'thumbnail';
    const maxSide = variant === 'detail' ? 1024 : 64;
    const size = source.getSize();
    const longestSide = Math.max(size.width, size.height);
    const scale = longestSide > maxSide ? maxSide / longestSide : 1;
    const preview = scale < 1
      ? source.resize({
          width: Math.max(1, Math.round(size.width * scale)),
          height: Math.max(1, Math.round(size.height * scale)),
          quality: 'best',
        })
      : source;
    const dataUrl = preview.toDataURL();
    if (!dataUrl.startsWith('data:image/')) {
      return { success: false, assetId: managed.assetId, error: 'preview_encode_failed' };
    }
    console.log('[PromptQueueAssets:Preview] ready asset=' + managed.assetId
      + ' variant=' + variant
      + ' source=' + size.width + 'x' + size.height
      + ' preview=' + preview.getSize().width + 'x' + preview.getSize().height);
    return {
      success: true,
      assetId: managed.assetId,
      variant,
      width: preview.getSize().width,
      height: preview.getSize().height,
      dataUrl,
    };
  } catch (error) {
    console.warn('[PromptQueueAssets:Preview] failed:', error?.message || error);
    return { success: false, error: error?.code || error?.message || 'preview_failed' };
  }
});

ipcMain.handle('prompt-queue:copy-image-to-clipboard', async (_event, ref = {}) => {
  try {
    // The renderer may request copy only for an attachment already owned by
    // the managed prompt asset store. Never turn this into a generic absolute
    // path clipboard primitive.
    const managed = await promptQueueAssetStore.existingManagedRef(ref);
    if (!managed) return { success: false, error: 'managed_image_missing' };
    const image = nativeImage.createFromPath(managed.path);
    if (!image || image.isEmpty()) {
      return { success: false, assetId: managed.assetId, error: 'image_decode_failed' };
    }
    clipboard.writeImage(image);
    return { success: true, assetId: managed.assetId };
  } catch (error) {
    console.warn('[PromptQueueAssets] clipboard image copy failed:', error?.message || error);
    return { success: false, error: error?.message || 'image_clipboard_copy_failed' };
  }
});

// Point-write for the Claude session id, mirroring the Codex path. Without it
// the only writer was a full `saveTabs` carrying a possibly stale tab array,
// which could roll another tab's freshly-detected id back to its previous
// value — the one data-loss risk found in the concurrency audit.
ipcMain.handle('claude:persist-session-id', (event, payload = {}) => {
  const tabId = String(payload?.tabId || '');
  const sessionId = payload?.sessionId ? String(payload.sessionId) : null;
  const expectedSessionId = payload?.expectedSessionId ? String(payload.expectedSessionId) : null;
  if (!tabId) return { success: false, error: 'tabId required' };
  const projectId = resolveAuthoritativeTabProjectId(tabId);
  if (!projectId) return { success: false, error: 'project_not_resolved' };
  try {
    const current = projectManager.db.getTabClaudeSessionId(projectId, tabId);
    if (current === undefined) return { success: false, error: 'claude_tab_row_missing' };
    if (current === sessionId) return { success: true, updated: false, currentSessionId: current };
    const updated = projectManager.db.compareAndSetTabClaudeSessionId(
      projectId,
      tabId,
      expectedSessionId ?? current ?? null,
      sessionId,
    );
    if (!updated) {
      const now = projectManager.db.getTabClaudeSessionId(projectId, tabId);
      console.warn('[Claude:Persist] compare-and-set conflict tab=' + tabId.slice(-12)
        + ' expected=' + (expectedSessionId ? expectedSessionId.slice(0, 8) : '-')
        + ' current=' + (now ? String(now).slice(0, 8) : 'none'));
      return { success: false, error: 'claude_session_compare_and_set_conflict', currentSessionId: now };
    }
    console.log('[Claude:Persist] point-write tab=' + tabId.slice(-12)
      + ' session=' + (sessionId ? sessionId.slice(0, 8) : 'none'));
    return { success: true, updated: true };
  } catch (error) {
    return { success: false, error: error?.message || String(error) };
  }
});

