// Codex session identity has a point-write ownership path. Renderer calls this
// before its generic workspace save so the latter can safely preserve the
// already-committed DB value instead of treating a cached snapshot as truth.
ipcMain.handle('codex:materialize-empty-session', async (_event, {
  projectId,
  tabId,
  cwd,
} = {}) => {
  if (!projectId || !tabId) {
    return { success: false, error: 'codex_empty_session_identity_required' };
  }
  return runKeyedExclusive(codexLaunchInflight, tabId, async () => (
    runKeyedExclusive(aiLifecycleActionInflight, tabId, async () => {
      const resolvedProjectId = resolveAuthoritativeTabProjectId(tabId, projectId);
      if (resolvedProjectId !== projectId) {
        return { success: false, error: 'codex_tab_project_mismatch' };
      }
      const commandState = await resolveTerminalCommandState({
        tabId,
        caller: 'codex-materialize-empty-session',
        expectedProcess: 'codex',
        allowProcessTreeLookup: true,
      });
      if (commandState?.processLookupUnknown) {
        return { success: false, error: 'codex_process_state_unknown' };
      }
      if (commandState?.isRunning) {
        return { success: false, error: 'codex_already_running' };
      }

      const currentSessionId = projectManager.db.getTabCodexSessionId(projectId, tabId);
      if (currentSessionId === undefined) {
        return { success: false, error: 'codex_tab_row_missing' };
      }
      const exactCwd = String(cwd || terminalProjects.get(tabId) || '').trim();
      if (!path.isAbsolute(exactCwd)) {
        return { success: false, error: 'codex_empty_session_cwd_required' };
      }
      if (currentSessionId) {
        const existing = await codexDataModule._api.findCodexSessionFile(
          currentSessionId,
          exactCwd,
        );
        if (!existing?.filePath) {
          return {
            success: false,
            error: 'codex_bound_session_file_missing',
            sessionId: currentSessionId,
          };
        }
        const loaded = await codexDataModule._api.loadSessionRecords(
          currentSessionId,
          exactCwd,
        );
        const materialization = loaded?.success
          ? codexDataModule._api.inspectConversationMaterialization(
            loaded.records,
            currentSessionId,
          )
          : null;
        return {
          success: true,
          created: false,
          sessionId: currentSessionId,
          filePath: existing.filePath,
          metadataOnly: materialization?.metadataOnly === true,
        };
      }

      const materialize = codexDataModule?._api?.materializeEmptySession;
      if (typeof materialize !== 'function') {
        return { success: false, error: 'codex_empty_session_api_unavailable' };
      }
      let created = null;
      try {
        created = await materialize({ cwd: exactCwd });
        const committed = projectManager.db.compareAndSetTabCodexSessionId(
          projectId,
          tabId,
          null,
          created.sessionId,
        );
        if (!committed) {
          await fs.promises.unlink(created.filePath).catch(() => null);
          codexDataModule._api.invalidateJsonlCache?.(created.filePath);
          return {
            success: false,
            error: 'codex_session_compare_and_set_conflict',
            currentSessionId: projectManager.db.getTabCodexSessionId(projectId, tabId),
          };
        }
        console.log('[CodexMaterialize] empty session created tab=' + String(tabId).slice(-12)
          + ' session=' + String(created.sessionId).slice(0, 8)
          + ' cwd=' + exactCwd);
        codexConversationMaterializationCache.set(created.sessionId, {
          materialized: false,
          metadataOnly: true,
          userRecords: 0,
          userTurns: 0,
          reason: 'session-meta-only',
        });
        return {
          success: true,
          created: true,
          sessionId: created.sessionId,
          filePath: created.filePath,
          metadataOnly: true,
        };
      } catch (error) {
        if (created?.filePath) {
          await fs.promises.unlink(created.filePath).catch(() => null);
          codexDataModule._api.invalidateJsonlCache?.(created.filePath);
        }
        return { success: false, error: error?.message || String(error) };
      }
    })
  ));
});

ipcMain.handle('tab:set-codex-session-id', async (_event, {
  projectId,
  tabId,
  sessionId,
  expectedSessionId = null,
  reason = 'unknown',
} = {}) => {
  if (!tabId) return { success: false, error: 'tab_id_required' };
  if (sessionId != null && typeof sessionId !== 'string') {
    return { success: false, error: 'invalid_codex_session_id' };
  }
  const historicalMutation = ['editRange', 'deleteRange', 'historyContext', 'api-edit-range', 'api-delete-range'].includes(reason);
  const unmaterializedDiscard = reason === 'discard-unmaterialized';
  if (!historicalMutation && !unmaterializedDiscard) {
    return { success: false, error: 'codex_session_identity_owned_by_main' };
  }
  if (!projectId) return { success: false, error: 'project_id_required' };

  // Historical edits and launch/resume share one lifecycle mutex. Otherwise a
  // slow "process absent" probe can finish after a new launch has started and
  // overwrite the binding that launch is about to materialize.
  return runKeyedExclusive(codexLaunchInflight, tabId, async () => {
    const resolvedProjectId = resolveAuthoritativeTabProjectId(tabId, projectId);
    if (resolvedProjectId !== projectId) {
      return { success: false, error: 'codex_tab_project_mismatch' };
    }
    const generationBefore = codexLastRunCommandPayload.get(tabId)?.launchId || null;
    const runtime = await getCodexRuntimeSessionSnapshot(tabId, {
      reason: 'codex-binding-point-write:' + reason,
      projectId,
      forceWriterReconcile: true,
    });
    const generationAfter = codexLastRunCommandPayload.get(tabId)?.launchId || null;
    if (generationAfter !== generationBefore) {
      return {
        success: false,
        error: 'codex_launch_generation_changed_during_historical_write',
      };
    }
    if (runtime.liveLifecycle !== false) {
      return {
        success: false,
        error: 'codex_historical_binding_requires_proven_stopped_runtime',
        liveLifecycle: runtime.liveLifecycle,
        sessionStatus: runtime.sessionStatus,
        writerStatus: runtime.writerStatus,
      };
    }
    try {
      const current = projectManager.db.getTabCodexSessionId(projectId, tabId);
      if (current === undefined) {
        return { success: false, error: 'codex_tab_row_missing' };
      }
      if ((expectedSessionId || null) !== (current || null)) {
        return {
          success: false,
          error: 'codex_session_compare_and_set_conflict',
          currentSessionId: current,
        };
      }
      let discardFilePath = null;
      if (unmaterializedDiscard && current) {
        const loaded = await codexDataModule._api.loadSessionRecords(
          current,
          terminalProjects.get(tabId),
        );
        const materialization = loaded?.success
          ? codexDataModule._api.inspectConversationMaterialization(
            loaded.records,
            current,
          )
          : null;
        if (materialization?.metadataOnly !== true) {
          return {
            success: false,
            error: 'codex_discard_requires_metadata_only_session',
          };
        }
        discardFilePath = loaded.filePath;
      }
      const updated = projectManager.db.compareAndSetTabCodexSessionId(
        projectId,
        tabId,
        expectedSessionId ?? null,
        sessionId ?? null,
      );
      if (!updated) {
        return {
          success: false,
          error: 'codex_session_compare_and_set_conflict',
          currentSessionId: projectManager.db.getTabCodexSessionId(projectId, tabId),
        };
      }
      if (discardFilePath) {
        await fs.promises.unlink(discardFilePath).catch((error) => {
          console.warn('[CodexMaterialize] orphan cleanup failed file=' + discardFilePath
            + ' error=' + (error?.message || String(error)));
        });
        codexDataModule._api.invalidateJsonlCache?.(discardFilePath);
        codexConversationMaterializationCache.delete(current);
      }
      return { success: true, updated: true };
    } catch (error) {
      console.warn('[Codex:Persist] point-write failed tab=' + String(tabId).slice(-12)
        + ' project=' + String(projectId).slice(-12)
        + ' session=' + (sessionId ? String(sessionId).slice(0, 8) : 'none')
        + ' error=' + (error?.message || String(error)));
      return { success: false, error: error?.message || String(error) };
    }
  });
});

ipcMain.handle('codex:reconcile-native-rewind-before-history-rewrite', async (_event, {
  tabId,
  sessionId,
} = {}) => {
  if (!tabId || !sessionId) {
    return { success: false, error: 'codex_history_rewrite_recovery_context_invalid' };
  }
  return runKeyedExclusive(codexLaunchInflight, tabId, async () => {
    const projectId = resolveAuthoritativeTabProjectId(tabId);
    if (!projectId) {
      return { success: false, error: 'codex_tab_project_unresolved' };
    }
    const boundBefore = projectManager.db.getTabCodexSessionId(projectId, tabId);
    if (boundBefore !== sessionId) {
      return {
        success: false,
        error: 'codex_history_rewrite_source_changed_before_recovery',
        currentSessionId: boundBefore || null,
      };
    }
    let pending = readPendingCodexNativeRewindHandoff(tabId);
    if (!pending) return { success: true, reconciled: false, sessionId };

    const recovery = await recoverPendingCodexNativeRewindHandoffs({
      noMutationRecoveryTabId: tabId,
    });
    pending = readPendingCodexNativeRewindHandoff(tabId);
    const boundAfter = projectManager.db.getTabCodexSessionId(projectId, tabId);
    if (!pending && boundAfter === sessionId) {
      console.log('[CodexWriterHandoff:HistoryRewrite] pending native Rewind reconciled before mutation tab='
        + String(tabId).slice(-12)
        + ' source=' + String(sessionId).slice(0, 8)
        + ' noMutation=' + Number(recovery?.noMutationCleared || 0)
        + ' stable=' + Number(recovery?.stableSourceRecovered || 0));
      return { success: true, reconciled: true, sessionId };
    }
    if (!pending && boundAfter !== sessionId) {
      return {
        success: false,
        error: 'codex_history_rewrite_source_changed_during_recovery',
        currentSessionId: boundAfter || null,
      };
    }
    return {
      success: false,
      error: 'codex_rewind_recovery_pending_before_history_rewrite',
      reason: pending?.invalid === true
        ? (pending.reason || pending.error || 'invalid-native-rewind-journal')
        : 'native-rewind-writer-handoff-unresolved',
      phase: pending?.phase || null,
      sourceSessionId: pending?.sourceSessionId || null,
      actionGeneration: pending?.actionGeneration || null,
    };
  });
});

ipcMain.handle('project:save-tabs', (event, { projectId, tabs, forceCleanup, expectedTabIds }) => {
  // During shutdown the renderer is still alive through the proxy-drain stall;
  // any save here would reinsert rows with was_interrupted=0 from the in-memory
  // tab and clobber before-quit's EARLY-MARK. preserveInterrupted=true makes
  // db.saveTabs never downgrade an on-disk 1 → 0. See fix-interrupted-session-lifecycle.md.
  const started = Date.now();
  const precondition = validateForceCleanupTabIds({
    forceCleanup,
    expectedTabIds,
    actualTabIds: projectManager.db.getProjectTabIds(projectId),
  });
  if (!precondition.ok) {
    console.warn('[SaveTabs] destructive precondition rejected project=' + String(projectId || '').slice(-12)
      + ' error=' + precondition.error
      + ' expected=' + (precondition.expectedTabIds?.length ?? 'missing')
      + ' actual=' + (precondition.actualTabIds?.length ?? 'unknown'));
    return { success: false, error: precondition.error };
  }
  const result = runSaveTabsWithAck(() => (
    projectManager.saveProjectTabs(projectId, tabs, forceCleanup, _gracefulShutdownInProgress)
  ));
  if (result.success === true && !_gracefulShutdownInProgress) {
    void tabWorkContext.syncLinks().catch((error) => console.warn('[TabContext] save sync:', error.message));
  }
  const durMs = Date.now() - started;
  if (durMs > 50 || forceCleanup) {
    console.log('[SaveTabs:Perf] project=' + String(projectId).slice(-12) +
      ' tabs=' + (Array.isArray(tabs) ? tabs.length : 'unknown') +
      ' forceCleanup=' + !!forceCleanup +
      ' shutdown=' + !!_gracefulShutdownInProgress +
      ' durMs=' + durMs);
  }
  if (result.success !== true) {
    console.warn('[SaveTabs] not committed project=' + String(projectId || '').slice(-12) +
      ' error=' + result.error +
      ' durMs=' + durMs);
  }
  return result;
});

