// Point-wise context% persistence for the control-bar meter. Cheap single-column
// UPDATE, no full-reinsert — the renderer throttles to whole-percent changes so
// this fires a few dozen times a session, not on every bridge tick. Persisted so
// the meter shows the last-known fill even when no Claude process is running.
ipcMain.handle('tab:persist-context-pct', (event, { tabId, pct }) => {
  try { projectManager?.db?.updateTabContextPct?.(tabId, pct); } catch {}
  return { success: true };
});

// Seed value for the meter on control-bar mount — survives CLI exit / restart.
// `requireExact` is the stricter automation path: it refuses SQLite last-known
// data and returns only a main-owned snapshot for the requested provider/session.
ipcMain.handle('tab:get-context-pct', async (event, {
  tabId,
  provider = null,
  sessionId = null,
  requireExact = false,
} = {}) => {
  try {
    const row = projectManager?.db?.db?.prepare(
      'SELECT claude_session_id, codex_session_id, command_type, cwd FROM tabs WHERE tab_id = ? LIMIT 1'
    ).get(tabId) || null;
    if (row?.codex_session_id) {
      await codexSessionContextObserver?.ensure(row.codex_session_id, row.cwd || null);
    }
    if (requireExact === true) {
      const requestedProvider = provider === 'codex' ? 'codex' : provider === 'claude' ? 'claude' : null;
      const requestedSessionId = typeof sessionId === 'string' ? sessionId.trim() : '';
      if (!requestedProvider || !requestedSessionId) {
        return { pct: null, exact: false, reason: 'provider-session-required' };
      }
      const boundSessionId = requestedProvider === 'codex'
        ? String(row?.codex_session_id || '')
        : String(bridgeKnownSessions.get(tabId) || row?.claude_session_id || '');
      if (!boundSessionId || boundSessionId !== requestedSessionId) {
        return {
          pct: null,
          exact: false,
          provider: requestedProvider,
          sessionId: requestedSessionId,
          reason: 'session-binding-mismatch',
        };
      }
      const snapshot = agentContextUsageState.read(tabId, {
        provider: requestedProvider,
        sessionId: requestedSessionId,
      });
      if (!snapshot) {
        return {
          pct: null,
          exact: false,
          provider: requestedProvider,
          sessionId: requestedSessionId,
          reason: 'exact-context-unavailable',
        };
      }
      return {
        pct: snapshot.contextPct,
        exact: true,
        provider: snapshot.provider,
        sessionId: snapshot.sessionId,
        observedAt: snapshot.observedAt,
      };
    }
    return { pct: projectManager?.db?.getTabContextPct?.(tabId) ?? null };
  } catch {
    return { pct: null, exact: false, reason: 'context-read-failed' };
  }
});

// Point-wise cache-stats persistence for the control-bar cooldown chip. One write
// per turn (message_start). stats = {cacheRead,cacheCreate,input,ts}. Persisted so
// the chip survives tab switches AND restart — the chip's countdown is anchored on
// ts (wall-clock), so a stored value stays accurate. Mirrors tab:persist-context-pct.
ipcMain.handle('tab:persist-cache-stats', (event, { tabId, stats }) => {
  try { projectManager?.db?.updateTabCacheStats?.(tabId, stats); } catch {}
  return { success: true };
});

// Seed value for the cooldown chip on control-bar mount.
ipcMain.handle('tab:get-cache-stats', (event, { tabId }) => {
  try { return { stats: projectManager?.db?.getTabCacheStats?.(tabId) ?? null }; }
  catch { return { stats: null }; }
});

// Synchronous version for beforeunload (pkill-safe)
ipcMain.on('project:save-tabs-sync', (event, { projectId, tabs, forceCleanup, expectedTabIds }) => {
  const started = Date.now();
  const precondition = validateForceCleanupTabIds({
    forceCleanup,
    expectedTabIds,
    actualTabIds: projectManager.db.getProjectTabIds(projectId),
  });
  if (!precondition.ok) {
    event.returnValue = { success: false, error: precondition.error };
    return;
  }
  const result = runSaveTabsWithAck(() => (
    projectManager.saveProjectTabs(projectId, tabs, forceCleanup, _gracefulShutdownInProgress)
  ));
  const durMs = Date.now() - started;
  if (durMs > 50 || forceCleanup) {
    console.log('[SaveTabs:Perf] sync project=' + String(projectId).slice(-12) +
      ' tabs=' + (Array.isArray(tabs) ? tabs.length : 'unknown') +
      ' forceCleanup=' + !!forceCleanup +
      ' shutdown=' + !!_gracefulShutdownInProgress +
      ' durMs=' + durMs);
  }
  if (result.success !== true) {
    console.warn('[SaveTabs] sync not committed project=' + String(projectId || '').slice(-12) +
      ' error=' + result.error +
      ' durMs=' + durMs);
  }
  event.returnValue = result;
});

// Cross-project DnD changes three representations of one identity: the scoped
// SQLite row, main's live PTY owner, and renderer Zustand. Commit the first two
// synchronously and acknowledge only then; renderer applies its local move
// after this returns, so no writer reconciliation can target a missing row in
// the destination project.
ipcMain.on('terminal:transfer-project-ownership-sync', (event, {
  sourceProjectId,
  targetProjectId,
  tabIds,
} = {}) => {
  const result = commitTabProjectTransfer({
    terminals,
    terminalProjectIds,
    tabIds,
    sourceProjectId,
    targetProjectId,
    transferRows: ({ sourceProjectId: source, targetProjectId: target, tabIds: ids }) => (
      projectManager.transferProjectTabs(source, target, ids)
    ),
  });
  if (result.success !== true) {
    console.warn('[TabProjectTransfer] rejected source=' + String(sourceProjectId || '').slice(-12)
      + ' target=' + String(targetProjectId || '').slice(-12)
      + ' tabs=' + (Array.isArray(tabIds) ? tabIds.length : 0)
      + ' error=' + (result.error || 'unknown'));
  } else {
    for (const transferredTabId of result.transferred || []) {
      revokeCodexActionAuthoritiesForTab(transferredTabId, 'project-owner-moved');
    }
    console.log('[TabProjectTransfer] committed source=' + String(sourceProjectId).slice(-12)
      + ' target=' + String(targetProjectId).slice(-12)
      + ' tabs=' + result.transferred.length
      + ' live=' + result.liveTabIds.length);
  }
  event.returnValue = result;
});

ipcMain.on('terminal:transfer-tab-group-ownership-sync', (event, {
  sourceProjectId,
  targetProjectId,
  groupId,
  targetGroupId,
  tabIds,
} = {}) => {
  const result = commitTabGroupProjectTransfer({
    terminals,
    terminalProjectIds,
    tabIds,
    sourceProjectId,
    targetProjectId,
    groupId,
    targetGroupId,
    transferRows: ({
      sourceProjectId: source,
      targetProjectId: target,
      groupId: sourceGroup,
      targetGroupId: nextGroup,
      tabIds: expectedIds,
    }) => projectManager.transferProjectTabGroup(
      source,
      target,
      sourceGroup,
      nextGroup,
      expectedIds
    ),
  });
  if (result.success !== true) {
    console.warn('[TabGroupProjectTransfer] rejected source=' + String(sourceProjectId || '').slice(-12)
      + ' target=' + String(targetProjectId || '').slice(-12)
      + ' group=' + String(groupId || '').slice(-12)
      + ' tabs=' + (Array.isArray(tabIds) ? tabIds.length : 0)
      + ' error=' + (result.error || 'unknown'));
  } else {
    for (const transferredTabId of result.transferred || []) {
      revokeCodexActionAuthoritiesForTab(transferredTabId, 'project-group-owner-moved');
    }
    console.log('[TabGroupProjectTransfer] committed source=' + String(sourceProjectId).slice(-12)
      + ' target=' + String(targetProjectId).slice(-12)
      + ' group=' + String(groupId).slice(-12)
      + ' nextGroup=' + String(targetGroupId).slice(-12)
      + ' tabs=' + result.transferred.length
      + ' live=' + result.liveTabIds.length);
  }
  event.returnValue = result;
});

ipcMain.on('tab-notification:play-sound', () => {
  try {
    if (process.platform === 'darwin') {
      const soundPath = '/System/Library/Sounds/Glass.aiff';
      if (fs.existsSync(soundPath)) {
        const child = spawn('afplay', [soundPath], {
          stdio: 'ignore',
          detached: true,
          env: buildChildProcessEnv(),
        });
        child.unref();
        return;
      }
    }
    process.stdout.write('\x07');
  } catch (e) {
    console.warn('[TabNotification] sound failed: ' + (e?.message || e));
  }
});

ipcMain.on('tab-notification:completed', (_event, detail = {}) => {
  let envelope;
  try {
    envelope = buildTerminalCompletionEnvelope(detail);
  } catch (error) {
    console.warn('[TabNotification:SC] ignored invalid completion: ' + (error?.message || error));
    return;
  }

  void scDesktopNotificationOutbox.enqueue(envelope).then((result) => {
    if (!result.ok) {
      console.warn('[TabNotification:SC] outbox rejected eventId=' + envelope.eventId
        + ' reason=' + result.reason);
      return;
    }
    console.log('[TabNotification:SC] outbox accepted eventId=' + envelope.eventId
      + ' queued=' + (result.queued === true)
      + ' duplicate=' + (result.duplicate === true)
      + ' durable=' + (result.durable !== false));
  }).catch((error) => {
    console.warn('[TabNotification:SC] outbox enqueue failed eventId=' + envelope.eventId
      + ' error=' + (error?.message || error));
  });
});

ipcMain.on('tab-notification:fired', (_event, detail = {}) => {
  try {
    const tabId = String(detail.tabId || '');
    const projectId = String(detail.projectId || '');
    if (!tabId || !projectId) return;
    const firedAt = Number(detail.firedAt) || Date.now();
    const normalizedDetail = {
      ...detail,
      projectId,
      tabId,
      tabName: String(detail.tabName || 'Terminal'),
      firedAt,
      persistent: detail.persistent === true,
    };
    tabCompletionNotifications.set(tabId, {
      projectId,
      tabName: normalizedDetail.tabName,
      firedAt,
      persistent: normalizedDetail.persistent,
    });
    scheduleProjectActivityBroadcast('tab-notification');
    try {
      require(path.join(srcMainDir, 'web-server')).sendTabCompletionPush?.(normalizedDetail).catch((e) => {
        console.warn('[TabNotification] APNs push failed: ' + (e?.message || e));
      });
    } catch (e) {
      console.warn('[TabNotification] APNs push unavailable: ' + (e?.message || e));
    }
  } catch (e) {
    console.warn('[TabNotification] fired sync failed: ' + (e?.message || e));
  }
});

ipcMain.on('tab-notification:cleared', (_event, detail = {}) => {
  try {
    const tabId = String(detail.tabId || '');
    if (!tabId) return;
    if (tabCompletionNotifications.delete(tabId)) {
      scheduleProjectActivityBroadcast('tab-notification-clear');
    }
  } catch (e) {
    console.warn('[TabNotification] clear sync failed: ' + (e?.message || e));
  }
});

