// ========== TAB HISTORY ==========

const ARCHIVE_MESSAGE_COUNT_DELAY_MS = 1000;
const ARCHIVE_MESSAGE_COUNT_MAX_BYTES = 256 * 1024 * 1024;
const ARCHIVE_AUTO_INDEX_DELAY_MS = 5000;
const ARCHIVE_AUTO_INDEX_MAX_BYTES = 5 * 1024 * 1024;
const ARCHIVE_HOME_INDEX_DELAY_MS = 1500;
const APP_STATE_KEY_SEMANTIC_AUTO_TITLES = 'semanticAutoIndexTitles';
const APP_STATE_KEY_SEMANTIC_AUTO_TITLES_SINCE = 'semanticAutoIndexTitlesSince';
const APP_STATE_KEY_SEMANTIC_AUTO_ITERATIONS = 'semanticAutoIndexIterations';
const APP_STATE_KEY_SEMANTIC_AUTO_ITERATIONS_SINCE = 'semanticAutoIndexIterationsSince';
const HISTORY_COUNT_BACKFILL_LIMIT = 8;
const historyCountBackfillInFlight = new Set();
const archiveHomeIndexInFlight = new Set();

function readAppBoolState(key) {
  try {
    const value = projectManager?.db?.getAppState?.(key);
    return value === true || value === 1 || value === '1' || value === 'true';
  } catch {
    return false;
  }
}

function readAppNumberState(key) {
  try {
    const value = Number(projectManager?.db?.getAppState?.(key) || 0);
    return Number.isFinite(value) ? value : 0;
  } catch {
    return 0;
  }
}

function formatBytesShort(bytes) {
  if (!Number.isFinite(bytes)) return 'unknown';
  if (bytes < 1024) return bytes + 'B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + 'KB';
  return (bytes / (1024 * 1024)).toFixed(1) + 'MB';
}

function isCountableUserEntry(entry) {
  if (!entry || entry.type !== 'user') return false;
  let rawContent = entry.message?.content;
  if (Array.isArray(rawContent)) {
    if (rawContent.some(item => item?.type === 'tool_result')) return false;
    const textBlock = rawContent.find(item => item?.type === 'text' && item.text);
    rawContent = textBlock?.text || null;
  }
  if (!rawContent || typeof rawContent !== 'string') return false;
  if (entry.isMeta) return false;
  if (rawContent.includes('<command-name>') ||
      rawContent.includes('<system-reminder>') ||
      rawContent.includes('<task-notification>') ||
      rawContent.startsWith('[Request interrupted')) return false;
  return true;
}

async function countUserMessagesStreaming(filePath) {
  let count = 0;
  const input = fs.createReadStream(filePath, { encoding: 'utf8' });
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  try {
    for await (const line of rl) {
      const text = line.trim();
      if (!text) continue;
      if (!text.includes('"type":"user"') && !text.includes('"type": "user"')) continue;
      try {
        const entry = JSON.parse(text);
        if (isCountableUserEntry(entry)) count++;
      } catch {}
    }
  } finally {
    input.destroy();
  }
  return count;
}

function updateTabHistoryMessageCount(historyId, count, label, started) {
  try {
    projectManager.db.db
      .prepare('UPDATE tab_history SET message_count = ? WHERE id = ?')
      .run(count, historyId);
  } catch (e) {
    console.warn('[Archive:Count] DB update failed ' + label + ': ' + e.message);
    return;
  }
  console.log('[Archive:Count] ' + label +
    ' count=' + count +
    ' durMs=' + (Date.now() - started));
  try {
    mainWindow?.webContents?.send('tab-history:message-count-updated', {
      id: historyId,
      message_count: count,
    });
  } catch {}
}

function scheduleCodexArchiveCount(tab, historyId) {
  const sessionId = tab?.codexSessionId || null;
  const cwd = tab?.cwd || null;
  if (!sessionId || !cwd || !historyId) return;

  setTimeout(async () => {
    const started = Date.now();
    const label = 'codex sid=' + sessionId.slice(0, 8);
    try {
      const found = await codexDataModule.findCodexSessionFile(sessionId, cwd);
      if (!found?.filePath) {
        console.log('[Archive:Count] Codex session file not found sid=' + sessionId.slice(0, 8) + ' cwd=' + cwd);
        return;
      }
      let stat = null;
      try { stat = fs.statSync(found.filePath); } catch {}
      const size = stat?.size || 0;
      if (size > ARCHIVE_MESSAGE_COUNT_MAX_BYTES) {
        console.log('[Archive:Count] skipped codex sid=' + sessionId.slice(0, 8) +
          ' size=' + formatBytesShort(size) +
          ' max=' + formatBytesShort(ARCHIVE_MESSAGE_COUNT_MAX_BYTES));
        return;
      }

      const loaded = await codexDataModule._api.loadSessionRecords(sessionId, cwd);
      if (!loaded?.success) {
        console.log('[Archive:Count] Codex load failed sid=' + sessionId.slice(0, 8) +
          ' error=' + (loaded?.error || 'unknown'));
        return;
      }
      const timeline = codexDataModule.buildCodexTimeline(loaded.records || [], sessionId);
      const count = Array.isArray(timeline)
        ? timeline.filter((entry) => entry?.type === 'user').length
        : 0;
      updateTabHistoryMessageCount(historyId, count, label + ' size=' + formatBytesShort(size), started);
    } catch (e) {
      console.warn('[Archive:Count] failed ' + label + ': ' + (e?.message || String(e)));
    }
  }, ARCHIVE_MESSAGE_COUNT_DELAY_MS);
}

function scheduleHistoryMessageCountBackfill(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return;
  const candidates = rows
    .filter((row) => row && row.id && row.message_count == null && (row.claude_session_id || row.codex_session_id) && row.cwd)
    .slice(0, HISTORY_COUNT_BACKFILL_LIMIT);
  if (candidates.length === 0) return;

  candidates.forEach((row, index) => {
    const key = String(row.id);
    if (historyCountBackfillInFlight.has(key)) return;
    historyCountBackfillInFlight.add(key);
    setTimeout(async () => {
      const started = Date.now();
      try {
        if (row.codex_session_id) {
          const sessionId = row.codex_session_id;
          const found = await codexDataModule.findCodexSessionFile(sessionId, row.cwd);
          if (!found?.filePath) return;
          let stat = null;
          try { stat = fs.statSync(found.filePath); } catch {}
          const size = stat?.size || 0;
          if (size > ARCHIVE_MESSAGE_COUNT_MAX_BYTES) return;
          const loaded = await codexDataModule._api.loadSessionRecords(sessionId, row.cwd);
          if (!loaded?.success) return;
          const timeline = codexDataModule.buildCodexTimeline(loaded.records || [], sessionId);
          const count = Array.isArray(timeline)
            ? timeline.filter((entry) => entry?.type === 'user').length
            : 0;
          updateTabHistoryMessageCount(row.id, count, 'backfill codex sid=' + sessionId.slice(0, 8) + ' size=' + formatBytesShort(size), started);
          return;
        }

        const sessionId = row.claude_session_id;
        const found = findSessionFile(sessionId, row.cwd);
        if (!found?.filePath) return;
        let stat = null;
        try { stat = fs.statSync(found.filePath); } catch {}
        const size = stat?.size || 0;
        if (size > ARCHIVE_MESSAGE_COUNT_MAX_BYTES) return;
        const count = await countUserMessagesStreaming(found.filePath);
        updateTabHistoryMessageCount(row.id, count, 'backfill sid=' + sessionId.slice(0, 8) + ' size=' + formatBytesShort(size), started);
      } catch (e) {
        console.warn('[Archive:Count] backfill failed historyId=' + row.id + ': ' + (e?.message || String(e)));
      } finally {
        historyCountBackfillInFlight.delete(key);
      }
    }, ARCHIVE_MESSAGE_COUNT_DELAY_MS + index * 150);
  });
}

function shouldAutoIndexArchivedHistory(enabledKey, sinceKey, closedAt) {
  if (!readAppBoolState(enabledKey)) return false;
  const since = readAppNumberState(sinceKey);
  return !since || closedAt >= since;
}

function scheduleArchiveHomeIndexSideEffects(projectId, tab, historyId) {
  if (!projectId || !historyId) return;
  const closedAt = Math.floor(Date.now() / 1000);
  const titleEnabled = shouldAutoIndexArchivedHistory(
    APP_STATE_KEY_SEMANTIC_AUTO_TITLES,
    APP_STATE_KEY_SEMANTIC_AUTO_TITLES_SINCE,
    closedAt
  );
  const iterationSince = readAppNumberState(APP_STATE_KEY_SEMANTIC_AUTO_ITERATIONS_SINCE);
  const iterationEnabled = shouldAutoIndexArchivedHistory(
    APP_STATE_KEY_SEMANTIC_AUTO_ITERATIONS,
    APP_STATE_KEY_SEMANTIC_AUTO_ITERATIONS_SINCE,
    closedAt
  );
  if (!titleEnabled && !iterationEnabled) return;

  const key = `${projectId}:${historyId}`;
  if (archiveHomeIndexInFlight.has(key)) return;
  archiveHomeIndexInFlight.add(key);

  setTimeout(async () => {
    const started = Date.now();
    try {
      const semanticSearch = require(path.join(srcMainDir, 'ipc', 'semantic-search'));
      if (titleEnabled) {
        const result = await semanticSearch.autoIndexTabTitle?.(projectManager, projectManager.db.db, projectId, historyId);
        console.log('[ProjectHome:AutoTitleIndex] historyId=' + historyId +
          ' indexed=' + (result?.indexed || 0) +
          ' skipped=' + (result?.skipped || 0) +
          ' failed=' + (result?.failed || 0) +
          ' durMs=' + (Date.now() - started));
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('tab-title-index:changed', { projectId, historyId, reason: 'auto-archive' });
        }
      }

      if (iterationEnabled && tab?.cwd && (tab?.claudeSessionId || tab?.codexSessionId)) {
        const result = await semanticSearch.autoIndexTabIterations?.(
          projectManager,
          projectManager.db.db,
          projectId,
          historyId,
          require(path.join(srcMainDir, 'ipc', 'claude-data')),
          codexDataModule,
          { minEntryTs: iterationSince || 0 }
        );
        console.log('[ProjectHome:AutoIterationIndex] historyId=' + historyId +
          ' parsed=' + (result?.parsedRows || 0) +
          ' indexed=' + (result?.indexed || 0) +
          ' skipped=' + (result?.skipped || 0) +
          ' failed=' + (result?.failed || 0) +
          ' minEntryTs=' + (iterationSince || 0) +
          ' durMs=' + (Date.now() - started));
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('tab-iteration-index:changed', { projectId, historyId, reason: 'auto-archive' });
        }
      }
    } catch (e) {
      console.warn('[ProjectHome:AutoIndex] failed historyId=' + historyId + ': ' + (e?.message || String(e)));
    } finally {
      archiveHomeIndexInFlight.delete(key);
    }
  }, ARCHIVE_HOME_INDEX_DELAY_MS);
}

function scheduleArchiveSideEffects(projectId, tab, historyId) {
  const sessionId = tab?.claudeSessionId || null;
  const cwd = tab?.cwd || null;
  scheduleArchiveHomeIndexSideEffects(projectId, tab, historyId);
  if (!cwd || !historyId) return;

  if (!sessionId) {
    scheduleCodexArchiveCount(tab, historyId);
    return;
  }

  const found = findSessionFile(sessionId, cwd);
  if (!found?.filePath) {
    console.log('[Archive:Close] session file not found sid=' + sessionId.slice(0, 8) + ' cwd=' + cwd);
    return;
  }

  let stat = null;
  try { stat = fs.statSync(found.filePath); } catch {}
  const size = stat?.size || 0;
  const projectSlug = path.basename(path.dirname(found.filePath));
  console.log('[Archive:Close] queued side-effects historyId=' + historyId +
    ' sid=' + sessionId.slice(0, 8) +
    ' size=' + formatBytesShort(size) +
    ' countDelayMs=' + ARCHIVE_MESSAGE_COUNT_DELAY_MS +
    ' autoIndexMax=' + formatBytesShort(ARCHIVE_AUTO_INDEX_MAX_BYTES));

  if (size > ARCHIVE_MESSAGE_COUNT_MAX_BYTES) {
    console.log('[Archive:Count] skipped sid=' + sessionId.slice(0, 8) +
      ' size=' + formatBytesShort(size) +
      ' max=' + formatBytesShort(ARCHIVE_MESSAGE_COUNT_MAX_BYTES));
  } else {
    setTimeout(() => {
      const started = Date.now();
      countUserMessagesStreaming(found.filePath)
        .then((count) => {
          updateTabHistoryMessageCount(historyId, count, 'sid=' + sessionId.slice(0, 8) + ' size=' + formatBytesShort(size), started);
        })
        .catch((e) => console.warn('[Archive:Count] failed sid=' + sessionId.slice(0, 8) + ': ' + e.message));
    }, ARCHIVE_MESSAGE_COUNT_DELAY_MS);
  }

  if (size > ARCHIVE_AUTO_INDEX_MAX_BYTES) {
    console.log('[SemanticSearch:AutoIndex] skipped on close sid=' + sessionId.slice(0, 8) +
      ' size=' + formatBytesShort(size) +
      ' max=' + formatBytesShort(ARCHIVE_AUTO_INDEX_MAX_BYTES) +
      ' reason=avoid-close-freeze');
    return;
  }

  setTimeout(() => {
    const started = Date.now();
    try {
      const semanticSearch = require(path.join(srcMainDir, 'ipc', 'semantic-search'));
      semanticSearch.indexSessionFile?.(projectManager.db.db, found.filePath, sessionId, projectSlug)
        ?.then(r => console.log('[SemanticSearch:AutoIndex] sid=' + sessionId.slice(0, 8) +
          ' chunks=' + r.chunked +
          ' skipped=' + !!r.skipped +
          ' durMs=' + (Date.now() - started)))
        ?.catch(e => console.error('[SemanticSearch:AutoIndex] failed sid=' + sessionId.slice(0, 8) + ': ' + e.message));
    } catch (e) {
      console.error('[SemanticSearch:AutoIndex] setup failed sid=' + sessionId.slice(0, 8) + ': ' + e.message);
    }
  }, ARCHIVE_AUTO_INDEX_DELAY_MS);
}

function getCodexArchiveGeneration(tabId) {
  const terminal = terminals.get(tabId) || null;
  const commandState = terminalCommandState.get(tabId) || null;
  const launch = codexLastRunCommandPayload.get(tabId) || null;
  return [
    terminal?.pid || 'no-pty',
    Number(commandState?.runSeq || 0),
    commandState?.isRunning === true ? 'running' : 'idle',
    launch?.launchId || 'no-launch',
    terminalProjectIds.get(tabId) || 'no-project',
  ].join(':');
}

function commitTabArchive(projectId, tab, {
  sourceTabId = null,
  codexWriterSessionId = null,
} = {}) {
  const started = Date.now();
  const tabType = tab?.tabType || tab?.tab_type || 'terminal';
  if (tabType === 'file') {
    console.log('[Archive:Close] skipped file tab project=' + String(projectId).slice(-12) +
      ' tabName=' + JSON.stringify(tab?.name || '') +
      ' durMs=' + (Date.now() - started));
    return { success: true, skipped: true, historyId: null };
  }
  const historyId = projectManager.db.archiveTab(projectId, tab, {
    sourceTabId,
    codexWriterSessionId,
  });
  if (historyId === null || historyId === undefined) {
    return { success: false, error: 'archive_not_committed', historyId: null };
  }
  const durMs = Date.now() - started;
  const sessionId = tab?.claudeSessionId || tab?.geminiSessionId || tab?.codexSessionId || null;
  console.log('[Archive:Close] archived historyId=' + historyId +
    ' project=' + String(projectId).slice(-12) +
    ' tabName=' + JSON.stringify(tab?.name || '') +
    ' cmd=' + (tab?.commandType || 'none') +
    ' sid=' + (sessionId ? sessionId.slice(0, 8) : 'none') +
    ' processWasRunning=' + !!tab?.processWasRunning +
    ' durMs=' + durMs);
  // Search/count indexing is secondary to the durable History insert. A
  // side-effect setup failure must not turn a committed archive into a false
  // negative response and make renderer keep/retry the same live tab.
  try {
    scheduleArchiveSideEffects(projectId, tab, historyId);
  } catch (error) {
    console.warn('[Archive:Close] post-commit side-effects failed historyId=' + historyId +
      ' error=' + (error?.message || String(error)));
  }
  return {
    success: true,
    historyId,
    codexSessionId: tab?.codexSessionId || null,
    processWasRunning: !!tab?.processWasRunning,
  };
}

ipcMain.handle('project:archive-tab', async (event, { projectId, tab }) => {
  const sourceTabId = tab?.tabId || null;
  const resolvedToolType = sourceTabId
    ? resolveAiToolTypeForTab(sourceTabId, null)
    : null;
  if (!resolvedToolType && (tab?.claudeSessionId || tab?.codexSessionId)) {
    return { success: false, error: 'archive_provider_owner_unknown', historyId: null };
  }
  const resolvedArchiveTab = resolvedToolType
    ? { ...tab, commandType: resolvedToolType }
    : tab;
  if (resolvedToolType !== 'codex') {
    return commitTabArchive(projectId, resolvedArchiveTab);
  }

  if (!sourceTabId || !projectId) {
    return { success: false, error: 'codex_archive_identity_required', historyId: null };
  }

  return runKeyedExclusive(codexLaunchInflight, sourceTabId, async () => {
    let rowState;
    try {
      const sessionId = projectManager.db.getTabCodexSessionId(projectId, sourceTabId);
      rowState = sessionId === undefined
        ? { status: 'missing' }
        : { status: 'found', sessionId };
    } catch (error) {
      rowState = { status: 'error', error: error?.message || String(error) };
    }

    const generationBefore = getCodexArchiveGeneration(sourceTabId);
    let runtime;
    try {
      runtime = await getCodexRuntimeSessionSnapshot(sourceTabId, {
        reason: 'archive-close',
        projectId,
        refreshTuiReady: true,
        forceWriterReconcile: true,
      });
    } catch (error) {
      runtime = {
        projectId,
        liveLifecycle: null,
        provenWriterSessionId: null,
        writerError: error?.message || String(error),
      };
    }
    const generationAfter = getCodexArchiveGeneration(sourceTabId);
    const snapshot = finalizeCodexArchiveSnapshot({
      projectId,
      rowState,
      runtime,
      generationBefore,
      generationAfter,
    });
    if (snapshot.success !== true) {
      console.warn('[Archive:Close] Codex snapshot rejected tab=' + String(sourceTabId).slice(-12)
        + ' project=' + String(projectId).slice(-12)
        + ' error=' + snapshot.error
        + ' row=' + rowState.status
        + ' live=' + String(runtime?.liveLifecycle)
        + ' writer=' + (runtime?.provenWriterSessionId ? String(runtime.provenWriterSessionId).slice(0, 8) : 'none')
        + ' generationBefore=' + generationBefore
        + ' generationAfter=' + generationAfter);
      return { success: false, error: snapshot.error, historyId: null };
    }
    if (snapshot.processWasRunning && !tab?.processWasRunning) {
      // The renderer made its confirmation decision from an earlier read. Do
      // not commit History and then kill a process the user was never asked
      // about; keep the tab intact so the next close attempt re-reads state and
      // shows the normal running-process confirmation.
      return {
        success: false,
        error: 'codex_process_state_changed_retry_close',
        historyId: null,
      };
    }

    const archiveTab = {
      ...resolvedArchiveTab,
      codexSessionId: snapshot.codexSessionId,
      // Renderer checks are useful for confirmation UX, but the durable close
      // record must not combine that earlier read with a later writer proof.
      processWasRunning: snapshot.processWasRunning,
    };
    if ((tab?.codexSessionId || null) !== snapshot.codexSessionId
      || !!tab?.processWasRunning !== snapshot.processWasRunning) {
      console.warn('[Archive:Close] replaced renderer Codex snapshot tab=' + String(sourceTabId).slice(-12)
        + ' rendererSession=' + String(tab?.codexSessionId || 'none').slice(0, 8)
        + ' archiveSession=' + String(snapshot.codexSessionId || 'none').slice(0, 8)
        + ' rendererRunning=' + !!tab?.processWasRunning
        + ' archiveRunning=' + snapshot.processWasRunning
        + ' source=' + snapshot.source);
    }
    return commitTabArchive(projectId, archiveTab, {
      sourceTabId,
      codexWriterSessionId: snapshot.source === 'writer-proof' ? snapshot.codexSessionId : null,
    });
  });
});

