// ========== SYSTEM: ELECTRON DEV APP PROCESSES ==========
function parseLongPsLine(line) {
  const match = String(line || '').trim().match(/^(\d+)\s+(\d+)\s+([\d.]+)\s+([\d.]+)\s+(\w+\s+\w+\s+\d+\s+(\d+:\d+:\d+)\s+\d+)\s+(.+)$/);
  if (!match) return null;
  return {
    pid: Number(match[1]),
    ppid: Number(match[2]),
    cpu: match[3],
    mem: match[4],
    startTime: match[6].substring(0, 5),
    command: match[7].trim(),
  };
}

function isElectronDevAppCommand(command) {
  const cmd = String(command || '');
  if (!cmd.includes('/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron')) return false;
  if (cmd.includes(' --type=')) return false;
  if (cmd.includes('/mcp/') || cmd.includes('mcp-server') || cmd.includes('terminal-server.mjs')) return false;
  return true;
}

function isElectronLauncherCommand(command) {
  const cmd = String(command || '');
  return /(^|\s)node\s+.*\/node_modules\/\.bin\/electron(\s|$)/.test(cmd);
}

async function getPidCwd(pid) {
  try {
    const out = await execAsync('lsof -a -p ' + Number(pid) + ' -d cwd -Fn', 1500);
    const line = (out || '').split('\n').find(l => l.startsWith('n'));
    return line ? line.slice(1) : '';
  } catch {
    return '';
  }
}

const DASHBOARD_PID_CWD_TTL_MS = 15000;
const dashboardPidCwdCache = new Map();

async function getDashboardPidCwd(pid) {
  const safePid = Number(pid);
  if (!Number.isInteger(safePid) || safePid <= 1) return '';

  const now = Date.now();
  const cached = dashboardPidCwdCache.get(safePid);
  if (cached && now - cached.createdAt < DASHBOARD_PID_CWD_TTL_MS) {
    return cached.cwd;
  }

  const cwd = await getPidCwd(safePid);
  dashboardPidCwdCache.set(safePid, { cwd, createdAt: now });
  if (dashboardPidCwdCache.size > 500) {
    const cutoff = now - DASHBOARD_PID_CWD_TTL_MS;
    for (const [cachedPid, entry] of dashboardPidCwdCache) {
      if (entry.createdAt < cutoff || !alivePid(cachedPid)) dashboardPidCwdCache.delete(cachedPid);
    }
  }
  return cwd;
}

function getProjectNameFromCwd(cwd) {
  if (!cwd) return '';
  try {
    const pkgPath = path.join(cwd, 'package.json');
    if (fs.existsSync(pkgPath)) {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
      if (pkg && typeof pkg.name === 'string' && pkg.name.trim()) return pkg.name.trim();
    }
  } catch {}
  return path.basename(cwd);
}

async function listElectronDevProcesses() {
  const psOutput = await execAsync('ps -axo pid=,ppid=,pcpu=,pmem=,lstart=,command=', 3000);
  const rows = (psOutput || '')
    .split('\n')
    .map(parseLongPsLine)
    .filter(Boolean);
  const byPid = new Map(rows.map(row => [row.pid, row]));
  const processes = [];

  for (const row of rows) {
    if (!isElectronDevAppCommand(row.command)) continue;
    if (row.pid === process.pid) continue;

    const cwd = await getPidCwd(row.pid);
    const projectName = getProjectNameFromCwd(cwd);
    const parent = byPid.get(row.ppid);
    const launcherPid = parent && isElectronLauncherCommand(parent.command) ? parent.pid : null;

    processes.push({
      pid: row.pid,
      ppid: row.ppid,
      launcherPid,
      cwd,
      name: projectName || 'Electron app',
      startTime: row.startTime,
      command: row.command,
      cpu: row.cpu,
      mem: row.mem,
      isOrphan: row.ppid === 1,
    });
  }

  return processes.sort((a, b) => {
    if (a.isOrphan !== b.isOrphan) return a.isOrphan ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
}

async function getDashboardProcessRows() {
  const psOutput = await execAsync('ps -axo pid=,ppid=,pcpu=,pmem=,lstart=,command=', 3000);
  return (psOutput || '')
    .split('\n')
    .map(parseLongPsLine)
    .filter(Boolean);
}

function alivePid(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function waitForPidsToExit(pids, deadlineMs) {
  const start = Date.now();
  while (Date.now() - start < deadlineMs) {
    const alive = pids.filter(alivePid);
    if (alive.length === 0) return [];
    await new Promise(resolve => setTimeout(resolve, 60));
  }
  return pids.filter(alivePid);
}

const DASHBOARD_OWNERSHIP_SNAPSHOT_TTL_MS = 1000;
let dashboardOwnershipSnapshotCache = null;
let dashboardOwnershipSnapshotInflight = null;

function commandLooksLikeNotedTerminalMain(command) {
  const text = String(command || '');
  const lower = text.toLowerCase();
  if (!text || lower.includes(' --type=')) return false;
  if (lower.includes('/noted terminal.app/contents/macos/noted terminal')) return true;
  if (lower.includes('/custom-terminal/node_modules/electron/dist/electron.app/contents/macos/electron')) return true;
  if (lower.includes('/noted-terminal') && lower.includes('/contents/macos/')) return true;
  return false;
}

function getDashboardInstanceKind(isPackaged, command) {
  if (isPackaged === false) return 'dev';
  if (isPackaged === true) return 'prod';
  const lower = String(command || '').toLowerCase();
  if (lower.includes('/node_modules/electron/')) return 'dev';
  if (lower.includes('.app/contents/macos/')) return 'prod';
  return 'app';
}

function formatDashboardInstanceLabel(pid, isPackaged, command) {
  const kind = getDashboardInstanceKind(isPackaged, command);
  if (pid === process.pid) return kind === 'app' ? 'this app' : 'this ' + kind;
  return kind === 'app' ? 'custom app' : kind;
}

function readDashboardInstanceFromPortFile(fileName, commandByPid) {
  const match = String(fileName || '').match(/^mcp-port-(\d+)$/);
  if (!match) return null;

  const pid = Number(match[1]);
  if (!Number.isInteger(pid) || pid <= 1 || !alivePid(pid)) return null;

  const command = commandByPid.get(pid) || '';
  if (pid !== process.pid && !commandLooksLikeNotedTerminalMain(command)) return null;

  let payload = null;
  try {
    const raw = fs.readFileSync(path.join(MCP_PORT_DIR, fileName), 'utf8');
    payload = JSON.parse(raw);
  } catch {}

  if (payload && payload.pid && Number(payload.pid) !== pid) return null;

  const isPackaged = typeof payload?.isPackaged === 'boolean'
    ? payload.isPackaged
    : (pid === process.pid ? app.isPackaged : undefined);

  return {
    pid,
    isPackaged,
    label: formatDashboardInstanceLabel(pid, isPackaged, command),
  };
}

function buildDashboardOwnershipSnapshotFromRows(rows) {
  const parentByPid = new Map();
  const commandByPid = new Map();
  for (const row of rows || []) {
    parentByPid.set(row.pid, row.ppid);
    commandByPid.set(row.pid, row.command);
  }

  const instancesByPid = new Map();
  instancesByPid.set(process.pid, {
    pid: process.pid,
    isPackaged: app.isPackaged,
    label: formatDashboardInstanceLabel(process.pid, app.isPackaged, commandByPid.get(process.pid) || ''),
  });

  try {
    const files = fs.readdirSync(MCP_PORT_DIR).filter(f => f.startsWith('mcp-port-'));
    for (const fileName of files) {
      const instance = readDashboardInstanceFromPortFile(fileName, commandByPid);
      if (instance) instancesByPid.set(instance.pid, instance);
    }
  } catch {}

  return {
    parentByPid,
    commandByPid,
    instancesByPid,
    createdAt: Date.now(),
  };
}

async function getDashboardOwnershipSnapshot() {
  const now = Date.now();
  if (dashboardOwnershipSnapshotCache && now - dashboardOwnershipSnapshotCache.createdAt < DASHBOARD_OWNERSHIP_SNAPSHOT_TTL_MS) {
    return dashboardOwnershipSnapshotCache;
  }

  if (dashboardOwnershipSnapshotInflight) return dashboardOwnershipSnapshotInflight;

  dashboardOwnershipSnapshotInflight = (async () => {
    try {
      const rows = await getDashboardProcessRows();
      const snapshot = buildDashboardOwnershipSnapshotFromRows(rows);
      dashboardOwnershipSnapshotCache = snapshot;
      return snapshot;
    } catch {}
    const snapshot = buildDashboardOwnershipSnapshotFromRows([]);
    dashboardOwnershipSnapshotCache = snapshot;
    return snapshot;
  })();

  try {
    return await dashboardOwnershipSnapshotInflight;
  } finally {
    dashboardOwnershipSnapshotInflight = null;
  }
}

function findDashboardOwnerPid(startPid, ownershipSnapshot) {
  let currentPid = Number(startPid);
  const seen = new Set();
  while (Number.isInteger(currentPid) && currentPid > 1 && !seen.has(currentPid)) {
    if (ownershipSnapshot.instancesByPid.has(currentPid)) return currentPid;
    seen.add(currentPid);
    currentPid = ownershipSnapshot.parentByPid.get(currentPid);
  }
  return null;
}

function resolveDashboardProcessOwner(startPid, ownershipSnapshot, tabId = null) {
  const ownerPid = findDashboardOwnerPid(startPid, ownershipSnapshot);
  const owner = ownerPid ? ownershipSnapshot.instancesByPid.get(ownerPid) : null;
  const isCurrentOwner = ownerPid === process.pid || !!tabId;

  if (owner) {
    return {
      ownerInstance: isCurrentOwner ? 'current' : 'custom-terminal',
      ownerPid,
      ownerLabel: owner.label,
      protectedByApp: true,
      killable: isCurrentOwner,
    };
  }

  if (tabId) {
    return {
      ownerInstance: 'current',
      ownerPid: process.pid,
      ownerLabel: formatDashboardInstanceLabel(process.pid, app.isPackaged, ownershipSnapshot.commandByPid.get(process.pid) || ''),
      protectedByApp: true,
      killable: true,
    };
  }

  return {
    ownerInstance: 'external',
    ownerPid: null,
    ownerLabel: 'external',
    protectedByApp: false,
    killable: true,
  };
}

ipcMain.handle('system:get-electron-dev-processes', async () => {
  try {
    return await listElectronDevProcesses();
  } catch (err) {
    console.log('[ElectronDev] list failed: ' + (err?.message || String(err)));
    return [];
  }
});

ipcMain.handle('system:kill-electron-dev-process', async (_event, pid) => {
  const targetPid = Number(pid);
  if (!Number.isInteger(targetPid) || targetPid <= 1) {
    return { success: false, error: 'invalid pid' };
  }

  const processes = await listElectronDevProcesses();
  const target = processes.find(proc => proc.pid === targetPid);
  if (!target) {
    return { success: false, error: 'not an Electron dev app process' };
  }

  const descendants = await findDescendantPids(targetPid);
  const pids = Array.from(new Set([targetPid, ...descendants, target.launcherPid].filter(Boolean)));
  const safePids = pids.filter(p => p !== process.pid && p !== process.ppid);
  console.log('[ElectronDev] stop pid=' + targetPid + ' name=' + target.name + ' pids=[' + safePids.join(',') + ']');

  for (const p of safePids) {
    try { process.kill(p, 'SIGTERM'); } catch {}
  }

  let alive = await waitForPidsToExit(safePids, 1500);
  let escalated = false;
  if (alive.length > 0) {
    escalated = true;
    console.log('[ElectronDev] SIGTERM timeout pid=' + targetPid + ' alive=[' + alive.join(',') + '] → SIGKILL');
    for (const p of alive) {
      try { process.kill(p, 'SIGKILL'); } catch {}
    }
    alive = await waitForPidsToExit(alive, 500);
  }

  const success = alive.length === 0;
  console.log('[ElectronDev] stop done pid=' + targetPid + ' success=' + success + ' escalated=' + escalated + ' residual=[' + alive.join(',') + ']');
  return { success, killed: safePids, escalated, residual: alive };
});

// ========== SYSTEM: CLAUDE PROCESSES ==========
ipcMain.handle('system:get-claude-processes', async () => {
  try {
    // Find all claude CLI processes with PPID for ownership detection
    // Added %cpu,%mem to ps format
    const psOutput = await execAsync(
      'ps -eo pid,ppid,pcpu,pmem,lstart,command | grep -i "claude" | grep -v grep | grep -v electron',
      3000
    );

    if (!psOutput) return [];

    // Build a set of our shell PIDs for ownership matching
    const ourShellPids = new Set();
    const pidToTabId = new Map();
    for (const [tabId, ptyProcess] of terminals) {
      ourShellPids.add(ptyProcess.pid);
      pidToTabId.set(ptyProcess.pid, tabId);
    }
    const ownershipSnapshot = await getDashboardOwnershipSnapshot();

    const lines = psOutput.split('\n').filter(Boolean);
    const processes = [];

    for (const line of lines) {
      try {
        // Parse ps output: PID PPID %CPU %MEM lstart(Day Mon DD HH:MM:SS YYYY) command
        const match = line.trim().match(/^\s*(\d+)\s+(\d+)\s+([\d.]+)\s+([\d.]+)\s+\w+\s+\w+\s+\d+\s+(\d+:\d+:\d+)\s+\d+\s+(.+)/);
        if (!match) continue;

        const pid = match[1];
        const ppid = Number(match[2]);
        const cpu = match[3];
        const mem = match[4];
        const startTime = match[5]; // HH:MM:SS
        const command = match[6].trim();

        // Skip non-CLI claude processes
        if (!commandLooksLikeAiProcess(command, 'claude') || command.includes('Electron')) continue;

        // Get CWD via lsof
        const cwd = await getPidCwd(Number(pid));

        if (!cwd) continue;

        // Check if this process belongs to one of our terminal tabs
        const tabId = pidToTabId.get(ppid) || null;
        const owner = resolveDashboardProcessOwner(ppid, ownershipSnapshot, tabId);

        processes.push({
          pid: Number(pid),
          ppid,
          cwd,
          startTime: startTime.substring(0, 5), // HH:MM
          command,
          tabId,
          cpu,
          mem,
          ...owner,
        });
      } catch {
        // Skip unparseable lines
      }
    }

    return processes;
  } catch {
    return [];
  }
});

