ipcMain.handle('system:get-codex-processes', async () => {
  try {
    const psOutput = await execAsync('ps -eo pid,ppid,pcpu,pmem,lstart,command', 3000);
    if (!psOutput) return [];

    const pidToTabId = new Map();
    for (const [tabId, ptyProcess] of terminals) {
      pidToTabId.set(ptyProcess.pid, tabId);
    }
    const ownershipSnapshot = await getDashboardOwnershipSnapshot();

    const rows = [];
    for (const line of psOutput.split('\n').filter(Boolean)) {
      const match = line.trim().match(/^\s*(\d+)\s+(\d+)\s+([\d.]+)\s+([\d.]+)\s+\w+\s+\w+\s+\d+\s+(\d+:\d+:\d+)\s+\d+\s+(.+)/);
      if (!match) continue;
      const command = match[6].trim();
      if (!command.includes('--no-alt-screen')) continue;
      if (!commandLooksLikeAiProcess(command, 'codex')) continue;

      rows.push({
        pid: Number(match[1]),
        ppid: Number(match[2]),
        cpu: match[3],
        mem: match[4],
        startTime: match[5].substring(0, 5),
        command,
      });
    }

    const codexPidSet = new Set(rows.map(row => row.pid));
    const processes = await Promise.all(rows.map(async (row) => {
      // Codex TUI normally appears as shell → node wrapper → vendor codex.
      // Show only the root wrapper so one chat is one Dashboard card.
      if (codexPidSet.has(row.ppid)) return null;

      const cwd = await getPidCwd(row.pid);
      if (!cwd) return null;

      const tabId = pidToTabId.get(row.ppid) || null;
      const owner = resolveDashboardProcessOwner(row.ppid, ownershipSnapshot, tabId);

      return {
        pid: row.pid,
        ppid: row.ppid,
        cwd,
        startTime: row.startTime,
        command: row.command,
        tabId,
        cpu: row.cpu,
        mem: row.mem,
        ...owner,
      };
    }));

    return processes.filter(Boolean);
  } catch {
    return [];
  }
});

async function buildDashboardElectronDevProcessesFromRows(rows) {
  const byPid = new Map(rows.map(row => [row.pid, row]));
  const selected = rows.filter(row => isElectronDevAppCommand(row.command) && row.pid !== process.pid);
  const processes = await Promise.all(selected.map(async (row) => {
    const cwd = await getDashboardPidCwd(row.pid);
    const projectName = getProjectNameFromCwd(cwd);
    const parent = byPid.get(row.ppid);
    const launcherPid = parent && isElectronLauncherCommand(parent.command) ? parent.pid : null;
    return {
      pid: row.pid,
      ppid: row.ppid,
      launcherPid,
      cwd,
      name: projectName || 'Electron app',
      startTime: row.startTime,
      command: row.command,
      cpu: row.cpu,
      mem: row.mem,
      isOrphan: row.ppid === 1,
    };
  }));

  return processes.sort((a, b) => {
    if (a.isOrphan !== b.isOrphan) return a.isOrphan ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
}

async function buildDashboardAiProcessesFromRows(rows, kind, ownershipSnapshot, pidToTabId) {
  let selected = rows.filter(row => {
    const command = row.command || '';
    if (command.includes('Electron') || command.includes('electron')) return false;
    if (kind === 'codex') {
      return command.includes('--no-alt-screen') && commandLooksLikeAiProcess(command, 'codex');
    }
    return command.toLowerCase().includes(kind) && commandLooksLikeAiProcess(command, kind);
  });

  if (kind === 'codex') {
    const codexPidSet = new Set(selected.map(row => row.pid));
    selected = selected.filter(row => !codexPidSet.has(row.ppid));
  }

  const processes = await Promise.all(selected.map(async (row) => {
    const cwd = await getDashboardPidCwd(row.pid);
    if (!cwd) return null;

    const tabId = pidToTabId.get(row.ppid) || null;
    const owner = resolveDashboardProcessOwner(row.ppid, ownershipSnapshot, tabId);

    return {
      pid: row.pid,
      ppid: row.ppid,
      cwd,
      startTime: row.startTime,
      command: row.command,
      tabId,
      cpu: row.cpu,
      mem: row.mem,
      ...owner,
    };
  }));

  return processes.filter(Boolean);
}

function commandLooksLikeMcpProcess(command) {
  const text = String(command || '');
  if (text.includes('Electron') || text.includes('electron')) return false;
  return /mcp|terminal-server\.mjs|knowledge-server\.mjs|gemini-mcp|yougile-mcp|playwright-mcp|chrome-devtools|extension-mcp/i.test(text);
}

function buildDashboardMcpProcessesFromRows(rows, ownershipSnapshot) {
  const aliveCliPids = new Set();
  for (const [, ptyProcess] of terminals) aliveCliPids.add(ptyProcess.pid);

  for (const row of rows) {
    const command = row.command || '';
    if (command.includes('Electron') || command.includes('electron')) continue;
    if ((commandLooksLikeAiProcess(command, 'claude') || commandLooksLikeAiProcess(command, 'gemini')) && aliveCliPids.has(row.ppid)) {
      aliveCliPids.add(row.pid);
    }
  }

  const processes = [];
  for (const row of rows) {
    if (!commandLooksLikeMcpProcess(row.command)) continue;

    let name = 'mcp';
    const m1 = row.command.match(/([\w.-]+(?:-mcp|mcp-server|server\.mjs|extension-mcp\/index\.js))/i);
    if (m1) name = m1[1].replace(/^.*\//, '');
    else {
      const parts = row.command.split(/\s+/);
      name = (parts[1] || parts[0] || 'mcp').split('/').pop() || 'mcp';
    }

    const owner = resolveDashboardProcessOwner(row.ppid, ownershipSnapshot, null);
    const isAlive = aliveCliPids.has(row.ppid) || !!owner.protectedByApp;
    processes.push({
      pid: row.pid,
      ppid: row.ppid,
      cpu: row.cpu,
      mem: row.mem,
      startTime: row.startTime,
      command: row.command,
      name,
      isAlive,
      ownerInstance: owner.ownerInstance,
      ownerLabel: owner.ownerLabel,
      ownerPid: owner.ownerPid,
      protectedByApp: owner.protectedByApp,
      killable: owner.killable,
    });
  }
  return processes;
}

ipcMain.handle('system:get-dashboard-processes', async () => {
  try {
    const rows = await getDashboardProcessRows();
    const ownershipSnapshot = buildDashboardOwnershipSnapshotFromRows(rows);
    dashboardOwnershipSnapshotCache = ownershipSnapshot;

    const pidToTabId = new Map();
    for (const [tabId, ptyProcess] of terminals) {
      pidToTabId.set(ptyProcess.pid, tabId);
    }

    const [electronDev, claude, gemini, codex] = await Promise.all([
      buildDashboardElectronDevProcessesFromRows(rows),
      buildDashboardAiProcessesFromRows(rows, 'claude', ownershipSnapshot, pidToTabId),
      buildDashboardAiProcessesFromRows(rows, 'gemini', ownershipSnapshot, pidToTabId),
      buildDashboardAiProcessesFromRows(rows, 'codex', ownershipSnapshot, pidToTabId),
    ]);

    return {
      claude,
      gemini,
      codex,
      mcp: buildDashboardMcpProcessesFromRows(rows, ownershipSnapshot),
      electronDev,
    };
  } catch (err) {
    console.log('[DashboardProcesses] aggregate failed: ' + (err?.message || String(err)));
    return { claude: [], gemini: [], codex: [], mcp: [], electronDev: [] };
  }
});

let agentSessionAvailabilityService = null;
let storageCleanupService = null;
let storageRetentionTimer = null;
let storageRelationDatabases = null;

function getCodexAvailabilityLineageManifest(sessionId) {
  try {
    const fork = projectManager?.db?.getSessionHistoryContext?.(sessionId)?.fork || null;
    return fork?.provider === 'codex' ? (fork.lineageManifest || null) : null;
  } catch {
    return null;
  }
}

function isAgentSessionRuntimeActive({ tabId, provider } = {}) {
  if (!tabId) return false;
  if (provider === 'codex') {
    return terminals.has(tabId) && (
      codexKnownSessions.has(tabId)
      || codexLastRunCommandPayload.has(tabId)
      || codexTurnWatchers.has(tabId)
      || codexTuiReadyTabs.has(tabId)
    );
  }
  if (provider === 'gemini') return geminiActiveTabs.has(tabId);
  return isClaudeProcessRunningInTab(tabId) || sdkSessions.has(tabId);
}

function getAgentSessionAvailabilityService() {
  if (agentSessionAvailabilityService) return agentSessionAvailabilityService;
  agentSessionAvailabilityService = new AgentSessionAvailabilityService({
    claudeProjectsDir: path.join(os.homedir(), '.claude', 'projects'),
    codexHome: process.env.CODEX_HOME || path.join(os.homedir(), '.codex'),
    resolveGeminiProjectDir,
    getCodexLineageManifest: getCodexAvailabilityLineageManifest,
    isRuntimeActive: isAgentSessionRuntimeActive,
  });
  return agentSessionAvailabilityService;
}

function broadcastAgentSessionAvailabilityInvalidated(sessionIds, metadata = {}) {
  const ids = [...new Set((Array.isArray(sessionIds) ? sessionIds : [])
    .map((value) => String(value || '').trim())
    .filter(Boolean))];
  if (ids.length === 0) return;
  for (const win of BrowserWindow.getAllWindows()) {
    if (!win || win.isDestroyed() || win.webContents?.isDestroyed()) continue;
    try {
      win.webContents.send('agent-session:availability-invalidated', {
        sessionIds: ids,
        source: metadata.source || 'noted-terminal',
        operationId: metadata.operationId || null,
        occurredAt: metadata.occurredAt || Date.now(),
      });
    } catch {}
  }
}

function noteStorageDeletedAgentSessions(result, metadata = {}) {
  const sessionIds = Array.isArray(result?.removedSessions) ? result.removedSessions : [];
  if (sessionIds.length === 0) return;
  const occurredAt = Date.now();
  getAgentSessionAvailabilityService().noteDeletedSessions(sessionIds, {
    source: metadata.source || 'storage',
    operationId: metadata.operationId || null,
    deletedAt: occurredAt,
  });
  broadcastAgentSessionAvailabilityInvalidated(sessionIds, {
    ...metadata,
    occurredAt,
  });
}

ipcMain.handle('agent-session:get-availability-batch', async (_event, request = {}) => {
  try {
    return await getAgentSessionAvailabilityService().probeBatch({
      sessions: request?.sessions,
      force: request?.force === true,
    });
  } catch (error) {
    console.warn('[SessionAvailability] batch probe failed:', error?.message || error);
    return { success: false, error: error?.code || error?.message || 'session_availability_failed', results: [] };
  }
});

function getStorageRelationDatabases() {
  if (storageRelationDatabases) return storageRelationDatabases;
  storageRelationDatabases = [];
  const currentUserDataDir = path.resolve(app.getPath('userData'));
  const canonicalUserDataDir = path.resolve(canonicalNotedUserDataDir);
  const candidates = new Map();
  const addCandidate = (environment, filename) => {
    const candidatePath = path.join(canonicalUserDataDir, filename);
    candidates.set(candidatePath, { environment, path: candidatePath });
  };
  if (currentUserDataDir !== canonicalUserDataDir) addCandidate('production', 'noted-terminal.db');
  addCandidate(app.isPackaged ? 'development' : 'production', app.isPackaged ? 'noted-terminal-dev.db' : 'noted-terminal.db');
  let Sqlite = null;
  try {
    Sqlite = require('better-sqlite3');
  } catch (error) {
    console.warn('[StorageCleanup] relation DB driver unavailable:', error?.message || error);
    return storageRelationDatabases;
  }
  for (const candidate of candidates.values()) {
    if (!fs.existsSync(candidate.path)) {
      console.warn('[StorageCleanup] relation DB missing environment=' + candidate.environment + ' path=' + candidate.path);
      continue;
    }
    try {
      const sqlite = new Sqlite(candidate.path, { readonly: true, fileMustExist: true });
      storageRelationDatabases.push({ environment: candidate.environment, sqlite, path: candidate.path });
      console.log('[StorageCleanup] relation DB authority environment=' + candidate.environment + ' path=' + candidate.path);
    } catch (error) {
      console.warn('[StorageCleanup] relation DB unavailable environment=' + candidate.environment + ':', error?.message || error);
    }
  }
  return storageRelationDatabases;
}

function getStorageMutationAuthority() {
  if (process.env.NOTED_E2E_TEST === 'true') {
    return { allowed: false, reason: 'e2e-storage-mutation-disabled' };
  }
  const ownsCanonicalProductionDb = app.isPackaged
    && path.resolve(app.getPath('userData')) === path.resolve(canonicalNotedUserDataDir);
  if (ownsCanonicalProductionDb) return { allowed: true, reason: 'packaged-production-owner' };
  const production = getStorageRelationDatabases().find((source) => (
    source?.environment === 'production' && source?.sqlite
  ));
  return production
    ? { allowed: true, reason: 'canonical-production-db-readonly' }
    : { allowed: false, reason: 'canonical-production-db-unavailable' };
}

function resolveStorageProjectRoot() {
  const candidates = new Set();
  if (!app.isPackaged) candidates.add(process.cwd());
  try {
    const rows = projectManager.db.db.prepare('SELECT path FROM projects WHERE path IS NOT NULL').all();
    for (const row of rows) candidates.add(String(row.path || ''));
  } catch {}
  candidates.add(path.join(os.homedir(), 'Desktop', 'custom-terminal'));
  for (const candidate of candidates) {
    if (!candidate) continue;
    try {
      const packageJson = JSON.parse(fs.readFileSync(path.join(candidate, 'package.json'), 'utf8'));
      if (packageJson?.name === 'noted-terminal'
        && fs.existsSync(path.join(candidate, 'src', 'renderer', 'components', 'Dashboard', 'Dashboard.tsx'))) {
        return path.resolve(candidate);
      }
    } catch {}
  }
  return null;
}

function storageRuntimeProtectedSessionIds() {
  const ids = new Set();
  const add = (value) => { if (typeof value === 'string' && value.trim()) ids.add(value.trim()); };
  for (const value of bridgeKnownSessions.values()) add(value);
  for (const value of codexKnownSessions.values()) add(value);
  for (const payload of codexLastRunCommandPayload.values()) add(payload?.sessionId);
  for (const watcher of codexTurnWatchers.values()) add(watcher?.sessionId);
  for (const watcher of codexWatchers.values()) {
    add(watcher?.sessionId);
    add(watcher?.sourceSessionId);
    add(watcher?.provisionalSourceObservation?.sessionId);
  }
  for (const observation of codexProvisionalSourceObservations.values()) {
    add(observation?.sessionId);
  }
  for (const sdk of sdkSessions.values()) add(sdk?.sessionId);
  return [...ids];
}

function getStorageCleanupService() {
  if (storageCleanupService) return storageCleanupService;
  storageCleanupService = new StorageCleanupService({
    sqlite: projectManager.db.db,
    dbManager: projectManager.db,
    appDataDir: app.getPath('userData'),
    projectRoot: resolveStorageProjectRoot(),
    codexHome: process.env.CODEX_HOME || path.join(os.homedir(), '.codex'),
    claudeHome: path.join(os.homedir(), '.claude'),
    codexBinary: path.join(os.homedir(), '.noted-terminal', 'bin', 'codex'),
    currentEnvironment: app.isPackaged ? 'production' : 'development',
    relationDatabases: getStorageRelationDatabases(),
    getRuntimeProtectedSessionIds: storageRuntimeProtectedSessionIds,
    getMutationAuthority: getStorageMutationAuthority,
    auditPath: path.join(canonicalNotedUserDataDir, 'storage-deletion-audit.jsonl'),
    logger: console,
  });
  return storageCleanupService;
}

function scheduleStorageRetentionSweep(delayMs = 90_000) {
  if (!canOwnAutomaticStorageRetention({
    isPackaged: app.isPackaged,
    e2e: process.env.NOTED_E2E_TEST === 'true',
  })) return;
  if (storageRetentionTimer) clearTimeout(storageRetentionTimer);
  storageRetentionTimer = setTimeout(async () => {
    storageRetentionTimer = null;
    let nextDelay = 6 * 60 * 60 * 1000;
    try {
      const result = await getStorageCleanupService().runRetentionSweep();
      noteStorageDeletedAgentSessions(result, { source: 'retention' });
      if (result?.remainingEligible > 0) nextDelay = 15 * 60 * 1000;
      if (result?.removed?.length > 0) {
        console.log('[StorageCleanup] retention removed=' + result.removed.length
          + ' reclaimedBytes=' + (result.reclaimedBytes || 0)
          + ' remaining=' + (result.remainingEligible || 0));
      }
    } catch (error) {
      console.warn('[StorageCleanup] retention sweep failed:', error?.message || error);
    }
    scheduleStorageRetentionSweep(nextDelay);
  }, Math.max(1_000, Number(delayMs) || 90_000));
  storageRetentionTimer.unref?.();
}

ipcMain.handle('storage:get-inventory', async (_event, request = {}) => {
  try {
    return await getStorageCleanupService().scan({ force: request?.force === true });
  } catch (error) {
    console.warn('[StorageCleanup] inventory failed:', error?.message || error);
    return { success: false, error: error?.code || error?.message || 'storage_inventory_failed' };
  }
});

